import { GoogleGenAI } from "@google/genai";
import { MOCK_MENU } from "../constants";

export const getAiInstance = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const menuData = MOCK_MENU.map(i => `${i.nameBn}: ৳${i.price}`).join(", ");

// Ultra-fast text completion for tiny queries
export const bfcFastText = async (message: string) => {
  const ai = getAiInstance();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: message,
    config: {
      systemInstruction: `You are BFC Assist. Extremely concise. Max 3 words. Context: ${menuData}`,
      temperature: 0.1,
    }
  });
  return response.text?.trim() || "কীভাবে সাহায্য করতে পারি?";
};

export function encodeAudio(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export function decodeAudio(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { decodeAudio, decodeAudioData, encodeAudio, getAiInstance } from '../services/geminiService';
import { ChatMessage } from '../types';
import { Modality, LiveServerMessage } from '@google/genai';
import { MOCK_MENU } from '../constants';

const menuData = MOCK_MENU.map(i => `${i.nameBn}: ${i.price}tk`).join(", ");

export const ChatBot: React.FC<{ isOnline?: boolean }> = ({ isOnline = true }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([{ role: 'model', text: "কী চাই?", timestamp: new Date() }]);
  const [input, setInput] = useState('');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [currentTranscription, setCurrentTranscription] = useState('');
  const [isMicOn, setIsMicOn] = useState(false);

  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const liveSessionRef = useRef<any>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const scrollRef = useRef<HTMLDivElement>(null);
  const micStreamRef = useRef<MediaStream | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);

  const stopAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setIsSpeaking(false);
  };

  const initAudioOutput = async () => {
    if (!outputAudioContextRef.current) {
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    if (outputAudioContextRef.current.state === 'suspended') await outputAudioContextRef.current.resume();
  };

  const connectLive = useCallback(async () => {
    if (!isOnline || liveSessionRef.current) return;
    await initAudioOutput();
    const ai = getAiInstance();

    try {
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsLiveActive(true);
            console.log("⚡ BFC Neural Link Active");
          },
          onmessage: async (msg: LiveServerMessage) => {
            const audioData = msg.serverContent?.modelTurn?.parts?.find(p => p.inlineData)?.inlineData?.data;
            if (audioData && outputAudioContextRef.current) {
              setIsSpeaking(true);
              const ctx = outputAudioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);

              const buffer = await decodeAudioData(decodeAudio(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              };
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }

            if (msg.serverContent?.outputTranscription) {
              const text = msg.serverContent.outputTranscription.text;
              setCurrentTranscription(prev => prev + text);
            }

            if (msg.serverContent?.turnComplete) {
              setMessages(prev => {
                const final = currentTranscription || "...";
                return [...prev, { role: 'model', text: final, timestamp: new Date() }];
              });
              setCurrentTranscription('');
            }

            if (msg.serverContent?.interrupted) stopAudio();
          },
          onerror: (e) => console.error("Link Error", e),
          onclose: () => {
            setIsLiveActive(false);
            liveSessionRef.current = null;
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          outputAudioTranscription: {},
          speechConfig: { 
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          },
          systemInstruction: `ACT: BFC Ultra-Fast. DATA: ${menuData}. RULES: Bengali only. Max 2-3 words. Extremely brief. Response must be near-instant. If order asked, say 'হচ্ছে!'. If price asked, say the number. Zero pleasantries.`
        }
      });
      liveSessionRef.current = await sessionPromise;
    } catch (e) {
      console.error("Link offline", e);
    }
  }, [isOnline, currentTranscription]);

  const handleSend = async () => {
    const text = input.trim();
    if (!text || !liveSessionRef.current) return;

    stopAudio();
    setMessages(prev => [...prev, { role: 'user', text, timestamp: new Date() }]);
    setInput('');

    liveSessionRef.current.sendRealtimeInput({
      message: { parts: [{ text }] }
    });
  };

  const toggleMic = async () => {
    if (!liveSessionRef.current) return;
    if (isMicOn) {
      if (micStreamRef.current) micStreamRef.current.getTracks().forEach(t => t.stop());
      setIsMicOn(false);
      return;
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;
      setIsMicOn(true);

      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      inputAudioContextRef.current = ctx;
      const source = ctx.createMediaStreamSource(stream);
      const processor = ctx.createScriptProcessor(512, 1, 1); // Reduced buffer for lower latency

      processor.onaudioprocess = (e) => {
        if (!isMicOn || !liveSessionRef.current) return;
        const inputData = e.inputBuffer.getChannelData(0);
        const int16 = new Int16Array(inputData.length);
        for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
        liveSessionRef.current.sendRealtimeInput({
          media: { data: encodeAudio(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' }
        });
      };

      source.connect(processor);
      processor.connect(ctx.destination);
    } catch (e) {
      setIsMicOn(false);
    }
  };

  useEffect(() => {
    if (isOpen) connectLive();
    return () => { if (liveSessionRef.current) liveSessionRef.current.close(); };
  }, [isOpen, connectLive]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight });
  }, [messages, currentTranscription]);

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-12 lg:right-12 z-[5000]">
      {isOpen ? (
        <div className="bg-white/98 dark:bg-gray-950/98 backdrop-blur-3xl w-[85vw] sm:w-[320px] h-[50vh] sm:h-[420px] rounded-[40px] shadow-[0_40px_100px_-20px_rgba(220,38,38,0.3)] flex flex-col border border-white/20 dark:border-white/10 overflow-hidden animate-slide-up ring-1 ring-black/5">
          <div className="bg-red-600 p-5 text-white flex justify-between items-center">
            <div className="flex items-center gap-3">
               <div className={`w-8 h-8 rounded-xl flex items-center justify-center ${isSpeaking ? 'bg-white text-red-600' : 'bg-white/20'}`}>
                  <i className={`fas ${isSpeaking ? 'fa-waveform animate-pulse' : 'fa-bolt-lightning'} text-xs`}></i>
               </div>
               <div>
                 <span className="text-[10px] font-black uppercase tracking-widest italic block">BFC FASTLINK</span>
                 <span className="text-[7px] font-bold opacity-70 uppercase tracking-widest">Latency: Low-Ops</span>
               </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="w-8 h-8 bg-white/10 rounded-xl flex items-center justify-center hover:bg-white/20 transition-all">
              <i className="fas fa-times text-[10px]"></i>
            </button>
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-5 space-y-4 scrollbar-hide bg-gray-50/10">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] px-4 py-2 rounded-[22px] text-[11px] font-black ${m.role === 'user' ? 'bg-red-600 text-white shadow-lg' : 'bg-white dark:bg-gray-900 text-gray-800 dark:text-gray-100 border border-gray-100 dark:border-white/5 shadow-sm'}`}>
                  {m.text}
                </div>
              </div>
            ))}
            {currentTranscription && (
              <div className="flex justify-start">
                <div className="max-w-[85%] px-4 py-2 rounded-[22px] text-[11px] font-black bg-white dark:bg-gray-900 text-red-600 border border-red-50 animate-pulse italic">
                  {currentTranscription}
                </div>
              </div>
            )}
          </div>

          <div className="p-4 bg-white dark:bg-gray-950 border-t dark:border-white/5 flex gap-3">
            <button onClick={toggleMic} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isMicOn ? 'bg-red-600 text-white animate-pulse' : 'bg-gray-100 dark:bg-gray-900 text-gray-400 hover:text-gray-600'}`}>
              <i className={`fas ${isMicOn ? 'fa-microphone' : 'fa-microphone-slash'} text-sm`}></i>
            </button>
            <div className="flex-1 flex items-center bg-gray-100 dark:bg-gray-900 rounded-2xl p-1 shadow-inner">
              <input 
                type="text" value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSend()}
                placeholder="অর্ডার দিন..."
                className="flex-1 bg-transparent border-none px-4 outline-none text-[11px] font-black dark:text-white placeholder:opacity-50"
              />
              <button onClick={handleSend} className="w-10 h-10 bg-red-600 text-white rounded-xl flex items-center justify-center shadow-lg active:scale-90 transition-all">
                <i className="fas fa-paper-plane text-[10px]"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button onClick={() => setIsOpen(true)} className="w-14 h-14 sm:w-16 sm:h-16 bg-red-600 text-white rounded-[24px] shadow-[0_20px_50px_rgba(220,38,38,0.4)] flex flex-col items-center justify-center hover:scale-110 active:scale-90 transition-all group border-2 border-white/20 overflow-hidden">
           <i className="fas fa-bolt-lightning text-xl sm:text-2xl group-hover:animate-bounce"></i>
           {isSpeaking && <span className="absolute top-2 right-2 flex h-2 w-2"><span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span><span className="relative inline-flex rounded-full h-2 w-2 bg-white"></span></span>}
        </button>
      )}
    </div>
  );
};

const CACHE_NAME = 'bfc-v6-elite';
const STATIC_ASSETS = [
  '/',
  '/index.html',
  '/manifest.json',
  '/index.tsx',
  'https://cdn.tailwindcss.com',
  'https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css',
  'https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&family=Hind+Siliguri:wght@400;700&display=swap',
  'https://images.unsplash.com/photo-1541140134513-85a161dc4a00?auto=format&fit=crop&q=80&w=1600'
];

const IMAGE_CACHE = 'bfc-img-store';

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      console.log('[BFC] Pre-caching Core Infrastructure');
      return cache.addAll(STATIC_ASSETS);
    })
  );
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => {
      return Promise.all(
        keys.map((key) => {
          if (key !== CACHE_NAME && key !== IMAGE_CACHE) {
            return caches.delete(key);
          }
        })
      );
    })
  );
  return self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);

  // Gemini API calls should always go to network (or fail gracefully in ChatBot)
  if (url.hostname.includes('generativelanguage.googleapis.com')) {
    return;
  }

  // Assets and Images
  if (request.destination === 'image' || url.hostname.includes('unsplash.com')) {
    event.respondWith(
      caches.open(IMAGE_CACHE).then((cache) => {
        return cache.match(request).then((cached) => {
          return cached || fetch(request).then((network) => {
            cache.put(request, network.clone());
            return network;
          }).catch(() => caches.match('https://img.icons8.com/color/512/000000/hamburger.png'));
        });
      })
    );
    return;
  }

  // Network-first for dynamic content, but fallback to cache
  event.respondWith(
    fetch(request)
      .then((response) => {
        if (response && response.status === 200) {
          const resClone = response.clone();
          caches.open(CACHE_NAME).then((cache) => cache.put(request, resClone));
        }
        return response;
      })
      .catch(() => {
        return caches.match(request).then((cached) => {
          if (cached) return cached;
          if (request.mode === 'navigate') return caches.match('/index.html');
          return null;
        });
      })
  );
});

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem, RewardVoucher } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'warning' | 'info';
  id: number;
}

const AVAILABLE_REWARDS: RewardVoucher[] = [
  { id: 'RV-01', title: 'Free Borhani', description: 'Redeem points for a 500ml chilled Borhani.', pointsCost: 150, code: 'FREEBOR', icon: 'fa-glass-water' },
  { id: 'RV-02', title: '20% Off Mission', description: 'Get 20% flat discount on your next order.', pointsCost: 300, code: 'OFF20ELITE', icon: 'fa-tags' },
  { id: 'RV-03', title: 'Priority Delivery', description: 'Skip the queue for the next 3 missions.', pointsCost: 100, code: 'FASTFLY', icon: 'fa-bolt' },
  { id: 'RV-04', title: 'Dessert Protocol', description: 'One free Mishti Doi with any kacchi.', pointsCost: 80, code: 'SWEETBFC', icon: 'fa-cookie-bite' },
];

const PAYMENT_METHODS = [
  { id: 'BKASH', label: 'bKash', icon: 'fa-mobile-screen', color: 'bg-[#d12053]', brandColor: '#d12053' },
  { id: 'NAGAD', label: 'Nagad', icon: 'fa-money-bill-transfer', color: 'bg-[#f7941d]', brandColor: '#f7941d' },
  { id: 'ROCKET', label: 'Rocket', icon: 'fa-building-columns', color: 'bg-[#8c3494]', brandColor: '#8c3494' },
  { id: 'UPAY', label: 'Upay', icon: 'fa-wallet', color: 'bg-[#ffc20e]', brandColor: '#ffc20e' },
  { id: 'CARD', label: 'Credit Card', icon: 'fa-credit-card', color: 'bg-[#1a1a1a]', brandColor: '#1a1a1a' },
  { id: 'COD', label: 'Cash on Delivery', icon: 'fa-hand-holding-dollar', color: 'bg-[#059669]', brandColor: '#059669' },
];

const App: React.FC = () => {
  // Core State
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT' | 'PROFILE'>('HOME');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [pwaInstallPrompt, setPwaInstallPrompt] = useState<any>(null);

  // Auth States
  const [isSignup, setIsSignup] = useState(false);
  const [formEmail, setFormEmail] = useState('');
  const [formPass, setFormPass] = useState('');
  const [formName, setFormName] = useState('');
  const [formPhone, setFormPhone] = useState('');
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  // Profile Edit States
  const [editName, setEditName] = useState('');
  const [editPhone, setEditPhone] = useState('');
  const [editImage, setEditImage] = useState<string | undefined>(undefined);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Menu Filter States
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');

  // Checkout & Gateway States
  const [isCheckingOut, setIsCheckingOut] = useState(false);
  const [selectedPayment, setSelectedPayment] = useState<string>('BKASH');
  const [gatewayStep, setGatewayStep] = useState<1 | 2 | 3>(1);
  const [mfsNumber, setMfsNumber] = useState('');
  const [cardDetails, setCardDetails] = useState({ number: '', expiry: '', cvv: '', name: '' });

  // Computed Values
  const categories = useMemo(() => ['All', ...new Set(menuItems.map(item => item.category))], [menuItems]);

  const filteredMenu = useMemo(() => {
    return menuItems.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            item.nameBn.includes(searchQuery);
      const matchesCategory = activeCategory === 'All' || item.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [menuItems, searchQuery, activeCategory]);

  const showToast = useCallback((message: string, type: Toast['type'] = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
  }, []);

  // Sync Persistence & PWA
  useEffect(() => {
    const savedSession = localStorage.getItem('bfc_user_session');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setEditName(user.name);
        setEditPhone(user.phone);
        setEditImage(user.profileImage);
        if (user.role !== UserRole.CUSTOMER) setView('ADMIN');
      } catch (e) { localStorage.removeItem('bfc_user_session'); }
    }

    const handleBeforeInstallPrompt = (e: any) => {
      e.preventDefault();
      setPwaInstallPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, []);

  useEffect(() => {
    const handleOnline = () => { 
      setIsOnline(true); 
      showToast('Neural Link Established. System Online.', 'success'); 
    };
    const handleOffline = () => { 
      setIsOnline(false); 
      showToast('Satellite Link Severed. Emergency Offline Mode.', 'error'); 
    };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => { 
      window.removeEventListener('online', handleOnline); 
      window.removeEventListener('offline', handleOffline); 
    };
  }, [showToast]);

  const handleInstallPWA = async () => {
    if (!pwaInstallPrompt) return;
    pwaInstallPrompt.prompt();
    const { outcome } = await pwaInstallPrompt.userChoice;
    if (outcome === 'accepted') {
      setPwaInstallPrompt(null);
      showToast('BFC Hub Installed to Desktop.', 'success');
    }
  };

  const handleAuth = async () => {
    if (!formEmail.trim() || !formPass.trim()) {
      showToast('Credentials required.', 'warning');
      return;
    }

    setIsAuthenticating(true);
    try {
      if (!isOnline) {
         showToast('Offline: Authentication requires server ping.', 'error');
         return;
      }
      await new Promise(resolve => setTimeout(resolve, 800));

      let user: User;

      if (isSignup) {
        user = {
          id: 'U-' + Math.random().toString(36).slice(2, 7),
          name: formName || 'New Citizen',
          email: formEmail,
          phone: formPhone || 'Not Set',
          role: UserRole.CUSTOMER,
          loyaltyPoints: 50,
          tier: 'SILVER',
          wishlist: [],
          referralCode: 'BFC-' + Math.random().toString(36).slice(2, 6).toUpperCase(),
          unlockedVouchers: []
        };
        showToast('Node Established! Welcome.', 'success');
      } else {
        const role = formEmail.includes('admin') ? UserRole.ADMIN : UserRole.CUSTOMER;
        user = {
          id: 'U-' + (Math.random() * 1000).toFixed(0),
          name: role === UserRole.ADMIN ? 'Super Admin' : 'Premium Member',
          email: formEmail,
          phone: formPhone || '01700000000',
          role,
          loyaltyPoints: 450,
          tier: 'GOLD',
          wishlist: [],
          referralCode: 'BFC-VIP',
          unlockedVouchers: []
        };
        showToast('Access Granted. Session Active.', 'success');
      }

      setCurrentUser(user);
      setEditName(user.name);
      setEditPhone(user.phone);
      setEditImage(user.profileImage);
      localStorage.setItem('bfc_user_session', JSON.stringify(user));
      setView(user.role === UserRole.ADMIN ? 'ADMIN' : 'HOME');
    } catch (error: any) {
      showToast('Authentication Interrupted.', 'error');
    } finally {
      setIsAuthenticating(false);
    }
  };

  const handleUpdateProfile = () => {
    if (!currentUser) return;
    if (!editName.trim()) { showToast('Name required.', 'warning'); return; }

    const updatedUser: User = { ...currentUser, name: editName, phone: editPhone, profileImage: editImage };
    setCurrentUser(updatedUser);
    localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));
    showToast('Neural Identity Updated.', 'success');
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) { showToast('Payload exceeds 2MB limit.', 'warning'); return; }
      const reader = new FileReader();
      reader.onloadend = () => setEditImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleRedeem = (reward: RewardVoucher) => {
    if (!currentUser) { setView('LOGIN'); return; }
    if (!isOnline) { showToast('Offline: Node sync required for vault access.', 'warning'); return; }
    if (currentUser.loyaltyPoints < reward.pointsCost) { showToast('Insufficient credits.', 'warning'); return; }

    const updatedUser: User = {
      ...currentUser,
      loyaltyPoints: currentUser.loyaltyPoints - reward.pointsCost,
      unlockedVouchers: [...(currentUser.unlockedVouchers || []), reward.id]
    };
    setCurrentUser(updatedUser);
    localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));
    showToast(`${reward.title} Activated.`, 'success');
  };

  const handleCheckoutInitiate = () => {
    if (!currentUser) { 
      showToast('Authorization required for checkout.', 'warning');
      setView('LOGIN'); 
      return; 
    }

    if (!isOnline) {
      showToast('Offline: Neural network required for payments.', 'error');
      return;
    }

    if (selectedPayment === 'CARD') {
       if (!cardDetails.number || !cardDetails.expiry || !cardDetails.cvv) {
         showToast('Incomplete card payload.', 'error');
         return;
       }
    }

    if (['BKASH', 'NAGAD', 'ROCKET', 'UPAY'].includes(selectedPayment)) {
      if (gatewayStep < 3) {
        if (gatewayStep === 1 && !mfsNumber) { showToast('Account link required.', 'warning'); return; }
        setGatewayStep((prev) => (prev + 1) as any);
        return;
      }
    }

    handleFinalOrder();
  };

  const handleFinalOrder = async () => {
    setIsCheckingOut(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 2000));
      const total = cart.reduce((a, b) => a + (b.item.price * b.qty), 0) + 50;
      const newOrder: Order = {
        id: 'BFC-' + Math.random().toString(36).slice(2, 8).toUpperCase(),
        customerId: currentUser!.id,
        customerName: currentUser!.name,
        customerPhone: currentUser!.phone,
        items: cart.map(c => ({ menuId: c.item.id, quantity: c.qty, price: c.item.price, name: c.item.name })),
        total,
        status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(),
        paymentStatus: selectedPayment === 'COD' ? 'UNPAID' : 'PAID',
        paymentMethod: selectedPayment as any,
        address: 'Sector 7, Dhaka Hub',
        deliveryZone: 'Dhaka Metropolitan',
        deliverySlot: 'Standard',
        pointsEarned: Math.floor(total / 15),
        trackingUpdates: [{ status: OrderStatus.PENDING, time: new Date().toLocaleTimeString() }]
      };
      setAllOrders(prev => [newOrder, ...prev]);

      const updatedUser: User = { ...currentUser!, loyaltyPoints: currentUser!.loyaltyPoints + Math.floor(total / 15) };
      setCurrentUser(updatedUser);
      localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));

      setCart([]);
      setGatewayStep(1);
      setView('HOME');
      showToast(`Mission Launched! Deployment confirmed.`, 'success');
    } finally {
      setIsCheckingOut(false);
    }
  };

  const addToCart = (item: MenuItem) => {
    if (item.stock <= 0) { showToast('Asset Depleted.', 'warning'); return; }
    setCart(prev => {
      const existing = prev.find(c => c.item.id === item.id);
      if (existing) return prev.map(c => c.item.id === item.id ? { ...c, qty: c.qty + 1 } : c);
      return [...prev, { item, qty: 1 }];
    });
    showToast(`${item.name} added to payload.`, 'success');
  };

  if (view === 'ADMIN' && currentUser?.role !== UserRole.CUSTOMER) {
    return (
      <AdminPanel 
        userRole={currentUser!.role} 
        onLogout={() => { setCurrentUser(null); setView('HOME'); localStorage.removeItem('bfc_user_session'); }}
