                            <td className="p-10">
                               <span className={`px-3 py-1 rounded-lg text-[8px] font-black uppercase tracking-widest ${l.level === 'CRITICAL' ? 'bg-red-600 text-white' : 'bg-gray-100 text-gray-500'}`}>{l.level}</span>
                            </td>
                         </tr>
                       ))}
                    </tbody>
                 </table>
              </div>
            </div>
          )}
        </div>
      </main>
      <ChatBot isOnline={true} />
      <style>{`
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fadeIn 0.3s ease-out; }
      `}</style>
    </div>
  );
};

