  const [newItem, setNewItem] = useState({
    name: '', nameBn: '', description: '', price: '', category: 'Biryani', image: '', stock: '20'
  });

  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([
    { id: 'LOG-001', userId: 'A-001', userName: 'Super Admin', action: 'SYSTEM_START', details: 'BFC Mainframe initialized.', timestamp: new Date(Date.now() - 86400000).toISOString(), level: 'INFO' },
  ]);

  const showToast = useCallback((msg: string, type: string) => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 4000);
  }, []);

  const addAuditLog = useCallback((action: string, details: string, level: AuditLog['level'] = 'INFO') => {
    const newLog: AuditLog = {
      id: `LOG-${Math.random().toString(36).slice(2, 7).toUpperCase()}`,
      userId: 'ADMIN-01',
      userName: 'Head Admin',
      action,
      details,
      timestamp: new Date().toISOString(),
      level
    };
    setAuditLogs(prev => [newLog, ...prev]);
  }, []);

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
    showToast(`Mission #${orderId.slice(-4)} updated to ${newStatus}.`, "success");
    addAuditLog('ORDER_UPDATE', `Order ${orderId} status set to ${newStatus}`);
  };

  const handleUpdateStock = (itemId: string, increment: boolean) => {
    setMenuItems(prev => prev.map(item => {
      if (item.id === itemId) {
        const newStock = increment ? item.stock + 1 : item.stock - 1;
        if (newStock < 0) return item;
        return { ...item, stock: newStock };
      }
      return item;
    }));
  };

  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newItem.name || !newItem.price) {
      showToast("Required parameters missing.", "error");
      return;
    }

    const item: MenuItem = {
      id: Date.now().toString(),
      name: newItem.name,
      nameBn: newItem.nameBn || newItem.name,
      description: newItem.description || "Standard BFC Unit.",
      price: parseInt(newItem.price),
      category: newItem.category,
      image: newItem.image || 'https://images.unsplash.com/photo-1541140134513-85a161dc4a00?q=80&w=800',
      rating: 5.0,
      ingredients: [],
      dietary: [],
      stock: parseInt(newItem.stock),
      prepTime: '20 min'
