    setNewItem({ name: '', nameBn: '', description: '', price: '', category: 'Biryani', image: '', stock: '20' });
  };

  const handleExportExcel = () => {
    let data: any[] = [];
    if (reportType === 'sales') {
      data = orders.map(o => ({ ID: o.id, Customer: o.customerName, Total: o.total, Status: o.status, Date: o.createdAt }));
    } else if (reportType === 'inventory') {
      data = menuItems.map(m => ({ Name: m.name, Price: m.price, Stock: m.stock, Category: m.category }));
    } else {
      data = MOCK_ADMIN_USERS.map(u => ({ Name: u.name, Email: u.email, Points: u.loyaltyPoints, Tier: u.tier }));
    }

    const worksheet = XLSX.utils.json_to_sheet(data);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "BFC_Intelligence");
    XLSX.writeFile(workbook, `BFC_${reportType}_Report.xlsx`);
    showToast("Excel Export Generated.", "success");
  };

  const handleExportPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(22);
    doc.text("BFC INTELLIGENCE REPORT", 14, 20);
    doc.setFontSize(12);
    doc.text(`Protocol: ${reportType.toUpperCase()} | Timestamp: ${new Date().toLocaleString()}`, 14, 30);

    const body = reportType === 'sales' 
      ? orders.map(o => [o.id, o.customerName, `৳${o.total}`, o.status])
