    const head = reportType === 'sales'
      ? [['Mission ID', 'Citizen', 'Value', 'Status']]
      : reportType === 'inventory'
      ? [['Unit Name', 'Class', 'Value', 'Capacity']]
      : [['Citizen', 'Neural ID', 'Access Tier', 'Credits']];

    autoTable(doc, {
      startY: 40,
      head: head,
      body: body,
      theme: 'grid',
      headStyles: { fillColor: [220, 38, 38] },
    });

    doc.save(`BFC_${reportType}_Intelligence.pdf`);
    showToast("PDF Export Finalized.", "success");
  };

  const filteredMenuItems = useMemo(() => {
    return menuItems.filter(i => 
      i.name.toLowerCase().includes(menuStockSearch.toLowerCase()) || 
      i.category.toLowerCase().includes(menuStockSearch.toLowerCase())
    );
  }, [menuItems, menuStockSearch]);

