                       <div className="w-20 h-20 bg-gray-100 rounded-3xl overflow-hidden shadow-inner flex items-center justify-center">
                          {newItem.image ? <img src={newItem.image} className="w-full h-full object-cover" alt="Preview" /> : <i className="fas fa-image text-gray-300"></i>}
                       </div>
