            </button>
          ) : (
            <Button size="sm" onClick={() => setView('LOGIN')}>Initialize</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-10">
        {view === 'HOME' && (
          <div className="animate-slide-up space-y-20">
            <header className="relative h-[400px] lg:h-[600px] rounded-[50px] overflow-hidden shadow-2xl border-4 border-white">
               <img src="https://images.unsplash.com/photo-1541140134513-85a161dc4a00?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover" />
               <div className="absolute inset-0 bg-gradient-to-t from-black/80 to-transparent flex flex-col justify-end p-12">
                  <h2 className="text-5xl lg:text-8xl font-black text-white leading-[0.9] mb-8 tracking-tighter italic uppercase">CRAFTING<br/><span className="text-red-600">LEGENDS</span></h2>
                  <div className="flex gap-4">
                    <Button onClick={() => setView('MENU')}>DEPLOY MISSION</Button>
                    <button onClick={() => setView('VAULT')} className="px-8 py-4 bg-white/10 backdrop-blur-xl text-white rounded-2xl font-black text-[10px] uppercase tracking-widest border border-white/20">REWARDS VAULT</button>
                  </div>
               </div>
            </header>
            <section className="grid grid-cols-1 md:grid-cols-3 gap-8">
              {menuItems.slice(0, 3).map(item => (
                <div key={item.id} className="bg-white p-8 rounded-[40px] shadow-sm border group">
                   <div className="overflow-hidden rounded-3xl mb-6">
                      <img src={item.image} className="h-56 w-full object-cover group-hover:scale-110 transition-transform" />
                   </div>
                   <h4 className="text-2xl font-black mb-1">{item.name}</h4>
                   <p className="text-[10px] font-black text-red-600 uppercase mb-6 tracking-widest italic">{item.nameBn}</p>
                   <Button fullWidth variant="outline" onClick={() => addToCart(item)}>DEPLOY ৳{item.price}</Button>
                </div>
              ))}
            </section>
          </div>
        )}

        {view === 'VAULT' && (
          <div className="animate-slide-up space-y-12 pb-20">
             <div className="bg-gray-950 p-16 rounded-[50px] text-white flex flex-col lg:flex-row justify-between items-center gap-10">
                <div>
                   <h3 className="text-6xl font-black italic tracking-tighter leading-none mb-4 uppercase">REWARDS VAULT</h3>
                   <p className="text-gray-400 font-bold uppercase tracking-[4px]">Neural Balance: {currentUser?.loyaltyPoints || 0} Credits</p>
                </div>
                <div className="bg-white/5 p-10 rounded-[40px] border border-white/10 text-center min-w-[200px]">
                   <p className="text-[60px] font-black text-red-600 italic leading-none">{currentUser?.loyaltyPoints || 0}</p>
                   <p className="text-[9px] font-black uppercase tracking-widest text-gray-500 mt-2">Available Credits</p>
                </div>
             </div>
             <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
                {AVAILABLE_REWARDS.map(reward => (
                  <div key={reward.id} className="bg-white p-10 rounded-[40px] border shadow-sm flex flex-col justify-between">
                     <div>
                        <div className="w-16 h-16 bg-gray-950 text-white rounded-2xl flex items-center justify-center text-2xl mb-8">
                           <i className={`fas ${reward.icon}`}></i>
                        </div>
                        <h5 className="text-xl font-black italic mb-2 uppercase">{reward.title}</h5>
                        <p className="text-xs font-bold text-gray-400 mb-8">{reward.description}</p>
                     </div>
                     <button onClick={() => handleRedeem(reward)} className="w-full py-5 bg-gray-50 rounded-2xl text-[9px] font-black uppercase tracking-[4px] hover:bg-red-600 hover:text-white transition-all">Redeem {reward.pointsCost} Cr</button>
                  </div>
                ))}
             </div>
             {currentUser?.claimedVouchers && currentUser.claimedVouchers.length > 0 && (
               <div className="space-y-6">
                  <h4 className="text-2xl font-black uppercase italic tracking-tighter">Active Neural Links</h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {currentUser.claimedVouchers.map(v => (
                      <div key={v.id} className={`p-8 rounded-[35px] border-2 border-dashed flex flex-col gap-4 ${v.status === 'EXPENDED' ? 'opacity-40 grayscale' : 'border-emerald-500 bg-emerald-50/20'}`}>
                        <div className="flex justify-between items-center">
                          <p className="text-[10px] font-black uppercase tracking-widest">{v.title}</p>
                          <span className={`text-[8px] font-black px-2 py-1 rounded-lg ${v.status === 'ACTIVE' ? 'bg-emerald-500 text-white' : 'bg-gray-400 text-white'}`}>{v.status}</span>
                        </div>
                        <p className="text-2xl font-black tracking-[4px] font-mono text-center py-4 bg-white/50 rounded-2xl">{v.uniqueCode}</p>
                        <p className="text-[8px] font-black text-gray-400 text-center uppercase">Code required for mission deployment</p>
                      </div>
                    ))}
                  </div>
               </div>
             )}
          </div>
        )}

        {view === 'CART' && (
          <div className="max-w-4xl mx-auto animate-slide-up space-y-12 pb-20">
             <h3 className="text-5xl font-black uppercase italic tracking-tighter">MANIFEST</h3>
             <div className="bg-white p-10 rounded-[50px] shadow-3xl border space-y-10">
                {cart.map((c, i) => (
                  <div key={i} className="flex justify-between items-center p-4 border-b">
                    <div className="flex gap-4 items-center">
                       <img src={c.item.image} className="w-16 h-16 rounded-2xl object-cover" />
                       <div>
                          <h4 className="font-black italic">{c.item.name}</h4>
                          <p className="text-[10px] text-gray-400">৳{c.item.price} x {c.qty}</p>
                       </div>
                    </div>
                    <p className="font-black">৳{c.item.price * c.qty}</p>
                  </div>
                ))}

                <div className="space-y-6">
                   <p className="text-[10px] font-black uppercase tracking-widest text-gray-400">Neural Discount Link</p>
                   <div className="flex gap-4">
                      <input 
                        type="text" 
                        value={discountCode}
                        onChange={e => setDiscountCode(e.target.value)}
                        placeholder="ENTER UNIQUE CODE (E.G. BFC-XXXX-XXXX)" 
                        className="flex-1 bg-gray-50 p-5 rounded-2xl outline-none font-black text-xs tracking-[4px] border-2 border-transparent focus:border-red-600 transition-all uppercase"
                      />
                      <button onClick={applyDiscount} className="px-10 py-5 bg-gray-950 text-white rounded-2xl font-black text-[9px] uppercase tracking-widest">Apply Link</button>
                   </div>
                   {appliedVoucher && (
                     <div className="bg-emerald-50 p-4 rounded-xl border border-emerald-100 flex justify-between items-center animate-slide-up">
                        <p className="text-[10px] font-black text-emerald-700 uppercase tracking-widest">Linked: {appliedVoucher.title}</p>
                        <button onClick={() => setAppliedVoucher(null)} className="text-emerald-700"><i className="fas fa-times"></i></button>
                     </div>
                   )}
                </div>

                <div className="pt-8 border-t-4 border-gray-50 space-y-4">
                   <div className="flex justify-between text-[11px] font-black uppercase tracking-widest text-gray-400">
                      <span>Subtotal</span>
                      <span>৳{subtotal}</span>
                   </div>
                   <div className="flex justify-between text-[11px] font-black uppercase tracking-widest text-gray-400">
                      <span>Delivery Hub</span>
                      <span>৳{deliveryFee}</span>
                   </div>
                   {discountAmount > 0 && (
                     <div className="flex justify-between text-[11px] font-black uppercase tracking-widest text-red-600">
                        <span>Neural Discount</span>
                        <span>-৳{discountAmount}</span>
                     </div>
                   )}
                   <div className="flex justify-between text-4xl font-black italic border-t-2 pt-6">
                      <span>TOTAL</span>
                      <span className="text-red-600">৳{total}</span>
                   </div>
                </div>

                <div className="grid grid-cols-2 lg:grid-cols-6 gap-4">
                  {PAYMENT_METHODS.map(p => (
                    <button key={p.id} onClick={() => setSelectedPayment(p.id)} className={`p-6 rounded-3xl border-4 transition-all flex flex-col items-center gap-3 ${selectedPayment === p.id ? 'border-red-600 bg-red-50' : 'border-transparent bg-gray-50'}`}>
                       <i className={`fas ${p.icon} text-lg ${selectedPayment === p.id ? 'text-red-600' : 'text-gray-400'}`}></i>
                       <span className="text-[8px] font-black uppercase tracking-widest">{p.label}</span>
                    </button>
                  ))}
                </div>

                <Button fullWidth size="lg" className="rounded-[30px] py-8 text-base tracking-[6px]" onClick={handleFinalOrder} disabled={isCheckingOut || cart.length === 0}>
                  {isCheckingOut ? 'PROCESSING...' : 'DEPLOY MISSION'}
                </Button>
             </div>
          </div>
        )}
      </main>
      <ChatBot isOnline={isOnline} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useCallback } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User, AuditLog, ClaimedVoucher } from './types';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer
} from 'recharts';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import * as XLSX from 'xlsx';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200 }, { name: 'Sun', sales: 3800 }, { name: 'Mon', sales: 5200 },
  { name: 'Tue', sales: 4800 }, { name: 'Wed', sales: 6200 }, { name: 'Thu', sales: 5800 },
  { name: 'Fri', sales: 8500 },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, onLogout, menuItems, setMenuItems, orders, setOrders 
}) => {
  const allowedTabs = useMemo(() => {
    if (userRole === UserRole.ADMIN) return ['dashboard', 'orders', 'menu-stock', 'promotions', 'reports', 'audit'];
    if (userRole === UserRole.MANAGER) return ['dashboard', 'orders', 'menu-stock', 'promotions'];
    return ['orders'];
  }, [userRole]);

  const [activeTab, setActiveTab] = useState(allowedTabs[0]);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [adminToast, setAdminToast] = useState<{msg: string, type: string} | null>(null);
  const [showAddModal, setShowAddModal] = useState(false);
  const [menuStockSearch, setMenuStockSearch] = useState('');
  const [reportType, setReportType] = useState<'sales' | 'inventory' | 'customers'>('sales');

  const [newItem, setNewItem] = useState({
    name: '', nameBn: '', description: '', price: '', category: 'Biryani', image: '', stock: '20'
  });

  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([
    { id: 'LOG-001', userId: 'A-001', userName: 'Super Admin', action: 'SYSTEM_START', details: 'BFC Mainframe initialized.', timestamp: new Date(Date.now() - 86400000).toISOString(), level: 'INFO' },
  ]);

  const showToast = useCallback((msg: string, type: string) => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 4000);
  }, []);

  const addAuditLog = useCallback((action: string, details: string, level: AuditLog['level'] = 'INFO') => {
    const newLog: AuditLog = {
      id: `LOG-${Math.random().toString(36).slice(2, 7).toUpperCase()}`,
      userId: 'ADMIN-01',
      userName: 'Head Admin',
      action,
      details,
      timestamp: new Date().toISOString(),
      level
    };
    setAuditLogs(prev => [newLog, ...prev]);
  }, []);

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
    showToast(`Mission #${orderId.slice(-4)} updated to ${newStatus}.`, "success");
    addAuditLog('ORDER_UPDATE', `Order ${orderId} status set to ${newStatus}`);
  };

  const handleUpdateStock = (itemId: string, increment: boolean) => {
    setMenuItems(prev => prev.map(item => {
      if (item.id === itemId) {
        const newStock = increment ? item.stock + 1 : item.stock - 1;
        if (newStock < 0) return item;
        return { ...item, stock: newStock };
      }
      return item;
    }));
  };

  const handleAddItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newItem.name || !newItem.price) { showToast("Required parameters missing.", "error"); return; }
    const item: MenuItem = {
      id: Date.now().toString(),
      name: newItem.name,
      nameBn: newItem.nameBn || newItem.name,
      description: newItem.description || "Standard BFC Unit.",
      price: parseInt(newItem.price),
      category: newItem.category,
      image: newItem.image || 'https://images.unsplash.com/photo-1541140134513-85a161dc4a00?q=80&w=800',
      rating: 5.0,
      ingredients: [],
      dietary: [],
      stock: parseInt(newItem.stock),
      prepTime: '20 min'
    };
    setMenuItems(prev => [item, ...prev]);
    showToast(`${item.name} registered.`, "success");
    addAuditLog('INVENTORY_ADD', `New unit '${item.name}' added.`);
    setShowAddModal(false);
  };

  const handleExportExcel = () => {
    const data = orders.map(o => ({ ID: o.id, Customer: o.customerName, Total: o.total, Status: o.status }));
    const worksheet = XLSX.utils.json_to_sheet(data);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Report");
    XLSX.writeFile(workbook, `BFC_Intelligence.xlsx`);
    showToast("Excel Exported.", "success");
  };

  const handleExportPDF = () => {
    const doc = new jsPDF();
    doc.text("BFC Intelligence Report", 14, 20);
    const body = orders.map(o => [o.id, o.customerName, `৳${o.total}`, o.status]);
    autoTable(doc, { startY: 30, head: [['ID', 'Citizen', 'Value', 'Status']], body });
    doc.save(`BFC_Report.pdf`);
    showToast("PDF Exported.", "success");
  };

  const filteredMenuItems = useMemo(() => {
    return menuItems.filter(i => 
      i.name.toLowerCase().includes(menuStockSearch.toLowerCase()) || 
      i.category.toLowerCase().includes(menuStockSearch.toLowerCase())
    );
  }, [menuItems, menuStockSearch]);

  return (
    <div className="flex h-screen bg-[#F8FAFC] dark:bg-gray-950 overflow-hidden font-sans">
      {adminToast && (
        <div className="fixed top-6 left-1/2 -translate-x-1/2 z-[9999] px-8 py-3 bg-gray-900 text-white rounded-2xl shadow-2xl animate-slide-up font-black text-[10px] uppercase tracking-widest border border-white/10">
          {adminToast.msg}
        </div>
      )}

      {showAddModal && (
        <div className="fixed inset-0 z-[8000] flex items-center justify-center p-6 bg-gray-950/80 backdrop-blur-xl">
           <div className="bg-white dark:bg-gray-900 w-full max-w-2xl rounded-[60px] p-12 shadow-3xl animate-slide-up max-h-[90vh] overflow-y-auto scrollbar-hide">
              <div className="flex justify-between items-center mb-10">
                 <h3 className="text-4xl font-black uppercase italic tracking-tighter">New Asset Deploy</h3>
                 <button onClick={() => setShowAddModal(false)} className="w-12 h-12 bg-gray-100 rounded-2xl flex items-center justify-center"><i className="fas fa-times"></i></button>
              </div>
              <form onSubmit={handleAddItem} className="space-y-8">
                 <div className="grid grid-cols-2 gap-8">
                    <input required placeholder="UNIT NAME" className="w-full bg-gray-50 dark:bg-gray-800 p-6 rounded-3xl outline-none font-black text-xs uppercase" value={newItem.name} onChange={e=>setNewItem({...newItem, name:e.target.value})} />
                    <input placeholder="নাম" className="w-full bg-gray-50 dark:bg-gray-800 p-6 rounded-3xl outline-none font-bold text-sm" value={newItem.nameBn} onChange={e=>setNewItem({...newItem, nameBn:e.target.value})} />
                 </div>
                 <textarea placeholder="MISSION BRIEF" className="w-full bg-gray-50 dark:bg-gray-800 p-6 rounded-3xl outline-none min-h-[120px] font-bold text-xs" value={newItem.description} onChange={e=>setNewItem({...newItem, description:e.target.value})} />
                 <div className="grid grid-cols-3 gap-8">
                    <input type="number" required placeholder="PRICE" className="w-full bg-gray-50 dark:bg-gray-800 p-6 rounded-3xl font-black" value={newItem.price} onChange={e=>setNewItem({...newItem, price:e.target.value})} />
                    <select className="w-full bg-gray-50 dark:bg-gray-800 p-6 rounded-3xl font-black text-[10px] uppercase" value={newItem.category} onChange={e=>setNewItem({...newItem, category:e.target.value})}>
                       <option value="Biryani">Biryani</option>
                       <option value="Curry">Curry</option>
                       <option value="Desserts">Desserts</option>
                    </select>
                    <input type="number" placeholder="STOCK" className="w-full bg-gray-50 dark:bg-gray-800 p-6 rounded-3xl font-black" value={newItem.stock} onChange={e=>setNewItem({...newItem, stock:e.target.value})} />
                 </div>
                 <Button fullWidth size="lg" className="rounded-3xl py-8 tracking-[6px] shadow-2xl shadow-red-600/20">REGISTER ASSET</Button>
              </form>
           </div>
        </div>
      )}

      <aside className={`fixed lg:static inset-y-0 left-0 z-[250] w-72 bg-white dark:bg-gray-900 border-r dark:border-gray-800 transition-transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 border-b dark:border-gray-800 flex items-center justify-between">
           <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-red-600 rounded-2xl flex items-center justify-center text-white font-black italic">B</div>
              <h1 className="text-xl font-black text-red-600 tracking-tight italic">BFC HUB</h1>
           </div>
           <button className="lg:hidden" onClick={() => setSidebarOpen(false)}><i className="fas fa-times text-gray-400"></i></button>
        </div>
        <nav className="p-6 space-y-2">
          {allowedTabs.map(tab => (
            <button key={tab} onClick={() => setActiveTab(tab)} className={`w-full flex items-center gap-5 px-6 py-5 rounded-2xl uppercase text-[9px] font-black tracking-[4px] transition-all ${activeTab === tab ? 'bg-red-600 text-white shadow-2xl shadow-red-600/30' : 'text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-800'}`}>
              <i className={`fas ${
                tab === 'dashboard' ? 'fa-chart-pie' : 
                tab === 'orders' ? 'fa-list-check' : 
                tab === 'menu-stock' ? 'fa-utensils' : 
                tab === 'promotions' ? 'fa-tags' : 
                tab === 'reports' ? 'fa-file-invoice' : 'fa-shield-halved'
              } text-xs`}></i>
              <span>{tab.replace('-', ' ')}</span>
            </button>
          ))}
          <div className="pt-10">
            <button onClick={onLogout} className="w-full py-5 text-red-600 font-black uppercase text-[8px] tracking-[4px] border-2 border-red-50 rounded-2xl hover:bg-red-600 hover:text-white transition-all">Terminal Logout</button>
          </div>
        </nav>
      </aside>

      <main className="flex-1 overflow-y-auto bg-[#F8FAFC] dark:bg-gray-950 scrollbar-hide">
        <header className="sticky top-0 z-40 bg-white/80 dark:bg-gray-900/80 backdrop-blur-md px-10 py-6 border-b dark:border-gray-800 flex justify-between items-center">
           <div className="flex items-center gap-6">
              <button className="lg:hidden w-12 h-12 bg-gray-50 rounded-2xl" onClick={() => setSidebarOpen(true)}><i className="fas fa-bars"></i></button>
              <h2 className="text-3xl font-black uppercase italic tracking-tighter leading-none">{activeTab.replace('-', ' ')}</h2>
           </div>
           <div className="w-12 h-12 bg-gray-950 text-white rounded-2xl flex items-center justify-center font-black text-[10px] ring-4 ring-gray-100">{userRole.charAt(0)}</div>
        </header>

        <div className="p-10 space-y-12 max-w-[1600px] mx-auto w-full">
          {activeTab === 'dashboard' && (
            <div className="animate-slide-up space-y-12">
               <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
