  deliveryZone: string;
  deliverySlot: string;
  deliveryInstructions?: string;
  pointsEarned: number;
  trackingUpdates: Array<{ status: OrderStatus; time: string }>;
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  phone: string;
  password?: string;
  loyaltyPoints: number;
  tier: 'SILVER' | 'GOLD' | 'PLATINUM';
  wishlist: string[];
  referralCode: string;
  profileImage?: string;
  sessionToken?: string;
  claimedVouchers: ClaimedVoucher[];
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

export interface AuditLog {
  id: string;
  userId: string;
  userName: string;
  action: string;
  details: string;
  timestamp: string;
  level: 'INFO' | 'WARNING' | 'CRITICAL';
}

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem, RewardVoucher, ClaimedVoucher } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'warning' | 'info';
  id: number;
}

const AVAILABLE_REWARDS: RewardVoucher[] = [
  { id: 'RV-01', title: 'Free Borhani', description: 'Redeem points for ৳50 Discount.', pointsCost: 150, code: 'BORHANI', icon: 'fa-glass-water', discountValue: 50 },
  { id: 'RV-02', title: '20% Off Mission', description: 'Get 20% flat discount on your next order.', pointsCost: 300, code: 'OFF20', icon: 'fa-tags', discountValue: 20, isPercentage: true },
  { id: 'RV-03', title: 'Elite Discount', description: '৳100 off on any premium biryani.', pointsCost: 100, code: 'ELITE100', icon: 'fa-bolt', discountValue: 100 },
  { id: 'RV-04', title: 'Dessert Protocol', description: '৳30 discount on Mishti Doi.', pointsCost: 80, code: 'SWEET', icon: 'fa-cookie-bite', discountValue: 30 },
];

const App: React.FC = () => {
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT' | 'PROFILE'>('HOME');
  const [toasts, setToasts] = useState<Toast[]>([]);

  const [discountCodeInput, setDiscountCodeInput] = useState('');
  const [activeVoucher, setActiveVoucher] = useState<ClaimedVoucher | null>(null);
  const [isCheckingOut, setIsCheckingOut] = useState(false);

  // Auth states
  const [formEmail, setFormEmail] = useState('');
  const [formPass, setFormPass] = useState('');

  const showToast = useCallback((message: string, type: Toast['type'] = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('bfc_user_session');
    if (saved) {
      const user = JSON.parse(saved);
      setCurrentUser(user);
      if (user.role !== UserRole.CUSTOMER) setView('ADMIN');
    }
  }, []);

  const handleAuth = async () => {
    const role = formEmail.includes('admin') ? UserRole.ADMIN : UserRole.CUSTOMER;
    const user: User = {
      id: 'U-' + Math.random().toString(36).slice(2, 7),
      name: role === UserRole.ADMIN ? 'Head Admin' : 'Premium Member',
      email: formEmail,
      phone: '01700000000',
      role,
      loyaltyPoints: 1000,
      tier: 'GOLD',
      wishlist: [],
      referralCode: 'BFC-POWER',
      claimedVouchers: []
    };
    setCurrentUser(user);
    localStorage.setItem('bfc_user_session', JSON.stringify(user));
    setView(user.role === UserRole.ADMIN ? 'ADMIN' : 'HOME');
    showToast('Authenticated Successfully.', 'success');
  };

  const generateSecureCode = () => {
    const charset = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    const pick = () => charset.charAt(Math.floor(Math.random() * charset.length));
    return `BFC-${pick()}${pick()}${pick()}${pick()}-${pick()}${pick()}${pick()}${pick()}`;
  };

  const handleRedeem = (reward: RewardVoucher) => {
    if (!currentUser) { setView('LOGIN'); return; }
    if (currentUser.loyaltyPoints < reward.pointsCost) { showToast('Insufficient Points.', 'error'); return; }

    const uniqueCode = generateSecureCode();
    const newClaim: ClaimedVoucher = {
      id: 'CV-' + Date.now(),
      voucherId: reward.id,
      uniqueCode,
      status: 'ACTIVE',
      claimedAt: new Date().toISOString(),
      title: reward.title,
      discountValue: reward.discountValue || 0,
      isPercentage: !!reward.isPercentage,
      ownerId: currentUser.id,
      ownerName: currentUser.name
    };

    const updatedUser: User = {
      ...currentUser,
      loyaltyPoints: currentUser.loyaltyPoints - reward.pointsCost,
      claimedVouchers: [...currentUser.claimedVouchers, newClaim]
    };

    setCurrentUser(updatedUser);
    localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));
    showToast(`Reward Claimed! Code: ${uniqueCode}`, 'success');
  };

  const applyVoucher = () => {
    if (!currentUser) return;
    const code = discountCodeInput.trim().toUpperCase();
    const found = currentUser.claimedVouchers.find(v => v.uniqueCode === code && v.status === 'ACTIVE');

    if (found) {
      setActiveVoucher(found);
      showToast(`${found.title} Applied!`, 'success');
    } else {
      showToast('Invalid or Expired Code.', 'error');
      setActiveVoucher(null);
    }
  };

  const subtotal = cart.reduce((a, b) => a + (b.item.price * b.qty), 0);
  const delivery = cart.length > 0 ? 50 : 0;

  const discountAmount = useMemo(() => {
    if (!activeVoucher) return 0;
    return activeVoucher.isPercentage 
      ? Math.floor(subtotal * (activeVoucher.discountValue / 100)) 
      : activeVoucher.discountValue;
  }, [activeVoucher, subtotal]);

  const total = Math.max(0, subtotal + delivery - discountAmount);

  const handleCheckout = async () => {
    if (!currentUser) return;
    setIsCheckingOut(true);
    try {
      await new Promise(r => setTimeout(r, 1500));

      const order: Order = {
        id: 'ORD-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
        customerId: currentUser.id,
        customerName: currentUser.name,
        items: cart.map(c => ({ menuId: c.item.id, quantity: c.qty, price: c.item.price, name: c.item.name })),
        total,
        discountAmount,
        status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(),
        paymentStatus: 'PAID',
        paymentMethod: 'BKASH',
        address: 'Dhaka Sector 7',
        deliveryZone: 'Dhaka',
        deliverySlot: 'ASAP',
        pointsEarned: Math.floor(total / 10),
        trackingUpdates: [{ status: OrderStatus.PENDING, time: new Date().toLocaleTimeString() }]
      };

      // Invalidate the used voucher
      let updatedVouchers = currentUser.claimedVouchers;
      if (activeVoucher) {
        updatedVouchers = updatedVouchers.map(v => v.id === activeVoucher.id ? { ...v, status: 'EXPENDED' } : v);
      }

      const updatedUser: User = {
        ...currentUser,
        loyaltyPoints: currentUser.loyaltyPoints + Math.floor(total / 10),
        claimedVouchers: updatedVouchers
      };

      setAllOrders(prev => [order, ...prev]);
      setCurrentUser(updatedUser);
      localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));
      setCart([]);
      setActiveVoucher(null);
      setDiscountCodeInput('');
      setView('HOME');
      showToast('Order Placed! Voucher Used.', 'success');
    } finally {
      setIsCheckingOut(false);
    }
  };

  if (view === 'ADMIN') {
    return <AdminPanel 
      userRole={currentUser!.role} 
      onLogout={() => { setCurrentUser(null); setView('HOME'); localStorage.removeItem('bfc_user_session'); }}
      menuItems={menuItems} setMenuItems={setMenuItems}
      orders={allOrders} setOrders={setAllOrders}
    />;
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC]">
      <div className="fixed top-24 right-6 z-[6000] space-y-4 pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto bg-white/95 backdrop-blur-xl px-6 py-4 rounded-2xl shadow-2xl border flex items-center gap-4 animate-slide-up">
            <i className={`fas ${t.type === 'error' ? 'fa-circle-xmark text-red-600' : 'fa-circle-check text-emerald-600'}`}></i>
            <span className="text-[10px] font-black uppercase tracking-widest">{t.message}</span>
          </div>
        ))}
      </div>

      <nav className="sticky top-0 z-50 glass-nav border-b px-6 py-4 flex justify-between items-center">
        <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center text-white font-black italic">B</div>
          <h1 className="text-2xl font-black text-red-600 italic tracking-tighter">BFC</h1>
        </div>
        <div className="flex gap-6">
          <button onClick={() => setView('MENU')} className="text-[10px] font-black uppercase tracking-widest text-gray-500 hover:text-red-600">Menu</button>
          <button onClick={() => setView('VAULT')} className="text-[10px] font-black uppercase tracking-widest text-gray-500 hover:text-red-600">Vault</button>
          <button onClick={() => setView('CART')} className="relative w-10 h-10 bg-white border rounded-xl flex items-center justify-center shadow-sm hover:scale-105 transition-transform">
            <i className="fas fa-shopping-cart text-gray-800"></i>
