);

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem, RewardVoucher, ClaimedVoucher } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'warning' | 'info';
  id: number;
}

const AVAILABLE_REWARDS: RewardVoucher[] = [
  { id: 'RV-01', title: 'Free Borhani Protocol', description: 'Exchange 150 Cr for ৳50 Discount.', pointsCost: 150, code: 'BORHANI', icon: 'fa-glass-water', discountValue: 50 },
  { id: 'RV-02', title: '20% Neutralizer', description: 'Shatter 20% off your next payload.', pointsCost: 300, code: 'OFF20', icon: 'fa-tags', discountValue: 20, isPercentage: true },
  { id: 'RV-03', title: 'Elite Shield', description: 'Flat ৳100 protection on premium units.', pointsCost: 100, code: 'ELITE100', icon: 'fa-bolt', discountValue: 100 },
];

const App: React.FC = () => {
  const [menuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT' | 'PROFILE'>('HOME');
  const [toasts, setToasts] = useState<Toast[]>([]);

  const [discountCodeInput, setDiscountCodeInput] = useState('');
  const [activeVoucher, setActiveVoucher] = useState<ClaimedVoucher | null>(null);
  const [isCheckingOut, setIsCheckingOut] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);

  // Form states
  const [formEmail, setFormEmail] = useState('');
  const [formPass, setFormPass] = useState('');

  const showToast = useCallback((message: string, type: Toast['type'] = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
  }, []);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 50);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('bfc_user_session');
    if (saved) {
      const user = JSON.parse(saved);
      setCurrentUser(user);
      if (user.role !== UserRole.CUSTOMER) setView('ADMIN');
    }
  }, []);

  const handleAuth = async () => {
    const role = formEmail.includes('admin') ? UserRole.ADMIN : UserRole.CUSTOMER;
    const user: User = {
      id: 'U-' + Math.random().toString(36).slice(2, 7),
      name: role === UserRole.ADMIN ? 'Head Admin' : 'Elite Citizen',
      email: formEmail,
      phone: '01700000000',
      role,
      loyaltyPoints: 1250,
      tier: 'PLATINUM',
      wishlist: [],
      referralCode: 'BFC-ELITE',
      claimedVouchers: []
    };
    setCurrentUser(user);
    localStorage.setItem('bfc_user_session', JSON.stringify(user));
    setView(user.role === UserRole.ADMIN ? 'ADMIN' : 'HOME');
    showToast('Access Terminal Granted.', 'success');
  };

  const generateSecureCode = () => {
    const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    const pick = () => chars.charAt(Math.floor(Math.random() * chars.length));
    return `BFC-${pick()}${pick()}${pick()}-${pick()}${pick()}${pick()}-${pick()}${pick()}${pick()}`.toUpperCase();
  };

  const handleRedeem = (reward: RewardVoucher) => {
    if (!currentUser) { setView('LOGIN'); return; }
    if (currentUser.loyaltyPoints < reward.pointsCost) { showToast('Insufficient Neural Credits.', 'error'); return; }

    const uniqueCode = generateSecureCode();
    const newClaim: ClaimedVoucher = {
      id: 'CV-' + Date.now(),
      voucherId: reward.id,
      uniqueCode,
      status: 'ACTIVE',
      claimedAt: new Date().toISOString(),
      title: reward.title,
      discountValue: reward.discountValue || 0,
      isPercentage: !!reward.isPercentage,
      ownerId: currentUser.id,
      ownerName: currentUser.name
    };

    const updatedUser: User = {
      ...currentUser,
      loyaltyPoints: currentUser.loyaltyPoints - reward.pointsCost,
      claimedVouchers: [...currentUser.claimedVouchers, newClaim]
    };

    setCurrentUser(updatedUser);
    localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));
    showToast(`Code Unlocked: ${uniqueCode}`, 'success');
  };

  const applyVoucher = () => {
    if (!currentUser) return;
    const code = discountCodeInput.trim().toUpperCase();
    const found = currentUser.claimedVouchers.find(v => v.uniqueCode === code && v.status === 'ACTIVE');

    if (found) {
      setActiveVoucher(found);
      showToast('Neural Link Established.', 'success');
    } else {
      showToast('Link Refused: Invalid Code.', 'error');
      setActiveVoucher(null);
    }
  };

  const subtotal = cart.reduce((a, b) => a + (b.item.price * b.qty), 0);
  const delivery = cart.length > 0 ? 60 : 0;

  const discountAmount = useMemo(() => {
    if (!activeVoucher) return 0;
    return activeVoucher.isPercentage 
      ? Math.floor(subtotal * (activeVoucher.discountValue / 100)) 
      : activeVoucher.discountValue;
  }, [activeVoucher, subtotal]);

  const total = Math.max(0, subtotal + delivery - discountAmount);

  const handleCheckout = async () => {
    if (!currentUser) return;
    setIsCheckingOut(true);
    try {
      await new Promise(r => setTimeout(r, 2000));
      const order: Order = {
        id: 'MISSION-' + Math.random().toString(36).slice(2, 6).toUpperCase(),
        customerId: currentUser.id,
        customerName: currentUser.name,
        items: cart.map(c => ({ menuId: c.item.id, quantity: c.qty, price: c.item.price, name: c.item.name })),
        total,
        discountAmount,
        status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(),
        paymentStatus: 'PAID',
        paymentMethod: 'BKASH',
        address: 'Sector 7, High-Rise Hub',
        deliveryZone: 'Dhaka',
        deliverySlot: 'EXPRESS',
        pointsEarned: Math.floor(total / 8),
        trackingUpdates: [{ status: OrderStatus.PENDING, time: new Date().toLocaleTimeString() }]
      };

      let updatedVouchers = currentUser.claimedVouchers;
      if (activeVoucher) {
        updatedVouchers = updatedVouchers.map(v => v.id === activeVoucher.id ? { ...v, status: 'EXPENDED' } : v);
      }

      const updatedUser: User = {
        ...currentUser,
        loyaltyPoints: currentUser.loyaltyPoints + Math.floor(total / 8),
        claimedVouchers: updatedVouchers
      };

      setAllOrders(prev => [order, ...prev]);
      setCurrentUser(updatedUser);
      localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));
      setCart([]);
      setActiveVoucher(null);
      setDiscountCodeInput('');
      setView('HOME');
      showToast('Mission Deployed Successfully.', 'success');
    } finally {
      setIsCheckingOut(false);
    }
  };

  const addToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(c => c.item.id === item.id);
      if (existing) return prev.map(c => c.item.id === item.id ? { ...c, qty: c.qty + 1 } : c);
      return [...prev, { item, qty: 1 }];
    });
    showToast(`${item.name} added to payload.`, 'success');
  };

  if (view === 'ADMIN') {
    return <AdminPanel 
      userRole={currentUser!.role} 
      onLogout={() => { setCurrentUser(null); setView('HOME'); localStorage.removeItem('bfc_user_session'); }}
      menuItems={menuItems} setMenuItems={() => {}} 
      orders={allOrders} setOrders={setAllOrders}
    />;
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] selection:bg-red-100 selection:text-red-600">
      {/* Dynamic Toast System */}
      <div className="fixed top-24 right-6 z-[9999] space-y-4 pointer-events-none max-w-sm">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto glass-card elite-shadow px-6 py-4 rounded-[24px] flex items-center gap-4 animate-slide-up border-white/50">
            <div className={`w-8 h-8 rounded-full flex items-center justify-center ${t.type === 'error' ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>
               <i className={`fas ${t.type === 'error' ? 'fa-bolt' : 'fa-check'} text-xs`}></i>
            </div>
            <span className="text-[10px] font-black uppercase tracking-[2px]">{t.message}</span>
          </div>
        ))}
      </div>

      {/* Elite Floating Navbar */}
      <nav className={`fixed top-0 inset-x-0 z-[5000] transition-all duration-500 px-6 py-4 flex justify-between items-center ${isScrolled ? 'bg-white/80 backdrop-blur-2xl shadow-xl py-3' : 'bg-transparent'}`}>
        <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 bg-red-600 rounded-[14px] flex items-center justify-center text-white font-black italic shadow-2xl group-hover:rotate-6 transition-transform">B</div>
          <h1 className="text-2xl font-black text-gray-900 italic tracking-tighter">BFC <span className="text-red-600">ELITE</span></h1>
        </div>

        <div className="hidden lg:flex items-center gap-12">
          {['HOME', 'MENU', 'VAULT'].map(v => (
            <button key={v} onClick={() => setView(v as any)} className={`text-[10px] font-black uppercase tracking-[4px] transition-colors ${view === v ? 'text-red-600' : 'text-gray-400 hover:text-gray-900'}`}>{v}</button>
          ))}
        </div>

        <div className="flex items-center gap-5">
          <button onClick={() => setView('CART')} className="relative w-12 h-12 glass-card rounded-2xl flex items-center justify-center shadow-sm hover:scale-105 active:scale-95 transition-all">
            <i className="fas fa-shopping-basket text-gray-800 text-sm"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[8px] w-5 h-5 rounded-full flex items-center justify-center font-black animate-bounce ring-4 ring-white">{cart.length}</span>}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-12 h-12 bg-gray-950 text-white rounded-2xl font-black flex items-center justify-center shadow-2xl ring-2 ring-white hover:rotate-3 transition-transform">{currentUser.name.charAt(0)}</button>
          ) : (
            <Button size="sm" className="rounded-2xl px-8" onClick={() => setView('LOGIN')}>INITIALIZE</Button>
          )}
        </div>
      </nav>

      <main className="pt-0">
        {view === 'LOGIN' && (
          <div className="min-h-screen flex items-center justify-center p-6 bg-gray-950">
            <div className="absolute inset-0 opacity-20 pointer-events-none overflow-hidden">
               <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(circle_at_50%_50%,#dc2626_0,transparent_50%)]"></div>
            </div>
            <div className="w-full max-w-md animate-slide-up relative">
              <div className="bg-white/5 backdrop-blur-3xl p-12 rounded-[50px] border border-white/10 space-y-10 shadow-3xl text-white">
                <div className="text-center">
                  <h2 className="text-5xl font-black italic uppercase tracking-tighter mb-2">Initialize</h2>
                  <p className="text-xs font-bold text-gray-500 uppercase tracking-[4px]">Elite Terminal Access</p>
                </div>
                <div className="space-y-5">
                  <input placeholder="NEURAL ID" className="w-full bg-white/5 p-6 rounded-[24px] outline-none border border-white/10 focus:border-red-600 font-black text-xs uppercase tracking-widest transition-all" value={formEmail} onChange={e=>setFormEmail(e.target.value)} />
                  <input type="password" placeholder="ACCESS KEY" className="w-full bg-white/5 p-6 rounded-[24px] outline-none border border-white/10 focus:border-red-600 font-black text-xs tracking-widest transition-all" value={formPass} onChange={e=>setFormPass(e.target.value)} />
                  <Button fullWidth size="lg" className="rounded-[24px] py-7 tracking-[10px]" onClick={handleAuth}>DECRYPT & ENTER</Button>
                </div>
              </div>
            </div>
          </div>
        )}

        {view === 'HOME' && (
          <div className="animate-slide-up">
            <section className="relative h-screen flex items-center px-10 overflow-hidden bg-gray-900">
               <img src="https://images.unsplash.com/photo-1633945274405-b6c8069047b0?q=80&w=2000" className="absolute inset-0 w-full h-full object-cover opacity-50" />
               <div className="absolute inset-0 bg-gradient-to-r from-gray-950 via-gray-950/40 to-transparent"></div>
               <div className="relative z-10 max-w-4xl space-y-10">
                  <p className="text-red-600 font-black uppercase tracking-[12px] text-xs">CRAFTING LEGENDS SINCE '99</p>
                  <h2 className="text-7xl lg:text-[140px] font-black text-white leading-[0.8] tracking-tighter italic uppercase">UNLEASH<br/><span className="text-red-600">THE TASTE</span></h2>
                  <p className="text-gray-400 font-bold text-lg max-w-xl leading-relaxed uppercase tracking-wide">The ultimate fusion of traditional spice and modern elite delivery service. Your payload is ready.</p>
                  <div className="flex flex-wrap gap-6 pt-6">
                    <Button size="lg" className="rounded-[24px] px-12 py-8 tracking-[6px]" onClick={() => setView('MENU')}>EXPLORE REGISTRY</Button>
                    <button onClick={() => setView('VAULT')} className="px-12 py-8 bg-white/5 backdrop-blur-xl text-white rounded-[24px] font-black text-[10px] uppercase tracking-[6px] border border-white/10 hover:bg-white/10 transition-all">VAULT ACCESS</button>
                  </div>
               </div>
               <div className="absolute bottom-10 right-10 flex flex-col items-end gap-2 text-white/30 font-black italic select-none">
                  <span className="text-8xl leading-none">01</span>
                  <span className="text-xs uppercase tracking-[8px]">CORE INFRASTRUCTURE</span>
               </div>
            </section>

            <section className="py-32 px-10 max-w-7xl mx-auto space-y-20">
               <div className="flex justify-between items-end">
                  <h3 className="text-5xl font-black italic uppercase tracking-tighter">Elite Selections</h3>
                  <button onClick={() => setView('MENU')} className="text-[10px] font-black uppercase tracking-[4px] text-gray-400 hover:text-red-600 transition-colors">View All Registry <i className="fas fa-arrow-right ml-2"></i></button>
               </div>
               <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
                  {menuItems.slice(0, 3).map(item => (
                    <div key={item.id} className="group relative bg-white p-6 rounded-[50px] elite-shadow border border-gray-100 hover:-translate-y-4 transition-all duration-500">
