            <button key={v} onClick={() => setView(v as any)} className={`text-[10px] font-black uppercase tracking-[4px] transition-colors ${view === v ? 'text-red-600' : (isScrolled || view !== 'HOME' ? 'text-gray-400 hover:text-gray-950' : 'text-white/70 hover:text-white')}`}>{v}</button>
          ))}
