          <button onClick={() => setView('CART')} className={`relative w-12 h-12 glass-card rounded-2xl flex items-center justify-center shadow-sm hover:scale-105 active:scale-95 transition-all ${isScrolled || view !== 'HOME' ? '' : 'bg-white/10 text-white border-white/20'}`}>
