                </div>
              ))}
            </div>

            {currentUser?.claimedVouchers && currentUser.claimedVouchers.length > 0 && (
              <div className="space-y-10">
                <h4 className="text-4xl font-black italic uppercase tracking-tighter text-center">Neural Vouchers</h4>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {currentUser.claimedVouchers.map(v => (
                    <div key={v.id} className={`p-8 rounded-[40px] border-2 border-dashed flex flex-col gap-6 transition-all ${v.status === 'EXPENDED' ? 'opacity-30 grayscale' : 'bg-emerald-50 border-emerald-400 elite-shadow'}`}>
                      <div className="flex justify-between items-center">
                        <p className="text-[9px] font-black uppercase tracking-[4px] text-emerald-800">{v.title}</p>
                        <span className={`text-[8px] font-black uppercase px-3 py-1 rounded-xl shadow-lg ${v.status === 'ACTIVE' ? 'bg-emerald-600 text-white' : 'bg-gray-400 text-white'}`}>{v.status}</span>
