                </>
              )}
            </div>
          </div>
        )}

        {view === 'PROFILE' && (
          <div className="pt-32 pb-40 px-6 max-w-5xl mx-auto space-y-12 animate-slide-up">
             <div className="bg-white p-12 lg:p-16 rounded-[60px] elite-shadow border border-gray-100 flex flex-col lg:flex-row items-center gap-12">
                <div className="w-32 h-32 bg-gray-950 text-white rounded-[40px] flex items-center justify-center text-5xl font-black shadow-3xl ring-8 ring-gray-50">
                   {currentUser?.name.charAt(0) || 'E'}
                </div>
                <div className="text-center lg:text-left space-y-4">
                   <h3 className="text-5xl font-black uppercase italic tracking-tighter">{currentUser?.name || 'Elite Citizen'}</h3>
                   <div className="flex flex-wrap justify-center lg:justify-start gap-4">
                      <span className="px-6 py-2 bg-red-600 text-white rounded-full text-[9px] font-black uppercase tracking-[4px]">{currentUser?.tier || 'PLATINUM'} RANK</span>
                      <span className="px-6 py-2 bg-gray-950 text-white rounded-full text-[9px] font-black uppercase tracking-[4px]">{currentUser?.loyaltyPoints || 0} CREDITS</span>
                   </div>
                   <p className="text-xs text-gray-400 font-bold tracking-widest uppercase">{currentUser?.email || 'neural@bfc.elite'}</p>
                </div>
                <div className="lg:ml-auto">
                   <Button variant="danger" onClick={() => { setCurrentUser(null); localStorage.removeItem('bfc_user_session'); setView('HOME'); }}>DEACTIVATE TERMINAL</Button>
                </div>
             </div>

             <div className="space-y-8">
                <h4 className="text-3xl font-black italic uppercase tracking-tighter">Recent Missions</h4>
                <div className="grid grid-cols-1 gap-6">
                   {allOrders.filter(o => o.customerId === currentUser?.id).map(o => (
                      <div key={o.id} className="bg-white p-8 rounded-[40px] border border-gray-100 elite-shadow flex flex-col lg:flex-row justify-between items-center gap-6">
                         <div className="flex items-center gap-6">
                            <div className="w-16 h-16 bg-gray-50 rounded-[24px] flex items-center justify-center text-red-600">
                               <i className="fas fa-satellite"></i>
