                         <div className="text-center lg:text-right">
                            <p className="text-2xl font-black italic">৳{o.total}</p>
                            <p className="text-[9px] text-gray-400 font-black uppercase tracking-widest">{new Date(o.createdAt).toLocaleDateString()} • {o.items.length} UNITS</p>
                         </div>
                      </div>
                   ))}
                   {allOrders.filter(o => o.customerId === currentUser?.id).length === 0 && (
                      <div className="text-center py-12 bg-gray-50 rounded-[40px] border border-dashed border-gray-200">
                         <p className="text-[9px] font-black text-gray-400 uppercase tracking-[6px]">No combat history recorded.</p>
                      </div>
                   )}
                </div>
             </div>
          </div>
        )}
      </main>

      <ChatBot isOnline={true} />
    </div>
  );
};

export default App;

export enum UserRole {
  ADMIN = 'ADMIN',
  MANAGER = 'MANAGER',
  STAFF = 'STAFF',
  CUSTOMER = 'CUSTOMER'
}

export enum OrderStatus {
  PENDING = 'PENDING',
  PREPARING = 'PREPARING',
  READY = 'READY',
  ON_THE_WAY = 'ON_THE_WAY',
  DELIVERED = 'DELIVERED',
  CANCELLED = 'CANCELLED'
}

export type LayoutPreset = 
  | 'ELITE_DARK' 
  | 'CLASSIC_RED' 
  | 'CYBER_NEON' 
  | 'MINIMAL_WHITE' 
  | 'NATURE_GREEN' 
  | 'LUXURY_GOLD' 
  | 'RETRO_VIBE' 
  | 'BOLD_MONO' 
  | 'PASTEL_SOFT' 
  | 'HIGH_TECH';

export interface SiteCMS {
  activeLayout: LayoutPreset;
  hero: {
    title: string;
    subtitle: string;
    description: string;
    image: string;
    cta: string;
  };
  navigation: {
    brand: string;
    links: { [key: string]: string };
  };
  vault: {
    title: string;
    description: string;
  };
}

export interface MenuItem {
  id: string;
  name: string;
  nameBn: string;
  description: string;
  price: number;
  category: string;
  image: string;
  stock: number;
}

export interface CartItem {
  item: MenuItem;
  qty: number;
}

export interface ClaimedVoucher {
  id: string;
  uniqueCode: string;
  status: 'ACTIVE' | 'EXPENDED';
  title: string;
  discountValue: number;
  isPercentage: boolean;
}

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  items: any[];
  total: number;
  status: OrderStatus;
  createdAt: string;
  paymentMethod: string;
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  loyaltyPoints: number;
  claimedVouchers: ClaimedVoucher[];
  tier: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem, SiteCMS, LayoutPreset, ClaimedVoucher } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

const DEFAULT_CMS: SiteCMS = {
  activeLayout: 'ELITE_DARK',
  hero: {
    title: "CRAFTING LEGENDS",
    subtitle: "ESTABLISHED 1999",
    description: "The definitive taste of Bangladesh, delivered through an elite neural logistics network.",
    image: "https://images.unsplash.com/photo-1633945274405-b6c8069047b0?q=80&w=2000",
    cta: "EXPLORE REGISTRY"
  },
  navigation: {
    brand: "BFC ELITE",
    links: { home: "HOME", menu: "MENU", vault: "VAULT", profile: "PROFILE" }
  },
  vault: {
    title: "Vault",
    description: "Neutral Credit Protocol Active"
  }
};

const App: React.FC = () => {
  const [cms, setCms] = useState<SiteCMS>(() => {
    const saved = localStorage.getItem('bfc_cms');
    return saved ? JSON.parse(saved) : DEFAULT_CMS;
  });

  const [menuItems, setMenuItems] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('bfc_menu');
    return saved ? JSON.parse(saved) : MOCK_MENU;
  });

  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT' | 'PROFILE'>('HOME');
  const [paymentStep, setPaymentStep] = useState<'IDLE' | 'SELECT' | 'PROCESSING' | 'SUCCESS'>('IDLE');

  const [toasts, setToasts] = useState<any[]>([]);
  const [activeVoucher, setActiveVoucher] = useState<ClaimedVoucher | null>(null);
  const [selectedPayment, setSelectedPayment] = useState('');

  const showToast = useCallback((message: string, type: 'success' | 'error' = 'success') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 3000);
  }, []);

  useEffect(() => {
    localStorage.setItem('bfc_cms', JSON.stringify(cms));
    localStorage.setItem('bfc_menu', JSON.stringify(menuItems));
  }, [cms, menuItems]);

  const subtotal = cart.reduce((a, b) => a + (b.item.price * b.qty), 0);
  const delivery = cart.length > 0 ? 60 : 0;
  const discount = activeVoucher ? (activeVoucher.isPercentage ? (subtotal * activeVoucher.discountValue / 100) : activeVoucher.discountValue) : 0;
  const total = Math.max(0, subtotal + delivery - discount);

  const getThemeClasses = () => {
    switch (cms.activeLayout) {
      case 'CLASSIC_RED': return 'bg-red-50 text-gray-900 font-serif';
      case 'CYBER_NEON': return 'bg-black text-cyan-400 font-mono uppercase';
      case 'NATURE_GREEN': return 'bg-emerald-50 text-emerald-950';
      case 'MINIMAL_WHITE': return 'bg-white text-gray-400 font-light';
      case 'LUXURY_GOLD': return 'bg-stone-900 text-amber-500';
      default: return 'bg-[#F8FAFC] text-gray-950 font-sans';
    }
  };

  const handleAuth = () => {
    const user: User = {
      id: 'U-1', name: 'Elite Admin', email: 'admin@bfc.com', role: UserRole.ADMIN, loyaltyPoints: 5000, tier: 'PLATINUM', claimedVouchers: []
    };
    setCurrentUser(user);
    setView('ADMIN');
    showToast('Admin Authorized.');
  };

  const processPayment = async () => {
    if (!selectedPayment) return showToast('Select Method', 'error');
    setPaymentStep('PROCESSING');
    await new Promise(r => setTimeout(r, 2000));
    setPaymentStep('SUCCESS');
    const newOrder: Order = {
      id: 'ORD-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
      customerId: currentUser?.id || 'GUEST',
      customerName: currentUser?.name || 'Guest',
      items: cart,
      total,
      status: OrderStatus.PENDING,
      createdAt: new Date().toISOString(),
      paymentMethod: selectedPayment
    };
    setAllOrders(p => [newOrder, ...p]);
    setCart([]);
    setTimeout(() => { setPaymentStep('IDLE'); setView('HOME'); }, 3000);
  };

  if (view === 'ADMIN') {
    return (
      <AdminPanel 
        cms={cms} setCms={setCms}
        menuItems={menuItems} setMenuItems={setMenuItems}
        orders={allOrders} setOrders={setAllOrders}
        onLogout={() => setView('HOME')}
      />
    );
  }

  return (
    <div className={`min-h-screen transition-all duration-700 ${getThemeClasses()} pb-24 lg:pb-0`}>
      {/* Toast System */}
      <div className="fixed top-24 right-6 z-[9999] space-y-4 pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto glass-card px-6 py-4 rounded-2xl flex items-center gap-4 animate-slide-up elite-shadow">
            <i className={`fas ${t.type === 'error' ? 'fa-bolt text-red-600' : 'fa-check text-emerald-600'}`}></i>
            <span className="text-[10px] font-black uppercase tracking-widest">{t.message}</span>
          </div>
        ))}
      </div>

      <nav className="fixed top-0 inset-x-0 z-[5000] px-6 py-4 flex justify-between items-center bg-white/80 backdrop-blur-2xl shadow-xl border-b">
        <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('HOME')}>
          <div className="w-8 h-8 bg-red-600 rounded-lg flex items-center justify-center text-white font-black italic">B</div>
          <h1 className="text-xl font-black italic tracking-tighter uppercase">{cms.navigation.brand}</h1>
        </div>
        <div className="flex gap-4 items-center">
          <button onClick={() => setView('MENU')} className="text-[10px] font-black uppercase tracking-widest text-gray-400 hover:text-red-600">Menu</button>
          <button onClick={() => setView('VAULT')} className="text-[10px] font-black uppercase tracking-widest text-gray-400 hover:text-red-600">Vault</button>
          <button onClick={() => setView('CART')} className="relative w-10 h-10 bg-gray-100 rounded-xl flex items-center justify-center">
            <i className="fas fa-shopping-basket"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[8px] w-4 h-4 rounded-full flex items-center justify-center">{cart.length}</span>}
          </button>
          <button onClick={() => setView('LOGIN')} className="w-10 h-10 bg-gray-900 text-white rounded-xl flex items-center justify-center"><i className="fas fa-user-shield"></i></button>
        </div>
      </nav>

      <main className="pt-20">
        {view === 'HOME' && (
          <div className="animate-slide-up">
            <section className="relative h-[80vh] flex items-center px-10 overflow-hidden bg-gray-900 text-white">
              <img src={cms.hero.image} className="absolute inset-0 w-full h-full object-cover opacity-40" />
              <div className="relative z-10 max-w-4xl space-y-6">
                <p className="text-red-600 font-black uppercase tracking-[8px] text-xs">{cms.hero.subtitle}</p>
                <h2 className="text-6xl lg:text-9xl font-black leading-none tracking-tighter italic uppercase">{cms.hero.title}</h2>
                <p className="text-gray-400 font-bold text-lg max-w-xl">{cms.hero.description}</p>
                <Button size="lg" className="rounded-2xl" onClick={() => setView('MENU')}>{cms.hero.cta}</Button>
              </div>
            </section>
          </div>
        )}

        {view === 'MENU' && (
          <div className="p-10 max-w-7xl mx-auto space-y-12 animate-slide-up">
            <h2 className="text-5xl font-black italic uppercase tracking-tighter text-center">Neural Menu</h2>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              {menuItems.map(item => (
                <div key={item.id} className="bg-white p-6 rounded-[40px] shadow-xl border group">
                  <div className="h-64 rounded-[30px] overflow-hidden mb-6">
                    <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform" />
                  </div>
                  <h4 className="text-2xl font-black italic uppercase mb-1">{item.name}</h4>
                  <p className="text-[10px] font-black text-red-600 uppercase mb-6">{item.nameBn}</p>
                  <div className="flex justify-between items-center">
                    <span className="text-xl font-black">৳{item.price}</span>
                    <Button onClick={() => {
                      setCart(prev => {
                        const ex = prev.find(c => c.item.id === item.id);
                        if (ex) return prev.map(c => c.item.id === item.id ? {...c, qty: c.qty+1} : c);
                        return [...prev, {item, qty:1}];
                      });
                      showToast('Added to cart');
                    }}>+ ADD</Button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="max-w-2xl mx-auto p-10 space-y-12 animate-slide-up">
            <h2 className="text-5xl font-black italic uppercase text-center">Manifest</h2>
            {paymentStep === 'IDLE' && (
              <div className="bg-white p-10 rounded-[50px] shadow-2xl space-y-8">
                {cart.map((c, i) => (
                  <div key={i} className="flex justify-between items-center border-b pb-4">
                    <span className="font-black italic uppercase">{c.item.name} x {c.qty}</span>
                    <span className="font-black">৳{c.item.price * c.qty}</span>
                  </div>
                ))}
                <div className="text-4xl font-black italic flex justify-between pt-6 border-t">
                  <span>TOTAL</span>
                  <span className="text-red-600">৳{total}</span>
                </div>
                <Button fullWidth size="lg" onClick={() => setPaymentStep('SELECT')}>DEPLOY PAYMENT</Button>
              </div>
            )}

            {paymentStep === 'SELECT' && (
              <div className="bg-white p-10 rounded-[50px] shadow-2xl space-y-8 animate-slide-up">
                <h3 className="text-xl font-black uppercase text-center">Select Gateway</h3>
                <div className="grid grid-cols-2 gap-4">
                  {['BKASH', 'NAGAD', 'CARD', 'COD'].map(m => (
                    <button key={m} onClick={() => setSelectedPayment(m)} className={`p-8 rounded-2xl border-2 font-black tracking-widest ${selectedPayment === m ? 'border-red-600 bg-red-50 text-red-600' : 'border-gray-100 text-gray-400'}`}>{m}</button>
                  ))}
                </div>
                <div className="flex gap-4">
                  <Button variant="outline" fullWidth onClick={() => setPaymentStep('IDLE')}>BACK</Button>
                  <Button fullWidth onClick={processPayment}>CONFIRM ৳{total}</Button>
                </div>
              </div>
            )}

            {paymentStep === 'PROCESSING' && (
              <div className="flex flex-col items-center justify-center py-20 space-y-6">
                <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin"></div>
                <p className="font-black uppercase tracking-[5px] text-gray-400">Verifying Signal...</p>
              </div>
            )}

            {paymentStep === 'SUCCESS' && (
              <div className="text-center py-20 space-y-6 animate-bounce">
                <i className="fas fa-check-circle text-8xl text-emerald-500"></i>
                <h3 className="text-4xl font-black italic uppercase">MISSION SUCCESS</h3>
                <p className="text-gray-400 font-bold">Your payload is on the way.</p>
              </div>
            )}
          </div>
        )}

        {view === 'LOGIN' && (
          <div className="max-w-md mx-auto mt-20 p-10 bg-white rounded-[50px] shadow-3xl border space-y-8 animate-slide-up">
            <h2 className="text-4xl font-black italic uppercase text-center">TERMINAL</h2>
            <div className="space-y-4">
              <input placeholder="NEURAL ID" className="w-full bg-gray-50 p-6 rounded-2xl outline-none font-black text-xs uppercase" />
              <input type="password" placeholder="KEY" className="w-full bg-gray-50 p-6 rounded-2xl outline-none font-black text-xs uppercase" />
              <Button fullWidth size="lg" onClick={handleAuth}>AUTHORIZE</Button>
            </div>
          </div>
        )}
      </main>
      <ChatBot isOnline={true} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { UserRole, Order, MenuItem, SiteCMS, LayoutPreset } from './types';
import { Button } from './components/Button';

interface AdminPanelProps {
  cms: SiteCMS;
  setCms: (cms: SiteCMS) => void;
  menuItems: MenuItem[];
  setMenuItems: (items: MenuItem[]) => void;
  orders: Order[];
  setOrders: (orders: Order[]) => void;
  onLogout: () => void;
}

const LAYOUTS: { id: LayoutPreset; name: string; color: string }[] = [
  { id: 'ELITE_DARK', name: 'Elite Dark', color: 'bg-gray-950' },
  { id: 'CLASSIC_RED', name: 'Classic BFC', color: 'bg-red-600' },
  { id: 'CYBER_NEON', name: 'Cyberpunk', color: 'bg-cyan-500' },
  { id: 'MINIMAL_WHITE', name: 'Clean Minimal', color: 'bg-white border' },
  { id: 'NATURE_GREEN', name: 'Organic Nature', color: 'bg-emerald-600' },
  { id: 'LUXURY_GOLD', name: 'Luxury Gold', color: 'bg-amber-600' },
  { id: 'RETRO_VIBE', name: '90s Retro', color: 'bg-pink-500' },
  { id: 'BOLD_MONO', name: 'Bold Mono', color: 'bg-black' },
  { id: 'PASTEL_SOFT', name: 'Soft Pastel', color: 'bg-purple-300' },
  { id: 'HIGH_TECH', name: 'High-Tech Blue', color: 'bg-blue-700' },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  cms, setCms, menuItems, setMenuItems, orders, onLogout 
}) => {
  const [tab, setTab] = useState<'LAYOUT' | 'CMS' | 'MENU' | 'ORDERS'>('LAYOUT');
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);

  const updateCms = (path: string, value: string) => {
    const keys = path.split('.');
    const newCms = { ...cms };
    let curr: any = newCms;
    for (let i = 0; i < keys.length - 1; i++) curr = curr[keys[i]];
    curr[keys[keys.length - 1]] = value;
    setCms(newCms);
  };

  const deleteMenuItem = (id: string) => {
    setMenuItems(menuItems.filter(i => i.id !== id));
  };

  const saveMenuItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingItem) return;
    if (menuItems.find(i => i.id === editingItem.id)) {
      setMenuItems(menuItems.map(i => i.id === editingItem.id ? editingItem : i));
    } else {
      setMenuItems([...menuItems, editingItem]);
    }
    setEditingItem(null);
  };

  return (
    <div className="flex h-screen bg-gray-950 text-white font-sans overflow-hidden">
      <aside className="w-80 bg-gray-900 border-r border-white/5 p-8 flex flex-col gap-8">
        <h1 className="text-2xl font-black italic tracking-tighter text-red-600">COMMANDER</h1>
        <nav className="flex flex-col gap-2">
          {['LAYOUT', 'CMS', 'MENU', 'ORDERS'].map((t: any) => (
            <button key={t} onClick={() => setTab(t)} className={`p-5 rounded-2xl text-[10px] font-black uppercase tracking-[4px] text-left transition-all ${tab === t ? 'bg-red-600 text-white' : 'text-gray-500 hover:bg-white/5'}`}>{t}</button>
          ))}
          <button onClick={onLogout} className="mt-10 p-5 rounded-2xl text-[8px] font-black uppercase tracking-[4px] border border-red-600/20 text-red-600">Exit Hub</button>
        </nav>
      </aside>

      <main className="flex-1 overflow-y-auto p-12 custom-scrollbar">
        {tab === 'LAYOUT' && (
          <div className="space-y-12 animate-slide-up">
            <h2 className="text-4xl font-black italic uppercase">Layout Store</h2>
            <div className="grid grid-cols-2 lg:grid-cols-5 gap-6">
              {LAYOUTS.map(l => (
                <button key={l.id} onClick={() => setCms({ ...cms, activeLayout: l.id })} className={`p-6 rounded-[35px] border-4 transition-all flex flex-col items-center gap-4 ${cms.activeLayout === l.id ? 'border-red-600 scale-105' : 'border-white/5'}`}>
                   <div className={`w-16 h-16 rounded-2xl ${l.color} shadow-2xl`}></div>
                   <span className="text-[10px] font-black uppercase tracking-widest">{l.name}</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {tab === 'CMS' && (
          <div className="space-y-12 animate-slide-up">
            <h2 className="text-4xl font-black italic uppercase">Neural Content Editor</h2>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
              <section className="space-y-6">
                 <h3 className="text-xs font-black text-red-600 uppercase tracking-[4px]">Hero Terminal</h3>
                 <div className="space-y-4">
                    <InputField label="Hero Title" value={cms.hero.title} onChange={v => updateCms('hero.title', v)} />
                    <InputField label="Hero Subtitle" value={cms.hero.subtitle} onChange={v => updateCms('hero.subtitle', v)} />
                    <InputField label="Hero Description" value={cms.hero.description} onChange={v => updateCms('hero.description', v)} />
                    <InputField label="Hero Image URL" value={cms.hero.image} onChange={v => updateCms('hero.image', v)} />
                 </div>
              </section>
              <section className="space-y-6">
                 <h3 className="text-xs font-black text-red-600 uppercase tracking-[4px]">Brand Identity</h3>
                 <div className="space-y-4">
                    <InputField label="Brand Name" value={cms.navigation.brand} onChange={v => updateCms('navigation.brand', v)} />
                    <InputField label="Vault Title" value={cms.vault.title} onChange={v => updateCms('vault.title', v)} />
                 </div>
              </section>
            </div>
          </div>
        )}

        {tab === 'MENU' && (
          <div className="space-y-12 animate-slide-up">
            <div className="flex justify-between items-center">
               <h2 className="text-4xl font-black italic uppercase">Menu Registry</h2>
               <Button onClick={() => setEditingItem({ id: 'M-'+Date.now(), name: '', nameBn: '', description: '', price: 0, category: 'General', image: '', stock: 0 })}>ADD NEW UNIT</Button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {menuItems.map(i => (
                <div key={i.id} className="bg-gray-900 p-8 rounded-[40px] border border-white/5 flex flex-col items-center gap-4">
                   <img src={i.image} className="w-20 h-20 rounded-2xl object-cover" />
                   <h4 className="font-black italic uppercase text-center">{i.name}</h4>
                   <div className="flex gap-2">
                      <Button size="sm" onClick={() => setEditingItem(i)}>Edit</Button>
                      <Button size="sm" variant="danger" onClick={() => deleteMenuItem(i.id)}>Delete</Button>
                   </div>
                </div>
              ))}
            </div>

            {editingItem && (
              <div className="fixed inset-0 z-[6000] bg-black/90 flex items-center justify-center p-10 backdrop-blur-xl">
                 <form onSubmit={saveMenuItem} className="bg-gray-900 p-12 rounded-[50px] border border-white/10 w-full max-w-2xl space-y-6 animate-slide-up">
                    <h3 className="text-2xl font-black italic uppercase tracking-tighter">Edit Unit Registry</h3>
                    <div className="grid grid-cols-2 gap-4">
                       <InputField label="Unit Name" value={editingItem.name} onChange={v => setEditingItem({...editingItem, name: v})} />
                       <InputField label="Bangla Name" value={editingItem.nameBn} onChange={v => setEditingItem({...editingItem, nameBn: v})} />
                       <InputField label="Price (৳)" value={String(editingItem.price)} onChange={v => setEditingItem({...editingItem, price: Number(v)})} />
                       <InputField label="Stock" value={String(editingItem.stock)} onChange={v => setEditingItem({...editingItem, stock: Number(v)})} />
                       <InputField label="Category" value={editingItem.category} onChange={v => setEditingItem({...editingItem, category: v})} className="col-span-2" />
                       <InputField label="Image URL" value={editingItem.image} onChange={v => setEditingItem({...editingItem, image: v})} className="col-span-2" />
                    </div>
                    <div className="flex gap-4">
                       <Button fullWidth variant="outline" type="button" onClick={() => setEditingItem(null)}>Cancel</Button>
                       <Button fullWidth type="submit">Save Unit</Button>
                    </div>
                 </form>
              </div>
            )}
          </div>
        )}

        {tab === 'ORDERS' && (
           <div className="space-y-12 animate-slide-up">
              <h2 className="text-4xl font-black italic uppercase">Mission Logs</h2>
              <div className="grid grid-cols-1 gap-4">
                 {orders.map(o => (
                    <div key={o.id} className="bg-gray-900 p-8 rounded-[40px] border border-white/5 flex justify-between items-center">
                       <div>
                          <p className="text-[10px] font-black text-red-600 uppercase tracking-widest mb-1">#{o.id}</p>
                          <h4 className="text-xl font-black italic uppercase">{o.customerName}</h4>
                       </div>
                       <div className="text-right">
                          <p className="text-2xl font-black italic">৳{o.total}</p>
                          <p className="text-[9px] font-black uppercase text-gray-500">{o.paymentMethod} • {o.status}</p>
                       </div>
                    </div>
                 ))}
              </div>
           </div>
        )}
      </main>
    </div>
  );
};

const InputField = ({ label, value, onChange, className }: any) => (
  <div className={`space-y-2 ${className}`}>
    <label className="text-[9px] font-black uppercase tracking-[3px] text-gray-500 ml-4">{label}</label>
    <input 
      value={value} 
      onChange={e => onChange(e.target.value)}
      className="w-full bg-white/5 p-5 rounded-[22px] outline-none border border-white/10 focus:border-red-600 transition-all font-black text-[11px] text-white" 
    />
  </div>
);

export enum UserRole {
  ADMIN = 'ADMIN',
  MANAGER = 'MANAGER',
  STAFF = 'STAFF',
  CUSTOMER = 'CUSTOMER'
}

export enum OrderStatus {
  PENDING = 'PENDING',
  PREPARING = 'PREPARING',
  READY = 'READY',
  ON_THE_WAY = 'ON_THE_WAY',
  DELIVERED = 'DELIVERED',
  CANCELLED = 'CANCELLED'
}

export type LayoutPreset = 
  | 'ELITE_DARK' 
  | 'CLASSIC_RED' 
  | 'CYBER_NEON' 
  | 'MINIMAL_WHITE' 
  | 'NATURE_GREEN' 
  | 'LUXURY_GOLD' 
  | 'RETRO_VIBE' 
  | 'BOLD_MONO' 
  | 'PASTEL_SOFT' 
  | 'HIGH_TECH';

export interface SiteCMS {
  activeLayout: LayoutPreset;
  hero: {
    title: string;
    subtitle: string;
    description: string;
    image: string;
    cta: string;
  };
  navigation: {
    brand: string;
    links: { [key: string]: string };
  };
  vault: {
    title: string;
    description: string;
  };
}

export interface MenuItem {
  id: string;
  name: string;
  nameBn: string;
  description: string;
  price: number;
  category: string;
  image: string;
  stock: number;
  // Properties used in constants.tsx to fix TS2339 errors
  rating?: number;
  ingredients?: string[];
  dietary?: string[];
  prepTime?: string;
  isPopular?: boolean;
}

export interface CartItem {
  item: MenuItem;
  qty: number;
}

export interface ClaimedVoucher {
  id: string;
  uniqueCode: string;
  status: 'ACTIVE' | 'EXPENDED';
  title: string;
  discountValue: number;
  isPercentage: boolean;
}

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  items: any[];
  total: number;
  status: OrderStatus;
  createdAt: string;
  paymentMethod: string;
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  loyaltyPoints: number;
  claimedVouchers: ClaimedVoucher[];
  tier: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { decodeAudio, decodeAudioData, encodeAudio, getAiInstance } from '../services/geminiService';
import { ChatMessage } from '../types';
import { Modality, LiveServerMessage } from '@google/genai';
import { MOCK_MENU } from '../constants';

const menuData = MOCK_MENU.map(i => `${i.nameBn}: ${i.price}tk`).join(", ");

export const ChatBot: React.FC<{ isOnline?: boolean }> = ({ isOnline = true }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([{ role: 'model', text: "কী চাই?", timestamp: new Date() }]);
  const [input, setInput] = useState('');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [currentTranscription, setCurrentTranscription] = useState('');
  const [isMicOn, setIsMicOn] = useState(false);

  const outputAudioContextRef = useRef<AudioContext | null>(null);
  // Track the session promise to avoid race conditions and stale closures
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const scrollRef = useRef<HTMLDivElement>(null);
  const micStreamRef = useRef<MediaStream | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const transcriptionRef = useRef('');

  const stopAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setIsSpeaking(false);
  };

  const initAudioOutput = async () => {
    if (!outputAudioContextRef.current) {
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    if (outputAudioContextRef.current.state === 'suspended') await outputAudioContextRef.current.resume();
  };

  const connectLive = useCallback(async () => {
    if (!isOnline || sessionPromiseRef.current) return;
    await initAudioOutput();
    const ai = getAiInstance();

    try {
      // Connect and store the promise for input streaming
      sessionPromiseRef.current = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsLiveActive(true);
            console.log("⚡ BFC Neural Link Active");
          },
          onmessage: async (msg: LiveServerMessage) => {
            // Correct extraction of audio parts from server content
            const audioData = msg.serverContent?.modelTurn?.parts?.find(p => p.inlineData)?.inlineData?.data;
            if (audioData && outputAudioContextRef.current) {
              setIsSpeaking(true);
              const ctx = outputAudioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);

              const buffer = await decodeAudioData(decodeAudio(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              };
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }

            // Handle audio transcription for model output
            if (msg.serverContent?.outputTranscription) {
              const text = msg.serverContent.outputTranscription.text;
              transcriptionRef.current += text;
              setCurrentTranscription(transcriptionRef.current);
            }

            // Update messages when turn is complete
            if (msg.serverContent?.turnComplete) {
              setMessages(prev => {
                const final = transcriptionRef.current || "...";
                return [...prev, { role: 'model', text: final, timestamp: new Date() }];
              });
              transcriptionRef.current = '';
              setCurrentTranscription('');
            }

            // Handle interruption signal
            if (msg.serverContent?.interrupted) stopAudio();
          },
          onerror: (e) => console.error("Link Error", e),
          onclose: () => {
            setIsLiveActive(false);
            sessionPromiseRef.current = null;
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          outputAudioTranscription: {},
          speechConfig: { 
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          },
          systemInstruction: `ACT: BFC Ultra-Fast. DATA: ${menuData}. RULES: Bengali only. Max 2-3 words. Extremely brief. Response must be near-instant. If order asked, say 'হচ্ছে!'. If price asked, say the number. Zero pleasantries.`
        }
      });
    } catch (e) {
      console.error("Link offline", e);
    }
  }, [isOnline]);

  const handleSend = async () => {
    const text = input.trim();
    if (!text || !sessionPromiseRef.current) return;

    stopAudio();
    setMessages(prev => [...prev, { role: 'user', text, timestamp: new Date() }]);
    setInput('');

    // Always use sessionPromise.then to ensure session is resolved before sending
    sessionPromiseRef.current.then((session) => {
      session.sendRealtimeInput({
        message: { parts: [{ text }] }
      });
    });
  };

  const toggleMic = async () => {
    if (!sessionPromiseRef.current) return;
    if (isMicOn) {
      if (micStreamRef.current) micStreamRef.current.getTracks().forEach(t => t.stop());
      setIsMicOn(false);
      return;
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;
      setIsMicOn(true);

      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      inputAudioContextRef.current = ctx;
      const source = ctx.createMediaStreamSource(stream);
      // Increased buffer size to 4096 for better compatibility
      const processor = ctx.createScriptProcessor(4096, 1, 1);

      processor.onaudioprocess = (e) => {
        const inputData = e.inputBuffer.getChannelData(0);
        const int16 = new Int16Array(inputData.length);
        for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;

        // CRITICAL: Rely solely on sessionPromise resolves to send realtime audio input
        sessionPromiseRef.current?.then((session) => {
          session.sendRealtimeInput({
            media: { 
              data: encodeAudio(new Uint8Array(int16.buffer)), 
              mimeType: 'audio/pcm;rate=16000' 
            }
          });
        });
      };

      source.connect(processor);
      processor.connect(ctx.destination);
    } catch (e) {
      setIsMicOn(false);
    }
  };

  useEffect(() => {
    if (isOpen) connectLive();
    return () => { 
      if (sessionPromiseRef.current) {
        sessionPromiseRef.current.then(s => s.close());
        sessionPromiseRef.current = null;
      }
    };
  }, [isOpen, connectLive]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight });
  }, [messages, currentTranscription]);

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-12 lg:right-12 z-[5000]">
      {isOpen ? (
        <div className="bg-white/98 dark:bg-gray-950/98 backdrop-blur-3xl w-[85vw] sm:w-[320px] h-[50vh] sm:h-[420px] rounded-[40px] shadow-[0_40px_100px_-20px_rgba(220,38,38,0.3)] flex flex-col border border-white/20 dark:border-white/10 overflow-hidden animate-slide-up ring-1 ring-black/5">
          <div className="bg-red-600 p-5 text-white flex justify-between items-center">
            <div className="flex items-center gap-3">
               <div className={`w-8 h-8 rounded-xl flex items-center justify-center ${isSpeaking ? 'bg-white text-red-600' : 'bg-white/20'}`}>
                  <i className={`fas ${isSpeaking ? 'fa-waveform animate-pulse' : 'fa-bolt-lightning'} text-xs`}></i>
               </div>
               <div>
                 <span className="text-[10px] font-black uppercase tracking-widest italic block">BFC FASTLINK</span>
                 <span className="text-[7px] font-bold opacity-70 uppercase tracking-widest">Latency: Low-Ops</span>
               </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="w-8 h-8 bg-white/10 rounded-xl flex items-center justify-center hover:bg-white/20 transition-all">
              <i className="fas fa-times text-[10px]"></i>
            </button>
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-5 space-y-4 scrollbar-hide bg-gray-50/10">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] px-4 py-2 rounded-[22px] text-[11px] font-black ${m.role === 'user' ? 'bg-red-600 text-white shadow-lg' : 'bg-white dark:bg-gray-900 text-gray-800 dark:text-gray-100 border border-gray-100 dark:border-white/5 shadow-sm'}`}>
                  {m.text}
                </div>
              </div>
            ))}
            {currentTranscription && (
              <div className="flex justify-start">
                <div className="max-w-[85%] px-4 py-2 rounded-[22px] text-[11px] font-black bg-white dark:bg-gray-900 text-red-600 border border-red-50 animate-pulse italic">
                  {currentTranscription}
                </div>
              </div>
            )}
          </div>

          <div className="p-4 bg-white dark:bg-gray-950 border-t dark:border-white/5 flex gap-3">
            <button onClick={toggleMic} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isMicOn ? 'bg-red-600 text-white animate-pulse' : 'bg-gray-100 dark:bg-gray-900 text-gray-400 hover:text-gray-600'}`}>
              <i className={`fas ${isMicOn ? 'fa-microphone' : 'fa-microphone-slash'} text-sm`}></i>
            </button>
            <div className="flex-1 flex items-center bg-gray-100 dark:bg-gray-900 rounded-2xl p-1 shadow-inner">
              <input 
                type="text" value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSend()}
                placeholder="অর্ডার দিন..."
                className="flex-1 bg-transparent border-none px-4 outline-none text-[11px] font-black dark:text-white placeholder:opacity-50"
              />
              <button onClick={handleSend} className="w-10 h-10 bg-red-600 text-white rounded-xl flex items-center justify-center shadow-lg active:scale-90 transition-all">
                <i className="fas fa-paper-plane text-[10px]"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button onClick={() => setIsOpen(true)} className="w-14 h-14 sm:w-16 sm:h-16 bg-red-600 text-white rounded-[24px] shadow-[0_20px_50px_rgba(220,38,38,0.4)] flex flex-col items-center justify-center hover:scale-110 active:scale-90 transition-all group border-2 border-white/20 overflow-hidden">
           <i className="fas fa-bolt-lightning text-xl sm:text-2xl group-hover:animate-bounce"></i>
           {isSpeaking && <span className="absolute top-2 right-2 flex h-2 w-2"><span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span><span className="relative inline-flex rounded-full h-2 w-2 bg-white"></span></span>}
        </button>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem, SiteCMS, LayoutPreset, ClaimedVoucher } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  id: number;
  message: string;
  description?: string;
  type: 'success' | 'error' | 'warning' | 'info';
}

const DEFAULT_CMS: SiteCMS = {
  activeLayout: 'ELITE_DARK',
  hero: {
    title: "CRAFTING LEGENDS",
    subtitle: "ESTABLISHED 1999",
    description: "The definitive taste of Bangladesh, delivered through an elite neural logistics network.",
    image: "https://images.unsplash.com/photo-1633945274405-b6c8069047b0?q=80&w=2000",
    cta: "EXPLORE REGISTRY"
  },
  navigation: {
    brand: "BFC ELITE",
    links: { home: "HOME", menu: "MENU", vault: "VAULT", profile: "PROFILE" }
  },
  vault: {
    title: "Vault",
    description: "Neutral Credit Protocol Active"
  }
};

const App: React.FC = () => {
  const [cms, setCms] = useState<SiteCMS>(() => {
    const saved = localStorage.getItem('bfc_cms');
    return saved ? JSON.parse(saved) : DEFAULT_CMS;
  });

  const [menuItems, setMenuItems] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('bfc_menu');
    return saved ? JSON.parse(saved) : MOCK_MENU;
  });

  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT' | 'PROFILE'>('HOME');
  const [paymentStep, setPaymentStep] = useState<'IDLE' | 'SELECT' | 'PROCESSING' | 'SUCCESS' | 'ERROR'>('IDLE');

  const [toasts, setToasts] = useState<Toast[]>([]);
  const [activeVoucher, setActiveVoucher] = useState<ClaimedVoucher | null>(null);
  const [selectedPayment, setSelectedPayment] = useState('');

  // Login fields
  const [loginId, setLoginId] = useState('');
  const [loginKey, setLoginKey] = useState('');
  const [loginError, setLoginError] = useState('');

  const showToast = useCallback((message: string, type: Toast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, description }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
  }, []);

  useEffect(() => {
    localStorage.setItem('bfc_cms', JSON.stringify(cms));
    localStorage.setItem('bfc_menu', JSON.stringify(menuItems));
  }, [cms, menuItems]);

  const subtotal = cart.reduce((a, b) => a + (b.item.price * b.qty), 0);
  const delivery = cart.length > 0 ? 60 : 0;
  const discount = activeVoucher ? (activeVoucher.isPercentage ? (subtotal * activeVoucher.discountValue / 100) : activeVoucher.discountValue) : 0;
  const total = Math.max(0, subtotal + delivery - discount);

  const getThemeClasses = () => {
    switch (cms.activeLayout) {
      case 'CLASSIC_RED': return 'bg-red-50 text-gray-900 font-serif';
      case 'CYBER_NEON': return 'bg-black text-cyan-400 font-mono uppercase';
      case 'NATURE_GREEN': return 'bg-emerald-50 text-emerald-950';
      case 'MINIMAL_WHITE': return 'bg-white text-gray-400 font-light';
      case 'LUXURY_GOLD': return 'bg-stone-900 text-amber-500';
      default: return 'bg-[#F8FAFC] text-gray-950 font-sans';
    }
  };

  const handleAuth = () => {
    setLoginError('');
    if (!loginId || !loginKey) {
      setLoginError('Please enter both Neural ID and Access Key.');
      showToast('Validation Error', 'error', 'Missing login credentials.');
      return;
    }

    // Mock auth: "admin" for admin, anything else for customer
    const isAdmin = loginId.toLowerCase().includes('admin');
    const user: User = {
      id: isAdmin ? 'U-ADMIN' : 'U-' + Math.random().toString(36).slice(2, 7),
      name: isAdmin ? 'Elite Admin' : 'Valued Customer',
      email: loginId,
      role: isAdmin ? UserRole.ADMIN : UserRole.CUSTOMER,
      loyaltyPoints: 1250,
      tier: 'PLATINUM',
      claimedVouchers: []
    };

    setCurrentUser(user);
    if (isAdmin) setView('ADMIN');
    else setView('HOME');
    showToast('Authorization Granted', 'success', `Welcome back, ${user.name}.`);
  };

  const processPayment = async () => {
    if (!selectedPayment) {
      showToast('Selection Required', 'warning', 'Please pick a payment gateway to proceed.');
      return;
    }

    setPaymentStep('PROCESSING');

    try {
      // Simulate network delay
      await new Promise(r => setTimeout(r, 2500));

      // Simulate a random 20% failure rate for "Network Issues"
      if (Math.random() < 0.2) {
        throw new Error('NETWORK_STABILITY_FAILURE');
      }

      setPaymentStep('SUCCESS');
      const newOrder: Order = {
        id: 'ORD-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
        customerId: currentUser?.id || 'GUEST',
        customerName: currentUser?.name || 'Guest',
        items: cart,
        total,
        status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(),
        paymentMethod: selectedPayment
      };
      setAllOrders(p => [newOrder, ...p]);
      setCart([]);
      showToast('Transaction Verified', 'success', 'Your order mission has been deployed.');
      setTimeout(() => { setPaymentStep('IDLE'); setView('HOME'); }, 3000);
    } catch (err: any) {
      setPaymentStep('ERROR');
      const guidance = err.message === 'NETWORK_STABILITY_FAILURE' 
        ? 'Encryption handshake failed. Please check your internet connection and try again.'
        : 'Payment provider rejected the link. Please verify your balance or try a different method.';
      showToast('Payment Failure', 'error', guidance);
    }
  };

  if (view === 'ADMIN') {
    return (
      <AdminPanel 
        cms={cms} setCms={setCms}
        menuItems={menuItems} setMenuItems={setMenuItems}
        orders={allOrders} setOrders={setAllOrders}
        onLogout={() => { setView('HOME'); setCurrentUser(null); }}
      />
    );
