        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto glass-card px-6 py-4 rounded-[24px] border border-white/50 elite-shadow animate-slide-up">
            <div className="flex items-start gap-4">
               <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${
                 t.type === 'error' ? 'bg-red-100 text-red-600' : 
                 t.type === 'warning' ? 'bg-amber-100 text-amber-600' : 
                 'bg-emerald-100 text-emerald-600'
               }`}>
                  <i className={`fas ${t.type === 'error' ? 'fa-triangle-exclamation' : t.type === 'warning' ? 'fa-bolt' : 'fa-check'} text-xs`}></i>
               </div>
               <div>
                  <h4 className="text-[10px] font-black uppercase tracking-widest leading-none mb-1">{t.message}</h4>
                  {t.description && <p className="text-[9px] font-bold text-gray-500 leading-tight">{t.description}</p>}
               </div>
               <button onClick={() => setToasts(prev => prev.filter(x => x.id !== t.id))} className="text-gray-300 hover:text-gray-600 ml-auto"><i className="fas fa-times text-[10px]"></i></button>
            </div>
          </div>
        ))}
      </div>

      <nav className="fixed top-0 inset-x-0 z-[5000] px-6 py-4 flex justify-between items-center bg-white/80 backdrop-blur-2xl shadow-xl border-b">
        <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-8 h-8 bg-red-600 rounded-lg flex items-center justify-center text-white font-black italic group-hover:rotate-6 transition-transform">B</div>
          <h1 className="text-xl font-black italic tracking-tighter uppercase">{cms.navigation.brand}</h1>
