          <button onClick={() => setView('VAULT')} className={`text-[10px] font-black uppercase tracking-widest transition-colors ${view === 'VAULT' ? 'text-red-600' : 'text-gray-400 hover:text-red-600'}`}>Vault</button>
          <button onClick={() => setView('CART')} className="relative w-10 h-10 bg-gray-100 dark:bg-gray-800 rounded-xl flex items-center justify-center hover:scale-105 transition-all">
            <i className="fas fa-shopping-basket"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[8px] w-4 h-4 rounded-full flex items-center justify-center font-black animate-pulse ring-2 ring-white">{cart.length}</span>}
