            <h2 className="text-5xl font-black italic uppercase text-center">Manifest</h2>
            {(paymentStep === 'IDLE' || paymentStep === 'ERROR') && (
              <div className="bg-white dark:bg-gray-900 p-10 rounded-[50px] shadow-2xl border dark:border-white/5 space-y-8">
                {cart.length === 0 ? (
                  <div className="text-center py-20 space-y-6">
                    <i className="fas fa-ghost text-5xl text-gray-200"></i>
                    <p className="text-[10px] font-black uppercase tracking-[6px] text-gray-400">Payload empty. No active mission.</p>
                    <Button variant="outline" onClick={() => setView('MENU')}>EXPLORE REGISTRY</Button>
                  </div>
                ) : (
                  <>
                    <div className="space-y-6">
