import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  id: number;
  message: string;
  description?: string;
  type: 'success' | 'error' | 'warning' | 'info';
}

const DEFAULT_CMS: SiteCMS = {
  activeLayout: 'ELITE_DARK',
  hero: {
    title: "CRAFTING LEGENDS",
    subtitle: "ESTABLISHED 1999",
    description: "The definitive taste of Bangladesh, delivered through an elite neural logistics network.",
    image: "https://images.unsplash.com/photo-1633945274405-b6c8069047b0?q=80&w=2000",
    cta: "EXPLORE REGISTRY"
  },
  navigation: {
    brand: "BFC ELITE",
    links: { home: "HOME", menu: "MENU", vault: "VAULT", profile: "PROFILE" }
  },
  vault: {
    title: "NEURAL VAULT",
    description: "Loyalty protocol active. Secure credits stored in the decentralized BFC Ledger."
  }
};

const App: React.FC = () => {
  const [cms, setCms] = useState<SiteCMS>(() => {
    const saved = localStorage.getItem('bfc_cms');
    return saved ? JSON.parse(saved) : DEFAULT_CMS;
  });

  const [menuItems, setMenuItems] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('bfc_menu');
    return saved ? JSON.parse(saved) : MOCK_MENU;
  });

  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT'>('HOME');
  const [paymentStep, setPaymentStep] = useState<'IDLE' | 'SELECT' | 'PROCESSING' | 'SUCCESS' | 'ERROR'>('IDLE');

  const [toasts, setToasts] = useState<Toast[]>([]);
  const [selectedPayment, setSelectedPayment] = useState('');

  const [loginId, setLoginId] = useState('');
  const [loginKey, setLoginKey] = useState('');
  const [loginError, setLoginError] = useState('');

  const showToast = useCallback((message: string, type: Toast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, description }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
  }, []);

  useEffect(() => {
    localStorage.setItem('bfc_cms', JSON.stringify(cms));
    localStorage.setItem('bfc_menu', JSON.stringify(menuItems));
  }, [cms, menuItems]);

  const subtotal = cart.reduce((a, b) => a + (b.item.price * b.qty), 0);
  const delivery = cart.length > 0 ? 60 : 0;
  const total = Math.max(0, subtotal + delivery);

  const handleAuth = () => {
    setLoginError('');
    if (!loginId) {
      setLoginError('Authorization ID required.');
      return;
    }
    const isAdmin = loginId.toLowerCase().includes('admin');
    const user: User = {
      id: isAdmin ? 'U-ADMIN' : 'U-GUEST',
      name: isAdmin ? 'Elite Commander' : 'Honored Guest',
      email: loginId,
      role: isAdmin ? UserRole.ADMIN : UserRole.CUSTOMER,
      loyaltyPoints: 1500,
      tier: 'PLATINUM',
      claimedVouchers: []
    };
    setCurrentUser(user);
    isAdmin ? setView('ADMIN') : setView('HOME');
    showToast('Secure Link Established', 'success', `Authorized as ${user.name}`);
  };

  const processPayment = async () => {
    if (!selectedPayment) return showToast('Selection Required', 'warning', 'Please select a gateway.');
    setPaymentStep('PROCESSING');
    await new Promise(r => setTimeout(r, 2000));
    setPaymentStep('SUCCESS');
    const newOrder: Order = {
      id: 'ORD-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
      customerId: currentUser?.id || 'GUEST',
      customerName: currentUser?.name || 'Guest',
      items: cart,
      total,
      status: OrderStatus.PENDING,
      createdAt: new Date().toISOString(),
      paymentMethod: selectedPayment
    };
    setAllOrders(p => [newOrder, ...p]);
    setCart([]);
    setTimeout(() => { setPaymentStep('IDLE'); setView('HOME'); }, 3000);
  };

  if (view === 'ADMIN' && currentUser?.role === UserRole.ADMIN) {
    return (
      <AdminPanel 
        cms={cms} setCms={setCms}
        menuItems={menuItems} setMenuItems={setMenuItems}
        orders={allOrders} setOrders={setAllOrders}
        onLogout={() => { setView('HOME'); setCurrentUser(null); }}
      />
    );
  }

  return (
    <div className={`themed-root min-h-screen theme-${cms.activeLayout} pb-20 lg:pb-0`}>
      {/* Toast System */}
      <div className="fixed top-24 right-6 z-[9999] space-y-4 pointer-events-none max-w-[calc(100vw-3rem)]">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto themed-card p-adaptive rounded-[24px] animate-slide-up flex gap-4 items-start ring-1 ring-white/10">
            <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 themed-primary`}>
              <i className={`fas ${t.type === 'error' ? 'fa-bolt' : 'fa-check'} text-[10px]`}></i>
            </div>
            <div>
              <h4 className="text-[10px] font-black uppercase tracking-widest">{t.message}</h4>
              {t.description && <p className="text-[9px] opacity-70 mt-1">{t.description}</p>}
            </div>
          </div>
        ))}
      </div>

      {/* Navigation */}
      <nav className="fixed top-0 inset-x-0 z-[5000] px-4 lg:px-10 py-4 flex justify-between items-center glass-effect border-b themed-border">
        <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-8 h-8 themed-primary rounded-lg flex items-center justify-center font-black">B</div>
          <h1 className="text-lg lg:text-xl font-black italic tracking-tighter uppercase hidden sm:block">{cms.navigation.brand}</h1>
        </div>
        <div className="flex gap-2 sm:gap-6 items-center">
          <button onClick={() => setView('MENU')} className="text-[9px] font-black uppercase tracking-[3px] opacity-50 hover:opacity-100 transition-opacity">Menu</button>
          <button onClick={() => setView('VAULT')} className="text-[9px] font-black uppercase tracking-[3px] opacity-50 hover:opacity-100 transition-opacity">Vault</button>
          <button onClick={() => setView('CART')} className="relative w-10 h-10 bg-white/5 themed-border border rounded-xl flex items-center justify-center transition-transform active:scale-90">
            <i className="fas fa-shopping-basket text-sm"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 themed-primary text-white text-[8px] w-4 h-4 rounded-full flex items-center justify-center font-black">{cart.length}</span>}
          </button>
          <button onClick={() => setView('LOGIN')} className="w-10 h-10 themed-primary rounded-xl flex items-center justify-center text-sm shadow-xl"><i className="fas fa-fingerprint"></i></button>
        </div>
      </nav>

      <main className="pt-20">
        {view === 'HOME' && (
          <div className="animate-fade-in">
            <section className="relative h-[70vh] lg:h-[85vh] flex items-center px-6 lg:px-20 overflow-hidden">
              <img src={cms.hero.image} className="absolute inset-0 w-full h-full object-cover opacity-30 grayscale-[0.5]" alt="BFC Hero" />
              <div className="absolute inset-0 bg-gradient-to-r from-[var(--bg)] to-transparent"></div>
              <div className="relative z-10 max-w-4xl space-y-8">
                <p className="themed-text-primary font-black uppercase tracking-[10px] text-[10px] lg:text-xs animate-slide-up">{cms.hero.subtitle}</p>
                <h2 className="text-4xl lg:text-8xl font-black leading-[1] tracking-tighter italic uppercase animate-slide-up hero-title">{cms.hero.title}</h2>
                <p className="text-sm lg:text-xl opacity-70 max-w-xl font-medium leading-relaxed animate-slide-up" style={{animationDelay: '0.1s'}}>{cms.hero.description}</p>
                <div className="pt-4 animate-slide-up" style={{animationDelay: '0.2s'}}>
                  <Button size="lg" className="rounded-2xl" onClick={() => setView('MENU')}>{cms.hero.cta}</Button>
                </div>
              </div>
            </section>
          </div>
        )}

        {view === 'MENU' && (
          <div className="p-6 lg:p-20 max-w-7xl mx-auto space-y-12 animate-slide-up">
            <div className="text-center space-y-4">
              <h2 className="text-4xl lg:text-6xl font-black italic uppercase tracking-tighter">Neural Registry</h2>
              <div className="h-1 w-20 themed-primary mx-auto rounded-full"></div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 lg:gap-12">
              {menuItems.map(item => (
                <div key={item.id} className="themed-card p-6 lg:p-8 rounded-[40px] group hover:-translate-y-2 transition-all">
                  <div className="h-56 lg:h-72 rounded-[30px] overflow-hidden mb-8 relative">
                    <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt={item.name} />
                    <div className="absolute top-4 right-4 themed-primary px-4 py-1 rounded-full text-[10px] font-black italic">৳{item.price}</div>
                  </div>
                  <h4 className="text-2xl font-black italic uppercase mb-1">{item.name}</h4>
                  <p className="text-[10px] font-black themed-text-primary uppercase mb-6 tracking-widest">{item.nameBn}</p>
                  <div className="flex justify-between items-center">
                    <span className="text-xl font-black">৳{item.price}</span>
                    <Button onClick={() => {
                      setCart(prev => {
                        const ex = prev.find(c => c.item.id === item.id);
                        if (ex) return prev.map(c => c.item.id === item.id ? {...c, qty: c.qty+1} : c);
                        return [...prev, {item, qty:1}];
                      });
                      showToast('Manifest Updated', 'success', `${item.name} secured.`);
                    }}>+ ADD</Button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {view === 'VAULT' && (
          <div className="p-6 lg:p-20 max-w-4xl mx-auto space-y-12 animate-slide-up">
            <div className="text-center space-y-4">
              <h2 className="text-4xl lg:text-6xl font-black italic uppercase tracking-tighter">{cms.vault.title}</h2>
              <p className="text-xs lg:text-sm opacity-60 max-w-xl mx-auto uppercase tracking-widest leading-loose">{cms.vault.description}</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
               <div className="themed-card p-10 rounded-[50px] space-y-6 text-center">
                  <p className="text-[10px] font-black uppercase tracking-[5px] opacity-40">Available Balance</p>
                  <h3 className="text-6xl font-black italic">৳{currentUser?.loyaltyPoints || 0}</h3>
                  <Button fullWidth variant="outline" className="rounded-3xl">RECHARGE SIGNAL</Button>
               </div>
               <div className="themed-card p-10 rounded-[50px] space-y-8">
                  <h4 className="text-[10px] font-black uppercase tracking-[5px] themed-text-primary">Recent Pulses</h4>
                  {[1,2,3].map(i => (
                    <div key={i} className="flex justify-between items-center border-b themed-border pb-4">
                      <div>
                        <p className="text-xs font-black uppercase italic">Neural Order #{1030 + i}</p>
                        <p className="text-[8px] opacity-40">24 OCT 2023</p>
                      </div>
                      <p className="text-xs font-black text-emerald-500">+150 pts</p>
                    </div>
                  ))}
               </div>
            </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="max-w-xl mx-auto p-6 lg:p-20 space-y-12 animate-slide-up">
            <h2 className="text-4xl lg:text-5xl font-black italic uppercase text-center">Checkout Flow</h2>

            {paymentStep === 'IDLE' && (
              <div className="themed-card p-8 lg:p-12 rounded-[50px] space-y-8">
                {cart.length === 0 ? (
                  <div className="text-center py-20 opacity-40 uppercase font-black tracking-widest text-[10px]">No items in manifest.</div>
                ) : (
                  <>
                    <div className="space-y-6">
                      {cart.map((c, i) => (
                        <div key={i} className="flex justify-between items-center border-b themed-border pb-4">
                          <span className="font-black italic uppercase text-sm">{c.item.name} <span className="opacity-40 ml-2">x {c.qty}</span></span>
                          <span className="font-black">৳{c.item.price * c.qty}</span>
                        </div>
                      ))}
                    </div>
                    <div className="text-4xl font-black italic flex justify-between pt-6 border-t themed-border">
                      <span>TOTAL</span>
                      <span className="themed-text-primary">৳{total}</span>
                    </div>
                    <Button fullWidth size="lg" className="rounded-[30px]" onClick={() => setPaymentStep('SELECT')}>PROCEED TO PAY</Button>
                  </>
                )}
              </div>
            )}

            {paymentStep === 'SELECT' && (
              <div className="themed-card p-8 lg:p-12 rounded-[50px] space-y-8">
                <h3 className="text-[10px] font-black uppercase tracking-widest text-center">Select Gateway</h3>
                <div className="grid grid-cols-2 gap-4">
                  {['BKASH', 'NAGAD', 'VISA', 'COD'].map(m => (
                    <button key={m} onClick={() => setSelectedPayment(m)} className={`p-8 rounded-3xl border-2 transition-all font-black text-[10px] tracking-widest ${selectedPayment === m ? 'themed-primary border-transparent' : 'themed-border opacity-50'}`}>{m}</button>
                  ))}
                </div>
                <div className="flex gap-4">
                  <Button variant="outline" fullWidth onClick={() => setPaymentStep('IDLE')} className="rounded-2xl">BACK</Button>
                  <Button fullWidth onClick={processPayment} className="rounded-2xl">CONFIRM</Button>
                </div>
              </div>
            )}

            {paymentStep === 'PROCESSING' && (
              <div className="flex flex-col items-center justify-center py-24 space-y-6">
                <div className="w-16 h-16 border-4 themed-text-primary border-t-transparent rounded-full animate-spin"></div>
                <p className="font-black uppercase tracking-[8px] opacity-40 text-[10px]">Encrypting Connection...</p>
              </div>
            )}

            {paymentStep === 'SUCCESS' && (
              <div className="text-center py-24 space-y-8 animate-slide-up">
                <i className="fas fa-check-circle text-8xl themed-text-primary"></i>
                <h3 className="text-4xl font-black italic uppercase">TRANSACTION SECURED</h3>
                <Button size="lg" className="rounded-3xl" onClick={() => setView('HOME')}>RETURN TO HUB</Button>
              </div>
            )}
          </div>
        )}

        {view === 'LOGIN' && (
          <div className="max-w-md mx-auto mt-10 lg:mt-20 p-8 lg:p-12 themed-card rounded-[60px] space-y-12 animate-slide-up">
            <div className="text-center space-y-3">
              <h2 className="text-3xl lg:text-4xl font-black italic uppercase">Access Port</h2>
              <p className="text-[10px] font-black uppercase tracking-[8px] opacity-40 leading-none">Enter Credentials</p>
            </div>
            <div className="space-y-6">
              <div className="space-y-2">
                 <label className="text-[9px] font-black uppercase tracking-widest opacity-40 ml-4">Neural Identity</label>
                 <input placeholder="AGENT_NAME" value={loginId} onChange={e => setLoginId(e.target.value)} className="w-full bg-white/5 themed-border border p-6 rounded-3xl outline-none font-black text-xs uppercase" />
              </div>
              <div className="space-y-2">
                 <label className="text-[9px] font-black uppercase tracking-widest opacity-40 ml-4">Neural Key</label>
                 <input type="password" placeholder="••••••••" value={loginKey} onChange={e => setLoginKey(e.target.value)} className="w-full bg-white/5 themed-border border p-6 rounded-3xl outline-none font-black text-xs uppercase" />
              </div>
              {loginError && <p className="text-[10px] text-red-600 font-black uppercase text-center">{loginError}</p>}
              <Button fullWidth size="lg" className="rounded-3xl py-8" onClick={handleAuth}>AUTHORIZE</Button>
              <div className="flex justify-between items-center px-4">
                 <button className="text-[8px] font-black uppercase tracking-widest opacity-40">Lost Link?</button>
                 <button className="text-[8px] font-black uppercase tracking-widest themed-text-primary">Create Identity</button>
              </div>
            </div>
          </div>
        )}
      </main>

      <ChatBot isOnline={true} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Order, MenuItem, SiteCMS, LayoutPreset } from './types';
import { Button } from './components/Button';

interface AdminPanelProps {
  cms: SiteCMS;
  setCms: (cms: SiteCMS) => void;
  menuItems: MenuItem[];
  setMenuItems: (items: MenuItem[]) => void;
  orders: Order[];
  setOrders: (orders: Order[]) => void;
  onLogout: () => void;
}

const LAYOUTS: { id: LayoutPreset; name: string; color: string; desc: string }[] = [
  { id: 'ELITE_DARK', name: 'Elite Dark', color: 'bg-gray-950', desc: 'Premium deep contrast aesthetics.' },
  { id: 'CLASSIC_RED', name: 'Classic BFC', color: 'bg-red-600', desc: 'Original BFC brand identity.' },
  { id: 'CYBER_NEON', name: 'Cyberpunk', color: 'bg-cyan-500', desc: 'Neon glows and monospaced tech.' },
  { id: 'MINIMAL_WHITE', name: 'Clean Minimal', color: 'bg-white border', desc: 'Zero noise, maximum focus.' },
  { id: 'NATURE_GREEN', name: 'Nature Organic', color: 'bg-emerald-600', desc: 'Earth-friendly organic tones.' },
  { id: 'LUXURY_GOLD', name: 'Luxury Gold', color: 'bg-amber-600', desc: 'High-end serif elegance.' },
  { id: 'RETRO_VIBE', name: '90s Retro', color: 'bg-pink-500', desc: 'Pastel aesthetics and bold edges.' },
  { id: 'BOLD_MONO', name: 'Bold Mono', color: 'bg-black', desc: 'Aggressive monochrome energy.' },
  { id: 'PASTEL_SOFT', name: 'Pastel Soft', color: 'bg-purple-300', desc: 'Gentle, soft-touch interface.' },
  { id: 'HIGH_TECH', name: 'Blue High-Tech', color: 'bg-blue-700', desc: 'Scientific data-driven visuals.' },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  cms, setCms, menuItems, setMenuItems, orders, onLogout 
}) => {
  const [tab, setTab] = useState<'LAYOUT' | 'CMS' | 'MENU' | 'ORDERS'>('LAYOUT');
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [isMobileSidebarOpen, setMobileSidebarOpen] = useState(false);

  const updateCms = (path: string, value: string) => {
    const keys = path.split('.');
    const newCms = { ...cms };
    let curr: any = newCms;
    for (let i = 0; i < keys.length - 1; i++) curr = curr[keys[i]];
    curr[keys[keys.length - 1]] = value;
    setCms(newCms);
  };

  const deleteMenuItem = (id: string) => {
    if (window.confirm("Purge unit from registry?")) {
      setMenuItems(menuItems.filter(i => i.id !== id));
    }
  };

  const saveMenuItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingItem) return;
    if (menuItems.find(i => i.id === editingItem.id)) {
      setMenuItems(menuItems.map(i => i.id === editingItem.id ? editingItem : i));
    } else {
      setMenuItems([...menuItems, editingItem]);
    }
    setEditingItem(null);
  };

  return (
    <div className={`themed-root flex flex-col lg:flex-row h-screen theme-${cms.activeLayout} overflow-hidden`}>
      {/* Mobile Top Header */}
      <header className="lg:hidden flex justify-between items-center p-6 glass-effect border-b themed-border z-[6000]">
        <h1 className="text-xl font-black italic tracking-tighter text-[var(--primary)]">HQ COMMAND</h1>
        <button onClick={() => setMobileSidebarOpen(!isMobileSidebarOpen)} className="w-10 h-10 themed-card rounded-xl">
          <i className={`fas ${isMobileSidebarOpen ? 'fa-times' : 'fa-bars'}`}></i>
        </button>
      </header>

      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[5000] w-full lg:w-80 themed-card border-r themed-border p-8 flex flex-col gap-8 transition-transform duration-500 ${isMobileSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <h1 className="text-2xl font-black italic tracking-tighter themed-text-primary hidden lg:block">BFC COMMANDER</h1>
        <nav className="flex flex-col gap-2 flex-1 pt-10 lg:pt-0">
          {[
            { id: 'LAYOUT', icon: 'fa-layer-group', label: 'Layout Store' },
            { id: 'CMS', icon: 'fa-pen-to-square', label: 'Terminal' },
            { id: 'MENU', icon: 'fa-utensils', label: 'Registry' },
            { id: 'ORDERS', icon: 'fa-satellite-dish', label: 'Pulse Logs' }
          ].map((t: any) => (
            <button key={t.id} onClick={() => { setTab(t.id); setMobileSidebarOpen(false); }} className={`p-6 rounded-3xl text-[10px] font-black uppercase tracking-[4px] text-left transition-all flex items-center gap-4 ${tab === t.id ? 'themed-primary shadow-xl' : 'opacity-40 hover:opacity-100 hover:bg-white/5'}`}>
              <i className={`fas ${t.icon} w-5`}></i>
              {t.label}
            </button>
          ))}
        </nav>
        <button onClick={onLogout} className="p-6 rounded-3xl text-[9px] font-black uppercase tracking-[5px] border themed-border themed-text-primary mt-auto">De-Authorize</button>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-6 lg:p-16 custom-scrollbar">
        {tab === 'LAYOUT' && (
          <div className="space-y-12 animate-slide-up">
            <div className="space-y-2">
              <h2 className="text-4xl lg:text-6xl font-black italic uppercase tracking-tighter">Layout Store</h2>
              <p className="text-[10px] font-black uppercase tracking-[8px] opacity-40">Change Visual Identity</p>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6">
              {LAYOUTS.map(l => (
                <button key={l.id} onClick={() => setCms({ ...cms, activeLayout: l.id })} className={`p-8 rounded-[40px] border-4 transition-all flex flex-col items-center gap-6 text-center group ${cms.activeLayout === l.id ? 'themed-primary border-transparent scale-105' : 'themed-card themed-border'}`}>
                   <div className={`w-20 h-20 rounded-3xl ${l.color} shadow-2xl ring-4 ring-white/10 group-hover:scale-110 transition-transform`}></div>
                   <div>
                     <span className="text-[10px] font-black uppercase tracking-widest block mb-1">{l.name}</span>
                     <span className="text-[8px] opacity-50 font-bold uppercase block leading-tight">{l.desc}</span>
                   </div>
                </button>
              ))}
            </div>
          </div>
        )}

        {tab === 'CMS' && (
          <div className="space-y-12 animate-slide-up">
            <h2 className="text-4xl lg:text-6xl font-black italic uppercase tracking-tighter">Neural Editor</h2>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
              <section className="themed-card p-10 rounded-[50px] space-y-6">
                 <h3 className="text-xs font-black themed-text-primary uppercase tracking-[4px] border-b themed-border pb-4">Hero Section</h3>
                 <div className="space-y-4">
                    <InputField label="Hero Title" value={cms.hero.title} onChange={v => updateCms('hero.title', v)} />
                    <InputField label="Hero Subtitle" value={cms.hero.subtitle} onChange={v => updateCms('hero.subtitle', v)} />
                    <InputField label="Image Link" value={cms.hero.image} onChange={v => updateCms('hero.image', v)} />
                 </div>
              </section>
              <section className="themed-card p-10 rounded-[50px] space-y-6">
