                   </div>
                   <div className="flex gap-2 w-full">
                      <Button fullWidth size="sm" variant="outline" onClick={() => setEditingItem(i)}>Edit</Button>
                      <Button fullWidth size="sm" variant="danger" onClick={() => deleteMenuItem(i.id)}>Delete</Button>
