                  <h4 className="text-2xl lg:text-3xl font-black italic uppercase mb-1 leading-none">{item.name}</h4>
                  <p className="text-[11px] font-black themed-text-primary uppercase mb-8 tracking-widest leading-none">{item.nameBn}</p>
                  <p className="text-[13px] opacity-60 font-medium mb-10 line-clamp-2 leading-relaxed">{item.description}</p>
                  <div className="flex justify-between items-center">
                    <span className="text-2xl font-black italic">৳{item.price}</span>
                    <Button className="rounded-2xl" onClick={() => {
                      setCart(prev => {
                        const ex = prev.find(c => c.item.id === item.id);
                        if (ex) return prev.map(c => c.item.id === item.id ? {...c, qty: c.qty+1} : c);
                        return [...prev, {item, qty:1}];
                      });
                      showToast('Registry Updated', 'success', `${item.name} added to payload.`);
                    }}>+ ADD UNIT</Button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* VAULT (RIBOT WALLET) VIEW */}
        {view === 'VAULT' && (
          <div className="p-6 lg:p-20 max-w-5xl mx-auto space-y-20 animate-elite-up pb-40">
            <div className="text-center space-y-6">
              <h2 className="text-5xl lg:text-8xl font-black italic uppercase tracking-tighter">{cms.vault.title}</h2>
              <p className="text-xs lg:text-lg opacity-60 max-w-2xl mx-auto uppercase tracking-widest leading-loose font-medium">{cms.vault.description}</p>
