                    </div>
                    <div className="w-16 h-16 themed-primary rounded-3xl flex items-center justify-center text-3xl shadow-2xl">
                      <i className="fas fa-shield-halved"></i>
                    </div>
                  </div>
                  <div className="flex flex-col sm:flex-row gap-6">
                    <Button fullWidth size="lg" className="rounded-[28px] py-10 text-sm">RECHARGE VAULT</Button>
                    <Button fullWidth variant="outline" size="lg" className="rounded-[28px] py-10 text-sm">TRANSFER LINK</Button>
