                    <button className="text-[10px] font-black uppercase opacity-40 hover:opacity-100 transition-opacity">View All</button>
                  </div>
                  <div className="space-y-6">
                    {[1, 2, 3, 4, 5].map(i => (
                      <div key={i} className="flex justify-between items-center border-b themed-border pb-6 last:border-0">
