                          <div className="w-10 h-10 rounded-xl bg-white/5 flex items-center justify-center text-xs opacity-50"><i className="fas fa-arrow-down-left"></i></div>
                          <div>
                            <p className="text-sm font-black uppercase italic leading-none mb-1">Feast Order #{1030 + i}</p>
                            <p className="text-[9px] opacity-40 font-bold uppercase tracking-widest">24 OCT 2023</p>
                          </div>
                        </div>
                        <p className="text-xs font-black text-emerald-500 leading-none">+150 PTS</p>
                      </div>
                    ))}
                  </div>
               </div>
            </div>
          </div>
        )}

        {/* CART & PAYMENT VIEW */}
        {view === 'CART' && (
          <div className="max-w-4xl mx-auto p-6 lg:p-20 space-y-20 animate-elite-up pb-40">
            <h2 className="text-5xl lg:text-8xl font-black italic uppercase text-center tracking-tighter">The Manifest</h2>

            <div className="grid grid-cols-1 lg:grid-cols-5 gap-10">
              <div className="lg:col-span-3 space-y-8">
                <div className="themed-card p-10 rounded-[56px] space-y-10">
                  {cart.length === 0 ? (
                    <div className="text-center py-20 opacity-30 uppercase font-black tracking-[12px] text-[11px]">Payload empty.</div>
