export function encodeAudio(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export function decodeAudio(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { decodeAudio, decodeAudioData, encodeAudio, getAiInstance, bfcFastText } from '../services/geminiService';
import { ChatMessage, User } from '../types';
import { Modality, LiveServerMessage } from '@google/genai';
import { MOCK_MENU } from '../constants';

const menuContext = MOCK_MENU.map(i => 
  `- ${i.name}: ${i.price}tk. ${i.category}. ${i.isPopular ? 'Popular' : ''}`
).join("\n");

interface ChatBotProps {
  isOnline?: boolean;
  currentUser?: User | null;
}

export const ChatBot: React.FC<ChatBotProps> = ({ isOnline = true, currentUser }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([{ role: 'model', text: "স্বাগতম! বিএফসি এলিট সার্ভিস থেকে আমি আপনাকে কীভাবে সাহায্য করতে পারি?", timestamp: new Date() }]);
  const [input, setInput] = useState('');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [currentTranscription, setCurrentTranscription] = useState('');
  const [isMicOn, setIsMicOn] = useState(false);

  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const scrollRef = useRef<HTMLDivElement>(null);
  const micStreamRef = useRef<MediaStream | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const transcriptionRef = useRef('');

  const stopAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setIsSpeaking(false);
  };

  const initAudioOutput = async () => {
    if (!outputAudioContextRef.current) {
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    if (outputAudioContextRef.current.state === 'suspended') await outputAudioContextRef.current.resume();
  };

  const connectLive = useCallback(async () => {
    if (!isOnline || sessionPromiseRef.current) return;
    await initAudioOutput();
    const ai = getAiInstance();

    try {
      sessionPromiseRef.current = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsLiveActive(true);
            console.log("⚡ BFC Neural Link Synchronized");
          },
          onmessage: async (msg: LiveServerMessage) => {
            const audioData = msg.serverContent?.modelTurn?.parts?.find(p => p.inlineData)?.inlineData?.data;
            if (audioData && outputAudioContextRef.current) {
              setIsSpeaking(true);
              const ctx = outputAudioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);

              const buffer = await decodeAudioData(decodeAudio(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              };
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }

            if (msg.serverContent?.outputTranscription) {
              const text = msg.serverContent.outputTranscription.text;
              transcriptionRef.current += text;
              setCurrentTranscription(transcriptionRef.current);
            }

            if (msg.serverContent?.turnComplete) {
              setMessages(prev => {
                const final = transcriptionRef.current || "...";
                return [...prev, { role: 'model', text: final, timestamp: new Date() }];
              });
              transcriptionRef.current = '';
              setCurrentTranscription('');
            }

            if (msg.serverContent?.interrupted) stopAudio();
          },
          onerror: (e) => console.error("Link Failure", e),
          onclose: () => {
            setIsLiveActive(false);
            sessionPromiseRef.current = null;
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          outputAudioTranscription: {},
          speechConfig: { 
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          },
          systemInstruction: `You are BFC Assist.
User: ${currentUser?.name || 'Guest'}. 
Menu Context:
${menuContext}

Goals:
1. Provide intelligent recommendations based on the menu.
2. Understand complex ingredients or preferences.
3. Be conversational but concise.
4. Use Bengali primarily.
5. Emphasize "Popular" items in recommendations.`
        }
      });
    } catch (e) {
      console.error("Connection failed", e);
    }
  }, [isOnline, currentUser]);

  const handleSend = async () => {
    const text = input.trim();
    if (!text) return;

    stopAudio();
    setMessages(prev => [...prev, { role: 'user', text, timestamp: new Date() }]);
    setInput('');
    setIsLoading(true);

    if (sessionPromiseRef.current) {
      sessionPromiseRef.current.then((session) => {
        session.sendRealtimeInput({ message: { parts: [{ text }] } });
        setIsLoading(false);
      });
    } else {
      const aiResponse = await bfcFastText(text, currentUser?.name);
      setMessages(prev => [...prev, { role: 'model', text: aiResponse, timestamp: new Date() }]);
      setIsLoading(false);
    }
  };

  const toggleMic = async () => {
    if (!sessionPromiseRef.current) await connectLive();

    if (isMicOn) {
      if (micStreamRef.current) micStreamRef.current.getTracks().forEach(t => t.stop());
      setIsMicOn(false);
      return;
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;
      setIsMicOn(true);

      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      inputAudioContextRef.current = ctx;
      const source = ctx.createMediaStreamSource(stream);
      const processor = ctx.createScriptProcessor(4096, 1, 1);

      processor.onaudioprocess = (e) => {
        const inputData = e.inputBuffer.getChannelData(0);
        const int16 = new Int16Array(inputData.length);
        for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;

        sessionPromiseRef.current?.then((session) => {
          session.sendRealtimeInput({
            media: { 
              data: encodeAudio(new Uint8Array(int16.buffer)), 
              mimeType: 'audio/pcm;rate=16000' 
            }
          });
        });
      };

      source.connect(processor);
      processor.connect(ctx.destination);
    } catch (e) {
      setIsMicOn(false);
    }
  };

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages, currentTranscription]);

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-12 lg:right-12 z-[5000]">
      {isOpen ? (
        <div className="bg-white/95 dark:bg-gray-950/95 backdrop-blur-3xl w-[85vw] sm:w-[320px] h-[55vh] sm:h-[450px] rounded-[40px] shadow-[0_50px_100px_-20px_rgba(220,38,38,0.4)] flex flex-col border border-white/20 dark:border-white/10 overflow-hidden animate-slide-up ring-1 ring-black/5">
          <div className="bg-red-600 p-5 text-white flex justify-between items-center shrink-0">
            <div className="flex items-center gap-3">
               <div className={`w-8 h-8 rounded-xl flex items-center justify-center ${isSpeaking ? 'bg-white text-red-600' : 'bg-white/20'}`}>
                  <i className={`fas ${isSpeaking ? 'fa-waveform animate-pulse' : 'fa-bolt-lightning'} text-xs`}></i>
               </div>
               <div>
                 <span className="text-[10px] font-black uppercase tracking-widest italic block">BFC INTELLIGENT ASSIST</span>
                 <span className="text-[7px] font-bold opacity-70 uppercase tracking-widest">Advanced NLU: Active</span>
               </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="w-8 h-8 bg-white/10 rounded-xl flex items-center justify-center hover:bg-white/20 transition-all">
              <i className="fas fa-times text-[10px]"></i>
            </button>
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-5 space-y-4 scrollbar-hide bg-gray-50/10 custom-scrollbar">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-fade-in`}>
                <div className={`max-w-[85%] px-4 py-3 rounded-[24px] text-[11px] font-black ${m.role === 'user' ? 'bg-red-600 text-white shadow-lg' : 'bg-white dark:bg-gray-900 text-gray-800 dark:text-gray-100 border border-gray-100 dark:border-white/5 shadow-sm'}`}>
                  {m.text}
                </div>
              </div>
            ))}
            {currentTranscription && (
              <div className="flex justify-start">
                <div className="max-w-[85%] px-4 py-2 rounded-[22px] text-[11px] font-black bg-white dark:bg-gray-900 text-red-600 border border-red-50 animate-pulse italic">
                  {currentTranscription}
                </div>
              </div>
            )}
            {isLoading && (
              <div className="flex justify-start">
                <div className="flex gap-1 p-2">
                  <span className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce"></span>
                  <span className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                  <span className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce [animation-delay:0.4s]"></span>
                </div>
              </div>
            )}
          </div>

          <div className="p-4 bg-white dark:bg-gray-950 border-t dark:border-white/5 flex gap-3 shrink-0">
            <button onClick={toggleMic} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isMicOn ? 'bg-red-600 text-white animate-pulse shadow-lg shadow-red-600/30' : 'bg-gray-100 dark:bg-gray-900 text-gray-400 hover:text-red-600'}`}>
              <i className={`fas ${isMicOn ? 'fa-microphone' : 'fa-microphone-slash'} text-sm`}></i>
            </button>
            <div className="flex-1 flex items-center bg-gray-100 dark:bg-gray-900 rounded-2xl p-1 shadow-inner">
              <input 
                type="text" value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSend()}
                placeholder="একটি খাবারের নাম বা প্রশ্ন লিখুন..."
                className="flex-1 bg-transparent border-none px-4 outline-none text-[11px] font-black dark:text-white placeholder:opacity-50"
              />
              <button onClick={handleSend} className="w-10 h-10 bg-red-600 text-white rounded-xl flex items-center justify-center shadow-lg active:scale-90 transition-all hover:brightness-110">
                <i className="fas fa-paper-plane text-[10px]"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button onClick={() => setIsOpen(true)} className="w-16 h-16 bg-red-600 text-white rounded-[24px] shadow-[0_20px_60px_rgba(220,38,38,0.5)] flex flex-col items-center justify-center hover:scale-110 active:scale-90 transition-all group border-2 border-white/20 overflow-hidden pulse-primary">
           <i className="fas fa-bolt-lightning text-2xl group-hover:animate-bounce"></i>
           {isSpeaking && <span className="absolute top-2 right-2 flex h-3 w-3"><span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span><span className="relative inline-flex rounded-full h-3 w-3 bg-white"></span></span>}
        </button>
      )}
    </div>
  );
};

