                    <input type="password" placeholder="••••••••••••" value={loginKey} onChange={e => setLoginKey(e.target.value)} className="w-full bg-white/5 themed-border border p-6 pl-14 rounded-3xl outline-none font-black text-xs uppercase focus:themed-primary/20 focus:themed-border transition-all" />
                   </div>
                </div>

                <Button fullWidth size="lg" className="rounded-[32px] py-10 shadow-2xl" onClick={handleAuth}>
                  {isNewCustomer ? 'INITIALIZE IDENTITY' : 'AUTHORIZE SESSION'}
                </Button>

                <div className="flex flex-col sm:flex-row justify-between items-center gap-4 px-6">
                   <button onClick={() => setIsNewCustomer(!isNewCustomer)} className="text-[10px] font-black uppercase tracking-widest themed-text-primary hover:brightness-125 transition-all">
                     {isNewCustomer ? 'Already registered? Login —>' : 'New recruit? Register —>'}
                   </button>
                   <button className="text-[10px] font-black uppercase tracking-widest opacity-30 hover:opacity-100 transition-opacity">Forgotten Key?</button>
                </div>
              </div>
            </div>

            <div className="mt-12 flex justify-center gap-10 opacity-20">
              <i className="fab fa-apple text-3xl"></i>
              <i className="fab fa-google text-3xl"></i>
              <i className="fab fa-facebook text-3xl"></i>
            </div>
          </div>
        )}
      </main>

      <ChatBot isOnline={true} currentUser={currentUser} />

      {/* Mobile Bottom Navigation Bar */}
      <nav className="fixed bottom-0 inset-x-0 z-[6000] lg:hidden glass-nav border-t themed-border flex justify-around items-center safe-bottom h-20">
        {[
          { id: 'HOME', icon: 'fa-house' },
          { id: 'MENU', icon: 'fa-utensils' },
          { id: 'VAULT', icon: 'fa-shield-halved' },
          { id: 'CART', icon: 'fa-shopping-basket' },
          { id: 'LOGIN', icon: 'fa-user' }
        ].map(item => (
          <button key={item.id} onClick={() => setView(item.id as any)} className={`flex flex-col items-center justify-center w-full h-full transition-all ${view === item.id ? 'themed-text-primary' : 'opacity-30'}`}>
            <i className={`fas ${item.icon} text-lg mb-1`}></i>
            <span className="text-[7px] font-black uppercase tracking-[3px]">{item.id}</span>
          </button>
        ))}
      </nav>
    </div>
  );
};

export default App;

export enum UserRole {
  ADMIN = 'ADMIN',
  MANAGER = 'MANAGER',
  STAFF = 'STAFF',
  CUSTOMER = 'CUSTOMER'
}

export enum OrderStatus {
  PENDING = 'PENDING',
  PREPARING = 'PREPARING',
  READY = 'READY',
  ON_THE_WAY = 'ON_THE_WAY',
  DELIVERED = 'DELIVERED',
  CANCELLED = 'CANCELLED'
}

export type LayoutPreset = 
  | 'ELITE_DARK' 
  | 'CLASSIC_RED' 
  | 'CYBER_NEON' 
  | 'MINIMAL_WHITE' 
  | 'NATURE_GREEN' 
  | 'LUXURY_GOLD' 
  | 'RETRO_VIBE' 
  | 'BOLD_MONO' 
  | 'PASTEL_SOFT' 
  | 'HIGH_TECH';

export interface ThemeConfig {
  bg: string;
  fg: string;
  primary: string;
  accent: string;
  card: string;
  border: string;
  font: string;
  shadow: string;
}

export interface SiteCMS {
  activeLayout: LayoutPreset;
  themeDefinitions: Record<LayoutPreset, ThemeConfig>;
  hero: {
    title: string;
    subtitle: string;
    description: string;
    image: string;
    cta: string;
  };
  navigation: {
    brand: string;
    links: { [key: string]: string };
  };
  vault: {
    title: string;
    description: string;
  };
}

export interface MenuItem {
  id: string;
  name: string;
  nameBn: string;
  description: string;
  price: number;
  category: string;
  image: string;
  stock: number;
  rating?: number;
  ingredients?: string[];
  dietary?: string[];
  prepTime?: string;
  isPopular?: boolean;
}

export interface CartItem {
  item: MenuItem;
  qty: number;
}

export interface ClaimedVoucher {
  id: string;
  uniqueCode: string;
  status: 'ACTIVE' | 'EXPENDED';
  title: string;
  discountValue: number;
  isPercentage: boolean;
}

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  items: any[];
  total: number;
  status: OrderStatus;
  createdAt: string;
  paymentMethod: string;
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  loyaltyPoints: number;
  claimedVouchers: ClaimedVoucher[];
  tier: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem, SiteCMS, ThemeConfig, LayoutPreset } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  id: number;
  message: string;
  description?: string;
  type: 'success' | 'error' | 'warning' | 'info';
}

const DEFAULT_THEMES: Record<LayoutPreset, ThemeConfig> = {
  ELITE_DARK: { bg: '#030712', fg: '#f9fafb', primary: '#dc2626', accent: '#ef4444', card: '#111827', border: '#1f2937', font: 'Plus Jakarta Sans', shadow: 'rgba(0,0,0,0.5)' },
  CLASSIC_RED: { bg: '#fef2f2', fg: '#111827', primary: '#dc2626', accent: '#991b1b', card: '#ffffff', border: '#fee2e2', font: 'Plus Jakarta Sans', shadow: 'rgba(220,38,38,0.1)' },
  CYBER_NEON: { bg: '#000000', fg: '#06b6d4', primary: '#06b6d4', accent: '#d946ef', card: '#080808', border: '#164e63', font: 'JetBrains Mono', shadow: 'rgba(6,182,212,0.2)' },
  MINIMAL_WHITE: { bg: '#ffffff', fg: '#0f172a', primary: '#111827', accent: '#64748b', card: '#f8fafc', border: '#f1f5f9', font: 'Plus Jakarta Sans', shadow: 'rgba(0,0,0,0.05)' },
  NATURE_GREEN: { bg: '#f0fdf4', fg: '#064e3b', primary: '#059669', accent: '#10b981', card: '#ffffff', border: '#dcfce7', font: 'Plus Jakarta Sans', shadow: 'rgba(5,150,105,0.1)' },
  LUXURY_GOLD: { bg: '#0c0a09', fg: '#fafaf9', primary: '#d97706', accent: '#f59e0b', card: '#1c1917', border: '#292524', font: 'Playfair Display', shadow: 'rgba(217,119,6,0.2)' },
  RETRO_VIBE: { bg: '#fdf2f8', fg: '#831843', primary: '#db2777', accent: '#ec4899', card: '#ffffff', border: '#fbcfe8', font: 'Plus Jakarta Sans', shadow: 'rgba(219,39,119,0.1)' },
  BOLD_MONO: { bg: '#000000', fg: '#ffffff', primary: '#ffffff', accent: '#888888', card: '#111111', border: '#333333', font: 'Plus Jakarta Sans', shadow: 'rgba(255,255,255,0.1)' },
  PASTEL_SOFT: { bg: '#f5f3ff', fg: '#4c1d95', primary: '#8b5cf6', accent: '#a78bfa', card: '#ffffff', border: '#ede9fe', font: 'Plus Jakarta Sans', shadow: 'rgba(139,92,246,0.1)' },
  HIGH_TECH: { bg: '#020617', fg: '#38bdf8', primary: '#0284c7', accent: '#0ea5e9', card: '#0f172a', border: '#1e293b', font: 'JetBrains Mono', shadow: 'rgba(2,132,199,0.2)' }
