                      <span className="text-sm self-center opacity-40 mr-4">NET</span>
                      <span className="themed-text-primary leading-none">৳{total}</span>
                    </div>
                  </div>

                  {paymentStep === 'IDLE' && (
                    <Button fullWidth size="lg" className="rounded-[28px] py-10 text-sm" onClick={() => setPaymentStep('SELECT')} disabled={cart.length === 0}>DEPLOY PAYMENT</Button>
