                  {paymentStep === 'SELECT' && (
                    <div className="space-y-8 animate-fade-in">
                      <div className="grid grid-cols-2 gap-4">
                        {['BKASH', 'NAGAD', 'VISA', 'COD'].map(m => (
                          <button key={m} onClick={() => setSelectedPayment(m)} className={`p-6 rounded-3xl border-2 transition-all font-black text-[10px] tracking-widest ${selectedPayment === m ? 'themed-primary border-transparent shadow-xl' : 'themed-border opacity-30 hover:opacity-100'}`}>{m}</button>
                        ))}
                      </div>
                      <div className="flex gap-4">
                        <Button variant="outline" fullWidth onClick={() => setPaymentStep('IDLE')} className="rounded-2xl">BACK</Button>
