                  {paymentStep === 'PROCESSING' && (
                    <div className="flex flex-col items-center justify-center py-10 space-y-6">
                      <div className="w-12 h-12 border-4 themed-text-primary border-t-transparent rounded-full animate-spin"></div>
                      <p className="font-black uppercase tracking-[8px] opacity-40 text-[10px]">Encrypting...</p>
                    </div>
                  )}

                  {paymentStep === 'SUCCESS' && (
                    <div className="text-center py-10 space-y-6 animate-elite-up">
                      <i className="fas fa-check-circle text-6xl themed-text-primary"></i>
                      <h3 className="text-2xl font-black italic uppercase">SECURED</h3>
                      <Button size="sm" className="rounded-xl" onClick={() => setView('HOME')}>DONE</Button>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}

        {/* LOGIN VIEW - ADVANCED PORTAL */}
        {view === 'LOGIN' && (
          <div className="max-w-xl mx-auto mt-10 lg:mt-20 px-6 animate-elite-up pb-40">
            <div className="themed-card p-10 lg:p-20 rounded-[72px] space-y-14 relative overflow-hidden">
              <div className="absolute top-0 left-0 w-full h-2 themed-primary"></div>
              <div className="text-center space-y-4">
                <h2 className="text-5xl lg:text-7xl font-black italic uppercase tracking-tighter leading-none">{isNewCustomer ? 'Registration' : 'Neural Access'}</h2>
                <p className="text-[11px] font-black uppercase tracking-[10px] opacity-40 leading-none">Sector: HQ Mainframe</p>
              </div>

              <div className="space-y-8">
                <div className="space-y-3">
                   <label className="text-[10px] font-black uppercase tracking-widest opacity-40 ml-6">Neural Identity (Email)</label>
                   <div className="relative">
                    <i className="fas fa-at absolute left-6 top-1/2 -translate-y-1/2 opacity-30 text-sm"></i>
                    <input placeholder="AGENT_NAME@BFC.ELITE" value={loginId} onChange={e => setLoginId(e.target.value)} className="w-full bg-white/5 themed-border border p-6 pl-14 rounded-3xl outline-none font-black text-xs uppercase focus:themed-primary/20 focus:themed-border transition-all" />
                   </div>
                </div>
                <div className="space-y-3">
                   <label className="text-[10px] font-black uppercase tracking-widest opacity-40 ml-6">Access Pulse Key</label>
                   <div className="relative">
                    <i className="fas fa-key absolute left-6 top-1/2 -translate-y-1/2 opacity-30 text-sm"></i>
                    <input type="password" placeholder="••••••••••••" value={loginKey} onChange={e => setLoginKey(e.target.value)} className="w-full bg-white/5 themed-border border p-6 pl-14 rounded-3xl outline-none font-black text-xs uppercase focus:themed-primary/20 focus:themed-border transition-all" />
                   </div>
                </div>

                <Button fullWidth size="lg" className="rounded-[32px] py-10 shadow-2xl" onClick={handleAuth}>
                  {isNewCustomer ? 'INITIALIZE IDENTITY' : 'AUTHORIZE SESSION'}
                </Button>

                <div className="flex flex-col sm:flex-row justify-between items-center gap-4 px-6">
                   <button onClick={() => setIsNewCustomer(!isNewCustomer)} className="text-[10px] font-black uppercase tracking-widest themed-text-primary hover:brightness-125 transition-all">
                     {isNewCustomer ? 'Already registered? Login —>' : 'New recruit? Register —>'}
                   </button>
                   <button className="text-[10px] font-black uppercase tracking-widest opacity-30 hover:opacity-100 transition-opacity">Forgotten Key?</button>
                </div>
              </div>
            </div>

            <div className="mt-12 flex justify-center gap-10 opacity-20">
              <i className="fab fa-apple text-3xl"></i>
              <i className="fab fa-google text-3xl"></i>
              <i className="fab fa-facebook text-3xl"></i>
            </div>
          </div>
        )}
      </main>

      <ChatBot isOnline={true} currentUser={currentUser} />

      {/* Mobile Bottom Navigation Bar */}
      <nav className="fixed bottom-0 inset-x-0 z-[6000] lg:hidden glass-nav border-t themed-border flex justify-around items-center safe-bottom h-20">
        {[
          { id: 'HOME', icon: 'fa-house' },
          { id: 'MENU', icon: 'fa-utensils' },
          { id: 'VAULT', icon: 'fa-shield-halved' },
          { id: 'CART', icon: 'fa-shopping-basket' },
          { id: 'LOGIN', icon: 'fa-user' }
        ].map(item => (
          <button key={item.id} onClick={() => setView(item.id as any)} className={`flex flex-col items-center justify-center w-full h-full transition-all ${view === item.id ? 'themed-text-primary' : 'opacity-30'}`}>
