            <span className="text-[7px] font-black uppercase tracking-[3px]">{item.id}</span>
          </button>
        ))}
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect } from 'react';
import { Order, MenuItem, SiteCMS, LayoutPreset, OrderStatus, ThemeConfig } from './types';
import { Button } from './components/Button';

interface AdminToast {
  id: number;
  message: string;
  type: 'success' | 'warning' | 'danger' | 'info';
  description?: string;
}

interface AdminPanelProps {
  cms: SiteCMS;
  setCms: (cms: SiteCMS) => void;
  menuItems: MenuItem[];
  setMenuItems: (items: MenuItem[]) => void;
  orders: Order[];
  setOrders: (orders: Order[]) => void;
  onLogout: () => void;
}

const LAYOUT_INFO: { id: LayoutPreset; name: string; desc: string }[] = [
  { id: 'ELITE_DARK', name: 'Elite Dark', desc: 'Premium deep contrast aesthetics.' },
  { id: 'CLASSIC_RED', name: 'Classic BFC', desc: 'Original BFC brand identity.' },
  { id: 'CYBER_NEON', name: 'Cyberpunk', desc: 'Neon glows and monospaced tech.' },
  { id: 'MINIMAL_WHITE', name: 'Clean Minimal', desc: 'Zero noise, maximum focus.' },
  { id: 'NATURE_GREEN', name: 'Nature Organic', desc: 'Earth-friendly organic tones.' },
  { id: 'LUXURY_GOLD', name: 'Luxury Gold', desc: 'High-end serif elegance.' },
  { id: 'RETRO_VIBE', name: '90s Retro', desc: 'Pastel aesthetics and bold edges.' },
  { id: 'BOLD_MONO', name: 'Bold Mono', desc: 'Aggressive monochrome energy.' },
  { id: 'PASTEL_SOFT', name: 'Pastel Soft', desc: 'Gentle, soft-touch interface.' },
  { id: 'HIGH_TECH', name: 'Blue High-Tech', desc: 'Scientific data-driven visuals.' },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  cms, setCms, menuItems, setMenuItems, orders, setOrders, onLogout 
}) => {
  const [tab, setTab] = useState<'LAYOUT' | 'CMS' | 'MENU' | 'ORDERS'>('LAYOUT');
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [isMobileSidebarOpen, setMobileSidebarOpen] = useState(false);
  const [toasts, setToasts] = useState<AdminToast[]>([]);
  const [customizingTheme, setCustomizingTheme] = useState<LayoutPreset | null>(cms.activeLayout);

  const showToast = useCallback((message: string, type: AdminToast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { id, message, type, description }]);
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id));
    }, 4000);
  }, []);

  const dismissToast = (id: number) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const selectLayout = (layoutId: LayoutPreset) => {
    setCms({ ...cms, activeLayout: layoutId });
    setCustomizingTheme(layoutId);
  };

  const persistLayout = () => {
    localStorage.setItem('bfc_cms', JSON.stringify(cms));
    showToast('Layout State Persisted', 'success', 'Current architectural settings synchronized to local storage.');
  };

  const updateThemeVariable = (layout: LayoutPreset, key: keyof ThemeConfig, value: string) => {
    const newDefs = { ...cms.themeDefinitions };
    newDefs[layout] = { ...newDefs[layout], [key]: value };
    setCms({ ...cms, themeDefinitions: newDefs });
  };

  const updateCms = (path: string, value: string) => {
    const keys = path.split('.');
    const newCms = { ...cms };
    let curr: any = newCms;
    for (let i = 0; i < keys.length - 1; i++) curr = curr[keys[i]];
    curr[keys[keys.length - 1]] = value;
    setCms(newCms);
  };

  const deleteMenuItem = (id: string) => {
    if (window.confirm("Purge unit from registry? This cannot be undone.")) {
      const itemToDelete = menuItems.find(i => i.id === id);
      setMenuItems(menuItems.filter(i => i.id !== id));
      showToast('Registry Purged', 'danger', `${itemToDelete?.name} has been removed from the mainframe.`);
    }
  };

  const saveMenuItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingItem) return;
    const isNew = !menuItems.find(i => i.id === editingItem.id);
    if (!isNew) {
      setMenuItems(menuItems.map(i => i.id === editingItem.id ? editingItem : i));
      showToast('Registry Updated', 'success', `Configuration for ${editingItem.name} has been saved.`);
    } else {
      setMenuItems([...menuItems, editingItem]);
      showToast('New Unit Authenticated', 'success', `${editingItem.name} is now active in the registry.`);
    }
    setEditingItem(null);
  };

  const updateOrderStatus = (orderId: string, status: OrderStatus) => {
    setOrders(orders.map(o => o.id === orderId ? { ...o, status } : o));
    showToast('Mission Status Updated', 'info', `Order ${orderId} transitioned to ${status}.`);
  };

  return (
    <div className={`themed-root flex flex-col lg:flex-row h-screen theme-${cms.activeLayout} overflow-hidden`}>
      {/* Admin Toast Container */}
      <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[10000] flex flex-col items-center gap-3 w-full max-w-md px-6 pointer-events-none">
        {toasts.map(t => (
          <div 
            key={t.id} 
            onClick={() => dismissToast(t.id)}
            className={`pointer-events-auto flex items-start gap-4 p-5 rounded-[32px] border border-white/10 shadow-2xl backdrop-blur-3xl animate-elite-up cursor-pointer group hover:scale-105 transition-all
              ${t.type === 'danger' ? 'bg-red-950/90 text-red-100' : 'bg-gray-900/90 text-white'}`}
          >
            <div className={`w-10 h-10 rounded-2xl flex items-center justify-center shrink-0 ${t.type === 'danger' ? 'bg-red-600' : 'themed-primary'}`}>
              <i className={`fas ${t.type === 'danger' ? 'fa-bolt' : 'fa-check-circle'} text-sm`}></i>
            </div>
            <div className="flex-1">
              <h4 className="text-[10px] font-black uppercase tracking-[3px] leading-tight">{t.message}</h4>
              {t.description && <p className="text-[9px] opacity-60 mt-1 font-medium leading-relaxed">{t.description}</p>}
            </div>
            <div className="opacity-0 group-hover:opacity-100 transition-opacity">
              <i className="fas fa-times text-[10px] opacity-40"></i>
            </div>
          </div>
        ))}
      </div>

      {/* Mobile Top Header */}
      <header className="lg:hidden flex justify-between items-center p-5 glass-nav border-b themed-border z-[6000]">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 themed-primary rounded-lg flex items-center justify-center font-black">B</div>
          <h1 className="text-lg font-black italic tracking-tighter text-[var(--primary)] uppercase leading-none">COMMAND HUB</h1>
        </div>
        <button onClick={() => setMobileSidebarOpen(!isMobileSidebarOpen)} className="w-10 h-10 themed-card rounded-xl flex items-center justify-center">
          <i className={`fas ${isMobileSidebarOpen ? 'fa-times' : 'fa-bars'} text-sm`}></i>
        </button>
      </header>

      {/* Sidebar - Desktop and Mobile */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[5500] w-full lg:w-80 themed-card border-r themed-border p-8 flex flex-col gap-10 transition-transform duration-500 ease-in-out ${isMobileSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="hidden lg:flex items-center gap-4">
          <div className="w-10 h-10 themed-primary rounded-xl flex items-center justify-center font-black">B</div>
          <h1 className="text-2xl font-black italic tracking-tighter themed-text-primary uppercase leading-none">BFC COMMANDER</h1>
        </div>

        <nav className="flex flex-col gap-3 flex-1 pt-20 lg:pt-0 overflow-y-auto no-scrollbar">
          {[
            { id: 'LAYOUT', icon: 'fa-layer-group', label: 'Layout Store' },
            { id: 'CMS', icon: 'fa-pen-to-square', label: 'Mainframe CMS' },
            { id: 'MENU', icon: 'fa-utensils', label: 'Unit Registry' },
            { id: 'ORDERS', icon: 'fa-satellite-dish', label: 'Mission Logs' }
          ].map((t: any) => (
            <button 
              key={t.id} 
              onClick={() => { setTab(t.id); setMobileSidebarOpen(false); }} 
              className={`p-6 rounded-[32px] text-[10px] font-black uppercase tracking-[4px] text-left transition-all flex items-center gap-5 ${tab === t.id ? 'themed-primary shadow-2xl scale-105 z-10' : 'opacity-40 hover:opacity-100 hover:bg-white/5'}`}
            >
              <i className={`fas ${t.icon} text-base w-6 text-center`}></i>
              {t.label}
            </button>
          ))}
        </nav>

        <div className="space-y-4">
          <div className="p-6 rounded-3xl bg-white/5 themed-border border space-y-2">
            <p className="text-[9px] font-black uppercase opacity-40 tracking-widest leading-none">System Status</p>
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
              <span className="text-[10px] font-black uppercase italic">Neural Link Active</span>
            </div>
          </div>
          <button onClick={onLogout} className="w-full p-6 rounded-[32px] text-[10px] font-black uppercase tracking-[5px] border themed-border themed-text-primary hover:bg-[var(--primary)] hover:text-white transition-all shadow-xl">DE-AUTHORIZE HUB</button>
        </div>
      </aside>

      {/* Main Command Area */}
      <main className="flex-1 overflow-y-auto p-6 lg:p-16 custom-scrollbar bg-black/20">

        {tab === 'LAYOUT' && (
          <div className="space-y-16 animate-elite-up pb-20">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-8">
              <div className="space-y-3">
                <h2 className="text-4xl lg:text-7xl font-black italic uppercase tracking-tighter leading-none">Layout Store</h2>
                <p className="text-[11px] font-black uppercase tracking-[10px] opacity-40">Architectural Visual Overrides</p>
              </div>
              <Button size="lg" className="rounded-2xl" onClick={persistLayout}>SAVE CURRENT LAYOUT</Button>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6">
              {LAYOUT_INFO.map(l => (
                <button 
                  key={l.id} 
                  onClick={() => selectLayout(l.id)} 
                  className={`p-6 rounded-[40px] border-2 transition-all flex flex-col items-center gap-6 text-center group relative overflow-hidden ${cms.activeLayout === l.id ? 'themed-primary border-transparent shadow-2xl scale-105' : 'themed-card themed-border'}`}
                >
                   <div className={`w-16 h-16 rounded-[24px] shadow-2xl ring-4 ring-white/10 group-hover:rotate-12 transition-all duration-500`} style={{backgroundColor: cms.themeDefinitions[l.id].bg}}></div>
                   <div className="space-y-1">
                     <span className="text-[10px] font-black uppercase tracking-[2px] block">{l.name}</span>
                   </div>
                </button>
              ))}
            </div>

            {customizingTheme && (
              <section className="themed-card p-10 lg:p-16 rounded-[64px] space-y-12 border-white/5 animate-elite-up">
                 <div className="flex flex-col lg:flex-row justify-between items-center gap-8 border-b themed-border pb-8">
                    <div className="space-y-2 text-center lg:text-left">
                       <h3 className="text-3xl font-black italic uppercase leading-none">Variables: {customizingTheme}</h3>
                       <p className="text-[10px] font-black uppercase tracking-[5px] opacity-40">Modify core CSS properties for this cluster</p>
                    </div>
                    <Button onClick={() => {
                        const defaultTheme = DEFAULT_THEMES[customizingTheme];
                        if (defaultTheme) {
                           const newDefs = { ...cms.themeDefinitions };
                           newDefs[customizingTheme] = { ...defaultTheme };
                           setCms({ ...cms, themeDefinitions: newDefs });
                           showToast('Variables Reset', 'info', `Standard ${customizingTheme} values restored.`);
                        }
                    }} variant="outline" className="rounded-xl py-4">RESET TO DEFAULTS</Button>
                 </div>

                 <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
                    <VariableField label="Primary Color" value={cms.themeDefinitions[customizingTheme].primary} onChange={v => updateThemeVariable(customizingTheme, 'primary', v)} />
                    <VariableField label="Background" value={cms.themeDefinitions[customizingTheme].bg} onChange={v => updateThemeVariable(customizingTheme, 'bg', v)} />
                    <VariableField label="Foreground" value={cms.themeDefinitions[customizingTheme].fg} onChange={v => updateThemeVariable(customizingTheme, 'fg', v)} />
                    <VariableField label="Card Color" value={cms.themeDefinitions[customizingTheme].card} onChange={v => updateThemeVariable(customizingTheme, 'card', v)} />
                    <VariableField label="Border Color" value={cms.themeDefinitions[customizingTheme].border} onChange={v => updateThemeVariable(customizingTheme, 'border', v)} />
                    <VariableField label="Accent Color" value={cms.themeDefinitions[customizingTheme].accent} onChange={v => updateThemeVariable(customizingTheme, 'accent', v)} />
                    <VariableField label="Font Family" value={cms.themeDefinitions[customizingTheme].font} onChange={v => updateThemeVariable(customizingTheme, 'font', v)} />
                    <VariableField label="Shadow Definition" value={cms.themeDefinitions[customizingTheme].shadow} onChange={v => updateThemeVariable(customizingTheme, 'shadow', v)} />
                 </div>
              </section>
            )}
          </div>
        )}

        {tab === 'CMS' && (
          <div className="space-y-16 animate-elite-up pb-20">
            <h2 className="text-4xl lg:text-7xl font-black italic uppercase tracking-tighter leading-none">Mainframe Editor</h2>
            <div className="grid grid-cols-1 xl:grid-cols-2 gap-12">
              <section className="themed-card p-12 lg:p-16 rounded-[64px] space-y-10 border-white/5">
                 <h3 className="text-sm font-black themed-text-primary uppercase tracking-[6px] border-b themed-border pb-6">Landing Hero Core</h3>
                 <div className="grid gap-8">
                    <InputField label="Hero Title" value={cms.hero.title} onChange={v => updateCms('hero.title', v)} />
                    <InputField label="Hero Subtitle" value={cms.hero.subtitle} onChange={v => updateCms('hero.subtitle', v)} />
                    <InputField label="Hero Description" value={cms.hero.description} onChange={v => updateCms('hero.description', v)} />
                    <InputField label="Image Source (Unsplash/URL)" value={cms.hero.image} onChange={v => updateCms('hero.image', v)} />
                 </div>
              </section>
              <section className="themed-card p-12 lg:p-16 rounded-[64px] space-y-10 border-white/5">
