  | 'LUXURY_GOLD' 
  | 'RETRO_VIBE' 
  | 'BOLD_MONO' 
  | 'PASTEL_SOFT' 
  | 'HIGH_TECH';

export interface ThemeConfig {
  bg: string;
  fg: string;
  primary: string;
  accent: string;
  card: string;
  border: string;
  font: string;
  shadow: string;
}

export interface Promotion {
  id: string;
  name: string;
  code: string;
  discountType: 'PERCENTAGE' | 'FIXED';
  discountValue: number;
  startDate: string;
  endDate: string;
  usageLimit: number;
  usageCount: number;
  isActive: boolean;
}

export interface SiteCMS {
  activeLayout: LayoutPreset;
  themeDefinitions: Record<LayoutPreset, ThemeConfig>;
  hero: {
    title: string;
    subtitle: string;
    description: string;
    image: string;
    cta: string;
  };
  navigation: {
    brand: string;
    links: { [key: string]: string };
  };
  vault: {
    title: string;
    description: string;
  };
}

export interface MenuItem {
  id: string;
  name: string;
  nameBn: string;
  description: string;
  price: number;
  category: string;
  image: string;
  stock: number;
  rating?: number;
  ingredients?: string[];
  dietary?: string[];
  prepTime?: string;
  isPopular?: boolean;
}

export interface CartItem {
  item: MenuItem;
  qty: number;
}

export interface ClaimedVoucher {
  id: string;
  uniqueCode: string;
  status: 'ACTIVE' | 'EXPENDED';
  title: string;
  discountValue: number;
  isPercentage: boolean;
}

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  items: any[];
  total: number;
  status: OrderStatus;
  createdAt: string;
  paymentMethod: string;
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  loyaltyPoints: number;
  claimedVouchers: ClaimedVoucher[];
  tier: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

import React, { useState, useCallback, useEffect } from 'react';
import { Order, MenuItem, SiteCMS, LayoutPreset, OrderStatus, ThemeConfig, Promotion } from './types';
import { Button } from './components/Button';

interface AdminToast {
  id: number;
  message: string;
  type: 'success' | 'warning' | 'danger' | 'info';
  description?: string;
}

interface AdminPanelProps {
  cms: SiteCMS;
  setCms: (cms: SiteCMS) => void;
  menuItems: MenuItem[];
  setMenuItems: (items: MenuItem[]) => void;
  orders: Order[];
  setOrders: (orders: Order[]) => void;
  onLogout: () => void;
}

const LAYOUT_INFO: { id: LayoutPreset; name: string; desc: string }[] = [
  { id: 'ELITE_DARK', name: 'Elite Dark', desc: 'Premium deep contrast aesthetics.' },
  { id: 'CLASSIC_RED', name: 'Classic BFC', desc: 'Original BFC brand identity.' },
  { id: 'CYBER_NEON', name: 'Cyberpunk', desc: 'Neon glows and monospaced tech.' },
  { id: 'MINIMAL_WHITE', name: 'Clean Minimal', desc: 'Zero noise, maximum focus.' },
  { id: 'NATURE_GREEN', name: 'Nature Organic', desc: 'Earth-friendly organic tones.' },
  { id: 'LUXURY_GOLD', name: 'Luxury Gold', desc: 'High-end serif elegance.' },
  { id: 'RETRO_VIBE', name: '90s Retro', desc: 'Pastel aesthetics and bold edges.' },
  { id: 'BOLD_MONO', name: 'Bold Mono', desc: 'Aggressive monochrome energy.' },
  { id: 'PASTEL_SOFT', name: 'Pastel Soft', desc: 'Gentle, soft-touch interface.' },
  { id: 'HIGH_TECH', name: 'Blue High-Tech', desc: 'Scientific data-driven visuals.' },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  cms, setCms, menuItems, setMenuItems, orders, setOrders, onLogout 
}) => {
  const [tab, setTab] = useState<'LAYOUT' | 'CMS' | 'MENU' | 'ORDERS' | 'PROMOTIONS'>('LAYOUT');
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [promotions, setPromotions] = useState<Promotion[]>(() => {
    const saved = localStorage.getItem('bfc_promotions');
    return saved ? JSON.parse(saved) : [];
  });
  const [isAddingPromotion, setIsAddingPromotion] = useState(false);
  const [newPromo, setNewPromo] = useState<Partial<Promotion>>({
    discountType: 'PERCENTAGE',
    discountValue: 0,
    usageLimit: 100,
    isActive: true
  });

  const [isMobileSidebarOpen, setMobileSidebarOpen] = useState(false);
  const [toasts, setToasts] = useState<AdminToast[]>([]);
  const [customizingTheme, setCustomizingTheme] = useState<LayoutPreset | null>(cms.activeLayout);
  const [hoveredLayout, setHoveredLayout] = useState<LayoutPreset | null>(null);

  useEffect(() => {
    localStorage.setItem('bfc_promotions', JSON.stringify(promotions));
  }, [promotions]);

  const showToast = useCallback((message: string, type: AdminToast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { id, message, type, description }]);
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id));
    }, 4000);
  }, []);

  const dismissToast = (id: number) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const generateUniqueCode = () => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let code = 'BFC-';
    for (let i = 0; i < 6; i++) {
      code += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    setNewPromo(prev => ({ ...prev, code }));
  };

  const savePromotion = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPromo.name || !newPromo.code || !newPromo.discountValue) {
      showToast('Validation Failed', 'danger', 'Please provide all mandatory promotion data points.');
      return;
    }
    const promo: Promotion = {
      id: 'PRM-' + Date.now(),
      name: newPromo.name || '',
      code: newPromo.code || '',
      discountType: newPromo.discountType || 'PERCENTAGE',
      discountValue: Number(newPromo.discountValue) || 0,
      startDate: newPromo.startDate || new Date().toISOString().split('T')[0],
      endDate: newPromo.endDate || new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
      usageLimit: Number(newPromo.usageLimit) || 100,
      usageCount: 0,
      isActive: true
    };
    setPromotions(prev => [...prev, promo]);
    setIsAddingPromotion(false);
    setNewPromo({ discountType: 'PERCENTAGE', discountValue: 0, usageLimit: 100, isActive: true });
    showToast('Promotion Deployed', 'success', `Discount code ${promo.code} is now active in the neural grid.`);
  };

  const deletePromotion = (id: string) => {
    setPromotions(prev => prev.filter(p => p.id !== id));
    showToast('Promotion Purged', 'info', 'The discount sequence has been removed from the mainframe.');
  };

  const selectLayout = (layoutId: LayoutPreset) => {
    setCms({ ...cms, activeLayout: layoutId });
    setCustomizingTheme(layoutId);
    showToast('Layout Selected', 'info', `Visual engine switched to ${layoutId}. Remember to save.`);
  };

  const persistLayout = () => {
    localStorage.setItem('bfc_cms', JSON.stringify(cms));
    showToast('Layout State Persisted', 'success', 'Current architectural settings synchronized to local storage.');
  };

  const updateThemeVariable = (layout: LayoutPreset, key: keyof ThemeConfig, value: string) => {
    const newDefs = { ...cms.themeDefinitions };
    newDefs[layout] = { ...newDefs[layout], [key]: value };
    setCms({ ...cms, themeDefinitions: newDefs });
  };

  const updateCms = (path: string, value: string) => {
    const keys = path.split('.');
    const newCms = { ...cms };
    let curr: any = newCms;
    for (let i = 0; i < keys.length - 1; i++) curr = curr[keys[i]];
    curr[keys[keys.length - 1]] = value;
    setCms(newCms);
  };

  const deleteMenuItem = (id: string) => {
    if (window.confirm("Purge unit from registry? This cannot be undone.")) {
      const itemToDelete = menuItems.find(i => i.id === id);
      setMenuItems(menuItems.filter(i => i.id !== id));
      showToast('Registry Purged', 'danger', `${itemToDelete?.name} has been removed from the mainframe.`);
    }
  };

  const saveMenuItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingItem) return;
    const isNew = !menuItems.find(i => i.id === editingItem.id);
    if (!isNew) {
      setMenuItems(menuItems.map(i => i.id === editingItem.id ? editingItem : i));
      showToast('Registry Updated', 'success', `Configuration for ${editingItem.name} has been saved.`);
    } else {
      setMenuItems([...menuItems, editingItem]);
      showToast('New Unit Authenticated', 'success', `${editingItem.name} is now active in the registry.`);
    }
    setEditingItem(null);
  };

  const updateOrderStatus = (orderId: string, status: OrderStatus) => {
    setOrders(orders.map(o => o.id === orderId ? { ...o, status } : o));
    showToast('Mission Status Updated', 'info', `Order ${orderId} transitioned to ${status}.`);
  };

  const currentPreviewTheme = hoveredLayout || cms.activeLayout;

  return (
    <div className={`themed-root flex flex-col lg:flex-row h-screen theme-${cms.activeLayout} overflow-hidden`}>
      {/* Admin Toast Container */}
      <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[10000] flex flex-col items-center gap-3 w-full max-w-md px-6 pointer-events-none">
        {toasts.map(t => (
          <div 
            key={t.id} 
            onClick={() => dismissToast(t.id)}
            className={`pointer-events-auto flex items-start gap-4 p-5 rounded-[32px] border border-white/10 shadow-2xl backdrop-blur-3xl animate-elite-up cursor-pointer group hover:scale-105 transition-all
              ${t.type === 'danger' ? 'bg-red-950/90 text-red-100' : 'bg-gray-900/90 text-white'}`}
          >
            <div className={`w-10 h-10 rounded-2xl flex items-center justify-center shrink-0 ${t.type === 'danger' ? 'bg-red-600' : 'themed-primary'}`}>
              <i className={`fas ${t.type === 'danger' ? 'fa-bolt' : 'fa-check-circle'} text-sm`}></i>
            </div>
            <div className="flex-1">
              <h4 className="text-[10px] font-black uppercase tracking-[3px] leading-tight">{t.message}</h4>
              {t.description && <p className="text-[9px] opacity-60 mt-1 font-medium leading-relaxed">{t.description}</p>}
            </div>
            <div className="opacity-0 group-hover:opacity-100 transition-opacity">
              <i className="fas fa-times text-[10px] opacity-40"></i>
            </div>
          </div>
        ))}
      </div>

      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[5500] w-full lg:w-80 themed-card border-r themed-border p-8 flex flex-col gap-10 transition-transform duration-500 ease-in-out ${isMobileSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="hidden lg:flex items-center gap-4">
          <div className="w-10 h-10 themed-primary rounded-xl flex items-center justify-center font-black">B</div>
          <h1 className="text-2xl font-black italic tracking-tighter themed-text-primary uppercase leading-none">BFC COMMANDER</h1>
        </div>

        <nav className="flex flex-col gap-3 flex-1 pt-20 lg:pt-0 overflow-y-auto no-scrollbar">
          {[
            { id: 'LAYOUT', icon: 'fa-layer-group', label: 'Layout Store' },
            { id: 'CMS', icon: 'fa-pen-to-square', label: 'Mainframe CMS' },
            { id: 'MENU', icon: 'fa-utensils', label: 'Unit Registry' },
            { id: 'ORDERS', icon: 'fa-satellite-dish', label: 'Mission Logs' },
            { id: 'PROMOTIONS', icon: 'fa-tags', label: 'Promotions' }
          ].map((t: any) => (
            <button 
              key={t.id} 
              onClick={() => { setTab(t.id); setMobileSidebarOpen(false); }} 
              className={`p-6 rounded-[32px] text-[10px] font-black uppercase tracking-[4px] text-left transition-all flex items-center gap-5 ${tab === t.id ? 'themed-primary shadow-2xl scale-105 z-10' : 'opacity-40 hover:opacity-100 hover:bg-white/5'}`}
            >
              <i className={`fas ${t.icon} text-base w-6 text-center`}></i>
              {t.label}
            </button>
          ))}
        </nav>

        <div className="space-y-4">
          <div className="p-6 rounded-3xl bg-white/5 themed-border border space-y-2">
            <p className="text-[9px] font-black uppercase opacity-40 tracking-widest leading-none">System Status</p>
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
              <span className="text-[10px] font-black uppercase italic">Neural Link Active</span>
            </div>
          </div>
          <button onClick={onLogout} className="w-full p-6 rounded-[32px] text-[10px] font-black uppercase tracking-[5px] border themed-border themed-text-primary hover:bg-[var(--primary)] hover:text-white transition-all shadow-xl">DE-AUTHORIZE HUB</button>
        </div>
      </aside>

      {/* Main Command Area */}
      <main className="flex-1 overflow-y-auto p-6 lg:p-16 custom-scrollbar bg-black/20">

        {tab === 'LAYOUT' && (
          <div className="space-y-12 animate-elite-up pb-20 max-w-7xl mx-auto">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-8">
              <div className="space-y-3">
                <h2 className="text-4xl lg:text-7xl font-black italic uppercase tracking-tighter leading-none">Layout Store</h2>
                <p className="text-[11px] font-black uppercase tracking-[10px] opacity-40">Architectural Visual Overrides</p>
              </div>
              <Button size="lg" className="rounded-2xl" onClick={persistLayout}>SAVE CURRENT LAYOUT</Button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
               <div className="lg:col-span-2 grid grid-cols-2 sm:grid-cols-3 gap-4 lg:gap-6">
                 {LAYOUT_INFO.map(l => (
                   <button 
                     key={l.id} 
                     onClick={() => selectLayout(l.id)}
                     onMouseEnter={() => setHoveredLayout(l.id)}
                     onMouseLeave={() => setHoveredLayout(null)}
                     className={`p-6 rounded-[40px] border-2 transition-all flex flex-col items-center gap-6 text-center group relative overflow-hidden ${cms.activeLayout === l.id ? 'themed-primary border-transparent shadow-2xl scale-105 z-10' : 'themed-card themed-border hover:themed-border active:scale-95'}`}
                   >
                      <div className={`w-16 h-16 rounded-[24px] shadow-2xl ring-4 ring-white/10 group-hover:rotate-12 transition-all duration-500`} style={{backgroundColor: cms.themeDefinitions[l.id].bg}}></div>
                      <div className="space-y-1">
                        <span className="text-[10px] font-black uppercase tracking-[2px] block">{l.name}</span>
                      </div>
                      {hoveredLayout === l.id && (
                        <div className="absolute top-2 right-2 flex gap-1 items-center">
                          <span className="w-1 h-1 bg-white rounded-full animate-ping"></span>
                          <span className="text-[7px] font-black uppercase tracking-widest opacity-50">Previewing</span>
                        </div>
                      )}
                   </button>
                 ))}
               </div>

               <div className="space-y-6">
                  <div className="flex items-center gap-3 px-4">
                    <i className="fas fa-desktop text-xs opacity-30"></i>
                    <h4 className="text-[11px] font-black uppercase tracking-[5px] opacity-40">Neural Theme Preview</h4>
                  </div>
                  <ThemePreviewMonitor 
                    theme={cms.themeDefinitions[currentPreviewTheme]} 
                    cms={cms}
                  />
                  <div className="p-6 themed-card rounded-[32px] space-y-4 border-dashed border-2">
                    <div className="flex items-center gap-2">
                      <i className="fas fa-info-circle themed-text-primary text-[10px]"></i>
                      <span className="text-[9px] font-black uppercase tracking-widest opacity-60 italic">Live Simulation Mode</span>
                    </div>
                    <p className="text-[10px] font-medium leading-relaxed opacity-40">Hover over any preset on the left to instantly update this simulation cluster with the corresponding neural color patterns.</p>
                  </div>
               </div>
            </div>

            {customizingTheme && (
              <section className="themed-card p-10 lg:p-16 rounded-[64px] space-y-12 border-white/5 animate-elite-up mt-12">
                 <div className="flex flex-col lg:flex-row justify-between items-center gap-8 border-b themed-border pb-8">
                    <div className="space-y-2 text-center lg:text-left">
                       <h3 className="text-3xl font-black italic uppercase leading-none">Variables: {customizingTheme}</h3>
                       <p className="text-[10px] font-black uppercase tracking-[5px] opacity-40">Modify core CSS properties for this cluster</p>
                    </div>
                    <Button onClick={() => {
                        const defaultTheme = DEFAULT_THEMES[customizingTheme];
                        if (defaultTheme) {
                           const newDefs = { ...cms.themeDefinitions };
                           newDefs[customizingTheme] = { ...defaultTheme };
                           setCms({ ...cms, themeDefinitions: newDefs });
                           showToast('Variables Reset', 'info', `Standard ${customizingTheme} values restored.`);
                        }
                    }} variant="outline" className="rounded-xl py-4">RESET TO DEFAULTS</Button>
                 </div>

                 <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
                    <VariableField label="Primary Color" value={cms.themeDefinitions[customizingTheme].primary} onChange={v => updateThemeVariable(customizingTheme, 'primary', v)} />
                    <VariableField label="Background" value={cms.themeDefinitions[customizingTheme].bg} onChange={v => updateThemeVariable(customizingTheme, 'bg', v)} />
                    <VariableField label="Foreground" value={cms.themeDefinitions[customizingTheme].fg} onChange={v => updateThemeVariable(customizingTheme, 'fg', v)} />
                    <VariableField label="Card Color" value={cms.themeDefinitions[customizingTheme].card} onChange={v => updateThemeVariable(customizingTheme, 'card', v)} />
                    <VariableField label="Border Color" value={cms.themeDefinitions[customizingTheme].border} onChange={v => updateThemeVariable(customizingTheme, 'border', v)} />
                    <VariableField label="Accent Color" value={cms.themeDefinitions[customizingTheme].accent} onChange={v => updateThemeVariable(customizingTheme, 'accent', v)} />
                    <VariableField label="Font Family" value={cms.themeDefinitions[customizingTheme].font} onChange={v => updateThemeVariable(customizingTheme, 'font', v)} />
                    <VariableField label="Shadow Definition" value={cms.themeDefinitions[customizingTheme].shadow} onChange={v => updateThemeVariable(customizingTheme, 'shadow', v)} />
                 </div>
              </section>
            )}
          </div>
        )}

        {tab === 'PROMOTIONS' && (
          <div className="space-y-16 animate-elite-up pb-20">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-8">
               <div className="space-y-2">
                 <h2 className="text-4xl lg:text-7xl font-black italic uppercase tracking-tighter leading-none">Promotion Hub</h2>
                 <p className="text-[11px] font-black uppercase tracking-[10px] opacity-40">Discount Strategy & Campaigns</p>
               </div>
               <Button size="lg" className="rounded-[28px] py-8" onClick={() => setIsAddingPromotion(true)}>DEPLOY NEW PROMO</Button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
              {promotions.map(promo => (
                <div key={promo.id} className="themed-card p-10 rounded-[56px] space-y-8 relative overflow-hidden group">
                  <div className="absolute top-0 right-0 w-32 h-32 themed-primary/10 blur-[60px]"></div>
                  <div className="flex justify-between items-start">
                    <div className="space-y-2">
                      <h4 className="text-2xl font-black italic uppercase leading-none">{promo.name}</h4>
                      <p className="text-[10px] font-black themed-text-primary uppercase tracking-[4px]">{promo.code}</p>
                    </div>
                    <div className={`w-3 h-3 rounded-full ${promo.isActive ? 'bg-emerald-500 animate-pulse' : 'bg-red-500'}`}></div>
                  </div>

                  <div className="grid grid-cols-2 gap-6 pt-4 border-t themed-border">
                    <div>
                      <p className="text-[8px] font-black uppercase opacity-40 tracking-widest mb-1">Value</p>
                      <p className="text-xl font-black">{promo.discountType === 'PERCENTAGE' ? `${promo.discountValue}%` : `৳${promo.discountValue}`}</p>
                    </div>
                    <div>
                      <p className="text-[8px] font-black uppercase opacity-40 tracking-widest mb-1">Utilization</p>
                      <p className="text-xl font-black">{promo.usageCount} / {promo.usageLimit}</p>
                    </div>
                  </div>

                  <div className="space-y-1">
                    <p className="text-[8px] font-black uppercase opacity-40 tracking-widest">Active Cycle</p>
                    <p className="text-[10px] font-black uppercase">{promo.startDate} — {promo.endDate}</p>
                  </div>

                  <Button variant="danger" fullWidth className="rounded-2xl py-6" onClick={() => deletePromotion(promo.id)}>PURGE PROMO</Button>
                </div>
              ))}
              {promotions.length === 0 && (
                <div className="col-span-full py-40 text-center opacity-20 space-y-6">
                   <i className="fas fa-ticket text-7xl"></i>
                   <p className="text-xl font-black uppercase tracking-[15px]">No Campaigns Active</p>
                </div>
              )}
            </div>

            {isAddingPromotion && (
              <div className="fixed inset-0 z-[10000] glass-nav p-6 lg:p-20 overflow-y-auto flex items-center justify-center">
                 <form onSubmit={savePromotion} className="themed-card p-10 lg:p-20 rounded-[72px] w-full max-w-3xl space-y-12 relative shadow-[0_50px_100px_-20px_rgba(0,0,0,0.5)] border-white/10">
                    <button type="button" onClick={() => setIsAddingPromotion(false)} className="absolute top-12 right-12 w-12 h-12 rounded-full hover:bg-white/5 flex items-center justify-center text-xl"><i className="fas fa-times"></i></button>
                    <div className="space-y-4">
                      <h3 className="text-4xl lg:text-6xl font-black italic uppercase tracking-tighter leading-none">New Campaign</h3>
                      <p className="text-[10px] font-black opacity-30 uppercase tracking-[8px]">Promotion Configuration Protocol</p>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
                       <InputField label="Campaign Name" value={newPromo.name} onChange={v => setNewPromo({...newPromo, name: v})} placeholder="e.g. SUMMER FEAST" />
                       <div className="space-y-3">
                         <label className="text-[11px] font-black uppercase tracking-[5px] opacity-40 ml-6">Unique Code</label>
                         <div className="flex gap-4">
                           <input 
                             value={newPromo.code} 
                             onChange={e => setNewPromo({...newPromo, code: e.target.value.toUpperCase()})}
                             className="flex-1 bg-white/5 themed-border border p-6 rounded-[32px] outline-none font-black text-xs uppercase focus:themed-primary/20 focus:themed-border transition-all" 
                             placeholder="AUTO-GENERATED"
                           />
                           <button type="button" onClick={generateUniqueCode} className="w-16 h-16 themed-primary rounded-3xl flex items-center justify-center text-xl shadow-xl hover:rotate-180 transition-all duration-500">
                             <i className="fas fa-arrows-rotate"></i>
                           </button>
                         </div>
                       </div>

                       <div className="space-y-3">
                         <label className="text-[11px] font-black uppercase tracking-[5px] opacity-40 ml-6">Discount Logic</label>
                         <select 
                           value={newPromo.discountType}
                           onChange={e => setNewPromo({...newPromo, discountType: e.target.value as any})}
                           className="w-full bg-white/5 themed-border border p-6 rounded-[32px] outline-none font-black text-xs uppercase focus:themed-primary/20 focus:themed-border transition-all"
                         >
                           <option value="PERCENTAGE">Percentage (%)</option>
                           <option value="FIXED">Fixed Amount (৳)</option>
                         </select>
                       </div>
                       <InputField label="Discount Value" value={String(newPromo.discountValue)} onChange={v => setNewPromo({...newPromo, discountValue: Number(v)})} type="number" />

                       <InputField label="Start Date" value={newPromo.startDate} onChange={v => setNewPromo({...newPromo, startDate: v})} type="date" />
