export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  cms, setCms, menuItems, setMenuItems, orders, setOrders, onLogout 
}) => {
  const [tab, setTab] = useState<'LAYOUT' | 'CMS' | 'MENU' | 'ORDERS' | 'PROMOTIONS'>('LAYOUT');
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [promotions, setPromotions] = useState<Promotion[]>(() => {
    const saved = localStorage.getItem('bfc_promotions');
    return saved ? JSON.parse(saved) : [];
  });

  // UI States for Promotion Management
  const [isPromoModalOpen, setIsPromoModalOpen] = useState(false);
  const [editingPromoId, setEditingPromoId] = useState<string | null>(null);
  const [promoForm, setPromoForm] = useState<Partial<Promotion>>({
    discountType: 'PERCENTAGE',
    discountValue: 0,
    usageLimit: 100,
    isActive: true
  });

  const [isMobileSidebarOpen, setMobileSidebarOpen] = useState(false);
  const [toasts, setToasts] = useState<AdminToast[]>([]);
  const [customizingTheme, setCustomizingTheme] = useState<LayoutPreset | null>(cms.activeLayout);
  const [hoveredLayout, setHoveredLayout] = useState<LayoutPreset | null>(null);

  useEffect(() => {
    localStorage.setItem('bfc_promotions', JSON.stringify(promotions));
  }, [promotions]);

  const showToast = useCallback((message: string, type: AdminToast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { id, message, type, description }]);
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id));
    }, 4000);
  }, []);

  const dismissToast = (id: number) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const generateUniqueCode = () => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let code = 'BFC-';
    for (let i = 0; i < 6; i++) {
      code += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    setPromoForm(prev => ({ ...prev, code }));
  };

  const openAddPromo = () => {
    setEditingPromoId(null);
    setPromoForm({
      discountType: 'PERCENTAGE',
      discountValue: 0,
      usageLimit: 100,
      isActive: true,
      startDate: new Date().toISOString().split('T')[0],
      endDate: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    });
    setIsPromoModalOpen(true);
  };

  const openEditPromo = (promo: Promotion) => {
    setEditingPromoId(promo.id);
    setPromoForm({ ...promo });
    setIsPromoModalOpen(true);
  };

  const savePromotion = (e: React.FormEvent) => {
    e.preventDefault();
    if (!promoForm.name || !promoForm.code || !promoForm.discountValue) {
      showToast('Validation Failed', 'danger', 'Please provide all mandatory promotion data points.');
      return;
    }

    if (editingPromoId) {
      setPromotions(prev => prev.map(p => p.id === editingPromoId ? { ...p, ...promoForm } as Promotion : p));
      showToast('Promotion Updated', 'success', `Configuration for ${promoForm.code} has been updated.`);
    } else {
      const promo: Promotion = {
        id: 'PRM-' + Date.now(),
        name: promoForm.name || '',
        code: promoForm.code || '',
        discountType: promoForm.discountType || 'PERCENTAGE',
        discountValue: Number(promoForm.discountValue) || 0,
        startDate: promoForm.startDate || '',
        endDate: promoForm.endDate || '',
        usageLimit: Number(promoForm.usageLimit) || 100,
        usageCount: 0,
        isActive: true
      };
      setPromotions(prev => [...prev, promo]);
      showToast('Promotion Deployed', 'success', `Discount code ${promo.code} is now active in the neural grid.`);
    }
    setIsPromoModalOpen(false);
  };

  const deletePromotion = (id: string) => {
    if (window.confirm("Purge promotion campaign from mainframe? This cannot be undone.")) {
      setPromotions(prev => prev.filter(p => p.id !== id));
      showToast('Promotion Purged', 'info', 'The discount sequence has been removed from the mainframe.');
    }
  };

  const selectLayout = (layoutId: LayoutPreset) => {
    setCms({ ...cms, activeLayout: layoutId });
    setCustomizingTheme(layoutId);
    showToast('Layout Selected', 'info', `Visual engine switched to ${layoutId}. Remember to save.`);
  };

  const persistLayout = () => {
    localStorage.setItem('bfc_cms', JSON.stringify(cms));
    showToast('Layout State Persisted', 'success', 'Current architectural settings synchronized to local storage.');
  };

  const updateThemeVariable = (layout: LayoutPreset, key: keyof ThemeConfig, value: string) => {
    const newDefs = { ...cms.themeDefinitions };
    newDefs[layout] = { ...newDefs[layout], [key]: value };
    setCms({ ...cms, themeDefinitions: newDefs });
  };

  const updateCms = (path: string, value: string) => {
    const keys = path.split('.');
    const newCms = { ...cms };
    let curr: any = newCms;
    for (let i = 0; i < keys.length - 1; i++) curr = curr[keys[i]];
    curr[keys[keys.length - 1]] = value;
    setCms(newCms);
  };

  const deleteMenuItem = (id: string) => {
    if (window.confirm("Purge unit from registry? This cannot be undone.")) {
      const itemToDelete = menuItems.find(i => i.id === id);
      setMenuItems(menuItems.filter(i => i.id !== id));
      showToast('Registry Purged', 'danger', `${itemToDelete?.name} has been removed from the mainframe.`);
    }
  };

  const saveMenuItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingItem) return;
    const isNew = !menuItems.find(i => i.id === editingItem.id);
    if (!isNew) {
      setMenuItems(menuItems.map(i => i.id === editingItem.id ? editingItem : i));
      showToast('Registry Updated', 'success', `Configuration for ${editingItem.name} has been saved.`);
    } else {
      setMenuItems([...menuItems, editingItem]);
      showToast('New Unit Authenticated', 'success', `${editingItem.name} is now active in the registry.`);
    }
    setEditingItem(null);
  };

  const updateOrderStatus = (orderId: string, status: OrderStatus) => {
    setOrders(orders.map(o => o.id === orderId ? { ...o, status } : o));
    showToast('Mission Status Updated', 'info', `Order ${orderId} transitioned to ${status}.`);
  };

  const currentPreviewTheme = hoveredLayout || cms.activeLayout;

  return (
    <div className={`themed-root flex flex-col lg:flex-row h-screen theme-${cms.activeLayout} overflow-hidden`}>
      {/* Admin Toast Container */}
      <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[10000] flex flex-col items-center gap-3 w-full max-w-md px-6 pointer-events-none">
        {toasts.map(t => (
          <div 
            key={t.id} 
            onClick={() => dismissToast(t.id)}
            className={`pointer-events-auto flex items-start gap-4 p-5 rounded-[32px] border border-white/10 shadow-2xl backdrop-blur-3xl animate-elite-up cursor-pointer group hover:scale-105 transition-all
              ${t.type === 'danger' ? 'bg-red-950/90 text-red-100' : 'bg-gray-900/90 text-white'}`}
          >
            <div className={`w-10 h-10 rounded-2xl flex items-center justify-center shrink-0 ${t.type === 'danger' ? 'bg-red-600' : 'themed-primary'}`}>
              <i className={`fas ${t.type === 'danger' ? 'fa-bolt' : 'fa-check-circle'} text-sm`}></i>
            </div>
            <div className="flex-1">
              <h4 className="text-[10px] font-black uppercase tracking-[3px] leading-tight">{t.message}</h4>
              {t.description && <p className="text-[9px] opacity-60 mt-1 font-medium leading-relaxed">{t.description}</p>}
            </div>
            <div className="opacity-0 group-hover:opacity-100 transition-opacity">
              <i className="fas fa-times text-[10px] opacity-40"></i>
            </div>
          </div>
        ))}
      </div>

      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[5500] w-full lg:w-80 themed-card border-r themed-border p-8 flex flex-col gap-10 transition-transform duration-500 ease-in-out ${isMobileSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="hidden lg:flex items-center gap-4">
          <div className="w-10 h-10 themed-primary rounded-xl flex items-center justify-center font-black">B</div>
          <h1 className="text-2xl font-black italic tracking-tighter themed-text-primary uppercase leading-none">BFC COMMANDER</h1>
        </div>

        <nav className="flex flex-col gap-3 flex-1 pt-20 lg:pt-0 overflow-y-auto no-scrollbar">
          {[
            { id: 'LAYOUT', icon: 'fa-layer-group', label: 'Layout Store' },
            { id: 'CMS', icon: 'fa-pen-to-square', label: 'Mainframe CMS' },
            { id: 'MENU', icon: 'fa-utensils', label: 'Unit Registry' },
            { id: 'ORDERS', icon: 'fa-satellite-dish', label: 'Mission Logs' },
