                                 className="bg-transparent text-[10px] font-black uppercase opacity-50 tracking-widest outline-none cursor-pointer hover:opacity-100 transition-opacity"
                               >
                                 {Object.values(OrderStatus).map(s => (
                                   <option key={s} value={s} className="bg-gray-900 text-white">{s}</option>
                                 ))}
                               </select>
                             </div>
                          </div>
                          <div className="hidden sm:block">
                            <Button variant="outline" className="rounded-2xl py-6 px-10">DETAILS</Button>
                          </div>
                       </div>
                    </div>
                 ))}
                 {orders.length === 0 && (
                   <div className="text-center py-40 opacity-20 space-y-6">
                      <i className="fas fa-ghost text-7xl"></i>
                      <p className="text-xl font-black uppercase tracking-[15px]">No Logs Recorded</p>
                   </div>
                 )}
              </div>
           </div>
        )}
      </main>
    </div>
  );
};

