  activeLayout: 'ELITE_DARK',
  themeDefinitions: DEFAULT_THEMES,
  hero: {
    title: "THE ULTIMATE TASTE OF BANGLADESH",
    subtitle: "ESTABLISHED 1999 • ELITE REGISTRY",
    description: "Experience the pinnacle of culinary excellence. Our neural logistics network ensures your feast arrives with absolute precision.",
    image: "https://images.unsplash.com/photo-1633945274405-b6c8069047b0?q=80&w=2000",
    cta: "EXPLORE REGISTRY"
  },
  navigation: {
    brand: "BFC ELITE",
    links: { home: "HOME", menu: "MENU", vault: "VAULT", profile: "PROFILE" }
  },
  vault: {
    title: "RIBOT WALLET",
    description: "Your secure vault for loyalty credits and exclusive BFC rewards. Every pulse counts towards your status."
  }
};

const App: React.FC = () => {
  const [cms, setCms] = useState<SiteCMS>(() => {
    const saved = localStorage.getItem('bfc_cms');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (!parsed.themeDefinitions) parsed.themeDefinitions = DEFAULT_THEMES;
      return parsed;
    }
    return DEFAULT_CMS;
  });

  const [menuItems, setMenuItems] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('bfc_menu');
    return saved ? JSON.parse(saved) : MOCK_MENU;
  });

  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT'>('HOME');
  const [paymentStep, setPaymentStep] = useState<'IDLE' | 'SELECT' | 'PROCESSING' | 'SUCCESS' | 'ERROR'>('IDLE');

  const [toasts, setToasts] = useState<Toast[]>([]);
  const [selectedPayment, setSelectedPayment] = useState('');

  const [loginId, setLoginId] = useState('');
  const [loginKey, setLoginKey] = useState('');
  const [isNewCustomer, setIsNewCustomer] = useState(false);

  const showToast = useCallback((message: string, type: Toast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, description }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 6000);
  }, []);

  // Network Status Monitor
  useEffect(() => {
    const handleOnline = () => showToast('Neural Link Restored', 'success', 'Back online. Mission data synchronized.');
    const handleOffline = () => showToast('Neural Link Severed', 'error', 'You are currently offline. Local cache active.');

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [showToast]);

  // Dynamic Theme Generation
  useEffect(() => {
    let css = '';
    (Object.entries(cms.themeDefinitions) as [string, ThemeConfig][]).forEach(([key, config]) => {
      css += `
        .theme-${key} {
          --bg: ${config.bg};
          --fg: ${config.fg};
          --primary: ${config.primary};
          --accent: ${config.accent};
          --card: ${config.card};
          --border: ${config.border};
          --font: '${config.font}';
          --shadow: ${config.shadow};
        }
      `;
    });

    let styleTag = document.getElementById('dynamic-themes');
    if (!styleTag) {
      styleTag = document.createElement('style');
      styleTag.id = 'dynamic-themes';
      document.head.appendChild(styleTag);
    }
    styleTag.innerHTML = css;

    localStorage.setItem('bfc_cms', JSON.stringify(cms));
  }, [cms]);

  useEffect(() => {
    localStorage.setItem('bfc_menu', JSON.stringify(menuItems));
  }, [menuItems]);

  const subtotal = cart.reduce((a, b) => a + (b.item.price * b.qty), 0);
  const delivery = cart.length > 0 ? 60 : 0;
  const total = Math.max(0, subtotal + delivery);

  const handleAuth = () => {
    if (!loginId) {
      return showToast('Identity Missing', 'error', 'Please enter your neural identity (email) to continue.');
    }
    if (!loginId.includes('@')) {
      return showToast('Identity Format Error', 'warning', 'Please enter a valid email address (e.g., name@bfc.elite).');
    }
    if (loginKey.length < 4) {
      return showToast('Access Key Too Short', 'warning', 'Neural pulse keys must be at least 4 characters long.');
    }

    const isAdmin = loginId.toLowerCase().includes('admin');
    const user: User = {
      id: isAdmin ? 'U-ADMIN' : 'U-' + Math.random().toString(36).slice(2, 7),
      name: isAdmin ? 'Elite Commander' : (isNewCustomer ? 'New Recruit' : 'Honored Guest'),
      email: loginId,
      role: isAdmin ? UserRole.ADMIN : UserRole.CUSTOMER,
      loyaltyPoints: isNewCustomer ? 0 : 2450,
      tier: isAdmin ? 'PLATINUM' : 'GOLD',
      claimedVouchers: []
    };
    setCurrentUser(user);
    isAdmin ? setView('ADMIN') : setView('HOME');
    showToast('Secure Link Established', 'success', `Welcome back, ${user.name}. Transmission is encrypted.`);
  };

  const processPayment = async () => {
    if (!selectedPayment) {
      return showToast('No Gateway Selected', 'warning', 'Please choose a secure payment gateway to finalize the manifest.');
    }

    if (!navigator.onLine) {
      return showToast('Logistics Offline', 'error', 'Cannot process payments without an active neural link. Please check your connection.');
    }

    setPaymentStep('PROCESSING');

    try {
      // Simulation of a possible gateway failure
      await new Promise((resolve, reject) => {
        setTimeout(() => {
          if (Math.random() < 0.05) reject(new Error('Neural sync timed out.'));
          else resolve(true);
        }, 2500);
      });

      setPaymentStep('SUCCESS');
      const newOrder: Order = {
        id: 'ORD-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
        customerId: currentUser?.id || 'GUEST',
        customerName: currentUser?.name || 'Guest',
        items: cart,
        total,
        status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(),
        paymentMethod: selectedPayment
      };
      setAllOrders(p => [newOrder, ...p]);
      setCart([]);
      showToast('Mission Success', 'success', 'Your payload is moving through our neural grid. Estimated arrival: 30-40 min.');
      setTimeout(() => { setPaymentStep('IDLE'); setView('HOME'); }, 3000);

    } catch (err: any) {
      setPaymentStep('ERROR');
      showToast('Gateway Interruption', 'error', err.message || 'The secure connection was interrupted. Please try again or choose another method.');
      setTimeout(() => setPaymentStep('SELECT'), 3000);
    }
  };

  const navBrandClass = useMemo(() => {
    return "text-lg lg:text-2xl font-black italic tracking-tighter uppercase";
  }, []);

  if (view === 'ADMIN' && currentUser?.role === UserRole.ADMIN) {
    return (
      <AdminPanel 
        cms={cms} setCms={setCms}
        menuItems={menuItems} setMenuItems={setMenuItems}
        orders={allOrders} setOrders={setAllOrders}
        onLogout={() => { setView('HOME'); setCurrentUser(null); }}
      />
    );
  }

  return (
    <div className={`themed-root theme-${cms.activeLayout}`}>
      {/* Dynamic Toast System */}
      <div className="fixed top-24 right-4 lg:right-10 z-[10000] space-y-4 pointer-events-none max-w-sm w-[calc(100vw-2rem)]">
        {toasts.map(t => (
          <div key={t.id} className={`pointer-events-auto themed-card p-6 rounded-[28px] animate-elite-up flex gap-5 items-start shadow-2xl backdrop-blur-3xl border ${
            t.type === 'error' ? 'border-red-600/30' : t.type === 'warning' ? 'border-amber-600/30' : 'border-white/10'
          }`}>
            <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 shadow-lg ${
              t.type === 'error' ? 'bg-red-600' : t.type === 'warning' ? 'bg-amber-600' : 'themed-primary'
            }`}>
              <i className={`fas ${t.type === 'error' ? 'fa-bolt' : t.type === 'warning' ? 'fa-triangle-exclamation' : 'fa-check-circle'} text-base`}></i>
            </div>
            <div className="flex-1 space-y-1">
              <h4 className="text-[12px] font-black uppercase tracking-widest">{t.message}</h4>
              {t.description && <p className="text-[10px] opacity-70 font-medium leading-relaxed">{t.description}</p>}
            </div>
            <button onClick={() => setToasts(prev => prev.filter(x => x.id !== t.id))} className="text-gray-400 hover:text-white transition-colors"><i className="fas fa-times text-xs"></i></button>
          </div>
        ))}
      </div>

      {/* Navigation - High Fidelity Glass */}
      <nav className="fixed top-0 inset-x-0 z-[5000] px-4 lg:px-12 py-5 flex justify-between items-center glass-nav border-b themed-border">
        <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 themed-primary rounded-xl flex items-center justify-center font-black text-lg transition-transform group-hover:rotate-6">B</div>
          <h1 className={`${navBrandClass} hidden sm:block`}>{cms.navigation.brand}</h1>
        </div>

        <div className="flex gap-2 sm:gap-6 items-center">
          <div className="hidden md:flex gap-8 mr-8">
            {['MENU', 'VAULT', 'HOME'].map(link => (
              <button key={link} onClick={() => setView(link as any)} className={`text-[10px] font-black uppercase tracking-[4px] transition-all hover:themed-text-primary ${view === link ? 'themed-text-primary' : 'opacity-40'}`}>
                {link}
              </button>
            ))}
          </div>

          <button onClick={() => setView('CART')} className="relative w-12 h-12 bg-white/5 themed-border border rounded-2xl flex items-center justify-center transition-all hover:scale-105 active:scale-95">
            <i className="fas fa-shopping-basket text-base"></i>
            {cart.length > 0 && <span className="absolute -top-2 -right-2 themed-primary text-white text-[9px] w-6 h-6 rounded-full flex items-center justify-center font-black border-2 border-[var(--bg)] animate-pulse">{cart.length}</span>}
          </button>

          <button onClick={() => setView('LOGIN')} className="w-12 h-12 themed-primary rounded-2xl flex items-center justify-center text-base shadow-xl hover:brightness-110 active:scale-95">
            <i className="fas fa-fingerprint"></i>
          </button>
        </div>
      </nav>

      <main className="pt-24 lg:pt-32 min-h-screen">
        {view === 'HOME' && (
          <div className="animate-fade-in space-y-20 lg:space-y-40 pb-40">
            <section className="relative h-[80vh] flex items-center px-6 lg:px-20 overflow-hidden rounded-[40px] lg:rounded-[80px] mx-4 lg:mx-10 shadow-3xl">
              <img src={cms.hero.image} className="absolute inset-0 w-full h-full object-cover opacity-40 scale-105" alt="BFC Hero" />
              <div className="absolute inset-0 bg-gradient-to-r from-[var(--bg)] via-[var(--bg)]/80 to-transparent"></div>
              <div className="relative z-10 max-w-4xl space-y-8 animate-elite-up">
                <p className="themed-text-primary font-black uppercase tracking-[12px] text-[10px] lg:text-sm">{cms.hero.subtitle}</p>
                <h2 className="text-4xl lg:text-9xl font-black leading-[1] tracking-tighter italic uppercase mobile-text-xl">{cms.hero.title}</h2>
                <p className="text-sm lg:text-2xl opacity-70 max-w-2xl font-medium leading-relaxed">{cms.hero.description}</p>
                <div className="pt-6 flex flex-col sm:flex-row gap-6">
                  <Button size="lg" className="rounded-3xl" onClick={() => setView('MENU')}>{cms.hero.cta}</Button>
                  <Button variant="outline" size="lg" className="rounded-3xl" onClick={() => setView('VAULT')}>VIEW WALLET</Button>
                </div>
              </div>
            </section>

            <section className="px-6 lg:px-20 space-y-12">
              <div className="flex justify-between items-end">
                <div className="space-y-4">
                  <h3 className="text-3xl lg:text-5xl font-black italic uppercase tracking-tighter">Top Registry Picks</h3>
                  <p className="text-[11px] font-black themed-text-primary uppercase tracking-[8px]">Highest Rated Units</p>
                </div>
                <button onClick={() => setView('MENU')} className="text-[10px] font-black uppercase tracking-[5px] opacity-40 hover:opacity-100 transition-opacity hidden sm:block">View Entire Menu —></button>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-10">
                {menuItems.slice(0, 3).map(item => (
                  <div key={item.id} className="themed-card p-6 lg:p-8 rounded-[48px] group hover:-translate-y-3 transition-all">
                    <div className="h-64 lg:h-80 rounded-[40px] overflow-hidden mb-8 relative shadow-2xl">
                      <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" alt={item.name} />
                      <div className="absolute top-6 left-6 themed-primary px-5 py-2 rounded-full text-[12px] font-black italic">৳{item.price}</div>
                    </div>
                    <h4 className="text-2xl lg:text-3xl font-black italic uppercase mb-2">{item.name}</h4>
                    <p className="text-[11px] font-black themed-text-primary uppercase tracking-widest mb-6">{item.nameBn}</p>
                    <div className="flex justify-between items-center border-t themed-border pt-6">
                      <div className="flex items-center gap-2">
                        <i className="fas fa-star text-amber-500 text-xs"></i>
                        <span className="text-xs font-black">4.9</span>
