        )}

        {view === 'MENU' && (
          <div className="p-6 lg:p-20 max-w-7xl mx-auto space-y-20 animate-elite-up pb-40">
            <div className="text-center space-y-4">
              <h2 className="text-5xl lg:text-8xl font-black italic uppercase tracking-tighter">The Neural Menu</h2>
              <p className="text-[12px] font-black opacity-40 uppercase tracking-[10px]">Registry version 4.0.2</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10 lg:gap-14">
              {menuItems.map(item => (
                <div key={item.id} className="themed-card p-6 lg:p-10 rounded-[56px] group hover:scale-[1.02] transition-all">
                  <div className="h-64 lg:h-80 rounded-[44px] overflow-hidden mb-10 relative">
                    <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt={item.name} />
                    <div className="absolute top-5 right-5 themed-primary px-6 py-2 rounded-full text-[11px] font-black italic shadow-xl">৳{item.price}</div>
