                  <h4 className="text-2xl lg:text-3xl font-black italic uppercase mb-1 leading-none">{item.name}</h4>
                  <p className="text-[11px] font-black themed-text-primary uppercase mb-8 tracking-widest leading-none">{item.nameBn}</p>
