const CACHE_NAME = 'bfc-v7-elite';
const STATIC_CACHE = 'bfc-static-v1';
const IMAGE_CACHE = 'bfc-images-v1';

const STATIC_ASSETS = [
  '/',
  '/index.html',
  '/manifest.json',
  '/index.tsx',
  'https://cdn.tailwindcss.com',
  'https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css',
  'https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&family=Hind+Siliguri:wght@400;700&family=JetBrains+Mono:wght@400;700&family=Playfair+Display:ital,wght@0,900;1,900&display=swap'
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    Promise.all([
      caches.open(STATIC_CACHE).then((cache) => cache.addAll(STATIC_ASSETS)),
      caches.open(CACHE_NAME)
    ])
  );
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => {
      return Promise.all(
        keys.map((key) => {
          if (![STATIC_CACHE, CACHE_NAME, IMAGE_CACHE].includes(key)) {
            return caches.delete(key);
          }
        })
      );
    })
  );
  return self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);

  // Skip Gemini API and other non-get requests
  if (url.hostname.includes('generativelanguage.googleapis.com') || request.method !== 'GET') {
    return;
  }

  // Strategy: Cache-First for Fonts and Scripts
  if (request.destination === 'font' || request.destination === 'script' || STATIC_ASSETS.includes(url.pathname)) {
    event.respondWith(
      caches.match(request).then((cached) => {
        return cached || fetch(request).then((response) => {
          const resClone = response.clone();
          caches.open(STATIC_CACHE).then((cache) => cache.put(request, resClone));
          return response;
        });
      })
    );
    return;
  }

  // Strategy: Cache with Network Fallback for Images
  if (request.destination === 'image' || url.hostname.includes('unsplash.com')) {
    event.respondWith(
      caches.match(request).then((cached) => {
        return cached || fetch(request).then((response) => {
          const resClone = response.clone();
          caches.open(IMAGE_CACHE).then((cache) => cache.put(request, resClone));
          return response;
        }).catch(() => caches.match('https://img.icons8.com/color/512/000000/hamburger.png'));
      })
    );
    return;
  }

  // Strategy: Network-First with Cache Fallback for HTML/Navigation
  event.respondWith(
    fetch(request)
      .then((response) => {
        if (response.status === 200) {
          const resClone = response.clone();
          caches.open(CACHE_NAME).then((cache) => cache.put(request, resClone));
        }
        return response;
      })
      .catch(() => {
        return caches.match(request).then((cached) => {
          if (cached) return cached;
          if (request.mode === 'navigate') return caches.match('/index.html');
          return null;
        });
      })
  );
});

