      </div>

      {/* Global Toast Monitor */}
      <div className={`fixed ${isOffline ? 'top-16' : 'top-8'} right-4 lg:right-10 z-[10000] space-y-4 pointer-events-none max-w-sm w-[calc(100vw-2rem)] transition-all duration-500`}>
        {toasts.map(t => (
          <div key={t.id} className={`pointer-events-auto themed-card p-6 rounded-[32px] animate-elite-up flex gap-5 items-start shadow-2xl backdrop-blur-3xl border border-white/10`}>
            <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 shadow-lg ${t.type === 'error' ? 'bg-red-600' : t.type === 'warning' ? 'bg-amber-600' : 'themed-primary'}`}>
              <i className={`fas ${t.type === 'error' ? 'fa-bolt' : t.type === 'warning' ? 'fa-exclamation-triangle' : 'fa-check-circle'} text-base text-white`}></i>
            </div>
