                     className={`p-6 rounded-[40px] border-2 transition-all flex flex-col items-center gap-6 text-center group relative overflow-hidden ${cms.activeLayout === l.id ? 'themed-primary border-transparent shadow-2xl scale-105 z-10' : 'themed-card themed-border hover:themed-border active:scale-95'}`}
                   >
                      <div className={`w-16 h-16 rounded-[24px] shadow-2xl ring-4 ring-white/10 group-hover:rotate-12 transition-all duration-500`} style={{backgroundColor: cms.themeDefinitions[l.id].bg}}></div>
                      <div className="space-y-1">
                        <span className="text-[10px] font-black uppercase tracking-[2px] block">{l.name}</span>
