                          <span className="text-[7px] font-black uppercase tracking-widest opacity-50">Previewing</span>
                        </div>
                      )}
                   </button>
                 ))}
               </div>

               <div className="space-y-6">
                  <div className="flex items-center gap-3 px-4">
                    <i className="fas fa-desktop text-xs opacity-30"></i>
                    <h4 className="text-[11px] font-black uppercase tracking-[5px] opacity-40">Neural Theme Preview</h4>
                  </div>
                  <ThemePreviewMonitor 
                    theme={cms.themeDefinitions[currentPreviewTheme]} 
                    cms={cms}
                  />
                  <div className="p-6 themed-card rounded-[32px] space-y-4 border-dashed border-2">
                    <div className="flex items-center gap-2">
                      <i className="fas fa-info-circle themed-text-primary text-[10px]"></i>
                      <span className="text-[9px] font-black uppercase tracking-widest opacity-60 italic">Live Simulation Mode</span>
                    </div>
                    <p className="text-[10px] font-medium leading-relaxed opacity-40">Hover over any preset on the left to instantly update this simulation cluster with the corresponding neural color patterns.</p>
                  </div>
               </div>
            </div>

            {customizingTheme && (
              <section className="themed-card p-10 lg:p-16 rounded-[64px] space-y-12 border-white/5 animate-elite-up mt-12">
                 <div className="flex flex-col lg:flex-row justify-between items-center gap-8 border-b themed-border pb-8">
                    <div className="space-y-2 text-center lg:text-left">
                       <h3 className="text-3xl font-black italic uppercase leading-none">Variables: {customizingTheme}</h3>
                       <p className="text-[10px] font-black uppercase tracking-[5px] opacity-40">Modify core CSS properties for this cluster</p>
                    </div>
                    <Button onClick={() => {
                        const defaultTheme = DEFAULT_THEMES[customizingTheme];
                        if (defaultTheme) {
                           const newDefs = { ...cms.themeDefinitions };
                           newDefs[customizingTheme] = { ...defaultTheme };
                           setCms({ ...cms, themeDefinitions: newDefs });
                           showToast('Variables Reset', 'info', `Standard ${customizingTheme} values restored.`);
                        }
                    }} variant="outline" className="rounded-xl py-4">RESET TO DEFAULTS</Button>
                 </div>

                 <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
                    <VariableField label="Primary Color" value={cms.themeDefinitions[customizingTheme].primary} onChange={(v: string) => updateThemeVariable(customizingTheme, 'primary', v)} />
                    <VariableField label="Background" value={cms.themeDefinitions[customizingTheme].bg} onChange={(v: string) => updateThemeVariable(customizingTheme, 'bg', v)} />
                    <VariableField label="Foreground" value={cms.themeDefinitions[customizingTheme].fg} onChange={(v: string) => updateThemeVariable(customizingTheme, 'fg', v)} />
                    <VariableField label="Card Color" value={cms.themeDefinitions[customizingTheme].card} onChange={(v: string) => updateThemeVariable(customizingTheme, 'card', v)} />
                    <VariableField label="Border Color" value={cms.themeDefinitions[customizingTheme].border} onChange={(v: string) => updateThemeVariable(customizingTheme, 'border', v)} />
                    <VariableField label="Accent Color" value={cms.themeDefinitions[customizingTheme].accent} onChange={(v: string) => updateThemeVariable(customizingTheme, 'accent', v)} />
                    <VariableField label="Font Family" value={cms.themeDefinitions[customizingTheme].font} onChange={(v: string) => updateThemeVariable(customizingTheme, 'font', v)} />
                    <VariableField label="Shadow Definition" value={cms.themeDefinitions[customizingTheme].shadow} onChange={(v: string) => updateThemeVariable(customizingTheme, 'shadow', v)} />
                 </div>
              </section>
            )}
          </div>
        )}

        {tab === 'PROMOTIONS' && (
          <div className="space-y-16 animate-elite-up pb-20 max-w-7xl mx-auto">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-8">
               <div className="space-y-2">
                 <h2 className="text-4xl lg:text-7xl font-black italic uppercase tracking-tighter leading-none">Promotion Hub</h2>
                 <p className="text-[11px] font-black uppercase tracking-[10px] opacity-40">Discount Strategy & Campaigns</p>
               </div>
               <Button size="lg" className="rounded-[28px] py-8" onClick={openAddPromo}>DEPLOY NEW PROMO</Button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
              {promotions.map(promo => {
                const isExpired = new Date(promo.endDate) < new Date();
                const isLimitReached = promo.usageCount >= promo.usageLimit;
                const status = !promo.isActive ? 'INACTIVE' : isExpired ? 'EXPIRED' : isLimitReached ? 'LIMIT REACHED' : 'ACTIVE';
                const usagePercent = Math.min(100, (promo.usageCount / promo.usageLimit) * 100);

                return (
                  <div key={promo.id} className="themed-card p-10 rounded-[56px] space-y-8 relative overflow-hidden group border-white/5 shadow-2xl hover:themed-border transition-all">
                    <div className="absolute top-0 right-0 w-32 h-32 themed-primary/5 blur-[60px]"></div>
                    <div className="flex justify-between items-start">
                      <div className="space-y-2">
                        <h4 className="text-2xl font-black italic uppercase leading-none">{promo.name}</h4>
                        <p className="text-[10px] font-black themed-text-primary uppercase tracking-[4px]">{promo.code}</p>
                      </div>
                      <div className={`px-3 py-1 rounded-full text-[8px] font-black tracking-widest ${
                        status === 'ACTIVE' ? 'bg-emerald-500/20 text-emerald-500' : 'bg-red-500/20 text-red-500'
                      }`}>
                        {status}
                      </div>
                    </div>

                    <div className="space-y-4">
                      <div className="grid grid-cols-2 gap-6 pt-6 border-t themed-border">
                        <div>
                          <p className="text-[8px] font-black uppercase opacity-40 tracking-widest mb-1">Value</p>
                          <p className="text-xl font-black italic">{promo.discountType === 'PERCENTAGE' ? `${promo.discountValue}%` : `৳${promo.discountValue}`}</p>
                        </div>
                        <div>
                          <p className="text-[8px] font-black uppercase opacity-40 tracking-widest mb-1">Utilization</p>
                          <div className="flex items-center gap-2">
                            <p className="text-xl font-black italic">{promo.usageCount}</p>
                            <span className="text-[10px] opacity-30">/ {promo.usageLimit}</span>
                          </div>
                        </div>
                      </div>
                      <div className="w-full h-1.5 bg-white/5 rounded-full overflow-hidden">
                        <div 
                          className={`h-full transition-all duration-1000 ${usagePercent > 90 ? 'bg-red-500' : 'themed-primary'}`} 
                          style={{ width: `${usagePercent}%` }}
                        ></div>
                      </div>
                    </div>

                    <div className="flex justify-between items-end gap-4">
                      <div className="space-y-1">
                        <p className="text-[8px] font-black uppercase opacity-40 tracking-widest">Active Cycle</p>
                        <p className="text-[10px] font-black uppercase tracking-tighter">{new Date(promo.startDate).toLocaleDateString()} — {new Date(promo.endDate).toLocaleDateString()}</p>
                      </div>
                      <div className="flex gap-2">
                        <button onClick={() => openEditPromo(promo)} className="w-10 h-10 bg-white/5 rounded-xl flex items-center justify-center hover:themed-primary transition-all group/btn" title="Edit Promotion">
                          <i className="fas fa-edit text-xs opacity-40 group-hover/btn:opacity-100"></i>
                        </button>
                        <button onClick={() => deletePromotion(promo.id)} className="w-10 h-10 bg-red-600/10 rounded-xl flex items-center justify-center hover:bg-red-600 transition-all group/btn" title="Delete Promotion">
                          <i className="fas fa-trash text-xs text-red-600 group-hover/btn:text-white"></i>
                        </button>
                      </div>
                    </div>
                  </div>
                );
              })}
              {promotions.length === 0 && (
                <div className="col-span-full py-40 text-center opacity-20 space-y-6">
                   <i className="fas fa-ticket text-7xl"></i>
                   <p className="text-xl font-black uppercase tracking-[15px]">No Campaigns Active</p>
                </div>
              )}
            </div>

            {isPromoModalOpen && (
              <div className="fixed inset-0 z-[10000] glass-nav p-6 lg:p-20 overflow-y-auto flex items-center justify-center">
                 <form onSubmit={savePromotion} className="themed-card p-10 lg:p-20 rounded-[72px] w-full max-w-3xl space-y-12 relative shadow-[0_50px_100px_-20px_rgba(0,0,0,0.5)] border-white/10">
                    <button type="button" onClick={() => setIsPromoModalOpen(false)} className="absolute top-12 right-12 w-12 h-12 rounded-full hover:bg-white/5 flex items-center justify-center text-xl"><i className="fas fa-times"></i></button>
                    <div className="space-y-4">
                      <h3 className="text-4xl lg:text-6xl font-black italic uppercase tracking-tighter leading-none">{editingPromoId ? 'Update Campaign' : 'New Campaign'}</h3>
                      <p className="text-[10px] font-black opacity-30 uppercase tracking-[8px]">Promotion Configuration Protocol</p>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
                       <InputField label="Campaign Name" value={promoForm.name} onChange={(v: string) => setPromoForm({...promoForm, name: v})} placeholder="e.g. SUMMER FEAST" />
                       <div className="space-y-3">
                         <label className="text-[11px] font-black uppercase tracking-[5px] opacity-40 ml-6">Unique Code</label>
                         <div className="flex gap-4">
                           <input 
                             value={promoForm.code} 
                             onChange={e => setPromoForm({...promoForm, code: e.target.value.toUpperCase()})}
                             className="flex-1 bg-white/5 themed-border border p-6 rounded-[32px] outline-none font-black text-xs uppercase focus:themed-primary/20 focus:themed-border transition-all" 
                             placeholder="AUTO-GENERATED"
                           />
                           {!editingPromoId && (
                             <button type="button" onClick={generateUniqueCode} className="w-16 h-16 themed-primary rounded-3xl flex items-center justify-center text-xl shadow-xl hover:rotate-180 transition-all duration-500">
                               <i className="fas fa-arrows-rotate"></i>
                             </button>
                           )}
                         </div>
                       </div>

