                           <option value="PERCENTAGE">Percentage (%)</option>
                           <option value="FIXED">Fixed Amount (৳)</option>
                         </select>
                       </div>
                       <InputField label="Discount Value" value={String(promoForm.discountValue)} onChange={(v: string) => setPromoForm({...promoForm, discountValue: Number(v)})} type="number" />

                       <InputField label="Start Date" value={promoForm.startDate} onChange={(v: string) => setPromoForm({...promoForm, startDate: v})} type="date" />
                       <InputField label="End Date" value={promoForm.endDate} onChange={(v: string) => setPromoForm({...promoForm, endDate: v})} type="date" />

