import React, { useState, useRef, useEffect, useCallback } from 'react';
import { decodeAudio, decodeAudioData, encodeAudio, getAiInstance, bfcFastText } from '../services/geminiService';
import { ChatMessage, User } from '../types';
import { Modality, LiveServerMessage } from '@google/genai';
import { MOCK_MENU } from '../constants';

const menuContext = MOCK_MENU.map(i => 
  `- ${i.name}: ${i.price}tk. ${i.category}. ${i.isPopular ? 'Popular' : ''}`
).join("\n");

interface ChatBotProps {
  isOnline?: boolean;
  currentUser?: User | null;
}

export const ChatBot: React.FC<ChatBotProps> = ({ isOnline = true, currentUser }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([{ role: 'model', text: "স্বাগতম! বিএফসি এলিট সার্ভিস থেকে আমি আপনাকে কীভাবে সাহায্য করতে পারি?", timestamp: new Date() }]);
  const [input, setInput] = useState('');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [currentTranscription, setCurrentTranscription] = useState('');
  const [isMicOn, setIsMicOn] = useState(false);

  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const scrollRef = useRef<HTMLDivElement>(null);
  const micStreamRef = useRef<MediaStream | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const transcriptionRef = useRef('');

  const stopAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setIsSpeaking(false);
  };

  const initAudioOutput = async () => {
    if (!outputAudioContextRef.current) {
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    if (outputAudioContextRef.current.state === 'suspended') await outputAudioContextRef.current.resume();
  };

  const connectLive = useCallback(async () => {
    if (!isOnline || sessionPromiseRef.current) return;
    await initAudioOutput();
    const ai = getAiInstance();

    try {
      sessionPromiseRef.current = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsLiveActive(true);
            console.log("⚡ BFC Neural Link Synchronized");
          },
          onmessage: async (msg: LiveServerMessage) => {
            const audioData = msg.serverContent?.modelTurn?.parts?.find(p => p.inlineData)?.inlineData?.data;
            if (audioData && outputAudioContextRef.current) {
              setIsSpeaking(true);
              const ctx = outputAudioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);

              const buffer = await decodeAudioData(decodeAudio(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              };
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }

            if (msg.serverContent?.outputTranscription) {
              const text = msg.serverContent.outputTranscription.text;
              transcriptionRef.current += text;
              setCurrentTranscription(transcriptionRef.current);
            }

            if (msg.serverContent?.turnComplete) {
              setMessages(prev => {
                const final = transcriptionRef.current || "...";
                return [...prev, { role: 'model', text: final, timestamp: new Date() }];
              });
              transcriptionRef.current = '';
              setCurrentTranscription('');
            }

            if (msg.serverContent?.interrupted) stopAudio();
          },
          onerror: (e) => console.error("Link Failure", e),
          onclose: () => {
            setIsLiveActive(false);
            sessionPromiseRef.current = null;
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          outputAudioTranscription: {},
          speechConfig: { 
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          },
          systemInstruction: `You are BFC Assist, a lightning-fast elite concierge. Respond in Bengali. Keep answers very short and snappy. User: ${currentUser?.name || 'Guest'}.`
        }
      });
    } catch (e) {
      console.error("Connection failed", e);
    }
  }, [isOnline, currentUser]);

  const handleSend = async () => {
    const text = input.trim();
    if (!text) return;

    stopAudio();
    setMessages(prev => [...prev, { role: 'user', text, timestamp: new Date() }]);
    setInput('');
    setIsLoading(true);

    if (sessionPromiseRef.current) {
      sessionPromiseRef.current.then((session) => {
        session.sendRealtimeInput({ message: { parts: [{ text }] } });
        setIsLoading(false);
      });
    } else {
      const aiResponse = await bfcFastText(text, currentUser?.name);
      setMessages(prev => [...prev, { role: 'model', text: aiResponse, timestamp: new Date() }]);
      setIsLoading(false);
    }
  };

  const toggleMic = async () => {
    if (!sessionPromiseRef.current) await connectLive();

    if (isMicOn) {
      if (micStreamRef.current) micStreamRef.current.getTracks().forEach(t => t.stop());
      setIsMicOn(false);
      return;
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;
      setIsMicOn(true);

      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      inputAudioContextRef.current = ctx;
      const source = ctx.createMediaStreamSource(stream);
      const processor = ctx.createScriptProcessor(4096, 1, 1);

      processor.onaudioprocess = (e) => {
        const inputData = e.inputBuffer.getChannelData(0);
        const int16 = new Int16Array(inputData.length);
        for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;

        sessionPromiseRef.current?.then((session) => {
          session.sendRealtimeInput({
            media: { 
              data: encodeAudio(new Uint8Array(int16.buffer)), 
              mimeType: 'audio/pcm;rate=16000' 
            }
          });
        });
      };

      source.connect(processor);
      processor.connect(ctx.destination);
    } catch (e) {
      setIsMicOn(false);
    }
  };

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages, currentTranscription]);

  return (
    <div className="fixed bottom-32 right-6 lg:bottom-12 lg:right-12 z-[10000]">
      {isOpen ? (
        <div className="bg-gray-900/95 backdrop-blur-3xl w-[85vw] sm:w-[350px] h-[60vh] sm:h-[500px] rounded-[48px] shadow-[0_50px_100px_-20px_rgba(220,38,38,0.5)] flex flex-col border border-white/10 overflow-hidden animate-elite-up">
          <div className="themed-primary p-6 text-white flex justify-between items-center shrink-0 shadow-lg">
            <div className="flex items-center gap-4">
               <div className={`w-10 h-10 rounded-2xl flex items-center justify-center bg-white/20 ${isSpeaking ? 'animate-pulse' : ''}`}>
                  <i className={`fas ${isSpeaking ? 'fa-volume-high' : 'fa-bolt-lightning'} text-sm`}></i>
               </div>
               <div>
                 <span className="text-[10px] font-black uppercase tracking-[3px] italic block leading-none mb-1">BFC ASSIST</span>
                 <span className="text-[7px] font-bold opacity-60 uppercase tracking-widest leading-none">Status: Ultra-Fast</span>
               </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="w-10 h-10 bg-white/10 rounded-2xl flex items-center justify-center hover:bg-white/20 transition-all">
              <i className="fas fa-times text-xs"></i>
            </button>
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar bg-black/20">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-elite-up`}>
                <div className={`max-w-[85%] px-5 py-4 rounded-[28px] text-[11px] font-black leading-relaxed shadow-xl ${m.role === 'user' ? 'bg-red-600 text-white' : 'bg-gray-800 text-gray-100 border border-white/5'}`}>
                  {m.text}
                </div>
              </div>
            ))}
            {currentTranscription && (
              <div className="flex justify-start">
                <div className="max-w-[85%] px-5 py-3 rounded-[24px] text-[11px] font-black bg-gray-800/50 text-emerald-400 border border-emerald-500/20 animate-pulse italic">
                  {currentTranscription}
                </div>
              </div>
            )}
            {isLoading && (
              <div className="flex justify-start pl-4">
                <div className="flex gap-2">
                  <span className="w-2 h-2 bg-red-600 rounded-full animate-bounce"></span>
                  <span className="w-2 h-2 bg-red-600 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                  <span className="w-2 h-2 bg-red-600 rounded-full animate-bounce [animation-delay:0.4s]"></span>
                </div>
              </div>
            )}
          </div>

          <div className="p-5 bg-gray-900 border-t border-white/5 flex gap-4 shrink-0">
            <button onClick={toggleMic} className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all ${isMicOn ? 'bg-red-600 text-white animate-pulse shadow-red-600/40' : 'bg-white/5 text-gray-400 hover:text-red-500'}`}>
              <i className={`fas ${isMicOn ? 'fa-microphone' : 'fa-microphone-slash'} text-lg`}></i>
            </button>
            <div className="flex-1 flex items-center bg-white/5 rounded-[28px] p-1 pr-3">
              <input 
                type="text" value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSend()}
                placeholder="একটি প্রশ্নের উত্তর জানতে লিখুন..."
                className="flex-1 bg-transparent border-none px-5 outline-none text-xs font-black text-white placeholder:opacity-30"
              />
              <button onClick={handleSend} className="w-12 h-12 bg-red-600 text-white rounded-2xl flex items-center justify-center shadow-lg active:scale-90 hover:brightness-110">
                <i className="fas fa-paper-plane text-xs"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button onClick={() => setIsOpen(true)} className="w-20 h-20 bg-red-600 text-white rounded-[32px] shadow-[0_25px_60px_rgba(220,38,38,0.6)] flex flex-col items-center justify-center hover:scale-110 active:scale-95 transition-all group pulse-primary border-2 border-white/20">
           <i className="fas fa-bolt-lightning text-3xl mb-1 group-hover:animate-bounce"></i>
           <span className="text-[7px] font-black uppercase tracking-widest opacity-60">Assist</span>
           {isSpeaking && <span className="absolute -top-1 -right-1 flex h-4 w-4"><span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span><span className="relative inline-flex rounded-full h-4 w-4 bg-emerald-500 shadow-lg"></span></span>}
        </button>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem, SiteCMS, ThemeConfig, LayoutPreset } from './types';
import { MOCK_MENU, MOCK_ORDERS, DEFAULT_THEMES } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  id: number;
  message: string;
  description?: string;
  type: 'success' | 'error' | 'warning' | 'info';
}

const DEFAULT_CMS: SiteCMS = {
  activeLayout: 'ELITE_DARK',
  themeDefinitions: DEFAULT_THEMES,
  hero: {
    title: "THE ULTIMATE TASTE OF BANGLADESH",
    subtitle: "ESTABLISHED 1999 • ELITE REGISTRY",
    description: "Experience the pinnacle of culinary excellence. Our neural logistics network ensures your feast arrives with absolute precision.",
    image: "https://images.unsplash.com/photo-1633945274405-b6c8069047b0?q=80&w=2000",
    cta: "EXPLORE REGISTRY"
  },
  navigation: {
    brand: "BFC ELITE",
    links: { home: "HOME", menu: "MENU", vault: "VAULT", profile: "PROFILE" }
  },
  vault: {
    title: "RIBOT WALLET",
    description: "Your secure vault for loyalty credits and exclusive BFC rewards. Every pulse counts towards your status."
  }
};

const App: React.FC = () => {
  const [cms, setCms] = useState<SiteCMS>(() => {
    const saved = localStorage.getItem('bfc_cms');
    return saved ? JSON.parse(saved) : DEFAULT_CMS;
  });

  const [menuItems, setMenuItems] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('bfc_menu');
    return saved ? JSON.parse(saved) : MOCK_MENU;
  });

  const [allOrders, setAllOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('bfc_orders');
    return saved ? JSON.parse(saved) : MOCK_ORDERS;
  });

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('bfc_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT'>('HOME');
  const [paymentStep, setPaymentStep] = useState<'IDLE' | 'SELECT' | 'PROCESSING' | 'SUCCESS' | 'ERROR'>('IDLE');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [selectedPayment, setSelectedPayment] = useState('');
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  const [loginId, setLoginId] = useState('');
  const [loginKey, setLoginKey] = useState('');
  const [isNewCustomer, setIsNewCustomer] = useState(false);

  const showToast = useCallback((message: string, type: Toast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, description }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 6000);
  }, []);

  useEffect(() => {
    const handleOnline = () => {
      setIsOffline(false);
      showToast('Neural Link Restored', 'success', 'Back online. Mission data synchronized.');
    };
    const handleOffline = () => {
      setIsOffline(true);
      showToast('Neural Link Severed', 'error', 'You are currently offline. Local cache active.');
    };

    const handleBeforeInstallPrompt = (e: any) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    };
  }, [showToast]);

  useEffect(() => { localStorage.setItem('bfc_cms', JSON.stringify(cms)); }, [cms]);
  useEffect(() => { localStorage.setItem('bfc_menu', JSON.stringify(menuItems)); }, [menuItems]);
  useEffect(() => { localStorage.setItem('bfc_orders', JSON.stringify(allOrders)); }, [allOrders]);
  useEffect(() => { localStorage.setItem('bfc_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { localStorage.setItem('bfc_user', JSON.stringify(currentUser)); }, [currentUser]);

  const subtotal = cart.reduce((a, b) => a + (b.item.price * b.qty), 0);
  const delivery = cart.length > 0 ? 60 : 0;
  const total = Math.max(0, subtotal + delivery);

  const installApp = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    if (outcome === 'accepted') {
      showToast('App Installed', 'success', 'BFC Elite has been added to your device registry.');
    }
    setDeferredPrompt(null);
  };

  const handleAuth = () => {
    if (!loginId) return showToast('Identity Missing', 'error', 'Email identification required.');
    if (!loginId.includes('@')) return showToast('Invalid Identity', 'warning', 'Please enter a valid neural address (email).');

    const isAdmin = loginId.toLowerCase().includes('admin');
    const user: User = {
      id: isAdmin ? 'U-ADMIN' : 'U-' + Math.random().toString(36).slice(2, 7),
      name: isAdmin ? 'Elite Commander' : (isNewCustomer ? 'New Recruit' : 'Honored Guest'),
      email: loginId,
      role: isAdmin ? UserRole.ADMIN : UserRole.CUSTOMER,
      loyaltyPoints: 2450,
      tier: 'PLATINUM',
      claimedVouchers: []
    };
    setCurrentUser(user);
    isAdmin ? setView('ADMIN') : setView('HOME');
    showToast('Link Established', 'success', `Welcome, ${user.name}.`);
  };

  const processPayment = async () => {
    if (!selectedPayment) return showToast('Payment Method Required', 'warning', 'Select a gateway to continue.');
    if (isOffline) return showToast('Link Required', 'error', 'Secure payment requires an active neural connection.');

    setPaymentStep('PROCESSING');
    try {
      await new Promise(r => setTimeout(r, 2000));
      const newOrder: Order = {
        id: 'ORD-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
        customerId: currentUser?.id || 'GUEST',
        customerName: currentUser?.name || 'Guest',
        items: [...cart],
        total,
        status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(),
        paymentMethod: selectedPayment
      };
      setAllOrders(p => [newOrder, ...p]);
      setCart([]);
      setPaymentStep('SUCCESS');
      showToast('Mission Success', 'success', 'Your payload is in the logistics queue.');
      setTimeout(() => { setPaymentStep('IDLE'); setView('HOME'); }, 3000);
    } catch (err) {
      setPaymentStep('ERROR');
      showToast('Gateway Failure', 'error', 'Transmission error during payment sync.');
    }
  };

  if (view === 'ADMIN' && currentUser?.role === UserRole.ADMIN) {
    return (
      <AdminPanel 
        cms={cms} setCms={setCms}
        menuItems={menuItems} setMenuItems={setMenuItems}
        orders={allOrders} setOrders={setAllOrders}
        onLogout={() => { setView('HOME'); setCurrentUser(null); }}
      />
    );
  }

  return (
