import React, { useState, useRef, useEffect, useCallback } from 'react';
import { decodeAudio, decodeAudioData, encodeAudio, getAiInstance, bfcFastText } from '../services/geminiService';
import { ChatMessage, User } from '../types';
import { Modality, LiveServerMessage } from '@google/genai';
import { MOCK_MENU } from '../constants';

const menuContext = MOCK_MENU.map(i => 
  `- ${i.name} (৳${i.price}): ${i.description}. ${i.isPopular ? 'Highly Popular' : ''}`
).join("\n");

interface ChatBotProps {
  isOnline?: boolean;
  currentUser?: User | null;
  setView: (view: any) => void;
}

export const ChatBot: React.FC<ChatBotProps> = ({ isOnline = true, currentUser, setView }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([{ role: 'model', text: "স্বাগতম! বিএফসি এলিট সার্ভিস থেকে আমি আপনাকে খাবার এবং মেনু সম্পর্কে কীভাবে সাহায্য করতে পারি?", timestamp: new Date() }]);
  const [input, setInput] = useState('');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [currentTranscription, setCurrentTranscription] = useState('');
  const [isMicOn, setIsMicOn] = useState(false);

  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const scrollRef = useRef<HTMLDivElement>(null);
  const micStreamRef = useRef<MediaStream | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const transcriptionRef = useRef('');

  const stopAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setIsSpeaking(false);
  };

  const initAudioOutput = async () => {
    if (!outputAudioContextRef.current) {
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    if (outputAudioContextRef.current.state === 'suspended') await outputAudioContextRef.current.resume();
  };

  const connectLive = useCallback(async () => {
    if (!isOnline || sessionPromiseRef.current) return;
    await initAudioOutput();
    const ai = getAiInstance();

    try {
      sessionPromiseRef.current = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsLiveActive(true);
            console.log("⚡ BFC Neural Link Synchronized");
          },
          onmessage: async (msg: LiveServerMessage) => {
            const audioData = msg.serverContent?.modelTurn?.parts?.find(p => p.inlineData)?.inlineData?.data;
            if (audioData && outputAudioContextRef.current) {
              setIsSpeaking(true);
              const ctx = outputAudioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);

              const buffer = await decodeAudioData(decodeAudio(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              };
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }

            if (msg.serverContent?.outputTranscription) {
              const text = msg.serverContent.outputTranscription.text;
              transcriptionRef.current += text;
              setCurrentTranscription(transcriptionRef.current);
            }

            if (msg.serverContent?.turnComplete) {
              const final = transcriptionRef.current || "...";
              setMessages(prev => [...prev, { role: 'model', text: final, timestamp: new Date() }]);
              transcriptionRef.current = '';
              setCurrentTranscription('');

              // Automated Payment Navigation Check
              if (final.toLowerCase().includes('payment') || final.toLowerCase().includes('পেমেন্ট') || final.toLowerCase().includes('checkout')) {
                setTimeout(() => setView('CART'), 2000);
              }
            }

            if (msg.serverContent?.interrupted) stopAudio();
          },
          onerror: (e) => console.error("Link Failure", e),
          onclose: () => {
            setIsLiveActive(false);
            sessionPromiseRef.current = null;
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          outputAudioTranscription: {},
          speechConfig: { 
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          },
          systemInstruction: `You are BFC Assist, the elite AI for BFC Restaurant. 
RESTRICTION: You ONLY talk about BFC menu, food items, prices, and orders. DO NOT discuss other topics.
MENU:
${menuContext}

GOAL: Help users find food, tell them prices/stocks, and guide them to pay.
If the user wants to pay or finish order, tell them you are taking them to the Payment/Cart section and remind them to ensure correct payment details. Respond in concise Bengali. Respond very fast.`
        }
      });
    } catch (e) {
      console.error("Connection failed", e);
    }
  }, [isOnline, currentUser, setView]);

  const handleSend = async () => {
    const text = input.trim();
    if (!text) return;

    stopAudio();
    setMessages(prev => [...prev, { role: 'user', text, timestamp: new Date() }]);
    setInput('');
    setIsLoading(true);

    if (sessionPromiseRef.current) {
      sessionPromiseRef.current.then((session) => {
        session.sendRealtimeInput({ message: { parts: [{ text }] } });
        setIsLoading(false);
      });
    } else {
      const aiResponse = await bfcFastText(text, currentUser?.name);
      setMessages(prev => [...prev, { role: 'model', text: aiResponse, timestamp: new Date() }]);
      setIsLoading(false);

      if (aiResponse.toLowerCase().includes('payment') || aiResponse.toLowerCase().includes('পেমেন্ট')) {
        setTimeout(() => setView('CART'), 2000);
      }
    }
  };

  const toggleMic = async () => {
    if (!sessionPromiseRef.current) await connectLive();

    if (isMicOn) {
      if (micStreamRef.current) micStreamRef.current.getTracks().forEach(t => t.stop());
      setIsMicOn(false);
      return;
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;
      setIsMicOn(true);

      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      inputAudioContextRef.current = ctx;
      const source = ctx.createMediaStreamSource(stream);
      const processor = ctx.createScriptProcessor(4096, 1, 1);

      processor.onaudioprocess = (e) => {
        const inputData = e.inputBuffer.getChannelData(0);
        const int16 = new Int16Array(inputData.length);
        for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;

        sessionPromiseRef.current?.then((session) => {
          session.sendRealtimeInput({
            media: { 
              data: encodeAudio(new Uint8Array(int16.buffer)), 
              mimeType: 'audio/pcm;rate=16000' 
            }
          });
        });
      };

      source.connect(processor);
      processor.connect(ctx.destination);
    } catch (e) {
      setIsMicOn(false);
    }
  };

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages, currentTranscription]);

  return (
    <div className="fixed bottom-36 right-6 lg:bottom-12 lg:right-12 z-[10000]">
      {isOpen ? (
        <div className="bg-gray-900/95 backdrop-blur-3xl w-[85vw] sm:w-[350px] h-[60vh] sm:h-[500px] rounded-[48px] shadow-[0_50px_100px_-20px_rgba(220,38,38,0.5)] flex flex-col border border-white/10 overflow-hidden animate-elite-up">
          <div className="themed-primary p-6 text-white flex justify-between items-center shrink-0 shadow-lg">
            <div className="flex items-center gap-4">
               <div className={`w-10 h-10 rounded-2xl flex items-center justify-center bg-white/20 ${isSpeaking ? 'animate-pulse' : ''}`}>
                  <i className={`fas ${isSpeaking ? 'fa-volume-high' : 'fa-bolt-lightning'} text-sm`}></i>
               </div>
               <div>
                 <span className="text-[10px] font-black uppercase tracking-[3px] italic block leading-none mb-1">BFC ASSIST</span>
                 <span className="text-[7px] font-bold opacity-60 uppercase tracking-widest leading-none">Food Concierge</span>
               </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="w-10 h-10 bg-white/10 rounded-2xl flex items-center justify-center hover:bg-white/20 transition-all">
              <i className="fas fa-times text-xs"></i>
            </button>
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar bg-black/20">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-elite-up`}>
                <div className={`max-w-[85%] px-5 py-4 rounded-[28px] text-[11px] font-black leading-relaxed shadow-xl ${m.role === 'user' ? 'bg-red-600 text-white' : 'bg-gray-800 text-gray-100 border border-white/5'}`}>
                  {m.text}
                </div>
              </div>
            ))}
            {currentTranscription && (
              <div className="flex justify-start">
                <div className="max-w-[85%] px-5 py-3 rounded-[24px] text-[11px] font-black bg-gray-800/50 text-emerald-400 border border-emerald-500/20 animate-pulse italic">
                  {currentTranscription}
                </div>
              </div>
            )}
            {isLoading && (
              <div className="flex justify-start pl-4">
                <div className="flex gap-2">
                  <span className="w-2 h-2 bg-red-600 rounded-full animate-bounce"></span>
                  <span className="w-2 h-2 bg-red-600 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                  <span className="w-2 h-2 bg-red-600 rounded-full animate-bounce [animation-delay:0.4s]"></span>
                </div>
              </div>
            )}
          </div>

          <div className="p-5 bg-gray-900 border-t border-white/5 flex gap-4 shrink-0">
            <button onClick={toggleMic} className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all ${isMicOn ? 'bg-red-600 text-white animate-pulse shadow-red-600/40' : 'bg-white/5 text-gray-400 hover:text-red-500'}`}>
              <i className={`fas ${isMicOn ? 'fa-microphone' : 'fa-microphone-slash'} text-lg`}></i>
            </button>
            <div className="flex-1 flex items-center bg-white/5 rounded-[28px] p-1 pr-3">
              <input 
                type="text" value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSend()}
                placeholder="খাবার সম্পর্কে জিজ্ঞাসা করুন..."
                className="flex-1 bg-transparent border-none px-5 outline-none text-xs font-black text-white placeholder:opacity-30"
              />
              <button onClick={handleSend} className="w-12 h-12 bg-red-600 text-white rounded-2xl flex items-center justify-center shadow-lg active:scale-90 hover:brightness-110">
                <i className="fas fa-paper-plane text-xs"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button onClick={() => setIsOpen(true)} className="w-20 h-20 bg-red-600 text-white rounded-[32px] shadow-[0_25px_60px_rgba(220,38,38,0.6)] flex flex-col items-center justify-center hover:scale-110 active:scale-95 transition-all group pulse-primary border-2 border-white/20">
           <i className="fas fa-bolt-lightning text-3xl mb-1 group-hover:animate-bounce"></i>
           <span className="text-[7px] font-black uppercase tracking-widest opacity-60">Assist</span>
           {isSpeaking && <span className="absolute -top-1 -right-1 flex h-4 w-4"><span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span><span className="relative inline-flex rounded-full h-4 w-4 bg-emerald-500 shadow-lg"></span></span>}
        </button>
      )}
    </div>
  );
};

