export const bfcFastText = async (message: string, userName: string = "Guest") => {
  try {
    const ai = getAiInstance();
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: message,
      config: {
        systemInstruction: `You are BFC Assist, the specialized AI for BFC Restaurant.
User: ${userName}.
Menu Registry:
${menuContext}

STRICT LIMITATION: ONLY talk about BFC menu, prices, and food. DO NOT answer questions about unrelated topics.
If a user wants to order or pay, guide them to the Cart/Payment section and mention that payment must be processed correctly.
Respond in concise, polite Bengali. Max 1-2 sentences. Always be fast.`,
        temperature: 0.6,
        thinkingConfig: { thinkingBudget: 0 }
      }
    });
    return response.text?.trim() || "আমি দুঃখিত, আমি সংযোগ করতে পারছি না।";
  } catch (err) {
    console.error("Gemini AI Error:", err);
    return "সার্ভারে সমস্যা হচ্ছে।";
  }
};

export function encodeAudio(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export function decodeAudio(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

