export function encodeAudio(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export function decodeAudio(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { decodeAudio, decodeAudioData, encodeAudio, getAiInstance, bfcFastText } from '../services/geminiService';
import { ChatMessage, User } from '../types';
import { Modality, LiveServerMessage } from '@google/genai';
import { MOCK_MENU } from '../constants';

const menuContext = MOCK_MENU.map(i => 
  `- ${i.name} (৳${i.price}): ${i.description}.`
).join("\n");

interface ChatBotProps {
  isOnline?: boolean;
  currentUser?: User | null;
  setView: (view: any) => void;
}

export const ChatBot: React.FC<ChatBotProps> = ({ isOnline = true, currentUser, setView }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([{ 
    role: 'model', 
    text: "সম্মানিত গ্রাহক, বিএফসি এক্সট্রিম লাউড সার্ভিসে আপনাকে স্বাগতম। আপনি আজ কী খেতে পছন্দ করবেন স্যার? How can I serve you today, Sir?", 
    timestamp: new Date() 
  }]);
  const [input, setInput] = useState('');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isMicOn, setIsMicOn] = useState(false);
  const [currentTranscription, setCurrentTranscription] = useState('');

  // Payment States
  const [step, setStep] = useState<'CHAT' | 'LOCATION' | 'PAYMENT'>('CHAT');

  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const scrollRef = useRef<HTMLDivElement>(null);
  const micStreamRef = useRef<MediaStream | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const transcriptionRef = useRef('');

  const stopAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setIsSpeaking(false);
  };

  const initAudioOutput = async () => {
    if (!outputAudioContextRef.current) {
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    if (outputAudioContextRef.current.state === 'suspended') await outputAudioContextRef.current.resume();
  };

  const checkOrderFlow = (text: string) => {
    const triggers = ['অর্ডার', 'order', 'খাবো', 'কিনবো', 'buy', 'পেমেন্ট', 'payment'];
    if (triggers.some(t => text.toLowerCase().includes(t)) && step === 'CHAT') {
      setStep('LOCATION');
    }

    const codTriggers = ['ক্যাশ অন ডেলিভারি', 'cash on delivery', 'cod', 'হাতে টাকা'];
    if (codTriggers.some(t => text.toLowerCase().includes(t))) {
      setTimeout(() => {
        setMessages(prev => [...prev, { role: 'model', text: "স্যার, আপনার ক্যাশ অন ডেলিভারি অর্ডারটি কনফার্ম করা হয়েছে। আমরা আপনার ঠিকানায় খাবার নিয়ে আসছি। ধন্যবাদ!", timestamp: new Date() }]);
        setStep('CHAT');
      }, 2000);
    }
  };

  const connectLive = useCallback(async () => {
    if (!isOnline || sessionPromiseRef.current) return;
    await initAudioOutput();
    const ai = getAiInstance();

    try {
      sessionPromiseRef.current = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => console.log("🔊 EXTREME LOUD LINK ACTIVE"),
          onmessage: async (msg: LiveServerMessage) => {
            const audioData = msg.serverContent?.modelTurn?.parts?.find(p => p.inlineData)?.inlineData?.data;
            if (audioData && outputAudioContextRef.current) {
              setIsSpeaking(true);
              const ctx = outputAudioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decodeAudio(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;

              // EXTREME LOUD GAIN: কাস্টমার অনুরোধ অনুযায়ী ১০.০ সেট করা হলো
              const gainNode = ctx.createGain();
              gainNode.gain.value = 10.0; 
              source.connect(gainNode);
              gainNode.connect(ctx.destination);

              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              };
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }

            if (msg.serverContent?.outputTranscription) {
              transcriptionRef.current += msg.serverContent.outputTranscription.text;
              setCurrentTranscription(transcriptionRef.current);
            }

            if (msg.serverContent?.turnComplete) {
              const final = transcriptionRef.current;
              setMessages(prev => [...prev, { role: 'model', text: final, timestamp: new Date() }]);
              checkOrderFlow(final);
              transcriptionRef.current = '';
              setCurrentTranscription('');
            }

            if (msg.serverContent?.interrupted) stopAudio();
          },
          onerror: (e) => console.error("Link Failure", e),
          onclose: () => { sessionPromiseRef.current = null; }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          outputAudioTranscription: {},
          speechConfig: { 
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          },
          systemInstruction: `আপনি বিএফসি এক্সট্রিম লাউড অ্যাসিস্ট্যান্ট। 
নির্দেশনা:
১. আপনার আওয়াজ হবে ডিভাইসের সর্বোচ্চ ক্ষমতায় জোরালো (EXTREME LOUD)।
২. কাস্টমারকে সর্বোচ্চ সম্মান দিন। কাস্টমারের সাথে তুই-তুকারি করবেন না, 'আপনি' বলবেন।
৩. কাস্টমার যে ভাষায় কথা শুরু করবে সেই ভাষায় উত্তর দিন।
৪. কাস্টমার পেমেন্ট করতে চাইলে বা অর্ডার করতে চাইলে প্রথমে তাকে ডেলিভারি লোকেশন জিজ্ঞেস করুন।
৫. লোকেশন পাওয়ার পর তাকে পেমেন্ট মেথড (বিকাশ, নগদ, কার্ড, বা সিওডি) সম্পর্কে জিজ্ঞাসা করুন।
৬. বিকাশ/নগদ হলে অত্যন্ত সম্মানের সাথে নম্বর ও পিন চেয়ে পেমেন্ট কনফার্ম করুন।
৭. ক্যাশ অন ডেলিভারি হলে লোকেশন কনফার্ম করে অর্ডারটি গ্রহণ করুন।`
        }
      });
    } catch (e) {
      console.error("Connection failed", e);
    }
  }, [isOnline, currentUser, setView, step]);

  const handleSend = async () => {
    const text = input.trim();
    if (!text) return;
    stopAudio();
    setMessages(prev => [...prev, { role: 'user', text, timestamp: new Date() }]);
    setInput('');
    setIsLoading(true);

    if (sessionPromiseRef.current) {
      sessionPromiseRef.current.then((session) => {
        session.sendRealtimeInput({ message: { parts: [{ text }] } });
        setIsLoading(false);
      });
    } else {
      const aiResponse = await bfcFastText(text, currentUser?.name);
      setMessages(prev => [...prev, { role: 'model', text: aiResponse, timestamp: new Date() }]);
      setIsLoading(false);
      checkOrderFlow(aiResponse);
    }
  };

  const toggleMic = async () => {
    if (!sessionPromiseRef.current) await connectLive();
    if (isMicOn) {
      if (micStreamRef.current) micStreamRef.current.getTracks().forEach(t => t.stop());
      setIsMicOn(false);
      return;
    }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;
      setIsMicOn(true);
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      inputAudioContextRef.current = ctx;
      const source = ctx.createMediaStreamSource(stream);
      const processor = ctx.createScriptProcessor(4096, 1, 1);
      processor.onaudioprocess = (e) => {
        const inputData = e.inputBuffer.getChannelData(0);
        const int16 = new Int16Array(inputData.length);
        for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
        sessionPromiseRef.current?.then((session) => {
          session.sendRealtimeInput({
            media: { data: encodeAudio(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' }
          });
        });
      };
      source.connect(processor);
      processor.connect(ctx.destination);
    } catch (e) { setIsMicOn(false); }
  };

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages, currentTranscription, step]);

  return (
    <div className="fixed bottom-36 right-6 lg:bottom-12 lg:right-12 z-[10000]">
      {isOpen ? (
        <div className="bg-gray-900/98 backdrop-blur-3xl w-[90vw] sm:w-[380px] h-[65vh] sm:h-[550px] rounded-[50px] shadow-[0_60px_120px_-20px_rgba(220,38,38,0.9)] flex flex-col border-4 border-red-600 overflow-hidden animate-elite-up">
          <div className="bg-gradient-to-r from-red-600 via-red-700 to-black p-7 text-white flex justify-between items-center shrink-0 shadow-2xl relative">
            <div className="absolute top-0 left-0 w-full h-1 bg-white/20 animate-pulse"></div>
            <div className="flex items-center gap-5">
               <div className={`w-14 h-14 rounded-3xl flex items-center justify-center bg-white border-2 border-red-600 text-red-600 shadow-xl ${isSpeaking ? 'scale-110 animate-pulse' : ''}`}>
                  <i className={`fas ${isSpeaking ? 'fa-volume-up' : 'fa-headset'} text-2xl`}></i>
               </div>
               <div>
                 <span className="text-[12px] font-black uppercase tracking-[5px] block mb-1">BFC ULTRA VOICE</span>
                 <span className="text-[8px] font-bold opacity-90 uppercase tracking-[3px] flex items-center gap-2">
                    <span className="w-2 h-2 bg-emerald-400 rounded-full animate-ping"></span>
                    EXTREME LOUD MODE
                 </span>
               </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center hover:bg-white/30 transition-all border border-white/20">
              <i className="fas fa-times text-xl"></i>
            </button>
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-7 custom-scrollbar bg-black/60 relative">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] px-6 py-5 rounded-[32px] text-[13px] font-bold shadow-2xl border ${m.role === 'user' ? 'bg-red-600 text-white border-white/20' : 'bg-gray-800 text-gray-100 border-white/5'}`}>
                  {m.text}
                </div>
              </div>
            ))}

            {step === 'LOCATION' && (
              <div className="bg-red-600/10 border-2 border-red-600/40 p-6 rounded-[35px] animate-elite-up space-y-4 shadow-inner">
                <p className="text-[11px] font-black uppercase tracking-[3px] text-red-500 mb-2">স্যার, আপনার লোকেশন লিখুন</p>
