export function encodeAudio(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export function decodeAudio(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { decodeAudio, decodeAudioData, encodeAudio, getAiInstance, bfcFastText } from '../services/geminiService';
import { ChatMessage, User } from '../types';
import { Modality, LiveServerMessage } from '@google/genai';
import { MOCK_MENU } from '../constants';

const menuContext = MOCK_MENU.map(i => 
  `- ${i.name} (৳${i.price}): ${i.description}.`
).join("\n");

interface ChatBotProps {
  isOnline?: boolean;
  currentUser?: User | null;
  setView: (view: any) => void;
}

export const ChatBot: React.FC<ChatBotProps> = ({ isOnline = true, currentUser, setView }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([{ 
    role: 'model', 
    text: "সম্মানিত গ্রাহক, বিএফসি ক্রিস্টাল-লাউড সার্ভিসে আপনাকে স্বাগতম। আপনি আজ কী খেতে পছন্দ করবেন স্যার? How can I serve you today, Sir?", 
    timestamp: new Date() 
  }]);
  const [input, setInput] = useState('');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isMicOn, setIsMicOn] = useState(false);
  const [currentTranscription, setCurrentTranscription] = useState('');

  // States for the Location & Payment Flow
  const [flow, setFlow] = useState<'CHAT' | 'LOCATION' | 'PAYMENT_METHOD' | 'BKASH_DETAILS' | 'SUCCESS'>('CHAT');
  const [orderDetails, setOrderDetails] = useState({ location: '', method: '', number: '', pin: '' });

  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const compressorNodeRef = useRef<DynamicsCompressorNode | null>(null);
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const scrollRef = useRef<HTMLDivElement>(null);
  const micStreamRef = useRef<MediaStream | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const transcriptionRef = useRef('');

  const stopAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setIsSpeaking(false);
  };

  const initAudioOutput = async () => {
    if (!outputAudioContextRef.current) {
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      outputAudioContextRef.current = ctx;

      // DynamicsCompressorNode added to prevent audio breaking at extreme gain
      const compressor = ctx.createDynamicsCompressor();
      compressor.threshold.setValueAtTime(-24, ctx.currentTime);
      compressor.knee.setValueAtTime(30, ctx.currentTime);
      compressor.ratio.setValueAtTime(12, ctx.currentTime);
      compressor.attack.setValueAtTime(0.003, ctx.currentTime);
      compressor.release.setValueAtTime(0.25, ctx.currentTime);
      compressor.connect(ctx.destination);
      compressorNodeRef.current = compressor;
    }
    if (outputAudioContextRef.current.state === 'suspended') await outputAudioContextRef.current.resume();
  };

  const handleFlowDetection = (text: string) => {
    const triggers = ['হ্যাঁ', 'yes', 'order', 'অর্ডার', 'কিনবো', 'পেমেন্ট', 'payment'];
    if (triggers.some(t => text.toLowerCase().includes(t)) && flow === 'CHAT') {
      setFlow('LOCATION');
    }

    if (text.toLowerCase().includes('ক্যাশ অন ডেলিভারি') || text.toLowerCase().includes('cod')) {
      setFlow('SUCCESS');
    }
  };

  const connectLive = useCallback(async () => {
    if (!isOnline || sessionPromiseRef.current) return;
    await initAudioOutput();
    const ai = getAiInstance();

    try {
      sessionPromiseRef.current = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => console.log("🔊 CRYSTAL LOUD VOICE ACTIVE"),
          onmessage: async (msg: LiveServerMessage) => {
            const audioData = msg.serverContent?.modelTurn?.parts?.find(p => p.inlineData)?.inlineData?.data;
            if (audioData && outputAudioContextRef.current && compressorNodeRef.current) {
              setIsSpeaking(true);
              const ctx = outputAudioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decodeAudio(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;

              // EXTREME LOUD GAIN: কাস্টমার অনুরোধ অনুযায়ী ১৫.০ সেট করা হলো
              const gainNode = ctx.createGain();
              gainNode.gain.value = 15.0; 

              source.connect(gainNode);
              gainNode.connect(compressorNodeRef.current);

              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              };
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }

            if (msg.serverContent?.outputTranscription) {
              transcriptionRef.current += msg.serverContent.outputTranscription.text;
              setCurrentTranscription(transcriptionRef.current);
            }

            if (msg.serverContent?.turnComplete) {
              const final = transcriptionRef.current;
              setMessages(prev => [...prev, { role: 'model', text: final, timestamp: new Date() }]);
              handleFlowDetection(final);
              transcriptionRef.current = '';
              setCurrentTranscription('');
            }

            if (msg.serverContent?.interrupted) stopAudio();
          },
          onerror: (e) => console.error("Link Failure", e),
          onclose: () => { sessionPromiseRef.current = null; }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          outputAudioTranscription: {},
          speechConfig: { 
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          },
          systemInstruction: `আপনি বিএফসি এলিট অ্যাসিস্ট্যান্ট। 
নির্দেশনা:
১. আপনার আওয়াজ হবে এক্সট্রিমলি লাউড (Extreme Loud) কিন্তু ক্রিস্টাল ক্লিয়ার (Crystal Clear)।
২. কাস্টমারকে সর্বোচ্চ সম্মান দিন (Treat like Royalty)। সবসময় 'আপনি' বলবেন।
৩. পেমেন্টের আগে কাস্টমারকে অত্যন্ত বিনয়ের সাথে ডেলিভারি লোকেশন জিজ্ঞাসা করুন।
৪. কাস্টমার লোকেশন দিলে পেমেন্ট মেথড (বিকাশ, নগদ, কার্ড, বা সিওডি) জানতে চান।
৫. বিকাশ/নগদ হলে নম্বর ও পিন নিয়ে অর্ডার কনফার্ম করুন। কার্ড হলে কাস্টমারকে কনফার্ম করতে বলুন।
৬. আপনার কথা হবে একদম পরিষ্কার এবং কোনো রকম ভুল ছাড়াই।`
        }
      });
    } catch (e) {
      console.error("Connection failed", e);
    }
  }, [isOnline, currentUser, flow]);

  const handleSend = async () => {
    const text = input.trim();
    if (!text) return;
    stopAudio();
    setMessages(prev => [...prev, { role: 'user', text, timestamp: new Date() }]);
    setInput('');
    setIsLoading(true);

    if (sessionPromiseRef.current) {
      sessionPromiseRef.current.then((session) => {
        session.sendRealtimeInput({ message: { parts: [{ text }] } });
        setIsLoading(false);
      });
    } else {
      const aiResponse = await bfcFastText(text, currentUser?.name);
      setMessages(prev => [...prev, { role: 'model', text: aiResponse, timestamp: new Date() }]);
      setIsLoading(false);
      handleFlowDetection(aiResponse);
    }
  };

  const toggleMic = async () => {
    if (!sessionPromiseRef.current) await connectLive();
    if (isMicOn) {
      if (micStreamRef.current) micStreamRef.current.getTracks().forEach(t => t.stop());
      setIsMicOn(false);
      return;
    }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;
      setIsMicOn(true);
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      inputAudioContextRef.current = ctx;
      const source = ctx.createMediaStreamSource(stream);
      const processor = ctx.createScriptProcessor(4096, 1, 1);
      processor.onaudioprocess = (e) => {
        const inputData = e.inputBuffer.getChannelData(0);
        const int16 = new Int16Array(inputData.length);
        for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
        sessionPromiseRef.current?.then((session) => {
          session.sendRealtimeInput({
            media: { data: encodeAudio(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' }
          });
        });
      };
      source.connect(processor);
      processor.connect(ctx.destination);
    } catch (e) { setIsMicOn(false); }
  };

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages, currentTranscription, flow]);

  return (
    <div className="fixed bottom-36 right-6 lg:bottom-12 lg:right-12 z-[10000]">
      {isOpen ? (
        <div className="bg-gray-950/98 backdrop-blur-3xl w-[92vw] sm:w-[400px] h-[70vh] sm:h-[600px] rounded-[55px] shadow-[0_60px_150px_-30px_rgba(220,38,38,1)] flex flex-col border-[6px] border-red-600 overflow-hidden animate-elite-up">
          <div className="bg-gradient-to-r from-red-600 via-red-800 to-black p-8 text-white flex justify-between items-center shrink-0 shadow-2xl">
            <div className="flex items-center gap-5">
               <div className={`w-16 h-16 rounded-[28px] flex items-center justify-center bg-white text-red-600 shadow-2xl border-4 border-white/20 ${isSpeaking ? 'animate-pulse scale-110' : ''}`}>
                  <i className={`fas ${isSpeaking ? 'fa-volume-up' : 'fa-headset'} text-3xl`}></i>
               </div>
               <div>
                 <span className="text-[14px] font-black uppercase tracking-[6px] block mb-1">BFC CRYSTAL HUB</span>
                 <span className="text-[9px] font-bold opacity-100 text-emerald-400 uppercase tracking-widest flex items-center gap-2">
                    <span className="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-ping"></span>
                    EXTREME CLEAR LOUD
                 </span>
               </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="w-14 h-14 bg-white/10 rounded-3xl flex items-center justify-center hover:bg-white/30 transition-all border-2 border-white/20">
              <i className="fas fa-times text-2xl"></i>
            </button>
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar bg-black/70">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[88%] px-7 py-6 rounded-[35px] text-[14px] font-black shadow-2xl border-2 ${m.role === 'user' ? 'bg-red-600 text-white border-white/30' : 'bg-gray-900 text-gray-100 border-white/10'}`}>
                  {m.text}
                </div>
              </div>
            ))}

            {flow === 'LOCATION' && (
              <div className="bg-red-600/20 border-4 border-red-600/50 p-8 rounded-[45px] animate-elite-up space-y-5">
                <p className="text-[12px] font-black uppercase tracking-[5px] text-red-500">স্যার, ডেলিভারি লোকেশনটি দিন</p>
                <input 
                  type="text" value={orderDetails.location} 
                  onChange={e => setOrderDetails({...orderDetails, location: e.target.value})}
                  placeholder="আপনার ঠিকানা..."
                  className="w-full bg-white/5 border-2 border-white/20 p-5 rounded-3xl text-sm text-white outline-none focus:border-red-600"
                />
                <button onClick={() => setFlow('PAYMENT_METHOD')} className="w-full py-4 bg-red-600 text-white rounded-2xl text-[11px] font-black uppercase tracking-[5px]">Next Step</button>
              </div>
            )}

            {flow === 'PAYMENT_METHOD' && (
              <div className="bg-gray-900 border-4 border-emerald-500/30 p-8 rounded-[45px] animate-elite-up space-y-6">
                <p className="text-[12px] font-black uppercase tracking-[5px] text-emerald-400">পেমেন্ট মেথড নির্বাচন করুন</p>
                <div className="grid grid-cols-2 gap-4">
                   {['bKash', 'Nagad', 'Card', 'COD'].map(p => (
                     <button key={p} onClick={() => {
                       if(p === 'bKash' || p === 'Nagad') setFlow('BKASH_DETAILS');
                       else setFlow('SUCCESS');
                     }} className="py-5 bg-white/5 border-2 border-white/10 rounded-3xl text-[11px] font-black hover:bg-red-600 transition-all uppercase">{p}</button>
                   ))}
                </div>
              </div>
            )}

            {flow === 'BKASH_DETAILS' && (
              <div className="bg-emerald-600/10 border-4 border-emerald-600/50 p-8 rounded-[45px] animate-elite-up space-y-5">
                <p className="text-[12px] font-black uppercase tracking-[5px] text-emerald-400">নম্বর এবং পিন দিন (স্যার)</p>
                <input type="text" placeholder="নম্বর" className="w-full bg-white/5 border-2 border-white/10 p-5 rounded-3xl text-sm text-white outline-none" />
