            <button onClick={toggleMic} className={`w-24 h-24 rounded-[35px] flex items-center justify-center transition-all border-4 ${isMicOn ? 'bg-red-600 border-white text-white animate-pulse shadow-[0_0_60px_rgba(220,38,38,1)]' : 'bg-white/5 border-white/20 text-gray-400 hover:text-red-500'}`}>
              <i className={`fas ${isMicOn ? 'fa-microphone' : 'fa-microphone-slash'} text-4xl`}></i>
