            <div className="flex-1 flex items-center bg-white/5 border-4 border-white/10 rounded-[45px] p-2 pr-6 focus-within:border-red-600 transition-all shadow-inner">
              <input 
                type="text" value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSend()}
                placeholder="সম্মানিত গ্রাহক, কিছু বলুন..."
                className="flex-1 bg-transparent border-none px-8 outline-none text-[16px] font-black text-white placeholder:opacity-20"
              />
              <button onClick={handleSend} className="w-16 h-16 bg-red-600 text-white rounded-[28px] flex items-center justify-center shadow-2xl active:scale-90 hover:brightness-125 transition-all">
                <i className="fas fa-paper-plane text-xl"></i>
