      ) : (
        <button onClick={() => setIsOpen(true)} className="w-32 h-32 bg-red-600 text-white rounded-[45px] shadow-[0_40px_100px_rgba(220,38,38,1)] flex flex-col items-center justify-center hover:scale-110 active:scale-95 transition-all group pulse-primary border-[6px] border-white relative overflow-hidden">
           <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/30 to-transparent animate-elite-shine"></div>
