           <span className="text-[10px] font-black uppercase tracking-[5px] opacity-100">CRYSTAL VOICE</span>
           {isSpeaking && <span className="absolute -top-4 -right-4 flex h-12 w-12"><span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-85"></span><span className="relative inline-flex rounded-full h-12 w-12 bg-emerald-500 shadow-2xl border-4 border-white"></span></span>}
