import React, { useState, useRef, useEffect, useCallback } from 'react';
import { decodeAudio, decodeAudioData, encodeAudio, getAiInstance, bfcFastText } from '../services/geminiService';
import { ChatMessage, User } from '../types';
import { Modality, LiveServerMessage } from '@google/genai';
import { MOCK_MENU } from '../constants';

const menuContext = MOCK_MENU.map(i => 
  `- ${i.name} (৳${i.price}): ${i.description}.`
).join("\n");

interface ChatBotProps {
  isOnline?: boolean;
  currentUser?: User | null;
  setView?: (view: any) => void;
}

export const ChatBot: React.FC<ChatBotProps> = ({ isOnline = true, currentUser, setView }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([{ 
    role: 'model', 
    text: "সম্মানিত গ্রাহক, বিএফসি এক্সট্রিম ক্রিস্টাল-লাউড সার্ভিসে আপনাকে স্বাগতম। আপনি আজ কী খেতে পছন্দ করবেন স্যার? How can I serve you today, Sir?", 
    timestamp: new Date() 
  }]);
  const [input, setInput] = useState('');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isMicOn, setIsMicOn] = useState(false);
  const [currentTranscription, setCurrentTranscription] = useState('');

  // States for the Location & Payment Flow
  const [flow, setFlow] = useState<'CHAT' | 'LOCATION' | 'PAYMENT_METHOD' | 'BKASH_DETAILS' | 'SUCCESS'>('CHAT');
  const [orderDetails, setOrderDetails] = useState({ location: '', method: '', number: '', pin: '' });

  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const compressorNodeRef = useRef<DynamicsCompressorNode | null>(null);
  const masterGainRef = useRef<GainNode | null>(null);
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const scrollRef = useRef<HTMLDivElement>(null);
  const micStreamRef = useRef<MediaStream | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const transcriptionRef = useRef('');

  const stopAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setIsSpeaking(false);
  };

  const initAudioOutput = async () => {
    if (!outputAudioContextRef.current) {
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      outputAudioContextRef.current = ctx;

      const compressor = ctx.createDynamicsCompressor();
      compressor.threshold.setValueAtTime(-20, ctx.currentTime);
      compressor.knee.setValueAtTime(30, ctx.currentTime);
      compressor.ratio.setValueAtTime(12, ctx.currentTime);
      compressor.attack.setValueAtTime(0.003, ctx.currentTime);
      compressor.release.setValueAtTime(0.25, ctx.currentTime);

      const gain = ctx.createGain();
      gain.gain.value = 20.0; // Extreme Loudness (20x)

      compressor.connect(gain);
      gain.connect(ctx.destination);

      compressorNodeRef.current = compressor;
      masterGainRef.current = gain;
    }
    if (outputAudioContextRef.current.state === 'suspended') await outputAudioContextRef.current.resume();
  };

  const handleFlowDetection = (text: string) => {
    const lowerText = text.toLowerCase();
    const triggers = ['হ্যাঁ', 'yes', 'order', 'অর্ডার', 'কিনবো', 'পেমেন্ট', 'payment', 'confirm', 'কনফার্ম'];
    if (triggers.some(t => lowerText.includes(t)) && flow === 'CHAT') {
      setFlow('LOCATION');
    }

    if (lowerText.includes('ক্যাশ অন ডেলিভারি') || lowerText.includes('cod')) {
      setFlow('SUCCESS');
    }
  };

  const connectLive = useCallback(async () => {
    if (!isOnline || sessionPromiseRef.current) return;
    await initAudioOutput();
    const ai = getAiInstance();

    try {
      sessionPromiseRef.current = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => console.log("🔊 CRYSTAL LOUD SYSTEM INITIALIZED"),
          onmessage: async (msg: LiveServerMessage) => {
            const audioData = msg.serverContent?.modelTurn?.parts?.find(p => p.inlineData)?.inlineData?.data;
            if (audioData && outputAudioContextRef.current && compressorNodeRef.current) {
              setIsSpeaking(true);
              const ctx = outputAudioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decodeAudio(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;

              source.connect(compressorNodeRef.current);

              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              };
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }

            if (msg.serverContent?.outputTranscription) {
              transcriptionRef.current += msg.serverContent.outputTranscription.text;
              setCurrentTranscription(transcriptionRef.current);
            }

            if (msg.serverContent?.turnComplete) {
              const final = transcriptionRef.current;
              setMessages(prev => [...prev, { role: 'model', text: final, timestamp: new Date() }]);
              handleFlowDetection(final);
              transcriptionRef.current = '';
              setCurrentTranscription('');
            }

            if (msg.serverContent?.interrupted) stopAudio();
          },
          onerror: (e) => {
            console.error("Link Error", e);
            sessionPromiseRef.current = null;
          },
          onclose: () => { sessionPromiseRef.current = null; }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          outputAudioTranscription: {},
          speechConfig: { 
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          },
          systemInstruction: `আপনি বিএফসি এক্সট্রিম ক্রিস্টাল-লাউড অ্যাসিস্ট্যান্ট। 
গুরুত্বপূর্ণ নিয়ম:
১. কথা হবে অত্যন্ত জোরালো (EXTREMELY LOUD) কিন্তু একদম পরিষ্কার।
২. কাস্টমারকে সর্বোচ্চ সম্মান দিন (Treat like a Master/Sir/Madam)।
৩. বাংলায় উত্তর দিন যদি কাস্টমার বাংলায় কথা বলে।
৪. কাস্টমার অর্ডারের কথা বললে প্রথমে লোকেশন এবং তারপর পেমেন্ট মেথড জিজ্ঞাসা করুন।
৫. বিকাশ/নগদ এর ক্ষেত্রে ফোন নম্বর এবং পিন জিজ্ঞাসা করে পেমেন্ট সম্পন্ন করুন।
৬. আপনার কাজ অর্ডার কনফার্ম করা এবং কাস্টমারকে খুশি রাখা।`
        }
      });
    } catch (e) {
      console.error("AI Link Failure", e);
    }
  }, [isOnline, currentUser, flow]);

  const handleSend = async () => {
    const text = input.trim();
    if (!text) return;
    stopAudio();
    setMessages(prev => [...prev, { role: 'user', text, timestamp: new Date() }]);
    setInput('');
    setIsLoading(true);

    if (sessionPromiseRef.current) {
      sessionPromiseRef.current.then((session) => {
        session.sendRealtimeInput({ message: { parts: [{ text }] } });
        setIsLoading(false);
      });
    } else {
      const aiResponse = await bfcFastText(text, currentUser?.name);
      setMessages(prev => [...prev, { role: 'model', text: aiResponse, timestamp: new Date() }]);
      setIsLoading(false);
      handleFlowDetection(aiResponse);
    }
  };

  const toggleMic = async () => {
    await initAudioOutput();
    if (!sessionPromiseRef.current) await connectLive();
    if (isMicOn) {
      if (micStreamRef.current) micStreamRef.current.getTracks().forEach(t => t.stop());
      setIsMicOn(false);
      return;
    }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;
      setIsMicOn(true);
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      inputAudioContextRef.current = ctx;
      const source = ctx.createMediaStreamSource(stream);
      const processor = ctx.createScriptProcessor(4096, 1, 1);
      processor.onaudioprocess = (e) => {
        const inputData = e.inputBuffer.getChannelData(0);
        const int16 = new Int16Array(inputData.length);
        for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
        sessionPromiseRef.current?.then((session) => {
          session.sendRealtimeInput({
            media: { data: encodeAudio(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' }
          });
        });
      };
      source.connect(processor);
      processor.connect(ctx.destination);
    } catch (e) { setIsMicOn(false); }
  };

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages, currentTranscription, flow]);

  return (
    <div className="fixed bottom-36 right-6 lg:bottom-12 lg:right-12 z-[10000]">
      {isOpen ? (
        <div className="bg-gray-950/98 backdrop-blur-3xl w-[94vw] sm:w-[420px] h-[75vh] sm:h-[620px] rounded-[60px] shadow-[0_60px_150px_-30px_rgba(220,38,38,1)] flex flex-col border-[8px] border-red-600 overflow-hidden animate-elite-up">
          <div className="bg-gradient-to-r from-red-600 via-red-900 to-black p-8 text-white flex justify-between items-center shrink-0 shadow-2xl relative">
            <div className="absolute top-0 left-0 w-full h-1 bg-white/30 animate-pulse"></div>
            <div className="flex items-center gap-6">
               <div className={`w-16 h-16 rounded-[32px] flex items-center justify-center bg-white text-red-600 shadow-2xl border-4 border-white/30 ${isSpeaking ? 'animate-pulse scale-110' : ''}`}>
                  <i className={`fas ${isSpeaking ? 'fa-volume-up' : 'fa-headset'} text-4xl`}></i>
               </div>
               <div>
                 <span className="text-[14px] font-black uppercase tracking-[6px] block mb-1">BFC MEGA VOICE</span>
                 <span className="text-[10px] font-bold text-emerald-400 uppercase tracking-widest flex items-center gap-2">
                    <span className="w-3 h-3 bg-emerald-500 rounded-full animate-ping"></span>
                    CRYSTAL EXTREME
                 </span>
               </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="w-14 h-14 bg-white/10 rounded-3xl flex items-center justify-center hover:bg-white/30 transition-all border-2 border-white/20">
              <i className="fas fa-times text-2xl"></i>
            </button>
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar bg-black/80">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[90%] px-8 py-6 rounded-[40px] text-[15px] font-black shadow-2xl border-2 ${m.role === 'user' ? 'bg-red-600 text-white border-white/30' : 'bg-gray-900 text-gray-100 border-white/10'}`}>
                  {m.text}
                </div>
              </div>
            ))}

            {flow === 'LOCATION' && (
              <div className="bg-red-600/20 border-4 border-red-600/50 p-8 rounded-[50px] animate-elite-up space-y-6">
                <p className="text-[12px] font-black uppercase tracking-[6px] text-red-500">স্যার, ডেলিভারি ঠিকানা দিন</p>
                <input 
                  type="text" value={orderDetails.location} 
                  onChange={e => setOrderDetails({...orderDetails, location: e.target.value})}
                  placeholder="আপনার লোকেশন..."
                  className="w-full bg-white/5 border-2 border-white/20 p-6 rounded-[30px] text-sm text-white outline-none focus:border-red-600"
                />
                <button onClick={() => setFlow('PAYMENT_METHOD')} className="w-full py-5 bg-red-600 text-white rounded-3xl text-[12px] font-black uppercase tracking-[6px] shadow-2xl active:scale-95">Next Step</button>
              </div>
            )}

            {flow === 'PAYMENT_METHOD' && (
              <div className="bg-gray-900 border-4 border-emerald-500/30 p-8 rounded-[50px] animate-elite-up space-y-7">
                <p className="text-[12px] font-black uppercase tracking-[6px] text-emerald-400">পেমেন্ট মেথড নির্বাচন করুন (স্যার)</p>
                <div className="grid grid-cols-2 gap-5">
                   {['bKash', 'Nagad', 'Card', 'COD'].map(p => (
                     <button key={p} onClick={() => {
                       if(p === 'bKash' || p === 'Nagad') setFlow('BKASH_DETAILS');
                       else { setFlow('SUCCESS'); setOrderDetails({...orderDetails, method: p}); }
                     }} className="py-6 bg-white/5 border-2 border-white/10 rounded-[30px] text-[11px] font-black hover:bg-red-600 transition-all uppercase">{p}</button>
                   ))}
                </div>
              </div>
            )}

            {flow === 'BKASH_DETAILS' && (
              <div className="bg-emerald-600/10 border-4 border-emerald-600/50 p-8 rounded-[50px] animate-elite-up space-y-6">
                <p className="text-[12px] font-black uppercase tracking-[6px] text-emerald-400">সিকিউর নম্বর এবং পিন দিন</p>
                <input type="text" placeholder="বিকাশ/নগদ নম্বর" className="w-full bg-white/5 border-2 border-white/20 p-6 rounded-[30px] text-sm text-white outline-none" />
                <input type="password" placeholder="গোপন পিন" className="w-full bg-white/5 border-2 border-white/10 p-6 rounded-[30px] text-sm text-white outline-none" />
                <button onClick={() => setFlow('SUCCESS')} className="w-full py-5 bg-emerald-600 text-white rounded-3xl text-[12px] font-black uppercase tracking-[6px] shadow-2xl">Confirm Payment</button>
              </div>
            )}

            {flow === 'SUCCESS' && (
              <div className="bg-emerald-600 p-10 rounded-[55px] animate-elite-up text-center space-y-5 shadow-[0_30px_80px_rgba(16,185,129,0.6)]">
                 <i className="fas fa-check-circle text-7xl text-white"></i>
                 <p className="text-[14px] font-black uppercase tracking-[5px] text-white">অর্ডার সফল হয়েছে স্যার! <br/><span className="text-[10px] opacity-80">খাবার ডেলিভারি হচ্ছে</span></p>
                 <button onClick={() => setFlow('CHAT')} className="px-10 py-4 bg-black text-white rounded-full text-[11px] font-black uppercase tracking-[4px]">Close Manifest</button>
              </div>
            )}

            {currentTranscription && (
              <div className="flex justify-start">
                <div className="max-w-[85%] px-7 py-5 rounded-[35px] text-[15px] font-black bg-gray-900/95 text-emerald-400 animate-pulse border-2 border-emerald-500/40 italic">
                  {currentTranscription}
                </div>
              </div>
            )}
          </div>

          <div className="p-8 bg-gray-950 border-t-[6px] border-red-600 flex gap-6 shrink-0 shadow-[0_-40px_100px_rgba(0,0,0,1)]">
            <button onClick={toggleMic} className={`w-24 h-24 rounded-[40px] flex items-center justify-center transition-all border-4 ${isMicOn ? 'bg-red-600 border-white text-white animate-pulse shadow-[0_0_70px_rgba(220,38,38,1)]' : 'bg-white/5 border-white/20 text-gray-400 hover:text-red-500'}`}>
              <i className={`fas ${isMicOn ? 'fa-microphone' : 'fa-microphone-slash'} text-4xl`}></i>
            </button>
            <div className="flex-1 flex items-center bg-white/5 border-4 border-white/10 rounded-[50px] p-2 pr-7 focus-within:border-red-600 transition-all shadow-inner">
              <input 
                type="text" value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSend()}
                placeholder="সম্মানিত গ্রাহক, কিছু বলুন..."
                className="flex-1 bg-transparent border-none px-8 outline-none text-[18px] font-black text-white placeholder:opacity-20"
              />
              <button onClick={handleSend} className="w-16 h-16 bg-red-600 text-white rounded-[30px] flex items-center justify-center shadow-2xl active:scale-90 hover:brightness-125 transition-all">
                <i className="fas fa-paper-plane text-2xl"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button onClick={() => setIsOpen(true)} className="w-36 h-36 bg-red-600 text-white rounded-[50px] shadow-[0_45px_120px_rgba(220,38,38,1)] flex flex-col items-center justify-center hover:scale-110 active:scale-95 transition-all group pulse-primary border-[8px] border-white relative overflow-hidden">
           <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/40 to-transparent animate-elite-shine"></div>
           <i className="fas fa-volume-up text-7xl mb-2 group-hover:rotate-12 transition-transform duration-300"></i>
           <span className="text-[11px] font-black uppercase tracking-[6px] opacity-100">EXTREME HUB</span>
           {isSpeaking && <span className="absolute -top-5 -right-5 flex h-14 w-14"><span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-90"></span><span className="relative inline-flex rounded-full h-14 w-14 bg-emerald-500 shadow-2xl border-[6px] border-white"></span></span>}
        </button>
      )}
    </div>
  );
};

