import React, { useState, useRef, useEffect, useCallback } from 'react';
import { decodeAudio, decodeAudioData, encodeAudio, getAiInstance, bfcFastText } from '../services/geminiService';
import { ChatMessage, User } from '../types';
import { Modality, LiveServerMessage } from '@google/genai';

interface ChatBotProps {
  isOnline?: boolean;
  currentUser?: User | null;
  setView?: (view: any) => void;
}

export const ChatBot: React.FC<ChatBotProps> = ({ isOnline = true, currentUser, setView }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([{ 
    role: 'model', 
    text: "সম্মানিত গ্রাহক, বিএফসি এক্সট্রিম সার্ভিসে স্বাগতম। আপনি আজ কী খেতে পছন্দ করবেন স্যার?", 
    timestamp: new Date() 
  }]);
  const [input, setInput] = useState('');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isMicOn, setIsMicOn] = useState(false);
  const [currentTranscription, setCurrentTranscription] = useState('');

  const [flowStep, setFlowStep] = useState<'CHAT' | 'LOCATION' | 'PAYMENT' | 'FINISH'>('CHAT');
  const [address, setAddress] = useState('');

  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const compressorNodeRef = useRef<DynamicsCompressorNode | null>(null);
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const scrollRef = useRef<HTMLDivElement>(null);
  const micStreamRef = useRef<MediaStream | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const transcriptionRef = useRef('');

  const stopAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setIsSpeaking(false);
  };

  const initAudioOutput = async () => {
    if (!outputAudioContextRef.current) {
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      outputAudioContextRef.current = ctx;
      const compressor = ctx.createDynamicsCompressor();
      compressor.threshold.setValueAtTime(-18, ctx.currentTime);
      const gain = ctx.createGain();
      gain.gain.value = 25.0; // Extreme Loud Mode
      compressor.connect(gain);
      gain.connect(ctx.destination);
      compressorNodeRef.current = compressor;
    }
    if (outputAudioContextRef.current.state === 'suspended') await outputAudioContextRef.current.resume();
  };

  const handleFlowCheck = (text: string) => {
    const lower = text.toLowerCase();
    if (['অর্ডার', 'order', 'কিনবো', 'confirm'].some(t => lower.includes(t)) && flowStep === 'CHAT') setFlowStep('LOCATION');
    if (lower.includes('ক্যাশ অন ডেলিভারি') || lower.includes('cod')) setFlowStep('FINISH');
  };

  const connectLive = useCallback(async () => {
    if (!isOnline || sessionPromiseRef.current) return;
    await initAudioOutput();
    const ai = getAiInstance();
    try {
      sessionPromiseRef.current = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onmessage: async (msg: LiveServerMessage) => {
            const audioData = msg.serverContent?.modelTurn?.parts?.find(p => p.inlineData)?.inlineData?.data;
            if (audioData && outputAudioContextRef.current && compressorNodeRef.current) {
              setIsSpeaking(true);
              const ctx = outputAudioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decodeAudio(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(compressorNodeRef.current);
              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              };
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }
            if (msg.serverContent?.outputTranscription) {
              transcriptionRef.current += msg.serverContent.outputTranscription.text;
              setCurrentTranscription(transcriptionRef.current);
            }
            if (msg.serverContent?.turnComplete) {
              setMessages(prev => [...prev, { role: 'model', text: transcriptionRef.current, timestamp: new Date() }]);
              handleFlowCheck(transcriptionRef.current);
              transcriptionRef.current = '';
              setCurrentTranscription('');
            }
            if (msg.serverContent?.interrupted) stopAudio();
          },
          onerror: () => { sessionPromiseRef.current = null; },
          onclose: () => { sessionPromiseRef.current = null; }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          outputAudioTranscription: {},
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
          systemInstruction: "আপনি বিএফসি কমপ্যাক্ট মেগা ভয়েস অ্যাসিস্ট্যান্ট। আওয়াজ অত্যন্ত জোরালো এবং পরিষ্কার। কাস্টমারকে 'আপনি' বলবেন। অর্ডার করলে লোকেশন ও পেমেন্ট কার্ড ওপেন করতে বলুন।"
        }
      });
    } catch (e) { console.error(e); }
  }, [isOnline, flowStep]);

  const handleSend = async () => {
    const text = input.trim();
    if (!text) return;
    stopAudio();
    await initAudioOutput();
    setMessages(prev => [...prev, { role: 'user', text, timestamp: new Date() }]);
    setInput('');
    if (sessionPromiseRef.current) {
      sessionPromiseRef.current.then(s => s.sendRealtimeInput({ message: { parts: [{ text }] } }));
    } else {
      const resp = await bfcFastText(text, currentUser?.name);
      setMessages(prev => [...prev, { role: 'model', text: resp, timestamp: new Date() }]);
      handleFlowCheck(resp);
    }
  };

  const toggleMic = async () => {
    await initAudioOutput();
    if (!sessionPromiseRef.current) await connectLive();
    if (isMicOn) {
      if (micStreamRef.current) micStreamRef.current.getTracks().forEach(t => t.stop());
      setIsMicOn(false);
      return;
    }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;
      setIsMicOn(true);
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      inputAudioContextRef.current = ctx;
      const source = ctx.createMediaStreamSource(stream);
      const processor = ctx.createScriptProcessor(4096, 1, 1);
      processor.onaudioprocess = (e) => {
        const inputData = e.inputBuffer.getChannelData(0);
        const int16 = new Int16Array(inputData.length);
        for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
        sessionPromiseRef.current?.then(s => s.sendRealtimeInput({
          media: { data: encodeAudio(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' }
        }));
      };
      source.connect(processor);
      processor.connect(ctx.destination);
    } catch (e) { setIsMicOn(false); }
  };

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages, currentTranscription]);

  return (
    <div className="fixed bottom-32 right-4 lg:bottom-10 lg:right-10 z-[10000]">
      {isOpen ? (
        <div className="bg-gray-950/98 backdrop-blur-2xl w-[90vw] sm:w-[350px] h-[500px] sm:h-[550px] rounded-[45px] shadow-[0_40px_100px_rgba(220,38,38,0.6)] flex flex-col border-[6px] border-red-600 overflow-hidden animate-elite-up">
          {/* Compact Header */}
          <div className="bg-red-600 p-5 text-white flex justify-between items-center shrink-0 shadow-lg">
            <div className="flex items-center gap-4">
               <div className={`w-10 h-10 rounded-2xl flex items-center justify-center bg-white text-red-600 ${isSpeaking ? 'animate-pulse' : ''}`}>
                  <i className={`fas ${isSpeaking ? 'fa-volume-up' : 'fa-headset'} text-xl`}></i>
               </div>
               <div>
                 <span className="text-[10px] font-black uppercase tracking-[3px] block">BFC HUB</span>
                 <span className="text-[8px] font-bold text-emerald-400 uppercase tracking-widest">CRYSTAL VOICE</span>
               </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="w-8 h-8 bg-white/10 rounded-xl flex items-center justify-center hover:bg-white/20 transition-all">
              <i className="fas fa-times text-sm"></i>
            </button>
          </div>

          {/* Compact Chat Area */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-5 space-y-5 custom-scrollbar bg-black/50">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] px-5 py-3.5 rounded-[28px] text-[13px] font-bold shadow-xl border ${m.role === 'user' ? 'bg-red-600 text-white border-white/20' : 'bg-gray-900 text-gray-100 border-white/5'}`}>
                  {m.text}
                </div>
              </div>
            ))}

            {flowStep === 'LOCATION' && (
              <div className="bg-red-600/10 border-2 border-red-600/30 p-5 rounded-[35px] animate-elite-up space-y-4">
                <p className="text-[10px] font-black uppercase tracking-[3px] text-red-500">স্যার, ডেলিভারি লোকেশন দিন</p>
                <input 
                  type="text" value={address} onChange={e => setAddress(e.target.value)}
                  placeholder="আপনার ঠিকানা..."
                  className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl text-[12px] text-white outline-none focus:border-red-600"
                />
                <button onClick={() => setFlowStep('PAYMENT')} className="w-full py-3 bg-red-600 text-white rounded-xl text-[10px] font-black uppercase tracking-[3px]">Next</button>
              </div>
            )}

            {flowStep === 'PAYMENT' && (
              <div className="bg-gray-900 border-2 border-emerald-500/20 p-5 rounded-[35px] animate-elite-up space-y-4">
                <p className="text-[10px] font-black uppercase tracking-[3px] text-emerald-400">পেমেন্ট মেথড (স্যার)</p>
                <div className="grid grid-cols-2 gap-3">
                   {['bKash', 'COD'].map(p => (
                     <button key={p} onClick={() => setFlowStep('FINISH')} className="py-3 bg-white/5 border border-white/10 rounded-xl text-[10px] font-black hover:bg-red-600 transition-all uppercase">{p}</button>
                   ))}
                </div>
              </div>
            )}

            {flowStep === 'FINISH' && (
              <div className="bg-emerald-600 p-8 rounded-[40px] animate-elite-up text-center space-y-3">
                 <i className="fas fa-check-circle text-4xl text-white"></i>
                 <p className="text-[12px] font-black uppercase tracking-[2px] text-white">অর্ডার সফল স্যার!</p>
                 <button onClick={() => setFlowStep('CHAT')} className="px-6 py-2 bg-black text-white rounded-full text-[9px] font-black uppercase">Close</button>
              </div>
            )}

            {currentTranscription && (
              <div className="flex justify-start">
                <div className="max-w-[80%] px-4 py-3 rounded-2xl text-[12px] font-bold bg-gray-900/90 text-emerald-400 animate-pulse italic">
                  {currentTranscription}
                </div>
              </div>
            )}
          </div>

          {/* Compact Input Area */}
          <div className="p-5 bg-gray-950 border-t-2 border-red-600 flex gap-4 shrink-0 shadow-2xl">
            <button onClick={toggleMic} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all border-2 ${isMicOn ? 'bg-red-600 border-white text-white animate-pulse' : 'bg-white/5 border-white/10 text-gray-500'}`}>
              <i className={`fas ${isMicOn ? 'fa-microphone' : 'fa-microphone-slash'} text-xl`}></i>
            </button>
            <div className="flex-1 flex items-center bg-white/5 border border-white/10 rounded-[28px] p-1.5 focus-within:border-red-600 transition-all">
              <input 
                type="text" value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSend()}
                placeholder="কিছু বলুন..."
                className="flex-1 bg-transparent border-none px-4 outline-none text-[13px] font-bold text-white placeholder:opacity-20"
              />
              <button onClick={handleSend} className="w-9 h-9 bg-red-600 text-white rounded-xl flex items-center justify-center shadow-lg active:scale-90">
                <i className="fas fa-paper-plane text-sm"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button onClick={() => setIsOpen(true)} className="w-24 h-24 bg-red-600 text-white rounded-[35px] shadow-[0_25px_60px_rgba(220,38,38,0.7)] flex flex-col items-center justify-center hover:scale-105 active:scale-95 transition-all group pulse-primary border-[4px] border-white relative overflow-hidden">
           <i className="fas fa-volume-up text-4xl mb-1 group-hover:rotate-12 transition-transform"></i>
           <span className="text-[8px] font-black uppercase tracking-[3px]">ASSISTANT</span>
           {isSpeaking && <span className="absolute -top-3 -right-3 flex h-10 w-10"><span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span><span className="relative inline-flex rounded-full h-10 w-10 bg-emerald-500 shadow-xl border-[4px] border-white"></span></span>}
        </button>
      )}
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import { MOCK_MENU } from "../constants";

export const getAiInstance = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const menuContext = MOCK_MENU.map(i => 
  `- ${i.name} (${i.nameBn}): ৳${i.price}.`
).join("\n");

export const bfcFastText = async (message: string, userName: string = "Guest") => {
  try {
    const ai = getAiInstance();
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: message,
      config: {
        systemInstruction: `আপনি বিএফসি অ্যাসিস্ট্যান্ট। 
১. কথা শুরু করবেন: "হ্যালো আসসালামু আলাইকুম, আপনার কী লাগবে স্যার?" দিয়ে।
২. খুব সংক্ষেপে কথা বলবেন। লম্বা বর্ণনা দেবেন না।
৩. কাস্টমার যা অর্ডার করতে চায় তা মেনু থেকে মিলিয়ে নিন।
মেনু:
${menuContext}`,
        temperature: 0.1,
        thinkingConfig: { thinkingBudget: 0 }
      }
    });
    return response.text?.trim() || "হ্যালো আসসালামু আলাইকুম, আপনার কী লাগবে স্যার?";
  } catch (err) {
    return "হ্যালো আসসালামু আলাইকুম, আপনার কী লাগবে স্যার?";
  }
};

export function encodeAudio(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export function decodeAudio(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

