            </div>
          </div>
        </div>
      ) : (
        <button onClick={() => setIsOpen(true)} className="w-20 h-20 bg-red-600 text-white rounded-[28px] shadow-2xl flex flex-col items-center justify-center hover:scale-105 transition-all border-4 border-white relative overflow-hidden pulse-primary">
