import React, { useState, useRef, useEffect, useCallback } from 'react';
import { decodeAudio, decodeAudioData, encodeAudio, getAiInstance, bfcFastText } from '../services/geminiService';
import { ChatMessage, User } from '../types';
import { Modality, LiveServerMessage } from '@google/genai';

interface ChatBotProps {
  isOnline?: boolean;
  currentUser?: User | null;
  setView?: (view: any) => void;
}

export const ChatBot: React.FC<ChatBotProps> = ({ isOnline = true, currentUser, setView }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([{ 
    role: 'model', 
    text: "হ্যালো আসসালামু আলাইকুম, আপনার কী লাগবে স্যার?", 
    timestamp: new Date() 
  }]);
  const [input, setInput] = useState('');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isMicOn, setIsMicOn] = useState(false);
  const [currentTranscription, setCurrentTranscription] = useState('');

  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const masterGainRef = useRef<GainNode | null>(null);
  const compressorNodeRef = useRef<DynamicsCompressorNode | null>(null);
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const scrollRef = useRef<HTMLDivElement>(null);
  const micStreamRef = useRef<MediaStream | null>(null);
  const transcriptionRef = useRef('');

  const stopAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setIsSpeaking(false);
  };

  const initAudioOutput = async () => {
    if (!outputAudioContextRef.current) {
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      outputAudioContextRef.current = ctx;

      // Multi-stage processing for Crystal Clear Audio
      const compressor = ctx.createDynamicsCompressor();
      compressor.threshold.setValueAtTime(-24, ctx.currentTime);
      compressor.knee.setValueAtTime(30, ctx.currentTime);
      compressor.ratio.setValueAtTime(12, ctx.currentTime);
      compressor.attack.setValueAtTime(0.003, ctx.currentTime);
      compressor.release.setValueAtTime(0.25, ctx.currentTime);

      const makeupGain = ctx.createGain();
      makeupGain.gain.value = 4.0; // Boost signal for loudness

      const masterGain = ctx.createGain();
      masterGain.gain.value = 1.5; // Final safety gain

      compressor.connect(makeupGain);
      makeupGain.connect(masterGain);
      masterGain.connect(ctx.destination);

      compressorNodeRef.current = compressor;
      masterGainRef.current = masterGain;
    }
    if (outputAudioContextRef.current.state === 'suspended') {
      await outputAudioContextRef.current.resume();
    }
  };

  const connectLive = useCallback(async () => {
    if (!isOnline || sessionPromiseRef.current) return;
    await initAudioOutput();
    const ai = getAiInstance();
    try {
      sessionPromiseRef.current = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            sessionPromiseRef.current?.then(s => s.sendRealtimeInput({
              message: { parts: [{ text: "Introduce yourself as BFC Ultra Fast AI. Greet with Salaam. Keep responses extremely short and audible." }] }
            }));
          },
          onmessage: async (msg: LiveServerMessage) => {
            const audioData = msg.serverContent?.modelTurn?.parts?.find(p => p.inlineData)?.inlineData?.data;
            if (audioData && outputAudioContextRef.current && compressorNodeRef.current) {
              setIsSpeaking(true);
              const ctx = outputAudioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decodeAudio(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(compressorNodeRef.current!);
              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              };
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }
            if (msg.serverContent?.outputTranscription) {
              transcriptionRef.current += msg.serverContent.outputTranscription.text;
              setCurrentTranscription(transcriptionRef.current);
            }
            if (msg.serverContent?.turnComplete) {
              const fullText = transcriptionRef.current || "আপনার সেবা দিতে প্রস্তুত স্যার।";
              setMessages(prev => [...prev, { role: 'model', text: fullText, timestamp: new Date() }]);
              transcriptionRef.current = '';
              setCurrentTranscription('');
            }
            if (msg.serverContent?.interrupted) stopAudio();
          },
          onerror: (e) => { 
            console.error("Live Error:", e);
            sessionPromiseRef.current = null; 
          },
          onclose: () => { sessionPromiseRef.current = null; }
        },
        config: {
          responseModalalities: [Modality.AUDIO],
          outputAudioTranscription: {},
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
          systemInstruction: "You are the BFC Ultra-Fast AI Assistant. 1. Always start with 'হ্যালো আসসালামু আলাইকুম'. 2. Support both Bengali and English fluently. 3. Speak clearly, loudly, and concisely. 4. If the user speaks English, reply in English. If Bengali, reply in Bengali. 5. Limit responses to 1-2 short sentences maximum for speed."
        }
      });
    } catch (e) { console.error(e); }
  }, [isOnline]);

  const handleSend = async () => {
    const text = input.trim();
    if (!text) return;
    stopAudio();
    await initAudioOutput();
    setMessages(prev => [...prev, { role: 'user', text, timestamp: new Date() }]);
    setInput('');
    if (sessionPromiseRef.current) {
      sessionPromiseRef.current.then(s => s.sendRealtimeInput({ message: { parts: [{ text }] } }));
    } else {
      const resp = await bfcFastText(text, currentUser?.name);
      setMessages(prev => [...prev, { role: 'model', text: resp, timestamp: new Date() }]);
    }
  };

  const toggleMic = async () => {
    await initAudioOutput();
    if (!sessionPromiseRef.current) await connectLive();
    if (isMicOn) {
      if (micStreamRef.current) micStreamRef.current.getTracks().forEach(t => t.stop());
      setIsMicOn(false);
      return;
    }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;
      setIsMicOn(true);
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const source = ctx.createMediaStreamSource(stream);
      const processor = ctx.createScriptProcessor(1024, 1, 1); // Lower buffer for better sync
      processor.onaudioprocess = (e) => {
        const inputData = e.inputBuffer.getChannelData(0);
        const int16 = new Int16Array(inputData.length);
        for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
        sessionPromiseRef.current?.then(s => s.sendRealtimeInput({
          media: { data: encodeAudio(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' }
        }));
      };
      source.connect(processor);
      processor.connect(ctx.destination);
    } catch (e) { setIsMicOn(false); }
  };

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'auto' });
  }, [messages, currentTranscription]);

  useEffect(() => {
    if (isOpen) {
      connectLive();
    }
  }, [isOpen, connectLive]);

  return (
    <div className="fixed bottom-32 right-4 lg:bottom-10 lg:right-10 z-[10000]">
      {isOpen ? (
        <div className="bg-gray-900/98 backdrop-blur-2xl w-[85vw] sm:w-[320px] h-[450px] rounded-[35px] shadow-[0_30px_80px_rgba(220,38,38,0.5)] flex flex-col border-4 border-red-600 overflow-hidden animate-elite-up">
          <div className="bg-red-600 p-4 text-white flex justify-between items-center shrink-0">
            <div className="flex items-center gap-3">
               <div className={`w-8 h-8 rounded-xl flex items-center justify-center bg-white text-red-600 ${isSpeaking ? 'animate-pulse' : ''}`}>
                  <i className={`fas ${isSpeaking ? 'fa-volume-up' : 'fa-headset'} text-sm`}></i>
               </div>
               <span className="text-[10px] font-black uppercase tracking-widest">BFC ULTRA VOICE</span>
            </div>
            <button onClick={() => setIsOpen(false)} className="w-7 h-7 bg-white/10 rounded-lg flex items-center justify-center"><i className="fas fa-times text-xs"></i></button>
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar bg-black/40">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] px-4 py-2.5 rounded-[22px] text-[12px] font-bold ${m.role === 'user' ? 'bg-red-600 text-white' : 'bg-gray-800 text-gray-100 shadow-lg'}`}>
