              <i className={`fas ${isMicOn ? 'fa-microphone' : 'fa-microphone-slash'} text-lg`}></i>
            </button>
            <div className="flex-1 flex items-center bg-white/5 border border-white/10 rounded-[20px] p-1 px-3">
