          <div className="max-w-2xl mx-auto p-6 animate-elite-up pb-40">
            <div className="themed-card p-10 lg:p-16 rounded-[60px] space-y-12 relative overflow-hidden shadow-3xl border-2 border-white/5 backdrop-blur-3xl">
               <div className="absolute top-0 left-0 w-full h-2 themed-primary animate-pulse"></div>

               <div className="text-center space-y-6">
                  <div className="w-20 h-20 themed-primary rounded-3xl flex items-center justify-center mx-auto shadow-[0_0_50px_rgba(220,38,38,0.4)] animate-bounce">
                    <i className={`fas ${authMode === 'LOGIN' ? 'fa-fingerprint' : 'fa-user-plus'} text-3xl`}></i>
                  </div>
                  <h2 className="text-4xl lg:text-6xl font-black italic uppercase tracking-tighter">{authMode === 'LOGIN' ? 'Identity Hub' : 'Join Elite'}</h2>
                  <div className="flex justify-center gap-4 bg-white/5 p-2 rounded-2xl max-w-xs mx-auto">
                    <button onClick={() => setAuthMode('LOGIN')} className={`flex-1 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${authMode === 'LOGIN' ? 'themed-primary shadow-lg' : 'opacity-30'}`}>Login</button>
                    <button onClick={() => setAuthMode('REGISTER')} className={`flex-1 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${authMode === 'REGISTER' ? 'themed-primary shadow-lg' : 'opacity-30'}`}>Register</button>
                  </div>
               </div>

               <div className="space-y-8 relative">
                 {authMode === 'REGISTER' && (
                   <div className="space-y-3 animate-fade-in">
                      <label className="text-[9px] font-black uppercase tracking-[6px] opacity-40 ml-6">Full Name</label>
                      <div className="relative group">
                        <i className="fas fa-signature absolute left-8 top-1/2 -translate-y-1/2 opacity-20 text-xs"></i>
                        <input placeholder="ENTER FULL NAME" value={regName} onChange={e => setRegName(e.target.value)} className="w-full bg-white/5 themed-border border p-8 pl-14 rounded-[32px] outline-none font-black text-xs uppercase focus:border-red-600 focus:shadow-[0_0_20px_rgba(220,38,38,0.1)] transition-all" />
                      </div>
                   </div>
                 )}

                 <div className="space-y-3">
                   <label className="text-[9px] font-black uppercase tracking-[6px] opacity-40 ml-6">Neural ID (Email)</label>
                   <div className="relative group">
                      <i className="fas fa-envelope absolute left-8 top-1/2 -translate-y-1/2 opacity-20 text-xs"></i>
                      <input placeholder="ACCESS_ID@BFC.ELITE" value={loginId} onChange={e => setLoginId(e.target.value)} className="w-full bg-white/5 themed-border border p-8 pl-14 rounded-[32px] outline-none font-black text-xs uppercase focus:border-red-600 focus:shadow-[0_0_20px_rgba(220,38,38,0.1)] transition-all" />
                   </div>
                 </div>

                 <Button fullWidth size="lg" className="rounded-[32px] py-10 shadow-2xl relative group" onClick={handleAuth} disabled={isAuthLoading}>
                   {isAuthLoading ? (
                     <i className="fas fa-circle-notch fa-spin text-lg"></i>
                   ) : (
                     <>
                        <span className="mr-4">{authMode === 'LOGIN' ? 'AUTHORIZE ACCESS' : 'ESTABLISH REGISTRY'}</span>
                        <i className="fas fa-arrow-right group-hover:translate-x-2 transition-transform"></i>
                     </>
                   )}
                 </Button>

                 <div className="flex items-center gap-6 opacity-20">
                    <div className="h-[1px] flex-1 bg-white"></div>
                    <span className="text-[8px] font-black tracking-widest">EXTERNAL LINKS</span>
                    <div className="h-[1px] flex-1 bg-white"></div>
                 </div>

                 <div className="grid grid-cols-2 gap-4">
                    <button className="flex items-center justify-center gap-3 bg-white/5 themed-border border py-5 rounded-2xl hover:bg-white/10 transition-all">
                      <i className="fab fa-google text-xs"></i>
                      <span className="text-[8px] font-black tracking-widest">GOOGLE</span>
                    </button>
                    <button className="flex items-center justify-center gap-3 bg-white/5 themed-border border py-5 rounded-2xl hover:bg-white/10 transition-all">
                      <i className="fab fa-apple text-xs"></i>
                      <span className="text-[8px] font-black tracking-widest">APPLE ID</span>
                    </button>
                 </div>

                 {currentUser && (
                   <Button fullWidth variant="danger" className="rounded-[28px] py-6" onClick={() => { setCurrentUser(null); setView('HOME'); }}>DE-AUTHORIZE SESSION</Button>
                 )}
               </div>

               <p className="text-[8px] text-center opacity-20 font-black tracking-[3px] uppercase">By continuing, you accept the BFC Elite Neural Protocol v7.0</p>
            </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="max-w-4xl mx-auto p-6 lg:p-20 space-y-20 animate-elite-up pb-40">
            <h2 className="text-6xl lg:text-9xl font-black italic uppercase text-center tracking-tighter">Manifest</h2>
            <div className="themed-card p-10 lg:p-16 rounded-[64px] space-y-12 shadow-3xl">
               {cart.length === 0 ? (
                 <div className="text-center py-20 space-y-6">
                    <i className="fas fa-box-open text-6xl opacity-10"></i>
                    <p className="text-[11px] font-black uppercase tracking-[12px] opacity-30">Deployment manifest empty.</p>
                    <Button variant="outline" size="sm" onClick={() => setView('MENU')}>Back to Registry</Button>
                 </div>
               ) : (
                 <>
                   <div className="space-y-10">
                     {cart.map((c, i) => (
                       <div key={i} className="flex justify-between items-center border-b themed-border pb-10 last:border-0 last:pb-0 group">
                         <div className="flex gap-8 items-center">
                           <div className="w-20 h-20 rounded-3xl bg-white/5 border themed-border overflow-hidden shadow-xl group-hover:scale-110 transition-transform">
                             <img src={c.item.image} className="w-full h-full object-cover" alt="" />
                           </div>
                           <div>
                             <p className="font-black italic uppercase text-xl leading-none mb-2">{c.item.name}</p>
                             <div className="flex items-center gap-4">
                               <button onClick={() => setCart(prev => prev.map(x => x.item.id === c.item.id ? {...x, qty: Math.max(0, x.qty-1)} : x).filter(x => x.qty > 0))} className="w-8 h-8 rounded-xl bg-white/5 border themed-border flex items-center justify-center text-xs hover:themed-primary transition-all"><i className="fas fa-minus"></i></button>
                               <span className="text-sm font-black w-4 text-center">{c.qty}</span>
                               <button onClick={() => setCart(prev => prev.map(x => x.item.id === c.item.id ? {...x, qty: x.qty+1} : x))} className="w-8 h-8 rounded-xl bg-white/5 border themed-border flex items-center justify-center text-xs hover:themed-primary transition-all"><i className="fas fa-plus"></i></button>
                             </div>
                           </div>
                         </div>
                         <p className="text-2xl font-black">৳{c.item.price * c.qty}</p>
                       </div>
                     ))}
                   </div>
                   <div className="pt-12 border-t-4 themed-border space-y-8">
                      <div className="flex justify-between items-end">
                        <div className="space-y-1">
                          <p className="text-[11px] font-black uppercase tracking-[8px] opacity-40">Deployment Logistics</p>
                          <p className="text-[10px] opacity-30 font-bold uppercase">Estimated Time: 35 MINS</p>
                        </div>
                        <span className="text-5xl lg:text-7xl font-black italic leading-none themed-text-primary">৳{total}</span>
                      </div>
                      <div className="pt-6">
                        {paymentStep === 'IDLE' ? (
                          <Button fullWidth size="lg" className="rounded-3xl py-10" onClick={() => setPaymentStep('SELECT')} disabled={isOffline}>
                            {isOffline ? 'NEURAL LINK REQUIRED' : 'AUTHORIZE DEPLOYMENT'}
                          </Button>
                        ) : paymentStep === 'SELECT' ? (
                          <div className="grid grid-cols-2 gap-6 animate-fade-in">
                            {['BKASH', 'COD'].map(m => (
                              <button key={m} onClick={() => setSelectedPayment(m)} className={`p-8 rounded-3xl border-2 transition-all font-black text-[12px] tracking-[4px] uppercase ${selectedPayment === m ? 'themed-primary border-transparent shadow-2xl' : 'themed-border opacity-40 hover:opacity-100'}`}>{m}</button>
                            ))}
                            <Button fullWidth variant="outline" className="col-span-2 rounded-3xl py-8" onClick={processPayment}>CONFIRM SIGNATURE</Button>
                          </div>
                        ) : (
                          <div className="text-center py-16 space-y-6">
                            <div className="w-16 h-16 border-4 themed-text-primary border-t-transparent rounded-full animate-spin mx-auto"></div>
                            <p className="text-[11px] font-black uppercase tracking-[10px] opacity-40">Synchronizing with Logistics Hub...</p>
                          </div>
                        )}
                      </div>
                   </div>
                 </>
               )}
            </div>
          </div>
        )}

        {view === 'VAULT' && (
          <div className="p-6 lg:p-20 max-w-6xl mx-auto space-y-20 animate-elite-up pb-40">
             <div className="text-center space-y-6">
                <h2 className="text-6xl lg:text-9xl font-black italic uppercase tracking-tighter">{cms.vault.title}</h2>
                <p className="text-sm lg:text-xl opacity-60 max-w-2xl mx-auto uppercase tracking-widest font-medium leading-relaxed">{cms.vault.description}</p>
             </div>
             <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
                <div className="lg:col-span-2 themed-card p-12 lg:p-20 rounded-[72px] relative overflow-hidden group shadow-3xl">
                   <div className="absolute top-0 right-0 w-96 h-96 bg-red-600/10 blur-[120px] group-hover:bg-red-600/20 transition-all"></div>
                   <div className="relative z-10 flex flex-col h-full justify-between gap-16">
                      <div className="space-y-4">
                        <p className="text-[11px] font-black uppercase tracking-[8px] opacity-40">Current Pulse Balance</p>
                        <h3 className="text-8xl lg:text-[10rem] font-black italic leading-none tracking-tighter">৳{currentUser?.loyaltyPoints || 0}</h3>
                      </div>
                      <div className="flex flex-col sm:flex-row gap-6">
                        <Button fullWidth size="lg" className="rounded-[32px] py-12" disabled={isOffline}>RECHARGE LINK</Button>
                        <Button fullWidth variant="outline" size="lg" className="rounded-[32px] py-12" disabled={isOffline}>SEND PULSE</Button>
                      </div>
                   </div>
                </div>
                <div className="themed-card p-10 rounded-[56px] space-y-12 shadow-2xl">
                   <h4 className="text-[11px] font-black uppercase tracking-[8px] themed-text-primary">Recent Activity</h4>
                   <div className="space-y-8">
                      {allOrders.slice(0, 4).map(o => (
                        <div key={o.id} className="flex justify-between items-center border-b themed-border pb-8 last:border-0">
                           <div>
                              <p className="text-sm font-black uppercase italic leading-none mb-2">Order #{o.id.split('-')[1]}</p>
                              <p className="text-[9px] opacity-30 font-bold uppercase">{new Date(o.createdAt).toLocaleDateString()}</p>
                           </div>
                           <p className="text-sm font-black text-emerald-500">+{Math.floor(o.total/10)} PTS</p>
                        </div>
                      ))}
                   </div>
                   <Button variant="outline" fullWidth className="rounded-2xl text-[8px]">View All Logs</Button>
                </div>
             </div>
          </div>
        )}
      </main>

      <ChatBot isOnline={!isOffline} currentUser={currentUser} setView={setView} menuItems={menuItems} />

      {/* Mobile Navigation Dock */}
      <nav className="fixed bottom-0 inset-x-0 z-[6000] lg:hidden glass-nav border-t themed-border flex justify-around items-center safe-bottom h-24 shadow-[0_-20px_50px_rgba(0,0,0,0.3)]">
        {[
          { id: 'HOME', icon: 'fa-house', label: 'Dash' },
          { id: 'MENU', icon: 'fa-utensils', label: 'Menu' },
          { id: 'VAULT', icon: 'fa-shield-halved', label: 'Vault' },
          { id: 'CART', icon: 'fa-shopping-basket', label: 'Cart' }
        ].map(item => (
          <button key={item.id} onClick={() => setView(item.id as any)} className={`flex flex-col items-center justify-center w-full h-full transition-all duration-300 ${view === item.id ? 'themed-text-primary scale-110' : 'opacity-30'}`}>
            <i className={`fas ${item.icon} text-xl mb-1.5`}></i>
            <span className="text-[8px] font-black uppercase tracking-[3px]">{item.label}</span>
          </button>
        ))}
      </nav>
    </div>
  );
};

export default App;

export enum UserRole {
  ADMIN = 'ADMIN',
  MANAGER = 'MANAGER',
  STAFF = 'STAFF',
  CUSTOMER = 'CUSTOMER'
}

export enum OrderStatus {
  PENDING = 'PENDING',
  PREPARING = 'PREPARING',
  READY = 'READY',
  ON_THE_WAY = 'ON_THE_WAY',
  DELIVERED = 'DELIVERED',
  CANCELLED = 'CANCELLED'
}

export type LayoutPreset = 
  | 'ELITE_DARK' 
  | 'CLASSIC_RED' 
  | 'CYBER_NEON' 
  | 'MINIMAL_WHITE' 
  | 'NATURE_GREEN' 
  | 'LUXURY_GOLD' 
  | 'RETRO_VIBE' 
  | 'BOLD_MONO' 
  | 'PASTEL_SOFT' 
  | 'HIGH_TECH';

export interface ThemeConfig {
  bg: string;
  fg: string;
  primary: string;
  accent: string;
  card: string;
  border: string;
  font: string;
  shadow: string;
}

export interface Promotion {
  id: string;
  name: string;
  code: string;
  discountType: 'PERCENTAGE' | 'FIXED';
  discountValue: number;
  startDate: string;
  endDate: string;
  usageLimit: number;
  usageCount: number;
  isActive: boolean;
}

export interface LoyaltyTier {
  id: string;
  name: string;
  minPoints: number;
  benefits: string[];
  color: string;
}

export interface SiteCMS {
  activeLayout: LayoutPreset;
  themeDefinitions: Record<LayoutPreset, ThemeConfig>;
  hero: {
    title: string;
    subtitle: string;
    description: string;
    image: string;
    cta: string;
  };
  navigation: {
    brand: string;
    links: { [key: string]: string };
  };
  vault: {
    title: string;
    description: string;
  };
}

export interface MenuItem {
  id: string;
  name: string;
  nameBn: string;
  description: string;
  price: number;
  category: string;
  image: string;
  stock: number;
  rating?: number;
  ingredients?: string[];
  dietary?: string[];
  prepTime?: string;
  isPopular?: boolean;
}

export interface CartItem {
  item: MenuItem;
  qty: number;
}

export interface ClaimedVoucher {
  id: string;
  uniqueCode: string;
  status: 'ACTIVE' | 'EXPENDED';
  title: string;
  discountValue: number;
  isPercentage: boolean;
}

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  items: any[];
  total: number;
  status: OrderStatus;
  createdAt: string;
  paymentMethod: string;
}

export interface User {
  id: string;
  name: string;
  username: string; // New: Unique handle
  hasCustomizedUsername: boolean; // New: Restriction flag
  email: string;
  role: UserRole;
  loyaltyPoints: number;
  claimedVouchers: ClaimedVoucher[];
  tier: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem, SiteCMS, ThemeConfig, LayoutPreset } from './types';
import { MOCK_MENU, MOCK_ORDERS, DEFAULT_THEMES } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  id: number;
  message: string;
  description?: string;
  type: 'success' | 'error' | 'warning' | 'info';
}

const DEFAULT_CMS: SiteCMS = {
  activeLayout: 'ELITE_DARK',
  themeDefinitions: DEFAULT_THEMES,
  hero: {
    title: "THE ULTIMATE TASTE OF BANGLADESH",
    subtitle: "ESTABLISHED 1999 • ELITE REGISTRY",
    description: "Experience the pinnacle of culinary excellence. Our neural logistics network ensures your feast arrives with absolute precision.",
    image: "https://images.unsplash.com/photo-1633945274405-b6c8069047b0?q=80&w=2000",
    cta: "EXPLORE REGISTRY"
  },
  navigation: {
    brand: "BFC ELITE",
    links: { home: "HOME", menu: "MENU", vault: "VAULT", profile: "PROFILE" }
  },
  vault: {
    title: "RIBOT WALLET",
    description: "Your secure vault for loyalty credits and exclusive BFC rewards. Every pulse counts towards your status."
  }
};

const App: React.FC = () => {
  const [cms, setCms] = useState<SiteCMS>(() => {
    const saved = localStorage.getItem('bfc_cms');
    return saved ? JSON.parse(saved) : DEFAULT_CMS;
  });

  const [menuItems, setMenuItems] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('bfc_menu');
    return saved ? JSON.parse(saved) : MOCK_MENU;
  });

  const [allOrders, setAllOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('bfc_orders');
    return saved ? JSON.parse(saved) : MOCK_ORDERS;
  });

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('bfc_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT'>('HOME');
  const [paymentStep, setPaymentStep] = useState<'IDLE' | 'SELECT' | 'PROCESSING' | 'SUCCESS' | 'ERROR'>('IDLE');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [selectedPayment, setSelectedPayment] = useState('');
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  // Advanced Auth States
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [loginId, setLoginId] = useState('');
  const [regName, setRegName] = useState('');
  const [isAuthLoading, setIsAuthLoading] = useState(false);
  const [customUsername, setCustomUsername] = useState('');

  const showToast = useCallback((message: string, type: Toast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, description }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 6000);
  }, []);

  useEffect(() => {
    const handleOnline = () => { setIsOffline(false); showToast('Neural Link Restored', 'success', 'Back online.'); };
    const handleOffline = () => { setIsOffline(true); showToast('Neural Link Severed', 'error', 'Local cache active.'); };
    const handleBeforeInstallPrompt = (e: any) => { e.preventDefault(); setDeferredPrompt(e); };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    };
  }, [showToast]);

  useEffect(() => { localStorage.setItem('bfc_cms', JSON.stringify(cms)); }, [cms]);
  useEffect(() => { localStorage.setItem('bfc_menu', JSON.stringify(menuItems)); }, [menuItems]);
  useEffect(() => { localStorage.setItem('bfc_orders', JSON.stringify(allOrders)); }, [allOrders]);
  useEffect(() => { localStorage.setItem('bfc_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { localStorage.setItem('bfc_user', JSON.stringify(currentUser)); }, [currentUser]);

  const subtotal = cart.reduce((a, b) => a + (b.item.price * b.qty), 0);
  const delivery = cart.length > 0 ? 60 : 0;
  const total = Math.max(0, subtotal + delivery);

  const installApp = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    if (outcome === 'accepted') showToast('App Installed', 'success');
    setDeferredPrompt(null);
  };

  const handleAuth = async () => {
    if (!loginId || !loginId.includes('@')) return showToast('Invalid Identity', 'warning', 'Please enter a valid neural address (email).');
    if (authMode === 'REGISTER' && !regName) return showToast('Name Required', 'warning', 'Enter your identity name.');

    setIsAuthLoading(true);
    await new Promise(r => setTimeout(r, 1500));

    const isAdmin = loginId.toLowerCase().includes('admin');
    const randomSuffix = Math.random().toString(36).slice(2, 6).toUpperCase();

    const user: User = {
      id: isAdmin ? 'U-ADMIN' : 'U-' + Math.random().toString(36).slice(2, 7),
      name: authMode === 'REGISTER' ? regName : (isAdmin ? 'Elite Commander' : 'Honored Guest'),
      username: isAdmin ? 'commander_elite' : `bfc_user_${randomSuffix}`, // Default handle
      hasCustomizedUsername: false,
      email: loginId,
      role: isAdmin ? UserRole.ADMIN : UserRole.CUSTOMER,
      loyaltyPoints: authMode === 'REGISTER' ? 500 : 2450,
      tier: isAdmin ? 'COMMANDER' : (authMode === 'REGISTER' ? 'BRONZE' : 'PLATINUM'),
      claimedVouchers: []
    };

    setCurrentUser(user);
    setIsAuthLoading(false);
    isAdmin ? setView('ADMIN') : setView('HOME');
    showToast(authMode === 'REGISTER' ? 'Registry Created' : 'Link Established', 'success', `Welcome, ${user.name}.`);
  };

  const updateUsername = () => {
    if (!currentUser || !customUsername) return;
    if (customUsername.length < 4) return showToast('Identity too short', 'warning', 'Username must be at least 4 characters.');

    const updatedUser: User = {
      ...currentUser,
      username: customUsername.toLowerCase().replace(/\s/g, '_'),
      hasCustomizedUsername: true
    };

    setCurrentUser(updatedUser);
    setCustomUsername('');
    showToast('Identity Synchronized', 'success', `You are now known as @${updatedUser.username}`);
  };

  const processPayment = async () => {
    if (!selectedPayment) return showToast('Payment Method Required', 'warning');
    setPaymentStep('PROCESSING');
    await new Promise(r => setTimeout(r, 2000));
    const newOrder: Order = {
      id: 'ORD-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
      customerId: currentUser?.id || 'GUEST',
      customerName: currentUser?.name || 'Guest',
      items: [...cart],
      total,
      status: OrderStatus.PENDING,
      createdAt: new Date().toISOString(),
      paymentMethod: selectedPayment
    };
    setAllOrders(p => [newOrder, ...p]);
    setCart([]);
    setPaymentStep('SUCCESS');
    showToast('Mission Success', 'success');
    setTimeout(() => { setPaymentStep('IDLE'); setView('HOME'); }, 3000);
  };

  if (view === 'ADMIN' && currentUser?.role === UserRole.ADMIN) {
    return (
      <AdminPanel 
        cms={cms} setCms={setCms}
        menuItems={menuItems} setMenuItems={setMenuItems}
        orders={allOrders} setOrders={setAllOrders}
        onLogout={() => { setView('HOME'); setCurrentUser(null); }}
      />
    );
  }

  return (
    <div className={`themed-root theme-${cms.activeLayout}`}>
      {/* ... previous navigation and toasts code ... */}
      <div className={`fixed top-0 inset-x-0 z-[10000] bg-red-600 text-white text-[9px] font-black uppercase tracking-[5px] py-2.5 text-center transition-transform duration-700 shadow-2xl ${isOffline ? 'translate-y-0' : '-translate-y-full'}`}>
        <i className="fas fa-satellite-dish-slash mr-3 animate-pulse"></i>
        BFC NEURAL LINK SEVERED • অফলাইন মোড সক্রিয়
      </div>

