import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem, SiteCMS, ThemeConfig, LayoutPreset } from './types';
import { MOCK_MENU, MOCK_ORDERS, DEFAULT_THEMES } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  id: number;
  message: string;
  description?: string;
  type: 'success' | 'error' | 'warning' | 'info';
}

const DEFAULT_CMS: SiteCMS = {
  activeLayout: 'ELITE_DARK',
  themeDefinitions: DEFAULT_THEMES,
  hero: {
    title: "THE ULTIMATE TASTE OF BANGLADESH",
    subtitle: "ESTABLISHED 1999 • ELITE REGISTRY",
    description: "Experience the pinnacle of culinary excellence. Our neural logistics network ensures your feast arrives with absolute precision.",
    image: "https://images.unsplash.com/photo-1633945274405-b6c8069047b0?q=80&w=2000",
    cta: "EXPLORE REGISTRY"
  },
  navigation: {
    brand: "BFC ELITE",
    links: { home: "HOME", menu: "MENU", vault: "VAULT", profile: "PROFILE" }
  },
  vault: {
    title: "RIBOT WALLET",
    description: "Your secure vault for loyalty credits and exclusive BFC rewards. Every pulse counts towards your status."
  }
};

const App: React.FC = () => {
  const [cms, setCms] = useState<SiteCMS>(() => {
    const saved = localStorage.getItem('bfc_cms');
    return saved ? JSON.parse(saved) : DEFAULT_CMS;
  });

  const [menuItems, setMenuItems] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('bfc_menu');
    return saved ? JSON.parse(saved) : MOCK_MENU;
  });

  const [allOrders, setAllOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('bfc_orders');
    return saved ? JSON.parse(saved) : MOCK_ORDERS;
  });

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('bfc_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT'>('HOME');
  const [paymentStep, setPaymentStep] = useState<'IDLE' | 'SELECT' | 'PROCESSING' | 'SUCCESS' | 'ERROR'>('IDLE');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [selectedPayment, setSelectedPayment] = useState('');
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  // Auth States
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [loginId, setLoginId] = useState('');
  const [regName, setRegName] = useState('');
  const [isAuthLoading, setIsAuthLoading] = useState(false);
  const [customUsername, setCustomUsername] = useState('');

  const showToast = useCallback((message: string, type: Toast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, description }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 6000);
  }, []);

  useEffect(() => {
    const handleOnline = () => { setIsOffline(false); showToast('Neural Link Restored', 'success'); };
    const handleOffline = () => { setIsOffline(true); showToast('Neural Link Severed', 'error'); };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [showToast]);

  useEffect(() => { localStorage.setItem('bfc_cms', JSON.stringify(cms)); }, [cms]);
  useEffect(() => { localStorage.setItem('bfc_menu', JSON.stringify(menuItems)); }, [menuItems]);
  useEffect(() => { localStorage.setItem('bfc_orders', JSON.stringify(allOrders)); }, [allOrders]);
  useEffect(() => { localStorage.setItem('bfc_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { localStorage.setItem('bfc_user', JSON.stringify(currentUser)); }, [currentUser]);

  const subtotal = cart.reduce((a, b) => a + (b.item.price * b.qty), 0);
  const delivery = cart.length > 0 ? 60 : 0;
  const total = Math.max(0, subtotal + delivery);

  const handleAuth = async () => {
    if (!loginId || !loginId.includes('@')) return showToast('Invalid ID', 'warning');
    if (authMode === 'REGISTER' && !regName) return showToast('Name Required', 'warning');
    setIsAuthLoading(true);
    await new Promise(r => setTimeout(r, 1500));
    const isAdmin = loginId.toLowerCase().includes('admin');
    const user: User = {
      id: isAdmin ? 'U-ADMIN' : 'U-' + Math.random().toString(36).slice(2, 7),
      name: authMode === 'REGISTER' ? regName : (isAdmin ? 'Elite Commander' : 'Honored Guest'),
      username: isAdmin ? 'admin' : `user_${Math.random().toString(36).slice(2, 6)}`,
      hasCustomizedUsername: false,
      email: loginId,
      role: isAdmin ? UserRole.ADMIN : UserRole.CUSTOMER,
      loyaltyPoints: authMode === 'REGISTER' ? 500 : 2450,
      tier: isAdmin ? 'COMMANDER' : (authMode === 'REGISTER' ? 'BRONZE' : 'PLATINUM'),
      claimedVouchers: []
    };
    setCurrentUser(user);
    setIsAuthLoading(false);
    isAdmin ? setView('ADMIN') : setView('HOME');
    showToast('Link Established', 'success');
  };

  const updateUsername = () => {
    if (!currentUser || !customUsername) return;
    const updatedUser: User = {
      ...currentUser,
      username: customUsername.toLowerCase().replace(/\s/g, '_'),
      hasCustomizedUsername: true
    };
    setCurrentUser(updatedUser);
    setCustomUsername('');
    showToast('Identity Synchronized', 'success');
  };

  if (view === 'ADMIN' && currentUser?.role === UserRole.ADMIN) {
    return (
      <AdminPanel 
        cms={cms} setCms={setCms}
        menuItems={menuItems} setMenuItems={setMenuItems}
        orders={allOrders} setOrders={setAllOrders}
        onLogout={() => { setView('HOME'); setCurrentUser(null); }}
      />
    );
  }

  return (
    <div className={`themed-root flex flex-col min-h-screen theme-${cms.activeLayout}`}>
      {/* Network Alert */}
      <div className={`fixed top-0 inset-x-0 z-[10000] bg-red-600 text-white text-[9px] font-black uppercase tracking-[5px] py-2.5 text-center transition-transform duration-700 ${isOffline ? 'translate-y-0' : '-translate-y-full'}`}>
        NEURAL LINK SEVERED • অফলাইন মোড
      </div>

      {/* Global Toasts */}
      <div className="fixed top-20 right-4 lg:right-10 z-[10000] space-y-4 max-w-sm w-[calc(100vw-2rem)]">
        {toasts.map(t => (
          <div key={t.id} className="themed-card p-5 rounded-[24px] animate-elite-up flex gap-4 items-center shadow-2xl backdrop-blur-3xl">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${t.type === 'error' ? 'bg-red-600' : 'themed-primary'}`}>
              <i className={`fas ${t.type === 'error' ? 'fa-bolt' : 'fa-check'} text-white`}></i>
            </div>
            <div className="flex-1">
              <h4 className="text-[10px] font-black uppercase tracking-widest">{t.message}</h4>
              {t.description && <p className="text-[9px] opacity-60 font-medium">{t.description}</p>}
            </div>
          </div>
        ))}
      </div>

      {/* Navigation */}
      <nav className={`fixed ${isOffline ? 'top-10' : 'top-0'} inset-x-0 z-[5000] px-6 lg:px-12 py-5 flex justify-between items-center glass-nav border-b themed-border transition-all duration-500`}>
        <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 themed-primary rounded-xl flex items-center justify-center font-black text-lg">B</div>
          <h1 className="text-xl font-black italic tracking-tighter uppercase hidden sm:block">{cms.navigation.brand}</h1>
        </div>
        <div className="flex gap-4 items-center">
          <div className="hidden lg:flex gap-8 mr-8">
            {['HOME', 'MENU', 'VAULT'].map(link => (
              <button key={link} onClick={() => setView(link as any)} className={`text-[9px] font-black uppercase tracking-[3px] transition-all hover:themed-text-primary ${view === link ? 'themed-text-primary underline underline-offset-8' : 'opacity-40'}`}>{link}</button>
            ))}
          </div>
          <button onClick={() => setView('CART')} className="relative w-11 h-11 bg-white/5 themed-border border rounded-xl flex items-center justify-center hover:scale-105 transition-all">
            <i className="fas fa-shopping-basket"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 themed-primary text-[8px] w-5 h-5 rounded-full flex items-center justify-center font-black animate-pulse">{cart.length}</span>}
          </button>
          <button onClick={() => setView('LOGIN')} className="w-11 h-11 themed-primary rounded-xl flex items-center justify-center shadow-lg hover:scale-105 transition-all overflow-hidden">
             {currentUser ? <img src={`https://ui-avatars.com/api/?name=${currentUser.name}&background=random&color=fff`} className="w-full h-full object-cover" /> : <i className="fas fa-user"></i>}
          </button>
        </div>
      </nav>

      {/* Main Content Viewport */}
      <main className={`flex-1 flex flex-col pt-28 lg:pt-32 pb-24 lg:pb-0 ${isOffline ? 'mt-8' : ''}`}>
        {view === 'HOME' && (
          <div className="animate-fade-in p-4 lg:p-10">
            <section className="relative h-[70vh] lg:h-[80vh] flex items-center px-6 lg:px-20 overflow-hidden rounded-[40px] lg:rounded-[60px] shadow-3xl">
              <img src={cms.hero.image} className="absolute inset-0 w-full h-full object-cover opacity-40 scale-105" />
              <div className="absolute inset-0 bg-gradient-to-r from-[var(--bg)] via-[var(--bg)]/80 to-transparent"></div>
              <div className="relative z-10 max-w-3xl space-y-6 lg:space-y-8 animate-elite-up">
                <p className="themed-text-primary font-black uppercase tracking-[10px] text-[10px] lg:text-sm">{cms.hero.subtitle}</p>
                <h2 className="text-4xl lg:text-8xl font-black leading-[1.1] tracking-tighter italic uppercase">{cms.hero.title}</h2>
                <p className="text-sm lg:text-xl opacity-70 max-w-xl font-medium leading-relaxed">{cms.hero.description}</p>
                <div className="pt-4 flex flex-col sm:flex-row gap-4">
                  <Button size="lg" className="rounded-2xl" onClick={() => setView('MENU')}>{cms.hero.cta}</Button>
                  <Button variant="outline" size="lg" className="rounded-2xl" onClick={() => setView('VAULT')}>SECURE VAULT</Button>
                </div>
              </div>
            </section>
          </div>
        )}

        {view === 'MENU' && (
          <div className="p-6 lg:p-20 max-w-7xl mx-auto space-y-16 animate-elite-up w-full">
            <div className="text-center space-y-4">
              <h2 className="text-5xl lg:text-8xl font-black italic uppercase tracking-tighter leading-none">The Registry</h2>
              <p className="text-[10px] font-black opacity-30 uppercase tracking-[10px]">Neural Deployment v7.0</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 lg:gap-12">
              {menuItems.map(item => (
                <div key={item.id} className="themed-card p-6 rounded-[48px] flex flex-col group hover:scale-[1.02] transition-all">
                  <div className="h-60 lg:h-72 rounded-[36px] overflow-hidden mb-8 relative">
                    <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" />
                    <div className="absolute top-4 right-4 themed-primary px-5 py-2 rounded-full text-[10px] font-black italic shadow-xl">৳{item.price}</div>
                  </div>
                  <div className="flex-1 space-y-2">
                    <h4 className="text-2xl font-black italic uppercase truncate">{item.name}</h4>
                    <p className="text-[10px] font-black themed-text-primary uppercase tracking-[4px]">{item.nameBn}</p>
                    <p className="text-xs opacity-60 font-medium line-clamp-2 leading-relaxed">{item.description}</p>
                  </div>
                  <div className="pt-6 mt-6 border-t themed-border flex justify-between items-center">
                    <span className="text-xl font-black">৳{item.price}</span>
                    <Button className="rounded-xl px-6 py-3" onClick={() => {
                      setCart(prev => {
                        const ex = prev.find(c => c.item.id === item.id);
                        if (ex) return prev.map(c => c.item.id === item.id ? {...c, qty: c.qty+1} : c);
                        return [...prev, {item, qty:1}];
                      });
                      showToast('Unit Secured', 'success');
                    }}>+ ADD</Button>
                  </div>
                </div>
              ))}
            </div>
          </div>
