        {view === 'VAULT' && (
          <div className="p-6 lg:p-20 max-w-6xl mx-auto space-y-12 animate-elite-up w-full">
             <div className="text-center space-y-4">
                <h2 className="text-5xl lg:text-8xl font-black italic uppercase tracking-tighter">{cms.vault.title}</h2>
                <p className="text-[10px] font-black uppercase tracking-[8px] themed-text-primary">Authenticated Handle: @{currentUser?.username || 'GUEST'}</p>
             </div>
             <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="lg:col-span-2 themed-card p-8 lg:p-16 rounded-[60px] relative overflow-hidden flex flex-col justify-between gap-12">
