                 )}
                 <div className="space-y-2">
                   <label className="text-[9px] font-black uppercase opacity-40 ml-4">Neural Address (Email)</label>
                   <input placeholder="EMAIL" value={loginId} onChange={e => setLoginId(e.target.value)} className="w-full bg-white/5 border themed-border p-6 rounded-[24px] outline-none font-black text-xs uppercase" />
                 </div>
                 <Button fullWidth size="lg" className="rounded-[28px] py-8" onClick={handleAuth} disabled={isAuthLoading}>
