                      <span className="text-4xl lg:text-6xl font-black italic themed-text-primary">৳{total}</span>
                   </div>
                   <Button fullWidth size="lg" className="rounded-[28px] py-8" onClick={() => setPaymentStep('SELECT')}>DEPLOY LOGISTICS</Button>
                 </>
               )}
            </div>
          </div>
        )}
      </main>

      {/* Mobile Navigation Dock */}
      <nav className="fixed bottom-0 inset-x-0 z-[6000] lg:hidden glass-nav border-t themed-border flex justify-around items-center safe-bottom h-20 shadow-2xl">
        {[
          { id: 'HOME', icon: 'fa-house', label: 'Dash' },
          { id: 'MENU', icon: 'fa-utensils', label: 'Menu' },
