            <span className="text-[8px] font-black uppercase tracking-widest">{item.label}</span>
          </button>
        ))}
      </nav>

      <ChatBot isOnline={!isOffline} currentUser={currentUser} menuItems={menuItems} />
    </div>
  );
};

