                  <div className="flex bg-white/5 p-1.5 rounded-2xl max-w-xs mx-auto">
                    <button onClick={() => setAuthMode('LOGIN')} className={`flex-1 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest ${authMode === 'LOGIN' ? 'themed-primary' : 'opacity-30'}`}>Login</button>
                    <button onClick={() => setAuthMode('REGISTER')} className={`flex-1 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest ${authMode === 'REGISTER' ? 'themed-primary' : 'opacity-30'}`}>Join</button>
