               <div className="space-y-6">
                 {authMode === 'REGISTER' && (
                   <div className="space-y-2">
                      <label className="text-[9px] font-black uppercase opacity-40 ml-4">Full Identity</label>
                      <input placeholder="NAME" value={regName} onChange={e => setRegName(e.target.value)} className="w-full bg-white/5 border themed-border p-6 rounded-[24px] outline-none font-black text-xs uppercase" />
                   </div>
                 )}
                 <div className="space-y-2">
                   <label className="text-[9px] font-black uppercase opacity-40 ml-4">Neural Address (Email)</label>
                   <input placeholder="EMAIL" value={loginId} onChange={e => setLoginId(e.target.value)} className="w-full bg-white/5 border themed-border p-6 rounded-[24px] outline-none font-black text-xs uppercase" />
                 </div>
                 <Button fullWidth size="lg" className="rounded-[28px] py-8" onClick={handleAuth} disabled={isAuthLoading}>
                   {isAuthLoading ? <i className="fas fa-circle-notch fa-spin"></i> : (authMode === 'LOGIN' ? 'AUTHORIZE' : 'REGISTER')}
                 </Button>
               </div>
               {currentUser && <Button variant="danger" fullWidth className="rounded-2xl mt-4" onClick={() => setCurrentUser(null)}>Logout</Button>}
            </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="max-w-4xl mx-auto p-6 lg:p-20 space-y-12 animate-elite-up w-full">
            <h2 className="text-5xl lg:text-8xl font-black italic uppercase text-center tracking-tighter">Manifest</h2>
            <div className="themed-card p-8 lg:p-12 rounded-[56px] space-y-8 shadow-3xl">
               {cart.length === 0 ? (
                 <div className="text-center py-20 space-y-6 opacity-20">
                    <i className="fas fa-shopping-basket text-6xl"></i>
                    <p className="text-[11px] font-black uppercase tracking-[10px]">Manifest Empty</p>
                 </div>
               ) : (
                 <>
                   <div className="space-y-6">
                     {cart.map((c, i) => (
                       <div key={i} className="flex justify-between items-center border-b themed-border pb-6 last:border-0">
                         <div className="flex gap-4 items-center">
                           <div className="w-16 h-16 rounded-xl overflow-hidden border themed-border shrink-0"><img src={c.item.image} className="w-full h-full object-cover" /></div>
                           <div>
                             <p className="font-black italic uppercase text-sm leading-none">{c.item.name}</p>
                             <div className="flex items-center gap-3 mt-2">
                               <button onClick={() => setCart(prev => prev.map(x => x.item.id === c.item.id ? { ...x, qty: Math.max(0, x.qty - 1) } : x).filter(x => x.qty > 0))} className="w-7 h-7 rounded-lg bg-white/5 border themed-border flex items-center justify-center text-[10px]"><i className="fas fa-minus"></i></button>
                               <span className="text-xs font-black">{c.qty}</span>
                               <button onClick={() => setCart(prev => prev.map(x => x.item.id === c.item.id ? { ...x, qty: x.qty + 1 } : x))} className="w-7 h-7 rounded-lg bg-white/5 border themed-border flex items-center justify-center text-[10px]"><i className="fas fa-plus"></i></button>
                             </div>
                           </div>
                         </div>
                         <p className="text-lg font-black italic">৳{c.item.price * c.qty}</p>
                       </div>
                     ))}
                   </div>
                   <div className="pt-8 border-t-2 themed-border flex justify-between items-end">
                      <span className="text-[10px] font-black uppercase opacity-40">Total Credit</span>
                      <span className="text-4xl lg:text-6xl font-black italic themed-text-primary">৳{total}</span>
                   </div>
