                 </>
               )}
            </div>
          </div>
        )}
      </main>

      {/* Mobile Navigation Dock */}
      <nav className="fixed bottom-0 inset-x-0 z-[6000] lg:hidden glass-nav border-t themed-border flex justify-around items-center safe-bottom h-20 shadow-[0_-20px_50px_rgba(0,0,0,0.4)]">
        {[
          { id: 'HOME', icon: 'fa-house', label: 'Dash' },
          { id: 'MENU', icon: 'fa-utensils', label: 'Menu' },
          { id: 'VAULT', icon: 'fa-shield-halved', label: 'Vault' },
