        ].map(item => (
          <button key={item.id} onClick={() => setView(item.id as any)} className={`flex flex-col items-center justify-center w-full transition-all ${view === item.id ? 'themed-text-primary scale-110' : 'opacity-30'}`}>
            <i className={`fas ${item.icon} text-lg mb-1`}></i>
