  vault: {
    title: "ELITE VAULT",
    description: "Manage your credits and unlock secret menu deployments."
  }
};

const App: React.FC = () => {
  const [cms, setCms] = useState<SiteCMS>(() => {
    const saved = localStorage.getItem('bfc_cms');
    return saved ? JSON.parse(saved) : DEFAULT_CMS;
  });
  const [menuItems, setMenuItems] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('bfc_menu');
    return saved ? JSON.parse(saved) : MOCK_MENU;
  });
  const [allOrders, setAllOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('bfc_orders');
    return saved ? JSON.parse(saved) : MOCK_ORDERS;
  });
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });
  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('bfc_cart');
    return saved ? JSON.parse(saved) : [];
  });
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT'>('HOME');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [loginId, setLoginId] = useState('');
  const [regName, setRegName] = useState('');
  const [isAuthLoading, setIsAuthLoading] = useState(false);
  const [formErrors, setFormErrors] = useState<{ [key: string]: boolean }>({});
  const [isShaking, setIsShaking] = useState(false);

  const showToast = useCallback((message: string, type: Toast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, description }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 6000);
  }, []);

  useEffect(() => {
    const handleOnline = () => { setIsOffline(false); showToast('Link Restored', 'success', 'System synchronized with neural core.'); };
    const handleOffline = () => { setIsOffline(true); showToast('Link Severed', 'error', 'Check your connection to resume full protocol.'); };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [showToast]);

  useEffect(() => { localStorage.setItem('bfc_cms', JSON.stringify(cms)); }, [cms]);
  useEffect(() => { localStorage.setItem('bfc_menu', JSON.stringify(menuItems)); }, [menuItems]);
  useEffect(() => { localStorage.setItem('bfc_orders', JSON.stringify(allOrders)); }, [allOrders]);
  useEffect(() => { localStorage.setItem('bfc_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { localStorage.setItem('bfc_user', JSON.stringify(currentUser)); }, [currentUser]);

  const subtotal = cart.reduce((a, b) => a + (b.item.price * b.qty), 0);
  const total = subtotal + (cart.length > 0 ? 60 : 0);

  const handleAuth = async () => {
    const errors: { [key: string]: boolean } = {};

    if (isOffline) {
      showToast('Authentication Failed', 'error', 'Neural link is offline. Connect to internet to verify identity.');
      return;
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!loginId) {
      errors.loginId = true;
      showToast('Identity Field Empty', 'warning', 'A valid email address is required to access your registry.');
    } else if (!loginId.includes('@')) {
      errors.loginId = true;
      showToast('Incomplete Address', 'warning', 'Your email handle is missing the "@" operator. Please check.');
    } else if (!emailRegex.test(loginId)) {
      errors.loginId = true;
      showToast('Invalid Protocol', 'warning', 'The email format provided is outside standard naming conventions.');
    }

    if (authMode === 'REGISTER' && (!regName || regName.trim().length < 3)) {
      errors.regName = true;
      showToast('Personnel Name Required', 'warning', 'Your legal name must be at least 3 characters for official records.');
    }

    if (Object.keys(errors).length > 0) {
      setFormErrors(errors);
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
      return;
    }

    setFormErrors({});
    setIsAuthLoading(true);

    try {
      await new Promise(r => setTimeout(r, 1500));
      const isAdmin = loginId.toLowerCase().includes('admin');
      const user: User = {
        id: isAdmin ? 'U-ADMIN' : 'U-' + Math.random().toString(36).slice(2, 7),
        name: authMode === 'REGISTER' ? regName : (isAdmin ? 'Admin Commander' : 'Honored Guest'),
        username: isAdmin ? 'admin' : `user_${Math.random().toString(36).slice(2, 6)}`,
        hasCustomizedUsername: false,
        email: loginId,
        role: isAdmin ? UserRole.ADMIN : UserRole.CUSTOMER,
        loyaltyPoints: authMode === 'REGISTER' ? 500 : 2500,
        tier: isAdmin ? 'COMMANDER' : 'GOLD',
        claimedVouchers: []
      };
      setCurrentUser(user);
      setIsAuthLoading(false);
      isAdmin ? setView('ADMIN') : setView('HOME');
      showToast('Identity Verified', 'success', `Welcome to the registry, ${user.name}.`);
    } catch (err) {
      setIsAuthLoading(false);
      showToast('Mainframe Refusal', 'error', 'The neural core rejected this connection due to a technical handshake error.');
    }
  };

  const handleCheckout = () => {
    if (isOffline) {
      showToast('Deployment Halted', 'error', 'Logistics cannot be dispatched while offline. Re-establish neural link.');
      return;
    }
    if (cart.length === 0) {
      showToast('Manifest Empty', 'warning', 'Please secure at least one food unit from the menu before initiating dispatch.');
      return;
    }
    if (!currentUser) {
      showToast('Authentication Required', 'info', 'Identity verification is needed before logistics deployment.');
      setView('LOGIN');
      return;
    }

    const success = Math.random() > 0.05; 
    if (success) {
      showToast('Mission Dispatched', 'success', 'Your order is verified. Hypersonic delivery protocol initiated.');
      setCart([]);
      setView('HOME');
    } else {
      showToast('Payment Protocol Failed', 'error', 'The credit verification timed out. Please refresh your wallet and try again.');
    }
  };

  if (view === 'ADMIN' && currentUser?.role === UserRole.ADMIN) {
    return <AdminPanel cms={cms} setCms={setCms} menuItems={menuItems} setMenuItems={setMenuItems} orders={allOrders} setOrders={setAllOrders} onLogout={() => { setView('HOME'); setCurrentUser(null); }} />;
  }

  return (
    <div className={`min-h-screen flex flex-col bg-[#020617]`}>
      <div className={`fixed top-0 inset-x-0 z-[10000] bg-red-600 text-white text-[10px] font-black uppercase tracking-[5px] py-2 text-center transition-all ${isOffline ? 'translate-y-0' : '-translate-y-full'}`}>Neural Link Severed • অফলাইন মোড</div>

      <div className="fixed top-24 right-4 lg:right-10 z-[10000] space-y-4 max-w-sm w-full pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto glass p-6 rounded-[32px] animate-elite-up flex flex-col gap-2 shadow-2xl border-l-4 border-l-red-600">
            <div className="flex items-center gap-4">
              <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${t.type === 'error' ? 'bg-red-600' : t.type === 'warning' ? 'bg-amber-500' : 'bg-emerald-600'}`}>
                <i className={`fas ${t.type === 'error' ? 'fa-bolt' : t.type === 'warning' ? 'fa-exclamation' : 'fa-check'} text-white text-[10px]`}></i>
              </div>
              <p className="text-[10px] font-black uppercase tracking-widest text-white leading-none">{t.message}</p>
            </div>
            {t.description && <p className="text-[9px] opacity-60 text-gray-300 font-medium ml-12 leading-relaxed">{t.description}</p>}
          </div>
        ))}
      </div>

      <nav className={`fixed top-0 inset-x-0 z-[5000] px-6 lg:px-12 py-5 glass flex justify-between items-center transition-all duration-300 ${view === 'LOGIN' ? 'hidden' : 'flex'}`}>
        <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-12 h-12 bg-red-600 rounded-2xl flex items-center justify-center font-black text-xl text-white shadow-[0_0_20px_rgba(220,38,38,0.4)]">B</div>
          <h1 className="text-xl font-black italic tracking-tighter uppercase hidden md:block text-white">{cms.navigation.brand}</h1>
        </div>
        <div className="hidden lg:flex items-center gap-12">
          {['HOME', 'MENU', 'VAULT'].map(link => (
            <button key={link} onClick={() => setView(link as any)} className={`text-[10px] font-black uppercase tracking-[4px] hover:text-red-600 transition-all ${view === link ? 'text-red-600' : 'text-gray-400'}`}>{link}</button>
          ))}
        </div>
        <div className="flex gap-4 items-center">
          <button onClick={() => setView('CART')} className="relative w-12 h-12 glass rounded-2xl flex items-center justify-center hover:scale-105 transition-all text-white">
            <i className="fas fa-shopping-bag"></i>
            {cart.length > 0 && <span className="absolute -top-2 -right-2 bg-red-600 text-white text-[9px] w-6 h-6 rounded-full flex items-center justify-center font-black">{cart.length}</span>}
          </button>
          <button onClick={() => setView('LOGIN')} className="w-12 h-12 bg-red-600 rounded-2xl flex items-center justify-center shadow-xl hover:scale-105 transition-all overflow-hidden border-2 border-white/20">
            {currentUser ? <img src={`https://ui-avatars.com/api/?name=${currentUser.name}&background=random&color=fff`} className="w-full" /> : <i className="fas fa-user text-white"></i>}
          </button>
        </div>
      </nav>

      <main className={`flex-1 flex flex-col ${view === 'LOGIN' ? '' : 'pt-28'}`}>
        {view === 'LOGIN' && (
          <div className="min-h-screen w-full flex flex-col lg:flex-row bg-[#020617]">
            <div className="hidden lg:flex lg:w-1/2 relative h-screen items-center justify-center p-24 bg-black overflow-hidden">
              <div className="absolute inset-0 z-0">
                <img src="https://images.unsplash.com/photo-1541140134513-85a161dc4a00?q=80&w=2000" className="w-full h-full object-cover opacity-40 grayscale" />
                <div className="absolute inset-0 bg-gradient-to-t from-red-600/20 via-black to-black"></div>
              </div>
              <div className="relative z-10 space-y-12 animate-elite-up">
                <div className="w-24 h-24 bg-red-600 rounded-[35px] flex items-center justify-center text-4xl text-white shadow-[0_20px_60px_rgba(220,38,38,0.6)]"><i className="fas fa-fingerprint"></i></div>
                <div className="space-y-6">
                  <h2 className="text-8xl font-black italic uppercase tracking-tighter text-white leading-none">Secure<br/><span className="text-red-600">The Vault</span></h2>
                  <p className="text-xl opacity-60 text-gray-300 max-w-lg font-medium tracking-wide">Enter the registry to unlock prioritized food deployment, secret menu codes, and exclusive member tier benefits.</p>
                </div>
              </div>
            </div>

            <div className="flex-1 flex flex-col items-center justify-center p-8 lg:p-24 relative">
              <div className={`w-full max-w-lg space-y-14 animate-elite-up ${isShaking ? 'animate-shake' : ''}`}>
                <div className="text-center lg:text-left space-y-4">
                   <h3 className="text-5xl font-black italic uppercase tracking-tighter text-white leading-none">{authMode === 'LOGIN' ? 'Access Registry' : 'New Identification'}</h3>
                   <p className="text-[11px] font-black uppercase tracking-[8px] text-red-600">Verification Required</p>
                </div>

                <div className="glass p-2 rounded-[30px] flex shadow-xl">
                  <button onClick={() => { setAuthMode('LOGIN'); setFormErrors({}); }} className={`flex-1 py-4 rounded-[22px] text-[10px] font-black uppercase tracking-widest transition-all ${authMode === 'LOGIN' ? 'bg-red-600 text-white shadow-2xl' : 'text-gray-500 opacity-50'}`}>Identity Check</button>
                  <button onClick={() => { setAuthMode('REGISTER'); setFormErrors({}); }} className={`flex-1 py-4 rounded-[22px] text-[10px] font-black uppercase tracking-widest transition-all ${authMode === 'REGISTER' ? 'bg-red-600 text-white shadow-2xl' : 'text-gray-500 opacity-50'}`}>Establish Entry</button>
                </div>

                <div className="space-y-8">
                  {authMode === 'REGISTER' && (
                    <div className="space-y-3 group">
                      <label className={`text-[9px] font-black uppercase tracking-[5px] transition-all ml-4 ${formErrors.regName ? 'text-red-500' : 'text-gray-500'}`}>Personnel Legal Name</label>
                      <div className="relative">
                        <i className={`fas fa-id-card absolute left-6 top-1/2 -translate-y-1/2 transition-all ${formErrors.regName ? 'text-red-500' : 'text-gray-600'} group-focus-within:text-red-600`}></i>
                        <input value={regName} onChange={e => { setRegName(e.target.value); setFormErrors(p => ({...p, regName: false})); }} placeholder="ARIF HOSSAIN" className={`w-full glass p-7 pl-16 rounded-[28px] outline-none font-black text-xs text-white uppercase glow-on-focus transition-all ${formErrors.regName ? 'border-error' : ''}`} />
                      </div>
                    </div>
                  )}

                  <div className="space-y-3 group">
                    <label className={`text-[9px] font-black uppercase tracking-[5px] transition-all ml-4 ${formErrors.loginId ? 'text-red-500' : 'text-gray-500'}`}>Neural Mail Address</label>
                    <div className="relative">
                      <i className={`fas fa-envelope absolute left-6 top-1/2 -translate-y-1/2 transition-all ${formErrors.loginId ? 'text-red-500' : 'text-gray-600'} group-focus-within:text-red-600`}></i>
                      <input value={loginId} onChange={e => { setLoginId(e.target.value); setFormErrors(p => ({...p, loginId: false})); }} placeholder="PERSONNEL@DOMAIN.COM" className={`w-full glass p-7 pl-16 rounded-[28px] outline-none font-black text-xs text-white uppercase glow-on-focus transition-all ${formErrors.loginId ? 'border-error' : ''}`} />
                    </div>
                  </div>

                  <div className="pt-8 space-y-8">
                    <Button fullWidth size="lg" className="rounded-[30px] py-10 shadow-[0_25px_50px_-12px_rgba(220,38,38,0.5)]" onClick={handleAuth} disabled={isAuthLoading}>
                      {isAuthLoading ? <i className="fas fa-spinner fa-spin text-xl"></i> : (authMode === 'LOGIN' ? 'AUTHORIZE ACCESS' : 'ESTABLISH IDENTITY')}
                    </Button>
                    <button onClick={() => setView('HOME')} className="w-full text-center text-[10px] font-black uppercase tracking-[6px] text-gray-600 hover:text-white transition-all py-4">Decline Authentication</button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {view === 'HOME' && (
          <div className="animate-elite-up space-y-24 pb-20">
            <section className="relative h-[85vh] flex items-center px-6 lg:px-24 mx-4 lg:mx-8 mt-4 rounded-[40px] lg:rounded-[60px] overflow-hidden group">
              <div className="absolute inset-0 z-0">
                <img src={cms.hero.image} className="w-full h-full object-cover opacity-60 group-hover:scale-110 transition-all duration-[15s]" />
                <div className="absolute inset-0 hero-mask"></div>
              </div>
              <div className="relative z-10 max-w-4xl space-y-8">
                <div className="inline-block px-6 py-2 glass rounded-full">
                  <p className="text-red-600 font-black uppercase tracking-[6px] text-[10px]">{cms.hero.subtitle}</p>
                </div>
                <h2 className="text-5xl lg:text-[110px] font-black leading-[0.9] tracking-tighter italic uppercase text-white drop-shadow-2xl">
                  {cms.hero.title}
                </h2>
                <p className="text-sm lg:text-2xl opacity-80 text-white font-medium max-w-2xl leading-relaxed">{cms.hero.description}</p>
                <div className="pt-6 flex flex-col sm:flex-row gap-6">
                  <Button size="lg" className="rounded-3xl px-16 shadow-[0_20px_40px_rgba(220,38,38,0.4)]" onClick={() => setView('MENU')}>{cms.hero.cta}</Button>
                  <Button variant="outline" size="lg" className="rounded-3xl px-16 glass text-white border-white/10" onClick={() => setView('VAULT')}>SECURE VAULT</Button>
                </div>
              </div>
            </section>

            <section className="px-6 lg:px-24 space-y-16">
              <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-8">
                <div className="space-y-4">
                  <h3 className="text-4xl lg:text-7xl font-black italic uppercase tracking-tighter text-white">Elite Signature</h3>
                  <p className="text-xs lg:text-base opacity-40 uppercase tracking-[10px] font-bold text-gray-400">Registry Categories</p>
                </div>
                <button onClick={() => setView('MENU')} className="text-stroke text-2xl lg:text-5xl font-black uppercase tracking-tighter hover:text-white transition-all">Explore Full Manifest <i className="fas fa-arrow-right-long text-xl align-middle ml-4 text-red-600"></i></button>
              </div>
              <div className="grid grid-cols-2 lg:grid-cols-4 gap-6 lg:gap-12">
                {[
                  { name: 'Kacchi Biryani', img: 'https://images.unsplash.com/photo-1633945274405-b6c8069047b0?w=600', code: 'BR-101' },
                  { name: 'Traditional Kebab', img: 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?w=600', code: 'KB-204' },
                  { name: 'Roasted Delights', img: 'https://images.unsplash.com/photo-1598515214211-89d3c73ae83b?w=600', code: 'RS-309' },
                  { name: 'Heritage Sweets', img: 'https://images.unsplash.com/photo-1488477181946-6428a0291777?w=600', code: 'DS-402' }
                ].map((cat, i) => (
                  <div key={i} className="group relative h-72 lg:h-[450px] rounded-[50px] overflow-hidden cursor-pointer shadow-2xl transition-all hover:-translate-y-4">
                    <img src={cat.img} className="absolute inset-0 w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-500" />
                    <div className="absolute inset-0 bg-gradient-to-t from-black via-black/20 to-transparent"></div>
                    <div className="absolute bottom-10 left-10 right-10 space-y-2">
                       <p className="text-red-600 font-black text-[10px] tracking-[5px] uppercase">{cat.code}</p>
                       <h4 className="text-2xl lg:text-4xl font-black italic uppercase text-white leading-none">{cat.name}</h4>
                    </div>
                  </div>
                ))}
              </div>
            </section>
          </div>
        )}

        {view === 'MENU' && (
          <div className="p-6 lg:p-24 max-w-7xl mx-auto space-y-20 animate-elite-up w-full">
            <div className="text-center space-y-4">
              <h2 className="text-6xl lg:text-[120px] font-black italic uppercase tracking-tighter text-white leading-none">The Registry</h2>
              <p className="text-[11px] font-black text-red-600 uppercase tracking-[15px]">Deployment Manifest v9.2</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-12">
              {menuItems.map(item => (
                <div key={item.id} className="glass p-6 rounded-[50px] group hover:-translate-y-4 transition-all duration-500 flex flex-col h-full border-white/5">
                  <div className="h-72 lg:h-96 rounded-[40px] overflow-hidden mb-8 relative">
                    <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" />
                    <div className="absolute top-6 right-6 bg-red-600 text-white px-6 py-2 rounded-full text-[11px] font-black shadow-2xl">৳{item.price}</div>
                    <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent opacity-60"></div>
                  </div>
                  <div className="flex-1 space-y-4 px-2">
                    <h4 className="text-3xl font-black italic uppercase text-white leading-tight">{item.name}</h4>
                    <p className="text-[11px] font-black text-red-600 uppercase tracking-[5px]">{item.category}</p>
                    <p className="text-sm opacity-50 text-gray-300 font-medium line-clamp-2 leading-relaxed">{item.description}</p>
                  </div>
                  <div className="pt-10 mt-10 border-t border-white/5 flex justify-between items-center px-2">
                    <span className="text-2xl font-black text-white italic tracking-tighter">৳{item.price}</span>
                    <Button className="rounded-2xl px-10 py-5" onClick={() => {
                      setCart(prev => {
                        const ex = prev.find(c => c.item.id === item.id);
                        if (ex) return prev.map(c => c.item.id === item.id ? { ...c, qty: c.qty + 1 } : c);
                        return [...prev, { item, qty: 1 }];
                      });
                      showToast('Secured To Bag', 'success', `${item.name} added to your deployment manifest.`);
                    }}>+ ADD UNIT</Button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="max-w-4xl mx-auto p-6 lg:p-20 space-y-12 animate-elite-up w-full">
            <h2 className="text-5xl lg:text-8xl font-black italic uppercase text-center tracking-tighter text-white">Manifest</h2>
            <div className="glass p-8 lg:p-12 rounded-[56px] space-y-8 shadow-3xl">
               {cart.length === 0 ? (
                 <div className="text-center py-20 space-y-6 opacity-20 text-white">
                    <i className="fas fa-shopping-basket text-6xl"></i>
                    <p className="text-[11px] font-black uppercase tracking-[10px]">Manifest Empty</p>
                    <Button variant="outline" className="rounded-2xl" onClick={() => setView('MENU')}>SECURE UNITS</Button>
                 </div>
               ) : (
                 <>
                   <div className="space-y-6">
                     {cart.map((c, i) => (
                       <div key={i} className="flex justify-between items-center border-b border-white/10 pb-6 last:border-0">
                         <div className="flex gap-4 items-center">
                           <div className="w-16 h-16 rounded-xl overflow-hidden border border-white/10 shrink-0"><img src={c.item.image} className="w-full h-full object-cover" /></div>
                           <div className="text-white">
                             <p className="font-black italic uppercase text-sm leading-none">{c.item.name}</p>
                             <div className="flex items-center gap-3 mt-2">
                               <button onClick={() => setCart(prev => prev.map(x => x.item.id === c.item.id ? { ...x, qty: Math.max(0, x.qty - 1) } : x).filter(x => x.qty > 0))} className="w-7 h-7 rounded-lg bg-white/5 border border-white/10 flex items-center justify-center text-[10px]"><i className="fas fa-minus"></i></button>
                               <span className="text-xs font-black">{c.qty}</span>
                               <button onClick={() => setCart(prev => prev.map(x => x.item.id === c.item.id ? { ...x, qty: x.qty + 1 } : x))} className="w-7 h-7 rounded-lg bg-white/5 border border-white/10 flex items-center justify-center text-[10px]"><i className="fas fa-plus"></i></button>
                             </div>
                           </div>
                         </div>
                         <p className="text-lg font-black italic text-white">৳{c.item.price * c.qty}</p>
                       </div>
                     ))}
                   </div>
                   <div className="pt-8 border-t-2 border-white/10 flex justify-between items-end text-white">
                      <span className="text-[10px] font-black uppercase opacity-40">Total Credit</span>
                      <span className="text-4xl lg:text-6xl font-black italic text-red-600">৳{total}</span>
                   </div>
                   <Button fullWidth size="lg" className="rounded-[28px] py-8" onClick={handleCheckout}>DEPLOY LOGISTICS</Button>
                 </>
               )}
            </div>
          </div>
        )}
      </main>

      {view !== 'LOGIN' && (
        <nav className="fixed bottom-0 inset-x-0 z-[6000] lg:hidden glass border-t border-white/10 flex justify-around items-center safe-bottom h-24 shadow-[0_-20px_50px_rgba(0,0,0,0.5)]">
          {[
            { id: 'HOME', icon: 'fa-house', label: 'Dash' },
            { id: 'MENU', icon: 'fa-utensils', label: 'Menu' },
            { id: 'VAULT', icon: 'fa-shield-halved', label: 'Vault' },
            { id: 'CART', icon: 'fa-shopping-bag', label: 'Bag' }
          ].map(item => (
            <button key={item.id} onClick={() => setView(item.id as any)} className={`flex flex-col items-center justify-center w-full transition-all ${view === item.id ? 'text-red-600 scale-110' : 'text-gray-500 opacity-40'}`}>
              <i className={`fas ${item.icon} text-xl mb-2`}></i>
              <span className="text-[9px] font-black uppercase tracking-widest">{item.label}</span>
            </button>
          ))}
        </nav>
      )}

      {view !== 'LOGIN' && <ChatBot isOnline={!isOffline} currentUser={currentUser} menuItems={menuItems} />}
    </div>
  );
};

export default App;

export enum UserRole {
  ADMIN = 'ADMIN',
  MANAGER = 'MANAGER',
  STAFF = 'STAFF',
  CUSTOMER = 'CUSTOMER'
}

export enum OrderStatus {
  PENDING = 'PENDING',
  PREPARING = 'PREPARING',
  READY = 'READY',
  ON_THE_WAY = 'ON_THE_WAY',
  DELIVERED = 'DELIVERED',
  CANCELLED = 'CANCELLED'
}

export type LayoutPreset = 
  | 'ELITE_DARK' 
  | 'CLASSIC_RED' 
  | 'CYBER_NEON' 
  | 'MINIMAL_WHITE' 
  | 'NATURE_GREEN' 
  | 'LUXURY_GOLD' 
  | 'RETRO_VIBE' 
  | 'BOLD_MONO' 
  | 'PASTEL_SOFT' 
  | 'HIGH_TECH';

export interface ThemeConfig {
  bg: string;
  fg: string;
  primary: string;
  accent: string;
  card: string;
  border: string;
  font: string;
  shadow: string;
}

export interface Promotion {
  id: string;
  name: string;
  code: string;
  discountType: 'PERCENTAGE' | 'FIXED';
  discountValue: number;
  startDate: string;
  endDate: string;
  usageLimit: number;
  usageCount: number;
  isActive: boolean;
}

export interface LoyaltyTier {
  id: string;
  name: string;
  minPoints: number;
  benefits: string[];
  color: string;
}

export interface SiteCMS {
  activeLayout: LayoutPreset;
  themeDefinitions: Record<LayoutPreset, ThemeConfig>;
  deliveryCharge: number;
  hero: {
    title: string;
    subtitle: string;
    description: string;
    image: string;
    cta: string;
  };
  navigation: {
    brand: string;
    links: { [key: string]: string };
  };
  vault: {
    title: string;
    description: string;
  };
}

export interface MenuItem {
  id: string;
  name: string;
  nameBn: string;
  description: string;
  price: number;
  category: string;
  image: string;
  stock: number;
  rating?: number;
}

export interface CartItem {
  item: MenuItem;
  qty: number;
}

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  customerPhone: string;
  customerEmail: string;
  address: string;
  items: CartItem[];
  subtotal: number;
  deliveryCharge: number;
  discount: number;
  total: number;
  status: OrderStatus;
  createdAt: string;
  paymentMethod: string;
  paymentDetails?: any;
}

export interface User {
  id: string;
  name: string;
  username: string;
  hasCustomizedUsername: boolean;
  email: string;
  role: UserRole;
  loyaltyPoints: number;
  tier: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { MenuItem, UserRole, User, Order, CartItem, SiteCMS, OrderStatus, Promotion } from './types';
import { MOCK_MENU, MOCK_ORDERS, DEFAULT_THEMES } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  id: number;
  message: string;
  description?: string;
  type: 'success' | 'error' | 'warning' | 'info';
}

const DEFAULT_CMS: SiteCMS = {
  activeLayout: 'ELITE_DARK',
  themeDefinitions: DEFAULT_THEMES,
  deliveryCharge: 50,
  hero: {
    title: "CRAFTING LEGENDARY TASTES",
    subtitle: "ESTABLISHED 1999 • BFC ELITE REGISTRY",
    description: "Indulge in the finest culinary heritage of Bangladesh. Where tradition meets high-tech precision in every bite.",
    image: "https://images.unsplash.com/photo-1633945274405-b6c8069047b0?q=80&w=2000",
    cta: "ACCESS REGISTRY"
  },
  navigation: {
    brand: "BFC ELITE",
    links: { home: "HOME", menu: "MENU", vault: "VAULT", profile: "PROFILE" }
  },
  vault: {
    title: "ELITE VAULT",
    description: "Manage your credits and unlock secret menu deployments."
  }
};

const App: React.FC = () => {
  const [cms, setCms] = useState<SiteCMS>(() => {
    const saved = localStorage.getItem('bfc_cms');
    return saved ? JSON.parse(saved) : DEFAULT_CMS;
  });
  const [menuItems, setMenuItems] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('bfc_menu');
    return saved ? JSON.parse(saved) : MOCK_MENU;
  });
  const [allOrders, setAllOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('bfc_orders');
    return saved ? JSON.parse(saved) : MOCK_ORDERS;
  });
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });
  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('bfc_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT' | 'CHECKOUT' | 'RECEIPT'>('HOME');
  const [checkoutStep, setCheckoutStep] = useState<'ADDRESS' | 'PAYMENT'>('ADDRESS');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [lastOrder, setLastOrder] = useState<Order | null>(null);

  // Form States
  const [addressData, setAddressData] = useState({ name: '', phone: '', city: 'Dhaka', street: '' });
  const [promoCode, setPromoCode] = useState('');
  const [activePromo, setActivePromo] = useState<Promotion | null>(null);
  const [paymentMethod, setPaymentMethod] = useState<'BKASH' | 'CARD' | 'COD'>('BKASH');
  const [paymentFields, setPaymentFields] = useState({ number: '', pin: '', cardNo: '', expiry: '', cvv: '' });

  const showToast = useCallback((message: string, type: Toast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, description }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 6000);
  }, []);

  useEffect(() => {
    const handleOnline = () => { setIsOffline(false); showToast('Link Restored', 'success'); };
    const handleOffline = () => { setIsOffline(true); showToast('Link Severed', 'error'); };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [showToast]);

  useEffect(() => { localStorage.setItem('bfc_cms', JSON.stringify(cms)); }, [cms]);
  useEffect(() => { localStorage.setItem('bfc_menu', JSON.stringify(menuItems)); }, [menuItems]);
  useEffect(() => { localStorage.setItem('bfc_orders', JSON.stringify(allOrders)); }, [allOrders]);
  useEffect(() => { localStorage.setItem('bfc_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { localStorage.setItem('bfc_user', JSON.stringify(currentUser)); }, [currentUser]);

  const subtotal = useMemo(() => cart.reduce((a, b) => a + (b.item.price * b.qty), 0), [cart]);
  const discountAmount = useMemo(() => {
    if (!activePromo) return 0;
    return activePromo.discountType === 'PERCENTAGE' 
      ? (subtotal * activePromo.discountValue) / 100 
      : activePromo.discountValue;
  }, [subtotal, activePromo]);
  const total = subtotal + cms.deliveryCharge - discountAmount;

  const handleApplyPromo = () => {
    const promos: Promotion[] = JSON.parse(localStorage.getItem('bfc_promotions') || '[]');
    const found = promos.find(p => p.code === promoCode.toUpperCase() && p.isActive);
    if (found) {
      setActivePromo(found);
      showToast('Promo Secured', 'success', `Discount of ৳${found.discountValue}${found.discountType === 'PERCENTAGE' ? '%' : ''} applied.`);
    } else {
      showToast('Invalid Code', 'error', 'This transmission code is not recognized by the registry.');
    }
  };

  const processPayment = async () => {
    if (isOffline) return showToast('Deployment Error', 'error', 'Link is offline.');

    // Simple validation
    if (paymentMethod === 'BKASH' && (!paymentFields.number || !paymentFields.pin)) {
      return showToast('Missing Data', 'warning', 'Please enter your wallet number and authorization pin.');
    }
    if (paymentMethod === 'CARD' && (!paymentFields.cardNo || !paymentFields.cvv)) {
      return showToast('Missing Data', 'warning', 'Secure card details are required for deployment.');
    }

    const order: Order = {
      id: 'BFC-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
      customerId: currentUser?.id || 'GUEST',
      customerName: addressData.name || currentUser?.name || 'Honored Guest',
      customerPhone: addressData.phone,
      customerEmail: currentUser?.email || 'unregistered@bfc.com',
      address: `${addressData.street}, ${addressData.city}`,
      items: [...cart],
      subtotal,
      deliveryCharge: cms.deliveryCharge,
      discount: discountAmount,
      total,
      status: OrderStatus.PENDING,
      createdAt: new Date().toISOString(),
      paymentMethod,
      paymentDetails: paymentMethod === 'COD' ? null : { provider: paymentMethod }
    };

    showToast('Authorizing Credits', 'info', 'Verifying transaction with neural bank...');
    await new Promise(r => setTimeout(r, 2000));

    setAllOrders(prev => [order, ...prev]);
    setLastOrder(order);
    setCart([]);
    setView('RECEIPT');
    showToast('Deployment Confirmed', 'success', 'Your order receipt has been generated.');
  };

  if (view === 'ADMIN' && currentUser?.role === UserRole.ADMIN) {
    return <AdminPanel cms={cms} setCms={setCms} menuItems={menuItems} setMenuItems={setMenuItems} orders={allOrders} setOrders={setAllOrders} onLogout={() => { setView('HOME'); setCurrentUser(null); }} />;
  }

  return (
    <div className={`min-h-screen flex flex-col bg-[#020617] text-white`}>
      {/* Global Navbar */}
      <nav className={`fixed top-0 inset-x-0 z-[5000] px-6 lg:px-12 py-5 glass flex justify-between items-center transition-all ${view === 'RECEIPT' ? 'hidden' : ''}`}>
        <div className="flex items-center gap-4 cursor-pointer" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center font-black">B</div>
          <h1 className="text-lg font-black italic uppercase hidden md:block">{cms.navigation.brand}</h1>
        </div>
        <div className="flex gap-4 items-center">
          <button onClick={() => setView('VAULT')} className="w-10 h-10 glass rounded-xl flex items-center justify-center"><i className="fas fa-shield-halved"></i></button>
          <button onClick={() => setView('CART')} className="relative w-10 h-10 glass rounded-xl flex items-center justify-center">
            <i className="fas fa-shopping-bag"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-[8px] w-5 h-5 rounded-full flex items-center justify-center font-black">{cart.length}</span>}
          </button>
          <button onClick={() => setView('LOGIN')} className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center overflow-hidden border-2 border-white/10">
            {currentUser ? <img src={`https://ui-avatars.com/api/?name=${currentUser.name}&background=random&color=fff`} /> : <i className="fas fa-user"></i>}
          </button>
        </div>
      </nav>

      <main className={`flex-1 flex flex-col pt-24 pb-20`}>
        {view === 'HOME' && (
          <div className="p-6 lg:p-20 space-y-20 animate-elite-up">
             <section className="h-[70vh] rounded-[40px] overflow-hidden relative flex items-center px-10">
                <img src={cms.hero.image} className="absolute inset-0 w-full h-full object-cover opacity-40" />
                <div className="relative z-10 max-w-2xl space-y-6">
                   <h2 className="text-6xl lg:text-8xl font-black italic uppercase leading-[0.9]">{cms.hero.title}</h2>
                   <p className="text-lg opacity-70">{cms.hero.description}</p>
                   <Button size="lg" onClick={() => setView('MENU')}>{cms.hero.cta}</Button>
                </div>
             </section>
          </div>
        )}

        {view === 'MENU' && (
          <div className="p-6 lg:p-20 space-y-12 animate-elite-up">
            <h2 className="text-6xl font-black italic uppercase text-center tracking-tighter">Unit Registry</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {menuItems.map(item => (
                <div key={item.id} className="glass p-6 rounded-[40px] group border-white/5 flex flex-col">
                  <div className="h-64 rounded-[30px] overflow-hidden mb-6"><img src={item.image} className="w-full h-full object-cover" /></div>
                  <div className="flex-1 space-y-2">
                    <h4 className="text-2xl font-black italic uppercase">{item.name}</h4>
                    <p className="text-xs opacity-50 uppercase tracking-widest">{item.category}</p>
                    <p className="text-xl font-black text-red-600">৳{item.price}</p>
                  </div>
                  <Button fullWidth className="mt-6 rounded-2xl" onClick={() => {
                    setCart(prev => {
                      const ex = prev.find(c => c.item.id === item.id);
                      if (ex) return prev.map(x => x.item.id === item.id ? { ...x, qty: x.qty + 1 } : x);
                      return [...prev, { item, qty: 1 }];
                    });
                    showToast('Secured', 'success', `${item.name} added to manifest.`);
                  }}>SECURE UNIT</Button>
                </div>
              ))}
            </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="max-w-2xl mx-auto p-6 w-full space-y-10 animate-elite-up">
            <h2 className="text-5xl font-black italic uppercase text-center">Manifest</h2>
            {cart.length === 0 ? (
              <div className="text-center opacity-30 py-20">
                <i className="fas fa-shopping-basket text-6xl mb-6"></i>
                <p className="uppercase font-black tracking-widest">Manifest is empty</p>
                <Button variant="outline" className="mt-6" onClick={() => setView('MENU')}>EXPLORE REGISTRY</Button>
              </div>
            ) : (
              <div className="glass p-8 rounded-[40px] space-y-8">
                <div className="space-y-4">
                  {cart.map((c, i) => (
                    <div key={i} className="flex justify-between items-center border-b border-white/5 pb-4">
                      <div className="flex gap-4 items-center">
                        <div className="w-12 h-12 rounded-lg overflow-hidden shrink-0"><img src={c.item.image} className="w-full h-full object-cover" /></div>
                        <p className="font-black italic text-sm">{c.item.name} x {c.qty}</p>
                      </div>
                      <p className="font-black">৳{c.item.price * c.qty}</p>
                    </div>
                  ))}
                </div>
                <div className="space-y-2 pt-4">
                  <div className="flex justify-between text-xs opacity-50 uppercase font-black"><span>Subtotal</span><span>৳{subtotal}</span></div>
                  <div className="flex justify-between text-xs opacity-50 uppercase font-black"><span>Logistics Charge</span><span>৳{cms.deliveryCharge}</span></div>
                  <div className="flex justify-between text-xl font-black italic text-red-600 pt-4 border-t border-white/10"><span>Total Deployment Credit</span><span>৳{total}</span></div>
                </div>
                <Button fullWidth size="lg" className="rounded-[25px]" onClick={() => {
                  if (!currentUser) { setView('LOGIN'); showToast('Identity Required', 'info'); }
                  else { setView('CHECKOUT'); setCheckoutStep('ADDRESS'); }
                }}>PROCEED TO DEPLOYMENT</Button>
              </div>
            )}
          </div>
        )}

        {view === 'CHECKOUT' && (
          <div className="max-w-xl mx-auto p-6 w-full space-y-8 animate-elite-up">
             <div className="flex justify-center items-center gap-4">
                <div className={`w-3 h-3 rounded-full ${checkoutStep === 'ADDRESS' ? 'bg-red-600' : 'bg-gray-700'}`}></div>
                <div className="w-10 h-0.5 bg-gray-800"></div>
                <div className={`w-3 h-3 rounded-full ${checkoutStep === 'PAYMENT' ? 'bg-red-600' : 'bg-gray-700'}`}></div>
             </div>

             {checkoutStep === 'ADDRESS' ? (
               <div className="glass p-10 rounded-[40px] space-y-6">
                 <h3 className="text-2xl font-black italic uppercase">Deployment Coordinates</h3>
                 <div className="space-y-4">
                    <input value={addressData.name} onChange={e => setAddressData({...addressData, name: e.target.value})} placeholder="FULL NAME" className="w-full glass p-5 rounded-2xl outline-none border border-white/5 font-bold uppercase text-xs" />
                    <input value={addressData.phone} onChange={e => setAddressData({...addressData, phone: e.target.value})} placeholder="PHONE NUMBER (01XXXXXXXXX)" className="w-full glass p-5 rounded-2xl outline-none border border-white/5 font-bold text-xs" />
                    <input value={addressData.street} onChange={e => setAddressData({...addressData, street: e.target.value})} placeholder="STREET ADDRESS / HOUSE / APARTMENT" className="w-full glass p-5 rounded-2xl outline-none border border-white/5 font-bold uppercase text-xs" />
                 </div>
                 <Button fullWidth size="lg" className="rounded-2xl" onClick={() => {
                   if (!addressData.name || !addressData.phone || !addressData.street) return showToast('Coordinates Missing', 'warning', 'Please fill all address fields.');
                   setCheckoutStep('PAYMENT');
                 }}>CONTINUE TO CREDITS</Button>
               </div>
             ) : (
               <div className="glass p-10 rounded-[40px] space-y-8">
                  <h3 className="text-2xl font-black italic uppercase">Credit Authorization</h3>

                  {/* Promo Section */}
                  <div className="flex gap-4">
                     <input value={promoCode} onChange={e => setPromoCode(e.target.value)} placeholder="PROMO CODE" className="flex-1 glass p-4 rounded-xl outline-none border border-white/5 font-bold text-xs uppercase" />
                     <button onClick={handleApplyPromo} className="px-6 bg-emerald-600 rounded-xl font-black text-[10px] uppercase">APPLY</button>
                  </div>

                  <div className="space-y-4">
                     <label className="text-[10px] font-black uppercase tracking-widest opacity-40">Payment Gateway</label>
                     <div className="grid grid-cols-3 gap-3">
                        {['BKASH', 'CARD', 'COD'].map(m => (
                          <button key={m} onClick={() => setPaymentMethod(m as any)} className={`p-4 rounded-xl border transition-all flex flex-col items-center gap-2 ${paymentMethod === m ? 'border-red-600 bg-red-600/10' : 'border-white/5 bg-white/5 opacity-50'}`}>
                             <i className={`fas ${m === 'BKASH' ? 'fa-wallet' : m === 'CARD' ? 'fa-credit-card' : 'fa-hand-holding-dollar'} text-lg`}></i>
                             <span className="text-[9px] font-black uppercase">{m}</span>
                          </button>
                        ))}
                     </div>
                  </div>

                  {paymentMethod === 'BKASH' && (
                    <div className="space-y-4 animate-elite-up">
                       <input value={paymentFields.number} onChange={e => setPaymentFields({...paymentFields, number: e.target.value})} placeholder="WALLET NUMBER" className="w-full glass p-5 rounded-2xl outline-none border border-white/5 font-bold text-xs" />
                       <input type="password" value={paymentFields.pin} onChange={e => setPaymentFields({...paymentFields, pin: e.target.value})} placeholder="SECURE PIN" className="w-full glass p-5 rounded-2xl outline-none border border-white/5 font-bold text-xs" />
                    </div>
                  )}

                  {paymentMethod === 'CARD' && (
                    <div className="space-y-4 animate-elite-up">
                       <input value={paymentFields.cardNo} onChange={e => setPaymentFields({...paymentFields, cardNo: e.target.value})} placeholder="CARD NUMBER" className="w-full glass p-5 rounded-2xl outline-none border border-white/5 font-bold text-xs" />
                       <div className="flex gap-4">
                          <input value={paymentFields.expiry} onChange={e => setPaymentFields({...paymentFields, expiry: e.target.value})} placeholder="MM/YY" className="flex-1 glass p-5 rounded-2xl outline-none border border-white/5 font-bold text-xs" />
                          <input value={paymentFields.cvv} onChange={e => setPaymentFields({...paymentFields, cvv: e.target.value})} placeholder="CVV" className="flex-1 glass p-5 rounded-2xl outline-none border border-white/5 font-bold text-xs" />
                       </div>
                    </div>
                  )}

                  <div className="pt-6 border-t border-white/10 space-y-4">
                     <div className="flex justify-between text-xl font-black italic"><span>Total Credits</span><span className="text-red-600">৳{total}</span></div>
                     <Button fullWidth size="lg" className="rounded-3xl" onClick={processPayment}>AUTHORIZE & DEPLOY</Button>
                  </div>
               </div>
             )}
          </div>
        )}

        {view === 'RECEIPT' && lastOrder && (
          <div className="max-w-2xl mx-auto p-6 w-full animate-elite-up">
             <div className="bg-white text-black p-10 lg:p-16 rounded-[10px] shadow-2xl space-y-10 relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-red-600 rotate-45 translate-x-16 -translate-y-16 flex items-end justify-center pb-4"><span className="text-white font-black text-[10px] -rotate-45">PAID</span></div>

                <div className="text-center space-y-2">
                   <h1 className="text-4xl font-black italic uppercase tracking-tighter">BANGLA FOOD CLUB</h1>
                   <p className="text-[10px] font-black uppercase tracking-[5px] opacity-40">Legendary Taste Registry</p>
                </div>

                <div className="grid grid-cols-2 gap-8 pt-8 border-t border-black/10">
                   <div className="space-y-1">
                      <p className="text-[8px] font-black uppercase opacity-40">Personnel Identity</p>
                      <p className="font-black uppercase text-sm">{lastOrder.customerName}</p>
                      <p className="text-[9px] font-medium opacity-60">@{currentUser?.username}</p>
                   </div>
                   <div className="text-right space-y-1">
                      <p className="text-[8px] font-black uppercase opacity-40">Manifest ID</p>
                      <p className="font-black text-sm">#{lastOrder.id}</p>
                      <p className="text-[9px] font-medium opacity-60">{new Date(lastOrder.createdAt).toLocaleString()}</p>
                   </div>
                </div>

                <div className="space-y-4 py-8 border-y border-black/10 border-dashed">
                   <table className="w-full">
                      <thead>
                         <tr className="text-[8px] font-black uppercase opacity-40 text-left">
                            <th className="pb-4">Registry Unit</th>
                            <th className="pb-4 text-center">Qty</th>
                            <th className="pb-4 text-right">Value</th>
                         </tr>
                      </thead>
                      <tbody>
                         {lastOrder.items.map((c, i) => (
                           <tr key={i} className="font-bold text-sm">
                              <td className="py-2">{c.item.name}</td>
                              <td className="py-2 text-center">{c.qty}</td>
                              <td className="py-2 text-right">৳{c.item.price * c.qty}</td>
                           </tr>
                         ))}
                      </tbody>
                   </table>
                </div>

                <div className="space-y-3 pt-4">
                   <div className="flex justify-between text-[10px] font-black uppercase"><span>Registry Subtotal</span><span>৳{lastOrder.subtotal}</span></div>
                   <div className="flex justify-between text-[10px] font-black uppercase"><span>Logistics Charge</span><span>৳{lastOrder.deliveryCharge}</span></div>
                   <div className="flex justify-between text-[10px] font-black uppercase"><span>Neural Discount</span><span>- ৳{lastOrder.discount}</span></div>
                   <div className="flex justify-between text-[10px] font-black uppercase"><span>V.A.T (0%)</span><span>৳0</span></div>
                   <div className="flex justify-between text-2xl font-black italic pt-6 border-t-2 border-black"><span>Total Value</span><span>৳{lastOrder.total}</span></div>
                </div>

                <div className="text-center pt-10 space-y-4">
                   <p className="text-[10px] font-black uppercase opacity-40">Payment: {lastOrder.paymentMethod}</p>
                   <div className="w-24 h-24 mx-auto opacity-10"><i className="fas fa-qrcode text-8xl"></i></div>
                   <p className="text-[8px] font-black uppercase tracking-[5px]">Mission Protocol Completed</p>
                </div>
             </div>
             <Button fullWidth className="mt-10 rounded-2xl" onClick={() => setView('HOME')}>RETURN TO DASHBOARD</Button>
          </div>
        )}

        {view === 'VAULT' && currentUser && (
          <div className="max-w-4xl mx-auto p-6 w-full space-y-12 animate-elite-up">
             <div className="glass p-12 rounded-[50px] flex flex-col lg:flex-row items-center gap-12 border-white/5">
                <div className="w-32 h-32 themed-primary rounded-[35px] flex items-center justify-center text-5xl font-black border-4 border-white/10 shadow-2xl">
