                      <button onClick={() => setAuthMode('LOGIN')} className={`text-[10px] font-black uppercase px-4 py-2 rounded-full border transition-all ${authMode === 'LOGIN' ? 'bg-red-600 border-red-600' : 'border-white/10 opacity-40'}`}>Login</button>
                      <button onClick={() => setAuthMode('REGISTER')} className={`text-[10px] font-black uppercase px-4 py-2 rounded-full border transition-all ${authMode === 'REGISTER' ? 'bg-red-600 border-red-600' : 'border-white/10 opacity-40'}`}>Register</button>
                   </div>
                </div>
                <div className="space-y-4">
                   {authMode === 'REGISTER' && <input value={regName} onChange={e => setRegName(e.target.value)} placeholder="FULL NAME" className="w-full glass p-5 rounded-2xl outline-none border border-white/5 font-bold uppercase text-xs" />}
                   <input value={loginId} onChange={e => setLoginId(e.target.value)} placeholder="PERSONNEL MAIL" className="w-full glass p-5 rounded-2xl outline-none border border-white/5 font-bold text-xs" />
                </div>
                <Button fullWidth size="lg" className="rounded-3xl" onClick={() => {
                   const isAdmin = loginId.toLowerCase().includes('admin');
                   const u: User = {
                     id: 'U-' + Math.random().toString(36).slice(2, 7),
                     name: authMode === 'REGISTER' ? regName : (isAdmin ? 'Admin Commander' : 'Honored Guest'),
                     username: isAdmin ? 'admin' : 'guest_' + Math.random().toString(36).slice(2,6),
                     hasCustomizedUsername: false,
                     email: loginId,
                     role: isAdmin ? UserRole.ADMIN : UserRole.CUSTOMER,
                     loyaltyPoints: 1250,
                     tier: 'GOLD',
                     claimedVouchers: []
                   };
                   setCurrentUser(u);
                   isAdmin ? setView('ADMIN') : setView('HOME');
                   showToast('Authorized', 'success');
                }}>VALIDATE IDENTITY</Button>
             </div>
          </div>
        )}
      </main>

      {/* Global Mobile Nav */}
      {view !== 'RECEIPT' && view !== 'LOGIN' && (
        <nav className="fixed bottom-0 inset-x-0 z-[6000] lg:hidden glass border-t border-white/5 flex justify-around items-center h-20 safe-bottom">
           <button onClick={() => setView('HOME')} className={`flex flex-col items-center gap-1 ${view === 'HOME' ? 'text-red-600' : 'opacity-40'}`}><i className="fas fa-home"></i><span className="text-[8px] font-black uppercase">Home</span></button>
           <button onClick={() => setView('MENU')} className={`flex flex-col items-center gap-1 ${view === 'MENU' ? 'text-red-600' : 'opacity-40'}`}><i className="fas fa-utensils"></i><span className="text-[8px] font-black uppercase">Menu</span></button>
           <button onClick={() => setView('CART')} className={`flex flex-col items-center gap-1 ${view === 'CART' ? 'text-red-600' : 'opacity-40'}`}><i className="fas fa-shopping-bag"></i><span className="text-[8px] font-black uppercase">Cart</span></button>
           <button onClick={() => setView('VAULT')} className={`flex flex-col items-center gap-1 ${view === 'VAULT' ? 'text-red-600' : 'opacity-40'}`}><i className="fas fa-user-shield"></i><span className="text-[8px] font-black uppercase">Vault</span></button>
        </nav>
      )}

      {/* Persistent ChatBot */}
      {view !== 'RECEIPT' && <ChatBot isOnline={!isOffline} currentUser={currentUser} menuItems={menuItems} />}

      {/* Toast Overlay */}
      <div className="fixed top-24 right-4 z-[10000] space-y-3 max-w-sm w-full pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto glass p-6 rounded-[30px] animate-elite-up border-l-4 border-red-600 shadow-2xl">
            <p className="text-[10px] font-black uppercase tracking-widest">{t.message}</p>
            {t.description && <p className="text-[9px] opacity-60 mt-1">{t.description}</p>}
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;

