  const [addressData, setAddressData] = useState({ name: '', phone: '', city: 'Dhaka', street: '' });
  const [promoCode, setPromoCode] = useState('');
  const [activePromo, setActivePromo] = useState<Promotion | null>(null);
  const [paymentMethod, setPaymentMethod] = useState<'BKASH' | 'NAGAD' | 'CARD' | 'COD'>('BKASH');
  const [paymentFields, setPaymentFields] = useState({ number: '', pin: '', cardNo: '', expiry: '', cvv: '' });
  const [loginId, setLoginId] = useState('');
  const [regName, setRegName] = useState('');

  const receiptRef = useRef<HTMLDivElement>(null);

  const showToast = useCallback((message: string, type: Toast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, description }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 6000);
  }, []);

  useEffect(() => {
    const handleOnline = () => { setIsOffline(false); showToast('Link Restored', 'success', 'Neural core synchronized.'); };
    const handleOffline = () => { setIsOffline(true); showToast('Link Severed', 'error', 'Working in offline mode.'); };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [showToast]);

  useEffect(() => { localStorage.setItem('bfc_cms', JSON.stringify(cms)); }, [cms]);
  useEffect(() => { localStorage.setItem('bfc_menu', JSON.stringify(menuItems)); }, [menuItems]);
  useEffect(() => { localStorage.setItem('bfc_orders', JSON.stringify(allOrders)); }, [allOrders]);
  useEffect(() => { localStorage.setItem('bfc_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { localStorage.setItem('bfc_user', JSON.stringify(currentUser)); }, [currentUser]);

  const subtotal = useMemo(() => cart.reduce((a, b) => a + (b.item.price * b.qty), 0), [cart]);
  const discountAmount = useMemo(() => {
    if (!activePromo) return 0;
    return activePromo.discountType === 'PERCENTAGE' 
      ? (subtotal * activePromo.discountValue) / 100 
      : activePromo.discountValue;
  }, [subtotal, activePromo]);
  const total = subtotal + cms.deliveryCharge - discountAmount;

  const handleApplyPromo = () => {
    const preCodes: Promotion[] = [
      { id: '1', name: 'Welcome', code: 'BFC50', discountType: 'FIXED', discountValue: 50, startDate: '', endDate: '', usageLimit: 100, usageCount: 0, isActive: true },
      { id: '2', name: 'Elite', code: 'ELITE20', discountType: 'PERCENTAGE', discountValue: 20, startDate: '', endDate: '', usageLimit: 100, usageCount: 0, isActive: true }
    ];
    const found = preCodes.find(p => p.code === promoCode.toUpperCase() && p.isActive);
    if (found) {
      setActivePromo(found);
      showToast('Promo Secured', 'success', `Discount of ৳${found.discountValue}${found.discountType === 'PERCENTAGE' ? '%' : ''} applied.`);
    } else {
      showToast('Invalid Code', 'error', 'Transmission code not recognized.');
    }
  };

  const processPayment = async () => {
    if (isOffline) return showToast('Deployment Error', 'error', 'Neural link is offline.');

    // Validate Phone (11 digits, BD format)
    const phoneRegex = /^01[3-9]\d{8}$/;
    if (!phoneRegex.test(addressData.phone)) {
      return showToast('Invalid Identification', 'warning', 'Phone number must be 11 digits (e.g., 01700000000).');
    }

    if ((paymentMethod === 'BKASH' || paymentMethod === 'NAGAD') && (!paymentFields.number || !paymentFields.pin)) {
      return showToast('Missing Protocols', 'warning', 'Wallet number and secure PIN required.');
    }

    if (paymentMethod === 'CARD' && (!paymentFields.cardNo || !paymentFields.cvv)) {
      return showToast('Insecure Data', 'warning', 'Full card manifest required for credit transfer.');
    }

    const order: Order = {
      id: 'BFC-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
      customerId: currentUser?.id || 'GUEST',
      customerName: addressData.name || currentUser?.name || 'Honored Guest',
      customerPhone: addressData.phone,
      customerEmail: currentUser?.email || 'unregistered@bfc.com',
      address: `${addressData.street}, ${addressData.city}`,
      items: [...cart],
      subtotal,
      deliveryCharge: cms.deliveryCharge,
      discount: discountAmount,
      total,
      status: OrderStatus.PENDING,
      createdAt: new Date().toISOString(),
      paymentMethod,
      paymentDetails: paymentMethod === 'COD' ? null : { provider: paymentMethod }
    };

    showToast('Authorizing Credits', 'info', 'Verifying transaction with neural bank...');
    await new Promise(r => setTimeout(r, 2000));

    setAllOrders(prev => [order, ...prev]);
    setLastOrder(order);
    setCart([]);
    setView('RECEIPT');
    showToast('Mission Dispatched', 'success', 'Order manifest generated successfully.');
  };

  const downloadReceiptImage = async () => {
    if (!receiptRef.current) return;
    const canvas = await html2canvas(receiptRef.current, { 
      scale: 3,
      backgroundColor: '#ffffff',
      useCORS: true
    });
    const link = document.createElement('a');
    link.download = `BFC_Manifest_${lastOrder?.id}.png`;
    link.href = canvas.toDataURL('image/png');
    link.click();
    showToast('Manifest Saved', 'success', 'Receipt image downloaded.');
  };

  const downloadReceiptPDF = async () => {
    if (!receiptRef.current) return;
    const canvas = await html2canvas(receiptRef.current, { scale: 3, backgroundColor: '#ffffff' });
    const imgData = canvas.toDataURL('image/png');
    const pdf = new jsPDF('p', 'mm', 'a4');
    const imgProps = pdf.getImageProperties(imgData);
    const pdfWidth = pdf.internal.pageSize.getWidth();
    const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;
    pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
    pdf.save(`BFC_Manifest_${lastOrder?.id}.pdf`);
    showToast('Document Saved', 'success', 'Receipt PDF generated.');
  };

  if (view === 'ADMIN' && currentUser?.role === UserRole.ADMIN) {
    return <AdminPanel cms={cms} setCms={setCms} menuItems={menuItems} setMenuItems={setMenuItems} orders={allOrders} setOrders={setAllOrders} onLogout={() => { setView('HOME'); setCurrentUser(null); }} />;
  }

  return (
    <div className={`min-h-screen flex flex-col bg-[#020617] text-white selection:bg-red-600/30`}>
      {/* Global Navbar */}
      <nav className={`fixed top-0 inset-x-0 z-[5000] px-6 lg:px-12 py-5 glass flex justify-between items-center transition-all ${view === 'RECEIPT' || view === 'LOGIN' ? 'hidden' : ''}`}>
        <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center font-black shadow-lg group-hover:scale-110 transition-all">B</div>
          <h1 className="text-lg font-black italic uppercase hidden md:block tracking-tighter">{cms.navigation.brand}</h1>
        </div>
        <div className="flex gap-4 items-center">
          <button onClick={() => setView('VAULT')} className="w-10 h-10 glass rounded-xl flex items-center justify-center hover:themed-primary transition-all"><i className="fas fa-user-shield"></i></button>
          <button onClick={() => setView('CART')} className="relative w-10 h-10 glass rounded-xl flex items-center justify-center hover:scale-110 transition-all">
            <i className="fas fa-shopping-bag"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-[8px] w-5 h-5 rounded-full flex items-center justify-center font-black animate-pulse">{cart.length}</span>}
          </button>
          <button onClick={() => setView('LOGIN')} className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center overflow-hidden border-2 border-white/10 shadow-xl">
            {currentUser ? <img src={`https://ui-avatars.com/api/?name=${currentUser.name}&background=random&color=fff`} className="w-full" /> : <i className="fas fa-user"></i>}
          </button>
        </div>
      </nav>

      <main className={`flex-1 flex flex-col pt-24 pb-20`}>
        {view === 'HOME' && (
          <div className="p-6 lg:p-20 space-y-20 animate-elite-up">
             <section className="h-[75vh] rounded-[50px] overflow-hidden relative flex items-center px-10 border border-white/5">
                <img src={cms.hero.image} className="absolute inset-0 w-full h-full object-cover opacity-40 hover:scale-110 transition-all duration-[20s]" />
                <div className="absolute inset-0 bg-gradient-to-r from-black/80 via-black/40 to-transparent"></div>
                <div className="relative z-10 max-w-2xl space-y-8">
                   <div className="inline-block px-6 py-2 glass rounded-full border border-red-600/30">
                      <p className="text-red-600 font-black text-[10px] uppercase tracking-[6px]">{cms.hero.subtitle}</p>
                   </div>
                   <h2 className="text-6xl lg:text-9xl font-black italic uppercase leading-[0.85] tracking-tighter drop-shadow-2xl">{cms.hero.title}</h2>
                   <p className="text-lg lg:text-xl opacity-70 max-w-lg leading-relaxed">{cms.hero.description}</p>
                   <div className="flex gap-4">
                      <Button size="lg" className="rounded-[30px]" onClick={() => setView('MENU')}>{cms.hero.cta}</Button>
                      <Button variant="outline" size="lg" className="rounded-[30px] glass text-white" onClick={() => setView('VAULT')}>VIEW VAULT</Button>
                   </div>
                </div>
             </section>
          </div>
        )}

        {view === 'MENU' && (
          <div className="p-6 lg:p-20 space-y-16 animate-elite-up">
            <div className="text-center space-y-4">
               <h2 className="text-7xl lg:text-[120px] font-black italic uppercase text-center tracking-tighter leading-none">Manifest</h2>
               <p className="text-[10px] font-black uppercase text-red-600 tracking-[15px]">Elite Deployment Registry</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10">
              {menuItems.map(item => (
                <div key={item.id} className="glass p-8 rounded-[50px] group border-white/5 flex flex-col hover:-translate-y-4 transition-all duration-500 shadow-2xl">
                  <div className="h-72 rounded-[40px] overflow-hidden mb-8 relative">
                    <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" />
                    <div className="absolute top-6 right-6 bg-red-600 text-white px-6 py-2 rounded-full text-[12px] font-black shadow-2xl">৳{item.price}</div>
                  </div>
                  <div className="flex-1 space-y-4">
                    <h4 className="text-3xl font-black italic uppercase leading-none">{item.name}</h4>
                    <p className="text-[10px] font-black text-red-600 uppercase tracking-[6px]">{item.category}</p>
                    <p className="text-sm opacity-50 font-medium leading-relaxed line-clamp-2">{item.description}</p>
                  </div>
                  <Button fullWidth className="mt-10 rounded-[25px] py-6 shadow-red-600/20" onClick={() => {
                    setCart(prev => {
                      const ex = prev.find(c => c.item.id === item.id);
                      if (ex) return prev.map(x => x.item.id === item.id ? { ...x, qty: x.qty + 1 } : x);
                      return [...prev, { item, qty: 1 }];
                    });
                    showToast('Secured to Bag', 'success', `${item.name} added to deployment manifest.`);
                  }}>SECURE TO BAG</Button>
                </div>
              ))}
            </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="max-w-2xl mx-auto p-6 w-full space-y-10 animate-elite-up mt-10">
            <div className="text-center space-y-2">
               <h2 className="text-6xl font-black italic uppercase tracking-tighter">My Bag</h2>
               <p className="text-[9px] font-black uppercase opacity-40 tracking-[10px]">Registry Confirmation</p>
            </div>
            {cart.length === 0 ? (
              <div className="text-center opacity-20 py-32 space-y-6">
                <i className="fas fa-shopping-basket text-7xl"></i>
                <p className="uppercase font-black tracking-widest text-xs">Manifest is empty</p>
                <Button variant="outline" className="mt-8 rounded-2xl" onClick={() => setView('MENU')}>RE-LOAD REGISTRY</Button>
              </div>
            ) : (
              <div className="glass p-10 rounded-[50px] space-y-10 shadow-3xl border-white/5">
                <div className="space-y-6">
                  {cart.map((c, i) => (
                    <div key={i} className="flex justify-between items-center border-b border-white/5 pb-6 last:border-0">
                      <div className="flex gap-6 items-center">
                        <div className="w-16 h-16 rounded-2xl overflow-hidden shrink-0 border border-white/10"><img src={c.item.image} className="w-full h-full object-cover" /></div>
                        <div className="space-y-1">
                           <p className="font-black italic uppercase text-lg leading-none">{c.item.name}</p>
                           <div className="flex items-center gap-4 pt-2">
                              <button onClick={() => setCart(prev => prev.map(x => x.item.id === c.item.id ? { ...x, qty: Math.max(0, x.qty - 1) } : x).filter(x => x.qty > 0))} className="w-8 h-8 rounded-xl glass flex items-center justify-center text-[10px]"><i className="fas fa-minus"></i></button>
                              <span className="text-sm font-black">{c.qty}</span>
                              <button onClick={() => setCart(prev => prev.map(x => x.item.id === c.item.id ? { ...x, qty: x.qty + 1 } : x))} className="w-8 h-8 rounded-xl glass flex items-center justify-center text-[10px]"><i className="fas fa-plus"></i></button>
                           </div>
                        </div>
                      </div>
                      <p className="text-2xl font-black italic">৳{c.item.price * c.qty}</p>
                    </div>
                  ))}
                </div>
                <div className="space-y-4 pt-6 border-t border-white/10">
                  <div className="flex justify-between text-[10px] font-black uppercase opacity-40"><span>Subtotal Value</span><span>৳{subtotal}</span></div>
                  <div className="flex justify-between text-[10px] font-black uppercase opacity-40"><span>Logistics Fee</span><span>৳{cms.deliveryCharge}</span></div>
                  <div className="flex justify-between text-4xl font-black italic text-red-600 pt-6 border-t-2 border-white/10"><span>Total Registry</span><span>৳{subtotal + cms.deliveryCharge}</span></div>
                </div>
                <Button fullWidth size="lg" className="rounded-[30px] py-8" onClick={() => {
                  if (!currentUser) { setView('LOGIN'); showToast('Authorization Required', 'info', 'Identity verification needed for deployment.'); }
                  else { setView('CHECKOUT'); setCheckoutStep('ADDRESS'); }
                }}>INITIATE DEPLOYMENT</Button>
              </div>
            )}
          </div>
        )}

        {view === 'CHECKOUT' && (
          <div className="max-w-xl mx-auto p-6 w-full space-y-10 animate-elite-up mt-10">
             <div className="flex justify-center items-center gap-6">
                <div className={`w-4 h-4 rounded-full transition-all ${checkoutStep === 'ADDRESS' ? 'bg-red-600 scale-125 shadow-[0_0_15px_rgba(220,38,38,0.5)]' : 'bg-gray-800'}`}></div>
                <div className="w-16 h-0.5 bg-gray-800 rounded-full"></div>
                <div className={`w-4 h-4 rounded-full transition-all ${checkoutStep === 'PAYMENT' ? 'bg-red-600 scale-125 shadow-[0_0_15px_rgba(220,38,38,0.5)]' : 'bg-gray-800'}`}></div>
             </div>

             {checkoutStep === 'ADDRESS' ? (
               <div className="glass p-12 rounded-[50px] space-y-8 shadow-2xl border-white/5">
                 <div className="space-y-2">
                    <h3 className="text-3xl font-black italic uppercase">Coordinates</h3>
                    <p className="text-[9px] font-black uppercase opacity-40 tracking-[6px]">Deployment Location</p>
                 </div>
                 <div className="space-y-5">
                    <div className="space-y-2">
                       <label className="text-[9px] font-black uppercase tracking-widest opacity-40 ml-4">Personnel Full Name</label>
                       <input value={addressData.name} onChange={e => setAddressData({...addressData, name: e.target.value})} placeholder="COMMANDER NAME" className="w-full glass p-6 rounded-[24px] outline-none border border-white/5 font-black uppercase text-xs focus:border-red-600/50 transition-all" />
                    </div>
                    <div className="space-y-2">
                       <label className="text-[9px] font-black uppercase tracking-widest opacity-40 ml-4">Neural Handset (11 Digits)</label>
                       <input value={addressData.phone} onChange={e => setAddressData({...addressData, phone: e.target.value})} maxLength={11} placeholder="01XXXXXXXXX" className="w-full glass p-6 rounded-[24px] outline-none border border-white/5 font-black text-xs focus:border-red-600/50 transition-all" />
                    </div>
                    <div className="space-y-2">
                       <label className="text-[9px] font-black uppercase tracking-widest opacity-40 ml-4">Sector Address</label>
                       <input value={addressData.street} onChange={e => setAddressData({...addressData, street: e.target.value})} placeholder="HOUSE / ROAD / SECTOR" className="w-full glass p-6 rounded-[24px] outline-none border border-white/5 font-black uppercase text-xs focus:border-red-600/50 transition-all" />
                    </div>
                 </div>
                 <Button fullWidth size="lg" className="rounded-[30px] py-7" onClick={() => {
                   if (!addressData.name || !addressData.phone || !addressData.street) return showToast('Coordinates Missing', 'warning', 'Registry require full deployment details.');
                   if (addressData.phone.length !== 11) return showToast('Invalid Handset', 'warning', 'Phone number must be exactly 11 digits.');
                   setCheckoutStep('PAYMENT');
                 }}>CONTINUE TO AUTHORIZATION</Button>
               </div>
             ) : (
               <div className="glass p-12 rounded-[50px] space-y-10 shadow-2xl border-white/5">
                  <div className="space-y-2">
                    <h3 className="text-3xl font-black italic uppercase">Authorization</h3>
                    <p className="text-[9px] font-black uppercase opacity-40 tracking-[6px]">Secure Credit Transfer</p>
                  </div>

                  {/* Promo Section */}
                  <div className="flex gap-4 glass p-2 rounded-[28px] border-white/5">
                     <input value={promoCode} onChange={e => setPromoCode(e.target.value)} placeholder="PROMO CODE" className="flex-1 bg-transparent p-5 rounded-2xl outline-none font-black text-xs uppercase placeholder:opacity-20" />
                     <button onClick={handleApplyPromo} className="px-10 bg-emerald-600 rounded-2xl font-black text-[10px] uppercase shadow-lg shadow-emerald-600/20 active:scale-95 transition-all">APPLY</button>
                  </div>

                  <div className="space-y-4">
                     <label className="text-[9px] font-black uppercase tracking-widest opacity-40 ml-2">Neural Gateway</label>
                     <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                        {[
                          { id: 'BKASH', icon: 'fa-wallet', label: 'bKash' },
                          { id: 'NAGAD', icon: 'fa-mobile-screen', label: 'Nagad' },
                          { id: 'CARD', icon: 'fa-credit-card', label: 'Card' },
                          { id: 'COD', icon: 'fa-hand-holding-dollar', label: 'COD' }
                        ].map(m => (
                          <button key={m.id} onClick={() => setPaymentMethod(m.id as any)} className={`p-5 rounded-3xl border-2 transition-all flex flex-col items-center gap-3 ${paymentMethod === m.id ? 'border-red-600 bg-red-600/10 shadow-xl' : 'border-white/5 bg-white/5 opacity-40 hover:opacity-100'}`}>
                             <i className={`fas ${m.icon} text-xl`}></i>
                             <span className="text-[8px] font-black uppercase tracking-widest">{m.label}</span>
                          </button>
                        ))}
                     </div>
                  </div>

                  {(paymentMethod === 'BKASH' || paymentMethod === 'NAGAD') && (
                    <div className="space-y-4 animate-elite-up">
                       <input value={paymentFields.number} onChange={e => setPaymentFields({...paymentFields, number: e.target.value})} placeholder={`${paymentMethod} WALLET NUMBER`} className="w-full glass p-6 rounded-[24px] outline-none border border-white/5 font-black text-xs" />
                       <input type="password" value={paymentFields.pin} onChange={e => setPaymentFields({...paymentFields, pin: e.target.value})} placeholder="SECRET PIN" className="w-full glass p-6 rounded-[24px] outline-none border border-white/5 font-black text-xs" />
                    </div>
                  )}

                  {paymentMethod === 'CARD' && (
                    <div className="space-y-4 animate-elite-up">
                       <input value={paymentFields.cardNo} onChange={e => setPaymentFields({...paymentFields, cardNo: e.target.value})} placeholder="CARD MANIFEST NUMBER" className="w-full glass p-6 rounded-[24px] outline-none border border-white/5 font-black text-xs" />
                       <div className="flex gap-4">
                          <input value={paymentFields.expiry} onChange={e => setPaymentFields({...paymentFields, expiry: e.target.value})} placeholder="MM/YY" className="flex-1 glass p-6 rounded-[24px] outline-none border border-white/5 font-black text-xs" />
                          <input value={paymentFields.cvv} onChange={e => setPaymentFields({...paymentFields, cvv: e.target.value})} placeholder="CVV" className="flex-1 glass p-6 rounded-[24px] outline-none border border-white/5 font-black text-xs" />
                       </div>
                    </div>
                  )}

                  <div className="pt-8 border-t border-white/10 space-y-4">
                     <div className="flex justify-between text-xs font-black uppercase opacity-40 tracking-widest"><span>Total Credit Requirement</span><span className="text-white">৳{total}</span></div>
                     <div className="flex justify-between text-3xl font-black italic"><span>Authorize</span><span className="text-red-600">৳{total}</span></div>
                     <Button fullWidth size="lg" className="rounded-[30px] py-8 mt-6" onClick={processPayment}>CONFIRM & DEPLOY</Button>
                  </div>
               </div>
             )}
          </div>
        )}

        {view === 'RECEIPT' && lastOrder && (
          <div className="max-w-2xl mx-auto p-6 w-full animate-elite-up space-y-10">
             <div ref={receiptRef} className="receipt-paper p-10 lg:p-16 relative overflow-hidden flex flex-col gap-10">
                <div className="absolute top-0 right-0 w-40 h-40 bg-red-600 rotate-45 translate-x-20 -translate-y-20 flex items-end justify-center pb-6 shadow-2xl">
                   <span className="text-white font-black text-[12px] -rotate-45 tracking-[4px]">PAID</span>
                </div>

                <div className="text-center space-y-3">
                   <div className="w-16 h-16 bg-red-600 text-white rounded-[20px] flex items-center justify-center font-black text-2xl mx-auto shadow-xl">B</div>
                   <h1 className="text-4xl font-black italic uppercase tracking-tighter text-black">BANGLA FOOD CLUB</h1>
                   <p className="text-[9px] font-black uppercase tracking-[8px] opacity-40 text-black">Legendary Taste Registry</p>
                </div>

                <div className="grid grid-cols-2 gap-10 pt-10 border-t border-black/10">
                   <div className="space-y-2">
                      <p className="text-[9px] font-black uppercase opacity-30 text-black tracking-widest">Personnel Identity</p>
                      <p className="font-black uppercase text-base text-black">{lastOrder.customerName}</p>
                      <p className="text-[10px] font-bold text-red-600">@{currentUser?.username} • {lastOrder.customerPhone}</p>
                      <p className="text-[9px] font-medium opacity-60 text-black max-w-[150px] leading-relaxed uppercase">{lastOrder.address}</p>
                   </div>
                   <div className="text-right space-y-2">
                      <p className="text-[9px] font-black uppercase opacity-30 text-black tracking-widest">Manifest Code</p>
                      <p className="font-black text-base text-black">#{lastOrder.id}</p>
                      <p className="text-[10px] font-bold opacity-60 text-black">{new Date(lastOrder.createdAt).toLocaleString()}</p>
                      <p className="text-[10px] font-black uppercase text-emerald-600">{lastOrder.paymentMethod} PROCESSED</p>
                   </div>
                </div>

                <div className="space-y-6 py-10 border-y border-black/10 border-dashed">
                   <table className="w-full text-black">
                      <thead>
                         <tr className="text-[9px] font-black uppercase opacity-30 text-left">
                            <th className="pb-6 tracking-widest">Registry Unit</th>
                            <th className="pb-6 text-center tracking-widest">Qty</th>
                            <th className="pb-6 text-right tracking-widest">Credit Value</th>
                         </tr>
                      </thead>
                      <tbody>
                         {lastOrder.items.map((c, i) => (
                           <tr key={i} className="font-black text-sm border-b border-black/5 last:border-0">
                              <td className="py-4 uppercase italic">{c.item.name}</td>
                              <td className="py-4 text-center">{c.qty}</td>
                              <td className="py-4 text-right">৳{c.item.price * c.qty}</td>
                           </tr>
                         ))}
                      </tbody>
                   </table>
                </div>

                <div className="space-y-4 pt-4 text-black">
                   <div className="flex justify-between text-[11px] font-black uppercase"><span>Registry Subtotal</span><span>৳{lastOrder.subtotal}</span></div>
                   <div className="flex justify-between text-[11px] font-black uppercase"><span>Logistics Surcharge</span><span>৳{lastOrder.deliveryCharge}</span></div>
                   {lastOrder.discount > 0 && <div className="flex justify-between text-[11px] font-black uppercase text-red-600"><span>Neural Discount</span><span>- ৳{lastOrder.discount}</span></div>}
                   <div className="flex justify-between text-[11px] font-black uppercase opacity-40"><span>V.A.T (0%)</span><span>৳0</span></div>
                   <div className="flex justify-between text-4xl font-black italic pt-10 border-t-4 border-black tracking-tighter"><span>Total Verified</span><span>৳{lastOrder.total}</span></div>
                </div>

                <div className="text-center pt-10 space-y-6">
                   <div className="w-28 h-28 mx-auto opacity-10 flex items-center justify-center border-4 border-black rounded-3xl p-4">
                      <i className="fas fa-qrcode text-7xl"></i>
                   </div>
                   <div className="space-y-1">
                      <p className="text-[9px] font-black uppercase tracking-[6px] opacity-40 text-black">Mission Complete</p>
                      <p className="text-[8px] font-medium opacity-30 text-black">Thank you for choosing BFC Elite Protocols.</p>
                   </div>
                </div>
             </div>

             <div className="grid grid-cols-2 gap-4">
                <Button fullWidth className="rounded-2xl py-6 glass text-white bg-blue-600/20" onClick={downloadReceiptImage}><i className="fas fa-image mr-3"></i> IMAGE</Button>
                <Button fullWidth className="rounded-2xl py-6 glass text-white bg-red-600/20" onClick={downloadReceiptPDF}><i className="fas fa-file-pdf mr-3"></i> PDF</Button>
             </div>
             <Button fullWidth className="rounded-[30px] py-8" onClick={() => setView('HOME')}>RETURN TO CORE DASHBOARD</Button>
          </div>
        )}

        {view === 'VAULT' && currentUser && (
          <div className="max-w-4xl mx-auto p-6 w-full space-y-12 animate-elite-up mt-10">
             <div className="glass p-12 rounded-[60px] flex flex-col lg:flex-row items-center gap-12 border-white/5 shadow-3xl">
                <div className="w-40 h-40 themed-primary rounded-[45px] flex items-center justify-center text-6xl font-black border-8 border-white/5 shadow-2xl relative">
                   <img src={`https://ui-avatars.com/api/?name=${currentUser.name}&background=random&color=fff&size=512`} className="w-full h-full object-cover rounded-[35px]" />
                   <div className="absolute -bottom-4 -right-4 bg-red-600 w-12 h-12 rounded-2xl flex items-center justify-center text-lg border-4 border-[#020617]"><i className="fas fa-shield-check"></i></div>
                </div>
                <div className="flex-1 text-center lg:text-left space-y-5">
                   <div className="inline-block px-5 py-1.5 bg-emerald-600/20 text-emerald-400 rounded-full text-[10px] font-black uppercase tracking-widest border border-emerald-400/20 shadow-lg shadow-emerald-600/10">{currentUser.tier} PERSONNEL</div>
                   <h3 className="text-5xl lg:text-6xl font-black italic uppercase leading-none tracking-tighter">{currentUser.name}</h3>
                   <div className="flex flex-wrap justify-center lg:justify-start gap-4">
                      <p className="text-red-600 font-black tracking-[4px] text-xs uppercase">@{currentUser.username}</p>
                      <span className="opacity-20">•</span>
                      <p className="text-[11px] font-black uppercase opacity-40">{currentUser.email}</p>
                   </div>
                </div>
                <div className="glass p-10 rounded-[45px] text-center min-w-[240px] border-white/10">
                   <p className="text-[10px] font-black uppercase opacity-40 mb-3 tracking-[5px]">Pulse Points</p>
                   <p className="text-5xl font-black italic text-red-600 leading-none">{currentUser.loyaltyPoints}</p>
                   <p className="text-[8px] font-bold opacity-30 uppercase mt-4">Redeemable in Registry</p>
                </div>
             </div>

             <div className="space-y-10">
                <div className="flex items-center justify-between border-b border-white/5 pb-6">
                   <h4 className="text-3xl font-black italic uppercase tracking-widest">Mission Archive</h4>
                   <p className="text-[10px] font-black uppercase opacity-40">{allOrders.filter(o => o.customerId === currentUser.id).length} Entries Found</p>
                </div>
                <div className="grid gap-8">
                   {allOrders.filter(o => o.customerId === currentUser.id).length > 0 ? (
                     allOrders.filter(o => o.customerId === currentUser.id).map(o => (
                       <div key={o.id} onClick={() => { setLastOrder(o); setView('RECEIPT'); }} className="glass p-10 rounded-[45px] flex flex-col sm:flex-row justify-between items-center cursor-pointer group hover:border-red-600/40 transition-all border border-white/5 shadow-xl hover:-translate-y-2">
                          <div className="flex gap-8 items-center w-full sm:w-auto">
                             <div className="w-16 h-16 glass rounded-2xl flex items-center justify-center text-2xl group-hover:bg-red-600 group-hover:text-white transition-all shadow-inner"><i className="fas fa-receipt opacity-40 group-hover:opacity-100"></i></div>
                             <div>
                                <p className="text-[10px] font-black opacity-30 uppercase tracking-[4px]">#{o.id}</p>
                                <p className="font-black italic uppercase text-xl leading-none pt-1">{new Date(o.createdAt).toLocaleDateString()}</p>
                                <p className="text-[10px] font-black uppercase opacity-40 mt-2">{o.items.length} Units Deployed</p>
                             </div>
                          </div>
                          <div className="text-center sm:text-right w-full sm:w-auto mt-6 sm:mt-0 pt-6 sm:pt-0 border-t sm:border-t-0 border-white/5">
                             <p className="text-3xl font-black italic">৳{o.total}</p>
                             <div className="flex items-center justify-center sm:justify-end gap-2 mt-1">
                                <div className={`w-2 h-2 rounded-full ${o.status === OrderStatus.DELIVERED ? 'bg-emerald-500' : 'bg-amber-500'}`}></div>
                                <p className={`text-[10px] font-black uppercase tracking-widest ${o.status === OrderStatus.DELIVERED ? 'text-emerald-500' : 'text-amber-500'}`}>{o.status}</p>
                             </div>
                          </div>
                       </div>
                     ))
                   ) : (
                     <div className="text-center py-20 opacity-20 space-y-4">
                        <i className="fas fa-satellite-dish text-5xl"></i>
                        <p className="font-black uppercase text-[10px] tracking-widest">No prior mission logs detected</p>
                     </div>
                   )}
                </div>
             </div>
          </div>
        )}

        {view === 'LOGIN' && (
          <div className="flex-1 flex flex-col items-center justify-center p-8 bg-[#020617]">
             <div className="w-full max-w-lg glass p-12 rounded-[60px] space-y-12 animate-elite-up shadow-3xl border-white/5">
                <div className="text-center space-y-6">
                   <div className="w-20 h-20 bg-red-600 rounded-[30px] flex items-center justify-center text-3xl font-black mx-auto shadow-2xl shadow-red-600/40"><i className="fas fa-fingerprint"></i></div>
                   <div className="space-y-2">
                      <h3 className="text-5xl font-black italic uppercase tracking-tighter leading-none">{authMode === 'LOGIN' ? 'Identity Access' : 'New Registry'}</h3>
                      <p className="text-[10px] font-black uppercase text-red-600 tracking-[8px]">Authorization Required</p>
                   </div>
                   <div className="flex p-2 glass rounded-[30px] border-white/5">
                      <button onClick={() => setAuthMode('LOGIN')} className={`flex-1 py-4 rounded-[22px] text-[10px] font-black uppercase tracking-widest transition-all ${authMode === 'LOGIN' ? 'bg-red-600 text-white shadow-xl' : 'text-gray-500 opacity-40 hover:opacity-100'}`}>Check-In</button>
                      <button onClick={() => setAuthMode('REGISTER')} className={`flex-1 py-4 rounded-[22px] text-[10px] font-black uppercase tracking-widest transition-all ${authMode === 'REGISTER' ? 'bg-red-600 text-white shadow-xl' : 'text-gray-500 opacity-40 hover:opacity-100'}`}>Establish Entry</button>
                   </div>
                </div>
                <div className="space-y-6">
                   {authMode === 'REGISTER' && (
                     <div className="space-y-2">
                        <label className="text-[9px] font-black uppercase tracking-widest opacity-40 ml-4">Legal Personnel Name</label>
                        <input value={regName} onChange={e => setRegName(e.target.value)} placeholder="ARIF HOSSAIN" className="w-full glass p-6 rounded-[24px] outline-none border border-white/5 font-black uppercase text-xs focus:border-red-600/50 transition-all" />
                     </div>
                   )}
                   <div className="space-y-2">
                      <label className="text-[9px] font-black uppercase tracking-widest opacity-40 ml-4">Neural Identification (Email)</label>
                      <input value={loginId} onChange={e => setLoginId(e.target.value)} placeholder="PERSONNEL@BFC.COM" className="w-full glass p-6 rounded-[24px] outline-none border border-white/5 font-black text-xs focus:border-red-600/50 transition-all" />
                   </div>
                </div>
                <div className="pt-6 space-y-6">
                   <Button fullWidth size="lg" className="rounded-[30px] py-10 shadow-2xl shadow-red-600/20" onClick={() => {
                      if (!loginId) return showToast('Identity Missing', 'warning', 'Authentication require neural handle.');
                      const isAdmin = loginId.toLowerCase().includes('admin');
                      const u: User = {
                        id: 'U-' + Math.random().toString(36).slice(2, 7),
                        name: authMode === 'REGISTER' ? regName : (isAdmin ? 'Admin Commander' : 'Honored Guest'),
                        username: isAdmin ? 'admin' : 'guest_' + Math.random().toString(36).slice(2,6),
                        hasCustomizedUsername: false,
                        email: loginId,
                        role: isAdmin ? UserRole.ADMIN : UserRole.CUSTOMER,
                        loyaltyPoints: 1250,
                        tier: isAdmin ? 'COMMANDER' : 'GOLD',
                        claimedVouchers: []
                      };
                      setCurrentUser(u);
                      isAdmin ? setView('ADMIN') : setView('HOME');
                      showToast('Authorized Access', 'success', `Welcome back, ${u.name}. System synchronization complete.`);
                   }}>{authMode === 'LOGIN' ? 'VALIDATE IDENTITY' : 'CREATE REGISTRY'}</Button>
                   <button onClick={() => setView('HOME')} className="w-full text-center text-[10px] font-black uppercase tracking-[8px] text-gray-600 hover:text-white transition-all py-4">Return to Public Interface</button>
                </div>
             </div>
          </div>
        )}
      </main>

      {/* Global Mobile Nav */}
      {view !== 'RECEIPT' && view !== 'LOGIN' && (
        <nav className="fixed bottom-0 inset-x-0 z-[6000] lg:hidden glass border-t border-white/5 flex justify-around items-center h-24 safe-bottom shadow-2xl">
           {[
             { id: 'HOME', icon: 'fa-home', label: 'Core' },
             { id: 'MENU', icon: 'fa-utensils', label: 'Menu' },
             { id: 'CART', icon: 'fa-shopping-bag', label: 'Bag' },
             { id: 'VAULT', icon: 'fa-shield-halved', label: 'Vault' }
           ].map(item => (
             <button key={item.id} onClick={() => setView(item.id as any)} className={`flex flex-col items-center gap-2 w-full transition-all ${view === item.id ? 'text-red-600 scale-110' : 'text-gray-500 opacity-40'}`}>
                <i className={`fas ${item.icon} text-xl`}></i>
                <span className="text-[9px] font-black uppercase tracking-[4px]">{item.label}</span>
             </button>
           ))}
        </nav>
      )}

      {/* Persistent ChatBot */}
      {view !== 'RECEIPT' && <ChatBot isOnline={!isOffline} currentUser={currentUser} menuItems={menuItems} />}

      {/* Toast Overlay */}
      <div className="fixed top-24 right-4 z-[10000] space-y-4 max-w-sm w-full pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto bg-gray-950/90 backdrop-blur-2xl p-7 rounded-[35px] animate-elite-up border-l-4 border-red-600 shadow-2xl ring-1 ring-white/5">
            <div className="flex items-center gap-4">
               <div className={`w-8 h-8 rounded-xl flex items-center justify-center text-xs text-white ${t.type === 'error' ? 'bg-red-600' : t.type === 'warning' ? 'bg-amber-600' : 'bg-emerald-600'}`}>
                  <i className={`fas ${t.type === 'error' ? 'fa-bolt' : t.type === 'warning' ? 'fa-exclamation' : 'fa-check'}`}></i>
               </div>
               <div>
                  <p className="text-[10px] font-black uppercase tracking-widest text-white">{t.message}</p>
                  {t.description && <p className="text-[9px] opacity-60 mt-1 leading-relaxed text-gray-400 font-medium">{t.description}</p>}
               </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { MenuItem, UserRole, User, Order, CartItem, SiteCMS, OrderStatus, Promotion } from './types';
import { MOCK_MENU, MOCK_ORDERS, DEFAULT_THEMES } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';
import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';

interface Toast {
  id: number;
  message: string;
  description?: string;
  type: 'success' | 'error' | 'warning' | 'info';
}

const DEFAULT_CMS: SiteCMS = {
  activeLayout: 'ELITE_DARK',
  themeDefinitions: DEFAULT_THEMES,
  deliveryCharge: 50,
  hero: {
    title: "Experience Elite Bangladeshi Cuisine",
    subtitle: "The Real Taste Of Bangla",
    description: "Indulge in the finest culinary heritage of Bangladesh. Where tradition meets high-tech precision in every bite.",
    image: "https://images.unsplash.com/photo-1633945274405-b6c8069047b0?q=80&w=2000",
    cta: "ACCESS REGISTRY"
  },
  navigation: {
    brand: "BFC ELITE",
    links: { home: "HOME", menu: "MENU", vault: "VAULT", profile: "PROFILE" }
  },
  vault: {
    title: "ELITE VAULT",
    description: "Manage your credits and unlock secret menu deployments."
  }
};

const App: React.FC = () => {
  const [cms, setCms] = useState<SiteCMS>(() => {
    const saved = localStorage.getItem('bfc_cms');
    return saved ? JSON.parse(saved) : DEFAULT_CMS;
  });
  const [menuItems, setMenuItems] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('bfc_menu');
    return saved ? JSON.parse(saved) : MOCK_MENU;
  });
  const [allOrders, setAllOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('bfc_orders');
    return saved ? JSON.parse(saved) : MOCK_ORDERS;
  });
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });
  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('bfc_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT' | 'CHECKOUT' | 'RECEIPT'>('HOME');
  const [checkoutStep, setCheckoutStep] = useState<'ADDRESS' | 'PAYMENT'>('ADDRESS');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [lastOrder, setLastOrder] = useState<Order | null>(null);

  // Form States
  const [addressData, setAddressData] = useState({ name: '', phone: '', city: 'Dhaka', street: '' });
  const [promoCode, setPromoCode] = useState('');
  const [activePromo, setActivePromo] = useState<Promotion | null>(null);
  const [paymentMethod, setPaymentMethod] = useState<'BKASH' | 'NAGAD' | 'CARD' | 'COD'>('BKASH');
  const [paymentFields, setPaymentFields] = useState({ number: '', pin: '', cardNo: '', expiry: '', cvv: '' });
  const [loginId, setLoginId] = useState('');
  const [regName, setRegName] = useState('');

  const receiptRef = useRef<HTMLDivElement>(null);

  const showToast = useCallback((message: string, type: Toast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, description }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 6000);
  }, []);

  useEffect(() => {
    const handleOnline = () => { setIsOffline(false); showToast('Link Restored', 'success', 'Neural core synchronized.'); };
    const handleOffline = () => { setIsOffline(true); showToast('Link Severed', 'error', 'Working in offline mode.'); };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [showToast]);

  useEffect(() => { localStorage.setItem('bfc_cms', JSON.stringify(cms)); }, [cms]);
  useEffect(() => { localStorage.setItem('bfc_menu', JSON.stringify(menuItems)); }, [menuItems]);
  useEffect(() => { localStorage.setItem('bfc_orders', JSON.stringify(allOrders)); }, [allOrders]);
  useEffect(() => { localStorage.setItem('bfc_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { localStorage.setItem('bfc_user', JSON.stringify(currentUser)); }, [currentUser]);

  const subtotal = useMemo(() => cart.reduce((a, b) => a + (b.item.price * b.qty), 0), [cart]);
  const discountAmount = useMemo(() => {
    if (!activePromo) return 0;
    return activePromo.discountType === 'PERCENTAGE' 
      ? (subtotal * activePromo.discountValue) / 100 
      : activePromo.discountValue;
  }, [subtotal, activePromo]);
  const total = subtotal + cms.deliveryCharge - discountAmount;

  const handleApplyPromo = () => {
    const preCodes: Promotion[] = [
      { id: '1', name: 'Welcome', code: 'BFC50', discountType: 'FIXED', discountValue: 50, startDate: '', endDate: '', usageLimit: 100, usageCount: 0, isActive: true },
      { id: '2', name: 'Elite', code: 'ELITE20', discountType: 'PERCENTAGE', discountValue: 20, startDate: '', endDate: '', usageLimit: 100, usageCount: 0, isActive: true }
    ];
    const found = preCodes.find(p => p.code === promoCode.toUpperCase() && p.isActive);
    if (found) {
      setActivePromo(found);
      showToast('Promo Secured', 'success', `Discount of ৳${found.discountValue}${found.discountType === 'PERCENTAGE' ? '%' : ''} applied.`);
    } else {
      showToast('Invalid Code', 'error', 'Transmission code not recognized.');
    }
  };

  const processPayment = async () => {
    if (isOffline) return showToast('Deployment Error', 'error', 'Neural link is offline.');

    // Validate Phone (11 digits, BD format)
    const phoneRegex = /^01[3-9]\d{8}$/;
    if (!phoneRegex.test(addressData.phone)) {
      return showToast('Invalid Identification', 'warning', 'Phone number must be 11 digits (e.g., 01700000000).');
    }

    if ((paymentMethod === 'BKASH' || paymentMethod === 'NAGAD') && (!paymentFields.number || !paymentFields.pin)) {
      return showToast('Missing Protocols', 'warning', 'Wallet number and secure PIN required.');
    }

    if (paymentMethod === 'CARD' && (!paymentFields.cardNo || !paymentFields.cvv)) {
      return showToast('Insecure Data', 'warning', 'Full card manifest required for credit transfer.');
    }

    const order: Order = {
      id: 'BFC-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
      customerId: currentUser?.id || 'GUEST',
      customerName: addressData.name || currentUser?.name || 'Honored Guest',
      customerPhone: addressData.phone,
      customerEmail: currentUser?.email || 'unregistered@bfc.com',
      address: `${addressData.street}, ${addressData.city}`,
      items: [...cart],
      subtotal,
      deliveryCharge: cms.deliveryCharge,
      discount: discountAmount,
      total,
      status: OrderStatus.PENDING,
      createdAt: new Date().toISOString(),
      paymentMethod,
      paymentDetails: paymentMethod === 'COD' ? null : { provider: paymentMethod }
    };

    showToast('Authorizing Credits', 'info', 'Verifying transaction with neural bank...');
    await new Promise(r => setTimeout(r, 2000));

    setAllOrders(prev => [order, ...prev]);
    setLastOrder(order);
    setCart([]);
    setView('RECEIPT');
    showToast('Mission Dispatched', 'success', 'Order manifest generated successfully.');
  };

  const downloadReceiptImage = async () => {
    if (!receiptRef.current) return;
    const canvas = await html2canvas(receiptRef.current, { 
      scale: 3,
      backgroundColor: '#ffffff',
      useCORS: true
    });
    const link = document.createElement('a');
    link.download = `BFC_Manifest_${lastOrder?.id}.png`;
    link.href = canvas.toDataURL('image/png');
    link.click();
    showToast('Manifest Saved', 'success', 'Receipt image downloaded.');
  };

  const downloadReceiptPDF = async () => {
    if (!receiptRef.current) return;
    const canvas = await html2canvas(receiptRef.current, { scale: 3, backgroundColor: '#ffffff' });
    const imgData = canvas.toDataURL('image/png');
    const pdf = new jsPDF('p', 'mm', 'a4');
    const imgProps = pdf.getImageProperties(imgData);
    const pdfWidth = pdf.internal.pageSize.getWidth();
    const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;
    pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
    pdf.save(`BFC_Manifest_${lastOrder?.id}.pdf`);
    showToast('Document Saved', 'success', 'Receipt PDF generated.');
  };

  if (view === 'ADMIN' && currentUser?.role === UserRole.ADMIN) {
    return <AdminPanel cms={cms} setCms={setCms} menuItems={menuItems} setMenuItems={setMenuItems} orders={allOrders} setOrders={setAllOrders} onLogout={() => { setView('HOME'); setCurrentUser(null); }} />;
  }

  return (
    <div className={`min-h-screen flex flex-col bg-[#020617] text-white selection:bg-red-600/30`}>
      {/* Global Navbar */}
      <nav className={`fixed top-0 inset-x-0 z-[5000] px-6 lg:px-12 py-5 glass flex justify-between items-center transition-all ${view === 'RECEIPT' || view === 'LOGIN' ? 'hidden' : ''}`}>
        <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center font-black shadow-lg group-hover:scale-110 transition-all">B</div>
          <h1 className="text-lg font-black italic uppercase hidden md:block tracking-tighter">{cms.navigation.brand}</h1>
        </div>
        <div className="flex gap-4 items-center">
          <button onClick={() => setView('VAULT')} className="w-10 h-10 glass rounded-xl flex items-center justify-center hover:themed-primary transition-all"><i className="fas fa-user-shield"></i></button>
          <button onClick={() => setView('CART')} className="relative w-10 h-10 glass rounded-xl flex items-center justify-center hover:scale-110 transition-all">
            <i className="fas fa-shopping-bag"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-[8px] w-5 h-5 rounded-full flex items-center justify-center font-black animate-pulse">{cart.length}</span>}
          </button>
          <button onClick={() => setView('LOGIN')} className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center overflow-hidden border-2 border-white/10 shadow-xl">
            {currentUser ? <img src={`https://ui-avatars.com/api/?name=${currentUser.name}&background=random&color=fff`} className="w-full" /> : <i className="fas fa-user"></i>}
          </button>
        </div>
      </nav>

      <main className={`flex-1 flex flex-col pt-24 pb-20`}>
        {view === 'HOME' && (
          <div className="p-6 lg:p-20 space-y-20 animate-elite-up">
             <section className="h-[75vh] rounded-[50px] overflow-hidden relative flex items-center px-10 border border-white/5">
                <img src={cms.hero.image} className="absolute inset-0 w-full h-full object-cover opacity-40 hover:scale-110 transition-all duration-[20s]" />
                <div className="absolute inset-0 bg-gradient-to-r from-black/80 via-black/40 to-transparent"></div>
                <div className="relative z-10 max-w-2xl space-y-8">
                   <div className="inline-block px-6 py-2 glass rounded-full border border-red-600/30">
                      <p className="text-red-600 font-black text-[10px] uppercase tracking-[6px]">{cms.hero.subtitle}</p>
                   </div>
