                              className="w-full glass bg-white/5 p-6 pl-14 rounded-[28px] outline-none border border-white/5 font-black text-xs focus:border-red-600/50 transition-all focus:bg-white/10" 
                            />
                         </div>
                      </div>
                   </div>

                   {/* Footer Actions */}
                   <div className="pt-6 space-y-8">
                      <Button 
                        fullWidth 
                        size="lg" 
                        className="rounded-[35px] py-9 shadow-[0_20px_50px_rgba(220,38,38,0.3)] group overflow-hidden relative" 
                        onClick={() => {
                           if (!loginId) return showToast('Identity Missing', 'warning', 'Authentication requires neural handle.');
                           const isAdmin = loginId.toLowerCase().includes('admin');
                           const u: User = {
                             id: 'U-' + Math.random().toString(36).slice(2, 7),
                             name: authMode === 'REGISTER' ? regName : (isAdmin ? 'Admin Commander' : 'Honored Guest'),
                             username: isAdmin ? 'admin' : 'guest_' + Math.random().toString(36).slice(2,6),
                             hasCustomizedUsername: false,
                             email: loginId,
                             role: isAdmin ? UserRole.ADMIN : UserRole.CUSTOMER,
                             loyaltyPoints: 1250,
                             tier: isAdmin ? 'COMMANDER' : 'GOLD',
                             claimedVouchers: []
                           };
                           setCurrentUser(u);
                           isAdmin ? setView('ADMIN') : setView('HOME');
                           showToast('Authorized Access', 'success', `Welcome, ${u.name}. Neural link established.`);
                        }}
                      >
                        <span className="relative z-10">{authMode === 'LOGIN' ? 'VALIDATE IDENTITY' : 'ESTABLISH ENTRY'}</span>
                        <div className="absolute inset-0 bg-white/10 translate-y-full group-hover:translate-y-0 transition-transform duration-500"></div>
                      </Button>

                      <div className="text-center">
                         <button 
                           onClick={() => setView('HOME')} 
                           className="text-[9px] font-black uppercase tracking-[8px] text-gray-600 hover:text-white transition-all py-2 hover:tracking-[10px] duration-500"
                         >
                           Return to Interface
                         </button>
                      </div>
                   </div>
                </div>

                {/* Trust Badges */}
                <div className="mt-12 flex justify-center gap-8 opacity-20 grayscale hover:grayscale-0 hover:opacity-50 transition-all duration-700">
                   <i className="fas fa-shield-halved text-2xl"></i>
                   <i className="fas fa-microchip text-2xl"></i>
                   <i className="fas fa-lock text-2xl"></i>
                </div>
             </div>
          </div>
        )}
      </main>

      {/* Global Mobile Nav */}
      {view !== 'RECEIPT' && view !== 'LOGIN' && (
        <nav className="fixed bottom-0 inset-x-0 z-[6000] lg:hidden glass border-t border-white/5 flex justify-around items-center h-24 safe-bottom shadow-2xl">
           {[
             { id: 'HOME', icon: 'fa-home', label: 'Core' },
             { id: 'MENU', icon: 'fa-utensils', label: 'Menu' },
             { id: 'CART', icon: 'fa-shopping-bag', label: 'Bag' },
             { id: 'VAULT', icon: 'fa-shield-halved', label: 'Vault' }
           ].map(item => (
             <button key={item.id} onClick={() => setView(item.id as any)} className={`flex flex-col items-center gap-2 w-full transition-all ${view === item.id ? 'text-red-600 scale-110' : 'text-gray-500 opacity-40'}`}>
                <i className={`fas ${item.icon} text-xl`}></i>
                <span className="text-[9px] font-black uppercase tracking-[4px]">{item.label}</span>
             </button>
           ))}
        </nav>
      )}

      {/* Persistent ChatBot */}
      {view !== 'RECEIPT' && <ChatBot isOnline={!isOffline} currentUser={currentUser} menuItems={menuItems} />}

      {/* Toast Overlay */}
      <div className="fixed top-24 right-4 z-[10000] space-y-4 max-w-sm w-full pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto bg-gray-950/90 backdrop-blur-2xl p-7 rounded-[35px] animate-elite-up border-l-4 border-red-600 shadow-2xl ring-1 ring-white/5">
            <div className="flex items-center gap-4">
               <div className={`w-8 h-8 rounded-xl flex items-center justify-center text-xs text-white ${t.type === 'error' ? 'bg-red-600' : t.type === 'warning' ? 'bg-amber-600' : 'bg-emerald-600'}`}>
                  <i className={`fas ${t.type === 'error' ? 'fa-bolt' : t.type === 'warning' ? 'fa-exclamation' : 'fa-check'}`}></i>
               </div>
               <div>
                  <p className="text-[10px] font-black uppercase tracking-widest text-white">{t.message}</p>
                  {t.description && <p className="text-[9px] opacity-60 mt-1 leading-relaxed text-gray-400 font-medium">{t.description}</p>}
               </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;

export enum UserRole {
  ADMIN = 'ADMIN',
  MANAGER = 'MANAGER',
  STAFF = 'STAFF',
  CUSTOMER = 'CUSTOMER'
}

export enum OrderStatus {
  PENDING = 'PENDING',
  PREPARING = 'PREPARING',
  READY = 'READY',
  ON_THE_WAY = 'ON_THE_WAY',
  DELIVERED = 'DELIVERED',
  CANCELLED = 'CANCELLED'
}

export type LayoutPreset = 
  | 'ELITE_DARK' 
  | 'CLASSIC_RED' 
  | 'BFC_CLASSIC'
  | 'CYBER_NEON' 
  | 'MINIMAL_WHITE' 
  | 'NATURE_GREEN' 
  | 'LUXURY_GOLD' 
  | 'RETRO_VIBE' 
  | 'BOLD_MONO' 
  | 'PASTEL_SOFT' 
  | 'HIGH_TECH';

export interface ThemeConfig {
  bg: string;
  fg: string;
  primary: string;
  accent: string;
  card: string;
  border: string;
  font: string;
  shadow: string;
}

export interface Promotion {
  id: string;
  name: string;
  code: string;
  discountType: 'PERCENTAGE' | 'FIXED';
  discountValue: number;
  startDate: string;
  endDate: string;
  usageLimit: number;
  usageCount: number;
  isActive: boolean;
}

export interface LoyaltyTier {
  id: string;
  name: string;
  minPoints: number;
  benefits: string[];
  color: string;
}

export interface SiteCMS {
  activeLayout: LayoutPreset;
  themeDefinitions: Record<LayoutPreset, ThemeConfig>;
  deliveryCharge: number;
  hero: {
    title: string;
    subtitle: string;
    description: string;
    image: string;
    cta: string;
  };
  navigation: {
    brand: string;
    links: { [key: string]: string };
  };
  vault: {
    title: string;
    description: string;
  };
}

export interface MenuItem {
  id: string;
  name: string;
  nameBn: string;
  description: string;
  price: number;
  category: string;
  image: string;
  stock: number;
  rating?: number;
  ingredients?: string[];
  dietary?: string[];
  prepTime?: string;
  isPopular?: boolean;
}

export interface CartItem {
  item: MenuItem;
  qty: number;
}

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  customerPhone: string;
  customerEmail: string;
  address: string;
  items: CartItem[];
  subtotal: number;
  deliveryCharge: number;
  discount: number;
  total: number;
  status: OrderStatus;
  createdAt: string;
  paymentMethod: string;
  paymentDetails?: any;
}

export interface User {
  id: string;
  name: string;
  username: string;
  hasCustomizedUsername: boolean;
  email: string;
  role: UserRole;
  loyaltyPoints: number;
  tier: string;
  claimedVouchers?: string[];
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { MenuItem, UserRole, User, Order, CartItem, SiteCMS, OrderStatus, Promotion } from './types';
import { MOCK_MENU, MOCK_ORDERS, DEFAULT_THEMES } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';
import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';

interface Toast {
  id: number;
  message: string;
  description?: string;
  type: 'success' | 'error' | 'warning' | 'info';
}

const DEFAULT_CMS: SiteCMS = {
  activeLayout: 'ELITE_DARK',
  themeDefinitions: DEFAULT_THEMES,
  deliveryCharge: 50,
  hero: {
    title: "Experience Elite Bangladeshi Cuisine",
    subtitle: "The Real Taste Of Bangla",
    description: "Indulge in the finest culinary heritage of Bangladesh. Where tradition meets high-tech precision in every bite.",
    image: "https://images.unsplash.com/photo-1633945274405-b6c8069047b0?q=80&w=2000",
    cta: "ACCESS REGISTRY"
  },
  navigation: {
    brand: "BFC ELITE",
    links: { home: "HOME", menu: "MENU", vault: "VAULT", profile: "PROFILE" }
  },
  vault: {
    title: "ELITE VAULT",
    description: "Manage your credits and unlock secret menu deployments."
  }
};

const App: React.FC = () => {
  const [cms, setCms] = useState<SiteCMS>(() => {
    const saved = localStorage.getItem('bfc_cms');
    return saved ? JSON.parse(saved) : DEFAULT_CMS;
  });
  const [menuItems, setMenuItems] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('bfc_menu');
    return saved ? JSON.parse(saved) : MOCK_MENU;
  });
  const [allOrders, setAllOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('bfc_orders');
    return saved ? JSON.parse(saved) : MOCK_ORDERS;
  });
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });
  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('bfc_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT' | 'CHECKOUT' | 'RECEIPT'>('HOME');
  const [checkoutStep, setCheckoutStep] = useState<'ADDRESS' | 'PAYMENT'>('ADDRESS');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [lastOrder, setLastOrder] = useState<Order | null>(null);

  // Form States
  const [addressData, setAddressData] = useState({ name: '', phone: '', city: 'Dhaka', street: '' });
  const [promoCode, setPromoCode] = useState('');
  const [activePromo, setActivePromo] = useState<Promotion | null>(null);
  const [paymentMethod, setPaymentMethod] = useState<'BKASH' | 'NAGAD' | 'CARD' | 'COD'>('BKASH');
  const [paymentFields, setPaymentFields] = useState({ number: '', pin: '', cardNo: '', expiry: '', cvv: '' });
  const [loginId, setLoginId] = useState('');
  const [regName, setRegName] = useState('');

  const receiptRef = useRef<HTMLDivElement>(null);

  const showToast = useCallback((message: string, type: Toast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, description }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 6000);
  }, []);

  useEffect(() => {
    const handleOnline = () => { setIsOffline(false); showToast('Link Restored', 'success', 'Neural core synchronized.'); };
    const handleOffline = () => { setIsOffline(true); showToast('Link Severed', 'error', 'Working in offline mode.'); };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [showToast]);

  useEffect(() => { localStorage.setItem('bfc_cms', JSON.stringify(cms)); }, [cms]);
  useEffect(() => { localStorage.setItem('bfc_menu', JSON.stringify(menuItems)); }, [menuItems]);
  useEffect(() => { localStorage.setItem('bfc_orders', JSON.stringify(allOrders)); }, [allOrders]);
  useEffect(() => { localStorage.setItem('bfc_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { localStorage.setItem('bfc_user', JSON.stringify(currentUser)); }, [currentUser]);

  const subtotal = useMemo(() => cart.reduce((a, b) => a + (b.item.price * b.qty), 0), [cart]);
  const discountAmount = useMemo(() => {
    if (!activePromo) return 0;
    return activePromo.discountType === 'PERCENTAGE' 
      ? (subtotal * activePromo.discountValue) / 100 
      : activePromo.discountValue;
  }, [subtotal, activePromo]);
  const total = subtotal + cms.deliveryCharge - discountAmount;

  const handleApplyPromo = () => {
    const preCodes: Promotion[] = [
      { id: '1', name: 'Welcome', code: 'BFC50', discountType: 'FIXED', discountValue: 50, startDate: '', endDate: '', usageLimit: 100, usageCount: 0, isActive: true },
      { id: '2', name: 'Elite', code: 'ELITE20', discountType: 'PERCENTAGE', discountValue: 20, startDate: '', endDate: '', usageLimit: 100, usageCount: 0, isActive: true }
    ];
    const found = preCodes.find(p => p.code === promoCode.toUpperCase() && p.isActive);
    if (found) {
      setActivePromo(found);
      showToast('Promo Secured', 'success', `Discount of ৳${found.discountValue}${found.discountType === 'PERCENTAGE' ? '%' : ''} applied.`);
    } else {
      showToast('Invalid Code', 'error', 'Transmission code not recognized.');
    }
  };

  const processPayment = async () => {
    if (isOffline) return showToast('Deployment Error', 'error', 'Neural link is offline.');

    const phoneRegex = /^01[3-9]\d{8}$/;
    if (!phoneRegex.test(addressData.phone)) {
      return showToast('Invalid Identification', 'warning', 'Phone number must be 11 digits (e.g., 01700000000).');
    }

    if ((paymentMethod === 'BKASH' || paymentMethod === 'NAGAD') && (!paymentFields.number || !paymentFields.pin)) {
      return showToast('Missing Protocols', 'warning', 'Wallet number and secure PIN required.');
    }

    if (paymentMethod === 'CARD' && (!paymentFields.cardNo || !paymentFields.cvv)) {
      return showToast('Insecure Data', 'warning', 'Full card manifest required for credit transfer.');
    }

    const order: Order = {
      id: 'BFC-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
      customerId: currentUser?.id || 'GUEST',
      customerName: addressData.name || currentUser?.name || 'Honored Guest',
      customerPhone: addressData.phone,
      customerEmail: currentUser?.email || 'unregistered@bfc.com',
      address: `${addressData.street}, ${addressData.city}`,
      items: [...cart],
      subtotal,
      deliveryCharge: cms.deliveryCharge,
      discount: discountAmount,
      total,
      status: OrderStatus.PENDING,
      createdAt: new Date().toISOString(),
      paymentMethod,
      paymentDetails: paymentMethod === 'COD' ? null : { provider: paymentMethod }
    };

    showToast('Authorizing Credits', 'info', 'Verifying transaction with neural bank...');
    await new Promise(r => setTimeout(r, 2000));

    setAllOrders(prev => [order, ...prev]);
    setLastOrder(order);
    setCart([]);
    setView('RECEIPT');
    showToast('Mission Dispatched', 'success', 'Order manifest generated successfully.');
  };

  const downloadReceiptImage = async () => {
    if (!receiptRef.current) return;
    const canvas = await html2canvas(receiptRef.current, { 
      scale: 3,
      backgroundColor: '#ffffff',
      useCORS: true
    });
    const link = document.createElement('a');
    link.download = `BFC_Manifest_${lastOrder?.id}.png`;
    link.href = canvas.toDataURL('image/png');
    link.click();
    showToast('Manifest Saved', 'success', 'Receipt image downloaded.');
  };

  const downloadReceiptPDF = async () => {
    if (!receiptRef.current) return;
    const canvas = await html2canvas(receiptRef.current, { scale: 3, backgroundColor: '#ffffff' });
    const imgData = canvas.toDataURL('image/png');
    const pdf = new jsPDF('p', 'mm', 'a4');
    const imgProps = pdf.getImageProperties(imgData);
    const pdfWidth = pdf.internal.pageSize.getWidth();
    const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;
    pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
    pdf.save(`BFC_Manifest_${lastOrder?.id}.pdf`);
    showToast('Document Saved', 'success', 'Receipt PDF generated.');
  };

  if (view === 'ADMIN' && currentUser?.role === UserRole.ADMIN) {
    return <AdminPanel cms={cms} setCms={setCms} menuItems={menuItems} setMenuItems={setMenuItems} orders={allOrders} setOrders={setAllOrders} onLogout={() => { setView('HOME'); setCurrentUser(null); }} />;
  }

  return (
    <div className={`min-h-screen flex flex-col bg-[#020617] text-white selection:bg-red-600/30 theme-${cms.activeLayout}`}>
      {/* Global Navbar */}
      <nav className={`fixed top-0 inset-x-0 z-[5000] px-6 lg:px-12 py-5 glass flex justify-between items-center transition-all ${view === 'RECEIPT' || view === 'LOGIN' ? 'hidden' : ''}`}>
        <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center font-black shadow-lg group-hover:scale-110 transition-all">B</div>
          <h1 className="text-lg font-black italic uppercase hidden md:block tracking-tighter">{cms.navigation.brand}</h1>
        </div>
        <div className="flex gap-4 items-center">
          <button onClick={() => setView('VAULT')} className="w-10 h-10 glass rounded-xl flex items-center justify-center hover:themed-primary transition-all"><i className="fas fa-user-shield"></i></button>
          <button onClick={() => setView('CART')} className="relative w-10 h-10 glass rounded-xl flex items-center justify-center hover:scale-110 transition-all">
            <i className="fas fa-shopping-bag"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-[8px] w-5 h-5 rounded-full flex items-center justify-center font-black animate-pulse">{cart.length}</span>}
          </button>
          <button onClick={() => setView('LOGIN')} className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center overflow-hidden border-2 border-white/10 shadow-xl">
            {currentUser ? <img src={`https://ui-avatars.com/api/?name=${currentUser.name}&background=random&color=fff`} className="w-full" alt="" /> : <i className="fas fa-user"></i>}
          </button>
        </div>
      </nav>

      <main className={`flex-1 flex flex-col pt-24 pb-20`}>
        {view === 'HOME' && (
          <div className="p-6 lg:p-20 space-y-20 animate-elite-up">
             <section className="h-[75vh] rounded-[50px] overflow-hidden relative flex items-center px-10 border border-white/5">
                <img src={cms.hero.image} className="absolute inset-0 w-full h-full object-cover opacity-40 hover:scale-110 transition-all duration-[20s]" alt="" />
                <div className="absolute inset-0 bg-gradient-to-r from-black/80 via-black/40 to-transparent"></div>
                <div className="relative z-10 max-w-2xl space-y-8">
                   <div className="inline-block px-6 py-2 glass rounded-full border border-red-600/30">
                      <p className="text-red-600 font-black text-[10px] uppercase tracking-[6px]">{cms.hero.subtitle}</p>
                   </div>
                   <h2 className="text-6xl lg:text-9xl font-black italic uppercase leading-[0.85] tracking-tighter drop-shadow-2xl">{cms.hero.title}</h2>
                   <p className="text-lg lg:text-xl opacity-70 max-w-lg leading-relaxed">{cms.hero.description}</p>
                   <div className="flex gap-4">
                      <Button size="lg" className="rounded-[30px]" onClick={() => setView('MENU')}>{cms.hero.cta}</Button>
                      <Button variant="outline" size="lg" className="rounded-[30px] glass text-white" onClick={() => setView('VAULT')}>VIEW VAULT</Button>
                   </div>
                </div>
             </section>
          </div>
        )}

        {view === 'MENU' && (
          <div className="p-6 lg:p-20 space-y-16 animate-elite-up">
            <div className="text-center space-y-4">
               <h2 className="text-7xl lg:text-[120px] font-black italic uppercase text-center tracking-tighter leading-none">Manifest</h2>
               <p className="text-[10px] font-black uppercase text-red-600 tracking-[15px]">Elite Deployment Registry</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10">
              {menuItems.map(item => (
                <div key={item.id} className="glass p-8 rounded-[50px] group border-white/5 flex flex-col hover:-translate-y-4 transition-all duration-500 shadow-2xl">
                  <div className="h-72 rounded-[40px] overflow-hidden mb-8 relative">
                    <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" alt="" />
                    <div className="absolute top-6 right-6 bg-red-600 text-white px-6 py-2 rounded-full text-[12px] font-black shadow-2xl">৳{item.price}</div>
                  </div>
                  <div className="flex-1 space-y-4">
                    <h4 className="text-3xl font-black italic uppercase leading-none">{item.name}</h4>
                    <p className="text-[10px] font-black text-red-600 uppercase tracking-[6px]">{item.category}</p>
                    <p className="text-sm opacity-50 font-medium leading-relaxed line-clamp-2">{item.description}</p>
                  </div>
                  <Button fullWidth className="mt-10 rounded-[25px] py-6 shadow-red-600/20" onClick={() => {
                    setCart(prev => {
                      const ex = prev.find(c => c.item.id === item.id);
                      if (ex) return prev.map(x => x.item.id === item.id ? { ...x, qty: x.qty + 1 } : x);
                      return [...prev, { item, qty: 1 }];
                    });
                    showToast('Secured to Bag', 'success', `${item.name} added to deployment manifest.`);
                  }}>SECURE TO BAG</Button>
                </div>
              ))}
            </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="max-w-2xl mx-auto p-6 w-full space-y-10 animate-elite-up mt-10">
            <div className="text-center space-y-2">
               <h2 className="text-6xl font-black italic uppercase tracking-tighter">My Bag</h2>
               <p className="text-[9px] font-black uppercase opacity-40 tracking-[10px]">Registry Confirmation</p>
            </div>
            {cart.length === 0 ? (
              <div className="text-center opacity-20 py-32 space-y-6">
                <i className="fas fa-shopping-basket text-7xl"></i>
                <p className="uppercase font-black tracking-widest text-xs">Manifest is empty</p>
                <Button variant="outline" className="mt-8 rounded-2xl" onClick={() => setView('MENU')}>RE-LOAD REGISTRY</Button>
              </div>
            ) : (
              <div className="glass p-10 rounded-[50px] space-y-10 shadow-3xl border-white/5">
                <div className="space-y-6">
                  {cart.map((c, i) => (
                    <div key={i} className="flex justify-between items-center border-b border-white/5 pb-6 last:border-0">
                      <div className="flex gap-6 items-center">
                        <div className="w-16 h-16 rounded-2xl overflow-hidden shrink-0 border border-white/10"><img src={c.item.image} className="w-full h-full object-cover" alt="" /></div>
                        <div className="space-y-1">
                           <p className="font-black italic uppercase text-lg leading-none">{c.item.name}</p>
                           <div className="flex items-center gap-4 pt-2">
                              <button onClick={() => setCart(prev => prev.map(x => x.item.id === c.item.id ? { ...x, qty: Math.max(0, x.qty - 1) } : x).filter(x => x.qty > 0))} className="w-8 h-8 rounded-xl glass flex items-center justify-center text-[10px]"><i className="fas fa-minus"></i></button>
                              <span className="text-sm font-black">{c.qty}</span>
                              <button onClick={() => setCart(prev => prev.map(x => x.item.id === c.item.id ? { ...x, qty: x.qty + 1 } : x))} className="w-8 h-8 rounded-xl glass flex items-center justify-center text-[10px]"><i className="fas fa-plus"></i></button>
                           </div>
                        </div>
