        <nav className="fixed bottom-0 inset-x-0 z-[6000] lg:hidden glass border-t border-white/5 flex justify-around items-center h-24 safe-bottom shadow-2xl">
           {[
             { id: 'HOME', icon: 'fa-home', label: 'Core' },
             { id: 'MENU', icon: 'fa-utensils', label: 'Menu' },
             { id: 'CART', icon: 'fa-shopping-bag', label: 'Bag' },
             { id: 'VAULT', icon: 'fa-shield-halved', label: 'Vault' }
           ].map(item => (
             <button key={item.id} onClick={() => setView(item.id as any)} className={`flex flex-col items-center gap-2 w-full transition-all ${view === item.id ? 'text-red-600 scale-110' : 'text-gray-500 opacity-40'}`}>
                <i className={`fas ${item.icon} text-xl`}></i>
                <span className="text-[9px] font-black uppercase tracking-[4px]">{item.label}</span>
             </button>
           ))}
        </nav>
      )}

      {/* Persistent ChatBot */}
      {view !== 'RECEIPT' && <ChatBot isOnline={!isOffline} currentUser={currentUser} menuItems={menuItems} />}

      {/* Toast Overlay */}
      <div className="fixed top-24 right-4 z-[10000] space-y-4 max-w-sm w-full pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto bg-gray-950/90 backdrop-blur-2xl p-7 rounded-[35px] animate-elite-up border-l-4 border-red-600 shadow-2xl ring-1 ring-white/5">
            <div className="flex items-center gap-4">
               <div className={`w-8 h-8 rounded-xl flex items-center justify-center text-xs text-white ${t.type === 'error' ? 'bg-red-600' : t.type === 'warning' ? 'bg-amber-600' : 'bg-emerald-600'}`}>
                  <i className={`fas ${t.type === 'error' ? 'fa-bolt' : t.type === 'warning' ? 'fa-exclamation' : 'fa-check'}`}></i>
               </div>
               <div>
                  <p className="text-[10px] font-black uppercase tracking-widest text-white">{t.message}</p>
                  {t.description && <p className="text-[9px] opacity-60 mt-1 leading-relaxed text-gray-400 font-medium">{t.description}</p>}
               </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Order, MenuItem, SiteCMS, OrderStatus, LayoutPreset, ThemeConfig } from './types';
import { Button } from './components/Button';

interface AdminPanelProps {
  cms: SiteCMS;
  setCms: (cms: SiteCMS) => void;
  menuItems: MenuItem[];
  setMenuItems: (items: MenuItem[]) => void;
  orders: Order[];
  setOrders: (orders: Order[]) => void;
  onLogout: () => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  cms, setCms, menuItems, setMenuItems, orders, setOrders, onLogout 
}) => {
  const [tab, setTab] = useState<'DASHBOARD' | 'MENU' | 'ORDERS' | 'LOGISTICS' | 'CMS' | 'LAYOUT'>('DASHBOARD');
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedLayoutForEdit, setSelectedLayoutForEdit] = useState<LayoutPreset>(cms.activeLayout);

  const totalRevenue = useMemo(() => orders.reduce((acc, curr) => acc + curr.total, 0), [orders]);
  const activeOrders = useMemo(() => orders.filter(o => o.status !== OrderStatus.DELIVERED && o.status !== OrderStatus.CANCELLED).length, [orders]);

  const updateStatus = (orderId: string, status: OrderStatus) => {
    setOrders(orders.map(o => o.id === orderId ? { ...o, status } : o));
  };

  const handleSaveItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingItem) return;

    if (editingItem.id === 'NEW') {
        const newItem = { ...editingItem, id: Math.random().toString(36).slice(2, 9) };
        setMenuItems([...menuItems, newItem]);
    } else {
        setMenuItems(menuItems.map(item => item.id === editingItem.id ? editingItem : item));
    }
    setEditingItem(null);
  };

