const StatCard = ({ label, value, icon, color = 'text-white', trend, isTrendDown }: any) => (
  <div className="glass p-8 rounded-[40px] flex items-center gap-6 group hover:border-red-600/20 transition-all border border-white/5 shadow-2xl relative overflow-hidden">
    <div className={`w-14 h-14 bg-white/5 rounded-2xl flex items-center justify-center text-xl ${color} shadow-inner group-hover:bg-red-600/10 group-hover:text-red-600 transition-all`}>
      <i className={`fas ${icon}`}></i>
    </div>
    <div>
      <div className="flex items-center gap-2 mb-1">
        <p className="text-[9px] font-black uppercase tracking-[3px] opacity-40">{label}</p>
        {trend && (
          <span className={`text-[8px] font-black px-2 py-0.5 rounded-full ${isTrendDown ? 'bg-red-500/20 text-red-500' : 'bg-emerald-500/20 text-emerald-500'}`}>
            {trend}
          </span>
        )}
      </div>
      <h4 className="text-3xl font-black italic leading-none">{value}</h4>
