);

const ColorInput = ({ label, value, onChange }: { label: string, value: string, onChange: (v: string) => void }) => (
  <div className="space-y-3">
    <label className="text-[10px] font-black uppercase tracking-[3px] opacity-40 ml-4">{label}</label>
    <div className="flex gap-4">
      <div className="w-16 h-16 rounded-[20px] border border-white/10 shrink-0 relative overflow-hidden shadow-inner">
        <input 
          type="color" 
          value={value} 
          onChange={(e) => onChange(e.target.value)} 
          className="absolute inset-0 w-[200%] h-[200%] translate-x-[-25%] translate-y-[-25%] cursor-pointer"
        />
      </div>
      <input 
        type="text" 
        value={value} 
        onChange={(e) => onChange(e.target.value)} 
        className="flex-1 glass border border-white/10 p-5 rounded-[24px] font-mono text-[10px] outline-none focus:border-red-600 transition-all"
      />
    </div>
  </div>
);

const InputGroup = ({ label, value, onChange, type = 'text', placeholder }: { label: string, value: string, onChange: (v: string) => void, type?: string, placeholder?: string }) => (
  <div className="space-y-3">
    <label className="text-[10px] font-black uppercase tracking-[3px] opacity-40 ml-4">{label}</label>
    <input 
      type={type} 
      value={value} 
      onChange={e => onChange(e.target.value)}
