           <div>
             <h1 className="text-xl font-black italic uppercase tracking-tighter">Elite Hub</h1>
             <p className="text-[8px] font-black uppercase text-red-600 tracking-[3px]">Admin Mainframe</p>
           </div>
        </div>

        <nav className="flex-1 space-y-1.5 overflow-y-auto no-scrollbar">
          {navItems.map(item => (
