                  </div>
                </div>
                <div className="glass p-8 rounded-[40px] border-white/5 space-y-6">
                  <h3 className="text-xl font-black italic uppercase tracking-widest flex items-center gap-3">
                    <i className="fas fa-fire text-red-600 text-sm"></i>
