                        className={`p-4 rounded-2xl border-2 text-[8px] font-black uppercase tracking-widest transition-all ${selectedLayoutForEdit === layout ? 'border-red-600 bg-red-600/10' : 'border-white/5 bg-white/5 opacity-40 hover:opacity-100'}`}
