                  <ColorInput label="Module Surface" value={currentEditTheme.card} onChange={(v) => updateThemeVar('card', v)} />
                  <ColorInput label="Stroke/Border Color" value={currentEditTheme.border} onChange={(v) => updateThemeVar('border', v)} />

                  <div className="space-y-3">
                    <label className="text-[10px] font-black uppercase tracking-[3px] opacity-40 ml-4">Font Family Registry</label>
