                  <h2 className="text-5xl lg:text-7xl font-black italic uppercase tracking-tighter">Unit Registry</h2>
                  <p className="text-[10px] font-black text-red-600 uppercase tracking-[10px]">Inventory Deployment Control</p>
                </div>
                {!editingItem && (
