                   <InputGroup label="Core Station Brand" value={cms.navigation.brand} onChange={v => setCms({...cms, navigation: {...cms.navigation, brand: v}})} placeholder="BFC Mainframe" />
                   <InputGroup label="Hero Visual Brief" value={cms.hero.title} onChange={v => setCms({...cms, hero: {...cms.hero, title: v}})} placeholder="Primary Objective" />
                   <div className="md:col-span-2">
