import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { MenuItem, UserRole, User, Order, CartItem, SiteCMS, OrderStatus, Promotion } from './types';
import { MOCK_MENU, MOCK_ORDERS, DEFAULT_THEMES } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';
import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';

interface Toast {
  id: number;
  message: string;
  description?: string;
  type: 'success' | 'error' | 'warning' | 'info';
}

const DEFAULT_CMS: SiteCMS = {
  activeLayout: 'ELITE_DARK',
  themeDefinitions: DEFAULT_THEMES,
  deliveryCharge: 50,
  hero: {
    title: "Experience Elite Bangladeshi Cuisine",
    subtitle: "The Real Taste Of Bangla",
    description: "Indulge in the finest culinary heritage of Bangladesh. Where tradition meets high-tech precision in every bite.",
    image: "https://images.unsplash.com/photo-1633945274405-b6c8069047b0?q=80&w=2000",
    cta: "ACCESS REGISTRY"
  },
  navigation: {
    brand: "BFC ELITE",
    links: { home: "HOME", menu: "MENU", vault: "VAULT", profile: "PROFILE" }
  },
  vault: {
    title: "ELITE VAULT",
    description: "Manage your credits and unlock secret menu deployments."
  }
};

const App: React.FC = () => {
  const [cms, setCms] = useState<SiteCMS>(() => {
    const saved = localStorage.getItem('bfc_cms');
    return saved ? JSON.parse(saved) : DEFAULT_CMS;
  });
  const [menuItems, setMenuItems] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('bfc_menu');
    return saved ? JSON.parse(saved) : MOCK_MENU;
  });
  const [allOrders, setAllOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('bfc_orders');
    return saved ? JSON.parse(saved) : MOCK_ORDERS;
  });
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });
  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('bfc_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT' | 'CHECKOUT' | 'RECEIPT'>('HOME');
  const [checkoutStep, setCheckoutStep] = useState<'ADDRESS' | 'PAYMENT'>('ADDRESS');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [lastOrder, setLastOrder] = useState<Order | null>(null);

  // Form States
  const [addressData, setAddressData] = useState({ name: '', phone: '', city: 'Dhaka', street: '' });
  const [promoCode, setPromoCode] = useState('');
  const [activePromo, setActivePromo] = useState<Promotion | null>(null);
  const [paymentMethod, setPaymentMethod] = useState<'BKASH' | 'NAGAD' | 'CARD' | 'COD'>('BKASH');
  const [paymentFields, setPaymentFields] = useState({ number: '', pin: '', cardNo: '', expiry: '', cvv: '' });
  const [loginId, setLoginId] = useState('');
  const [regName, setRegName] = useState('');

  const receiptRef = useRef<HTMLDivElement>(null);

  const showToast = useCallback((message: string, type: Toast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, description }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 6000);
  }, []);

  useEffect(() => {
    const handleOnline = () => { setIsOffline(false); showToast('Link Restored', 'success', 'Neural core synchronized.'); };
    const handleOffline = () => { setIsOffline(true); showToast('Link Severed', 'error', 'Working in offline mode.'); };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [showToast]);

  useEffect(() => { localStorage.setItem('bfc_cms', JSON.stringify(cms)); }, [cms]);
  useEffect(() => { localStorage.setItem('bfc_menu', JSON.stringify(menuItems)); }, [menuItems]);
  useEffect(() => { localStorage.setItem('bfc_orders', JSON.stringify(allOrders)); }, [allOrders]);
  useEffect(() => { localStorage.setItem('bfc_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { localStorage.setItem('bfc_user', JSON.stringify(currentUser)); }, [currentUser]);

  const subtotal = useMemo(() => cart.reduce((a, b) => a + (b.item.price * b.qty), 0), [cart]);
  const discountAmount = useMemo(() => {
    if (!activePromo) return 0;
    return activePromo.discountType === 'PERCENTAGE' 
      ? (subtotal * activePromo.discountValue) / 100 
      : activePromo.discountValue;
  }, [subtotal, activePromo]);
  const total = subtotal + cms.deliveryCharge - discountAmount;

  const handleApplyPromo = () => {
    const preCodes: Promotion[] = [
      { id: '1', name: 'Welcome', code: 'BFC50', discountType: 'FIXED', discountValue: 50, startDate: '', endDate: '', usageLimit: 100, usageCount: 0, isActive: true },
      { id: '2', name: 'Elite', code: 'ELITE20', discountType: 'PERCENTAGE', discountValue: 20, startDate: '', endDate: '', usageLimit: 100, usageCount: 0, isActive: true }
    ];
    const found = preCodes.find(p => p.code === promoCode.toUpperCase() && p.isActive);
    if (found) {
      setActivePromo(found);
      showToast('Promo Secured', 'success', `Discount of ৳${found.discountValue}${found.discountType === 'PERCENTAGE' ? '%' : ''} applied.`);
    } else {
      showToast('Invalid Code', 'error', 'Transmission code not recognized.');
    }
  };

  const processPayment = async () => {
    if (isOffline) return showToast('Deployment Error', 'error', 'Neural link is offline.');

    const phoneRegex = /^01[3-9]\d{8}$/;
    if (!phoneRegex.test(addressData.phone)) {
      return showToast('Invalid Identification', 'warning', 'Phone number must be 11 digits (e.g., 01700000000).');
    }

    if ((paymentMethod === 'BKASH' || paymentMethod === 'NAGAD') && (!paymentFields.number || !paymentFields.pin)) {
      return showToast('Missing Protocols', 'warning', 'Wallet number and secure PIN required.');
    }

    if (paymentMethod === 'CARD' && (!paymentFields.cardNo || !paymentFields.cvv)) {
      return showToast('Insecure Data', 'warning', 'Full card manifest required for credit transfer.');
    }

    const order: Order = {
      id: 'BFC-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
      customerId: currentUser?.id || 'GUEST',
      customerName: addressData.name || currentUser?.name || 'Honored Guest',
      customerPhone: addressData.phone,
      customerEmail: currentUser?.email || 'unregistered@bfc.com',
      address: `${addressData.street}, ${addressData.city}`,
      items: [...cart],
      subtotal,
      deliveryCharge: cms.deliveryCharge,
      discount: discountAmount,
      total,
      status: OrderStatus.PENDING,
      createdAt: new Date().toISOString(),
      paymentMethod,
      paymentDetails: paymentMethod === 'COD' ? null : { provider: paymentMethod }
    };

    showToast('Authorizing Credits', 'info', 'Verifying transaction with neural bank...');
    await new Promise(r => setTimeout(r, 2000));

    setAllOrders(prev => [order, ...prev]);
    setLastOrder(order);
    setCart([]);
    setView('RECEIPT');
    showToast('Mission Dispatched', 'success', 'Order manifest generated successfully.');
  };

  const downloadReceiptImage = async () => {
    if (!receiptRef.current) return;
    const canvas = await html2canvas(receiptRef.current, { 
      scale: 3,
      backgroundColor: '#ffffff',
      useCORS: true
    });
    const link = document.createElement('a');
    link.download = `BFC_Manifest_${lastOrder?.id}.png`;
    link.href = canvas.toDataURL('image/png');
    link.click();
    showToast('Manifest Saved', 'success', 'Receipt image downloaded.');
  };

  const downloadReceiptPDF = async () => {
    if (!receiptRef.current) return;
    const canvas = await html2canvas(receiptRef.current, { scale: 3, backgroundColor: '#ffffff' });
    const imgData = canvas.toDataURL('image/png');
    const pdf = new jsPDF('p', 'mm', 'a4');
    const imgProps = pdf.getImageProperties(imgData);
    const pdfWidth = pdf.internal.pageSize.getWidth();
    const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;
    pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
    pdf.save(`BFC_Manifest_${lastOrder?.id}.pdf`);
    showToast('Document Saved', 'success', 'Receipt PDF generated.');
  };

  if (view === 'ADMIN' && currentUser?.role === UserRole.ADMIN) {
    return <AdminPanel cms={cms} setCms={setCms} menuItems={menuItems} setMenuItems={setMenuItems} orders={allOrders} setOrders={setAllOrders} onLogout={() => { setView('HOME'); setCurrentUser(null); }} />;
  }

  return (
    <div className={`min-h-screen flex flex-col bg-[#020617] text-white selection:bg-red-600/30 theme-${cms.activeLayout}`}>
      {/* Global Navbar */}
      <nav className={`fixed top-0 inset-x-0 z-[5000] px-6 lg:px-12 py-5 glass flex justify-between items-center transition-all ${view === 'RECEIPT' || view === 'LOGIN' ? 'hidden' : ''}`}>
        <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center font-black shadow-lg group-hover:scale-110 transition-all">B</div>
          <h1 className="text-lg font-black italic uppercase hidden md:block tracking-tighter">{cms.navigation.brand}</h1>
        </div>
        <div className="flex gap-4 items-center">
          <button onClick={() => setView('VAULT')} className="w-10 h-10 glass rounded-xl flex items-center justify-center hover:themed-primary transition-all"><i className="fas fa-user-shield"></i></button>
          <button onClick={() => setView('CART')} className="relative w-10 h-10 glass rounded-xl flex items-center justify-center hover:scale-110 transition-all">
            <i className="fas fa-shopping-bag"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-[8px] w-5 h-5 rounded-full flex items-center justify-center font-black animate-pulse">{cart.length}</span>}
          </button>
          <button onClick={() => setView('LOGIN')} className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center overflow-hidden border-2 border-white/10 shadow-xl">
            {currentUser ? <img src={`https://ui-avatars.com/api/?name=${currentUser.name}&background=random&color=fff`} className="w-full" alt="" /> : <i className="fas fa-user"></i>}
          </button>
        </div>
      </nav>

      <main className={`flex-1 flex flex-col pt-24 pb-20`}>
        {view === 'HOME' && (
          <div className="p-6 lg:p-20 space-y-20 animate-elite-up">
             <section className="h-[75vh] rounded-[50px] overflow-hidden relative flex items-center px-10 border border-white/5">
                <img src={cms.hero.image} className="absolute inset-0 w-full h-full object-cover opacity-40 hover:scale-110 transition-all duration-[20s]" alt="" />
