    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });
  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('bfc_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT' | 'CHECKOUT' | 'RECEIPT'>('HOME');
  const [checkoutStep, setCheckoutStep] = useState<'ADDRESS' | 'PAYMENT'>('ADDRESS');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [lastOrder, setLastOrder] = useState<Order | null>(null);

  // Form States
  const [addressData, setAddressData] = useState({ name: '', phone: '', city: 'Dhaka', street: '' });
  const [promoCode, setPromoCode] = useState('');
  const [activePromo, setActivePromo] = useState<Promotion | null>(null);
  const [paymentMethod, setPaymentMethod] = useState<'BKASH' | 'NAGAD' | 'CARD' | 'COD'>('BKASH');
  const [paymentFields, setPaymentFields] = useState({ number: '', pin: '', cardNo: '', expiry: '', cvv: '' });
  const [loginId, setLoginId] = useState('');
  const [regName, setRegName] = useState('');

  const receiptRef = useRef<HTMLDivElement>(null);

  const showToast = useCallback((message: string, type: Toast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, description }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
  }, []);

  useEffect(() => {
    const handleOnline = () => { setIsOffline(false); showToast('Link Restored', 'success', 'Neural core synchronized.'); };
    const handleOffline = () => { setIsOffline(true); showToast('Link Severed', 'error', 'Working in offline mode.'); };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [showToast]);

  useEffect(() => { localStorage.setItem('bfc_cms', JSON.stringify(cms)); }, [cms]);
  useEffect(() => { localStorage.setItem('bfc_menu', JSON.stringify(menuItems)); }, [menuItems]);
  useEffect(() => { localStorage.setItem('bfc_orders', JSON.stringify(allOrders)); }, [allOrders]);
  useEffect(() => { localStorage.setItem('bfc_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { localStorage.setItem('bfc_user', JSON.stringify(currentUser)); }, [currentUser]);

  const subtotal = useMemo(() => cart.reduce((a, b) => a + (b.item.price * b.qty), 0), [cart]);
  const discountAmount = useMemo(() => {
    if (!activePromo) return 0;
    return activePromo.discountType === 'PERCENTAGE' 
      ? (subtotal * activePromo.discountValue) / 100 
      : activePromo.discountValue;
  }, [subtotal, activePromo]);
  const total = subtotal + cms.deliveryCharge - discountAmount;

  const handleApplyPromo = () => {
    const preCodes: Promotion[] = [
      { id: '1', name: 'Welcome', code: 'BFC50', discountType: 'FIXED', discountValue: 50, startDate: '', endDate: '', usageLimit: 100, usageCount: 0, isActive: true },
      { id: '2', name: 'Elite', code: 'ELITE20', discountType: 'PERCENTAGE', discountValue: 20, startDate: '', endDate: '', usageLimit: 100, usageCount: 0, isActive: true }
    ];
    const found = preCodes.find(p => p.code === promoCode.toUpperCase() && p.isActive);
    if (found) {
      setActivePromo(found);
      showToast('Promo Secured', 'success', `Discount applied.`);
    } else {
      showToast('Invalid Code', 'error', 'Transmission code not recognized.');
    }
  };

  const processPayment = async () => {
    if (isOffline) return showToast('Deployment Error', 'error', 'Neural link is offline.');
    const phoneRegex = /^01[3-9]\d{8}$/;
    if (!phoneRegex.test(addressData.phone)) return showToast('Invalid Identification', 'warning', 'Phone number required.');

    const order: Order = {
      id: 'BFC-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
      customerId: currentUser?.id || 'GUEST',
      customerName: addressData.name || currentUser?.name || 'Honored Guest',
      customerPhone: addressData.phone,
      customerEmail: currentUser?.email || 'unregistered@bfc.com',
      address: `${addressData.street}, ${addressData.city}`,
      items: [...cart],
      subtotal,
      deliveryCharge: cms.deliveryCharge,
      discount: discountAmount,
      total,
      status: OrderStatus.PENDING,
      createdAt: new Date().toISOString(),
      paymentMethod,
    };

    showToast('Authorizing Credits', 'info', 'Verifying transaction...');
    await new Promise(r => setTimeout(r, 1500));
    setAllOrders(prev => [order, ...prev]);
    setLastOrder(order);
    setCart([]);
    setView('RECEIPT');
    showToast('Mission Dispatched', 'success', 'Deployment successful.');
  };

  // Fix: Implemented downloadReceiptImage to handle receipt visual manifest export
  const downloadReceiptImage = async () => {
    if (!receiptRef.current) return;
    try {
      const canvas = await html2canvas(receiptRef.current, {
        scale: 3,
        backgroundColor: '#ffffff',
        logging: false,
        useCORS: true
      });
      const link = document.createElement('a');
      link.download = `BFC-Receipt-${lastOrder?.id || 'deployment'}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
      showToast('Asset Downloaded', 'success', 'Image manifest saved to storage.');
    } catch (err) {
      showToast('Extraction Failed', 'error', 'Could not generate visual manifest.');
    }
  };

  // Fix: Implemented downloadReceiptPDF to handle receipt PDF manifest export
  const downloadReceiptPDF = async () => {
    if (!receiptRef.current) return;
    try {
      const canvas = await html2canvas(receiptRef.current, {
        scale: 3,
        backgroundColor: '#ffffff',
        logging: false,
        useCORS: true
      });
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      const imgProps = pdf.getImageProperties(imgData);
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;
      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      pdf.save(`BFC-Receipt-${lastOrder?.id || 'deployment'}.pdf`);
      showToast('Asset Downloaded', 'success', 'PDF manifest saved to storage.');
    } catch (err) {
      showToast('Extraction Failed', 'error', 'Could not generate PDF manifest.');
    }
  };

  const ViewWrapper: React.FC<{ children: React.ReactNode }> = ({ children }) => (
    <div className="flex-1 flex flex-col animate-elite-up gpu-accel">
      {children}
    </div>
  );

  if (view === 'ADMIN' && currentUser?.role === UserRole.ADMIN) {
    return <AdminPanel cms={cms} setCms={setCms} menuItems={menuItems} setMenuItems={setMenuItems} orders={allOrders} setOrders={setAllOrders} onLogout={() => { setView('HOME'); setCurrentUser(null); }} />;
  }

  return (
    <div className={`min-h-screen flex flex-col bg-[#020617] text-white selection:bg-red-600/30 theme-${cms.activeLayout}`}>
      {/* Navbar */}
      <nav className={`fixed top-0 inset-x-0 z-[5000] px-6 lg:px-12 py-6 glass flex justify-between items-center transition-all ${view === 'RECEIPT' || view === 'LOGIN' ? 'hidden' : ''}`}>
        <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-11 h-11 bg-red-600 rounded-2xl flex items-center justify-center font-black shadow-lg group-hover:scale-105 transition-all">B</div>
          <h1 className="text-xl font-black italic uppercase hidden md:block tracking-tighter">{cms.navigation.brand}</h1>
        </div>
        <div className="flex gap-4 items-center">
          <button onClick={() => setView('VAULT')} className="w-11 h-11 glass rounded-2xl flex items-center justify-center hover:bg-white/5 transition-all"><i className="fas fa-shield-halved"></i></button>
          <button onClick={() => setView('CART')} className="relative w-11 h-11 glass rounded-2xl flex items-center justify-center hover:scale-105 transition-all">
            <i className="fas fa-shopping-bag"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-[10px] w-6 h-6 rounded-full flex items-center justify-center font-black shadow-lg">{cart.length}</span>}
          </button>
          <button onClick={() => setView('LOGIN')} className="w-11 h-11 bg-red-600 rounded-2xl flex items-center justify-center overflow-hidden border-2 border-white/10 shadow-xl">
            {currentUser ? <img src={`https://ui-avatars.com/api/?name=${currentUser.name}&background=random&color=fff`} className="w-full" alt="" /> : <i className="fas fa-user"></i>}
          </button>
        </div>
      </nav>

      <main className="flex-1 flex flex-col pt-24 pb-24 lg:pb-0">
        {view === 'HOME' && (
          <ViewWrapper>
            <div className="p-6 lg:p-12 xl:p-20 space-y-20">
              <section className="h-[80vh] rounded-[60px] overflow-hidden relative flex items-center px-8 lg:px-16 border border-white/5 shadow-3xl">
                <img src={cms.hero.image} className="absolute inset-0 w-full h-full object-cover opacity-30 hover:scale-105 transition-all duration-[20s] ease-linear" alt="" />
                <div className="absolute inset-0 bg-gradient-to-r from-black via-black/40 to-transparent"></div>
                <div className="relative z-10 max-w-3xl space-y-8">
                   <div className="inline-block px-6 py-2 glass rounded-full border border-red-600/20">
                      <p className="text-red-500 font-black text-[10px] uppercase tracking-[8px]">{cms.hero.subtitle}</p>
                   </div>
                   <h2 className="text-7xl lg:text-9xl font-black italic uppercase leading-[0.8] tracking-tighter drop-shadow-2xl">{cms.hero.title}</h2>
                   <p className="text-xl lg:text-2xl opacity-60 max-w-xl leading-relaxed font-medium">{cms.hero.description}</p>
                   <div className="flex flex-wrap gap-5 pt-4">
                      <Button size="lg" className="rounded-[35px]" onClick={() => setView('MENU')}>{cms.hero.cta}</Button>
                      <Button variant="outline" size="lg" className="rounded-[35px] glass text-white !border-white/10" onClick={() => setView('VAULT')}>PERSONNEL VAULT</Button>
                   </div>
                </div>
              </section>
            </div>
          </ViewWrapper>
        )}

        {view === 'MENU' && (
          <ViewWrapper>
            <div className="p-6 lg:p-20 space-y-16">
              <header className="text-center space-y-4">
                <h2 className="text-8xl lg:text-[140px] font-black italic uppercase tracking-tighter leading-none text-glow">Manifest</h2>
                <p className="text-[12px] font-black uppercase text-red-600 tracking-[20px] opacity-80">Elite Deployment Registry</p>
              </header>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
                {menuItems.map(item => (
                  <div key={item.id} className="glass p-7 rounded-[50px] group border-white/5 flex flex-col hover:-translate-y-3 transition-all duration-500 shadow-2xl">
                    <div className="h-64 rounded-[40px] overflow-hidden mb-8 relative border border-white/5 shadow-inner">
                      <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" alt="" />
                      <div className="absolute bottom-6 left-6 themed-primary px-6 py-2 rounded-full text-[14px] font-black shadow-2xl">৳{item.price}</div>
                    </div>
                    <div className="flex-1 space-y-3 px-2">
                      <h4 className="text-3xl font-black italic uppercase leading-none">{item.name}</h4>
                      <p className="text-[10px] font-black text-red-500 uppercase tracking-[6px]">{item.category}</p>
                      <p className="text-sm opacity-40 font-medium leading-relaxed line-clamp-2">{item.description}</p>
                    </div>
                    <Button fullWidth className="mt-10 rounded-[28px] py-6 shadow-red-600/20" onClick={() => {
                      setCart(prev => {
                        const ex = prev.find(c => c.item.id === item.id);
                        if (ex) return prev.map(x => x.item.id === item.id ? { ...x, qty: x.qty + 1 } : x);
                        return [...prev, { item, qty: 1 }];
                      });
                      showToast('Secured', 'success', `${item.name} logged.`);
                    }}>SECURE TO BAG</Button>
                  </div>
                ))}
              </div>
            </div>
          </ViewWrapper>
        )}

        {view === 'CART' && (
          <ViewWrapper>
            <div className="max-w-2xl mx-auto p-6 w-full space-y-12 mt-12">
              <div className="text-center space-y-2">
                 <h2 className="text-7xl font-black italic uppercase tracking-tighter">My Bag</h2>
                 <p className="text-[10px] font-black uppercase opacity-40 tracking-[10px]">Registry Confirmation</p>
              </div>
              {cart.length === 0 ? (
                <div className="text-center py-40 glass rounded-[60px] border-white/5 flex flex-col items-center gap-8">
                  <div className="w-24 h-24 bg-white/5 rounded-full flex items-center justify-center text-4xl opacity-20"><i className="fas fa-shopping-basket"></i></div>
                  <p className="uppercase font-black tracking-widest text-sm opacity-30">Bag manifest is empty</p>
                  <Button variant="outline" className="rounded-3xl !border-white/10" onClick={() => setView('MENU')}>RE-LOAD REGISTRY</Button>
                </div>
              ) : (
                <div className="glass p-10 lg:p-14 rounded-[60px] space-y-12 shadow-4xl border-white/5">
                  <div className="space-y-8">
                    {cart.map((c, i) => (
                      <div key={i} className="flex justify-between items-center border-b border-white/5 pb-8 last:border-0">
                        <div className="flex gap-8 items-center">
                          <div className="w-20 h-20 rounded-3xl overflow-hidden shrink-0 border border-white/10 shadow-lg"><img src={c.item.image} className="w-full h-full object-cover" alt="" /></div>
                          <div className="space-y-2">
                             <p className="font-black italic uppercase text-2xl leading-none">{c.item.name}</p>
                             <div className="flex items-center gap-5 pt-2">
                                <button onClick={() => setCart(prev => prev.map(x => x.item.id === c.item.id ? { ...x, qty: Math.max(0, x.qty - 1) } : x).filter(x => x.qty > 0))} className="w-10 h-10 rounded-2xl glass flex items-center justify-center text-[12px] hover:bg-white/10 transition-all"><i className="fas fa-minus"></i></button>
                                <span className="text-lg font-black">{c.qty}</span>
                                <button onClick={() => setCart(prev => prev.map(x => x.item.id === c.item.id ? { ...x, qty: x.qty + 1 } : x))} className="w-10 h-10 rounded-2xl glass flex items-center justify-center text-[12px] hover:bg-white/10 transition-all"><i className="fas fa-plus"></i></button>
                             </div>
                          </div>
                        </div>
                        <p className="text-3xl font-black italic">৳{c.item.price * c.qty}</p>
                      </div>
                    ))}
                  </div>
                  <div className="space-y-5 pt-8 border-t border-white/10">
                    <div className="flex justify-between text-[11px] font-black uppercase opacity-40 tracking-widest"><span>Subtotal Value</span><span>৳{subtotal}</span></div>
                    <div className="flex justify-between text-[11px] font-black uppercase opacity-40 tracking-widest"><span>Logistics Fee</span><span>৳{cms.deliveryCharge}</span></div>
                    <div className="flex justify-between text-5xl font-black italic themed-text-primary pt-8 border-t-2 border-white/10 tracking-tighter"><span>Total</span><span>৳{subtotal + cms.deliveryCharge}</span></div>
                  </div>
                  <Button fullWidth size="lg" className="rounded-[40px] py-10 text-xl" onClick={() => {
                    if (!currentUser) setView('LOGIN');
                    else { setView('CHECKOUT'); setCheckoutStep('ADDRESS'); }
                  }}>INITIATE DEPLOYMENT</Button>
                </div>
              )}
            </div>
          </ViewWrapper>
        )}

        {view === 'CHECKOUT' && (
          <ViewWrapper>
             <div className="max-w-xl mx-auto p-6 w-full space-y-12 mt-12">
                <div className="flex justify-center items-center gap-8">
                   <div className={`w-5 h-5 rounded-full transition-all duration-500 ${checkoutStep === 'ADDRESS' ? 'bg-red-600 scale-125 shadow-[0_0_20px_rgba(220,38,38,0.6)]' : 'bg-gray-800'}`}></div>
                   <div className="w-20 h-0.5 bg-gray-800 rounded-full"></div>
                   <div className={`w-5 h-5 rounded-full transition-all duration-500 ${checkoutStep === 'PAYMENT' ? 'bg-red-600 scale-125 shadow-[0_0_20px_rgba(220,38,38,0.6)]' : 'bg-gray-800'}`}></div>
                </div>

                {checkoutStep === 'ADDRESS' ? (
                  <div className="glass p-12 lg:p-14 rounded-[60px] space-y-10 shadow-4xl border-white/5">
                    <div className="space-y-3">
                       <h3 className="text-4xl font-black italic uppercase tracking-tighter">Coordinates</h3>
                       <p className="text-[10px] font-black uppercase opacity-40 tracking-[8px]">Deployment Sector</p>
                    </div>
                    <div className="space-y-6">
                       <div className="space-y-3">
                          <label className="text-[10px] font-black uppercase tracking-widest opacity-40 ml-4">Personnel Full Name</label>
                          <input value={addressData.name} onChange={e => setAddressData({...addressData, name: e.target.value})} placeholder="COMMANDER IDENTITY" className="w-full glass p-7 rounded-[35px] outline-none border border-white/5 font-black uppercase text-sm focus:border-red-600/50 transition-all shadow-inner" />
                       </div>
                       <div className="space-y-3">
                          <label className="text-[10px] font-black uppercase tracking-widest opacity-40 ml-4">Neural Handset (11 Digits)</label>
                          <input value={addressData.phone} onChange={e => setAddressData({...addressData, phone: e.target.value})} maxLength={11} placeholder="01XXXXXXXXX" className="w-full glass p-7 rounded-[35px] outline-none border border-white/5 font-black text-sm focus:border-red-600/50 transition-all shadow-inner" />
                       </div>
                       <div className="space-y-3">
                          <label className="text-[10px] font-black uppercase tracking-widest opacity-40 ml-4">Sector Hub Address</label>
                          <input value={addressData.street} onChange={e => setAddressData({...addressData, street: e.target.value})} placeholder="HOUSE / ROAD / SECTOR" className="w-full glass p-7 rounded-[35px] outline-none border border-white/5 font-black uppercase text-sm focus:border-red-600/50 transition-all shadow-inner" />
                       </div>
                    </div>
                    <Button fullWidth size="lg" className="rounded-[40px] py-9" onClick={() => {
                      if (!addressData.name || !addressData.phone || !addressData.street) return showToast('Incomplete Coordinates', 'warning');
                      setCheckoutStep('PAYMENT');
                    }}>CONTINUE TO AUTH</Button>
                  </div>
                ) : (
                  <div className="glass p-12 lg:p-14 rounded-[60px] space-y-12 shadow-4xl border-white/5">
                     <div className="space-y-3">
                       <h3 className="text-4xl font-black italic uppercase tracking-tighter">Authorization</h3>
                       <p className="text-[10px] font-black uppercase opacity-40 tracking-[8px]">Secure Credit Transfer</p>
                     </div>

                     <div className="flex gap-4 glass p-2 rounded-[35px] border-white/10">
                        <input value={promoCode} onChange={e => setPromoCode(e.target.value)} placeholder="PROMO CODE" className="flex-1 bg-transparent p-6 rounded-3xl outline-none font-black text-sm uppercase placeholder:opacity-20" />
                        <button onClick={handleApplyPromo} className="px-10 themed-primary rounded-3xl font-black text-[12px] uppercase shadow-lg shadow-red-600/20 active:scale-95 transition-all">APPLY</button>
                     </div>

                     <div className="space-y-5">
                        <label className="text-[10px] font-black uppercase tracking-widest opacity-40 ml-4">Neural Gateway</label>
                        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                           {['BKASH', 'NAGAD', 'CARD', 'COD'].map(m => (
                             <button key={m} onClick={() => setPaymentMethod(m as any)} className={`p-6 rounded-[30px] border-2 transition-all flex flex-col items-center gap-4 ${paymentMethod === m ? 'border-red-600 bg-red-600/10 shadow-2xl scale-105' : 'border-white/5 bg-white/5 opacity-40 hover:opacity-100'}`}>
                                <i className={`fas ${m === 'BKASH' || m === 'NAGAD' ? 'fa-wallet' : m === 'CARD' ? 'fa-credit-card' : 'fa-hand-holding-dollar'} text-2xl`}></i>
                                <span className="text-[9px] font-black uppercase tracking-widest">{m}</span>
                             </button>
                           ))}
                        </div>
                     </div>

                     <div className="pt-8 border-t border-white/10 space-y-5">
                        <div className="flex justify-between text-[11px] font-black uppercase opacity-40 tracking-widest"><span>Total Registry Credits</span><span className="text-white">৳{total}</span></div>
                        <div className="flex justify-between text-4xl lg:text-5xl font-black italic themed-text-primary tracking-tighter"><span>Authorize</span><span>৳{total}</span></div>
                        <Button fullWidth size="lg" className="rounded-[40px] py-10 mt-8" onClick={processPayment}>CONFIRM & DEPLOY</Button>
                     </div>
                  </div>
                )}
             </div>
          </ViewWrapper>
        )}

        {view === 'RECEIPT' && lastOrder && (
          <ViewWrapper>
            <div className="max-w-2xl mx-auto p-6 w-full space-y-12 mb-20">
               <div ref={receiptRef} className="receipt-paper p-10 lg:p-16 relative overflow-hidden flex flex-col gap-12 animate-scale-in">
                  <div className="absolute top-0 right-0 w-48 h-48 bg-red-600 rotate-45 translate-x-24 -translate-y-24 flex items-end justify-center pb-8 shadow-2xl">
                     <span className="text-white font-black text-[14px] -rotate-45 tracking-[6px]">VERIFIED</span>
                  </div>

                  <div className="text-center space-y-4">
                     <div className="w-20 h-20 bg-red-600 text-white rounded-[30px] flex items-center justify-center font-black text-4xl mx-auto shadow-2xl">B</div>
                     <h1 className="text-5xl font-black italic uppercase tracking-tighter text-black">BFC ELITE</h1>
                     <p className="text-[11px] font-black uppercase tracking-[12px] opacity-40 text-black">Registry Manifest</p>
                  </div>

                  <div className="grid grid-cols-2 gap-10 pt-10 border-t border-black/10">
                     <div className="space-y-2">
                        <p className="text-[10px] font-black uppercase opacity-30 text-black tracking-widest">Personnel</p>
                        <p className="font-black uppercase text-xl text-black leading-none">{lastOrder.customerName}</p>
                        <p className="text-[11px] font-black text-red-600 mt-1">{lastOrder.customerPhone}</p>
                     </div>
                     <div className="text-right space-y-2">
                        <p className="text-[10px] font-black uppercase opacity-30 text-black tracking-widest">Manifest Code</p>
                        <p className="font-black text-xl text-black leading-none">#{lastOrder.id}</p>
                        <p className="text-[11px] font-bold opacity-40 text-black">{new Date(lastOrder.createdAt).toLocaleDateString()}</p>
                     </div>
                  </div>

                  <div className="space-y-6 py-10 border-y border-black/10 border-dashed">
                     <table className="w-full text-black">
                        <thead>
                           <tr className="text-[10px] font-black uppercase opacity-30 text-left">
                              <th className="pb-8 tracking-widest">Registry Unit</th>
                              <th className="pb-8 text-center tracking-widest">Qty</th>
                              <th className="pb-8 text-right tracking-widest">Credit</th>
                           </tr>
                        </thead>
                        <tbody className="divide-y divide-black/5">
                           {lastOrder.items.map((c, i) => (
                             <tr key={i} className="font-black text-lg">
                                <td className="py-5 uppercase italic leading-none">{c.item.name}</td>
                                <td className="py-5 text-center">{c.qty}</td>
                                <td className="py-5 text-right">৳{c.item.price * c.qty}</td>
                             </tr>
                           ))}
                        </tbody>
                     </table>
                  </div>

                  <div className="space-y-5 text-black">
                     <div className="flex justify-between text-[12px] font-black uppercase opacity-50"><span>Subtotal</span><span>৳{lastOrder.subtotal}</span></div>
                     <div className="flex justify-between text-[12px] font-black uppercase opacity-50"><span>Logistics</span><span>৳{lastOrder.deliveryCharge}</span></div>
                     <div className="flex justify-between text-5xl font-black italic pt-12 border-t-8 border-black tracking-tighter"><span>Total</span><span>৳{lastOrder.total}</span></div>
                  </div>

                  <div className="text-center pt-10 space-y-8">
