                  <div className="absolute top-0 right-0 p-20 opacity-[0.03] rotate-12"><i className="fas fa-shield-halved text-[200px]"></i></div>
                  <div className="w-48 h-48 themed-primary rounded-[50px] flex items-center justify-center text-7xl font-black border-8 border-white/5 shadow-4xl relative z-10">
                     <img src={`https://ui-avatars.com/api/?name=${currentUser.name}&background=random&color=fff&size=512`} className="w-full h-full object-cover rounded-[42px]" alt="" />
                     <div className="absolute -bottom-5 -right-5 bg-red-600 w-14 h-14 rounded-2xl flex items-center justify-center text-2xl border-4 border-[#020617] shadow-xl"><i className="fas fa-check-double"></i></div>
                  </div>
                  <div className="flex-1 text-center lg:text-left space-y-6 relative z-10">
                     <div className="inline-block px-6 py-2 bg-emerald-500/10 text-emerald-400 rounded-full text-[11px] font-black uppercase tracking-widest border border-emerald-500/20 shadow-xl">{currentUser.tier} LEVEL PERSONNEL</div>
                     <h3 className="text-6xl lg:text-7xl font-black italic uppercase leading-none tracking-tighter">{currentUser.name}</h3>
                     <div className="flex flex-wrap justify-center lg:justify-start gap-5 items-center">
                        <p className="text-red-500 font-black tracking-[6px] text-sm uppercase">@{currentUser.username}</p>
                        <span className="w-1.5 h-1.5 rounded-full bg-white/20"></span>
                        <p className="text-[12px] font-black uppercase opacity-40 tracking-widest">{currentUser.email}</p>
                     </div>
                  </div>
                  <div className="glass p-12 rounded-[55px] text-center min-w-[280px] border-white/10 shadow-3xl relative z-10">
                     <p className="text-[11px] font-black uppercase opacity-40 mb-4 tracking-[6px]">Pulse Credits</p>
                     <p className="text-7xl font-black italic themed-text-primary leading-none tracking-tighter">{currentUser.loyaltyPoints}</p>
                     <p className="text-[9px] font-bold opacity-30 uppercase mt-5 tracking-widest">Redeemable Units</p>
                  </div>
               </div>

               <div className="space-y-12">
                  <div className="flex items-center justify-between border-b border-white/5 pb-8">
                     <h4 className="text-4xl font-black italic uppercase tracking-widest">Mission Archive</h4>
                     <p className="text-[11px] font-black uppercase opacity-40 tracking-widest">{allOrders.filter(o => o.customerId === currentUser.id).length} Entries</p>
                  </div>
                  <div className="grid gap-8">
                     {allOrders.filter(o => o.customerId === currentUser.id).length > 0 ? (
                       allOrders.filter(o => o.customerId === currentUser.id).map(o => (
                         <div key={o.id} onClick={() => { setLastOrder(o); setView('RECEIPT'); }} className="glass p-10 lg:p-12 rounded-[55px] flex flex-col sm:flex-row justify-between items-center cursor-pointer group hover:border-red-600/30 transition-all border border-white/5 shadow-2xl hover:-translate-y-2">
                            <div className="flex gap-10 items-center w-full sm:w-auto">
                               <div className="w-20 h-20 glass rounded-3xl flex items-center justify-center text-3xl group-hover:themed-primary group-hover:text-white transition-all shadow-inner"><i className="fas fa-file-invoice opacity-30 group-hover:opacity-100"></i></div>
                               <div>
                                  <p className="text-[11px] font-black opacity-30 uppercase tracking-[6px] mb-2">ARCHIVE #{o.id}</p>
                                  <p className="font-black italic uppercase text-2xl leading-none">{new Date(o.createdAt).toLocaleDateString('en-GB')}</p>
                                  <p className="text-[10px] font-black uppercase opacity-40 mt-3 tracking-widest">{o.items.length} Units Deployed</p>
                               </div>
                            </div>
                            <div className="text-center sm:text-right w-full sm:w-auto mt-8 sm:mt-0 pt-8 sm:pt-0 border-t sm:border-t-0 border-white/5">
                               <p className="text-4xl font-black italic themed-text-primary leading-none tracking-tighter">৳{o.total}</p>
                               <div className="flex items-center justify-center sm:justify-end gap-3 mt-3">
                                  <div className={`w-2.5 h-2.5 rounded-full ${o.status === OrderStatus.DELIVERED ? 'bg-emerald-500 shadow-[0_0_10px_#10b981]' : 'bg-amber-500 shadow-[0_0_10px_#f59e0b]'}`}></div>
                                  <p className={`text-[11px] font-black uppercase tracking-widest ${o.status === OrderStatus.DELIVERED ? 'text-emerald-500' : 'text-amber-500'}`}>{o.status.replace(/_/g, ' ')}</p>
                               </div>
