                         </div>
                       ))
                     ) : (
                       <div className="text-center py-32 opacity-20 space-y-6">
                          <i className="fas fa-radar text-7xl"></i>
                          <p className="font-black uppercase text-[12px] tracking-widest">No prior mission logs</p>
                       </div>
                     )}
                  </div>
               </div>
            </div>
          </ViewWrapper>
        )}

        {view === 'LOGIN' && (
          <ViewWrapper>
            <div className="flex-1 flex items-center justify-center p-6 relative overflow-hidden">
               <div className="absolute inset-0 z-0 opacity-40 pointer-events-none">
                 <div className="absolute top-[-10%] right-[-10%] w-[60%] h-[60%] bg-red-600/10 blur-[150px] rounded-full"></div>
                 <div className="absolute bottom-[-10%] left-[-10%] w-[60%] h-[60%] bg-blue-600/5 blur-[150px] rounded-full"></div>
               </div>

               <div className="w-full max-w-xl z-10">
                  <div className="glass p-12 lg:p-16 rounded-[70px] border border-white/10 shadow-[0_50px_120px_rgba(0,0,0,0.6)] backdrop-blur-3xl space-y-14 relative overflow-hidden">
                     <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-red-600 to-transparent"></div>

                     <div className="text-center space-y-10">
                        <div className="relative inline-block group cursor-pointer">
                           <div className="w-28 h-28 bg-gradient-to-br from-red-500 to-red-700 rounded-[40px] flex items-center justify-center text-5xl font-black mx-auto shadow-4xl shadow-red-600/30 group-hover:scale-110 transition-transform duration-700">
                             <i className="fas fa-id-badge text-white"></i>
                           </div>
                           <div className="absolute -inset-4 bg-red-600/20 blur-2xl rounded-full opacity-0 group-hover:opacity-100 transition-opacity"></div>
                        </div>

                        <div className="space-y-4">
                           <h3 className="text-6xl font-black italic uppercase tracking-tighter leading-none">{authMode === 'LOGIN' ? 'Entry' : 'Protocol'}</h3>
                           <p className="text-[11px] font-black uppercase text-red-500 tracking-[15px] opacity-80">Authorization Registry</p>
                        </div>

                        <div className="flex p-2.5 glass rounded-[40px] border-white/5 bg-white/5 max-w-[340px] mx-auto shadow-inner">
                           <button onClick={() => setAuthMode('LOGIN')} className={`flex-1 py-5 rounded-[32px] text-[11px] font-black uppercase tracking-widest transition-all duration-700 ${authMode === 'LOGIN' ? 'themed-primary text-white shadow-2xl' : 'text-gray-500 opacity-40 hover:opacity-100'}`}>Check-In</button>
                           <button onClick={() => setAuthMode('REGISTER')} className={`flex-1 py-5 rounded-[32px] text-[11px] font-black uppercase tracking-widest transition-all duration-700 ${authMode === 'REGISTER' ? 'themed-primary text-white shadow-2xl' : 'text-gray-500 opacity-40 hover:opacity-100'}`}>Registry</button>
                        </div>
                     </div>

                     <div className="space-y-10">
                        {authMode === 'REGISTER' && (
                          <div className="space-y-4 animate-scale-in">
                             <label className="text-[10px] font-black uppercase tracking-[5px] opacity-40 ml-5">Personnel Name</label>
                             <div className="relative group">
                                <i className="fas fa-user-tag absolute left-7 top-1/2 -translate-y-1/2 opacity-20 group-focus-within:opacity-100 group-focus-within:themed-text-primary transition-all"></i>
                                <input value={regName} onChange={e => setRegName(e.target.value)} placeholder="ARIF HOSSAIN" className="w-full glass bg-white/5 p-7 pl-16 rounded-[35px] outline-none border border-white/5 font-black uppercase text-sm focus:border-red-600/50 transition-all focus:bg-white/10 shadow-inner" />
                             </div>
                          </div>
                        )}
                        <div className="space-y-4">
                           <label className="text-[10px] font-black uppercase tracking-[5px] opacity-40 ml-5">Neural Handle (Email)</label>
                           <div className="relative group">
                              <i className="fas fa-fingerprint absolute left-7 top-1/2 -translate-y-1/2 opacity-20 group-focus-within:opacity-100 group-focus-within:themed-text-primary transition-all"></i>
                              <input value={loginId} onChange={e => setLoginId(e.target.value)} placeholder="PERSONNEL@BFC.COM" className="w-full glass bg-white/5 p-7 pl-16 rounded-[35px] outline-none border border-white/5 font-black text-sm focus:border-red-600/50 transition-all focus:bg-white/10 shadow-inner" />
                           </div>
                        </div>
                     </div>

                     <div className="pt-10 space-y-10">
                        <Button fullWidth size="lg" className="rounded-[40px] py-10 shadow-4xl text-lg relative group overflow-hidden" onClick={() => {
                           if (!loginId) return showToast('Identity Required', 'warning');
                           const isAdmin = loginId.toLowerCase().includes('admin');
                           const u: User = {
                             id: 'U-' + Math.random().toString(36).slice(2, 7),
                             name: authMode === 'REGISTER' ? regName : (isAdmin ? 'Admin Commander' : 'Honored Guest'),
                             username: isAdmin ? 'admin' : 'guest_' + Math.random().toString(36).slice(2,6),
                             hasCustomizedUsername: false,
                             email: loginId,
                             role: isAdmin ? UserRole.ADMIN : UserRole.CUSTOMER,
                             loyaltyPoints: 1250,
                             tier: isAdmin ? 'SUPREME' : 'GOLD',
                           };
                           setCurrentUser(u);
                           isAdmin ? setView('ADMIN') : setView('HOME');
                           showToast('Authorized', 'success');
                        }}>
                          <span className="relative z-10 tracking-[6px]">{authMode === 'LOGIN' ? 'VALIDATE IDENTITY' : 'ESTABLISH ENTRY'}</span>
                          <div className="absolute inset-0 bg-white/10 translate-y-full group-hover:translate-y-0 transition-transform duration-700"></div>
                        </Button>
                        <div className="text-center">
                           <button onClick={() => setView('HOME')} className="text-[10px] font-black uppercase tracking-[10px] text-gray-600 hover:text-white transition-all py-3 hover:tracking-[12px] duration-700">Return to interface</button>
                        </div>
                     </div>
                  </div>
               </div>
            </div>
          </ViewWrapper>
        )}
      </main>

      {/* Persistent Mobile Navigation */}
      {view !== 'RECEIPT' && view !== 'LOGIN' && view !== 'ADMIN' && (
        <nav className="fixed bottom-0 inset-x-0 z-[6000] lg:hidden glass border-t border-white/10 flex justify-around items-center h-28 safe-bottom shadow-[0_-20px_50px_rgba(0,0,0,0.5)]">
           {[
             { id: 'HOME', icon: 'fa-house', label: 'Core' },
             { id: 'MENU', icon: 'fa-utensils', label: 'Menu' },
             { id: 'CART', icon: 'fa-shopping-bag', label: 'Bag' },
             { id: 'VAULT', icon: 'fa-shield-halved', label: 'Vault' }
           ].map(item => (
             <button key={item.id} onClick={() => setView(item.id as any)} className={`flex flex-col items-center gap-2.5 w-full transition-all duration-500 ${view === item.id ? 'themed-text-primary scale-110' : 'text-gray-500 opacity-40'}`}>
                <i className={`fas ${item.icon} text-2xl`}></i>
                <span className="text-[10px] font-black uppercase tracking-[5px]">{item.label}</span>
             </button>
           ))}
        </nav>
      )}

      <ChatBot isOnline={!isOffline} currentUser={currentUser} menuItems={menuItems} setCart={setCart} setView={setView} />

      <div className="fixed top-28 right-6 z-[10000] space-y-5 max-w-sm w-full pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto bg-gray-900/95 backdrop-blur-3xl p-6 rounded-[35px] animate-elite-up border-l-4 border-red-600 shadow-4xl ring-1 ring-white/10">
            <div className="flex items-center gap-5">
               <div className={`w-10 h-10 rounded-2xl flex items-center justify-center text-sm text-white shadow-lg ${t.type === 'error' ? 'bg-red-600' : t.type === 'warning' ? 'bg-amber-600' : 'bg-emerald-600'}`}>
                  <i className={`fas ${t.type === 'error' ? 'fa-bolt' : t.type === 'warning' ? 'fa-exclamation' : 'fa-check'}`}></i>
               </div>
               <div>
                  <p className="text-[11px] font-black uppercase tracking-widest text-white leading-none">{t.message}</p>
                  {t.description && <p className="text-[10px] opacity-50 mt-1.5 leading-relaxed text-gray-300 font-medium">{t.description}</p>}
               </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;

export enum UserRole {
  ADMIN = 'ADMIN',
  MANAGER = 'MANAGER',
  STAFF = 'STAFF',
  CUSTOMER = 'CUSTOMER'
}

export enum OrderStatus {
  PENDING = 'PENDING',
  PREPARING = 'PREPARING',
  READY = 'READY',
  ON_THE_WAY = 'ON_THE_WAY',
  DELIVERED = 'DELIVERED',
  CANCELLED = 'CANCELLED'
}

export type LayoutPreset = 
  | 'ELITE_DARK' 
  | 'CLASSIC_RED' 
  | 'BFC_CLASSIC'
  | 'CYBER_NEON' 
  | 'MINIMAL_WHITE' 
  | 'NATURE_GREEN' 
  | 'LUXURY_GOLD' 
  | 'RETRO_VIBE' 
  | 'BOLD_MONO' 
  | 'PASTEL_SOFT' 
  | 'HIGH_TECH';

export interface ThemeConfig {
  bg: string;
  fg: string;
  primary: string;
  accent: string;
  card: string;
  border: string;
  font: string;
  shadow: string;
}

export interface Promotion {
  id: string;
  name: string;
  code: string;
  discountType: 'PERCENTAGE' | 'FIXED';
  discountValue: number;
  startDate: string;
  endDate: string;
  usageLimit: number;
  usageCount: number;
  isActive: boolean;
}

export interface LoyaltyTier {
  id: string;
  name: string;
  minPoints: number;
  benefits: string[];
  color: string;
}

export interface SiteCMS {
  activeLayout: LayoutPreset;
  themeDefinitions: Record<LayoutPreset, ThemeConfig>;
  deliveryCharge: number;
  hero: {
    title: string;
    subtitle: string;
    description: string;
    image: string;
    cta: string;
  };
  navigation: {
    brand: string;
    links: { [key: string]: string };
  };
  vault: {
    title: string;
    description: string;
  };
}

export interface MenuItem {
  id: string;
  name: string;
  nameBn: string;
  description: string;
  price: number;
  category: string;
  image: string;
  stock: number;
  rating?: number;
  ingredients?: string[];
  dietary?: string[];
  prepTime?: string;
  isPopular?: boolean;
}

export interface CartItem {
  item: MenuItem;
  qty: number;
}

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  customerPhone: string;
  customerEmail: string;
  address: string;
  items: CartItem[];
  subtotal: number;
  deliveryCharge: number;
  discount: number;
  total: number;
  status: OrderStatus;
  createdAt: string;
  paymentMethod: string;
  paymentDetails?: any;
}

export interface User {
  id: string;
  name: string;
  username: string;
  hasCustomizedUsername: boolean;
  email: string;
  phone?: string;
  address?: string;
  favoriteCategory?: string;
  role: UserRole;
  loyaltyPoints: number;
  tier: string;
  claimedVouchers?: string[];
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { MenuItem, UserRole, User, Order, CartItem, SiteCMS, OrderStatus, Promotion } from './types';
import { MOCK_MENU, MOCK_ORDERS, DEFAULT_THEMES } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';
import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';

interface Toast {
  id: number;
  message: string;
  description?: string;
  type: 'success' | 'error' | 'warning' | 'info';
}

const DEFAULT_CMS: SiteCMS = {
  activeLayout: 'ELITE_DARK',
  themeDefinitions: DEFAULT_THEMES,
  deliveryCharge: 50,
  hero: {
    title: "Experience Elite Bangladeshi Cuisine",
    subtitle: "The Real Taste Of Bangla",
    description: "Indulge in the finest culinary heritage of Bangladesh. Where tradition meets high-tech precision in every bite.",
    image: "https://images.unsplash.com/photo-1633945274405-b6c8069047b0?q=80&w=2000",
    cta: "ACCESS REGISTRY"
  },
  navigation: {
    brand: "BFC ELITE",
    links: { home: "HOME", menu: "MENU", vault: "VAULT", profile: "PROFILE" }
  },
  vault: {
    title: "ELITE VAULT",
    description: "Manage your credits and unlock secret menu deployments."
  }
};

const App: React.FC = () => {
  const [cms, setCms] = useState<SiteCMS>(() => {
    const saved = localStorage.getItem('bfc_cms');
    return saved ? JSON.parse(saved) : DEFAULT_CMS;
  });
  const [menuItems, setMenuItems] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('bfc_menu');
    return saved ? JSON.parse(saved) : MOCK_MENU;
  });
  const [allOrders, setAllOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('bfc_orders');
    return saved ? JSON.parse(saved) : MOCK_ORDERS;
  });
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });
  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('bfc_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT' | 'CHECKOUT' | 'RECEIPT'>('HOME');
  const [checkoutStep, setCheckoutStep] = useState<'ADDRESS' | 'PAYMENT'>('ADDRESS');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [lastOrder, setLastOrder] = useState<Order | null>(null);

  // Auth States
  const [loginId, setLoginId] = useState('');
  const [regData, setRegData] = useState({
    name: '',
    username: '',
    email: '',
    phone: '',
    address: '',
    favCategory: 'Biryani'
  });

  // Form States (Checkout)
  const [addressData, setAddressData] = useState({ name: '', phone: '', city: 'Dhaka', street: '' });
  const [promoCode, setPromoCode] = useState('');
  const [activePromo, setActivePromo] = useState<Promotion | null>(null);
  const [paymentMethod, setPaymentMethod] = useState<'BKASH' | 'NAGAD' | 'CARD' | 'COD'>('BKASH');

  const receiptRef = useRef<HTMLDivElement>(null);

  const showToast = useCallback((message: string, type: Toast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, description }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
  }, []);

  useEffect(() => {
    const handleOnline = () => { setIsOffline(false); showToast('Link Restored', 'success', 'Neural core synchronized.'); };
    const handleOffline = () => { setIsOffline(true); showToast('Link Severed', 'error', 'Working in offline mode.'); };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [showToast]);

  useEffect(() => { localStorage.setItem('bfc_cms', JSON.stringify(cms)); }, [cms]);
  useEffect(() => { localStorage.setItem('bfc_menu', JSON.stringify(menuItems)); }, [menuItems]);
  useEffect(() => { localStorage.setItem('bfc_orders', JSON.stringify(allOrders)); }, [allOrders]);
  useEffect(() => { localStorage.setItem('bfc_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { localStorage.setItem('bfc_user', JSON.stringify(currentUser)); }, [currentUser]);

  const subtotal = useMemo(() => cart.reduce((a, b) => a + (b.item.price * b.qty), 0), [cart]);
  const discountAmount = useMemo(() => {
    if (!activePromo) return 0;
    return activePromo.discountType === 'PERCENTAGE' 
      ? (subtotal * activePromo.discountValue) / 100 
      : activePromo.discountValue;
  }, [subtotal, activePromo]);
  const total = subtotal + cms.deliveryCharge - discountAmount;

  const handleApplyPromo = () => {
    const found = [
      { id: '1', name: 'Welcome', code: 'BFC50', discountType: 'FIXED', discountValue: 50, isActive: true },
      { id: '2', name: 'Elite', code: 'ELITE20', discountType: 'PERCENTAGE', discountValue: 20, isActive: true }
    ].find(p => p.code === promoCode.toUpperCase() && p.isActive);
    if (found) {
      setActivePromo(found as any);
      showToast('Promo Secured', 'success', `Discount applied.`);
    } else {
      showToast('Invalid Code', 'error', 'Transmission code not recognized.');
    }
  };

  const processPayment = async () => {
    if (isOffline) return showToast('Deployment Error', 'error', 'Neural link is offline.');
    const phoneRegex = /^01[3-9]\d{8}$/;
    if (!phoneRegex.test(addressData.phone)) return showToast('Invalid Identification', 'warning', 'Phone number required.');

    const order: Order = {
      id: 'BFC-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
      customerId: currentUser?.id || 'GUEST',
      customerName: addressData.name || currentUser?.name || 'Honored Guest',
      customerPhone: addressData.phone,
      customerEmail: currentUser?.email || 'unregistered@bfc.com',
      address: `${addressData.street}, ${addressData.city}`,
      items: [...cart],
      subtotal,
      deliveryCharge: cms.deliveryCharge,
      discount: discountAmount,
      total,
      status: OrderStatus.PENDING,
      createdAt: new Date().toISOString(),
      paymentMethod,
    };

    showToast('Authorizing Credits', 'info', 'Verifying transaction...');
    await new Promise(r => setTimeout(r, 1500));
    setAllOrders(prev => [order, ...prev]);
    setLastOrder(order);
    setCart([]);
    setView('RECEIPT');
    showToast('Mission Dispatched', 'success', 'Deployment successful.');
  };

  const downloadReceiptImage = async () => {
    if (!receiptRef.current) return;
    const canvas = await html2canvas(receiptRef.current, { scale: 3, backgroundColor: '#ffffff', useCORS: true });
    const link = document.createElement('a');
    link.download = `BFC-Receipt-${lastOrder?.id}.png`;
    link.href = canvas.toDataURL('image/png');
    link.click();
    showToast('Manifest Saved', 'success');
  };

  const downloadReceiptPDF = async () => {
    if (!receiptRef.current) return;
    const canvas = await html2canvas(receiptRef.current, { scale: 3, backgroundColor: '#ffffff' });
    const imgData = canvas.toDataURL('image/png');
    const pdf = new jsPDF('p', 'mm', 'a4');
    const pdfWidth = pdf.internal.pageSize.getWidth();
    const pdfHeight = (canvas.height * pdfWidth) / canvas.width;
    pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
    pdf.save(`BFC-Receipt-${lastOrder?.id}.pdf`);
    showToast('PDF Document Saved', 'success');
  };

  const ViewWrapper: React.FC<{ children: React.ReactNode }> = ({ children }) => (
    <div className="flex-1 flex flex-col animate-elite-up gpu-accel">
      {children}
    </div>
  );

  if (view === 'ADMIN' && currentUser?.role === UserRole.ADMIN) {
    return <AdminPanel cms={cms} setCms={setCms} menuItems={menuItems} setMenuItems={setMenuItems} orders={allOrders} setOrders={setAllOrders} onLogout={() => { setView('HOME'); setCurrentUser(null); }} />;
  }

  return (
    <div className={`min-h-screen flex flex-col bg-[#020617] text-white selection:bg-red-600/30 theme-${cms.activeLayout}`}>
