               <div className="w-full max-w-4xl z-10">
                  <div className="glass p-10 lg:p-14 rounded-[70px] border border-white/10 shadow-[0_50px_120px_rgba(0,0,0,0.6)] backdrop-blur-3xl space-y-12 relative overflow-hidden">
