                           <button onClick={() => setAuthMode('REGISTER')} className={`flex-1 py-4 rounded-[32px] text-[11px] font-black uppercase tracking-widest transition-all duration-700 ${authMode === 'REGISTER' ? 'themed-primary text-white shadow-2xl' : 'text-gray-500 opacity-40 hover:opacity-100'}`}>Registry</button>
                        </div>
                     </div>

                     {authMode === 'LOGIN' ? (
                       <div className="max-w-md mx-auto space-y-8 animate-scale-in">
                         <div className="space-y-4">
                            <label className="text-[10px] font-black uppercase tracking-[5px] opacity-40 ml-5">Neural Handle (Email)</label>
                            <div className="relative group">
                               <i className="fas fa-fingerprint absolute left-7 top-1/2 -translate-y-1/2 opacity-20 group-focus-within:opacity-100 group-focus-within:themed-text-primary transition-all"></i>
                               <input value={loginId} onChange={e => setLoginId(e.target.value)} placeholder="PERSONNEL@BFC.COM" className="w-full glass bg-white/5 p-7 pl-16 rounded-[35px] outline-none border border-white/5 font-black text-sm focus:border-red-600/50 transition-all shadow-inner" />
