                <h2 className="text-6xl lg:text-9xl font-black italic uppercase tracking-tighter leading-none text-glow">Mainframe CMS</h2>
                <p className="text-[12px] font-black text-red-600 uppercase tracking-[12px]">Platform Narrative Registry</p>
              </header>
              <div className="glass p-10 lg:p-20 rounded-[80px] border-white/5 space-y-16 shadow-4xl relative overflow-hidden">
                <div className="absolute bottom-0 right-0 p-32 opacity-[0.02] rotate-45 pointer-events-none"><i className="fas fa-microchip text-[400px]"></i></div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-12 lg:gap-16">
                   <div className="md:col-span-2 space-y-8">
                      <label className="text-[12px] font-black uppercase tracking-[8px] opacity-40 ml-6">Global Interface Protocol</label>
                      <div className="grid grid-cols-2 sm:grid-cols-4 gap-6">
                        {(['ELITE_DARK', 'BFC_CLASSIC', 'CLASSIC_RED', 'CYBER_NEON'] as LayoutPreset[]).map(layout => (
                          <button key={layout} onClick={() => setCms({...cms, activeLayout: layout})} className={`p-8 rounded-[40px] border-2 text-[12px] font-black uppercase tracking-widest transition-all ${cms.activeLayout === layout ? 'border-red-600 bg-red-600/10 shadow-4xl scale-105' : 'border-white/5 bg-white/5 opacity-40 hover:opacity-100 hover:scale-105'}`}>
                            {layout.replace(/_/g, ' ')}
                          </button>
                        ))}
                      </div>
                   </div>
                   <InputGroup label="Core Platform Label" value={cms.navigation.brand} onChange={v => setCms({...cms, navigation: {...cms.navigation, brand: v}})} placeholder="BFC Hub" />
                   <InputGroup label="Hero Visual Brief" value={cms.hero.title} onChange={v => setCms({...cms, hero: {...cms.hero, title: v}})} placeholder="Mission Objective" />
                   <div className="md:col-span-2">
                     <InputGroup label="Mission Narrative Description" value={cms.hero.description} onChange={v => setCms({...cms, hero: {...cms.hero, description: v}})} placeholder="Describe the deployment goal..." />
                   </div>
                   <div className="md:col-span-2">
                     <InputGroup label="Hero Imagery Deployment (URL)" value={cms.hero.image} onChange={v => setCms({...cms, hero: {...cms.hero, image: v}})} placeholder="Background Asset Link" />
                   </div>
                </div>
                <div className="pt-16 border-t border-white/10 flex justify-end relative z-10">
                  <Button size="lg" className="rounded-[50px] !px-24 shadow-4xl py-12 text-xl">SYNC MAINFRAME</Button>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

