  <div className="glass p-10 rounded-[55px] flex items-center gap-10 group hover:border-red-600/30 transition-all border border-white/5 shadow-3xl relative overflow-hidden">
    <div className={`w-20 h-20 bg-white/5 rounded-3xl flex items-center justify-center text-3xl ${color} shadow-inner group-hover:themed-primary group-hover:text-white transition-all`}>
      <i className={`fas ${icon}`}></i>
    </div>
    <div className="space-y-2">
      <div className="flex items-center gap-4">
        <p className="text-[11px] font-black uppercase tracking-[5px] opacity-40">{label}</p>
        {trend && <span className="text-[10px] font-black px-3 py-1 rounded-full bg-emerald-500/20 text-emerald-500">{trend}</span>}
      </div>
      <h4 className="text-5xl font-black italic leading-none tracking-tighter">{value}</h4>
    </div>
  </div>
);

const ColorInput = ({ label, value, onChange }: { label: string, value: string, onChange: (v: string) => void }) => (
  <div className="space-y-4">
    <label className="text-[11px] font-black uppercase tracking-[6px] opacity-40 ml-5">{label}</label>
    <div className="flex gap-5">
      <div className="w-20 h-20 rounded-[30px] border-2 border-white/10 shrink-0 relative overflow-hidden shadow-2xl group cursor-pointer hover:scale-105 transition-transform">
        <input type="color" value={value} onChange={(e) => onChange(e.target.value)} className="absolute inset-0 w-[200%] h-[200%] translate-x-[-25%] translate-y-[-25%] cursor-pointer opacity-0" />
        <div className="w-full h-full" style={{ backgroundColor: value }}></div>
      </div>
      <input type="text" value={value} onChange={(e) => onChange(e.target.value)} className="flex-1 glass border border-white/10 p-7 rounded-[30px] font-mono text-[12px] outline-none focus:border-red-600 transition-all text-white bg-black/40 shadow-inner" />
    </div>
  </div>
);

const InputGroup = ({ label, value, onChange, type = 'text', placeholder }: { label: string, value: string, onChange: (v: string) => void, type?: string, placeholder?: string }) => (
  <div className="space-y-4">
    <label className="text-[11px] font-black uppercase tracking-[6px] opacity-40 ml-6">{label}</label>
    <input type={type} value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} className="w-full glass border border-white/10 p-8 lg:p-9 rounded-[45px] font-bold text-base outline-none focus:border-red-600/50 transition-all placeholder:opacity-20 shadow-inner text-white bg-black/40" />
  </div>
);

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { decodeAudio, decodeAudioData, encodeAudio, getAiInstance, bfcFastText } from '../services/geminiService';
import { ChatMessage, User, MenuItem, CartItem } from '../types';
import { LiveServerMessage, Modality } from '@google/genai';

interface ChatBotProps {
  isOnline?: boolean;
  currentUser?: User | null;
  setView?: (view: any) => void;
  setCart?: React.Dispatch<React.SetStateAction<CartItem[]>>;
  menuItems: MenuItem[];
  lastUpdate?: MenuItem | null;
}

const OFFLINE_BRAIN = [
  { keywords: ['menu', 'food', 'খাবার', 'মেনু'], response: "স্যার, বর্তমানে আমাদের কাছে কাচ্চি, রোস্ট, পোলাও এবং কাবাব আছে। মেনু সেকশনে বিস্তারিত দেখতে পাবেন।" },
  { keywords: ['price', 'দাম', 'কত'], response: "খাবারের দাম ৪ ১৫০ টাকা থেকে শুরু। বিরিয়ানি ৪৫০ এবং কাবাব ১৫০ টাকা।" },
  { keywords: ['order', 'অর্ডার', 'কিনব'], response: "আপনি 'SECURE TO BAG' বাটনে ক্লিক করে খাবার কার্টে যোগ করতে পারেন, তারপর চেকআউট করুন।" },
  { keywords: ['status', 'অবস্থা', 'কোথায়'], response: "দুঃখিত স্যার, অফলাইনে লাইভ ট্র্যাকিং সম্ভব নয়। ইন্টারনেট সংযোগ ফিরে এলে আপডেট পাবেন।" },
  { keywords: ['help', 'সাহায্য', 'সহায়তা'], response: "আমি আপনাকে মেনু এবং সাধারণ তথ্যে সাহায্য করতে পারি। অফলাইনে আমার ক্ষমতা সীমিত।" },
];

export const ChatBot: React.FC<ChatBotProps> = ({ isOnline = true, currentUser, setView, setCart, menuItems, lastUpdate }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [hasNewUpdate, setHasNewUpdate] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([{ 
    role: 'model', 
    text: "আসসালামু আলাইকুম, আমি বিএফসি থেকে বলছি। কিভাবে আপনাকে সাহায্য করতে পারি?", 
    timestamp: new Date() 
  }]);
  const [input, setInput] = useState('');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isMicOn, setIsMicOn] = useState(false);
  const [currentTranscription, setCurrentTranscription] = useState('');
  const [recentlyViewed, setRecentlyViewed] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('bfc_recent');
    return saved ? JSON.parse(saved) : [];
  });

  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const compressorNodeRef = useRef<DynamicsCompressorNode | null>(null);
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const scrollRef = useRef<HTMLDivElement>(null);
  const micStreamRef = useRef<MediaStream | null>(null);
  const transcriptionRef = useRef('');
  const recognitionRef = useRef<any>(null);

  const stopAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setIsSpeaking(false);
    if (window.speechSynthesis.speaking) {
      window.speechSynthesis.cancel();
    }
  };

  const initAudioOutput = async () => {
    if (!outputAudioContextRef.current) {
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      outputAudioContextRef.current = ctx;
      const compressor = ctx.createDynamicsCompressor();
      const makeupGain = ctx.createGain();
      makeupGain.gain.setValueAtTime(4.0, ctx.currentTime);
      compressor.connect(makeupGain);
      makeupGain.connect(ctx.destination);
      compressorNodeRef.current = compressor;
    }
    if (outputAudioContextRef.current.state === 'suspended') {
      await outputAudioContextRef.current.resume();
    }
  };

  const speakOffline = (text: string) => {
    if (!('speechSynthesis' in window)) return;
    stopAudio();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'bn-BD';
    utterance.rate = 1.0;
    utterance.pitch = 1.0;
    utterance.onstart = () => setIsSpeaking(true);
    utterance.onend = () => setIsSpeaking(false);
    window.speechSynthesis.speak(utterance);
  };

  // React to lastUpdate prop from AdminPanel
  useEffect(() => {
    if (lastUpdate) {
      setHasNewUpdate(true);
      const updateMsg = `ব্রেকিং নিউজ! আমাদের মেনুতে ${lastUpdate.nameBn} যুক্ত হয়েছে/আপডেট হয়েছে। আপনি কি এটি ট্রাই করতে চান?`;
      setMessages(prev => [...prev, { role: 'model', text: updateMsg, timestamp: new Date() }]);

      if (!isOpen) {
        // Automatically open the bot if there's a critical update
        setIsOpen(true);
      }

      if (!isOnline) {
        speakOffline(updateMsg);
      } else {
        // If online session exists, push the update to AI context
        if (sessionPromiseRef.current) {
          sessionPromiseRef.current.then(s => s.sendRealtimeInput({
            message: { parts: [{ text: `System Alert: A menu item was just updated or added: ${lastUpdate.name}. Please inform the user proactively and cheerfully.` }] }
          }));
        }
      }
    }
  }, [lastUpdate, isOnline]);

  const processOfflineActions = (query: string): string | null => {
    const q = query.toLowerCase();

    // 1. Check for Cart Actions
    const cartKeywords = ['add', 'order', 'bag', 'অর্ডার', 'দাও', 'কিনব', 'যোগ'];
    if (cartKeywords.some(k => q.includes(k))) {
      const targetItem = menuItems.find(item => 
        q.includes(item.name.toLowerCase()) || q.includes(item.nameBn)
      );
      if (targetItem && setCart) {
        setCart(prev => {
          const ex = prev.find(c => c.item.id === targetItem.id);
          if (ex) return prev.map(x => x.item.id === targetItem.id ? { ...x, qty: x.qty + 1 } : x);
          return [...prev, { item: targetItem, qty: 1 }];
        });
        // Track recently viewed
        setRecentlyViewed(prev => {
          const filtered = prev.filter(p => p.id !== targetItem.id);
          const next = [targetItem, ...filtered].slice(0, 3);
          localStorage.setItem('bfc_recent', JSON.stringify(next));
          return next;
        });
        return `জি স্যার, আমি ${targetItem.nameBn} আপনার কার্টে যোগ করে দিয়েছি। আর কিছু লাগবে?`;
      }
    }

    // 2. Navigation Actions
    if (q.includes('menu') || q.includes('মেনু')) {
      if (setView) setView('MENU');
      return "জি স্যার, আমাদের মেনু সেকশন খুলে দিয়েছি।";
    }

    if (q.includes('cart') || q.includes('bag') || q.includes('ব্যাগ')) {
      if (setView) setView('CART');
      return "জি স্যার, আপনার ব্যাগ খুলে দিয়েছি।";
    }

    return null;
  };

  const getOfflineResponse = (query: string): string => {
    // Try action first
    const actionResp = processOfflineActions(query);
    if (actionResp) return actionResp;

    const q = query.toLowerCase();
    const match = OFFLINE_BRAIN.find(entry => 
      entry.keywords.some(k => q.includes(k))
    );
    return match ? match.response : "দুঃখিত স্যার, ইন্টারনেট সংযোগ নেই। আমি শুধু মেনু এবং কার্টে খাবার যোগ করতে সাহায্য করতে পারছি।";
  };

  const connectLive = useCallback(async () => {
    if (!isOnline || sessionPromiseRef.current) return;
    await initAudioOutput();
    const ai = getAiInstance();
    const currentMenuString = menuItems.map(i => `${i.name} (৳${i.price})`).join(", ");
    const updateHint = lastUpdate ? `Note: ${lastUpdate.name} was just recently added or updated.` : '';

    try {
      sessionPromiseRef.current = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            sessionPromiseRef.current?.then(s => s.sendRealtimeInput({
              message: { parts: [{ text: `Greeting: 'আসসালামু আলাইকুম'। আপনি বিএফসি থেকে বলছেন। ${updateHint} নতুন কোনো মেনু আপডেট থাকলে সেটি উল্লেখ করুন।` }] }
            }));
          },
          onmessage: async (msg: LiveServerMessage) => {
            const audioData = msg.serverContent?.modelTurn?.parts?.find(p => p.inlineData)?.inlineData?.data;
            if (audioData && outputAudioContextRef.current && compressorNodeRef.current) {
              setIsSpeaking(true);
              const ctx = outputAudioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decodeAudio(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(compressorNodeRef.current!);
              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              };
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }
            if (msg.serverContent?.outputTranscription) {
              transcriptionRef.current += msg.serverContent.outputTranscription.text;
              setCurrentTranscription(transcriptionRef.current);
            }
            if (msg.serverContent?.turnComplete) {
              const fullText = transcriptionRef.current || "জি স্যার, আমি শুনছি।";
              setMessages(prev => [...prev, { role: 'model', text: fullText, timestamp: new Date() }]);
              transcriptionRef.current = '';
              setCurrentTranscription('');
            }
            if (msg.serverContent?.interrupted) stopAudio();
          },
          onerror: (e) => { sessionPromiseRef.current = null; },
          onclose: () => { sessionPromiseRef.current = null; }
        },
        config: {
          responseModalities: [Modality.AUDIO], 
          outputAudioTranscription: {},
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
          systemInstruction: `আপনি বিএফসি (Bangla Food Club) এর একজন অত্যন্ত বিনয়ী সহকারী।
আপনার নিয়মাবলী:
১. কথা শুরু করবেন শুধুমাত্র একবার 'আসসালামু আলাইকুম' দিয়ে।
২. আপনার আলোচনার বিষয় শুধুমাত্র বিএফসি-র বর্তমান খাবার: ${currentMenuString}।
৩. যদি কোনো নতুন খাবার লিস্টে দেখেন যা আগে ছিল না (${updateHint}), কাস্টমারকে সেটি ট্রাই করতে বলুন।
৪. পেমেন্ট পদ্ধতি: বিকাশ ও ক্যাশ অন ডেলিভারি।
৫. কাস্টমারকে সবসময় 'জি স্যার/ম্যাম' বলে সম্বোধন করবেন এবং সর্বোচ্চ সম্মান দিবেন।
৬. উত্তর খুব ছোট এবং স্পষ্ট রাখবেন (১-২ লাইন)।`
        }
      });
    } catch (e) { 
      sessionPromiseRef.current = null;
    }
  }, [isOnline, menuItems, lastUpdate]);

  const handleSend = async (textOverride?: string) => {
    const text = textOverride || input.trim();
    if (!text) return;
    stopAudio();
    setMessages(prev => [...prev, { role: 'user', text, timestamp: new Date() }]);
    setInput('');

    if (!isOnline) {
      const response = getOfflineResponse(text);
      setMessages(prev => [...prev, { role: 'model', text: response, timestamp: new Date() }]);
      speakOffline(response);
      return;
    }

    await initAudioOutput();
    if (sessionPromiseRef.current) {
      sessionPromiseRef.current.then(s => s.sendRealtimeInput({ message: { parts: [{ text }] } }));
    } else {
      const resp = await bfcFastText(text, menuItems, currentUser?.name);
      setMessages(prev => [...prev, { role: 'model', text: resp, timestamp: new Date() }]);
    }
  };

  const toggleMic = async () => {
    await initAudioOutput();

    if (isMicOn) {
      if (isOnline) {
        if (micStreamRef.current) micStreamRef.current.getTracks().forEach(t => t.stop());
      } else if (recognitionRef.current) {
        recognitionRef.current.stop();
      }
      setIsMicOn(false);
      return;
    }

    if (!isOnline) {
      // Offline Web Speech API
      const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      if (!SpeechRecognition) {
        showOfflineNotice("ভয়েস কমান্ডের জন্য আধুনিক ব্রাউজার প্রয়োজন।");
        return;
      }
      const recognition = new SpeechRecognition();
      recognition.lang = 'bn-BD';
      recognition.continuous = false;
      recognition.interimResults = true;
      recognition.onstart = () => setIsMicOn(true);
      recognition.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setCurrentTranscription(transcript);
        if (event.results[0].isFinal) {
          handleSend(transcript);
          setIsMicOn(false);
        }
      };
      recognition.onerror = () => setIsMicOn(false);
      recognition.onend = () => setIsMicOn(false);
      recognitionRef.current = recognition;
      recognition.start();
      return;
    }

    // Online Live API Mic
    try {
      if (!sessionPromiseRef.current) await connectLive();
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;
      setIsMicOn(true);
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const source = ctx.createMediaStreamSource(stream);
      const processor = ctx.createScriptProcessor(2048, 1, 1);
      processor.onaudioprocess = (e) => {
        const inputData = e.inputBuffer.getChannelData(0);
        const int16 = new Int16Array(inputData.length);
        for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
        sessionPromiseRef.current?.then(s => s.sendRealtimeInput({
          media: { data: encodeAudio(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' }
        }));
      };
      source.connect(processor);
      processor.connect(ctx.destination);
    } catch (e) { setIsMicOn(false); }
  };

  const showOfflineNotice = (txt: string) => {
    setMessages(prev => [...prev, { role: 'model', text: txt, timestamp: new Date() }]);
    speakOffline(txt);
  };

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'auto' });
  }, [messages, currentTranscription]);

  useEffect(() => {
    if (isOpen && isOnline) {
      connectLive();
      setHasNewUpdate(false);
    }
  }, [isOpen, connectLive, isOnline]);

  return (
    <div className="fixed bottom-32 right-4 lg:bottom-10 lg:right-10 z-[10000]">
      {isOpen ? (
        <div className={`bg-gray-900/98 backdrop-blur-3xl w-[85vw] sm:w-[350px] h-[500px] rounded-[40px] shadow-[0_40px_100px_rgba(0,0,0,0.6)] flex flex-col border-4 ${isOnline ? 'border-red-600' : 'border-amber-500'} overflow-hidden animate-elite-up`}>
          <div className={`${isOnline ? 'bg-red-600' : 'bg-amber-500'} p-5 text-white flex justify-between items-center shrink-0 shadow-lg relative z-10`}>
            <div className="flex items-center gap-3">
               <div className={`w-10 h-10 rounded-2xl flex items-center justify-center bg-white ${isOnline ? 'text-red-600' : 'text-amber-500'} ${isSpeaking ? 'animate-pulse shadow-[0_0_15px_white]' : ''}`}>
                  <i className={`fas ${isSpeaking ? 'fa-volume-up' : 'fa-headset'} text-sm`}></i>
               </div>
               <div className="flex flex-col">
                  <span className="text-[10px] font-black uppercase tracking-widest leading-tight">BFC {isOnline ? 'Official Assist' : 'Offline Mode'}</span>
                  {!isOnline && <span className="text-[8px] font-black uppercase opacity-60 tracking-wider">Neural Link Severed</span>}
               </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="w-9 h-9 bg-white/10 rounded-xl flex items-center justify-center active:scale-90 transition-all"><i className="fas fa-times text-xs"></i></button>
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-5 space-y-5 no-scrollbar bg-black/40 relative">
            {!isOnline && (
              <div className="sticky top-0 z-20 text-center p-3 bg-amber-500/10 backdrop-blur-md border border-amber-500/30 rounded-3xl mb-4 shadow-xl">
                 <p className="text-[9px] font-black uppercase text-amber-500 tracking-[4px]">Local Intelligence Engine Active</p>
                 <div className="mt-2 flex gap-2 justify-center overflow-x-auto no-scrollbar pb-1">
                    {['মেনু দেখাও', 'কাচ্চি দাও', 'অর্ডার'].map(cmd => (
                      <button key={cmd} onClick={() => setInput(cmd)} className="px-3 py-1 bg-amber-500/20 rounded-full text-[8px] font-black text-amber-300 border border-amber-500/10 hover:bg-amber-500/40 transition-all uppercase">{cmd}</button>
                    ))}
                 </div>
              </div>
            )}

            {recentlyViewed.length > 0 && !isOnline && (
              <div className="space-y-2 mb-4">
                 <p className="text-[7px] font-black uppercase opacity-30 tracking-[3px] ml-2">Recently Viewed</p>
                 <div className="flex gap-3 overflow-x-auto no-scrollbar">
                    {recentlyViewed.map(item => (
                      <div key={item.id} className="glass p-2 rounded-2xl shrink-0 flex items-center gap-2 border-white/5 bg-white/5 cursor-pointer" onClick={() => setInput(`Add ${item.name}`)}>
                         <img src={item.image} className="w-6 h-6 rounded-lg object-cover" />
