                  {m.text}
                </div>
              </div>
            ))}
            {currentTranscription && (
              <div className="max-w-[80%] px-4 py-3 rounded-3xl text-[11px] font-bold bg-gray-800/80 text-emerald-400 animate-pulse italic border border-emerald-500/20 shadow-xl">
                {currentTranscription}
              </div>
            )}
          </div>

          <div className={`p-5 bg-gray-950 border-t ${isOnline ? 'border-red-600/30' : 'border-amber-500/30'} flex gap-4 shrink-0 shadow-2xl`}>
            <button onClick={toggleMic} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all border-2 ${isMicOn ? 'bg-red-600 border-white text-white animate-pulse shadow-[0_0_25px_rgba(220,38,38,0.7)]' : 'bg-white/5 border-white/10 text-gray-500 hover:text-white hover:bg-white/10'}`}>
              <i className={`fas ${isMicOn ? 'fa-microphone' : 'fa-microphone-slash'} text-xl`}></i>
            </button>
            <div className="flex-1 flex items-center bg-white/5 border border-white/10 rounded-[28px] p-1 px-4 focus-within:border-white/30 transition-all">
              <input 
                type="text" value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSend()}
                placeholder={isOnline ? "কি অর্ডার করবেন স্যার?" : "অফলাইন সহায়তা..."}
                className="flex-1 bg-transparent border-none outline-none text-[12px] font-bold text-white placeholder:opacity-20 py-3"
              />
              <button onClick={() => handleSend()} className={`w-9 h-9 ${isOnline ? 'bg-red-600' : 'bg-amber-500'} text-white rounded-xl flex items-center justify-center active:scale-90 transition-all shadow-lg shadow-black/40`}><i className="fas fa-paper-plane text-xs"></i></button>
            </div>
          </div>
        </div>
      ) : (
        <button onClick={() => { setIsOpen(true); initAudioOutput(); }} className={`w-24 h-24 ${isOnline ? 'bg-red-600' : 'bg-amber-500'} text-white rounded-[35px] shadow-[0_25px_50px_rgba(0,0,0,0.5)] flex flex-col items-center justify-center hover:scale-110 active:scale-95 transition-all border-4 border-white relative overflow-hidden group ${isOnline ? 'pulse-primary' : ''}`}>
