           {(isSpeaking || hasNewUpdate) && (
             <span className="absolute -top-3 -right-3 flex h-10 w-10">
               <span className={`animate-ping absolute inline-flex h-full w-full rounded-full ${hasNewUpdate ? 'bg-red-400' : 'bg-emerald-400'} opacity-75`}></span>
               <span className={`relative inline-flex rounded-full h-10 w-10 ${hasNewUpdate ? 'bg-red-600' : 'bg-emerald-500'} border-4 border-white flex items-center justify-center`}>
                 {hasNewUpdate && <i className="fas fa-exclamation text-white text-[10px]"></i>}
               </span>
             </span>
           )}
        </button>
      )}
    </div>
  );
};

import React, { useState, useMemo, useRef } from 'react';
import { Order, MenuItem, SiteCMS, OrderStatus, LayoutPreset, ThemeConfig } from './types';
import { Button } from './components/Button';

interface AdminPanelProps {
  cms: SiteCMS;
  setCms: (cms: SiteCMS) => void;
  menuItems: MenuItem[];
  setMenuItems: (items: MenuItem[]) => void;
  orders: Order[];
  setOrders: (orders: Order[]) => void;
  onLogout: () => void;
  onItemUpdate?: (item: MenuItem) => void;
}

interface AdminToast {
  id: number;
  message: string;
  type: 'success' | 'warning' | 'danger' | 'info';
  description?: string;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  cms, setCms, menuItems, setMenuItems, orders, setOrders, onLogout, onItemUpdate 
}) => {
  const [tab, setTab] = useState<'DASHBOARD' | 'MENU' | 'ORDERS' | 'LOGISTICS' | 'CMS' | 'LAYOUT'>('DASHBOARD');
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedLayoutForEdit, setSelectedLayoutForEdit] = useState<LayoutPreset>(cms.activeLayout);
  const [toasts, setToasts] = useState<AdminToast[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const totalRevenue = useMemo(() => orders.reduce((acc, curr) => acc + curr.total, 0), [orders]);
  const activeOrdersCount = useMemo(() => orders.filter(o => o.status !== OrderStatus.DELIVERED && o.status !== OrderStatus.CANCELLED).length, [orders]);

  const showToast = (message: string, type: AdminToast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { id, message, type, description }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
  };

  const updateStatus = (orderId: string, status: OrderStatus) => {
    setOrders(orders.map(o => o.id === orderId ? { ...o, status } : o));
    showToast('Mission Status Updated', 'info', `Order ${orderId} is now ${status}.`);
  };

  const handleSaveItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingItem) return;
    let finalItem = editingItem;
    if (editingItem.id === 'NEW') {
        finalItem = { ...editingItem, id: Math.random().toString(36).slice(2, 9) };
        setMenuItems([...menuItems, finalItem]);
    } else {
        setMenuItems(menuItems.map(item => item.id === editingItem.id ? editingItem : item));
    }
    if (onItemUpdate) onItemUpdate(finalItem);
    setEditingItem(null);
    showToast('Registry Synchronized', 'success', `${finalItem.name} has been updated.`);
  };

  const updateThemeVar = (key: keyof ThemeConfig, value: string) => {
    const updatedThemes = { ...cms.themeDefinitions };
    updatedThemes[selectedLayoutForEdit] = {
      ...updatedThemes[selectedLayoutForEdit],
      [key]: value
    };
    setCms({ ...cms, themeDefinitions: updatedThemes });
  };

  const handleExportPalette = () => {
    const data = JSON.stringify(cms.themeDefinitions, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `bfc-palette-manifest-${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
    showToast('Palette Exported', 'success', 'Visual manifest saved to local storage.');
  };

  const handleImportPalette = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const importedThemes = JSON.parse(event.target?.result as string);
        if (typeof importedThemes === 'object' && importedThemes !== null) {
          setCms({ ...cms, themeDefinitions: { ...cms.themeDefinitions, ...importedThemes } });
          showToast('Palette Injected', 'success', 'New visual protocols established.');
        }
      } catch (err) {
        showToast('Neural Error', 'danger', 'Failed to parse visual manifest.');
      }
    };
    reader.readAsText(file);
    e.target.value = ''; 
  };

  const navItems = [
    { id: 'DASHBOARD', icon: 'fa-chart-pie', label: 'Intelligence' },
    { id: 'ORDERS', icon: 'fa-satellite-dish', label: 'Mission Logs' },
    { id: 'MENU', icon: 'fa-utensils', label: 'Unit Registry' },
    { id: 'LAYOUT', icon: 'fa-palette', label: 'Visual Palette' },
    { id: 'LOGISTICS', icon: 'fa-truck-fast', label: 'Logistics' },
    { id: 'CMS', icon: 'fa-microchip', label: 'CMS Engine' },
  ] as const;

  const currentEditTheme = cms.themeDefinitions[selectedLayoutForEdit] || cms.themeDefinitions['ELITE_DARK'];

  return (
    <div className={`flex h-screen bg-[#020617] text-white selection:bg-red-600/30 overflow-hidden font-['Plus_Jakarta_Sans'] theme-${cms.activeLayout}`}>
      {/* Admin Toasts */}
      <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[10000] space-y-3 w-full max-w-md px-4 pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto bg-gray-900/95 backdrop-blur-xl border border-white/10 p-5 rounded-[28px] shadow-2xl animate-elite-up flex items-center gap-4">
            <div className={`w-10 h-10 rounded-2xl flex items-center justify-center ${t.type === 'danger' ? 'bg-red-600' : 'bg-red-600'}`}>
              <i className="fas fa-bolt text-xs text-white"></i>
            </div>
            <div>
              <p className="text-[10px] font-black uppercase tracking-widest text-white leading-none">{t.message}</p>
              {t.description && <p className="text-[8px] opacity-50 mt-1 uppercase">{t.description}</p>}
            </div>
          </div>
        ))}
      </div>

      {/* Sidebar Mobile Overlay */}
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-md z-[6000] lg:hidden" onClick={() => setIsSidebarOpen(false)} />
      )}

      {/* Sidebar Terminal */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[7000] w-72 glass border-r border-white/10 flex flex-col gap-10 p-8 transition-transform duration-700 ease-[cubic-bezier(0.19,1,0.22,1)] ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="flex items-center gap-5">
           <div className="w-12 h-12 bg-red-600 rounded-2xl flex items-center justify-center font-black text-xl shadow-2xl">B</div>
           <div>
             <h1 className="text-xl font-black italic uppercase tracking-tighter leading-none">Elite Hub</h1>
             <p className="text-[9px] font-black uppercase text-red-600 tracking-[4px] mt-1">Terminal</p>
           </div>
        </div>

        <nav className="flex-1 space-y-2 overflow-y-auto no-scrollbar">
          {navItems.map(item => (
            <button 
              key={item.id} 
              onClick={() => { setTab(item.id); setEditingItem(null); setIsSidebarOpen(false); }} 
              className={`w-full flex items-center gap-5 p-5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${tab === item.id ? 'bg-red-600 text-white shadow-2xl scale-105' : 'text-white/40 hover:text-white hover:bg-white/5'}`}
            >
              <i className={`fas ${item.icon} w-5 text-center text-sm`}></i>
              {item.label}
            </button>
          ))}
        </nav>

        <div className="pt-8 border-t border-white/10 space-y-6">
          <div className="flex items-center gap-5 px-2">
            <div className="w-12 h-12 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center text-sm">
              <i className="fas fa-user-shield"></i>
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-[11px] font-black uppercase truncate">Commander Admin</p>
              <p className="text-[9px] font-black text-emerald-500 uppercase tracking-[5px] mt-1">Authorized</p>
            </div>
          </div>
          <Button variant="danger" className="w-full rounded-2xl py-5 !tracking-[3px]" onClick={onLogout}>
            <i className="fas fa-power-off mr-2"></i> LOG OUT
          </Button>
        </div>
      </aside>

      {/* Operations Panel */}
      <main className="flex-1 overflow-y-auto custom-scrollbar relative flex flex-col bg-black/20">
        <header className="lg:hidden p-6 flex justify-between items-center border-b border-white/10 glass sticky top-0 z-[5000]">
          <button onClick={() => setIsSidebarOpen(true)} className="w-12 h-12 glass rounded-2xl flex items-center justify-center"><i className="fas fa-bars text-xl"></i></button>
          <h2 className="text-[12px] font-black uppercase tracking-[8px]">{tab}</h2>
          <div className="w-11 h-11 rounded-2xl bg-red-600 flex items-center justify-center font-black">B</div>
        </header>

        <div className="p-6 lg:p-12 xl:p-20 flex-1 space-y-16 max-w-[1600px] mx-auto w-full">
          {tab === 'DASHBOARD' && (
            <div className="space-y-16 animate-elite-up">
              <header className="space-y-4">
                <h2 className="text-6xl lg:text-9xl font-black italic uppercase tracking-tighter leading-none text-glow">Intelligence</h2>
                <p className="text-[12px] font-black text-red-600 uppercase tracking-[12px]">Mainframe Analytics</p>
              </header>

              <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-8">
                <StatCard label="Total Credits" value={`৳${totalRevenue.toLocaleString()}`} icon="fa-taka-sign" trend="+15%" />
                <StatCard label="Live Missions" value={activeOrdersCount.toString()} icon="fa-rocket" color="text-amber-500" />
                <StatCard label="Unit Manifest" value={menuItems.length.toString()} icon="fa-boxes-stacked" color="text-blue-500" />
                <StatCard label="Uptime Core" value="100%" icon="fa-heart-pulse" color="text-emerald-500" />
              </div>

              <div className="grid grid-cols-1 xl:grid-cols-2 gap-10">
                <div className="glass p-10 rounded-[55px] border-white/5 space-y-8 shadow-3xl">
                  <h3 className="text-2xl font-black italic uppercase tracking-widest flex items-center gap-4">
                    <i className="fas fa-tower-broadcast text-red-600 text-lg"></i>
                    Signal Feed
                  </h3>
                  <div className="space-y-5">
                    {orders.slice(0, 5).map(o => (
                      <div key={o.id} className="flex items-center gap-6 p-6 rounded-[35px] bg-white/5 border border-white/5 hover:bg-white/10 transition-all group cursor-pointer shadow-lg">
                        <div className="w-14 h-14 rounded-2xl bg-red-600/10 text-red-600 flex items-center justify-center text-xl group-hover:rotate-12 transition-transform">
                          <i className="fas fa-file-invoice-dollar"></i>
                        </div>
                        <div className="flex-1">
                          <p className="text-sm font-black uppercase tracking-tight">{o.customerName}</p>
                          <p className="text-[10px] opacity-40 uppercase tracking-widest mt-1">Manifest #{o.id} • {new Date(o.createdAt).toLocaleTimeString()}</p>
                        </div>
                        <div className="text-right">
                          <p className="text-lg font-black italic themed-text-primary leading-none">৳{o.total}</p>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
                <div className="glass p-10 rounded-[55px] border-white/5 space-y-8 shadow-3xl">
                  <h3 className="text-2xl font-black italic uppercase tracking-widest flex items-center gap-4">
                    <i className="fas fa-bolt-lightning text-red-600 text-lg"></i>
                    Registry Hotspots
                  </h3>
                  <div className="space-y-6">
                    {menuItems.slice(0, 4).map(item => (
                      <div key={item.id} className="flex items-center gap-6">
                        <img src={item.image} className="w-16 h-16 rounded-3xl object-cover border border-white/10 shadow-lg" alt="" />
                        <div className="flex-1 space-y-3">
                          <p className="text-sm font-black uppercase italic tracking-tight">{item.name}</p>
                          <div className="w-full bg-white/5 h-2.5 rounded-full overflow-hidden shadow-inner">
                            <div className="bg-red-600 h-full rounded-full shadow-[0_0_15px_rgba(220,38,38,0.5)]" style={{ width: `${Math.random() * 50 + 50}%` }}></div>
                          </div>
                        </div>
                        <span className="text-[11px] font-black text-white/40 uppercase tracking-widest">৳{item.price}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          )}

          {tab === 'LAYOUT' && (
            <div className="space-y-16 animate-elite-up">
              <header className="flex flex-col md:flex-row justify-between items-start md:items-end gap-10">
                <div className="space-y-4">
                  <h2 className="text-6xl lg:text-9xl font-black italic uppercase tracking-tighter leading-none text-glow">Palette Engine</h2>
                  <p className="text-[12px] font-black text-red-600 uppercase tracking-[12px]">Visual Architecture Core</p>
                </div>
                <div className="flex gap-4">
                  <Button variant="outline" className="rounded-[30px] !border-white/10" onClick={handleExportPalette}>
                    <i className="fas fa-file-export mr-3"></i> EXPORT PALETTE
                  </Button>
                  <Button variant="outline" className="rounded-[30px] !border-white/10" onClick={() => fileInputRef.current?.click()}>
                    <i className="fas fa-file-import mr-3"></i> IMPORT PALETTE
                  </Button>
                  <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={handleImportPalette} />
                </div>
              </header>

              <div className="glass p-10 lg:p-14 rounded-[65px] border-white/5 space-y-14 shadow-4xl">
                <div className="space-y-6">
                  <label className="text-[11px] font-black uppercase tracking-[5px] opacity-40 ml-5">Active Target Matrix</label>
                  <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-5 xl:grid-cols-6 gap-4">
                    {Object.keys(cms.themeDefinitions).map((layout) => (
                      <button 
                        key={layout}
                        onClick={() => setSelectedLayoutForEdit(layout as LayoutPreset)}
                        className={`p-5 rounded-3xl border-2 text-[9px] font-black uppercase tracking-widest transition-all ${selectedLayoutForEdit === layout ? 'border-red-600 bg-red-600/10 shadow-2xl scale-105' : 'border-white/5 bg-white/5 opacity-40 hover:opacity-100 hover:scale-105'}`}
