                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10 pt-8">
                  <ColorInput label="Primary Action" value={currentEditTheme.primary} onChange={(v) => updateThemeVar('primary', v)} />
                  <ColorInput label="Accent Overload" value={currentEditTheme.accent} onChange={(v) => updateThemeVar('accent', v)} />
                  <ColorInput label="Base Terminal" value={currentEditTheme.bg} onChange={(v) => updateThemeVar('bg', v)} />
                  <ColorInput label="Data Color" value={currentEditTheme.fg} onChange={(v) => updateThemeVar('fg', v)} />
                  <ColorInput label="Module Surface" value={currentEditTheme.card} onChange={(v) => updateThemeVar('card', v)} />
                  <ColorInput label="Signal Border" value={currentEditTheme.border} onChange={(v) => updateThemeVar('border', v)} />

                  <div className="space-y-4">
                    <label className="text-[11px] font-black uppercase tracking-[5px] opacity-40 ml-5">Typography Font</label>
                    <select 
                      value={currentEditTheme.font} 
                      onChange={(e) => updateThemeVar('font', e.target.value)}
                      className="w-full glass border border-white/10 p-6 rounded-[35px] font-bold text-sm outline-none focus:border-red-600 transition-all bg-black/60 text-white cursor-pointer shadow-lg"
                    >
                      <option value="Plus Jakarta Sans">Plus Jakarta Sans</option>
                      <option value="Hind Siliguri">Hind Siliguri</option>
                      <option value="JetBrains Mono">JetBrains Mono</option>
                      <option value="Playfair Display">Playfair Display</option>
                    </select>
                  </div>
                  <div className="md:col-span-2">
                    <InputGroup label="Elevation Shadow (CSS)" value={currentEditTheme.shadow} onChange={(v) => updateThemeVar('shadow', v)} placeholder="rgba(0,0,0,0.5)" />
                  </div>
                </div>

                <div className="pt-12 border-t border-white/10 flex flex-col md:flex-row justify-between items-center gap-10">
                   <div className="flex gap-5 items-center glass p-6 rounded-[40px] shadow-2xl">
                      <div className="w-14 h-14 rounded-[22px] border-4 border-white/10 shadow-2xl" style={{ backgroundColor: currentEditTheme.primary }}></div>
                      <div className="w-14 h-14 rounded-[22px] border-4 border-white/10 shadow-2xl" style={{ backgroundColor: currentEditTheme.accent }}></div>
                      <div className="w-14 h-14 rounded-[22px] border-4 border-white/10 shadow-2xl" style={{ backgroundColor: currentEditTheme.bg }}></div>
                      <div className="ml-5">
                         <p className="text-[10px] font-black uppercase tracking-[6px] opacity-40 leading-none">Preview</p>
