                      </div>
                   </div>
                   <Button size="lg" className="rounded-[40px] !px-20 shadow-4xl py-10" onClick={() => window.location.reload()}>SYNC NEURAL DATA</Button>
                </div>
              </div>
            </div>
          )}

          {tab === 'MENU' && (
