                      </div>
                   </div>
                   <InputGroup label="Core Platform Label" value={cms.navigation.brand} onChange={v => setCms({...cms, navigation: {...cms.navigation, brand: v}})} placeholder="BFC Hub" />
                   <InputGroup label="Hero Visual Brief" value={cms.hero.title} onChange={v => setCms({...cms, hero: {...cms.hero, title: v}})} placeholder="Mission Objective" />
                   <div className="md:col-span-2">
                     <InputGroup label="Mission Narrative Description" value={cms.hero.description} onChange={v => setCms({...cms, hero: {...cms.hero, description: v}})} placeholder="Describe the deployment goal..." />
