             { id: 'MENU', icon: 'fa-utensils', label: 'Menu' },
             { id: 'BFC_ASSIST', icon: 'fa-robot', label: 'Assist' },
             { id: 'CART', icon: 'fa-shopping-bag', label: 'Bag' },
             { id: 'VAULT', icon: 'fa-shield-halved', label: 'Vault' }
           ].map(item => (
             <button 
               key={item.id} 
               onClick={() => {
                 if (item.id === 'BFC_ASSIST') setIsChatOpen(true);
                 else setView(item.id as any);
               }} 
               className={`flex flex-col items-center gap-2.5 w-full transition-all duration-500 ${(view === item.id || (item.id === 'BFC_ASSIST' && isChatOpen)) ? 'themed-text-primary scale-110' : 'text-gray-500 opacity-40'}`}
             >
                <i className={`fas ${item.icon} text-2xl`}></i>
                <span className="text-[9px] font-black uppercase tracking-[4px]">{item.label}</span>
             </button>
           ))}
        </nav>
      )}

      <ChatBot 
        isOnline={!isOffline} 
        currentUser={currentUser} 
        menuItems={menuItems} 
        setCart={setCart} 
        setView={setView} 
        lastUpdate={lastUpdate}
        isOpen={isChatOpen}
        setIsOpen={setIsChatOpen}
      />

      {/* Global Toast Notification System */}
      <div className="fixed top-28 right-6 z-[10000] space-y-4 max-w-sm w-full pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto bg-gray-950/90 backdrop-blur-2xl p-6 rounded-[35px] animate-elite-up border-l-4 border-red-600 shadow-4xl ring-1 ring-white/10">
            <div className="flex items-center gap-5">
               <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-white shadow-lg ${t.type === 'error' ? 'bg-red-600' : t.type === 'warning' ? 'bg-amber-600' : 'bg-emerald-600'}`}>
                  <i className={`fas ${t.type === 'error' ? 'fa-bolt' : t.type === 'warning' ? 'fa-exclamation' : 'fa-check'}`}></i>
               </div>
               <div>
                  <p className="text-[11px] font-black uppercase tracking-widest text-white leading-none">{t.message}</p>
                  {t.description && <p className="text-[10px] opacity-40 mt-1.5 leading-relaxed text-gray-300 font-medium">{t.description}</p>}
               </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { decodeAudio, decodeAudioData, encodeAudio, getAiInstance, bfcFastText } from '../services/geminiService';
import { ChatMessage, User, MenuItem, CartItem } from '../types';
import { LiveServerMessage, Modality } from '@google/genai';

interface ChatBotProps {
  isOnline?: boolean;
  currentUser?: User | null;
  setView?: (view: any) => void;
  setCart?: React.Dispatch<React.SetStateAction<CartItem[]>>;
  menuItems: MenuItem[];
  lastUpdate?: MenuItem | null;
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
}

const OFFLINE_BRAIN = [
  { keywords: ['menu', 'food', 'খাবার', 'মেনু'], response: "স্যার, বর্তমানে আমাদের কাছে কাচ্চি, রোস্ট, পোলাও এবং কাবাব আছে। মেনু সেকশনে বিস্তারিত দেখতে পাবেন।" },
  { keywords: ['price', 'দাম', 'কত'], response: "খাবারের দাম ৪ ১৫০ টাকা থেকে শুরু। বিরিয়ানি ৪৫০ এবং কাবাব ১৫০ টাকা।" },
  { keywords: ['order', 'অর্ডার', 'কিনব'], response: "আপনি 'SECURE TO BAG' বাটনে ক্লিক করে খাবার কার্টে যোগ করতে পারেন, তারপর চেকআউট করুন।" },
  { keywords: ['status', 'অবস্থা', 'কোথায়'], response: "দুঃখিত স্যার, অফলাইনে লাইভ ট্র্যাকিং সম্ভব নয়। ইন্টারনেট সংযোগ ফিরে এলে আপডেট পাবেন।" },
  { keywords: ['help', 'সাহায্য', 'সহায়তা'], response: "আমি আপনাকে মেনু এবং সাধারণ তথ্যে সাহায্য করতে পারি। অফলাইনে আমার ক্ষমতা সীমিত।" },
];

export const ChatBot: React.FC<ChatBotProps> = ({ isOnline = true, currentUser, setView, setCart, menuItems, lastUpdate, isOpen, setIsOpen }) => {
  const [hasNewUpdate, setHasNewUpdate] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([{ 
    role: 'model', 
    text: "আসসালামু আলাইকুম, আমি বিএফসি থেকে বলছি। কিভাবে আপনাকে সাহায্য করতে পারি?", 
    timestamp: new Date() 
  }]);
  const [input, setInput] = useState('');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isMicOn, setIsMicOn] = useState(false);
  const [currentTranscription, setCurrentTranscription] = useState('');
  const [showTooltip, setShowTooltip] = useState(false);
  const [recentlyViewed, setRecentlyViewed] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('bfc_recent');
    return saved ? JSON.parse(saved) : [];
  });

  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const compressorNodeRef = useRef<DynamicsCompressorNode | null>(null);
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const scrollRef = useRef<HTMLDivElement>(null);
  const micStreamRef = useRef<MediaStream | null>(null);
  const transcriptionRef = useRef('');
  const recognitionRef = useRef<any>(null);

  const stopAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setIsSpeaking(false);
    if (window.speechSynthesis.speaking) {
      window.speechSynthesis.cancel();
    }
  };

  const initAudioOutput = async () => {
    if (!outputAudioContextRef.current) {
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      outputAudioContextRef.current = ctx;
      const compressor = ctx.createDynamicsCompressor();
      const makeupGain = ctx.createGain();
      makeupGain.gain.setValueAtTime(4.0, ctx.currentTime);
      compressor.connect(makeupGain);
      makeupGain.connect(ctx.destination);
      compressorNodeRef.current = compressor;
    }
    if (outputAudioContextRef.current.state === 'suspended') {
      await outputAudioContextRef.current.resume();
    }
  };

  const speakOffline = (text: string) => {
    if (!('speechSynthesis' in window)) return;
    stopAudio();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'bn-BD';
    utterance.rate = 1.0;
    utterance.pitch = 1.0;
    utterance.onstart = () => setIsSpeaking(true);
    utterance.onend = () => setIsSpeaking(false);
    window.speechSynthesis.speak(utterance);
  };

  // Tooltip effect to attract attention
  useEffect(() => {
    const timer = setTimeout(() => setShowTooltip(true), 5000);
    return () => clearTimeout(timer);
  }, []);

  // React to lastUpdate prop from AdminPanel
  useEffect(() => {
    if (lastUpdate) {
      setHasNewUpdate(true);
      const updateMsg = `ব্রেকিং নিউজ! আমাদের মেনুতে ${lastUpdate.nameBn} যুক্ত হয়েছে/আপডেট হয়েছে। আপনি কি এটি ট্রাই করতে চান?`;
      setMessages(prev => [...prev, { role: 'model', text: updateMsg, timestamp: new Date() }]);

      if (!isOpen) {
        setIsOpen(true);
      }

      if (!isOnline) {
        speakOffline(updateMsg);
      } else {
        if (sessionPromiseRef.current) {
          sessionPromiseRef.current.then(s => s.sendRealtimeInput({
            message: { parts: [{ text: `System Alert: A menu item was just updated or added: ${lastUpdate.name}. Please inform the user proactively and cheerfully.` }] }
          }));
        }
      }
    }
  }, [lastUpdate, isOnline, isOpen, setIsOpen]);

  const getOfflineResponse = (query: string): string => {
    const actionResp = processOfflineActions(query);
    if (actionResp) return actionResp;

    const q = query.toLowerCase();
    const match = OFFLINE_BRAIN.find(entry => entry.keywords.some(k => q.includes(k)));
    return match ? match.response : "দুঃখিত স্যার, ইন্টারনেট সংযোগ নেই। আমি শুধু মেনু এবং কার্টে খাবার যোগ করতে সাহায্য করতে পারছি।";
  };

  const processOfflineActions = (query: string): string | null => {
    const q = query.toLowerCase();
    const cartKeywords = ['add', 'order', 'bag', 'অর্ডার', 'দাও', 'কিনব', 'যোগ'];
    if (cartKeywords.some(k => q.includes(k))) {
      const targetItem = menuItems.find(item => q.includes(item.name.toLowerCase()) || q.includes(item.nameBn));
      if (targetItem && setCart) {
        setCart(prev => {
          const ex = prev.find(c => c.item.id === targetItem.id);
          if (ex) return prev.map(x => x.item.id === targetItem.id ? { ...x, qty: x.qty + 1 } : x);
          return [...prev, { item: targetItem, qty: 1 }];
        });
        return `জি স্যার, আমি ${targetItem.nameBn} আপনার কার্টে যোগ করে দিয়েছি। আর কিছু লাগবে?`;
      }
    }
    if (q.includes('menu') || q.includes('মেনু')) {
      if (setView) setView('MENU');
      return "জি স্যার, আমাদের মেনু সেকশন খুলে দিয়েছি।";
    }
    return null;
  };

  const connectLive = useCallback(async () => {
    if (!isOnline || sessionPromiseRef.current) return;
    await initAudioOutput();
    const ai = getAiInstance();
    const currentMenuString = menuItems.map(i => `${i.name} (৳${i.price})`).join(", ");
    const updateHint = lastUpdate ? `Note: ${lastUpdate.name} was just recently added or updated.` : '';

    try {
      sessionPromiseRef.current = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            sessionPromiseRef.current?.then(s => s.sendRealtimeInput({
              message: { parts: [{ text: `Greeting: 'আসসালামু আলাইকুম'। আপনি বিএফসি থেকে বলছেন। ${updateHint} নতুন কোনো মেনু আপডেট থাকলে সেটি উল্লেখ করুন।` }] }
            }));
          },
          onmessage: async (msg: LiveServerMessage) => {
            const audioData = msg.serverContent?.modelTurn?.parts?.find(p => p.inlineData)?.inlineData?.data;
            if (audioData && outputAudioContextRef.current && compressorNodeRef.current) {
              setIsSpeaking(true);
              const ctx = outputAudioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decodeAudio(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(compressorNodeRef.current!);
              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              };
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }
            if (msg.serverContent?.outputTranscription) {
              transcriptionRef.current += msg.serverContent.outputTranscription.text;
              setCurrentTranscription(transcriptionRef.current);
            }
            if (msg.serverContent?.turnComplete) {
              const fullText = transcriptionRef.current || "জি স্যার, আমি শুনছি।";
              setMessages(prev => [...prev, { role: 'model', text: fullText, timestamp: new Date() }]);
              transcriptionRef.current = '';
              setCurrentTranscription('');
            }
            if (msg.serverContent?.interrupted) stopAudio();
          },
          onerror: (e) => { sessionPromiseRef.current = null; },
          onclose: () => { sessionPromiseRef.current = null; }
        },
        config: {
          responseModalities: [Modality.AUDIO], 
          outputAudioTranscription: {},
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
          systemInstruction: `আপনি বিএফসি (Bangla Food Club) এর একজন অত্যন্ত বিনয়ী সহকারী। কাস্টমারকে সবসময় 'জি স্যার/ম্যাম' বলে সম্বোধন করবেন। বর্তমান মেনু: ${currentMenuString}.`
        }
      });
    } catch (e) { sessionPromiseRef.current = null; }
  }, [isOnline, menuItems, lastUpdate]);

  const handleSend = async (textOverride?: string) => {
    const text = textOverride || input.trim();
    if (!text) return;
    stopAudio();
    setMessages(prev => [...prev, { role: 'user', text, timestamp: new Date() }]);
    setInput('');

    if (!isOnline) {
      const response = getOfflineResponse(text);
      setMessages(prev => [...prev, { role: 'model', text: response, timestamp: new Date() }]);
      speakOffline(response);
      return;
    }

    await initAudioOutput();
    if (sessionPromiseRef.current) {
      sessionPromiseRef.current.then(s => s.sendRealtimeInput({ message: { parts: [{ text }] } }));
    } else {
      const resp = await bfcFastText(text, menuItems, currentUser?.name);
      setMessages(prev => [...prev, { role: 'model', text: resp, timestamp: new Date() }]);
    }
  };

  const toggleMic = async () => {
    await initAudioOutput();
    if (isMicOn) {
      if (isOnline && micStreamRef.current) micStreamRef.current.getTracks().forEach(t => t.stop());
      else if (recognitionRef.current) recognitionRef.current.stop();
      setIsMicOn(false);
      return;
    }

    if (!isOnline) {
      const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      if (!SpeechRecognition) return;
      const recognition = new SpeechRecognition();
      recognition.lang = 'bn-BD';
      recognition.onstart = () => setIsMicOn(true);
      recognition.onresult = (event: any) => handleSend(event.results[0][0].transcript);
      recognition.onend = () => setIsMicOn(false);
      recognitionRef.current = recognition;
      recognition.start();
      return;
    }

    try {
      if (!sessionPromiseRef.current) await connectLive();
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;
      setIsMicOn(true);
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const source = ctx.createMediaStreamSource(stream);
      const processor = ctx.createScriptProcessor(2048, 1, 1);
      processor.onaudioprocess = (e) => {
        const inputData = e.inputBuffer.getChannelData(0);
        const int16 = new Int16Array(inputData.length);
        for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
        sessionPromiseRef.current?.then(s => s.sendRealtimeInput({
          media: { data: encodeAudio(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' }
        }));
      };
      source.connect(processor);
      processor.connect(ctx.destination);
    } catch (e) { setIsMicOn(false); }
  };

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'auto' });
  }, [messages, currentTranscription]);

  useEffect(() => {
    if (isOpen && isOnline) {
      connectLive();
      setHasNewUpdate(false);
      setShowTooltip(false);
    }
  }, [isOpen, connectLive, isOnline]);

  return (
    <div className="fixed bottom-32 right-4 lg:bottom-10 lg:right-10 z-[10000]">
      {isOpen ? (
        <div className={`bg-gray-900/98 backdrop-blur-3xl w-[85vw] sm:w-[380px] h-[600px] max-h-[80vh] rounded-[40px] shadow-[0_40px_100px_rgba(0,0,0,0.8)] flex flex-col border-4 ${isOnline ? 'border-red-600' : 'border-amber-500'} overflow-hidden animate-scale-in origin-bottom-right`}>
          <div className={`${isOnline ? 'bg-red-600' : 'bg-amber-500'} p-6 text-white flex justify-between items-center shrink-0 shadow-lg relative z-10`}>
            <div className="flex items-center gap-4">
               <div className={`w-12 h-12 rounded-2xl flex items-center justify-center bg-white ${isOnline ? 'text-red-600' : 'text-amber-500'} ${isSpeaking ? 'animate-pulse shadow-[0_0_20px_white]' : ''}`}>
                  <i className={`fas ${isSpeaking ? 'fa-volume-up' : 'fa-headset'} text-lg`}></i>
               </div>
               <div className="flex flex-col">
                  <span className="text-[12px] font-black uppercase tracking-widest leading-none">BFC Official Assist</span>
                  <div className="flex items-center gap-2 mt-1">
                    <span className={`w-2 h-2 rounded-full ${isOnline ? 'bg-emerald-400 animate-pulse' : 'bg-gray-400'}`}></span>
                    <span className="text-[9px] font-black uppercase opacity-70 tracking-widest">{isOnline ? 'Neural Core Online' : 'Local Archive Only'}</span>
                  </div>
               </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center active:scale-90 transition-all hover:bg-white/20"><i className="fas fa-times text-sm"></i></button>
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 no-scrollbar bg-black/40 relative">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] px-5 py-3.5 rounded-[26px] text-[13px] font-bold ${m.role === 'user' ? 'themed-primary text-white shadow-lg' : 'bg-gray-800 text-gray-100 shadow-xl border border-white/5'}`}>
                  {m.text}
                </div>
              </div>
            ))}
            {currentTranscription && (
              <div className="max-w-[80%] px-5 py-3.5 rounded-3xl text-[12px] font-bold bg-gray-800/80 text-emerald-400 animate-pulse italic border border-emerald-500/20 shadow-xl">
                {currentTranscription}
              </div>
            )}
          </div>

          <div className={`p-6 bg-gray-950 border-t ${isOnline ? 'border-red-600/30' : 'border-amber-500/30'} flex gap-4 shrink-0 shadow-2xl`}>
            <button onClick={toggleMic} className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all border-2 ${isMicOn ? 'bg-red-600 border-white text-white animate-pulse shadow-[0_0_25px_rgba(220,38,38,0.7)]' : 'bg-white/5 border-white/10 text-gray-500 hover:text-white hover:bg-white/10'}`}>
              <i className={`fas ${isMicOn ? 'fa-microphone' : 'fa-microphone-slash'} text-2xl`}></i>
            </button>
            <div className="flex-1 flex items-center bg-white/5 border border-white/10 rounded-[30px] p-1 px-5 focus-within:border-white/30 transition-all">
              <input 
                type="text" value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSend()}
                placeholder={isOnline ? "কি অর্ডার করবেন স্যার?" : "অফলাইন সহায়তা..."}
                className="flex-1 bg-transparent border-none outline-none text-[13px] font-bold text-white placeholder:opacity-20 py-4"
              />
              <button onClick={() => handleSend()} className={`w-10 h-10 ${isOnline ? 'bg-red-600' : 'bg-amber-500'} text-white rounded-xl flex items-center justify-center active:scale-90 transition-all shadow-lg hover:brightness-110`}><i className="fas fa-paper-plane text-xs"></i></button>
            </div>
          </div>
        </div>
      ) : (
        <div className="relative group">
          {/* Proactive Tooltip */}
          {showTooltip && (
            <div className="absolute bottom-full right-0 mb-6 w-48 bg-white text-black p-4 rounded-3xl text-[10px] font-black uppercase tracking-widest shadow-2xl animate-bounce-slow">
              <div className="relative">
                 {hasNewUpdate ? "New Manifest Entry!" : "Need help ordering?"}
                 <div className="absolute top-full right-6 w-4 h-4 bg-white rotate-45 -translate-y-2"></div>
              </div>
            </div>
          )}

          <button onClick={() => { setIsOpen(true); initAudioOutput(); }} className={`w-24 lg:w-28 h-24 lg:h-28 ${isOnline ? 'bg-red-600' : 'bg-amber-500'} text-white rounded-[40px] shadow-[0_30px_60px_rgba(0,0,0,0.6)] flex flex-col items-center justify-center hover:scale-110 active:scale-95 transition-all border-4 border-white relative overflow-hidden group pulse-primary`}>
             <i className="fas fa-robot text-4xl lg:text-5xl mb-1 group-hover:rotate-12 transition-transform"></i>
             <span className="text-[9px] font-black uppercase tracking-[4px] leading-none">ASSIST</span>
             {(isSpeaking || hasNewUpdate) && (
               <span className="absolute top-2 right-2 flex h-4 w-4">
                 <span className={`animate-ping absolute inline-flex h-full w-full rounded-full ${hasNewUpdate ? 'bg-red-400' : 'bg-emerald-400'} opacity-75`}></span>
                 <span className={`relative inline-flex rounded-full h-4 w-4 ${hasNewUpdate ? 'bg-red-600' : 'bg-emerald-500'}`}></span>
               </span>
             )}
             <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
          </button>
        </div>
      )}
    </div>
  );
};

export enum UserRole {
  ADMIN = 'ADMIN',
  MANAGER = 'MANAGER',
  STAFF = 'STAFF',
  CUSTOMER = 'CUSTOMER'
}

export enum OrderStatus {
  PENDING = 'PENDING',
  PREPARING = 'PREPARING',
  READY = 'READY',
  ON_THE_WAY = 'ON_THE_WAY',
  DELIVERED = 'DELIVERED',
  CANCELLED = 'CANCELLED'
}

export type LayoutPreset = 
  | 'ELITE_DARK' 
  | 'CLASSIC_RED' 
  | 'BFC_CLASSIC'
  | 'CYBER_NEON' 
  | 'MINIMAL_WHITE' 
  | 'NATURE_GREEN' 
  | 'LUXURY_GOLD' 
  | 'RETRO_VIBE' 
  | 'BOLD_MONO' 
  | 'PASTEL_SOFT' 
  | 'HIGH_TECH';

export interface ThemeConfig {
  bg: string;
  fg: string;
  primary: string;
  accent: string;
  card: string;
  border: string;
  font: string;
  shadow: string;
}

export interface Promotion {
  id: string;
  name: string;
  code: string;
  discountType: 'PERCENTAGE' | 'FIXED';
  discountValue: number;
  startDate: string;
  endDate: string;
  usageLimit: number;
  usageCount: number;
  isActive: boolean;
}

export interface SiteCMS {
  activeLayout: LayoutPreset;
  themeDefinitions: Record<LayoutPreset, ThemeConfig>;
  deliveryCharge: number;
  hero: {
    title: string;
    subtitle: string;
    description: string;
    image: string;
    cta: string;
  };
  navigation: {
    brand: string;
    links: { [key: string]: string };
  };
  vault: {
    title: string;
    description: string;
  };
}

export interface MenuItem {
  id: string;
  name: string;
  nameBn: string;
  description: string;
  price: number;
  category: string;
  image: string;
  stock: number;
  rating?: number;
  ingredients?: string[];
  dietary?: string[];
  prepTime?: string;
  isPopular?: boolean;
}

export interface CartItem {
  item: MenuItem;
  qty: number;
}

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  customerPhone: string;
  customerEmail: string;
  address: string;
  items: CartItem[];
  subtotal: number;
  deliveryCharge: number;
  discount: number;
  total: number;
  status: OrderStatus;
  createdAt: string;
  paymentMethod: string;
  paymentDetails?: any;
}

export interface User {
  id: string;
  name: string;
  username: string;
  hasCustomizedUsername: boolean;
  email: string;
  password?: string;
  authProvider: 'EMAIL' | 'GOOGLE';
  phone?: string;
  address?: string;
  favoriteCategory?: string;
  role: UserRole;
  loyaltyPoints: number;
  tier: string;
  claimedVouchers?: string[];
  avatar?: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { MenuItem, UserRole, User, Order, CartItem, SiteCMS, OrderStatus, Promotion } from './types';
import { MOCK_MENU, MOCK_ORDERS, DEFAULT_THEMES } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';
import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';

interface Toast {
  id: number;
  message: string;
  description?: string;
  type: 'success' | 'error' | 'warning' | 'info';
}

const DEFAULT_CMS: SiteCMS = {
  activeLayout: 'ELITE_DARK',
  themeDefinitions: DEFAULT_THEMES,
  deliveryCharge: 50,
  hero: {
    title: "Experience Elite Bangladeshi Cuisine",
    subtitle: "The Real Taste Of Bangla",
    description: "Indulge in the finest culinary heritage of Bangladesh. Where tradition meets high-tech precision in every bite.",
    image: "https://images.unsplash.com/photo-1633945274405-b6c8069047b0?q=80&w=2000",
    cta: "ACCESS REGISTRY"
  },
  navigation: {
    brand: "BFC ELITE",
    links: { home: "HOME", menu: "MENU", vault: "VAULT", profile: "PROFILE" }
  },
  vault: {
    title: "ELITE VAULT",
    description: "Manage your credits and unlock secret menu deployments."
  }
};

const App: React.FC = () => {
  const [cms, setCms] = useState<SiteCMS>(() => {
    const saved = localStorage.getItem('bfc_cms');
    return saved ? JSON.parse(saved) : DEFAULT_CMS;
  });
  const [menuItems, setMenuItems] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('bfc_menu');
    return saved ? JSON.parse(saved) : MOCK_MENU;
  });
  const [allOrders, setAllOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('bfc_orders');
    return saved ? JSON.parse(saved) : MOCK_ORDERS;
  });
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });
  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('bfc_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT' | 'CHECKOUT' | 'RECEIPT'>('HOME');
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [lastOrder, setLastOrder] = useState<Order | null>(null);
  const [lastUpdate, setLastUpdate] = useState<MenuItem | null>(null);

  // Auth States
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPassword, setLoginPassword] = useState('');
  const [regData, setRegData] = useState({
    name: '',
    username: '',
    email: '',
    password: '',
    phone: '',
    address: '',
    city: 'Dhaka',
    postalCode: '',
    favCategory: 'Biryani',
    dietary: 'None'
  });

  const [isAuthenticating, setIsAuthenticating] = useState(false);

  const receiptRef = useRef<HTMLDivElement>(null);

  const showToast = useCallback((message: string, type: Toast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, description }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
  }, []);

  useEffect(() => {
    const handleOnline = () => { setIsOffline(false); showToast('Link Restored', 'success', 'Neural core synchronized.'); };
    const handleOffline = () => { setIsOffline(true); showToast('Link Severed', 'error', 'Working in offline mode.'); };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [showToast]);

  useEffect(() => { localStorage.setItem('bfc_cms', JSON.stringify(cms)); }, [cms]);
  useEffect(() => { localStorage.setItem('bfc_menu', JSON.stringify(menuItems)); }, [menuItems]);
  useEffect(() => { localStorage.setItem('bfc_orders', JSON.stringify(allOrders)); }, [allOrders]);
  useEffect(() => { localStorage.setItem('bfc_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { localStorage.setItem('bfc_user', JSON.stringify(currentUser)); }, [currentUser]);

  const handleGoogleLogin = async () => {
    setIsAuthenticating(true);
    showToast('Connecting Google', 'info', 'Establishing secure OAuth link...');

    // Simulate Google Login delay
    await new Promise(r => setTimeout(r, 1500));

    const googleUser: User = {
      id: 'G-' + Math.random().toString(36).slice(2, 7),
      name: 'Google User',
      username: 'google_elite_' + Math.random().toString(36).slice(2, 6),
      hasCustomizedUsername: false,
      email: 'user@gmail.com',
      authProvider: 'GOOGLE',
      role: UserRole.CUSTOMER,
      loyaltyPoints: 500,
      tier: 'SILVER',
      avatar: 'https://ui-avatars.com/api/?name=Google+User&background=4285F4&color=fff'
    };

    setCurrentUser(googleUser);
    setView('HOME');
    setIsAuthenticating(false);
    showToast('Access Granted', 'success', `Welcome, ${googleUser.name}`);
  };

  const handleEmailLogin = async () => {
    if (!loginEmail || !loginPassword) return showToast('Error', 'error', 'Please enter email and password.');
    setIsAuthenticating(true);

    await new Promise(r => setTimeout(r, 1000));

    const isAdmin = loginEmail.toLowerCase().includes('admin');
    const u: User = {
      id: 'U-' + Math.random().toString(36).slice(2, 7),
      name: isAdmin ? 'Admin Commander' : 'Elite Member',
      username: isAdmin ? 'admin' : 'user_' + Math.random().toString(36).slice(2, 6),
      hasCustomizedUsername: false,
      email: loginEmail,
      authProvider: 'EMAIL',
      role: isAdmin ? UserRole.ADMIN : UserRole.CUSTOMER,
      loyaltyPoints: 1250,
      tier: isAdmin ? 'SUPREME' : 'GOLD',
    };

    setCurrentUser(u);
    setIsAuthenticating(false);
    isAdmin ? setView('ADMIN') : setView('HOME');
    showToast('Success', 'success', 'Identity Verified.');
  };

  const handleRegister = async () => {
    if (!regData.email || !regData.password || !regData.name) return showToast('Registry Failed', 'error', 'Required fields are missing.');
    setIsAuthenticating(true);

    await new Promise(r => setTimeout(r, 1200));

    const u: User = {
      id: 'U-' + Math.random().toString(36).slice(2, 7),
      name: regData.name,
      username: regData.username || 'elite_' + Math.random().toString(36).slice(2, 6),
      hasCustomizedUsername: !!regData.username,
      email: regData.email,
      password: regData.password,
      authProvider: 'EMAIL',
      phone: regData.phone,
      address: `${regData.address}, ${regData.city}`,
      favoriteCategory: regData.favCategory,
      role: UserRole.CUSTOMER,
      loyaltyPoints: 500,
      tier: 'SILVER',
    };

    setCurrentUser(u);
    setView('HOME');
    setIsAuthenticating(false);
    showToast('Registry Successful', 'success', 'Your elite account is active.');
  };

  const ViewWrapper: React.FC<{ children: React.ReactNode }> = ({ children }) => (
    <div className="flex-1 flex flex-col animate-elite-up gpu-accel">
      {children}
    </div>
  );

  if (view === 'ADMIN' && currentUser?.role === UserRole.ADMIN) {
    return <AdminPanel 
      cms={cms} 
      setCms={setCms} 
      menuItems={menuItems} 
      setMenuItems={setMenuItems} 
      orders={allOrders} 
      setOrders={setAllOrders} 
      onLogout={() => { setView('HOME'); setCurrentUser(null); }}
      onItemUpdate={setLastUpdate}
    />;
  }

  return (
    <div className={`min-h-screen flex flex-col bg-[#020617] text-white selection:bg-red-600/30 theme-${cms.activeLayout}`}>
      {/* Navbar */}
      <nav className={`fixed top-0 inset-x-0 z-[5000] px-6 lg:px-12 py-6 glass flex justify-between items-center transition-all ${view === 'RECEIPT' || view === 'LOGIN' ? 'hidden' : ''}`}>
        <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-11 h-11 bg-red-600 rounded-2xl flex items-center justify-center font-black shadow-lg group-hover:scale-105 transition-all">B</div>
          <h1 className="text-xl font-black italic uppercase hidden md:block tracking-tighter">{cms.navigation.brand}</h1>
        </div>
        <div className="flex gap-4 items-center">
          <button onClick={() => setIsChatOpen(!isChatOpen)} className={`w-11 h-11 glass rounded-2xl flex items-center justify-center hover:bg-white/5 transition-all ${isChatOpen ? 'themed-text-primary scale-110 shadow-[0_0_20px_rgba(220,38,38,0.5)]' : ''}`} title="BFC Assist">
            <i className="fas fa-robot text-lg"></i>
          </button>
          <button onClick={() => setView('VAULT')} className="w-11 h-11 glass rounded-2xl flex items-center justify-center hover:bg-white/5 transition-all"><i className="fas fa-shield-halved"></i></button>
          <button onClick={() => setView('CART')} className="relative w-11 h-11 glass rounded-2xl flex items-center justify-center hover:scale-105 transition-all">
            <i className="fas fa-shopping-bag"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-[10px] w-6 h-6 rounded-full flex items-center justify-center font-black shadow-lg">{cart.length}</span>}
          </button>
          <button onClick={() => setView('LOGIN')} className="w-11 h-11 bg-red-600 rounded-2xl flex items-center justify-center overflow-hidden border-2 border-white/10 shadow-xl">
            {currentUser ? <img src={currentUser.avatar || `https://ui-avatars.com/api/?name=${currentUser.name}&background=random&color=fff`} className="w-full h-full object-cover" alt="" /> : <i className="fas fa-user"></i>}
          </button>
        </div>
      </nav>

      <main className="flex-1 flex flex-col pt-24 pb-24 lg:pb-0">
        {view === 'HOME' && (
          <ViewWrapper>
            <div className="p-6 lg:p-12 xl:p-20 space-y-20">
              <section className="h-[80vh] rounded-[60px] overflow-hidden relative flex items-center px-8 lg:px-16 border border-white/5 shadow-3xl">
                <img src={cms.hero.image} className="absolute inset-0 w-full h-full object-cover opacity-30 hover:scale-105 transition-all duration-[20s] ease-linear" alt="" />
                <div className="absolute inset-0 bg-gradient-to-r from-black via-black/40 to-transparent"></div>
                <div className="relative z-10 max-w-3xl space-y-8">
                   <div className="inline-block px-6 py-2 glass rounded-full border border-red-600/20">
                      <p className="text-red-500 font-black text-[10px] uppercase tracking-[8px]">{cms.hero.subtitle}</p>
                   </div>
                   <h2 className="text-7xl lg:text-9xl font-black italic uppercase leading-[0.8] tracking-tighter drop-shadow-2xl">{cms.hero.title}</h2>
                   <p className="text-xl lg:text-2xl opacity-60 max-w-xl leading-relaxed font-medium">{cms.hero.description}</p>
                   <div className="flex flex-wrap gap-5 pt-4">
                      <Button size="lg" className="rounded-[35px] !px-16" onClick={() => setView('MENU')}>{cms.hero.cta}</Button>
                      <Button variant="outline" size="lg" className="rounded-[35px] glass text-white !border-white/10 group flex items-center gap-4" onClick={() => setIsChatOpen(true)}>
                        <i className="fas fa-comment-dots group-hover:animate-bounce"></i> ASK BFC ASSIST
                      </Button>
                   </div>
                </div>
              </section>
            </div>
          </ViewWrapper>
        )}

        {view === 'LOGIN' && (
          <ViewWrapper>
            <div className="min-h-[90vh] flex items-center justify-center p-4 lg:p-12 relative overflow-hidden">
               <div className="absolute inset-0 z-0 pointer-events-none overflow-hidden">
                 <div className="absolute top-[-10%] right-[-10%] w-[50%] h-[50%] bg-red-600/10 blur-[150px] rounded-full"></div>
                 <div className="absolute bottom-[-10%] left-[-10%] w-[40%] h-[40%] bg-blue-600/5 blur-[120px] rounded-full"></div>
               </div>

               <div className={`w-full z-10 transition-all duration-700 ${authMode === 'REGISTER' ? 'max-w-5xl' : 'max-w-2xl'}`}>
                  <div className="glass p-8 lg:p-16 rounded-[40px] lg:rounded-[80px] border border-white/10 shadow-[0_60px_150px_rgba(0,0,0,0.7)] backdrop-blur-3xl space-y-10 relative">
                     <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-transparent via-red-600 to-transparent"></div>

                     <div className="text-center space-y-6">
                        <div className="space-y-4">
                           <h3 className="text-5xl lg:text-7xl font-black italic uppercase tracking-tighter leading-none">{authMode === 'LOGIN' ? 'AUTHENTICATE' : 'REGISTRY'}</h3>
