                           <button onClick={() => setAuthMode('LOGIN')} className={`flex-1 py-4 lg:py-5 rounded-[28px] lg:rounded-[38px] text-[10px] lg:text-[11px] font-black uppercase tracking-widest transition-all duration-500 ${authMode === 'LOGIN' ? 'themed-primary text-white shadow-2xl' : 'text-gray-500 opacity-40 hover:opacity-100'}`}>Sign In</button>
                           <button onClick={() => setAuthMode('REGISTER')} className={`flex-1 py-4 lg:py-5 rounded-[28px] lg:rounded-[38px] text-[10px] lg:text-[11px] font-black uppercase tracking-widest transition-all duration-500 ${authMode === 'REGISTER' ? 'themed-primary text-white shadow-2xl' : 'text-gray-500 opacity-40 hover:opacity-100'}`}>Sign Up</button>
                        </div>
                     </div>

                     {authMode === 'LOGIN' ? (
                       <div className="max-w-md mx-auto space-y-8 animate-scale-in">
