                            <div className="space-y-3">
                               <label className="text-[10px] font-black uppercase tracking-[5px] opacity-40 ml-6">Registry Email</label>
                               <input value={loginEmail} onChange={e => setLoginEmail(e.target.value)} placeholder="ELITE@BFC.COM" className="w-full glass bg-white/5 p-7 rounded-[35px] outline-none border border-white/5 font-black text-sm focus:border-red-600/50 transition-all" />
                            </div>
                            <div className="space-y-3">
                               <label className="text-[10px] font-black uppercase tracking-[5px] opacity-40 ml-6">Access Cipher (Password)</label>
                               <input type="password" value={loginPassword} onChange={e => setLoginPassword(e.target.value)} placeholder="••••••••" className="w-full glass bg-white/5 p-7 rounded-[35px] outline-none border border-white/5 font-black text-sm focus:border-red-600/50 transition-all" />
                            </div>
                         </div>

                         <div className="space-y-4">
                            <Button fullWidth size="lg" className="rounded-[40px] py-10 shadow-4xl text-xl tracking-[4px]" onClick={handleEmailLogin} disabled={isAuthenticating}>
                               {isAuthenticating ? 'VALIDATING...' : 'AUTHORIZE LOGIN'}
                            </Button>

                            <div className="flex items-center gap-4 py-2">
                               <div className="flex-1 h-[1px] bg-white/10"></div>
                               <span className="text-[10px] font-black opacity-20 uppercase tracking-[4px]">OR CONTINUE WITH</span>
                               <div className="flex-1 h-[1px] bg-white/10"></div>
                            </div>

                            <button onClick={handleGoogleLogin} disabled={isAuthenticating} className="w-full glass bg-white/5 hover:bg-white/10 p-7 rounded-[40px] flex items-center justify-center gap-4 transition-all border border-white/5 active:scale-95 group shadow-2xl">
                               <svg className="w-6 h-6 group-hover:scale-110 transition-transform" viewBox="0 0 48 48">
                                  <path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z"/>
                                  <path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.13-.45-4.69H24v9.07h12.91c-.54 2.92-2.22 5.39-4.72 7.03l7.38 5.73c4.3-3.96 6.81-9.79 6.81-16.14z"/>
                                  <path fill="#FBBC05" d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z"/>
                                  <path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.38-5.73c-2.06 1.42-4.75 2.29-8.51 2.29-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z"/>
                               </svg>
                               <span className="text-[12px] font-black uppercase tracking-[3px]">Google Elite Sign-In</span>
                            </button>
                         </div>
                       </div>
                     ) : (
                       <div className="animate-scale-in grid grid-cols-1 lg:grid-cols-2 gap-8">
                          <div className="space-y-6">
                            <div className="space-y-4">
                               <label className="text-[10px] font-black uppercase tracking-[5px] opacity-40 ml-6">Display Identity</label>
                               <input value={regData.name} onChange={e => setRegData({...regData, name: e.target.value})} placeholder="FULL NAME" className="w-full glass bg-white/5 p-7 rounded-[35px] border-white/5 font-black uppercase text-xs" />
                            </div>
                            <div className="space-y-4">
                               <label className="text-[10px] font-black uppercase tracking-[5px] opacity-40 ml-6">Communication Link (Phone)</label>
                               <input value={regData.phone} onChange={e => setRegData({...regData, phone: e.target.value})} placeholder="01XXXXXXXXX" className="w-full glass bg-white/5 p-7 rounded-[35px] border-white/5 font-black text-xs" />
                            </div>
                            <div className="space-y-4">
                               <label className="text-[10px] font-black uppercase tracking-[5px] opacity-40 ml-6">Preferred Category</label>
                               <select value={regData.favCategory} onChange={e => setRegData({...regData, favCategory: e.target.value})} className="w-full glass bg-white/5 p-7 rounded-[35px] border-white/5 font-black uppercase text-xs text-white outline-none">
                                  {['Biryani', 'Curry', 'Kebab', 'Desserts'].map(cat => <option key={cat} value={cat} className="bg-[#020617]">{cat}</option>)}
                               </select>
                            </div>
                          </div>

                          <div className="space-y-6">
                            <div className="space-y-4">
                               <label className="text-[10px] font-black uppercase tracking-[5px] opacity-40 ml-6">Registry Email</label>
                               <input value={regData.email} onChange={e => setRegData({...regData, email: e.target.value})} placeholder="ELITE@BFC.COM" className="w-full glass bg-white/5 p-7 rounded-[35px] border-white/5 font-black text-xs" />
                            </div>
                            <div className="space-y-4">
                               <label className="text-[10px] font-black uppercase tracking-[5px] opacity-40 ml-6">New Access Cipher</label>
                               <input type="password" value={regData.password} onChange={e => setRegData({...regData, password: e.target.value})} placeholder="CREATE PASSWORD" className="w-full glass bg-white/5 p-7 rounded-[35px] border-white/5 font-black text-xs" />
                            </div>
                            <div className="space-y-4">
                               <label className="text-[10px] font-black uppercase tracking-[5px] opacity-40 ml-6">Hub Sector (Address)</label>
                               <input value={regData.address} onChange={e => setRegData({...regData, address: e.target.value})} placeholder="HOUSE, ROAD, AREA" className="w-full glass bg-white/5 p-7 rounded-[35px] border-white/5 font-black uppercase text-xs" />
