export const bfcFastText = async (message: string, menuItems: MenuItem[], user?: User | null) => {
  try {
    const ai = getAiInstance();
    const menuContext = menuItems.map(i => 
      `- ${i.name} (${i.nameBn}): ৳${i.price}.`
    ).join("\n");

    const honorific = user?.gender === 'FEMALE' ? 'Madam' : 'Sir';
    const userName = user?.name || 'Guest';

    const systemInstruction = `You are "BFC Assist", the elite professional concierge for Bangla Food Club (BFC).

Identity Core:
1. Always address the user as "${userName} ${honorific}".
2. Language: If the user speaks in Bangla, respond in professional and polite Bangla. If English, use high-class professional English.
3. Speed: Be concise and extremely fast. 
4. Personality: Intelligent, respectful, and helpful.
5. Restrictions: You only have access to information about the current user (${userName}) and the BFC menu. You cannot disclose other users' data.

Current Context:
User Tier: ${user?.tier || 'Guest'}
Current Menu:
${menuContext}

Goal: Help ${userName} ${honorific} place an order or answer questions about our premium Bangladeshi cuisine.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: message,
      config: {
        systemInstruction,
        temperature: 0.3,
      }
    });
    return response.text?.trim() || "আসসালামু আলাইকুম, আমি বিএফসি থেকে বলছি। কিভাবে আপনাকে সাহায্য করতে পারি?";
  } catch (err) {
    return "I apologize, Sir/Madam. My neural link is temporarily interrupted. How may I assist you manually?";
  }
};

export function encodeAudio(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export function decodeAudio(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

