                            className="bg-transparent text-[10px] font-black uppercase text-amber-500 outline-none cursor-pointer"
                          >
                            {Object.values(OrderStatus).map(s => <option key={s} value={s} className="bg-gray-900">{s}</option>)}
                          </select>
                       </div>
                       <div className="text-right">
                          <p className="text-[9px] font-black opacity-30 uppercase tracking-[4px]">Total Mission Value</p>
                          <p className="text-3xl font-black italic themed-text-primary">৳{o.total}</p>
                       </div>
                       <Button variant="outline" className="rounded-xl">Details</Button>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export enum UserRole {
  ADMIN = 'ADMIN',
  MANAGER = 'MANAGER',
  STAFF = 'STAFF',
  CUSTOMER = 'CUSTOMER'
}

export enum OrderStatus {
  PENDING = 'PENDING',
  PREPARING = 'PREPARING',
  READY = 'READY',
  ON_THE_WAY = 'ON_THE_WAY',
  DELIVERED = 'DELIVERED',
  CANCELLED = 'CANCELLED'
}

export type LayoutPreset = 
  | 'ELITE_DARK' 
  | 'CLASSIC_RED' 
  | 'BFC_CLASSIC'
  | 'CYBER_NEON' 
  | 'MINIMAL_WHITE' 
  | 'NATURE_GREEN' 
  | 'LUXURY_GOLD' 
  | 'RETRO_VIBE' 
  | 'BOLD_MONO' 
  | 'PASTEL_SOFT' 
  | 'HIGH_TECH';

export interface ThemeConfig {
  bg: string;
  fg: string;
  primary: string;
  accent: string;
  card: string;
  border: string;
  font: string;
  shadow: string;
}

export interface User {
  id: string;
  name: string;
  username: string;
  bio?: string;
  gender?: 'MALE' | 'FEMALE' | 'OTHER';
  email: string;
  password?: string;
  authProvider: 'EMAIL' | 'GOOGLE';
  phone?: string;
  address?: string;
  favoriteCategory?: string;
  role: UserRole;
  loyaltyPoints: number;
  tier: string;
  avatar?: string;
  createdAt: string;
}

export interface MenuItem {
  id: string;
  name: string;
  nameBn: string;
  description: string;
  price: number;
  category: string;
  image: string;
  stock: number;
  // Added optional fields to resolve "Object literal may only specify known properties" errors in constants.tsx
  rating?: number;
  ingredients?: string[];
  dietary?: string[];
  prepTime?: string;
  isPopular?: boolean;
}

export interface CartItem {
  item: MenuItem;
  qty: number;
}

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  customerPhone: string;
  customerEmail: string;
  address: string;
  items: CartItem[];
  subtotal: number;
  deliveryCharge: number;
  discount: number;
  total: number;
  status: OrderStatus;
  createdAt: string;
  paymentMethod: 'BKASH' | 'NAGAD' | 'CARD' | 'COD';
  paymentStatus: 'PAID' | 'UNPAID';
  transactionId?: string;
}

export interface SiteCMS {
  activeLayout: LayoutPreset;
  themeDefinitions: Record<LayoutPreset, ThemeConfig>;
  deliveryCharge: number;
  hero: {
    title: string;
    subtitle: string;
    description: string;
    image: string;
    cta: string;
  };
  navigation: {
    brand: string;
    links: { [key: string]: string };
  };
  vault: {
    title: string;
    description: string;
  };
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { MenuItem, UserRole, User, Order, CartItem, SiteCMS, OrderStatus } from './types';
import { MOCK_MENU, MOCK_ORDERS, DEFAULT_THEMES } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';
import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';

interface Toast {
  id: number;
  message: string;
  description?: string;
  type: 'success' | 'error' | 'warning' | 'info';
}

const DEFAULT_CMS: SiteCMS = {
  activeLayout: 'ELITE_DARK',
  themeDefinitions: DEFAULT_THEMES,
  deliveryCharge: 50,
  hero: {
    title: "Experience Elite Bangladeshi Cuisine",
    subtitle: "The Real Taste Of Bangla",
    description: "Indulge in the finest culinary heritage of Bangladesh. Where tradition meets high-tech precision in every bite.",
    image: "https://images.unsplash.com/photo-1633945274405-b6c8069047b0?q=80&w=2000",
    cta: "ACCESS REGISTRY"
  },
  navigation: { brand: "BFC ELITE", links: { home: "HOME", menu: "MENU", vault: "VAULT", profile: "PROFILE" } },
  vault: { title: "ELITE VAULT", description: "Manage your credits and unlock secret menu deployments." }
};

const App: React.FC = () => {
  const [cms, setCms] = useState<SiteCMS>(() => {
    const saved = localStorage.getItem('bfc_cms');
    return saved ? JSON.parse(saved) : DEFAULT_CMS;
  });
  const [menuItems, setMenuItems] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('bfc_menu');
    return saved ? JSON.parse(saved) : MOCK_MENU;
  });
  const [allOrders, setAllOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('bfc_orders');
    return saved ? JSON.parse(saved) : MOCK_ORDERS;
  });
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });
  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('bfc_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'PROFILE' | 'CHECKOUT' | 'RECEIPT'>('HOME');
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER' | 'GOOGLE_PICKER'>('LOGIN');
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [lastOrder, setLastOrder] = useState<Order | null>(null);

  // Form States
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPass, setLoginPass] = useState('');
  const [regData, setRegData] = useState({ name: '', email: '', password: '', phone: '', address: '', username: '', gender: 'MALE' as const });
  const [paymentData, setPaymentData] = useState({ method: 'BKASH' as any, trxId: '' });

  const receiptRef = useRef<HTMLDivElement>(null);

  const showToast = useCallback((message: string, type: Toast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, description }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
  }, []);

  useEffect(() => {
    localStorage.setItem('bfc_cms', JSON.stringify(cms));
    localStorage.setItem('bfc_menu', JSON.stringify(menuItems));
    localStorage.setItem('bfc_orders', JSON.stringify(allOrders));
    localStorage.setItem('bfc_cart', JSON.stringify(cart));
    localStorage.setItem('bfc_user', JSON.stringify(currentUser));
  }, [cms, menuItems, allOrders, cart, currentUser]);

  const validateEmail = (email: string) => {
    return String(email)
      .toLowerCase()
      .match(/^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/);
  };

  const handleGoogleSelect = (email: string) => {
    setIsAuthenticating(true);
    setTimeout(() => {
      const u: User = {
        id: 'G-' + Math.random().toString(36).slice(2, 7),
        name: email.split('@')[0],
        username: email.split('@')[0].toLowerCase() + '_' + Math.random().toString(36).slice(2, 5),
        email,
        authProvider: 'GOOGLE',
        role: UserRole.CUSTOMER,
        loyaltyPoints: 500,
        tier: 'GOLD',
        createdAt: new Date().toISOString(),
        avatar: `https://ui-avatars.com/api/?name=${email}&background=4285F4&color=fff`
      };
      setCurrentUser(u);
      setIsAuthenticating(false);
      setView('HOME');
      showToast('Auth Success', 'success', `Welcome back, Sir.`);
    }, 1500);
  };

  const handleEmailLogin = async () => {
    if (!loginEmail) return showToast('Identifier Required', 'warning', 'Please enter your registry email address.');
    if (!validateEmail(loginEmail)) return showToast('Malformed Email', 'error', 'The provided email address is not in a valid format.');
    if (!loginPass) return showToast('Cipher Required', 'warning', 'Authentication requires an access password.');

    setIsAuthenticating(true);
    // Simulate API Auth
    await new Promise(r => setTimeout(r, 1200));

    if (loginPass === 'wrong') {
      setIsAuthenticating(false);
      return showToast('Auth Failed', 'error', 'Invalid cipher. Please check your password and try again.');
    }

    const isAdmin = loginEmail.toLowerCase().includes('admin');
    const u: User = {
      id: 'U-' + Math.random().toString(36).slice(2, 7),
      name: isAdmin ? 'Admin Commander' : 'Elite Member',
      username: isAdmin ? 'admin' : 'user_' + Math.random().toString(36).slice(2, 6),
      hasCustomizedUsername: false,
      email: loginEmail,
      authProvider: 'EMAIL',
      role: isAdmin ? UserRole.ADMIN : UserRole.CUSTOMER,
      loyaltyPoints: 1250,
      tier: isAdmin ? 'SUPREME' : 'GOLD',
      createdAt: new Date().toISOString()
    };

    setCurrentUser(u);
    setIsAuthenticating(false);
    isAdmin ? setView('ADMIN') : setView('HOME');
    showToast('Identify Success', 'success', `Access granted to sector ${isAdmin ? 'Admin' : 'Home'}.`);
  };

  const handleRegister = async () => {
    if (!regData.name) return showToast('Data Missing', 'warning', 'Full name is required for identification.');
    if (!regData.email || !validateEmail(regData.email)) return showToast('Invalid Email', 'error', 'A valid email is needed for communication links.');
    if (!regData.password || regData.password.length < 6) return showToast('Weak Cipher', 'warning', 'Password must be at least 6 characters for security.');
    if (!regData.phone || regData.phone.length < 11) return showToast('Link Error', 'error', 'A valid phone number (11+ digits) is required.');

    setIsAuthenticating(true);
    await new Promise(r => setTimeout(r, 1500));

    const u: User = {
      id: 'U-' + Math.random().toString(36).slice(2, 7),
      name: regData.name,
      username: regData.username || 'elite_' + Math.random().toString(36).slice(2, 6),
      hasCustomizedUsername: !!regData.username,
      email: regData.email,
      password: regData.password,
      authProvider: 'EMAIL',
      phone: regData.phone,
      address: regData.address,
      role: UserRole.CUSTOMER,
      loyaltyPoints: 500,
      tier: 'SILVER',
      gender: regData.gender,
      createdAt: new Date().toISOString(),
      avatar: `https://ui-avatars.com/api/?name=${regData.name}&background=random&color=fff`
    };

    setCurrentUser(u);
    setView('HOME');
    setIsAuthenticating(false);
    showToast('Registry Established', 'success', 'Welcome to the BFC elite tier.');
  };

  const processPayment = async () => {
    if (paymentData.method !== 'COD' && !paymentData.trxId) {
      return showToast('Mission Blocked', 'error', 'Transaction ID is required for verification.');
    }

    setIsAuthenticating(true);
    await new Promise(r => setTimeout(r, 2000));

    // Simulated failure for "fail" trxid
    if (paymentData.trxId?.toLowerCase() === 'fail') {
      setIsAuthenticating(false);
      return showToast('Sync Interrupted', 'error', 'Payment provider rejected the transaction. Please verify details.');
    }

    const subtotal = cart.reduce((a, b) => a + (b.item.price * b.qty), 0);
    const order: Order = {
      id: 'BFC-' + Math.random().toString(36).slice(2, 8).toUpperCase(),
      customerId: currentUser?.id || 'GUEST',
      customerName: currentUser?.name || 'Guest',
      customerEmail: currentUser?.email || 'guest@bfc.com',
      customerPhone: currentUser?.phone || 'N/A',
      address: currentUser?.address || 'Pickup from Store',
      items: [...cart],
      subtotal,
      deliveryCharge: cms.deliveryCharge,
      discount: 0,
      total: subtotal + cms.deliveryCharge,
      status: OrderStatus.PENDING,
      paymentMethod: paymentData.method,
      paymentStatus: paymentData.method === 'COD' ? 'UNPAID' : 'PAID',
      transactionId: paymentData.trxId,
      createdAt: new Date().toISOString()
    };

    setAllOrders(prev => [order, ...prev]);
    setLastOrder(order);
    setCart([]);
    setIsAuthenticating(false);
    setView('RECEIPT');
    showToast('Deployment Confirmed', 'success', 'Order manifest has been synchronized with delivery nodes.');
  };

  const downloadReceipt = async (format: 'PDF' | 'IMAGE') => {
    if (!receiptRef.current) return showToast('Render Error', 'error', 'Receipt canvas not found. Please refresh.');
    try {
      const canvas = await html2canvas(receiptRef.current, { scale: 3 });
      if (format === 'IMAGE') {
        const link = document.createElement('a');
        link.download = `BFC-Receipt-${lastOrder?.id}.png`;
        link.href = canvas.toDataURL();
        link.click();
        showToast('Capture Saved', 'success', 'Image download initiated.');
      } else {
        const pdf = new jsPDF('p', 'mm', 'a4');
        const imgData = canvas.toDataURL('image/png');
        const imgProps = pdf.getImageProperties(imgData);
        const pdfWidth = pdf.internal.pageSize.getWidth();
        const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;
        pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
        pdf.save(`BFC-Receipt-${lastOrder?.id}.pdf`);
        showToast('Document Generated', 'success', 'PDF manifest saved to storage.');
      }
    } catch (e) {
      showToast('Export Failed', 'error', 'Internal error during document generation. Please try again.');
    }
  };

  return (
    <div className={`min-h-screen flex flex-col bg-[#020617] text-white selection:bg-red-600/30 theme-${cms.activeLayout}`}>
      <nav className={`fixed top-0 inset-x-0 z-[5000] px-6 lg:px-12 py-5 glass flex justify-between items-center transition-all ${view === 'LOGIN' ? 'hidden' : ''}`}>
        <div className="flex items-center gap-4 cursor-pointer" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center font-black shadow-lg">B</div>
          <h1 className="text-xl font-black italic uppercase tracking-tighter">{cms.navigation.brand}</h1>
        </div>
        <div className="flex gap-4">
          <button onClick={() => setView('CART')} className="relative w-10 h-10 glass rounded-xl flex items-center justify-center">
            <i className="fas fa-shopping-bag"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-[10px] w-5 h-5 rounded-full flex items-center justify-center font-black">{cart.length}</span>}
          </button>
          <button onClick={() => setView(currentUser ? 'PROFILE' : 'LOGIN')} className="w-10 h-10 glass rounded-xl overflow-hidden border border-white/10">
            {currentUser?.avatar ? <img src={currentUser.avatar} className="w-full h-full object-cover" /> : <i className="fas fa-user"></i>}
          </button>
        </div>
      </nav>

      <main className="flex-1 flex flex-col pt-24">
        {view === 'HOME' && (
          <div className="p-6 lg:p-20 space-y-12 animate-elite-up">
            <section className="h-[60vh] rounded-[45px] overflow-hidden relative flex items-center px-12 border border-white/5">
              <img src={cms.hero.image} className="absolute inset-0 w-full h-full object-cover opacity-30" />
              <div className="relative z-10 max-w-2xl space-y-6">
                 <h2 className="text-6xl lg:text-8xl font-black italic uppercase leading-none">{cms.hero.title}</h2>
                 <p className="text-lg opacity-60">{cms.hero.description}</p>
                 <Button size="lg" onClick={() => setView('MENU')}>{cms.hero.cta}</Button>
              </div>
            </section>
          </div>
        )}

        {view === 'LOGIN' && (
          <div className="min-h-[80vh] flex items-center justify-center p-6 animate-scale-in">
             <div className="w-full max-w-md glass p-10 rounded-[50px] space-y-8 border border-white/10 shadow-4xl relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1.5 bg-red-600"></div>

                {authMode === 'GOOGLE_PICKER' ? (
                  <div className="space-y-6">
                    <h3 className="text-2xl font-black uppercase text-center">Select Account</h3>
                    <div className="space-y-3">
                       {['john.doe@gmail.com', 'shakib.elite@gmail.com', 'commander@gmail.com'].map(email => (
                         <button key={email} onClick={() => handleGoogleSelect(email)} className="w-full glass p-5 rounded-2xl flex items-center gap-4 hover:bg-white/10 transition-all border border-white/5">
                            <div className="w-10 h-10 rounded-full bg-blue-600 flex items-center justify-center font-bold">{email[0].toUpperCase()}</div>
                            <div className="text-left">
                               <p className="text-sm font-bold">{email.split('@')[0]}</p>
                               <p className="text-[10px] opacity-40">{email}</p>
                            </div>
                         </button>
                       ))}
                    </div>
                    <button onClick={() => setAuthMode('LOGIN')} className="w-full text-[10px] font-black uppercase tracking-widest opacity-30 hover:opacity-100 transition-all">Cancel</button>
                  </div>
                ) : (
                  <>
                    <div className="text-center space-y-2">
                       <h3 className="text-4xl font-black italic uppercase">{authMode === 'LOGIN' ? 'Identify' : 'Registry'}</h3>
                       <p className="text-[10px] font-black text-red-600 tracking-[10px] uppercase">BFC Security Core</p>
                    </div>

                    <div className="space-y-4">
                       <input value={loginEmail} onChange={e => setLoginEmail(e.target.value)} placeholder="EMAIL" className="w-full glass bg-white/5 p-6 rounded-3xl border-white/5 font-black text-xs" />
                       <input type="password" value={loginPass} onChange={e => setLoginPass(e.target.value)} placeholder="CIPHER" className="w-full glass bg-white/5 p-6 rounded-3xl border-white/5 font-black text-xs" />
                       <Button fullWidth onClick={handleEmailLogin} disabled={isAuthenticating}>
                          {isAuthenticating ? 'SYNCING...' : 'AUTHORIZE'}
                       </Button>
                    </div>

                    <div className="flex items-center gap-4 py-2">
                       <div className="flex-1 h-[1px] bg-white/10"></div>
                       <span className="text-[8px] font-black opacity-20 uppercase tracking-[4px]">Social OAuth</span>
                       <div className="flex-1 h-[1px] bg-white/10"></div>
                    </div>

                    <button onClick={() => setAuthMode('GOOGLE_PICKER')} className="w-full glass p-5 rounded-[25px] flex items-center justify-center gap-4 hover:bg-white/10 transition-all">
                       <i className="fab fa-google text-blue-500"></i>
                       <span className="text-[10px] font-black uppercase tracking-widest">Login with Google</span>
                    </button>

                    <div className="text-center">
                       <button onClick={() => setAuthMode(authMode === 'LOGIN' ? 'REGISTER' : 'LOGIN')} className="text-[10px] font-black uppercase tracking-widest text-red-600 hover:scale-105 transition-all">
                          {authMode === 'LOGIN' ? 'New Registry Needed?' : 'Already Identified?'}
                       </button>
                    </div>
                  </>
                )}

                {authMode === 'REGISTER' && (
                   <div className="space-y-6 animate-scale-in">
                      <div className="grid grid-cols-1 gap-4">
                        <input value={regData.name} onChange={e => setRegData({...regData, name: e.target.value})} placeholder="FULL NAME" className="w-full glass bg-white/5 p-5 rounded-2xl border-white/5 font-black text-xs" />
                        <input value={regData.email} onChange={e => setRegData({...regData, email: e.target.value})} placeholder="REGISTRY EMAIL" className="w-full glass bg-white/5 p-5 rounded-2xl border-white/5 font-black text-xs" />
                        <input type="password" value={regData.password} onChange={e => setRegData({...regData, password: e.target.value})} placeholder="NEW CIPHER" className="w-full glass bg-white/5 p-5 rounded-2xl border-white/5 font-black text-xs" />
                        <input value={regData.phone} onChange={e => setRegData({...regData, phone: e.target.value})} placeholder="PHONE (01...)" className="w-full glass bg-white/5 p-5 rounded-2xl border-white/5 font-black text-xs" />
                        <select value={regData.gender} onChange={e => setRegData({...regData, gender: e.target.value as any})} className="w-full glass bg-black p-5 rounded-2xl border-white/5 font-black text-xs text-white">
                           <option value="MALE">MALE</option>
                           <option value="FEMALE">FEMALE</option>
                           <option value="OTHER">OTHER</option>
                        </select>
                      </div>
                      <Button fullWidth onClick={handleRegister} disabled={isAuthenticating}>
                        {isAuthenticating ? 'PROCESSING...' : 'COMMIT REGISTRY'}
                      </Button>
                      <button onClick={() => setAuthMode('LOGIN')} className="w-full text-[10px] font-black uppercase tracking-widest opacity-30 hover:opacity-100">Abort Registration</button>
                   </div>
                )}
             </div>
          </div>
        )}

        {view === 'MENU' && (
          <div className="p-6 lg:p-20 space-y-12 animate-elite-up">
             <h2 className="text-7xl font-black italic uppercase text-center leading-none">Manifest</h2>
             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                {menuItems.map(item => (
                  <div key={item.id} className="glass p-6 rounded-[40px] border border-white/5 group hover:border-red-600/30 transition-all">
                    <div className="h-48 rounded-[30px] overflow-hidden mb-6 relative">
                      <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                      <div className="absolute top-4 right-4 bg-red-600 px-4 py-1.5 rounded-full text-xs font-black">৳{item.price}</div>
                    </div>
                    <h4 className="text-2xl font-black italic uppercase leading-none">{item.name}</h4>
                    <p className="text-[10px] opacity-40 mt-2 mb-6 line-clamp-2">{item.description}</p>
                    <Button fullWidth variant="outline" onClick={() => { 
                      setCart(prev => {
                        const ex = prev.find(c => c.item.id === item.id);
                        if (ex) return prev.map(x => x.item.id === item.id ? { ...x, qty: x.qty + 1 } : x);
                        return [...prev, { item, qty: 1 }];
                      });
                      showToast('Logged', 'success', `${item.name} added to mission bag.`);
                    }}>Add to Bag</Button>
                  </div>
                ))}
             </div>
          </div>
        )}

        {view === 'PROFILE' && currentUser && (
          <div className="max-w-4xl mx-auto p-6 lg:p-12 space-y-12 animate-elite-up">
             <div className="glass p-12 rounded-[60px] flex flex-col md:flex-row items-center gap-12 border-white/10">
                <div className="relative group cursor-pointer">
                  <img src={currentUser.avatar} className="w-40 h-40 rounded-[45px] object-cover border-4 border-white/10" />
                  <div className="absolute inset-0 bg-black/60 rounded-[45px] opacity-0 group-hover:opacity-100 flex items-center justify-center transition-all">
                    <i className="fas fa-camera text-2xl"></i>
                  </div>
                </div>
                <div className="flex-1 space-y-4 text-center md:text-left">
                   <div className="flex flex-col md:flex-row md:items-end gap-4">
                      <h2 className="text-6xl font-black italic uppercase leading-none">{currentUser.name}</h2>
                      <span className="text-red-600 font-black text-xs uppercase tracking-widest bg-red-600/10 px-4 py-1 rounded-full">{currentUser.tier} PERSONNEL</span>
                   </div>
                   <p className="text-emerald-500 font-black tracking-widest uppercase">@{currentUser.username}</p>
                   <textarea 
                     value={currentUser.bio || ''} 
                     onChange={e => setCurrentUser({...currentUser, bio: e.target.value})}
                     placeholder="Mission bio..."
