             </div>
             <button onClick={() => setView('HOME')} className="w-full text-[10px] font-black uppercase tracking-[10px] opacity-40 hover:opacity-100 py-4 transition-all">Close Manifest</button>
          </div>
        )}

        {view === 'CART' && (
          <div className="max-w-3xl mx-auto p-6 lg:p-20 space-y-12 animate-elite-up">
             <h2 className="text-6xl font-black italic uppercase leading-none">Secure Bag</h2>
             {cart.length === 0 ? (
               <div className="text-center py-20 space-y-6">
                  <i className="fas fa-shopping-bag text-6xl opacity-10"></i>
                  <p className="opacity-40 font-black uppercase tracking-widest">Bag is currently empty</p>
                  <Button onClick={() => setView('MENU')}>Deploy to Menu</Button>
               </div>
             ) : (
               <div className="space-y-8">
                  <div className="glass p-8 rounded-[40px] space-y-6">
                     {cart.map((item, idx) => (
                       <div key={idx} className="flex items-center gap-6 pb-6 border-b border-white/5 last:border-none">
                          <img src={item.item.image} className="w-20 h-20 rounded-2xl object-cover" />
                          <div className="flex-1">
                             <h4 className="font-black italic text-xl uppercase leading-none">{item.item.name}</h4>
                             <p className="text-[10px] opacity-40 mt-1 uppercase tracking-widest">৳{item.item.price} per unit</p>
                             <div className="flex items-center gap-4 mt-4">
                                <button onClick={() => setCart(prev => prev.map((x, i) => i === idx ? {...x, qty: Math.max(1, x.qty - 1)} : x))} className="w-8 h-8 glass rounded-lg flex items-center justify-center"><i className="fas fa-minus text-[10px]"></i></button>
                                <span className="font-black text-sm">{item.qty}</span>
                                <button onClick={() => setCart(prev => prev.map((x, i) => i === idx ? {...x, qty: x.qty + 1} : x))} className="w-8 h-8 glass rounded-lg flex items-center justify-center"><i className="fas fa-plus text-[10px]"></i></button>
                             </div>
                          </div>
                          <button onClick={() => setCart(prev => prev.filter((_, i) => i !== idx))} className="text-red-600 opacity-40 hover:opacity-100 transition-all"><i className="fas fa-trash"></i></button>
                       </div>
                     ))}
                  </div>
                  <div className="glass p-8 rounded-[40px] space-y-4">
                     <div className="flex justify-between text-xs font-black uppercase opacity-40">
                        <span>Subtotal</span>
                        <span>৳{cart.reduce((a, b) => a + (b.item.price * b.qty), 0)}</span>
                     </div>
                     <div className="flex justify-between text-2xl font-black italic uppercase border-t border-white/10 pt-4">
