                        <span>৳{cart.reduce((a, b) => a + (b.item.price * b.qty), 0) + cms.deliveryCharge}</span>
                     </div>
                     <Button fullWidth size="lg" onClick={() => setView('CHECKOUT')}>Authorize Deployment</Button>
                  </div>
               </div>
             )}
          </div>
        )}
      </main>

      <ChatBot 
        isOnline={true} currentUser={currentUser} menuItems={menuItems} setCart={setCart} setView={setView}
        isOpen={isChatOpen} setIsOpen={setIsChatOpen} 
      />

      <div className="fixed top-24 right-6 z-[10000] space-y-3 max-w-sm pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto glass bg-black/95 p-5 rounded-[30px] border-l-4 border-red-600 animate-elite-up shadow-4xl ring-1 ring-white/10">
