                    </div>
                    <div className="space-y-4">
                       <input value={loginEmail} onChange={e => setLoginEmail(e.target.value)} placeholder="ELITE EMAIL" className="w-full glass bg-white/5 p-6 rounded-3xl border-white/5 font-black text-xs outline-none focus:border-red-600/50 transition-all" />
                       <input type="password" value={loginPass} onChange={e => setLoginPass(e.target.value)} placeholder="ACCESS CIPHER" className="w-full glass bg-white/5 p-6 rounded-3xl border-white/5 font-black text-xs outline-none focus:border-red-600/50 transition-all" />
                       <Button fullWidth onClick={() => {
                          if (loginEmail === 'admin@bfc.com' && loginPass === 'admin') {
                            setCurrentUser({ id: 'ADM', name: 'Commander Admin', email: 'admin@bfc.com', role: UserRole.ADMIN, loyaltyPoints: 99999, tier: 'SUPREME', username: 'commander', authProvider: 'EMAIL', createdAt: '2023-01-01' });
                            setView('ADMIN');
                          } else {
                            handleGoogleSelect(loginEmail || 'user@elite.com');
