                       }} disabled={isAuthenticating}>Authorize Access</Button>
                    </div>
                    <div className="flex items-center gap-4">
                       <div className="flex-1 h-[1px] bg-white/10"></div>
                       <span className="text-[8px] font-black opacity-20 uppercase tracking-[4px]">OAuth Link</span>
