             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                {menuItems.map(item => (
                  <div key={item.id} className="glass p-6 rounded-[45px] border border-white/5 group hover:border-red-600/30 transition-all shadow-xl">
