                    <Button fullWidth variant="outline" className="rounded-2xl py-4" onClick={() => { 
                      setCart(prev => {
                        const ex = prev.find(c => c.item.id === item.id);
                        if (ex) return prev.map(x => x.item.id === item.id ? { ...x, qty: x.qty + 1 } : x);
                        return [...prev, { item, qty: 1 }];
                      });
                      showToast('Logged to Bag', 'success', `${item.name} added.`);
