                             <p className="text-[10px] font-black uppercase opacity-40 tracking-[4px]"><i className="fas fa-wallet mr-3 text-red-600"></i>{o.paymentMethod} • {o.paymentStatus}</p>
                          </div>
                       </div>
                    </div>
                    <div className="flex flex-wrap justify-center xl:flex-1 gap-3 px-10 z-10">
                       {Object.values(OrderStatus).map(s => (
                         <button 
                           key={s} 
                           onClick={() => setOrders(orders.map(x => x.id === o.id ? {...x, status: s} : x))} 
                           className={`px-5 py-3 rounded-2xl text-[9px] font-black uppercase tracking-[3px] border transition-all ${o.status === s ? 'themed-primary border-transparent shadow-4xl scale-110' : 'border-white/5 bg-white/5 opacity-30 hover:opacity-100'}`}
                         >
                           {/* Fix potential "type unknown" error by casting enum value to string */}
                           {(s as string).replace(/_/g, ' ')}
                         </button>
                       ))}
                    </div>
                    <div className="text-center xl:text-right w-full xl:w-auto pt-10 xl:pt-0 border-t xl:border-t-0 border-white/10 z-10">
                       <p className="text-[10px] font-black opacity-30 uppercase tracking-[6px]">Mission Value</p>
                       <p className="text-5xl font-black italic themed-text-primary leading-none tracking-tighter mt-2">৳{o.total}</p>
                       <p className="text-[9px] font-bold opacity-30 uppercase tracking-[4px] mt-4">{new Date(o.createdAt).toLocaleString()}</p>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

const StatBox = ({ label, value, icon, trend }: { label: string, value: string, icon: string, trend?: string }) => (
  <div className="glass p-10 rounded-[50px] flex items-center gap-10 group hover:border-red-600/30 transition-all border border-white/5 shadow-3xl relative overflow-hidden">
    <div className="absolute top-0 right-0 p-8 opacity-5 rotate-12 pointer-events-none group-hover:scale-110 transition-transform"><i className={`fas ${icon} text-[80px]`}></i></div>
    <div className="w-20 h-20 bg-white/5 rounded-[30px] flex items-center justify-center text-4xl shadow-inner group-hover:themed-primary transition-all duration-500"><i className={`fas ${icon}`}></i></div>
    <div className="space-y-2 z-10">
      <div className="flex items-center gap-4">
        <p className="text-[11px] font-black uppercase tracking-[5px] opacity-40">{label}</p>
        {trend && <span className="text-[9px] font-black px-3 py-1 rounded-full bg-emerald-500/20 text-emerald-500">{trend}</span>}
      </div>
      <h4 className="text-5xl font-black italic leading-none tracking-tighter">{value}</h4>
    </div>
  </div>
);

export enum UserRole {
