  | 'ELITE_DARK' 
  | 'CLASSIC_RED' 
  | 'BFC_CLASSIC'
  | 'CYBER_NEON' 
  | 'MINIMAL_WHITE' 
  | 'NATURE_GREEN' 
  | 'LUXURY_GOLD' 
  | 'RETRO_VIBE' 
  | 'BOLD_MONO' 
  | 'PASTEL_SOFT' 
  | 'HIGH_TECH';

export interface ThemeConfig {
  bg: string;
  fg: string;
  primary: string;
  accent: string;
  card: string;
  border: string;
  font: string;
  shadow: string;
}

export interface User {
  id: string;
  name: string;
  username: string;
  hasCustomizedUsername?: boolean;
  bio?: string;
  gender?: 'MALE' | 'FEMALE' | 'OTHER';
