export interface SiteCMS {
  activeLayout: LayoutPreset;
  themeDefinitions: Record<LayoutPreset, ThemeConfig>;
  deliveryCharge: number;
  hero: {
    title: string;
    subtitle: string;
    description: string;
    image: string;
    cta: string;
  };
  navigation: {
    brand: string;
    links: { [key: string]: string };
  };
  vault: {
    title: string;
    description: string;
  };
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { MenuItem, UserRole, User, Order, CartItem, SiteCMS, OrderStatus } from './types';
import { MOCK_MENU, MOCK_ORDERS, DEFAULT_THEMES } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';
import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';

interface Toast {
  id: number;
  message: string;
  description?: string;
  type: 'success' | 'error' | 'warning' | 'info';
}

const DEFAULT_CMS: SiteCMS = {
  activeLayout: 'ELITE_DARK',
  themeDefinitions: DEFAULT_THEMES,
  deliveryCharge: 50,
  hero: {
    title: "Experience Elite Bangladeshi Cuisine",
    subtitle: "The Real Taste Of Bangla",
    description: "Indulge in the finest culinary heritage of Bangladesh. Where tradition meets high-tech precision in every bite.",
    image: "https://images.unsplash.com/photo-1633945274405-b6c8069047b0?q=80&w=2000",
    cta: "ACCESS REGISTRY"
  },
  navigation: { brand: "BFC ELITE", links: { home: "HOME", menu: "MENU", vault: "VAULT", profile: "PROFILE" } },
  vault: { title: "ELITE VAULT", description: "Manage your credits and unlock secret menu deployments." }
};

const App: React.FC = () => {
  const [cms, setCms] = useState<SiteCMS>(() => {
    const saved = localStorage.getItem('bfc_cms');
    return saved ? JSON.parse(saved) : DEFAULT_CMS;
  });
  const [menuItems, setMenuItems] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('bfc_menu');
    return saved ? JSON.parse(saved) : MOCK_MENU;
  });
  const [allOrders, setAllOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('bfc_orders');
    return saved ? JSON.parse(saved) : MOCK_ORDERS;
  });
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });
  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('bfc_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'PROFILE' | 'VAULT' | 'CHECKOUT' | 'RECEIPT'>('HOME');
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER' | 'GOOGLE_PICKER'>('LOGIN');
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [lastOrder, setLastOrder] = useState<Order | null>(null);

  // Form States
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPass, setLoginPass] = useState('');
  const [paymentData, setPaymentData] = useState({ method: 'BKASH' as any, trxId: '' });

  const receiptRef = useRef<HTMLDivElement>(null);

  const showToast = useCallback((message: string, type: Toast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, description }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
  }, []);

  useEffect(() => {
    localStorage.setItem('bfc_cms', JSON.stringify(cms));
    localStorage.setItem('bfc_menu', JSON.stringify(menuItems));
    localStorage.setItem('bfc_orders', JSON.stringify(allOrders));
    localStorage.setItem('bfc_cart', JSON.stringify(cart));
    localStorage.setItem('bfc_user', JSON.stringify(currentUser));
  }, [cms, menuItems, allOrders, cart, currentUser]);

  const handleGoogleSelect = (email: string) => {
    setIsAuthenticating(true);
    setTimeout(() => {
      const u: User = {
        id: 'G-' + Math.random().toString(36).slice(2, 7),
        name: email.split('@')[0].toUpperCase(),
        username: email.split('@')[0].toLowerCase() + '_' + Math.random().toString(36).slice(2, 5),
        email,
        authProvider: 'GOOGLE',
        role: UserRole.CUSTOMER,
        loyaltyPoints: 750,
        tier: 'GOLD',
        createdAt: new Date().toISOString(),
        avatar: `https://ui-avatars.com/api/?name=${email}&background=4285F4&color=fff`
      };
      setCurrentUser(u);
      setIsAuthenticating(false);
      setView('HOME');
      showToast('Welcome, Elite Member', 'success', `Authorized as ${u.name}`);
    }, 1200);
  };

  const handleEmailAuth = () => {
    if (loginEmail === 'admin@bfc.com' && loginPass === 'admin') {
      const admin: User = { 
        id: 'ADM-001', name: 'Commander Admin', email: 'admin@bfc.com', role: UserRole.ADMIN, 
        loyaltyPoints: 9999, tier: 'SUPREME', username: 'commander', authProvider: 'EMAIL', createdAt: '2023-01-01' 
      };
      setCurrentUser(admin);
      setView('ADMIN');
      showToast('Admin Authorized', 'success', 'Welcome back, Commander.');
      return;
    }
    handleGoogleSelect(loginEmail || 'guest@bfc.com');
  };

  const processPayment = async () => {
    if (paymentData.method !== 'COD' && !paymentData.trxId) {
      return showToast('Mission Blocked', 'error', 'Transaction ID is required for verification.');
    }

    setIsAuthenticating(true);
    await new Promise(r => setTimeout(r, 1500));

    if (paymentData.trxId?.toLowerCase() === 'fail') {
      setIsAuthenticating(false);
      return showToast('Transaction Failed', 'error', 'The bank rejected your request. Try again.');
    }

    const subtotal = cart.reduce((a, b) => a + (b.item.price * b.qty), 0);
    const order: Order = {
      id: 'BFC-' + Math.random().toString(36).slice(2, 8).toUpperCase(),
      customerId: currentUser?.id || 'GUEST',
      customerName: currentUser?.name || 'Guest',
      customerEmail: currentUser?.email || 'guest@bfc.com',
      customerPhone: currentUser?.phone || 'N/A',
      address: currentUser?.address || 'Dhaka Base',
      items: [...cart],
      subtotal,
      deliveryCharge: cms.deliveryCharge,
      discount: 0,
      total: subtotal + cms.deliveryCharge,
      status: OrderStatus.PENDING,
      paymentMethod: paymentData.method,
      paymentStatus: paymentData.method === 'COD' ? 'UNPAID' : 'PAID',
      transactionId: paymentData.trxId,
      createdAt: new Date().toISOString()
    };

    setAllOrders(prev => [order, ...prev]);
    setLastOrder(order);
    setCart([]);
    setIsAuthenticating(false);
    setView('RECEIPT');
    showToast('Deployment Confirmed', 'success', 'Order manifest synchronized.');
  };

  const downloadReceipt = async (format: 'PDF' | 'IMAGE') => {
    if (!receiptRef.current) return;
    const canvas = await html2canvas(receiptRef.current, { scale: 3 });
    if (format === 'IMAGE') {
      const link = document.createElement('a');
      link.download = `Receipt-${lastOrder?.id}.png`;
      link.href = canvas.toDataURL();
      link.click();
    } else {
      const pdf = new jsPDF('p', 'mm', 'a4');
      const imgData = canvas.toDataURL('image/png');
      const imgProps = pdf.getImageProperties(imgData);
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;
      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      pdf.save(`Receipt-${lastOrder?.id}.pdf`);
    }
  };

  if (view === 'ADMIN' && currentUser?.role === UserRole.ADMIN) {
    return (
      <AdminPanel 
        cms={cms} setCms={setCms} menuItems={menuItems} setMenuItems={setMenuItems} 
        orders={allOrders} setOrders={setAllOrders} onLogout={() => { setView('HOME'); setCurrentUser(null); }} 
      />
    );
  }

  return (
    <div className={`min-h-screen flex flex-col bg-[#020617] text-white selection:bg-red-600/30 theme-${cms.activeLayout}`}>
      {/* Navbar */}
      <nav className={`fixed top-0 inset-x-0 z-[5000] px-6 lg:px-12 py-5 glass flex justify-between items-center transition-all ${view === 'LOGIN' ? 'hidden' : ''}`}>
        <div className="flex items-center gap-4 cursor-pointer" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center font-black shadow-lg">B</div>
          <h1 className="text-xl font-black italic uppercase tracking-tighter">{cms.navigation.brand}</h1>
        </div>
        <div className="flex gap-4 items-center">
          <button onClick={() => setView('MENU')} className="px-5 py-2 glass rounded-full text-[10px] font-black uppercase tracking-widest hover:bg-white/5 transition-all hidden md:block">Menu</button>
          <button onClick={() => setView('VAULT')} className="w-10 h-10 glass rounded-xl flex items-center justify-center hover:bg-white/5"><i className="fas fa-shield-halved"></i></button>
          <button onClick={() => setView('CART')} className="relative w-10 h-10 glass rounded-xl flex items-center justify-center">
            <i className="fas fa-shopping-bag"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-[10px] w-5 h-5 rounded-full flex items-center justify-center font-black">{cart.length}</span>}
          </button>
          <button onClick={() => setView(currentUser ? 'PROFILE' : 'LOGIN')} className="w-10 h-10 glass rounded-xl overflow-hidden border border-white/10 shadow-xl">
            {currentUser?.avatar ? <img src={currentUser.avatar} className="w-full h-full object-cover" /> : <i className="fas fa-user"></i>}
          </button>
        </div>
      </nav>

      <main className="flex-1 flex flex-col pt-24 pb-28 lg:pb-0">
        {view === 'HOME' && (
          <div className="p-6 lg:p-20 space-y-12 animate-elite-up">
            <section className="h-[60vh] rounded-[45px] overflow-hidden relative flex items-center px-12 border border-white/5">
              <img src={cms.hero.image} className="absolute inset-0 w-full h-full object-cover opacity-30" />
              <div className="relative z-10 max-w-2xl space-y-6">
                 <h2 className="text-6xl lg:text-8xl font-black italic uppercase leading-none">{cms.hero.title}</h2>
                 <p className="text-lg opacity-60 leading-relaxed">{cms.hero.description}</p>
                 <Button size="lg" className="rounded-full" onClick={() => setView('MENU')}>{cms.hero.cta}</Button>
              </div>
            </section>
          </div>
        )}

        {view === 'LOGIN' && (
          <div className="min-h-[85vh] flex items-center justify-center p-6 animate-scale-in">
             <div className="w-full max-w-md glass p-10 rounded-[50px] space-y-10 border border-white/10 shadow-4xl relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1.5 bg-red-600"></div>
                {authMode === 'GOOGLE_PICKER' ? (
                  <div className="space-y-6">
                    <h3 className="text-2xl font-black uppercase text-center">Select Account</h3>
                    <div className="space-y-3">
                       {['shakib.dev@gmail.com', 'tanvir.elite@gmail.com', 'guest.user@gmail.com'].map(email => (
                         <button key={email} onClick={() => handleGoogleSelect(email)} className="w-full glass p-5 rounded-3xl flex items-center gap-4 hover:bg-white/10 transition-all border border-white/5">
                            <div className="w-10 h-10 rounded-full bg-blue-600 flex items-center justify-center font-bold text-white shadow-lg">{email[0].toUpperCase()}</div>
                            <div className="text-left">
                               <p className="text-sm font-bold text-white">{email.split('@')[0]}</p>
                               <p className="text-[10px] opacity-40 text-gray-400">{email}</p>
                            </div>
                         </button>
                       ))}
                    </div>
                    <button onClick={() => setAuthMode('LOGIN')} className="w-full text-[10px] font-black uppercase opacity-30 hover:opacity-100 transition-all py-4">Cancel</button>
                  </div>
                ) : (
                  <>
                    <div className="text-center space-y-3">
                       <h3 className="text-4xl font-black italic uppercase">Identify</h3>
                       <p className="text-[10px] font-black text-red-600 tracking-[10px] uppercase">BFC Security Core</p>
                    </div>
                    <div className="space-y-4">
                       <input value={loginEmail} onChange={e => setLoginEmail(e.target.value)} placeholder="EMAIL" className="w-full glass bg-white/5 p-6 rounded-3xl border-white/5 font-black text-xs outline-none" />
                       <input type="password" value={loginPass} onChange={e => setLoginPass(e.target.value)} placeholder="CIPHER" className="w-full glass bg-white/5 p-6 rounded-3xl border-white/5 font-black text-xs outline-none" />
                       <Button fullWidth onClick={handleEmailAuth} disabled={isAuthenticating}>Authorize</Button>
                    </div>
                    <button onClick={() => setAuthMode('GOOGLE_PICKER')} className="w-full glass p-5 rounded-[25px] flex items-center justify-center gap-4 hover:bg-white/10 transition-all border border-white/5">
                       <i className="fab fa-google text-blue-500"></i>
                       <span className="text-[10px] font-black uppercase tracking-widest">Sign in with Google</span>
                    </button>
                    <button onClick={() => setView('HOME')} className="w-full text-[9px] font-black opacity-30 uppercase tracking-[10px] py-2">Return Home</button>
                  </>
                )}
             </div>
          </div>
        )}

        {view === 'MENU' && (
          <div className="p-6 lg:p-20 space-y-16 animate-elite-up">
             <div className="text-center space-y-4">
               <h2 className="text-6xl lg:text-9xl font-black italic uppercase leading-none tracking-tighter">Manifest</h2>
               <p className="text-[12px] font-black text-red-600 uppercase tracking-[12px]">Deployment Catalog</p>
             </div>
             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                {menuItems.map(item => (
                  <div key={item.id} className="glass p-6 rounded-[45px] border border-white/5 group hover:border-red-600/30 transition-all shadow-xl">
                    <div className="h-52 rounded-[35px] overflow-hidden mb-6 relative">
                      <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-[2s]" />
                      <div className="absolute top-4 right-4 bg-red-600 px-5 py-2 rounded-full text-xs font-black shadow-lg">৳{item.price}</div>
                    </div>
                    <h4 className="text-2xl font-black italic uppercase leading-none tracking-tight">{item.name}</h4>
                    <p className="text-[10px] opacity-40 mt-3 mb-6 line-clamp-2 leading-relaxed">{item.description}</p>
                    <Button fullWidth variant="outline" className="rounded-2xl py-4" onClick={() => { 
                      setCart(prev => {
                        const ex = prev.find(c => c.item.id === item.id);
                        if (ex) return prev.map(x => x.item.id === item.id ? { ...x, qty: x.qty + 1 } : x);
                        return [...prev, { item, qty: 1 }];
                      });
                      showToast('Logged to Bag', 'success', `${item.name} added.`);
                    }}>Add to Mission</Button>
                  </div>
                ))}
             </div>
          </div>
        )}

        {view === 'VAULT' && currentUser && (
          <div className="max-w-4xl mx-auto p-6 lg:p-12 space-y-12 animate-elite-up">
             <div className="text-center space-y-4">
                <h2 className="text-6xl lg:text-9xl font-black italic uppercase tracking-tighter">Vault</h2>
                <p className="text-[12px] font-black text-red-600 uppercase tracking-[12px]">Financial Surveillance</p>
             </div>
             <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                <div className="glass p-10 rounded-[45px] text-center border-white/10 md:col-span-2 shadow-4xl flex flex-col justify-center min-h-[300px]">
                   <p className="text-[10px] font-black opacity-30 uppercase tracking-[10px] mb-6">Total Registry Assets</p>
                   <p className="text-8xl font-black italic themed-text-primary">৳{(currentUser.loyaltyPoints * 0.5).toFixed(0)}</p>
                   <p className="text-xs font-black uppercase tracking-widest opacity-40 mt-4">Equivalent to BFC Credits</p>
                </div>
                <div className="glass p-10 rounded-[45px] flex flex-col justify-between border-white/10 shadow-3xl">
                   <div className="w-16 h-16 rounded-2xl bg-emerald-500/10 text-emerald-500 flex items-center justify-center text-2xl shadow-inner"><i className="fas fa-bolt"></i></div>
                   <div>
                      <h4 className="text-2xl font-black italic uppercase leading-none">Supreme Tier</h4>
                      <p className="text-[10px] opacity-40 uppercase tracking-widest mt-2">Level 4 Clearance</p>
                   </div>
                   <Button variant="outline" className="rounded-2xl py-3 text-[9px]">Upgrade Link</Button>
                </div>
             </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="max-w-3xl mx-auto p-6 lg:p-20 space-y-12 animate-elite-up">
             <h2 className="text-6xl font-black italic uppercase leading-none tracking-tighter">Secure Bag</h2>
             {cart.length === 0 ? (
               <div className="text-center py-20 space-y-8 glass rounded-[60px] border-white/5">
                  <i className="fas fa-shopping-bag text-8xl opacity-10 floating"></i>
                  <p className="opacity-40 font-black uppercase tracking-[12px]">Bag is Empty</p>
                  <Button onClick={() => setView('MENU')} className="rounded-full">Deploy to Manifest</Button>
               </div>
             ) : (
               <div className="space-y-8">
                  <div className="glass p-8 rounded-[45px] space-y-6 border-white/5 shadow-2xl">
                     {cart.map((item, idx) => (
                       <div key={idx} className="flex items-center gap-6 pb-6 border-b border-white/5 last:border-none">
                          <img src={item.item.image} className="w-24 h-24 rounded-[30px] object-cover shadow-xl" />
                          <div className="flex-1">
                             <h4 className="font-black italic text-xl uppercase leading-none">{item.item.name}</h4>
                             <p className="text-[10px] opacity-40 mt-1.5 tracking-widest">৳{item.item.price} UNIT VALUE</p>
                             <div className="flex items-center gap-4 mt-5">
