    const saved = localStorage.getItem('bfc_orders');
    return saved ? JSON.parse(saved) : MOCK_ORDERS;
  });
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });
  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('bfc_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'PROFILE' | 'VAULT' | 'CHECKOUT' | 'RECEIPT'>('HOME');
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER' | 'GOOGLE_PICKER'>('LOGIN');
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [lastOrder, setLastOrder] = useState<Order | null>(null);

  // Form States
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPass, setLoginPass] = useState('');
  const [paymentData, setPaymentData] = useState({ method: 'BKASH' as any, trxId: '' });

  const receiptRef = useRef<HTMLDivElement>(null);

  const showToast = useCallback((message: string, type: Toast['type'] = 'success', description?: string) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, description }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
  }, []);

  useEffect(() => {
    localStorage.setItem('bfc_cms', JSON.stringify(cms));
    localStorage.setItem('bfc_menu', JSON.stringify(menuItems));
    localStorage.setItem('bfc_orders', JSON.stringify(allOrders));
    localStorage.setItem('bfc_cart', JSON.stringify(cart));
    localStorage.setItem('bfc_user', JSON.stringify(currentUser));
  }, [cms, menuItems, allOrders, cart, currentUser]);

  const handleGoogleSelect = (email: string) => {
    setIsAuthenticating(true);
