    const order: Order = {
      id: 'BFC-' + Math.random().toString(36).slice(2, 8).toUpperCase(),
      customerId: currentUser?.id || 'GUEST',
      customerName: currentUser?.name || 'Guest',
      customerEmail: currentUser?.email || 'guest@bfc.com',
      customerPhone: currentUser?.phone || 'N/A',
      address: currentUser?.address || 'Dhaka, Bangladesh',
