      subtotal,
      deliveryCharge: cms.deliveryCharge,
      discount: 0,
      total: subtotal + cms.deliveryCharge,
      status: OrderStatus.PENDING,
      paymentMethod: paymentData.method,
      paymentStatus: paymentData.method === 'COD' ? 'UNPAID' : 'PAID',
