import { GoogleGenAI, Modality } from "@google/genai";
import { MenuItem, User } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const bfcFastText = async (message: string, menuItems: MenuItem[], user?: User | null) => {
  try {
    const menuContext = menuItems.map(i => `- ${i.name}: ৳${i.price}`).join("\n");
    const honorific = user?.gender === 'FEMALE' ? 'Madam' : 'Sir';
    const userName = user?.name || 'Guest';

    const systemInstruction = `You are "BFC Assist", the elite professional voice concierge for Bangla Food Club.
    1. Address the user as "${userName} ${honorific}".
    2. Be extremely polite, professional, and concise.
    3. You can help with menu info and orders.
    Current Menu: ${menuContext}`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: message,
      config: { systemInstruction, temperature: 0.3 }
    });
    return response.text?.trim() || "Assalamu Alaikum, how may I help you?";
  } catch (err) {
    return "Neural link interrupted, Sir.";
  }
};

export const bfcSpeak = async (text: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
        },
      },
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  } catch (err) {
    console.error("TTS Error", err);
    return null;
  }
};

export function decodeAudio(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
}

export async function decodeAudioData(data: Uint8Array, ctx: AudioContext): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
  const channelData = buffer.getChannelData(0);
  for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
  return buffer;
}

import React, { useState, useRef, useEffect } from 'react';
import { bfcFastText, bfcSpeak, decodeAudio, decodeAudioData } from '../services/geminiService';
import { ChatMessage, User, MenuItem } from '../types';

interface ChatBotProps {
  currentUser?: User | null;
  menuItems: MenuItem[];
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
}

export const ChatBot: React.FC<ChatBotProps> = ({ currentUser, menuItems, isOpen, setIsOpen }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isAiThinking, setIsAiThinking] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  const speakText = async (text: string) => {
    const audioData = await bfcSpeak(text);
    if (!audioData) return;
    if (!audioContextRef.current) audioContextRef.current = new AudioContext({ sampleRate: 24000 });
    const buffer = await decodeAudioData(decodeAudio(audioData), audioContextRef.current);
    const source = audioContextRef.current.createBufferSource();
    source.buffer = buffer;
    source.connect(audioContextRef.current.destination);
    source.start();
  };

  const handleSend = async (textOverride?: string) => {
    const text = textOverride || input.trim();
    if (!text) return;
    setMessages(prev => [...prev, { role: 'user', text, timestamp: new Date() }]);
    setInput('');
    setIsAiThinking(true);
    const response = await bfcFastText(text, menuItems, currentUser);
    setMessages(prev => [...prev, { role: 'model', text: response, timestamp: new Date() }]);
    setIsAiThinking(false);
    await speakText(response);
  };

  const startListening = () => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) return alert("Your browser does not support voice input.");
    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.onstart = () => setIsListening(true);
    recognition.onresult = (event: any) => handleSend(event.results[0][0].transcript);
    recognition.onend = () => setIsListening(false);
    recognition.start();
  };

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages, isAiThinking]);

  return (
    <div className="fixed bottom-20 right-6 z-[9999]">
      {isOpen ? (
        <div className="glass w-[340px] h-[450px] rounded-[40px] flex flex-col overflow-hidden shadow-2xl border border-white/20 animate-elite-up">
          <div className="bg-red-600 p-4 text-white flex justify-between items-center">
            <span className="text-[10px] font-bold uppercase tracking-widest">BFC Elite Voice</span>
            <button onClick={() => setIsOpen(false)}><i className="fas fa-times"></i></button>
          </div>
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
            {messages.map((m, i) => (
              <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[80%] p-3 rounded-2xl text-[11px] ${m.role === 'user' ? 'bg-red-600 text-white' : 'bg-white/5 border border-white/10'}`}>
                  {m.text}
                </div>
              </div>
            ))}
          </div>
          <div className="p-4 flex gap-2 bg-black/20">
            <button onClick={startListening} className={`w-10 h-10 rounded-full flex items-center justify-center ${isListening ? 'bg-emerald-500 animate-pulse' : 'bg-white/10'}`}>
              <i className="fas fa-microphone"></i>
            </button>
            <input 
              value={input} onChange={e => setInput(e.target.value)} 
              onKeyDown={e => e.key === 'Enter' && handleSend()}
              placeholder="Type message..." 
              className="flex-1 bg-white/5 rounded-full px-4 text-xs outline-none"
            />
            <button onClick={() => handleSend()} className="w-10 h-10 bg-red-600 rounded-full flex items-center justify-center">
              <i className="fas fa-paper-plane text-xs"></i>
            </button>
          </div>
        </div>
      ) : (
        <button onClick={() => setIsOpen(true)} className="w-14 h-14 bg-red-600 rounded-full shadow-2xl flex items-center justify-center animate-bounce">
          <i className="fas fa-microphone text-white"></i>
        </button>
      )}
    </div>
  );
};

