interface ChatBotProps {
  currentUser?: User | null;
  menuItems: MenuItem[];
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
}

export const ChatBot: React.FC<ChatBotProps> = ({ currentUser, menuItems, isOpen, setIsOpen }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isAiThinking, setIsAiThinking] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Initialize Audio Context on first interaction
  const initAudio = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
  };

  const speakText = async (text: string) => {
    initAudio();
    const audioData = await bfcSpeak(text);
    if (!audioData || !audioContextRef.current) return;

    if (audioContextRef.current.state === 'suspended') {
      await audioContextRef.current.resume();
    }

    const buffer = await decodeAudioData(decodeAudio(audioData), audioContextRef.current);
    const source = audioContextRef.current.createBufferSource();
    source.buffer = buffer;
    source.connect(audioContextRef.current.destination);
    source.start();
  };

  const handleSend = async (textOverride?: string) => {
    const text = textOverride || input.trim();
    if (!text) return;

    initAudio();
    setMessages(prev => [...prev, { role: 'user', text, timestamp: new Date() }]);
    setInput('');
    setIsAiThinking(true);

    const response = await bfcFastText(text, menuItems, currentUser);

    setMessages(prev => [...prev, { role: 'model', text: response, timestamp: new Date() }]);
    setIsAiThinking(false);
    await speakText(response);
  };

  const startListening = () => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) return alert("Security Notice: Your browser environment does not support voice input.");

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.onstart = () => setIsListening(true);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      handleSend(transcript);
    };
    recognition.onend = () => setIsListening(false);
    recognition.onerror = () => setIsListening(false);
    recognition.start();
  };

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, isAiThinking]);

