            {isAiThinking && (
              <div className="flex justify-start">
                 <div className="bg-white/5 border border-white/10 p-5 rounded-[30px] flex gap-3 shadow-xl">
                    <span className="w-2 h-2 rounded-full bg-red-600 animate-bounce"></span>
                    <span className="w-2 h-2 rounded-full bg-red-600 animate-bounce delay-75"></span>
                    <span className="w-2 h-2 rounded-full bg-red-600 animate-bounce delay-150"></span>
