import { GoogleGenAI, Modality } from "@google/genai";
import { MenuItem, User, MenuUpdate } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const bfcFastText = async (message: string, menuItems: MenuItem[], user?: User | null, updates: MenuUpdate[] = []) => {
  try {
    const menuContext = menuItems.map(i => `- ${i.name}: ৳${i.price} (${i.stock > 0 ? 'In Stock' : 'Out of Stock'})`).join("\n");
    const updatesContext = updates.length > 0 
      ? updates.map(u => `[UPDATE ${u.type}] ${u.itemName}: ${u.details}`).join("\n")
      : "No recent updates.";

    const honorific = user?.gender === 'FEMALE' ? 'Madam' : 'Sir';
    const userName = user?.name || 'Guest';

    const systemInstruction = `You are the "BFC Elite Concierge". 
    1. ALWAYS respond with "Assalamu Alaikum" if the user greets you or starts a conversation.
    2. Address the user as "${userName} ${honorific}".
    3. Use extremely professional, high-class, and respectful language.
    4. NEVER remain silent. Always acknowledge the user's intent clearly.
    5. If there are RECENT MENU UPDATES, mention them gracefully in your first response of the session if appropriate, or when discussing the menu.

    RECENT MENU UPDATES:
    ${updatesContext}

    ELITE MENU:
    ${menuContext}

    6. Maintain a 5-star hospitality tone at all times. Be helpful and concise.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: message,
      config: { systemInstruction, temperature: 0.1 }
    });
    return response.text?.trim() || "Assalamu Alaikum Sir, I am at your service.";
  } catch (err) {
    return "My apologies Sir, the neural link is fluctuating. Assalamu Alaikum.";
  }
};

export const bfcSpeak = async (text: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
        },
      },
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  } catch (err) {
    console.error("Audio Output Error:", err);
    return null;
  }
};

export function decodeAudio(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
}

export async function decodeAudioData(data: Uint8Array, ctx: AudioContext): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
  const channelData = buffer.getChannelData(0);
  for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
  return buffer;
}

