import { GoogleGenAI, Modality } from "@google/genai";
import { MenuItem, User, MenuUpdate } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const bfcFastText = async (message: string, menuItems: MenuItem[], user?: User | null, updates: MenuUpdate[] = []) => {
  try {
    const menuContext = menuItems.map(i => `- ${i.name}: ৳${i.price}`).join("\n");
    const updatesContext = updates.length > 0 
      ? updates.map(u => `[NEWS] ${u.itemName}: ${u.details}`).join("\n")
      : "";

    const honorific = user?.gender === 'FEMALE' ? 'Madam' : 'Sir';
    const userName = user?.name || 'Guest';

    const systemInstruction = `You are the "BFC Elite Concierge". 
    ULTIMATE POWER MODE:
    1. BILINGUAL: Respond in the language the user speaks (Bangla or English).
    2. EXTREME CONCISENESS: Your responses MUST be extremely short. Maximum 10-15 words. 
    3. ETIQUETTE: Always start with "Assalamu Alaikum" and address the user as "${honorific}".
    4. UPDATES: If there are menu updates, mention only the most critical one briefly if relevant.
    5. TONE: Highly professional, sharp, and elite. 

    MENU:
    ${menuContext}

    UPDATES:
    ${updatesContext}

    Example Response: "Assalamu Alaikum Sir. Kacchi is available for ৳450. Shall I add it?"`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: message,
      config: { systemInstruction, temperature: 0.1 }
    });
    return response.text?.trim() || "Assalamu Alaikum Sir. How may I assist?";
  } catch (err) {
    return "My apologies Sir, system glitch. Assalamu Alaikum.";
  }
};

export const bfcSpeak = async (text: string) => {
  try {
    // Detect if text is mostly Bangla to adjust voice if necessary (Kore handles multilingual well)
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
        },
      },
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  } catch (err) {
    console.error("Audio Output Error:", err);
    return null;
  }
};

export function decodeAudio(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
}

export async function decodeAudioData(data: Uint8Array, ctx: AudioContext): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
  const channelData = buffer.getChannelData(0);
  for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
  return buffer;
}

import React, { useState, useRef, useEffect } from 'react';
import { bfcFastText, bfcSpeak, decodeAudio, decodeAudioData } from '../services/geminiService';
import { ChatMessage, User, MenuItem, MenuUpdate } from '../types';

interface ChatBotProps {
  currentUser?: User | null;
  menuItems: MenuItem[];
  menuUpdates: MenuUpdate[];
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
}

export const ChatBot: React.FC<ChatBotProps> = ({ currentUser, menuItems, menuUpdates, isOpen, setIsOpen }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isAiThinking, setIsAiThinking] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  const initAudio = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
  };

  const speakText = async (text: string) => {
    initAudio();
    const audioData = await bfcSpeak(text);
    if (!audioData || !audioContextRef.current) return;

    if (audioContextRef.current.state === 'suspended') {
      await audioContextRef.current.resume();
    }

    const buffer = await decodeAudioData(decodeAudio(audioData), audioContextRef.current);
    const source = audioContextRef.current.createBufferSource();
    source.buffer = buffer;
    source.connect(audioContextRef.current.destination);
    source.start();
  };

  const handleSend = async (textOverride?: string) => {
    const text = textOverride || input.trim();
    if (!text) return;

    initAudio();
    setMessages(prev => [...prev, { role: 'user', text, timestamp: new Date() }]);
    setInput('');
    setIsAiThinking(true);

    const response = await bfcFastText(text, menuItems, currentUser, menuUpdates);

    setMessages(prev => [...prev, { role: 'model', text: response, timestamp: new Date() }]);
    setIsAiThinking(false);
    await speakText(response);
  };

  const startListening = () => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) return alert("Security Notice: Speech recognition unavailable.");

    const recognition = new SpeechRecognition();
    // Allow both English and Bangla recognition by letting the browser handle locale or defaulting to a bilingual-friendly setup
    recognition.lang = 'bn-BD'; // Default to Bangla, but most modern browsers handle mixed input well if switched

    recognition.onstart = () => setIsListening(true);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      handleSend(transcript);
    };
    recognition.onend = () => setIsListening(false);
    recognition.onerror = () => setIsListening(false);
    recognition.start();
  };

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, isAiThinking]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[10000] flex items-end justify-center lg:items-end lg:justify-end lg:p-12 pointer-events-none">
       <div className="w-full lg:w-[420px] h-[85vh] lg:h-[750px] glass rounded-t-[60px] lg:rounded-[60px] flex flex-col overflow-hidden shadow-[0_50px_100px_rgba(0,0,0,0.8)] border border-white/20 pointer-events-auto animate-elite-up">
          <div className="bg-gradient-to-r from-red-600 to-red-800 p-8 text-white flex justify-between items-center shadow-2xl z-20">
            <div className="flex items-center gap-5">
               <div className="w-14 h-14 bg-white/20 rounded-2xl flex items-center justify-center text-3xl shadow-inner border border-white/20">
                  <i className="fas fa-user-tie"></i>
               </div>
               <div>
                  <h3 className="text-xl font-black italic uppercase tracking-tighter leading-none">BFC Assist</h3>
                  <div className="flex items-center gap-2 mt-1">
                     <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></span>
                     <span className="text-[9px] font-black uppercase tracking-[3px] opacity-80">Bilingual Active</span>
                  </div>
               </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="w-12 h-12 bg-black/10 hover:bg-black/20 rounded-full transition-all flex items-center justify-center border border-white/10">
              <i className="fas fa-times"></i>
            </button>
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar bg-slate-950/20">
            {messages.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center text-center space-y-6 opacity-20">
                <i className="fas fa-comment-dots text-6xl"></i>
                <p className="text-[10px] font-black uppercase tracking-[8px]">Awaiting Instructions Sir</p>
              </div>
            )}
            {messages.map((m, i) => (
              <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-scale-in`}>
                <div className={`max-w-[85%] p-6 rounded-[35px] text-sm font-bold leading-relaxed shadow-2xl ${m.role === 'user' ? 'bg-red-600 text-white rounded-tr-none' : 'bg-white/5 border border-white/10 text-white/90 rounded-tl-none'}`}>
                  {m.text}
                </div>
              </div>
            ))}
            {isAiThinking && (
              <div className="flex justify-start">
                 <div className="bg-white/5 border border-white/10 p-5 rounded-[30px] flex gap-3 shadow-xl">
                    <span className="w-2 h-2 rounded-full bg-red-600 animate-bounce"></span>
                    <span className="w-2 h-2 rounded-full bg-red-600 animate-bounce delay-75"></span>
                    <span className="w-2 h-2 rounded-full bg-red-600 animate-bounce delay-150"></span>
                 </div>
              </div>
            )}
          </div>

          <div className="p-8 space-y-6 bg-black/60 border-t border-white/10 backdrop-blur-3xl">
            <div className="flex gap-4">
               <button 
                 onMouseDown={initAudio}
                 onClick={startListening} 
                 className={`w-16 h-16 rounded-[24px] flex items-center justify-center shadow-2xl transition-all duration-500 border-2 ${isListening ? 'bg-emerald-500 border-emerald-400 scale-110 shadow-emerald-500/20' : 'bg-white/5 border-white/10 hover:border-red-600/50'}`}
               >
                  <i className={`fas fa-microphone ${isListening ? 'text-white' : 'text-red-600'} text-2xl`}></i>
               </button>
               <div className="flex-1 relative">
                  <input 
                    value={input} 
                    onChange={e => setInput(e.target.value)} 
                    onKeyDown={e => e.key === 'Enter' && handleSend()}
                    onFocus={initAudio}
                    placeholder="কথা বলুন বা টাইপ করুন..." 
                    className="w-full h-16 bg-white/5 border border-white/10 rounded-[24px] px-8 text-sm font-bold outline-none focus:border-red-600 transition-all shadow-inner placeholder:text-white/20"
                  />
                  <button onClick={() => handleSend()} className="absolute right-3 top-3 w-10 h-10 bg-red-600 rounded-2xl flex items-center justify-center shadow-xl transform active:scale-90 transition-all">
                    <i className="fas fa-paper-plane text-xs"></i>
                  </button>
               </div>
            </div>
            <p className="text-[8px] text-center font-black uppercase tracking-[6px] opacity-20">Elite Concierge v5.1 | Concise Mode</p>
          </div>
       </div>
    </div>
  );
};

