        </div>
        <div className="flex items-center gap-6">
          <button onClick={() => setView('CART')} className="relative w-12 h-12 glass rounded-2xl flex items-center justify-center border-white/10 hover:border-red-600/50 transition-all shadow-xl">
            <i className="fas fa-shopping-bag text-lg"></i>
            {cart.length > 0 && <span className="absolute -top-2 -right-2 bg-red-600 text-[10px] font-black w-6 h-6 rounded-full flex items-center justify-center border-2 border-[#020617] animate-pulse">{cart.length}</span>}
          </button>
          {currentUser ? (
             <div onClick={() => setView('PROFILE')} className="flex items-center gap-3 cursor-pointer group">
                <img src={currentUser.avatar || `https://ui-avatars.com/api/?name=${currentUser.name}&background=dc2626&color=fff`} className="w-12 h-12 rounded-2xl border-2 border-white/10 group-hover:border-red-600 transition-all shadow-2xl" />
             </div>
          ) : (
             <Button variant="primary" size="sm" className="!rounded-2xl !px-8" onClick={() => setView('LOGIN')}>Access Gate</Button>
          )}
        </div>
      </nav>

      <main className="flex-1 pt-24 pb-32 lg:pb-10 w-full max-w-[1920px] mx-auto px-6 lg:px-24">
        {view === 'LOGIN' && (
          <div className="min-h-[70vh] flex items-center justify-center">
            <div className="w-full max-w-lg glass p-12 lg:p-16 rounded-[60px] space-y-12 border-white/10 shadow-[0_100px_200px_rgba(0,0,0,0.8)] animate-scale-in">
              <div className="text-center space-y-4">
                 <h3 className="text-5xl font-black italic uppercase tracking-tighter">Identity Check</h3>
                 <p className="text-[10px] font-black text-red-600 tracking-[10px] uppercase">Elite Gate Authorization</p>
              </div>
              <div className="space-y-6">
                 <input placeholder="ENTER EMAIL" className="w-full glass bg-white/5 p-6 rounded-[28px] border-white/10 font-bold text-sm outline-none focus:border-red-600 transition-all shadow-inner" />
                 <input type="password" placeholder="••••••••" className="w-full glass bg-white/5 p-6 rounded-[28px] border-white/10 font-bold text-sm outline-none focus:border-red-600 transition-all shadow-inner" />
                 <Button fullWidth className="py-7 !rounded-[28px]" onClick={() => handleLogin({ id: 'E-001', name: 'Elite User', username: 'shakib_elite', email: 'shakib@bfc.com', role: UserRole.CUSTOMER, loyaltyPoints: 1500, tier: 'PLATINUM', authProvider: 'GOOGLE', createdAt: '2024-01-01', address: 'Banani, Dhaka', phone: '01700000000' })}>Authorize Session</Button>
              </div>
            </div>
          </div>
        )}

        {view === 'HOME' && (
          <div className="space-y-24 py-12 animate-elite-up">
            <section className="relative h-[75vh] rounded-[70px] overflow-hidden group shadow-4xl border border-white/5">
              <img src="https://images.unsplash.com/photo-1633945274405-b6c8069047b0?q=80&w=2000" className="absolute inset-0 w-full h-full object-cover opacity-70 group-hover:scale-110 transition-transform duration-[20s]" />
              <div className="absolute inset-0 bg-gradient-to-t from-[#020617] via-black/30 to-transparent"></div>
              <div className="relative z-10 h-full flex flex-col justify-end p-12 lg:p-24 space-y-8">
                 <h1 className="text-6xl lg:text-[11rem] font-black italic uppercase leading-[0.85] tracking-tighter text-glow">The Royal<br/>Kacchi.</h1>
                 <p className="text-base lg:text-2xl opacity-60 max-w-2xl leading-relaxed uppercase font-light tracking-wide">Reserved for those who understand the true essence of tradition.</p>
                 <div className="flex gap-6 pt-6">
                    <Button size="lg" className="!rounded-full shadow-red-600/40 !px-16" onClick={() => setView('MENU')}>Order Manifest</Button>
                    <Button variant="outline" size="lg" className="!rounded-full !border-white/20 !text-white !px-16 backdrop-blur-md" onClick={() => setIsChatOpen(true)}>Concierge Call</Button>
