                  <Button fullWidth className="py-7 !rounded-[30px]" onClick={() => setView('CHECKOUT')}>Proceed To Deployment</Button>
                </div>
              </div>
            )}
          </div>
        )}

        {view === 'CHECKOUT' && (
          <div className="max-w-5xl mx-auto py-12 animate-elite-up">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-16">
              <div className="space-y-12">
