                            { id: 'BKASH', label: 'bKash', icon: 'fa-mobile-screen' },
                            { id: 'NAGAD', label: 'Nagad', icon: 'fa-money-bill-wave' },
                            { id: 'CARD', label: 'Card', icon: 'fa-credit-card' },
                            { id: 'COD', label: 'COD', icon: 'fa-handshake' }
                          ].map(method => (
                            <button 
                              key={method.id}
                              onClick={() => setPaymentMethod(method.id as any)}
                              className={`p-6 rounded-[24px] border-2 transition-all flex flex-col items-center gap-2 ${paymentMethod === method.id ? 'bg-red-600 border-red-500 shadow-xl' : 'bg-white/5 border-white/5 hover:border-white/20'}`}
                            >
                              <i className={`fas ${method.icon} text-2xl`}></i>
                              <span className="text-[10px] font-black uppercase tracking-widest">{method.label}</span>
                            </button>
                          ))}
                       </div>
                    </div>
                 </div>
              </div>

              <div className="glass p-12 rounded-[60px] border-white/10 h-fit space-y-10 sticky top-32">
                 <h3 className="text-3xl font-black italic uppercase tracking-tighter">Manifest Review</h3>
                 <div className="space-y-6 divide-y divide-white/5">
                    {cart.map((c, i) => (
                      <div key={i} className="flex justify-between py-4">
                         <span className="text-sm font-bold opacity-60 uppercase">{c.item.name} <span className="text-red-600">x{c.qty}</span></span>
                         <span className="text-sm font-black">৳{c.item.price * c.qty}</span>
                      </div>
                    ))}
                 </div>
                 <div className="space-y-4 pt-6">
                    <div className="flex justify-between opacity-40 text-xs font-black uppercase tracking-widest">
                       <span>Subtotal</span>
