  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('bfc_user');
    setView('LOGIN');
  };

  const handleMenuUpdate = (update: MenuUpdate) => {
    setMenuUpdates(prev => [update, ...prev].slice(0, 5));
  };

  const addToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.item.id === item.id);
      if (existing) {
        return prev.map(i => i.item.id === item.id ? { ...i, qty: i.qty + 1 } : i);
      }
      return [...prev, { item, qty: 1 }];
    });
  };

  const calculateSubtotal = () => cart.reduce((acc, c) => acc + (c.item.price * c.qty), 0);
  const deliveryCharge = 50;
  const totalAmount = calculateSubtotal() + deliveryCharge;

  const initiatePayment = () => {
    if (!deliveryAddress || !customerPhone) return alert("Please provide address and phone.");
    setIsProcessingPayment(true);

    setTimeout(() => {
      const newOrder: Order = {
        id: `BFC-${Math.floor(100000 + Math.random() * 900000)}`,
        customerId: currentUser?.id || 'GUEST',
        customerName: currentUser?.name || 'Guest User',
        customerPhone: customerPhone,
        customerEmail: currentUser?.email || 'guest@bfc.com',
        address: deliveryAddress,
        items: [...cart],
        subtotal: calculateSubtotal(),
        deliveryCharge,
        discount: 0,
        total: totalAmount,
        status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(),
        paymentMethod,
        paymentStatus: paymentMethod === 'COD' ? 'UNPAID' : 'PAID',
        transactionId: paymentMethod === 'COD' ? undefined : `TXN-${Math.random().toString(36).substr(2, 9).toUpperCase()}`
      };

      setCurrentOrder(newOrder);
      setCart([]);
      setIsProcessingPayment(false);
      setView('RECEIPT');
    }, 2500);
  };

  const downloadReceiptPDF = async () => {
    if (!receiptRef.current) return;
    const canvas = await html2canvas(receiptRef.current, { scale: 3, backgroundColor: '#ffffff' });
    const imgData = canvas.toDataURL('image/png');
    const pdf = new jsPDF('p', 'mm', 'a4');
    const imgProps = pdf.getImageProperties(imgData);
    const pdfWidth = pdf.internal.pageSize.getWidth();
    const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;
    pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
    pdf.save(`BFC_Receipt_${currentOrder?.id}.pdf`);
  };

  const downloadReceiptImage = async () => {
    if (!receiptRef.current) return;
    const canvas = await html2canvas(receiptRef.current, { scale: 3, backgroundColor: '#ffffff' });
