  onLogout: () => void;
  onMenuUpdate: (update: MenuUpdate) => void;
}

type MainTab = 'DASHBOARD' | 'OPERATIONS' | 'MANIFEST' | 'INTELLIGENCE' | 'LAYOUT';
type SubTab = 
