  | 'LIVE_ORDERS' | 'KITCHEN' | 'FLEET' 
  | 'CATALOG' | 'CATEGORIES' | 'STOCK' 
  | 'REGISTRY' | 'TIERS' | 'VOUCHERS'
  | 'PRESETS' | 'EDITOR' | 'VARIABLES';

