  DASHBOARD: [
    { id: 'OVERVIEW', label: 'Overview', icon: 'fa-chart-line' },
    { id: 'REVENUE', label: 'Revenue Intel', icon: 'fa-hand-holding-dollar' },
    { id: 'TRAFFIC', label: 'User Traffic', icon: 'fa-users-rays' },
  ],
  OPERATIONS: [
    { id: 'LIVE_ORDERS', label: 'Live Orders', icon: 'fa-clock-rotate-left' },
    { id: 'KITCHEN', label: 'Kitchen Feed', icon: 'fa-fire-burner' },
    { id: 'FLEET', label: 'Fleet Status', icon: 'fa-truck-fast' },
  ],
  MANIFEST: [
    { id: 'CATALOG', label: 'Unit Catalog', icon: 'fa-book-open' },
    { id: 'CATEGORIES', label: 'Categories', icon: 'fa-tags' },
    { id: 'STOCK', label: 'Inventory', icon: 'fa-boxes-stacked' },
  ],
  INTELLIGENCE: [
    { id: 'REGISTRY', label: 'Personnel Registry', icon: 'fa-address-book' },
    { id: 'TIERS', label: 'Loyalty Tiers', icon: 'fa-crown' },
    { id: 'VOUCHERS', label: 'Voucher Codes', icon: 'fa-ticket' },
  ],
  LAYOUT: [
    { id: 'PRESETS', label: 'Presets', icon: 'fa-palette' },
    { id: 'EDITOR', label: 'Theme Editor', icon: 'fa-pen-nib' },
    { id: 'VARIABLES', label: 'CSS Variables', icon: 'fa-code' },
  ]
};

export const AdminPanel: React.FC<AdminPanelProps> = ({ user, menuItems, setMenuItems, orders, onLogout, onMenuUpdate }) => {
  const [activeTab, setActiveTab] = useState<MainTab>(user.role === UserRole.STAFF ? 'OPERATIONS' : 'DASHBOARD');
  const [activeSubTab, setActiveSubTab] = useState<SubTab>(SUB_TABS[user.role === UserRole.STAFF ? 'OPERATIONS' : 'DASHBOARD'][0].id);

  // Dynamic Theming State
  const [themes, setThemes] = useState<Record<LayoutPreset, ThemeConfig>>(() => {
    const saved = localStorage.getItem('bfc_custom_themes');
    return saved ? JSON.parse(saved) : DEFAULT_THEMES;
  });
  const [editingPreset, setEditingPreset] = useState<LayoutPreset>('ELITE_DARK');

  // Apply theme to document root for real-time preview
  useEffect(() => {
    const theme = themes[editingPreset];
    const root = document.documentElement;
    root.style.setProperty('--bg', theme.bg);
    root.style.setProperty('--fg', theme.fg);
    root.style.setProperty('--primary', theme.primary);
    root.style.setProperty('--card', theme.card);
    root.style.setProperty('--border', theme.border);
    // Optionally handle font and shadow if desired
  }, [themes, editingPreset]);

  const getAvailableTabs = (): MainTab[] => {
    switch(user.role) {
      case UserRole.ADMIN: return ['DASHBOARD', 'OPERATIONS', 'MANIFEST', 'INTELLIGENCE', 'LAYOUT'];
      case UserRole.MANAGER: return ['DASHBOARD', 'OPERATIONS', 'MANIFEST'];
      case UserRole.STAFF: return ['OPERATIONS'];
      default: return [];
    }
