                                   value={themes[editingPreset][field.key]} 
                                   onChange={(e) => handleThemeChange(field.key, e.target.value)}
                                   className="bg-white/5 border border-white/10 rounded-lg px-3 py-2 text-[10px] font-mono text-white w-24 text-center"
                                 />
                                 <input 
                                   type="color" 
                                   value={themes[editingPreset][field.key].startsWith('#') ? themes[editingPreset][field.key] : '#000000'} 
                                   onChange={(e) => handleThemeChange(field.key, e.target.value)}
                                   className="w-10 h-10 rounded-xl border-0 cursor-pointer overflow-hidden bg-transparent"
                                 />
                              </div>
                           </div>
                         ))}
