                            />
                         </div>
                      </div>
                      <div className="pt-6 border-t border-white/5">
                         <p className="text-[9px] font-black text-white/20 italic">Note: Real-time preview is active for the current session. Use 'Save Manifest' to persist changes to the global ecosystem.</p>
                      </div>
