                      <Button fullWidth onClick={handleAdminPin}>Authenticate PIN</Button>
                    </>
                  ) : (
                    <>
                      <i className="fas fa-fingerprint text-5xl text-red-600 mb-4 animate-pulse"></i>
                      <h3 className="text-3xl font-black italic uppercase tracking-tighter">Identity MFA</h3>
                      <p className="text-[10px] font-black uppercase tracking-[5px] opacity-40">Step 2: Dual-Auth Channel</p>
