                        className="w-full glass bg-white/5 p-6 rounded-[28px] border-white/10 font-bold text-center text-xl outline-none focus:border-red-600 transition-all shadow-inner tracking-[15px]" 
                      />
                      <p className="text-[8px] font-bold opacity-30 italic">Simulator Hint: 654321</p>
                      <Button fullWidth onClick={handleAdminMfa}>Authorize Secure Session</Button>
                      <button onClick={() => setAdminGateStep('PIN')} className="text-[9px] font-black uppercase tracking-widest text-white/30 hover:text-white transition-all mt-4">Reset Sequence</button>
                    </>
                  )}
               </div>
            </div>
          )
        )}
      </main>

      <nav className="fixed bottom-0 inset-x-0 z-[100] h-28 glass border-t border-white/10 flex justify-around items-center lg:hidden safe-bottom shadow-[0_-20px_50px_rgba(0,0,0,0.5)] px-8">
