           <button onClick={() => setIsChatOpen(true)} className="w-20 h-20 bg-red-600 rounded-[28px] flex items-center justify-center shadow-[0_25px_50px_rgba(220,38,38,0.5)] ring-8 ring-[#020617] transform active:scale-90 transition-all duration-300">
              <i className="fas fa-microphone text-white text-3xl"></i>
           </button>
        </div>
        <NavItem id="CART" icon="fa-shopping-bag" label="Bag" />
        <NavItem id="ADMIN" icon="fa-shield-halved" label="Command" />
      </nav>

      <div className="hidden lg:flex fixed left-8 bottom-8 z-[100]">
        <button onClick={() => setView('ADMIN')} className="w-14 h-14 glass rounded-2xl flex items-center justify-center border-white/10 hover:border-red-600/50 transition-all shadow-xl group">
          <i className="fas fa-shield-halved group-hover:text-red-600 transition-colors"></i>
        </button>
      </div>

      <ChatBot 
        currentUser={currentUser} 
        menuItems={menuItems} 
        menuUpdates={menuUpdates}
        isOpen={isChatOpen} 
        setIsOpen={setIsChatOpen} 
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { MenuItem, UserRole, User, Order, CartItem, OrderStatus, MenuUpdate, ViewState, LayoutPreset, ThemeConfig } from './types';
import { MOCK_MENU, MOCK_ORDERS, DEFAULT_THEMES } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';
import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [menuUpdates, setMenuUpdates] = useState<MenuUpdate[]>([]);
  const [view, setView] = useState<ViewState>('HOME');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isChatOpen, setIsChatOpen] = useState(false);

  // Theme Management
  const [activePreset, setActivePreset] = useState<LayoutPreset>(() => {
    return (localStorage.getItem('bfc_active_preset') as LayoutPreset) || 'BFC_CLASSIC';
  });

  // Load and apply themes on mount and update
  useEffect(() => {
    const savedThemes = localStorage.getItem('bfc_custom_themes');
    const themes: Record<LayoutPreset, ThemeConfig> = savedThemes ? JSON.parse(savedThemes) : DEFAULT_THEMES;
    const theme = themes[activePreset];
    const root = document.documentElement;

    // Apply CSS Variables
    root.style.setProperty('--bg', theme.bg);
    root.style.setProperty('--fg', theme.fg);
    root.style.setProperty('--primary', theme.primary);
    root.style.setProperty('--card', theme.card);
    root.style.setProperty('--border', theme.border);

    // Apply global class for theme-specific CSS
    document.body.className = `custom-scrollbar theme-${activePreset}`;
    localStorage.setItem('bfc_active_preset', activePreset);
  }, [activePreset, view]);

  // Admin Security State
  const [adminGateStep, setAdminGateStep] = useState<'PIN' | 'MFA' | 'UNLOCKED'>('PIN');
  const [adminPin, setAdminPin] = useState('');
  const [mfaCode, setMfaCode] = useState('');
  const [mfaSent, setMfaSent] = useState(false);

  // Checkout & Payment State
  const [paymentMethod, setPaymentMethod] = useState<'BKASH' | 'NAGAD' | 'CARD' | 'COD'>('BKASH');
  const [deliveryAddress, setDeliveryAddress] = useState(currentUser?.address || '');
  const [customerPhone, setCustomerPhone] = useState(currentUser?.phone || '');
  const [currentOrder, setCurrentOrder] = useState<Order | null>(null);
  const [isProcessingPayment, setIsProcessingPayment] = useState(false);

  const receiptRef = useRef<HTMLDivElement>(null);

  const NavItem = ({ id, icon, label }: { id: ViewState, icon: string, label: string }) => (
    <button 
      onClick={() => setView(id)}
      className={`flex flex-col items-center justify-center gap-2 w-full h-full transition-all duration-500 ${view === id ? 'text-red-600 scale-110' : 'text-gray-500 opacity-40 hover:opacity-100'}`}
    >
      <i className={`fas ${icon} text-xl ${activePreset === 'BFC_CLASSIC' && view === id ? '!text-[#2d1b5e]' : ''}`}></i>
      <span className="text-[8px] font-black uppercase tracking-[3px]">{label}</span>
    </button>
  );

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setDeliveryAddress(user.address || '');
    setCustomerPhone(user.phone || '');
    localStorage.setItem('bfc_user', JSON.stringify(user));
    setView('HOME');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('bfc_user');
    setView('LOGIN');
  };

  const handleMenuUpdate = (update: MenuUpdate) => {
    setMenuUpdates(prev => [update, ...prev].slice(0, 5));
  };

  const addToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.item.id === item.id);
      if (existing) {
        return prev.map(i => i.item.id === item.id ? { ...i, qty: i.qty + 1 } : i);
      }
      return [...prev, { item, qty: 1 }];
    });
  };

  const calculateSubtotal = () => cart.reduce((acc, c) => acc + (c.item.price * c.qty), 0);
  const deliveryCharge = 50;
  const totalAmount = calculateSubtotal() + deliveryCharge;

  const initiatePayment = () => {
    if (!deliveryAddress || !customerPhone) return alert("Please provide address and phone.");
    setIsProcessingPayment(true);

    setTimeout(() => {
      const newOrder: Order = {
        id: `BFC-${Math.floor(100000 + Math.random() * 900000)}`,
        customerId: currentUser?.id || 'GUEST',
        customerName: currentUser?.name || 'Guest User',
        customerPhone: customerPhone,
        customerEmail: currentUser?.email || 'guest@bfc.com',
        address: deliveryAddress,
        items: [...cart],
        subtotal: calculateSubtotal(),
        deliveryCharge,
        discount: 0,
        total: totalAmount,
        status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(),
        paymentMethod,
        paymentStatus: paymentMethod === 'COD' ? 'UNPAID' : 'PAID',
        transactionId: paymentMethod === 'COD' ? undefined : `TXN-${Math.random().toString(36).substr(2, 9).toUpperCase()}`
      };

      setCurrentOrder(newOrder);
      setCart([]);
      setIsProcessingPayment(false);
      setView('RECEIPT');
    }, 2500);
  };

  const downloadReceiptPDF = async () => {
    if (!receiptRef.current) return;
    const canvas = await html2canvas(receiptRef.current, { scale: 3, backgroundColor: '#ffffff' });
    const imgData = canvas.toDataURL('image/png');
    const pdf = new jsPDF('p', 'mm', 'a4');
    const imgProps = pdf.getImageProperties(imgData);
    const pdfWidth = pdf.internal.pageSize.getWidth();
    const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;
    pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
    pdf.save(`BFC_Receipt_${currentOrder?.id}.pdf`);
  };

  const downloadReceiptImage = async () => {
    if (!receiptRef.current) return;
    const canvas = await html2canvas(receiptRef.current, { scale: 3, backgroundColor: '#ffffff' });
    const link = document.createElement('a');
    link.download = `BFC_Receipt_${currentOrder?.id}.png`;
    link.href = canvas.toDataURL('image/png');
    link.click();
  };

  const handleAdminPin = () => {
    if (adminPin === '1234') {
      setAdminGateStep('MFA');
      setTimeout(() => setMfaSent(true), 1000);
    } else {
      alert('Security Breach: Invalid Command PIN');
    }
  };

  const handleAdminMfa = () => {
    if (mfaCode === '654321') {
      setAdminGateStep('UNLOCKED');
    } else {
      alert('Security Breach: Invalid MFA Auth-Key');
    }
  };

