        <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-12 h-12 bg-red-600 rounded-2xl flex items-center justify-center font-black text-2xl shadow-2xl shadow-red-600/30 group-hover:rotate-6 transition-transform themed-primary">B</div>
          <div className="hidden sm:block">
            <h1 className="text-xl font-black italic uppercase tracking-tighter leading-none">
              {activePreset === 'BFC_CLASSIC' ? 'বাংলা ফুড ক্লাব' : 'BFC Elite'}
            </h1>
            <p className={`text-[8px] font-black tracking-[5px] uppercase mt-1 ${activePreset === 'BFC_CLASSIC' ? 'accent-green-text' : 'text-red-600'}`}>
              {activePreset === 'BFC_CLASSIC' ? 'The Real Taste Of Bangla' : 'Professional Core'}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-6">
          <button onClick={() => setView('CART')} className="relative w-12 h-12 glass rounded-2xl flex items-center justify-center border-white/10 hover:border-red-600/50 transition-all shadow-xl">
            <i className="fas fa-shopping-bag text-lg"></i>
            {cart.length > 0 && <span className="absolute -top-2 -right-2 bg-red-600 text-[10px] font-black w-6 h-6 rounded-full flex items-center justify-center border-2 border-[#020617] animate-pulse themed-primary">{cart.length}</span>}
          </button>
          {currentUser ? (
             <div onClick={() => setView('PROFILE')} className="flex items-center gap-3 cursor-pointer group">
                <img src={currentUser.avatar || `https://ui-avatars.com/api/?name=${currentUser.name}&background=dc2626&color=fff`} className="w-12 h-12 rounded-2xl border-2 border-white/10 group-hover:border-red-600 transition-all shadow-2xl" />
             </div>
          ) : (
             <Button variant="primary" size="sm" className="!rounded-2xl !px-8 themed-primary" onClick={() => setView('LOGIN')}>Access Gate</Button>
          )}
        </div>
      </nav>

      <main className="flex-1 pt-24 pb-32 lg:pb-10 w-full max-w-[1920px] mx-auto px-6 lg:px-24">
        {view === 'LOGIN' && (
          <div className="min-h-[70vh] flex items-center justify-center">
            <div className="w-full max-w-lg glass p-12 lg:p-16 rounded-[60px] space-y-12 border-white/10 shadow-[0_100px_200px_rgba(0,0,0,0.8)] animate-scale-in">
              <div className="text-center space-y-4">
                 <h3 className="text-5xl font-black italic uppercase tracking-tighter">Identity Check</h3>
                 <p className={`text-[10px] font-black tracking-[10px] uppercase ${activePreset === 'BFC_CLASSIC' ? 'accent-green-text' : 'text-red-600'}`}>Elite Gate Authorization</p>
              </div>
              <div className="space-y-6">
                 <input placeholder="ENTER EMAIL" className="w-full glass bg-white/5 p-6 rounded-[28px] border-white/10 font-bold text-sm outline-none focus:border-red-600 transition-all shadow-inner" />
                 <input type="password" placeholder="••••••••" className="w-full glass bg-white/5 p-6 rounded-[28px] border-white/10 font-bold text-sm outline-none focus:border-red-600 transition-all shadow-inner" />
                 <Button fullWidth className="py-7 !rounded-[28px] themed-primary" onClick={() => handleLogin({ id: 'E-001', name: 'Admin One', username: 'admin_master', email: 'admin@bfc.com', role: UserRole.ADMIN, loyaltyPoints: 9999, tier: 'DIAMOND', authProvider: 'GOOGLE', createdAt: '2023-01-01', address: 'BFC HQ, Dhaka', phone: '01911111111' })}>Authorize Session</Button>
