  const [activePreset] = useState<LayoutPreset>(() => {
    return (localStorage.getItem('bfc_active_preset') as LayoutPreset) || 'BFC_CLASSIC';
  });

  useEffect(() => {
    const savedThemes = localStorage.getItem('bfc_custom_themes');
    const themes: Record<LayoutPreset, ThemeConfig> = savedThemes ? JSON.parse(savedThemes) : DEFAULT_THEMES;
    const theme = themes[activePreset];
    const root = document.documentElement;

    root.style.setProperty('--bg', theme.bg);
    root.style.setProperty('--fg', theme.fg);
    root.style.setProperty('--primary', theme.primary);
    root.style.setProperty('--card', theme.card);
    root.style.setProperty('--border', theme.border);

    document.body.className = `custom-scrollbar theme-${activePreset}`;
