        </div>
        <NavItem id="CART" icon="fa-shopping-bag" label="Bag" />
        <NavItem id="ADMIN" icon="fa-shield-halved" label="Admin" />
      </nav>

      {/* --- GLOBAL CHATBOT --- */}
      <ChatBot 
        currentUser={currentUser} 
        menuItems={menuItems} 
        menuUpdates={menuUpdates}
        isOpen={isChatOpen} 
        setIsOpen={setIsChatOpen} 
      />
    </div>
  );
};

