import React, { useState, useEffect, useMemo } from 'react';
import { MenuItem, UserRole, User, Order, CartItem, OrderStatus, MenuUpdate, ViewState, LayoutPreset, ThemeConfig } from './types';
import { MOCK_MENU, DEFAULT_THEMES } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('bfc_orders');
    return saved ? JSON.parse(saved) : [];
  });
  const [view, setView] = useState<ViewState>('HOME');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeCategory, setActiveCategory] = useState('ALL');
  const [paymentMethod, setPaymentMethod] = useState<'BKASH' | 'NAGAD' | null>(null);
  const [lastOrder, setLastOrder] = useState<Order | null>(null);

  useEffect(() => {
    localStorage.setItem('bfc_orders', JSON.stringify(orders));
  }, [orders]);

  const categories = useMemo(() => ['ALL', ...new Set(menuItems.map(i => i.category.toUpperCase()))], [menuItems]);
  const filteredMenu = useMemo(() => {
    return menuItems.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase()) || item.nameBn.includes(searchTerm);
      const matchesCategory = activeCategory === 'ALL' || item.category.toUpperCase() === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [menuItems, searchTerm, activeCategory]);

  const addToCart = (item: MenuItem) => {
    if (item.stock === 0) return;
    setCart(prev => {
      const existing = prev.find(i => i.item.id === item.id);
      if (existing) return prev.map(i => i.item.id === item.id ? { ...i, qty: i.qty + 1 } : i);
      return [...prev, { item, qty: 1 }];
    });
  };

  const calculateSubtotal = () => cart.reduce((acc, c) => acc + (c.item.price * c.qty), 0);

  const handleProcessPayment = (method: 'BKASH' | 'NAGAD') => {
    setPaymentMethod(method);
    setView('PAYMENT');
  };

  const completeOrder = () => {
    const newOrder: Order = {
      id: `ORD-${Date.now().toString().slice(-6)}`,
      customerId: currentUser?.id || 'GUEST',
      customerName: currentUser?.name || 'Guest User',
      customerPhone: currentUser?.phone || 'Unknown',
      address: currentUser?.address || 'Pickup',
      items: [...cart],
      subtotal: calculateSubtotal(),
      deliveryCharge: 50,
      total: calculateSubtotal() + 50,
      status: OrderStatus.PENDING,
      paymentMethod: paymentMethod!,
      transactionId: `TRX-${Math.random().toString(36).toUpperCase().slice(2, 10)}`,
      createdAt: new Date().toISOString()
    };
    setOrders(prev => [newOrder, ...prev]);
    setLastOrder(newOrder);
    setCart([]);
    setView('RECEIPT');
  };

  const NavItem = ({ id, icon, label }: { id: ViewState, icon: string, label: string }) => (
    <button onClick={() => setView(id)} className={`flex flex-col items-center justify-center gap-1 w-full h-full transition-all ${view === id ? 'text-[#8b1e3f] scale-110' : 'text-gray-400 opacity-50'}`}>
      <i className={`fas ${icon} text-xl`}></i>
      <span className="text-[8px] font-black uppercase tracking-[2px]">{label}</span>
    </button>
  );

  return (
    <div className="min-h-screen flex flex-col bg-white">
      {/* Navbar */}
      <nav className="fixed top-0 inset-x-0 z-[100] glass px-6 h-20 flex justify-between items-center border-b">
        <div className="flex items-center gap-4 cursor-pointer" onClick={() => setView('HOME')}>
          <div className="w-12 h-12 bg-[#8b1e3f] rounded-2xl flex items-center justify-center text-white font-black text-2xl shadow-xl">B</div>
          <div className="hidden sm:block">
            <h1 className="text-xl font-black italic uppercase leading-none tracking-tighter">Bangla Food Club</h1>
            <p className="text-[8px] font-black tracking-[3px] uppercase text-[#008b45]">বিএফসি - খাঁটি স্বাদ</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setView('CART')} className="relative w-12 h-12 bg-gray-50 rounded-2xl flex items-center justify-center border">
            <i className="fas fa-shopping-cart text-lg"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-[#8b1e3f] text-[10px] text-white font-black w-6 h-6 rounded-full flex items-center justify-center border-2 border-white">{cart.length}</span>}
          </button>
          {!currentUser ? (
            <Button size="sm" onClick={() => setView('LOGIN')}>Login</Button>
          ) : (
            <img onClick={() => setView('PROFILE')} src={currentUser.avatar || `https://ui-avatars.com/api/?name=${currentUser.name}`} className="w-12 h-12 rounded-2xl cursor-pointer border shadow-md" />
          )}
        </div>
      </nav>

      <main className="flex-1 pt-20 pb-32">
        {view === 'HOME' && (
          <div className="reveal space-y-20 p-6 lg:p-24">
             <div className="grid lg:grid-cols-2 gap-12 items-center">
                <div className="space-y-8">
                   <h2 className="text-7xl lg:text-9xl font-black italic uppercase leading-[0.85] tracking-tighter">খাঁটি স্বাদের <br/> <span className="text-[#8b1e3f]">আসল মেজবানি।</span></h2>
                   <p className="text-lg text-gray-500 max-w-lg">BFC brings the elite taste of Bangladeshi heritage to your doorstep. Authentic, fresh, and premium.</p>
                   <Button size="lg" onClick={() => setView('MENU')}>View Catalog</Button>
                </div>
                <img src="https://images.unsplash.com/photo-1601050690597-df0568f70950?q=80&w=1000" className="rounded-[60px] shadow-2xl h-[500px] object-cover" />
             </div>
          </div>
        )}

        {view === 'MENU' && (
          <div className="reveal max-w-7xl mx-auto px-6 space-y-12 pt-10">
             <div className="flex flex-col lg:flex-row justify-between items-end gap-10">
                <h2 className="text-6xl font-black italic uppercase tracking-tighter">Manifest</h2>
                <input placeholder="Search favorites..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full lg:w-96 bg-gray-50 p-6 rounded-[25px] font-bold text-sm outline-none border focus:border-[#8b1e3f]/20 shadow-sm" />
             </div>
             <div className="category-bar-sticky glass rounded-3xl p-3 flex gap-3 overflow-x-auto no-scrollbar shadow-xl border border-[#8b1e3f]/10">
                {categories.map(cat => (
                  <button key={cat} onClick={() => setActiveCategory(cat)} className={`px-10 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeCategory === cat ? 'bg-[#8b1e3f] text-white' : 'text-gray-500 hover:bg-gray-100'}`}>{cat}</button>
                ))}
             </div>
             <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-10">
                {filteredMenu.map(item => (
                  <div key={item.id} className="bg-white rounded-[50px] overflow-hidden border border-gray-100 shadow-xl group hover:-translate-y-2 transition-all p-5">
                     <img src={item.image} className="h-60 w-full object-cover rounded-[40px] mb-5" />
                     <h4 className="text-2xl font-black italic uppercase">{item.nameBn}</h4>
                     <p className="text-xs text-gray-400 font-bold uppercase mb-4">{item.name}</p>
                     <div className="flex justify-between items-center mt-auto">
                        <span className="text-xl font-black text-[#8b1e3f]">৳{item.price}</span>
                        <Button size="sm" onClick={() => addToCart(item)} disabled={item.stock === 0}>Add To Bag</Button>
                     </div>
                  </div>
                ))}
             </div>
          </div>
        )}

