import React, { useState } from 'react';
import { Order, MenuItem, OrderStatus, UserRole, User, MenuUpdate } from './types';
import { Button } from './components/Button';

interface AdminPanelProps {
  user: User;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: any;
  onLogout: () => void;
  onMenuUpdate: (update: MenuUpdate) => void;
  cms: any;
  setCms: any;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ user, menuItems, setMenuItems, orders, setOrders, onLogout }) => {
  const [activeTab, setActiveTab] = useState<'DASHBOARD' | 'ORDERS' | 'MENU'>('DASHBOARD');

  const updateOrderStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders((prev: Order[]) => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
  };

  const toggleStock = (id: string) => {
    setMenuItems(prev => prev.map(m => m.id === id ? { ...m, stock: m.stock > 0 ? 0 : 50 } : m));
  };

  const calculateTotalRevenue = () => orders.reduce((acc, o) => acc + o.total, 0);

  return (
    <div className="h-[85vh] glass rounded-[60px] flex overflow-hidden border shadow-2xl animate-elite-up">
       <aside className="w-80 bg-black/5 border-r p-10 flex flex-col gap-10">
          <h1 className="text-3xl font-black italic uppercase">Terminal</h1>
          <nav className="flex flex-col gap-4">
             {['DASHBOARD', 'ORDERS', 'MENU'].map((t: any) => (
               <button key={t} onClick={() => setActiveTab(t)} className={`px-8 py-5 rounded-2xl text-[10px] font-black uppercase tracking-widest text-left ${activeTab === t ? 'bg-[#8b1e3f] text-white shadow-xl' : 'hover:bg-black/5 text-gray-500'}`}>{t}</button>
             ))}
          </nav>
          <div className="mt-auto">
             <Button variant="danger" fullWidth onClick={onLogout}>Exit Terminal</Button>
          </div>
       </aside>

       <main className="flex-1 p-16 overflow-y-auto custom-scrollbar space-y-12">
          {activeTab === 'DASHBOARD' && (
             <div className="space-y-10 reveal">
                <h2 className="text-5xl font-black italic uppercase">Performance Intel</h2>
                <div className="grid grid-cols-3 gap-8">
                   <div className="bg-white p-10 rounded-[45px] border shadow-xl">
                      <p className="text-[10px] font-black uppercase text-gray-400">Total Revenue</p>
                      <h4 className="text-4xl font-black text-[#8b1e3f] mt-2">৳{calculateTotalRevenue()}</h4>
                   </div>
                   <div className="bg-white p-10 rounded-[45px] border shadow-xl">
                      <p className="text-[10px] font-black uppercase text-gray-400">Total Deployments</p>
                      <h4 className="text-4xl font-black text-[#8b1e3f] mt-2">{orders.length}</h4>
                   </div>
                   <div className="bg-white p-10 rounded-[45px] border shadow-xl">
                      <p className="text-[10px] font-black uppercase text-gray-400">Active Units</p>
                      <h4 className="text-4xl font-black text-[#8b1e3f] mt-2">{menuItems.length}</h4>
                   </div>
                </div>
             </div>
          )}

          {activeTab === 'ORDERS' && (
             <div className="space-y-8 reveal">
                <h2 className="text-5xl font-black italic uppercase">Live Operations</h2>
                <div className="grid gap-6">
                   {orders.map(o => (
                     <div key={o.id} className="bg-white p-8 rounded-[40px] border shadow-lg flex justify-between items-center">
                        <div className="flex gap-8 items-center">
                           <div className="w-14 h-14 bg-gray-50 rounded-2xl flex items-center justify-center text-2xl font-black text-[#8b1e3f]">{o.id.slice(-2)}</div>
                           <div>
                              <h4 className="text-xl font-black uppercase">{o.customerName}</h4>
                              <p className="text-xs text-gray-400 font-bold">{o.customerPhone} | {o.paymentMethod}</p>
                           </div>
                        </div>
                        <select value={o.status} onChange={e => updateOrderStatus(o.id, e.target.value as OrderStatus)} className="bg-gray-50 border p-3 rounded-xl font-bold text-xs uppercase">
                           {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                     </div>
                   ))}
                </div>
             </div>
          )}

          {activeTab === 'MENU' && (
             <div className="space-y-8 reveal">
                <h2 className="text-5xl font-black italic uppercase">Manifest Control</h2>
                <div className="grid grid-cols-2 gap-8">
                   {menuItems.map(item => (
                     <div key={item.id} className="bg-white p-8 rounded-[40px] border shadow-lg flex gap-8 items-center">
                        <img src={item.image} className="w-24 h-24 rounded-[30px] object-cover" />
                        <div className="flex-1">
                           <h5 className="text-xl font-black italic uppercase">{item.nameBn}</h5>
                           <p className="text-[10px] font-black text-gray-400 mb-4">PRICE: ৳{item.price}</p>
                           <button onClick={() => toggleStock(item.id)} className={`px-6 py-2 rounded-xl text-[8px] font-black uppercase tracking-widest ${item.stock > 0 ? 'bg-emerald-100 text-emerald-600' : 'bg-red-100 text-red-600'}`}>
                             {item.stock > 0 ? 'ACTIVE' : 'OFFLINE'}
                           </button>
                        </div>
                     </div>
                   ))}
                </div>
             </div>
          )}
       </main>
    </div>
  );
};

