               <button 
                 key={t.id} 
                 onClick={() => { setActiveTab(t.id as any); setSelectedCustomer(null); }} 
                 className={`flex items-center gap-4 px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all duration-300 ${activeTab === t.id ? 'bg-[#8b1e3f] text-white shadow-2xl shadow-[#8b1e3f]/20 scale-105' : 'hover:bg-white/5 text-gray-500 hover:text-white'}`}
