                                     <p><i className="fas fa-envelope mr-3 text-[#8b1e3f]"></i> {selectedCustomer.email}</p>
                                     <p><i className="fas fa-venus-mars mr-3 text-[#8b1e3f]"></i> {selectedCustomer.gender}</p>
                                     <p className="col-span-full"><i className="fas fa-location-dot mr-3 text-[#8b1e3f]"></i> {selectedCustomer.address}</p>
