                      </div>
                   )}
                </div>
             )}
          </div>
       </main>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Order, MenuItem, OrderStatus, UserRole, User, MenuUpdate } from './types';
import { Button } from './components/Button';
import { 
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  AreaChart, Area, BarChart, Bar, Cell 
} from 'recharts';

interface AdminPanelProps {
  user: User;
  users: User[];
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: any;
  onLogout: () => void;
  onMenuUpdate: (update: MenuUpdate) => void;
  cms: any;
  setCms: any;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  user, users, menuItems, setMenuItems, orders, setOrders, onLogout, onMenuUpdate 
}) => {
  const [activeTab, setActiveTab] = useState<'DASHBOARD' | 'ORDERS' | 'MENU' | 'CUSTOMERS'>('DASHBOARD');
  const [customerSearch, setCustomerSearch] = useState('');
  const [selectedCustomer, setSelectedCustomer] = useState<User | null>(null);

  // Edit Menu Item State
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);

  const updateOrderStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders((prev: Order[]) => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
  };

  const toggleStock = (id: string) => {
    setMenuItems(prev => prev.map(m => {
      if (m.id === id) {
        const newStock = m.stock > 0 ? 0 : 50;
        onMenuUpdate({
          type: 'AVAILABILITY',
          itemName: m.name,
          details: newStock > 0 ? 'Item reactivated' : 'Item marked out of stock',
          timestamp: new Date()
        });
        return { ...m, stock: newStock };
      }
      return m;
    }));
  };

  const handleSaveItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingItem) return;

    setMenuItems(prev => {
      const exists = prev.find(i => i.id === editingItem.id);
      if (exists) {
        onMenuUpdate({
          type: 'PRICE_CHANGE',
          itemName: editingItem.name,
          details: `Unit details updated in Manifest`,
          timestamp: new Date()
        });
        return prev.map(i => i.id === editingItem.id ? editingItem : i);
      } else {
        onMenuUpdate({
          type: 'ADD',
          itemName: editingItem.name,
          details: `New strategic unit deployed`,
          timestamp: new Date()
        });
        return [...prev, editingItem];
      }
    });
    setEditingItem(null);
  };

  // --- ANALYTICS DATA ---
  const revenueData = useMemo(() => {
    const daily: Record<string, number> = {};
    orders.forEach(o => {
      const date = new Date(o.createdAt).toLocaleDateString('en-US', { weekday: 'short' });
      daily[date] = (daily[date] || 0) + o.total;
    });
    return Object.entries(daily).map(([name, value]) => ({ name, value }));
  }, [orders]);

  const kpis = {
    revenue: orders.reduce((acc, o) => acc + o.total, 0),
    orderCount: orders.length,
    customerCount: users.length,
    pending: orders.filter(o => o.status === OrderStatus.PENDING).length
  };

  const filteredCustomers = useMemo(() => {
    return users.filter(u => 
      u.name.toLowerCase().includes(customerSearch.toLowerCase()) || 
      u.phone.includes(customerSearch)
    );
  }, [users, customerSearch]);

  const getCustomerOrders = (userId: string) => orders.filter(o => o.customerId === userId);

  return (
    <div className="h-[90vh] bg-[#020617] text-white rounded-[40px] lg:rounded-[60px] flex flex-col lg:flex-row overflow-hidden border border-white/5 shadow-[0_50px_100px_rgba(0,0,0,0.8)] animate-elite-up relative">

       {/* --- EDIT MODAL --- */}
       {editingItem && (
         <div className="fixed inset-0 z-[500] flex items-center justify-center p-6 lg:p-12 bg-black/80 backdrop-blur-md">
            <div className="w-full max-w-2xl bg-[#0f172a] border border-white/10 rounded-[50px] overflow-hidden shadow-[0_0_100px_rgba(139,30,63,0.3)] animate-scale-in">
               <div className="p-8 lg:p-12 border-b border-white/5 flex justify-between items-center bg-gradient-to-r from-[#8b1e3f]/20 to-transparent">
                  <h3 className="text-3xl font-black italic uppercase tracking-tighter">Modify Manifest Unit</h3>
                  <button onClick={() => setEditingItem(null)} className="w-12 h-12 rounded-full bg-white/5 hover:bg-white/10 flex items-center justify-center transition-all">
                     <i className="fas fa-times"></i>
                  </button>
               </div>
               <form onSubmit={handleSaveItem} className="p-8 lg:p-12 space-y-6">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                     <div className="space-y-2">
                        <label className="text-[9px] font-black uppercase text-gray-500 tracking-[3px]">Internal Name</label>
                        <input 
                           required
                           className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-[#8b1e3f] font-bold"
                           value={editingItem.name}
                           onChange={e => setEditingItem({...editingItem, name: e.target.value})}
                        />
                     </div>
                     <div className="space-y-2">
                        <label className="text-[9px] font-black uppercase text-gray-500 tracking-[3px]">Display Name (BN)</label>
                        <input 
                           required
                           className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-[#8b1e3f] font-bold"
                           value={editingItem.nameBn}
                           onChange={e => setEditingItem({...editingItem, nameBn: e.target.value})}
                        />
                     </div>
                     <div className="space-y-2">
                        <label className="text-[9px] font-black uppercase text-gray-500 tracking-[3px]">Strategic Value (Price)</label>
                        <input 
                           required
                           type="number"
                           className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-[#8b1e3f] font-bold"
                           value={editingItem.price}
                           onChange={e => setEditingItem({...editingItem, price: parseInt(e.target.value)})}
                        />
                     </div>
                     <div className="space-y-2">
                        <label className="text-[9px] font-black uppercase text-gray-500 tracking-[3px]">Sector (Category)</label>
                        <input 
                           required
                           className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-[#8b1e3f] font-bold"
                           value={editingItem.category}
                           onChange={e => setEditingItem({...editingItem, category: e.target.value})}
                        />
                     </div>
                     <div className="col-span-full space-y-2">
                        <label className="text-[9px] font-black uppercase text-gray-500 tracking-[3px]">Visual Link (Image URL)</label>
                        <input 
                           required
                           className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-[#8b1e3f] font-bold"
                           value={editingItem.image}
                           onChange={e => setEditingItem({...editingItem, image: e.target.value})}
                        />
                     </div>
                     <div className="col-span-full space-y-2">
                        <label className="text-[9px] font-black uppercase text-gray-500 tracking-[3px]">Tactical Intel (Description)</label>
                        <textarea 
                           className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-[#8b1e3f] font-bold h-32 resize-none"
                           value={editingItem.description}
                           onChange={e => setEditingItem({...editingItem, description: e.target.value})}
                        />
                     </div>
                  </div>
                  <div className="pt-6 flex gap-4">
                     <Button type="button" variant="outline" fullWidth onClick={() => setEditingItem(null)}>Cancel</Button>
                     <Button type="submit" fullWidth>Commit Changes</Button>
                  </div>
               </form>
            </div>
         </div>
       )}

       {/* --- STRATEGIC SIDEBAR --- */}
       <aside className="w-full lg:w-72 bg-black/40 border-b lg:border-b-0 lg:border-r border-white/5 p-8 flex flex-col gap-10 backdrop-blur-3xl">
          <div className="flex items-center gap-4">
             <div className="w-12 h-12 bg-[#8b1e3f] rounded-2xl flex items-center justify-center text-white text-2xl font-black shadow-2xl">B</div>
             <div>
                <h1 className="text-lg font-black italic uppercase tracking-tighter leading-none">Command</h1>
                <p className="text-[7px] font-black text-emerald-500 uppercase tracking-[5px] mt-1">Status: Online</p>
             </div>
          </div>

          <nav className="flex lg:flex-col gap-2 overflow-x-auto no-scrollbar pb-4 lg:pb-0">
