                                    </div>
                                    <div className="bg-black/40 p-5 rounded-3xl border border-white/5">
                                       <p className="text-[8px] font-black uppercase text-gray-500 mb-1">Tier</p>
                                       <p className="text-xl font-black text-emerald-500">{cust.tier}</p>
                                    </div>
                                 </div>
                              </div>
                            ))}
                         </div>
                      </>
                   ) : (
                      <div className="space-y-10 reveal">
                         <button onClick={() => setSelectedCustomer(null)} className="text-[10px] font-black uppercase tracking-widest text-gray-500 hover:text-white transition-colors flex items-center gap-2">
                            <i className="fas fa-arrow-left"></i> Return to Registry
                         </button>
                         <div className="bg-white/5 p-12 rounded-[60px] border border-white/5 space-y-12">
                            <div className="flex flex-col md:flex-row items-center gap-12 border-b border-white/5 pb-12">
                               <img src={selectedCustomer.avatar || `https://ui-avatars.com/api/?name=${selectedCustomer.name}&background=8b1e3f&color=fff`} className="w-48 h-48 rounded-[50px] shadow-2xl border-4 border-white/5" />
                               <div className="flex-1 space-y-4 text-center md:text-left">
                                  <h3 className="text-5xl font-black italic uppercase">{selectedCustomer.name}</h3>
                                  <span className="inline-block bg-[#8b1e3f] text-white px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-[5px]">{selectedCustomer.tier} Operative</span>
                                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6 text-sm font-bold opacity-60 pt-6">
                                     <p><i className="fas fa-phone mr-3 text-[#8b1e3f]"></i> {selectedCustomer.phone}</p>
                                     <p><i className="fas fa-envelope mr-3 text-[#8b1e3f]"></i> {selectedCustomer.email}</p>
                                     <p><i className="fas fa-venus-mars mr-3 text-[#8b1e3f]"></i> {selectedCustomer.gender}</p>
                                     <p className="col-span-full"><i className="fas fa-location-dot mr-3 text-[#8b1e3f]"></i> {selectedCustomer.address}</p>
                                  </div>
                               </div>
                            </div>
                            <div className="space-y-8">
                               <h4 className="text-2xl font-black uppercase italic tracking-widest">Deployment Logs</h4>
                               <div className="grid gap-4">
                                  {getCustomerOrders(selectedCustomer.id).map(order => (
                                    <div key={order.id} className="bg-black/40 p-6 rounded-3xl flex justify-between items-center border border-white/5">
                                       <div>
                                          <p className="text-[9px] font-black opacity-30 uppercase">{order.id}</p>
                                          <p className="font-bold">{new Date(order.createdAt).toLocaleDateString()}</p>
                                       </div>
                                       <div className="text-right">
                                          <p className="text-2xl font-black text-[#8b1e3f]">৳{order.total}</p>
                                          <span className="text-[9px] font-black uppercase tracking-widest text-emerald-500">{order.status}</span>
                                       </div>
                                    </div>
                                  ))}
                               </div>
                            </div>
                         </div>
                      </div>
                   )}
                </div>
             )}
          </div>
       </main>
    </div>
  );
};

export enum UserRole {
  ADMIN = 'ADMIN',
  MANAGER = 'MANAGER',
  STAFF = 'STAFF',
  CUSTOMER = 'CUSTOMER'
}

export enum OrderStatus {
  PENDING = 'PENDING',
  PREPARING = 'PREPARING',
  READY = 'READY',
  ON_THE_WAY = 'ON_THE_WAY',
  DELIVERED = 'DELIVERED',
  CANCELLED = 'CANCELLED'
}

export type LayoutPreset = 'BFC_CLASSIC' | 'ELITE_DARK' | 'MINIMAL_WHITE';

export interface ThemeConfig {
  bg: string;
  fg: string;
  primary: string;
  accent: string;
  card: string;
  border: string;
  font: string;
  shadow: string;
}

export interface User {
  id: string;
  name: string;
  username: string;
  email: string;
  phone: string;
  address: string;
  gender: 'MALE' | 'FEMALE' | 'OTHER';
  bio?: string;
  avatar?: string;
  role: UserRole;
  loyaltyPoints: number;
  tier: string;
  createdAt: string;
  vouchers?: string[];
}

export interface MenuItem {
  id: string;
  name: string;
  nameBn: string;
  description: string;
  price: number;
  category: string;
  image: string;
  stock: number;
  isPopular?: boolean;
}

export interface MenuUpdate {
  type: 'ADD' | 'PRICE_CHANGE' | 'AVAILABILITY' | 'PROMO';
  itemName: string;
  details: string;
  timestamp: Date;
}

export interface CartItem {
  item: MenuItem;
  qty: number;
}

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  customerPhone: string;
  address: string;
  items: CartItem[];
  subtotal: number;
  deliveryCharge: number;
  total: number;
  status: OrderStatus;
  paymentMethod: 'BKASH' | 'NAGAD';
  transactionId: string;
  createdAt: string;
}

export type ViewState = 'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'PROFILE' | 'LOGIN' | 'SIGNUP' | 'PAYMENT' | 'RECEIPT';

// Fix: Added ChatMessage interface to resolve the import error in ChatBot.tsx
export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

import React, { useState, useMemo } from 'react';
import { Order, MenuItem, OrderStatus, UserRole, User, MenuUpdate } from './types';
import { Button } from './components/Button';
import { 
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  AreaChart, Area, BarChart, Bar, Cell 
} from 'recharts';

interface AdminPanelProps {
  user: User;
  users: User[];
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: any;
  onLogout: () => void;
  onMenuUpdate: (update: MenuUpdate) => void;
  cms: any;
  setCms: any;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  user, users, menuItems, setMenuItems, orders, setOrders, onLogout, onMenuUpdate 
}) => {
  const [activeTab, setActiveTab] = useState<'DASHBOARD' | 'ORDERS' | 'MENU' | 'CUSTOMERS'>('DASHBOARD');
  const [customerSearch, setCustomerSearch] = useState('');
  const [selectedCustomer, setSelectedCustomer] = useState<User | null>(null);
  const [customerSubTab, setCustomerSubTab] = useState<'LOGS' | 'VOUCHERS' | 'BIO'>('LOGS');

  // Edit Menu Item State
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);

  const updateOrderStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders((prev: Order[]) => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
  };

  const toggleStock = (id: string) => {
    setMenuItems(prev => prev.map(m => {
      if (m.id === id) {
        const newStock = m.stock > 0 ? 0 : 50;
        onMenuUpdate({
          type: 'AVAILABILITY',
          itemName: m.name,
          details: newStock > 0 ? 'Item reactivated' : 'Item marked out of stock',
          timestamp: new Date()
        });
        return { ...m, stock: newStock };
      }
      return m;
    }));
  };

  const handleSaveItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingItem) return;

    setMenuItems(prev => {
      const exists = prev.find(i => i.id === editingItem.id);
      if (exists) {
        onMenuUpdate({
          type: 'PRICE_CHANGE',
          itemName: editingItem.name,
          details: `Unit details updated in Manifest`,
          timestamp: new Date()
        });
        return prev.map(i => i.id === editingItem.id ? editingItem : i);
      } else {
        onMenuUpdate({
          type: 'ADD',
          itemName: editingItem.name,
          details: `New strategic unit deployed`,
          timestamp: new Date()
        });
        return [...prev, editingItem];
      }
    });
    setEditingItem(null);
  };

  // --- ANALYTICS DATA ---
  const revenueData = useMemo(() => {
    const daily: Record<string, number> = {};
    orders.forEach(o => {
      const date = new Date(o.createdAt).toLocaleDateString('en-US', { weekday: 'short' });
      daily[date] = (daily[date] || 0) + o.total;
    });
    return Object.entries(daily).map(([name, value]) => ({ name, value }));
  }, [orders]);

  const kpis = {
    revenue: orders.reduce((acc, o) => acc + o.total, 0),
    orderCount: orders.length,
    customerCount: users.length,
    pending: orders.filter(o => o.status === OrderStatus.PENDING).length
  };

  const filteredCustomers = useMemo(() => {
    return users.filter(u => 
      u.name.toLowerCase().includes(customerSearch.toLowerCase()) || 
      u.phone.includes(customerSearch)
    );
  }, [users, customerSearch]);

  const getCustomerOrders = (userId: string) => orders.filter(o => o.customerId === userId);

  const calculateCustomerMetrics = (userId: string) => {
    const userOrders = getCustomerOrders(userId);
    const totalSpent = userOrders.reduce((acc, o) => acc + o.total, 0);
    const avgOrder = userOrders.length > 0 ? totalSpent / userOrders.length : 0;
    return { totalSpent, totalOrders: userOrders.length, avgOrder };
  };

  return (
    <div className="h-[90vh] bg-[#020617] text-white rounded-[40px] lg:rounded-[60px] flex flex-col lg:flex-row overflow-hidden border border-white/5 shadow-[0_50px_100px_rgba(0,0,0,0.8)] animate-elite-up relative">

       {/* --- EDIT MODAL --- */}
       {editingItem && (
         <div className="fixed inset-0 z-[500] flex items-center justify-center p-6 lg:p-12 bg-black/80 backdrop-blur-md">
            <div className="w-full max-w-2xl bg-[#0f172a] border border-white/10 rounded-[50px] overflow-hidden shadow-[0_0_100px_rgba(139,30,63,0.3)] animate-scale-in">
               <div className="p-8 lg:p-12 border-b border-white/5 flex justify-between items-center bg-gradient-to-r from-[#8b1e3f]/20 to-transparent">
                  <h3 className="text-3xl font-black italic uppercase tracking-tighter">Modify Manifest Unit</h3>
                  <button onClick={() => setEditingItem(null)} className="w-12 h-12 rounded-full bg-white/5 hover:bg-white/10 flex items-center justify-center transition-all">
                     <i className="fas fa-times"></i>
                  </button>
               </div>
               <form onSubmit={handleSaveItem} className="p-8 lg:p-12 space-y-6">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                     <div className="space-y-2">
                        <label className="text-[9px] font-black uppercase text-gray-500 tracking-[3px]">Internal Name</label>
                        <input 
                           required
                           className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-[#8b1e3f] font-bold"
                           value={editingItem.name}
                           onChange={e => setEditingItem({...editingItem, name: e.target.value})}
                        />
                     </div>
                     <div className="space-y-2">
                        <label className="text-[9px] font-black uppercase text-gray-500 tracking-[3px]">Display Name (BN)</label>
                        <input 
                           required
                           className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-[#8b1e3f] font-bold"
                           value={editingItem.nameBn}
                           onChange={e => setEditingItem({...editingItem, nameBn: e.target.value})}
                        />
                     </div>
                     <div className="space-y-2">
                        <label className="text-[9px] font-black uppercase text-gray-500 tracking-[3px]">Strategic Value (Price)</label>
                        <input 
                           required
                           type="number"
                           className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-[#8b1e3f] font-bold"
                           value={editingItem.price}
                           onChange={e => setEditingItem({...editingItem, price: parseInt(e.target.value)})}
                        />
                     </div>
                     <div className="space-y-2">
                        <label className="text-[9px] font-black uppercase text-gray-500 tracking-[3px]">Sector (Category)</label>
                        <input 
                           required
                           className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-[#8b1e3f] font-bold"
                           value={editingItem.category}
                           onChange={e => setEditingItem({...editingItem, category: e.target.value})}
                        />
                     </div>
                     <div className="col-span-full space-y-2">
                        <label className="text-[9px] font-black uppercase text-gray-500 tracking-[3px]">Visual Link (Image URL)</label>
                        <input 
                           required
                           className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-[#8b1e3f] font-bold"
                           value={editingItem.image}
                           onChange={e => setEditingItem({...editingItem, image: e.target.value})}
                        />
                     </div>
                     <div className="col-span-full space-y-2">
                        <label className="text-[9px] font-black uppercase text-gray-500 tracking-[3px]">Tactical Intel (Description)</label>
                        <textarea 
                           className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-[#8b1e3f] font-bold h-32 resize-none"
                           value={editingItem.description}
                           onChange={e => setEditingItem({...editingItem, description: e.target.value})}
                        />
                     </div>
                  </div>
                  <div className="pt-6 flex gap-4">
                     <Button type="button" variant="outline" fullWidth onClick={() => setEditingItem(null)}>Cancel</Button>
                     <Button type="submit" fullWidth>Commit Changes</Button>
                  </div>
               </form>
            </div>
         </div>
       )}

       {/* --- STRATEGIC SIDEBAR --- */}
       <aside className="w-full lg:w-72 bg-black/40 border-b lg:border-b-0 lg:border-r border-white/5 p-8 flex flex-col gap-10 backdrop-blur-3xl">
          <div className="flex items-center gap-4">
             <div className="w-12 h-12 bg-[#8b1e3f] rounded-2xl flex items-center justify-center text-white text-2xl font-black shadow-2xl">B</div>
             <div>
                <h1 className="text-lg font-black italic uppercase tracking-tighter leading-none">Command</h1>
                <p className="text-[7px] font-black text-emerald-500 uppercase tracking-[5px] mt-1">Status: Online</p>
             </div>
          </div>

          <nav className="flex lg:flex-col gap-2 overflow-x-auto no-scrollbar pb-4 lg:pb-0">
             {[
               { id: 'DASHBOARD', icon: 'fa-chart-pie', label: 'Intel' },
               { id: 'ORDERS', icon: 'fa-truck-fast', label: 'Fleet' },
               { id: 'MENU', icon: 'fa-folder-tree', label: 'Manifest' },
               { id: 'CUSTOMERS', icon: 'fa-users-gear', label: 'Personnel' }
             ].map((t) => (
               <button 
                 key={t.id} 
                 onClick={() => { setActiveTab(t.id as any); setSelectedCustomer(null); }} 
                 className={`flex items-center gap-4 px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all duration-300 ${activeTab === t.id ? 'bg-[#8b1e3f] text-white shadow-2xl shadow-[#8b1e3f]/20 scale-105' : 'hover:bg-white/5 text-gray-500 hover:text-white'}`}
               >
                 <i className={`fas ${t.icon} text-sm`}></i>
                 <span className="hidden lg:inline">{t.label}</span>
               </button>
             ))}
          </nav>

          <div className="mt-auto hidden lg:block space-y-4">
             <div className="bg-white/5 p-5 rounded-3xl border border-white/5">
                <p className="text-[8px] font-black uppercase text-gray-500 mb-2">Logged as Admin</p>
                <p className="text-[10px] font-bold truncate">{user.name}</p>
             </div>
             <Button variant="danger" fullWidth onClick={onLogout} className="!rounded-2xl !py-4">Sign Out</Button>
          </div>
       </aside>

       {/* --- MAIN TERMINAL AREA --- */}
       <main className="flex-1 overflow-y-auto custom-scrollbar bg-gradient-to-br from-[#020617] to-[#0f172a]">

          <header className="p-8 lg:px-12 lg:py-10 border-b border-white/5 flex justify-between items-center sticky top-0 bg-[#020617]/80 backdrop-blur-xl z-20">
             <div>
                <h2 className="text-4xl font-black italic uppercase tracking-tighter leading-none">{activeTab}</h2>
                <p className="text-[8px] font-black uppercase text-[#8b1e3f] tracking-[10px] mt-2">BFC Global Control</p>
             </div>
             <div className="flex items-center gap-4">
                <div className="hidden md:flex flex-col items-end">
                   <p className="text-[10px] font-bold text-gray-400">{new Date().toLocaleDateString()}</p>
                   <p className="text-[8px] font-black text-emerald-500 uppercase tracking-widest">System Operational</p>
                </div>
                <div className="w-10 h-10 rounded-xl bg-white/5 border border-white/10 flex items-center justify-center">
                   <i className="fas fa-bell text-gray-400"></i>
                </div>
             </div>
          </header>

          <div className="p-8 lg:p-12 space-y-12 pb-32">

             {/* --- DASHBOARD VIEW --- */}
             {activeTab === 'DASHBOARD' && (
                <div className="space-y-12 reveal">

                   {/* KPI Grid */}
                   <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                      {[
                        { label: 'Total Revenue', value: `৳${kpis.revenue}`, icon: 'fa-dollar-sign', color: 'text-emerald-500' },
                        { label: 'Total Deployments', value: kpis.orderCount, icon: 'fa-box', color: 'text-blue-500' },
                        { label: 'Registered Personnel', value: kpis.customerCount, icon: 'fa-user-group', color: 'text-purple-500' },
                        { label: 'Critical/Pending', value: kpis.pending, icon: 'fa-triangle-exclamation', color: 'text-[#8b1e3f]' }
                      ].map((item, i) => (
                        <div key={i} className="bg-white/5 border border-white/5 p-8 rounded-[35px] hover:border-white/20 transition-all group">
                           <div className="flex justify-between items-start mb-6">
                              <div className={`w-12 h-12 rounded-2xl bg-white/5 flex items-center justify-center ${item.color} group-hover:scale-110 transition-transform`}>
                                 <i className={`fas ${item.icon} text-lg`}></i>
                              </div>
                              <span className="text-[10px] font-black text-emerald-500">+12%</span>
                           </div>
                           <p className="text-[9px] font-black uppercase text-gray-500 tracking-widest">{item.label}</p>
                           <h4 className="text-3xl font-black mt-2 tracking-tighter">{item.value}</h4>
                        </div>
                      ))}
                   </div>

                   {/* Charts Section */}
                   <div className="grid lg:grid-cols-3 gap-8">
                      <div className="lg:col-span-2 bg-white/5 border border-white/5 p-10 rounded-[45px]">
                         <h3 className="text-xl font-black italic uppercase mb-10 tracking-widest">Revenue Flow (Weekly)</h3>
                         <div className="h-80 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                               <AreaChart data={revenueData}>
                                  <defs>
                                     <linearGradient id="colorRev" x1="0" y1="0" x2="0" y2="1">
                                        <stop offset="5%" stopColor="#8b1e3f" stopOpacity={0.3}/>
                                        <stop offset="95%" stopColor="#8b1e3f" stopOpacity={0}/>
                                     </linearGradient>
                                  </defs>
                                  <CartesianGrid strokeDasharray="3 3" stroke="#ffffff05" vertical={false} />
                                  <XAxis dataKey="name" stroke="#4b5563" fontSize={10} fontWeight="bold" axisLine={false} tickLine={false} />
                                  <YAxis stroke="#4b5563" fontSize={10} fontWeight="bold" axisLine={false} tickLine={false} />
                                  <Tooltip 
                                    contentStyle={{ background: '#020617', border: '1px solid #ffffff10', borderRadius: '15px', color: '#fff' }} 
                                    itemStyle={{ color: '#8b1e3f' }}
                                  />
                                  <Area type="monotone" dataKey="value" stroke="#8b1e3f" fillOpacity={1} fill="url(#colorRev)" strokeWidth={4} />
                               </AreaChart>
                            </ResponsiveContainer>
                         </div>
                      </div>

                      <div className="bg-white/5 border border-white/5 p-10 rounded-[45px] space-y-8">
                         <h3 className="text-xl font-black italic uppercase tracking-widest">Live Activity</h3>
                         <div className="space-y-6">
                            {orders.slice(0, 5).map((o, i) => (
                              <div key={i} className="flex gap-4 items-center">
                                 <div className="w-10 h-10 rounded-xl bg-emerald-500/10 flex items-center justify-center text-emerald-500 text-xs">
                                    <i className="fas fa-plus"></i>
                                 </div>
                                 <div className="flex-1">
                                    <p className="text-[10px] font-bold">{o.customerName} ordered for ৳{o.total}</p>
                                    <p className="text-[8px] font-black text-gray-500 uppercase mt-0.5">{new Date(o.createdAt).toLocaleTimeString()}</p>
                                 </div>
                              </div>
                            ))}
                         </div>
                      </div>
                   </div>
                </div>
             )}

             {/* --- FLEET (ORDERS) VIEW --- */}
             {activeTab === 'ORDERS' && (
                <div className="space-y-8 reveal">
                   <div className="flex justify-between items-end">
                      <h3 className="text-4xl font-black italic uppercase tracking-tighter">Fleet Ops</h3>
                      <div className="flex gap-2">
                         <span className="bg-emerald-500/10 text-emerald-500 px-4 py-2 rounded-xl text-[8px] font-black uppercase tracking-widest border border-emerald-500/20">Active: {kpis.orderCount}</span>
                      </div>
                   </div>
                   <div className="grid gap-4">
                      {orders.length > 0 ? orders.map(o => (
                        <div key={o.id} className="bg-white/5 p-8 rounded-[35px] border border-white/5 flex flex-col md:flex-row justify-between items-center gap-6 group hover:border-[#8b1e3f]/40 transition-all">
                           <div className="flex gap-8 items-center">
                              <div className="w-16 h-16 bg-white/5 rounded-2xl flex items-center justify-center text-2xl font-black text-[#8b1e3f] border border-white/10 group-hover:bg-[#8b1e3f] group-hover:text-white transition-all">
                                 {o.id.slice(-2)}
                              </div>
                              <div>
                                 <h4 className="text-xl font-black uppercase group-hover:text-[#8b1e3f] transition-colors">{o.customerName}</h4>
                                 <p className="text-xs text-gray-500 font-bold">{o.customerPhone} | ৳{o.total} | {o.paymentMethod}</p>
                              </div>
                           </div>
                           <div className="flex gap-4 items-center w-full md:w-auto">
                              <span className="text-[8px] font-black uppercase tracking-widest text-gray-500">{new Date(o.createdAt).toLocaleTimeString()}</span>
                              <select 
                                value={o.status} 
                                onChange={e => updateOrderStatus(o.id, e.target.value as OrderStatus)} 
                                className="bg-black/40 border border-white/10 p-4 rounded-2xl font-black text-[9px] uppercase outline-none focus:ring-2 ring-[#8b1e3f]/30 flex-1 md:flex-none cursor-pointer"
                              >
                                 {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                              </select>
                           </div>
                        </div>
                      )) : <div className="py-40 text-center opacity-20 uppercase font-black text-2xl tracking-[10px]">No Active Ops</div>}
                   </div>
                </div>
             )}

             {/* --- MANIFEST (MENU) VIEW --- */}
             {activeTab === 'MENU' && (
                <div className="space-y-8 reveal">
                   <div className="flex justify-between items-end">
                      <h3 className="text-4xl font-black italic uppercase tracking-tighter">Unit Manifest</h3>
                      <Button size="sm" className="!rounded-2xl !bg-white !text-black" onClick={() => setEditingItem({
                         id: `U-${Date.now()}`,
                         name: '',
                         nameBn: '',
                         description: '',
                         price: 0,
                         category: 'General',
                         image: '',
                         stock: 50
                      })}>New Unit</Button>
