import React, { useState, useMemo, useRef } from 'react';
import { Order, MenuItem, OrderStatus, UserRole, User, MenuUpdate, ThemeConfig } from './types';
import { Button } from './components/Button';
import { 
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  AreaChart, Area, BarChart, Bar, Cell 
} from 'recharts';

interface AdminPanelProps {
  user: User;
  users: User[];
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: any;
  onLogout: () => void;
  onMenuUpdate: (update: MenuUpdate) => void;
  cms: any;
  setCms: any;
  theme: ThemeConfig;
  setTheme: React.Dispatch<React.SetStateAction<ThemeConfig>>;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  user, users, menuItems, setMenuItems, orders, setOrders, onLogout, onMenuUpdate, theme, setTheme 
}) => {
  const [activeTab, setActiveTab] = useState<'DASHBOARD' | 'ORDERS' | 'MENU' | 'CUSTOMERS' | 'LAYOUT'>('DASHBOARD');
  const [customerSearch, setCustomerSearch] = useState('');
  const [selectedCustomer, setSelectedCustomer] = useState<User | null>(null);
  const [customerSubTab, setCustomerSubTab] = useState<'LOGS' | 'VOUCHERS' | 'BIO'>('LOGS');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);

  const updateOrderStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders((prev: Order[]) => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
  };

  const toggleStock = (id: string) => {
    setMenuItems(prev => prev.map(m => {
      if (m.id === id) {
        const newStock = m.stock > 0 ? 0 : 50;
        onMenuUpdate({
          type: 'AVAILABILITY',
          itemName: m.name,
          details: newStock > 0 ? 'Item reactivated' : 'Item marked out of stock',
          timestamp: new Date()
        });
        return { ...m, stock: newStock };
      }
      return m;
    }));
  };

  const handleSaveItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingItem) return;

    setMenuItems(prev => {
      const exists = prev.find(i => i.id === editingItem.id);
      if (exists) {
        onMenuUpdate({
          type: 'PRICE_CHANGE',
          itemName: editingItem.name,
          details: `Unit details updated in Manifest`,
          timestamp: new Date()
        });
        return prev.map(i => i.id === editingItem.id ? editingItem : i);
      } else {
        onMenuUpdate({
          type: 'ADD',
          itemName: editingItem.name,
          details: `New strategic unit deployed`,
          timestamp: new Date()
        });
        return [...prev, editingItem];
      }
    });
    setEditingItem(null);
  };

  // --- EXPORT/IMPORT LOGIC ---
  const handleExportTheme = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(theme, null, 2));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", "bfc-strategy-layout.json");
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const handleImportTheme = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const json = JSON.parse(e.target?.result as string);
        if (json.primary && json.bg && json.card) {
          setTheme(json);
          alert("Strategic Blueprint successfully imported!");
        } else {
          alert("Invalid Blueprint format.");
        }
      } catch (err) {
        alert("Execution failed: File is corrupted.");
      }
    };
    reader.readAsText(file);
  };

  // --- ANALYTICS DATA ---
  const revenueData = useMemo(() => {
    const daily: Record<string, number> = {};
    orders.forEach(o => {
      const date = new Date(o.createdAt).toLocaleDateString('en-US', { weekday: 'short' });
      daily[date] = (daily[date] || 0) + o.total;
    });
    return Object.entries(daily).map(([name, value]) => ({ name, value }));
  }, [orders]);

  const kpis = {
    revenue: orders.reduce((acc, o) => acc + o.total, 0),
    orderCount: orders.length,
    customerCount: users.length,
