  };

  const filteredCustomers = useMemo(() => {
    return users.filter(u => 
      u.name.toLowerCase().includes(customerSearch.toLowerCase()) || 
      u.phone.includes(customerSearch)
    );
  }, [users, customerSearch]);

  const getCustomerOrders = (userId: string) => orders.filter(o => o.customerId === userId);

  const calculateCustomerMetrics = (userId: string) => {
    const userOrders = getCustomerOrders(userId);
    const totalSpent = userOrders.reduce((acc, o) => acc + o.total, 0);
    const avgOrder = userOrders.length > 0 ? totalSpent / userOrders.length : 0;
    return { totalSpent, totalOrders: userOrders.length, avgOrder };
  };

  return (
