                               <div className="pt-4 flex gap-4">
                                  <div className="px-6 py-2 rounded-xl text-[8px] font-black uppercase tracking-widest text-white" style={{ backgroundColor: theme.primary }}>Action Unit</div>
                                  <div className="px-6 py-2 rounded-xl text-[8px] font-black uppercase tracking-widest text-white" style={{ backgroundColor: theme.accent }}>Success Status</div>
                               </div>
                            </div>

                            <div className="p-8 rounded-[30px] bg-white/5 border border-white/5 flex items-center justify-between">
                               <p className="text-[10px] font-black uppercase tracking-widest text-gray-500">Blueprint Integrity</p>
                               <span className="text-emerald-500 text-xs font-black">100% OPERATIONAL</span>
                            </div>
                         </div>
                      </div>
                   </div>
                </div>
             )}
          </div>
       </main>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { MenuItem, UserRole, User, Order, CartItem, OrderStatus, MenuUpdate, ViewState, LayoutPreset, ThemeConfig } from './types';
import { MOCK_MENU, DEFAULT_THEMES } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [currentTheme, setCurrentTheme] = useState<ThemeConfig>(() => {
    const saved = localStorage.getItem('bfc_theme');
    return saved ? JSON.parse(saved) : DEFAULT_THEMES.BFC_CLASSIC;
  });

  const [allUsers, setAllUsers] = useState<User[]>(() => {
    const saved = localStorage.getItem('bfc_all_users');
    if (saved) return JSON.parse(saved);
    return [{ 
      id: 'U1', 
      name: 'Elite Member', 
      username: 'member', 
      email: 'user@bfc.com', 
      phone: '01712345678', 
      address: 'Dhanmondi, Dhaka', 
      gender: 'MALE', 
      role: UserRole.CUSTOMER, 
      loyaltyPoints: 150, 
      tier: 'GOLD', 
      createdAt: '2024-01-01' 
    }];
  });

  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('bfc_orders');
    return saved ? JSON.parse(saved) : [];
  });
  const [view, setView] = useState<ViewState>('HOME');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeCategory, setActiveCategory] = useState('ALL');
  const [paymentMethod, setPaymentMethod] = useState<'BKASH' | 'NAGAD' | null>(null);
  const [lastOrder, setLastOrder] = useState<Order | null>(null);
  const [transactionId, setTransactionId] = useState('');

  useEffect(() => {
    localStorage.setItem('bfc_orders', JSON.stringify(orders));
  }, [orders]);

  useEffect(() => {
    localStorage.setItem('bfc_all_users', JSON.stringify(allUsers));
  }, [allUsers]);

  useEffect(() => {
    localStorage.setItem('bfc_theme', JSON.stringify(currentTheme));
    const root = document.documentElement;
    root.style.setProperty('--primary', currentTheme.primary);
    root.style.setProperty('--bg', currentTheme.bg);
    root.style.setProperty('--fg', currentTheme.fg);
    root.style.setProperty('--card', currentTheme.card);
    root.style.setProperty('--border', currentTheme.border);
  }, [currentTheme]);

  const categories = useMemo(() => ['ALL', ...new Set(menuItems.map(i => i.category.toUpperCase()))], [menuItems]);
  const filteredMenu = useMemo(() => {
    return menuItems.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase()) || item.nameBn.includes(searchTerm);
      const matchesCategory = activeCategory === 'ALL' || item.category.toUpperCase() === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [menuItems, searchTerm, activeCategory]);

  const addToCart = (item: MenuItem) => {
    if (item.stock === 0) return;
    setCart(prev => {
      const existing = prev.find(i => i.item.id === item.id);
      if (existing) return prev.map(i => i.item.id === item.id ? { ...i, qty: i.qty + 1 } : i);
      return [...prev, { item, qty: 1 }];
    });
  };

  const removeFromCart = (itemId: string) => {
    setCart(prev => prev.filter(i => i.item.id !== itemId));
  };

  const updateCartQty = (itemId: string, delta: number) => {
    setCart(prev => prev.map(i => {
      if (i.item.id === itemId) {
        const newQty = Math.max(1, i.qty + delta);
        return { ...i, qty: newQty };
      }
      return i;
    }));
  };

  const calculateSubtotal = () => cart.reduce((acc, c) => acc + (c.item.price * c.qty), 0);

  const handleCheckout = () => {
    if (cart.length === 0) return alert("Your bag is empty!");
    if (!currentUser) return setView('LOGIN');
    setView('PAYMENT');
  };

  const completeOrder = () => {
    if (!transactionId || transactionId.length < 5) return alert("Please enter a valid Transaction ID");

    const newOrder: Order = {
      id: `ORD-${Date.now().toString().slice(-6)}`,
      customerId: currentUser?.id || 'GUEST',
      customerName: currentUser?.name || 'Guest User',
      customerPhone: currentUser?.phone || 'Unknown',
      address: currentUser?.address || 'Default Address',
      items: [...cart],
      subtotal: calculateSubtotal(),
      deliveryCharge: 50,
      total: calculateSubtotal() + 50,
      status: OrderStatus.PENDING,
      paymentMethod: paymentMethod || 'BKASH',
      transactionId: transactionId,
      createdAt: new Date().toISOString()
    };

    setOrders(prev => [newOrder, ...prev]);
    setLastOrder(newOrder);
    setCart([]);
    setTransactionId('');
    setView('RECEIPT');
  };

  const NavItem = ({ id, icon, label }: { id: ViewState, icon: string, label: string }) => (
    <button onClick={() => setView(id)} className={`flex flex-col items-center justify-center gap-1 w-full h-full transition-all ${view === id ? 'text-[#8b1e3f] scale-110' : 'text-gray-400 opacity-50'}`}>
      <i className={`fas ${icon} text-xl`}></i>
      <span className="text-[8px] font-black uppercase tracking-[2px]">{label}</span>
    </button>
  );

  return (
    <div className="min-h-screen flex flex-col" style={{ backgroundColor: 'var(--bg)', color: 'var(--fg)' }}>
      {/* Navbar */}
      <nav className="fixed top-0 inset-x-0 z-[100] glass px-6 h-20 flex justify-between items-center border-b">
        <div className="flex items-center gap-4 cursor-pointer" onClick={() => setView('HOME')}>
          <div className="w-12 h-12 rounded-2xl flex items-center justify-center text-white font-black text-2xl shadow-xl" style={{ backgroundColor: 'var(--primary)' }}>B</div>
          <div className="hidden sm:block">
            <h1 className="text-xl font-black italic uppercase leading-none tracking-tighter">Bangla Food Club</h1>
            <p className="text-[8px] font-black tracking-[3px] uppercase" style={{ color: 'var(--accent)' }}>বিএফসি - খাঁটি স্বাদ</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setView('CART')} className="relative w-12 h-12 bg-gray-50/10 rounded-2xl flex items-center justify-center border border-white/10">
            <i className="fas fa-shopping-cart text-lg"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 text-[10px] text-white font-black w-6 h-6 rounded-full flex items-center justify-center border-2 border-white" style={{ backgroundColor: 'var(--primary)' }}>{cart.length}</span>}
          </button>
          {!currentUser ? (
            <Button size="sm" onClick={() => setView('LOGIN')}>Login</Button>
          ) : (
            <img onClick={() => setView('PROFILE')} src={currentUser.avatar || `https://ui-avatars.com/api/?name=${currentUser.name}&background=8b1e3f&color=fff`} className="w-12 h-12 rounded-2xl cursor-pointer border shadow-md" />
          )}
        </div>
      </nav>

      <main className="flex-1 pt-20 pb-32">
        {view === 'HOME' && (
          <div className="reveal space-y-20 p-6 lg:p-24">
             <div className="grid lg:grid-cols-2 gap-12 items-center">
                <div className="space-y-8 text-center lg:text-left">
                   <h2 className="text-6xl lg:text-9xl font-black italic uppercase leading-[0.85] tracking-tighter">খাঁটি স্বাদের <br/> <span style={{ color: 'var(--primary)' }}>আসল মেজবানি।</span></h2>
                   <p className="text-lg opacity-60 max-w-lg mx-auto lg:mx-0">BFC brings the elite taste of Bangladeshi heritage to your doorstep. Authentic, fresh, and premium.</p>
                   <Button size="lg" onClick={() => setView('MENU')}>View Catalog</Button>
                </div>
                <img src="https://images.unsplash.com/photo-1601050690597-df0568f70950?q=80&w=1000" className="rounded-[60px] shadow-2xl h-[500px] object-cover" />
             </div>
          </div>
        )}

        {view === 'MENU' && (
          <div className="reveal max-w-7xl mx-auto px-6 space-y-12 pt-10">
             <div className="flex flex-col lg:flex-row justify-between items-end gap-10">
                <h2 className="text-6xl font-black italic uppercase tracking-tighter">Manifest</h2>
                <input placeholder="Search favorites..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full lg:w-96 bg-black/5 p-6 rounded-[25px] font-bold text-sm outline-none border border-white/10 focus:border-red-600/20 shadow-sm" />
             </div>
             <div className="category-bar-sticky glass rounded-3xl p-3 flex gap-3 overflow-x-auto no-scrollbar shadow-xl border border-white/5">
                {categories.map(cat => (
                  <button key={cat} onClick={() => setActiveCategory(cat)} className={`px-10 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeCategory === cat ? 'text-white' : 'text-gray-500 hover:bg-black/5'}`} style={{ backgroundColor: activeCategory === cat ? 'var(--primary)' : 'transparent' }}>{cat}</button>
                ))}
             </div>
             <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-10">
                {filteredMenu.map(item => (
                  <div key={item.id} className="rounded-[50px] overflow-hidden border border-white/5 shadow-xl group hover:-translate-y-2 transition-all p-5 flex flex-col" style={{ backgroundColor: 'var(--card)' }}>
                     <img src={item.image} className="h-60 w-full object-cover rounded-[40px] mb-5" />
                     <h4 className="text-2xl font-black italic uppercase">{item.nameBn}</h4>
                     <p className="text-xs text-gray-400 font-bold uppercase mb-4">{item.name}</p>
                     <div className="flex justify-between items-center mt-auto">
                        <span className="text-xl font-black" style={{ color: 'var(--primary)' }}>৳{item.price}</span>
                        <Button size="sm" onClick={() => addToCart(item)} disabled={item.stock === 0}>{item.stock > 0 ? 'Add To Bag' : 'Out of Stock'}</Button>
                     </div>
                  </div>
                ))}
             </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="reveal max-w-4xl mx-auto px-6 pt-10 space-y-10">
             <h2 className="text-5xl font-black italic uppercase tracking-tighter">Your Bag</h2>
             {cart.length > 0 ? (
               <div className="space-y-6">
                 <div className="bg-white/5 rounded-[40px] p-8 border border-white/10 space-y-6" style={{ backgroundColor: 'var(--card)' }}>
                   {cart.map(c => (
                     <div key={c.item.id} className="flex items-center justify-between py-4 border-b border-white/5 last:border-0">
                       <div className="flex items-center gap-6">
                         <img src={c.item.image} className="w-20 h-20 rounded-2xl object-cover" />
                         <div>
                           <h4 className="text-xl font-black uppercase italic">{c.item.nameBn}</h4>
                           <p className="text-sm font-bold opacity-40">৳{c.item.price} per unit</p>
                         </div>
                       </div>
                       <div className="flex items-center gap-6">
                         <div className="flex items-center bg-black/5 rounded-xl px-4 py-2 border border-white/10">
                           <button onClick={() => updateCartQty(c.item.id, -1)} className="px-2 text-xl font-black">-</button>
                           <span className="px-4 font-black">{c.qty}</span>
                           <button onClick={() => updateCartQty(c.item.id, 1)} className="px-2 text-xl font-black">+</button>
                         </div>
                         <button onClick={() => removeFromCart(c.item.id)} className="text-red-500 hover:text-red-700"><i className="fas fa-trash"></i></button>
                       </div>
                     </div>
                   ))}
                 </div>
                 <div className="bg-white/5 rounded-[40px] p-10 border border-white/10 space-y-6" style={{ backgroundColor: 'var(--card)' }}>
                   <div className="flex justify-between text-xl font-bold opacity-60"><span>Subtotal</span><span>৳{calculateSubtotal()}</span></div>
                   <div className="flex justify-between text-xl font-bold opacity-60"><span>Delivery Charge</span><span>৳50</span></div>
                   <div className="flex justify-between text-3xl font-black border-t border-white/10 pt-6"><span>Total</span><span style={{ color: 'var(--primary)' }}>৳{calculateSubtotal() + 50}</span></div>
                   <Button fullWidth size="lg" onClick={handleCheckout}>Proceed to Checkout</Button>
                 </div>
               </div>
             ) : (
               <div className="py-40 text-center space-y-6 opacity-20">
                 <i className="fas fa-shopping-bag text-9xl"></i>
                 <p className="text-2xl font-black uppercase tracking-[10px]">Your bag is empty</p>
                 <Button onClick={() => setView('MENU')}>Back to Menu</Button>
               </div>
             )}
          </div>
        )}

        {view === 'PAYMENT' && (
          <div className="reveal max-w-md mx-auto px-6 pt-10 space-y-10">
             <h2 className="text-4xl font-black italic uppercase tracking-tighter text-center">Secure Checkout</h2>
             <div className="bg-white/5 rounded-[50px] p-10 border border-white/10 space-y-10 shadow-2xl" style={{ backgroundColor: 'var(--card)' }}>
                <div className="space-y-4">
                  <p className="text-[10px] font-black uppercase text-gray-500 tracking-[3px] text-center">Select Gateway</p>
                  <div className="grid grid-cols-2 gap-4">
                    <button onClick={() => setPaymentMethod('BKASH')} className={`p-6 rounded-3xl border-2 transition-all flex flex-col items-center gap-3 ${paymentMethod === 'BKASH' ? 'border-[#D12053] bg-[#D12053]/5' : 'border-white/5 hover:border-white/20'}`}>
                      <img src="https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSq_uXm_7Qz-eKj4iY4_XN-E0t9-w-9_C8pYw&s" className="h-10 object-contain" alt="bKash" />
                      <span className="text-[10px] font-black">bKash</span>
                    </button>
                    <button onClick={() => setPaymentMethod('NAGAD')} className={`p-6 rounded-3xl border-2 transition-all flex flex-col items-center gap-3 ${paymentMethod === 'NAGAD' ? 'border-[#F15922] bg-[#F15922]/5' : 'border-white/5 hover:border-white/20'}`}>
                      <img src="https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR_R7-B7-S7H_e6_8z3W9l0N0z2P-O7n_P6eA&s" className="h-10 object-contain" alt="Nagad" />
                      <span className="text-[10px] font-black">Nagad</span>
                    </button>
                  </div>
                </div>

                {paymentMethod && (
                  <div className="space-y-6 animate-scale-in">
                    <div className="bg-black/5 p-6 rounded-3xl border border-white/5 space-y-4">
                      <p className="text-sm font-bold text-center">Send Money to: <span className="text-red-600 font-black">017XXXXXXXX</span></p>
                      <p className="text-sm font-bold text-center">Amount: <span className="font-black">৳{calculateSubtotal() + 50}</span></p>
                    </div>
                    <div className="space-y-2">
                      <label className="text-[9px] font-black uppercase text-gray-500 tracking-[3px]">Transaction ID</label>
                      <input 
                        value={transactionId}
                        onChange={e => setTransactionId(e.target.value)}
                        placeholder="e.g. 8K3J9S1L" 
                        className="w-full bg-black/5 p-5 rounded-2xl border border-white/10 outline-none font-bold text-center uppercase" 
                      />
                    </div>
                    <Button fullWidth onClick={completeOrder}>Verify & Complete</Button>
                  </div>
                )}
             </div>
          </div>
        )}

        {view === 'RECEIPT' && lastOrder && (
          <div className="reveal max-w-xl mx-auto px-6 pt-10 space-y-10">
             <div className="text-center space-y-4">
                <div className="w-24 h-24 bg-emerald-500 rounded-full flex items-center justify-center mx-auto shadow-2xl shadow-emerald-500/20 text-white text-4xl animate-bounce">
                  <i className="fas fa-check"></i>
                </div>
                <h2 className="text-4xl font-black italic uppercase tracking-tighter">Order Placed!</h2>
                <p className="text-sm font-bold opacity-40 uppercase tracking-[4px]">Thank you for choosing BFC Elite</p>
             </div>

             <div className="bg-white/5 rounded-[60px] p-12 border-4 border-dashed border-white/10 space-y-10 relative overflow-hidden" style={{ backgroundColor: 'var(--card)' }}>
                <div className="absolute top-0 right-0 p-10 opacity-[0.03] -rotate-12"><i className="fas fa-receipt text-[200px]"></i></div>

                <div className="flex justify-between items-start pb-8 border-b border-white/10">
                   <div>
                      <p className="text-[10px] font-black opacity-30 uppercase tracking-widest">ORDER_ID</p>
                      <h4 className="text-2xl font-black text-[#8b1e3f]">{lastOrder.id}</h4>
                   </div>
                   <div className="text-right">
                      <p className="text-[10px] font-black opacity-30 uppercase tracking-widest">DATE</p>
                      <h4 className="font-bold">{new Date(lastOrder.createdAt).toLocaleDateString()}</h4>
                   </div>
                </div>

                <div className="space-y-4">
                   {lastOrder.items.map((c, i) => (
                     <div key={i} className="flex justify-between font-bold">
                        <span>{c.item.nameBn} x {c.qty}</span>
                        <span>৳{c.item.price * c.qty}</span>
                     </div>
                   ))}
                   <div className="pt-4 border-t border-white/5 space-y-2 opacity-60 text-sm font-bold">
                      <div className="flex justify-between"><span>Delivery</span><span>৳50</span></div>
                      <div className="flex justify-between"><span>Payment Mode</span><span>{lastOrder.paymentMethod}</span></div>
                   </div>
                   <div className="pt-6 border-t border-white/10 flex justify-between items-center">
                      <span className="text-xl font-black uppercase italic">Total Paid</span>
                      <span className="text-3xl font-black" style={{ color: 'var(--primary)' }}>৳{lastOrder.total}</span>
                   </div>
                </div>

                <div className="bg-black/5 p-6 rounded-3xl text-center space-y-1">
                   <p className="text-[8px] font-black opacity-40 uppercase tracking-widest">Transaction Hash</p>
                   <p className="font-mono text-xs font-bold">{lastOrder.transactionId}</p>
                </div>

                <div className="flex gap-4">
                   <Button variant="outline" fullWidth size="sm" onClick={() => window.print()}>Save Receipt</Button>
                   <Button fullWidth size="sm" onClick={() => setView('HOME')}>Finish Session</Button>
                </div>
             </div>
          </div>
        )}

        {view === 'LOGIN' && (
          <div className="flex items-center justify-center px-6 min-h-[70vh]">
             <div className="w-full max-w-md p-12 rounded-[50px] border border-white/5 shadow-2xl space-y-10" style={{ backgroundColor: 'var(--card)' }}>
                <h3 className="text-3xl font-black italic uppercase text-center">Member Login</h3>
                <div className="space-y-5">
                   <input placeholder="Email or Number" className="w-full bg-black/5 p-5 rounded-2xl border border-white/10 outline-none font-bold" />
                   <input type="password" placeholder="Password" className="w-full bg-black/5 p-5 rounded-2xl border border-white/10 outline-none font-bold" />
                   <Button fullWidth onClick={() => {
                     const u = allUsers[0];
                     setCurrentUser(u);
                     localStorage.setItem('bfc_user', JSON.stringify(u));
                     setView('HOME');
                   }}>Access Club</Button>
                </div>
             </div>
          </div>
        )}

        {view === 'ADMIN' && (
          <div className="p-6">
            {!currentUser || currentUser.role === UserRole.CUSTOMER ? (
              <div className="flex items-center justify-center min-h-[50vh]">
                 <div className="w-full max-w-md p-12 rounded-[50px] border border-white/5 shadow-2xl space-y-8" style={{ backgroundColor: 'var(--card)' }}>
                    <h3 className="text-3xl font-black italic uppercase text-center">Command Access</h3>
                    <input type="password" placeholder="Admin Terminal Key" className="w-full bg-black/5 p-5 rounded-2xl border border-white/10 outline-none font-bold text-center" />
                    <Button fullWidth onClick={() => {
                       const admin: User = { id: 'A1', name: 'Elite Admin', username: 'admin', email: 'admin@bfc.com', phone: '01000', address: 'Command Center', gender: 'MALE', role: UserRole.ADMIN, loyaltyPoints: 999, tier: 'DIAMOND', createdAt: '2024' };
                       setCurrentUser(admin);
                       localStorage.setItem('bfc_user', JSON.stringify(admin));
                    }}>Unlock Terminal</Button>
                 </div>
              </div>
            ) : (
              <AdminPanel 
                user={currentUser} 
                users={allUsers} 
                menuItems={menuItems} 
                setMenuItems={setMenuItems} 
                orders={orders} 
                setOrders={setOrders} 
                onLogout={() => { setCurrentUser(null); localStorage.removeItem('bfc_user'); setView('HOME'); }} 
                onMenuUpdate={() => {}} 
                cms={null} 
                setCms={null} 
                theme={currentTheme}
                setTheme={setCurrentTheme}
              />
            )}
          </div>
        )}
      </main>

      <nav className="fixed bottom-0 inset-x-0 z-[100] h-24 bg-white/80 backdrop-blur-xl border-t flex justify-around items-center lg:hidden safe-bottom shadow-[0_-20px_50px_rgba(0,0,0,0.05)] px-6">
        <NavItem id="HOME" icon="fa-home-alt" label="Home" />
        <NavItem id="MENU" icon="fa-utensils" label="Menu" />
        <div className="relative -top-10">
           <button onClick={() => setIsChatOpen(true)} className="w-20 h-20 text-white rounded-[30px] flex items-center justify-center shadow-2xl shadow-red-600/40 border-4 border-white" style={{ backgroundColor: 'var(--primary)' }}><i className="fas fa-robot text-3xl"></i></button>
        </div>
        <NavItem id="CART" icon="fa-shopping-bag" label="Bag" />
        <NavItem id="ADMIN" icon="fa-shield-halved" label="Admin" />
      </nav>

      <ChatBot currentUser={currentUser} menuItems={menuItems} menuUpdates={[]} isOpen={isChatOpen} setIsOpen={setIsChatOpen} />
    </div>
  );
};

export default App;

export enum UserRole {
  ADMIN = 'ADMIN',
  MANAGER = 'MANAGER',
  STAFF = 'STAFF',
  CUSTOMER = 'CUSTOMER'
}

export enum OrderStatus {
  PENDING = 'PENDING',
  PREPARING = 'PREPARING',
  READY = 'READY',
  ON_THE_WAY = 'ON_THE_WAY',
  DELIVERED = 'DELIVERED',
  CANCELLED = 'CANCELLED'
}

export type LayoutPreset = 'BFC_CLASSIC' | 'ELITE_DARK' | 'MINIMAL_WHITE';

export interface ThemeConfig {
  bg: string;
  fg: string;
  primary: string;
  accent: string;
  card: string;
  border: string;
  font: string;
  shadow: string;
}

export interface User {
  id: string;
  name: string;
  username: string;
  email: string;
  phone: string;
  address: string;
  gender: 'MALE' | 'FEMALE' | 'OTHER';
  bio?: string;
  avatar?: string;
  role: UserRole;
  loyaltyPoints: number;
  tier: string;
  createdAt: string;
  vouchers?: string[];
}

export interface MenuItem {
  id: string;
  name: string;
  nameBn: string;
  description: string;
  price: number;
  category: string;
  image: string;
  stock: number;
  isPopular?: boolean;
}

export interface MenuUpdate {
  type: 'ADD' | 'PRICE_CHANGE' | 'AVAILABILITY' | 'PROMO';
  itemName: string;
  details: string;
  timestamp: Date;
}

export interface CartItem {
  item: MenuItem;
  qty: number;
}

export type PaymentMethod = 'BKASH' | 'NAGAD' | 'ROCKET' | 'UPAY' | 'CARD' | 'COD';

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  customerPhone: string;
  address: string;
  items: CartItem[];
  subtotal: number;
  deliveryCharge: number;
  total: number;
  status: OrderStatus;
  paymentMethod: PaymentMethod;
  transactionId: string;
  createdAt: string;
}

export type ViewState = 'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'PROFILE' | 'LOGIN' | 'SIGNUP' | 'PAYMENT' | 'RECEIPT';

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { MenuItem, UserRole, User, Order, CartItem, OrderStatus, MenuUpdate, ViewState, ThemeConfig, PaymentMethod } from './types';
import { MOCK_MENU, DEFAULT_THEMES } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [currentTheme, setCurrentTheme] = useState<ThemeConfig>(() => {
    const saved = localStorage.getItem('bfc_theme');
    return saved ? JSON.parse(saved) : DEFAULT_THEMES.BFC_CLASSIC;
  });

  const [allUsers, setAllUsers] = useState<User[]>(() => {
    const saved = localStorage.getItem('bfc_all_users');
    if (saved) return JSON.parse(saved);
    return [{ 
      id: 'U1', 
      name: 'Elite Member', 
      username: 'member', 
      email: 'user@bfc.com', 
      phone: '01712345678', 
      address: 'Dhanmondi, Dhaka', 
      gender: 'MALE', 
      role: UserRole.CUSTOMER, 
      loyaltyPoints: 150, 
      tier: 'GOLD', 
      createdAt: '2024-01-01' 
    }];
  });

  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('bfc_orders');
    return saved ? JSON.parse(saved) : [];
  });
  const [view, setView] = useState<ViewState>('HOME');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeCategory, setActiveCategory] = useState('ALL');
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod | null>(null);
  const [lastOrder, setLastOrder] = useState<Order | null>(null);

  // Payment Gateway States
  const [showGateway, setShowGateway] = useState(false);
  const [gatewayStep, setGatewayStep] = useState<'NUMBER' | 'OTP' | 'PIN' | 'SUCCESS'>('NUMBER');
  const [payMobile, setPayMobile] = useState('');
  const [payPin, setPayPin] = useState('');
  const [payCard, setPayCard] = useState({ num: '', exp: '', cvv: '' });
  const [isProcessing, setIsProcessing] = useState(false);

  const receiptRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('bfc_orders', JSON.stringify(orders));
  }, [orders]);

  useEffect(() => {
    localStorage.setItem('bfc_theme', JSON.stringify(currentTheme));
    const root = document.documentElement;
    root.style.setProperty('--primary', currentTheme.primary);
    root.style.setProperty('--bg', currentTheme.bg);
    root.style.setProperty('--fg', currentTheme.fg);
    root.style.setProperty('--card', currentTheme.card);
    root.style.setProperty('--border', currentTheme.border);
  }, [currentTheme]);

  const categories = useMemo(() => ['ALL', ...new Set(menuItems.map(i => i.category.toUpperCase()))], [menuItems]);
  const filteredMenu = useMemo(() => {
    return menuItems.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase()) || item.nameBn.includes(searchTerm);
      const matchesCategory = activeCategory === 'ALL' || item.category.toUpperCase() === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [menuItems, searchTerm, activeCategory]);

  const addToCart = (item: MenuItem) => {
    if (item.stock === 0) return;
    setCart(prev => {
      const existing = prev.find(i => i.item.id === item.id);
      if (existing) return prev.map(i => i.item.id === item.id ? { ...i, qty: i.qty + 1 } : i);
      return [...prev, { item, qty: 1 }];
    });
  };

  const updateCartQty = (itemId: string, delta: number) => {
    setCart(prev => prev.map(i => {
      if (i.item.id === itemId) {
        const newQty = Math.max(1, i.qty + delta);
        return { ...i, qty: newQty };
      }
      return i;
    }));
  };

  const calculateTotal = () => cart.reduce((acc, c) => acc + (c.item.price * c.qty), 0) + 50;

  const handleGatewayAction = () => {
    if (gatewayStep === 'NUMBER') {
      if (payMobile.length < 11) return alert("Enter valid mobile number");
      setGatewayStep('OTP');
    } else if (gatewayStep === 'OTP') {
      setGatewayStep('PIN');
    } else if (gatewayStep === 'PIN') {
      if (payPin.length < 4) return alert("Enter PIN");
      processPayment();
    }
  };

  const processPayment = () => {
    setIsProcessing(true);
    setTimeout(() => {
      const newOrder: Order = {
        id: `ORD-${Date.now().toString().slice(-6)}`,
        customerId: currentUser?.id || 'GUEST',
        customerName: currentUser?.name || 'Guest User',
        customerPhone: currentUser?.phone || 'Unknown',
        address: currentUser?.address || 'Pickup Point',
        items: [...cart],
        subtotal: calculateTotal() - 50,
        deliveryCharge: 50,
        total: calculateTotal(),
        status: OrderStatus.PENDING,
        paymentMethod: paymentMethod!,
        transactionId: `TRX-${Math.random().toString(36).toUpperCase().slice(2, 10)}`,
        createdAt: new Date().toISOString()
      };
      setOrders(prev => [newOrder, ...prev]);
      setLastOrder(newOrder);
      setCart([]);
      setIsProcessing(false);
      setShowGateway(false);
      setView('RECEIPT');
    }, 2500);
  };

  const downloadReceipt = async (format: 'PDF' | 'IMAGE') => {
    if (!receiptRef.current) return;
    const canvas = await html2canvas(receiptRef.current, { scale: 2 });
    if (format === 'IMAGE') {
      const link = document.createElement('a');
      link.download = `BFC-Receipt-${lastOrder?.id}.png`;
      link.href = canvas.toDataURL();
      link.click();
    } else {
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      const imgProps = pdf.getImageProperties(imgData);
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;
      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      pdf.save(`BFC-Receipt-${lastOrder?.id}.pdf`);
    }
  };

  const NavItem = ({ id, icon, label }: { id: ViewState, icon: string, label: string }) => (
    <button onClick={() => setView(id)} className={`flex flex-col items-center justify-center gap-1 w-full h-full transition-all ${view === id ? 'text-[#8b1e3f] scale-110' : 'text-gray-400 opacity-50'}`}>
      <i className={`fas ${icon} text-xl`}></i>
      <span className="text-[8px] font-black uppercase tracking-[2px]">{label}</span>
    </button>
  );

  return (
    <div className="min-h-screen flex flex-col" style={{ backgroundColor: 'var(--bg)', color: 'var(--fg)' }}>
      {/* Navbar */}
      <nav className="fixed top-0 inset-x-0 z-[100] glass px-6 h-20 flex justify-between items-center border-b">
        <div className="flex items-center gap-4 cursor-pointer" onClick={() => setView('HOME')}>
          <div className="w-12 h-12 rounded-2xl flex items-center justify-center text-white font-black text-2xl shadow-xl" style={{ backgroundColor: 'var(--primary)' }}>B</div>
          <h1 className="text-xl font-black italic uppercase leading-none tracking-tighter hidden sm:block">Bangla Food Club</h1>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setView('CART')} className="relative w-12 h-12 bg-gray-50/10 rounded-2xl flex items-center justify-center border border-white/10">
            <i className="fas fa-shopping-cart text-lg"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 text-[10px] text-white font-black w-6 h-6 rounded-full flex items-center justify-center bg-red-600 border-2 border-white">{cart.length}</span>}
          </button>
          {!currentUser ? (
            <Button size="sm" onClick={() => setView('LOGIN')}>Login</Button>
          ) : (
            <img onClick={() => setView('PROFILE')} src={currentUser.avatar || `https://ui-avatars.com/api/?name=${currentUser.name}&background=8b1e3f&color=fff`} className="w-12 h-12 rounded-2xl cursor-pointer border shadow-md" />
          )}
        </div>
      </nav>

      {/* Realistic Gateway Modal */}
      {showGateway && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-black/80 backdrop-blur-md p-6">
           <div className={`w-full max-w-sm rounded-[40px] overflow-hidden shadow-2xl animate-scale-in flex flex-col h-[550px] ${paymentMethod === 'BKASH' ? 'bg-[#D12053]' : paymentMethod === 'NAGAD' ? 'bg-[#F15922]' : paymentMethod === 'ROCKET' ? 'bg-[#8C3494]' : 'bg-[#00529B]'}`}>
              {/* Gateway Header */}
              <div className="p-6 flex justify-between items-center bg-white/10">
                 <img src={paymentMethod === 'BKASH' ? 'https://logowik.com/content/uploads/images/bkash-payment-icon1112.jpg' : 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR_R7-B7-S7H_e6_8z3W9l0N0z2P-O7n_P6eA&s'} className="h-10 object-contain rounded-lg" />
                 <button onClick={() => setShowGateway(false)} className="text-white opacity-50"><i className="fas fa-times"></i></button>
              </div>

              {isProcessing ? (
                <div className="flex-1 flex flex-col items-center justify-center text-white space-y-6">
                   <div className="w-16 h-16 border-4 border-white/30 border-t-white rounded-full animate-spin"></div>
                   <p className="font-black uppercase tracking-widest text-xs">Processing Strategic Payment...</p>
                </div>
              ) : (
                <div className="flex-1 p-8 flex flex-col justify-center space-y-8 bg-white/95 text-gray-800">
                   <div className="text-center">
                      <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest mb-1">Payable Amount</p>
                      <h4 className="text-4xl font-black">৳{calculateTotal()}</h4>
                   </div>

                   {gatewayStep === 'NUMBER' && (
                     <div className="space-y-4">
                        <label className="text-[10px] font-black uppercase tracking-widest text-gray-400">Your {paymentMethod} Account Number</label>
                        <input value={payMobile} onChange={e => setPayMobile(e.target.value)} placeholder="e.g. 017XXXXXXXX" className="w-full p-5 rounded-2xl bg-gray-100 border border-transparent focus:border-red-600 outline-none font-bold text-lg" />
                     </div>
                   )}

                   {gatewayStep === 'OTP' && (
                     <div className="space-y-4">
                        <label className="text-[10px] font-black uppercase tracking-widest text-gray-400">Enter OTP sent to {payMobile}</label>
                        <input placeholder="6-digit code" maxLength={6} className="w-full p-5 rounded-2xl bg-gray-100 border border-transparent focus:border-red-600 outline-none font-black text-2xl tracking-[10px] text-center" />
                     </div>
                   )}

                   {gatewayStep === 'PIN' && (
                     <div className="space-y-4">
                        <label className="text-[10px] font-black uppercase tracking-widest text-gray-400">Enter Your Secret PIN</label>
                        <input type="password" value={payPin} onChange={e => setPayPin(e.target.value)} placeholder="****" maxLength={4} className="w-full p-5 rounded-2xl bg-gray-100 border border-transparent focus:border-red-600 outline-none font-black text-2xl tracking-[10px] text-center" />
                     </div>
                   )}

                   <div className="pt-4 space-y-3">
                      <button onClick={handleGatewayAction} className={`w-full py-5 rounded-2xl text-white font-black uppercase tracking-[4px] shadow-xl ${paymentMethod === 'BKASH' ? 'bg-[#D12053]' : paymentMethod === 'NAGAD' ? 'bg-[#F15922]' : 'bg-[#00529B]'}`}>
                        {gatewayStep === 'PIN' ? 'Confirm Payment' : 'Proceed'}
                      </button>
                      <p className="text-[8px] text-center font-bold text-gray-400 uppercase">Secure Transaction by BFC Elite Network</p>
                   </div>
                </div>
              )}
           </div>
        </div>
      )}

      <main className="flex-1 pt-20 pb-32">
        {view === 'HOME' && (
          <div className="reveal space-y-20 p-6 lg:p-24">
             <div className="grid lg:grid-cols-2 gap-12 items-center">
                <div className="space-y-8 text-center lg:text-left">
                   <h2 className="text-6xl lg:text-9xl font-black italic uppercase leading-[0.85] tracking-tighter">খাঁটি স্বাদের <br/> <span style={{ color: 'var(--primary)' }}>আসল মেজবানি।</span></h2>
                   <p className="text-lg opacity-60 max-w-lg mx-auto lg:mx-0">Elite Bangladeshi taste delivered to your command center.</p>
                   <Button size="lg" onClick={() => setView('MENU')}>View Manifest</Button>
                </div>
                <img src="https://images.unsplash.com/photo-1601050690597-df0568f70950?q=80&w=1000" className="rounded-[60px] shadow-2xl h-[500px] object-cover" />
             </div>
          </div>
        )}

        {view === 'MENU' && (
          <div className="reveal max-w-7xl mx-auto px-6 space-y-12 pt-10">
             <div className="flex flex-col lg:flex-row justify-between items-end gap-10">
                <h2 className="text-6xl font-black italic uppercase tracking-tighter">Manifest</h2>
                <div className="category-bar glass rounded-3xl p-3 flex gap-3 overflow-x-auto no-scrollbar shadow-xl border border-white/5">
                  {categories.map(cat => (
                    <button key={cat} onClick={() => setActiveCategory(cat)} className={`px-10 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeCategory === cat ? 'bg-red-600 text-white shadow-xl' : 'text-gray-500 hover:bg-black/5'}`}>{cat}</button>
                  ))}
                </div>
             </div>
             <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-10">
                {filteredMenu.map(item => (
                  <div key={item.id} className="rounded-[50px] overflow-hidden border border-white/5 shadow-xl group hover:-translate-y-2 transition-all p-5 flex flex-col" style={{ backgroundColor: 'var(--card)' }}>
                     <img src={item.image} className="h-60 w-full object-cover rounded-[40px] mb-5" />
                     <h4 className="text-2xl font-black italic uppercase">{item.nameBn}</h4>
                     <p className="text-xs text-gray-400 font-bold uppercase mb-4">{item.name}</p>
                     <div className="flex justify-between items-center mt-auto">
                        <span className="text-xl font-black" style={{ color: 'var(--primary)' }}>৳{item.price}</span>
                        <Button size="sm" onClick={() => addToCart(item)} disabled={item.stock === 0}>{item.stock > 0 ? 'Deploy' : 'Sold Out'}</Button>
                     </div>
                  </div>
                ))}
             </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="reveal max-w-4xl mx-auto px-6 pt-10 space-y-10">
             <h2 className="text-5xl font-black italic uppercase tracking-tighter">Unit Bag</h2>
             {cart.length > 0 ? (
               <div className="grid lg:grid-cols-3 gap-10">
                 <div className="lg:col-span-2 space-y-6">
                   <div className="bg-white rounded-[40px] p-8 border shadow-xl space-y-6">
                     {cart.map(c => (
                       <div key={c.item.id} className="flex items-center justify-between py-4 border-b last:border-0">
                         <div className="flex items-center gap-6">
                           <img src={c.item.image} className="w-20 h-20 rounded-2xl object-cover" />
                           <div>
                             <h4 className="text-xl font-black uppercase italic">{c.item.nameBn}</h4>
                             <p className="text-sm font-bold opacity-40">৳{c.item.price} ea</p>
                           </div>
                         </div>
                         <div className="flex items-center gap-6">
                           <div className="flex items-center bg-gray-100 rounded-xl px-4 py-2">
                             <button onClick={() => updateCartQty(c.item.id, -1)} className="px-2 text-xl font-black">-</button>
                             <span className="px-4 font-black">{c.qty}</span>
                             <button onClick={() => updateCartQty(c.item.id, 1)} className="px-2 text-xl font-black">+</button>
                           </div>
                         </div>
                       </div>
                     ))}
                   </div>
                 </div>
                 <div className="space-y-6">
                    <div className="bg-white rounded-[40px] p-10 border shadow-2xl space-y-6">
                       <h3 className="text-2xl font-black uppercase italic tracking-tighter">Order Intel</h3>
                       <div className="space-y-4 font-bold opacity-60">
                          <div className="flex justify-between"><span>Subtotal</span><span>৳{calculateTotal() - 50}</span></div>
                          <div className="flex justify-between"><span>Delivery</span><span>৳50</span></div>
                       </div>
                       <div className="pt-6 border-t flex justify-between items-center text-3xl font-black">
                          <span>Total</span>
                          <span className="text-red-600">৳{calculateTotal()}</span>
                       </div>
                       <Button fullWidth size="lg" onClick={() => setView('PAYMENT')}>Initiate Checkout</Button>
                    </div>
                 </div>
               </div>
             ) : (
               <div className="py-40 text-center opacity-20"><i className="fas fa-shopping-bag text-9xl"></i></div>
             )}
          </div>
        )}

        {view === 'PAYMENT' && (
          <div className="reveal max-w-4xl mx-auto px-6 pt-10 space-y-10">
             <h2 className="text-4xl font-black italic uppercase tracking-tighter text-center">Tactical Payment</h2>
             <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
                {[
                  { id: 'BKASH', label: 'bKash', img: 'https://logowik.com/content/uploads/images/bkash-payment-icon1112.jpg', color: 'hover:border-[#D12053]' },
                  { id: 'NAGAD', label: 'Nagad', img: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR_R7-B7-S7H_e6_8z3W9l0N0z2P-O7n_P6eA&s', color: 'hover:border-[#F15922]' },
                  { id: 'ROCKET', label: 'Rocket', img: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcS8XhH7QG9O8hF09m9Q8o8l7k8_O9p0k8l7k8&s', color: 'hover:border-[#8C3494]' },
                  { id: 'UPAY', label: 'Upay', img: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcT7T9T7T9T7T9T7T9T7T9T7T9T7T9T7T9T7T9&s', color: 'hover:border-[#00529B]' },
                  { id: 'CARD', label: 'Credit Card', img: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcS4U9u9X4_X4_X4_X4_X4_X4_X4_X4_X4_X&s', color: 'hover:border-blue-500' },
                  { id: 'COD', label: 'Cash on Delivery', img: 'https://img.icons8.com/color/512/cash-on-delivery.png', color: 'hover:border-emerald-500' }
                ].map(gate => (
                  <button key={gate.id} onClick={() => {
                    setPaymentMethod(gate.id as any);
                    if (gate.id === 'COD') processPayment();
                    else {
                      setGatewayStep('NUMBER');
                      setShowGateway(true);
                    }
                  }} className={`bg-white p-8 rounded-[40px] border-4 border-transparent shadow-xl transition-all flex flex-col items-center gap-6 group hover:scale-[1.05] ${gate.color}`}>
                     <img src={gate.img} className="h-16 object-contain rounded-xl grayscale group-hover:grayscale-0 transition-all" />
                     <span className="text-sm font-black uppercase tracking-widest">{gate.label}</span>
                  </button>
                ))}
             </div>
          </div>
        )}

        {view === 'RECEIPT' && lastOrder && (
          <div className="reveal max-w-2xl mx-auto px-6 pt-10 space-y-10">
             <div className="text-center space-y-4">
                <div className="w-20 h-20 bg-emerald-500 rounded-full flex items-center justify-center mx-auto text-white text-3xl shadow-xl animate-bounce">
                  <i className="fas fa-check"></i>
                </div>
                <h2 className="text-4xl font-black italic uppercase">Deployment Successful</h2>
                <p className="text-xs font-black opacity-40 uppercase tracking-[4px]">Thank you for your strategy, Commander.</p>
             </div>

             <div ref={receiptRef} className="bg-white rounded-[50px] p-12 shadow-2xl space-y-8 border-t-[16px] border-red-600 relative">
                <div className="flex justify-between items-start border-b pb-8">
                   <div>
                      <h3 className="text-3xl font-black italic uppercase text-red-600">BFC Elite Receipt</h3>
                      <p className="text-xs font-bold opacity-40 mt-1">Transaction ID: {lastOrder.transactionId}</p>
                   </div>
                   <div className="text-right">
                      <p className="text-xs font-black uppercase tracking-widest opacity-30">Status</p>
                      <span className="text-emerald-500 font-black uppercase text-xs">Paid via {lastOrder.paymentMethod}</span>
                   </div>
                </div>

                <div className="space-y-4">
                   {lastOrder.items.map((c, i) => (
                     <div key={i} className="flex justify-between items-center py-2">
                        <div>
                           <p className="font-black text-lg uppercase italic">{c.item.nameBn}</p>
                           <p className="text-[10px] font-bold opacity-40 uppercase">Qty: {c.qty} | Unit: ৳{c.item.price}</p>
                        </div>
                        <span className="text-xl font-black">৳{c.item.price * c.qty}</span>
                     </div>
                   ))}
                   <div className="pt-6 border-t space-y-2 opacity-60 font-bold">
                      <div className="flex justify-between"><span>Subtotal</span><span>৳{lastOrder.subtotal}</span></div>
                      <div className="flex justify-between"><span>Delivery Ops</span><span>৳{lastOrder.deliveryCharge}</span></div>
                   </div>
                   <div className="pt-8 border-t-2 border-dashed flex justify-between items-center">
                      <span className="text-2xl font-black uppercase italic">Total Dispatched</span>
                      <span className="text-4xl font-black text-red-600">৳{lastOrder.total}</span>
                   </div>
                </div>

                <div className="bg-gray-50 p-6 rounded-3xl text-center space-y-1">
                   <p className="text-[8px] font-black opacity-30 uppercase tracking-[4px]">Order Date</p>
                   <p className="font-bold text-sm">{new Date(lastOrder.createdAt).toLocaleString()}</p>
                </div>
