import { MenuItem, UserRole, User, Order, CartItem, OrderStatus, MenuUpdate, ViewState, ThemeConfig, PaymentMethod } from './types';
import { MOCK_MENU, DEFAULT_THEMES } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [currentTheme, setCurrentTheme] = useState<ThemeConfig>(() => {
    const saved = localStorage.getItem('bfc_theme');
    return saved ? JSON.parse(saved) : DEFAULT_THEMES.BFC_CLASSIC;
  });

  const [allUsers, setAllUsers] = useState<User[]>(() => {
    const saved = localStorage.getItem('bfc_all_users');
    if (saved) return JSON.parse(saved);
    return [{ 
      id: 'U1', 
      name: 'Elite Member', 
      username: 'member', 
      email: 'user@bfc.com', 
      phone: '01712345678', 
      address: 'Dhanmondi, Dhaka', 
      gender: 'MALE', 
      role: UserRole.CUSTOMER, 
      loyaltyPoints: 150, 
      tier: 'GOLD', 
      createdAt: '2024-01-01' 
    }];
  });

  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('bfc_orders');
    return saved ? JSON.parse(saved) : [];
  });
  const [view, setView] = useState<ViewState>('HOME');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeCategory, setActiveCategory] = useState('ALL');
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod | null>(null);
  const [lastOrder, setLastOrder] = useState<Order | null>(null);

  const [showGateway, setShowGateway] = useState(false);
  const [gatewayStep, setGatewayStep] = useState<'NUMBER' | 'OTP' | 'PIN'>('NUMBER');
  const [payMobile, setPayMobile] = useState('');
  const [payPin, setPayPin] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);

  const receiptRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('bfc_orders', JSON.stringify(orders));
  }, [orders]);

  useEffect(() => {
    localStorage.setItem('bfc_theme', JSON.stringify(currentTheme));
    const root = document.documentElement;
    root.style.setProperty('--primary', currentTheme.primary);
    root.style.setProperty('--bg', currentTheme.bg);
    root.style.setProperty('--fg', currentTheme.fg);
    root.style.setProperty('--card', currentTheme.card);
    root.style.setProperty('--border', currentTheme.border);
  }, [currentTheme]);

  const categories = useMemo(() => ['ALL', ...new Set(menuItems.map(i => i.category.toUpperCase()))], [menuItems]);
  const filteredMenu = useMemo(() => {
    return menuItems.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase()) || item.nameBn.includes(searchTerm);
      const matchesCategory = activeCategory === 'ALL' || item.category.toUpperCase() === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [menuItems, searchTerm, activeCategory]);

  const addToCart = (item: MenuItem, qty: number = 1) => {
    if (item.stock === 0) return;
    setCart(prev => {
      const existing = prev.find(i => i.item.id === item.id);
      if (existing) return prev.map(i => i.item.id === item.id ? { ...i, qty: i.qty + qty } : i);
      return [...prev, { item, qty }];
    });
  };

  const handleVoiceAddToCart = (itemName: string, quantity: number) => {
    const item = menuItems.find(m => m.name.toLowerCase().includes(itemName.toLowerCase()) || m.nameBn.includes(itemName));
    if (item) {
      addToCart(item, quantity);
      alert(`${quantity}x ${item.nameBn} added to cart via voice.`);
    }
  };

  const updateCartQty = (itemId: string, delta: number) => {
    setCart(prev => prev.map(i => {
      if (i.item.id === itemId) {
        const newQty = Math.max(1, i.qty + delta);
        return { ...i, qty: newQty };
      }
      return i;
    }));
  };

  const calculateTotal = () => cart.reduce((acc, c) => acc + (c.item.price * c.qty), 0) + 50;

  const handleGatewayAction = () => {
    if (gatewayStep === 'NUMBER') {
      if (payMobile.length < 11) return alert("Enter valid mobile number");
      setGatewayStep('OTP');
    } else if (gatewayStep === 'OTP') {
      setGatewayStep('PIN');
    } else if (gatewayStep === 'PIN') {
      if (payPin.length < 4) return alert("Enter PIN");
      processPayment();
    }
  };

  const processPayment = () => {
    setIsProcessing(true);
    setTimeout(() => {
      const newOrder: Order = {
        id: `ORD-${Date.now().toString().slice(-6)}`,
        customerId: currentUser?.id || 'GUEST',
        customerName: currentUser?.name || 'Guest User',
        customerPhone: currentUser?.phone || 'Unknown',
        address: currentUser?.address || 'Pickup Point',
        items: [...cart],
        subtotal: calculateTotal() - 50,
        deliveryCharge: 50,
        total: calculateTotal(),
        status: OrderStatus.PENDING,
        paymentMethod: paymentMethod!,
        transactionId: `TRX-${Math.random().toString(36).toUpperCase().slice(2, 10)}`,
        createdAt: new Date().toISOString()
      };
      setOrders(prev => [newOrder, ...prev]);
      setLastOrder(newOrder);
      setCart([]);
      setIsProcessing(false);
      setShowGateway(false);
      setView('RECEIPT');
    }, 2500);
  };

  const downloadReceipt = async (format: 'PDF' | 'IMAGE') => {
    if (!receiptRef.current) return;
    const canvas = await html2canvas(receiptRef.current, { scale: 2 });
    if (format === 'IMAGE') {
      const link = document.createElement('a');
      link.download = `BFC-Receipt-${lastOrder?.id}.png`;
      link.href = canvas.toDataURL();
      link.click();
    } else {
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      const imgProps = pdf.getImageProperties(imgData);
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;
      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      pdf.save(`BFC-Receipt-${lastOrder?.id}.pdf`);
    }
  };

  const NavItem = ({ id, icon, label }: { id: ViewState, icon: string, label: string }) => (
    <button onClick={() => setView(id)} className={`flex flex-col items-center justify-center gap-1 w-full h-full transition-all ${view === id ? 'scale-110' : 'text-gray-400 opacity-50'}`} style={{ color: view === id ? currentTheme.primary : '' }}>
      <i className={`fas ${icon} text-xl`}></i>
      <span className="text-[8px] font-black uppercase tracking-[2px]">{label}</span>
    </button>
  );

  return (
    <div className="min-h-screen flex flex-col" style={{ backgroundColor: currentTheme.bg, color: currentTheme.fg }}>
      {/* Navbar */}
      <nav className="fixed top-0 inset-x-0 z-[100] glass px-6 h-20 flex justify-between items-center border-b">
        <div className="flex items-center gap-4 cursor-pointer" onClick={() => setView('HOME')}>
          <div className="w-12 h-12 rounded-2xl flex items-center justify-center text-white font-black text-2xl shadow-xl" style={{ backgroundColor: currentTheme.primary }}>B</div>
          <h1 className="text-xl font-black italic uppercase leading-none tracking-tighter hidden sm:block">Bangla Food Club</h1>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setView('CART')} className="relative w-12 h-12 bg-gray-50/10 rounded-2xl flex items-center justify-center border border-white/10">
            <i className="fas fa-shopping-cart text-lg"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 text-[10px] text-white font-black w-6 h-6 rounded-full flex items-center justify-center bg-red-600 border-2 border-white">{cart.length}</span>}
          </button>
          {!currentUser ? (
            <Button size="sm" onClick={() => setView('LOGIN')}>Login</Button>
          ) : (
            <img onClick={() => setView('PROFILE')} src={currentUser.avatar || `https://ui-avatars.com/api/?name=${currentUser.name}&background=8b1e3f&color=fff`} className="w-12 h-12 rounded-2xl cursor-pointer border shadow-md" />
          )}
        </div>
      </nav>

      {showGateway && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-black/80 backdrop-blur-md p-6">
           <div className={`w-full max-w-sm rounded-[40px] overflow-hidden shadow-2xl animate-scale-in flex flex-col h-[550px] ${paymentMethod === 'BKASH' ? 'bg-[#D12053]' : paymentMethod === 'NAGAD' ? 'bg-[#F15922]' : 'bg-[#00529B]'}`}>
              <div className="p-6 flex justify-between items-center bg-white/10">
                 <h4 className="text-white font-black uppercase italic tracking-widest">{paymentMethod} Gateway</h4>
                 <button onClick={() => setShowGateway(false)} className="text-white opacity-50"><i className="fas fa-times"></i></button>
              </div>

              {isProcessing ? (
                <div className="flex-1 flex flex-col items-center justify-center text-white space-y-6">
                   <div className="w-16 h-16 border-4 border-white/30 border-t-white rounded-full animate-spin"></div>
                   <p className="font-black uppercase tracking-widest text-xs">Processing Strategic Payment...</p>
                </div>
              ) : (
                <div className="flex-1 p-8 flex flex-col justify-center space-y-8 bg-white/95 text-gray-800">
                   <div className="text-center">
                      <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest mb-1">Payable Amount</p>
                      <h4 className="text-4xl font-black">৳{calculateTotal()}</h4>
                   </div>

                   {gatewayStep === 'NUMBER' && (
                     <div className="space-y-4">
                        <label className="text-[10px] font-black uppercase tracking-widest text-gray-400">Account Number</label>
                        <input value={payMobile} onChange={e => setPayMobile(e.target.value)} placeholder="017XXXXXXXX" className="w-full p-5 rounded-2xl bg-gray-100 border border-transparent focus:border-red-600 outline-none font-bold text-lg" />
                     </div>
                   )}

                   {gatewayStep === 'OTP' && (
                     <div className="space-y-4 text-center">
                        <label className="text-[10px] font-black uppercase tracking-widest text-gray-400">Enter OTP</label>
                        <input placeholder="000000" maxLength={6} className="w-full p-5 rounded-2xl bg-gray-100 text-center font-black text-2xl tracking-[10px]" />
                     </div>
                   )}

                   {gatewayStep === 'PIN' && (
                     <div className="space-y-4 text-center">
                        <label className="text-[10px] font-black uppercase tracking-widest text-gray-400">Enter PIN</label>
                        <input type="password" value={payPin} onChange={e => setPayPin(e.target.value)} placeholder="****" maxLength={4} className="w-full p-5 rounded-2xl bg-gray-100 text-center font-black text-2xl tracking-[10px]" />
                     </div>
                   )}

                   <div className="pt-4">
                      <button onClick={handleGatewayAction} className="w-full py-5 rounded-2xl text-white font-black uppercase tracking-[4px] shadow-xl" style={{ backgroundColor: paymentMethod === 'BKASH' ? '#D12053' : '#F15922' }}>
                        {gatewayStep === 'PIN' ? 'Confirm Payment' : 'Proceed'}
                      </button>
                   </div>
                </div>
              )}
           </div>
        </div>
      )}

      <main className="flex-1 pt-20 pb-32">
        {view === 'HOME' && (
          <div className="reveal space-y-20 p-6 lg:p-24 text-center lg:text-left">
             <div className="grid lg:grid-cols-2 gap-12 items-center">
                <div className="space-y-8">
                   <h2 className="text-6xl lg:text-9xl font-black italic uppercase leading-[0.85] tracking-tighter">খাঁটি স্বাদের <br/> <span style={{ color: currentTheme.primary }}>আসল মেজবানি।</span></h2>
                   <p className="text-lg opacity-60 max-w-lg mx-auto lg:mx-0">Elite Bangladeshi taste delivered to your command center.</p>
                   <Button size="lg" onClick={() => setView('MENU')}>View Manifest</Button>
                </div>
                <img src="https://images.unsplash.com/photo-1601050690597-df0568f70950?q=80&w=1000" className="rounded-[60px] shadow-2xl h-[500px] object-cover" />
             </div>
          </div>
        )}

        {view === 'MENU' && (
          <div className="reveal max-w-7xl mx-auto px-6 space-y-12 pt-10">
             <div className="flex flex-col lg:flex-row justify-between items-end gap-10">
                <h2 className="text-6xl font-black italic uppercase tracking-tighter">Manifest</h2>
                <div className="flex gap-3 overflow-x-auto no-scrollbar pb-2">
                  {categories.map(cat => (
                    <button key={cat} onClick={() => setActiveCategory(cat)} className={`px-10 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeCategory === cat ? 'bg-red-600 text-white shadow-xl' : 'text-gray-500 hover:bg-black/5'}`}>{cat}</button>
                  ))}
                </div>
             </div>
             <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-10">
                {filteredMenu.map(item => (
                  <div key={item.id} className="rounded-[50px] overflow-hidden border border-white/5 shadow-xl p-5 flex flex-col bg-white" style={{ backgroundColor: currentTheme.card }}>
                     <img src={item.image} className="h-60 w-full object-cover rounded-[40px] mb-5" />
                     <h4 className="text-2xl font-black italic uppercase">{item.nameBn}</h4>
                     <p className="text-xs text-gray-400 font-bold uppercase mb-4">{item.name}</p>
                     <div className="flex justify-between items-center mt-auto">
                        <span className="text-xl font-black" style={{ color: currentTheme.primary }}>৳{item.price}</span>
                        <Button size="sm" onClick={() => addToCart(item)} disabled={item.stock === 0}>{item.stock > 0 ? 'Deploy' : 'Sold Out'}</Button>
                     </div>
                  </div>
                ))}
             </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="reveal max-w-4xl mx-auto px-6 pt-10 space-y-10">
             <h2 className="text-5xl font-black italic uppercase tracking-tighter">Unit Bag</h2>
             {cart.length > 0 ? (
               <div className="grid lg:grid-cols-3 gap-10">
                 <div className="lg:col-span-2 space-y-6">
                   <div className="bg-white rounded-[40px] p-8 border shadow-xl space-y-6">
                     {cart.map(c => (
                       <div key={c.item.id} className="flex items-center justify-between py-4 border-b last:border-0">
                         <div className="flex items-center gap-6">
                           <img src={c.item.image} className="w-20 h-20 rounded-2xl object-cover" />
                           <div>
                             <h4 className="text-xl font-black uppercase italic">{c.item.nameBn}</h4>
                             <p className="text-sm font-bold opacity-40">৳{c.item.price}</p>
                           </div>
                         </div>
                         <div className="flex items-center bg-gray-100 rounded-xl px-4 py-2">
                           <button onClick={() => updateCartQty(c.item.id, -1)} className="px-2 text-xl font-black">-</button>
                           <span className="px-4 font-black">{c.qty}</span>
                           <button onClick={() => updateCartQty(c.item.id, 1)} className="px-2 text-xl font-black">+</button>
                         </div>
                       </div>
                     ))}
                   </div>
                 </div>
                 <div className="bg-white rounded-[40px] p-10 border shadow-2xl space-y-6">
                    <h3 className="text-2xl font-black uppercase italic tracking-tighter">Summary</h3>
                    <div className="pt-6 border-t flex justify-between items-center text-3xl font-black">
                       <span>Total</span>
                       <span className="text-red-600">৳{calculateTotal()}</span>
                    </div>
                    <Button fullWidth size="lg" onClick={() => setView('PAYMENT')}>Checkout</Button>
                 </div>
               </div>
             ) : (
               <div className="py-40 text-center opacity-20"><i className="fas fa-shopping-bag text-9xl"></i></div>
             )}
          </div>
        )}

        {view === 'PAYMENT' && (
          <div className="reveal max-w-4xl mx-auto px-6 pt-10 space-y-10">
             <h2 className="text-4xl font-black italic uppercase tracking-tighter text-center">Payment Methods</h2>
             <div className="grid md:grid-cols-3 gap-6">
                {['BKASH', 'NAGAD', 'ROCKET', 'UPAY', 'CARD', 'COD'].map(id => (
                  <button key={id} onClick={() => {
                    setPaymentMethod(id as any);
                    if (id === 'COD') processPayment();
                    else { setGatewayStep('NUMBER'); setShowGateway(true); }
                  }} className="bg-white p-8 rounded-[40px] shadow-xl transition-all flex flex-col items-center gap-6 hover:scale-105 border-4 border-transparent hover:border-red-600">
                     <i className={`fas ${id === 'CARD' ? 'fa-credit-card' : id === 'COD' ? 'fa-truck' : 'fa-mobile-screen'} text-4xl text-red-600`}></i>
                     <span className="text-sm font-black uppercase tracking-widest">{id}</span>
                  </button>
                ))}
             </div>
          </div>
        )}

        {view === 'RECEIPT' && lastOrder && (
          <div className="reveal max-w-2xl mx-auto px-6 pt-10 space-y-10">
             <div ref={receiptRef} className="bg-white rounded-[50px] p-12 shadow-2xl space-y-8 border-t-[16px] border-red-600">
                <h3 className="text-3xl font-black italic uppercase text-red-600 text-center">BFC Elite Invoice</h3>
                <div className="space-y-4">
                   {lastOrder.items.map((c, i) => (
                     <div key={i} className="flex justify-between items-center py-2">
                        <span className="font-black text-lg">{c.item.nameBn} x {c.qty}</span>
                        <span className="text-xl font-black">৳{c.item.price * c.qty}</span>
                     </div>
                   ))}
                   <div className="pt-8 border-t-2 border-dashed flex justify-between items-center">
                      <span className="text-2xl font-black italic">Total</span>
                      <span className="text-4xl font-black text-red-600">৳{lastOrder.total}</span>
                   </div>
                </div>
             </div>
             <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                <Button variant="outline" size="sm" onClick={() => downloadReceipt('PDF')}>PDF</Button>
                <Button variant="outline" size="sm" onClick={() => downloadReceipt('IMAGE')}>Image</Button>
                <Button size="sm" onClick={() => setView('HOME')}>Done</Button>
             </div>
          </div>
        )}

        {view === 'ADMIN' && currentUser?.role === UserRole.ADMIN && (
          <div className="p-6">
            <AdminPanel 
              user={currentUser} 
              users={allUsers} 
              menuItems={menuItems} 
              setMenuItems={setMenuItems} 
              orders={orders} 
              setOrders={setOrders} 
              onLogout={() => { setCurrentUser(null); localStorage.removeItem('bfc_user'); setView('HOME'); }} 
              onMenuUpdate={() => {}} 
              theme={currentTheme}
              setTheme={setCurrentTheme}
            />
          </div>
        )}
      </main>

      <nav className="fixed bottom-0 inset-x-0 z-[100] h-24 bg-white/80 backdrop-blur-xl border-t flex justify-around items-center lg:hidden safe-bottom px-6">
        <NavItem id="HOME" icon="fa-home-alt" label="Home" />
        <NavItem id="MENU" icon="fa-utensils" label="Menu" />
        <div className="relative -top-10">
           <button onClick={() => setIsChatOpen(true)} className="w-20 h-20 text-white rounded-[30px] flex items-center justify-center shadow-2xl bg-red-600 border-4 border-white"><i className="fas fa-robot text-3xl"></i></button>
        </div>
        <NavItem id="CART" icon="fa-shopping-bag" label="Bag" />
        <NavItem id="ADMIN" icon="fa-shield-halved" label="Admin" />
      </nav>

      <ChatBot currentUser={currentUser} menuItems={menuItems} menuUpdates={[]} isOpen={isChatOpen} setIsOpen={setIsChatOpen} onAddToCart={handleVoiceAddToCart} />
    </div>
  );
};

export default App;

import { MenuItem, Order, OrderStatus, User, MenuUpdate } from '../types';
import { MOCK_MENU } from '../constants';

/** 
 * HEADLESS API ENGINE
 * Simulates a central server/database architecture
 */
const DB_KEYS = {
  MENU: 'bfc_headless_menu',
  ORDERS: 'bfc_headless_orders',
  USERS: 'bfc_headless_users',
  UPDATES: 'bfc_headless_updates',
  ADMIN_TOKEN: 'bfc_admin_secret_token'
};

// Initialize Database if empty
if (!localStorage.getItem(DB_KEYS.MENU)) {
  localStorage.setItem(DB_KEYS.MENU, JSON.stringify(MOCK_MENU));
}

export const API = {
  // --- MENU OPERATIONS ---
  async getMenu(): Promise<MenuItem[]> {
    const data = localStorage.getItem(DB_KEYS.MENU);
    return data ? JSON.parse(data) : [];
  },

  async updateMenuItem(item: MenuItem): Promise<void> {
    const menu = await this.getMenu();
    const updated = menu.map(m => m.id === item.id ? item : m);
    localStorage.setItem(DB_KEYS.MENU, JSON.stringify(updated));
    this.broadcast('MENU_UPDATED');
  },

  // --- ORDER OPERATIONS ---
  async getOrders(): Promise<Order[]> {
    const data = localStorage.getItem(DB_KEYS.ORDERS);
    return data ? JSON.parse(data) : [];
  },

  async placeOrder(order: Order): Promise<void> {
    const orders = await this.getOrders();
    localStorage.setItem(DB_KEYS.ORDERS, JSON.stringify([order, ...orders]));

    // Simulate real-time push to Admin
    this.broadcast('NEW_ORDER_RECEIVED', order);
  },

  async updateOrderStatus(orderId: string, status: OrderStatus): Promise<void> {
    const orders = await this.getOrders();
    const updated = orders.map(o => o.id === orderId ? { ...o, status } : o);
    localStorage.setItem(DB_KEYS.ORDERS, JSON.stringify(updated));
    this.broadcast('ORDER_STATUS_CHANGED', { orderId, status });
  },

  // --- SECURITY / AUTH ---
  async validateAdmin(token: string): Promise<boolean> {
    // Secret hardcoded token for the terminal: "BFC-ELITE-2025"
    return token === "BFC-ELITE-2025";
  },

  // --- EVENT BROADCASTER (Simulates WebSockets) ---
  broadcast(type: string, payload?: any) {
    const event = new CustomEvent('BFC_GATEWAY_EVENT', { detail: { type, payload } });
    window.dispatchEvent(event);
  },

  subscribe(callback: (event: any) => void) {
    window.addEventListener('BFC_GATEWAY_EVENT', (e: any) => callback(e.detail));
  }
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { MenuItem, UserRole, User, Order, CartItem, OrderStatus, ViewState, ThemeConfig, PaymentMethod } from './types';
import { DEFAULT_THEMES } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';
import { API } from './services/api';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';

const App: React.FC = () => {
  // Central State Managed via API
  const [menuItems, setMenuItems] = useState<MenuItem[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [view, setView] = useState<ViewState>('HOME');
  const [isAdminTerminal, setIsAdminTerminal] = useState(false);

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [currentTheme, setCurrentTheme] = useState<ThemeConfig>(() => {
    const saved = localStorage.getItem('bfc_theme');
    return saved ? JSON.parse(saved) : DEFAULT_THEMES.BFC_CLASSIC;
  });

  // UI States
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeCategory, setActiveCategory] = useState('ALL');
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod | null>(null);
  const [lastOrder, setLastOrder] = useState<Order | null>(null);
  const [showGateway, setShowGateway] = useState(false);
  const [gatewayStep, setGatewayStep] = useState<'NUMBER' | 'OTP' | 'PIN'>('NUMBER');
  const [payMobile, setPayMobile] = useState('');
  const [payPin, setPayPin] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);

  const receiptRef = useRef<HTMLDivElement>(null);

  // Sync Data on Mount & Real-time Subscriptions
  useEffect(() => {
    const sync = async () => {
      setMenuItems(await API.getMenu());
      setOrders(await API.getOrders());
    };
    sync();

    // Subscribe to "Headless" Real-time Updates
    API.subscribe((event) => {
      if (event.type === 'MENU_UPDATED') sync();
      if (event.type === 'NEW_ORDER_RECEIVED') {
        sync();
        if (isAdminTerminal) {
          const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
          audio.play().catch(() => {});
        }
      }
    });
  }, [isAdminTerminal]);

  useEffect(() => {
    localStorage.setItem('bfc_theme', JSON.stringify(currentTheme));
    const root = document.documentElement;
    root.style.setProperty('--primary', currentTheme.primary);
    root.style.setProperty('--bg', currentTheme.bg);
    root.style.setProperty('--fg', currentTheme.fg);
    root.style.setProperty('--card', currentTheme.card);
    root.style.setProperty('--border', currentTheme.border);
  }, [currentTheme]);

  // Derived Values
  const categories = useMemo(() => ['ALL', ...new Set(menuItems.map(i => i.category.toUpperCase()))], [menuItems]);
  const filteredMenu = useMemo(() => {
    return menuItems.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase()) || item.nameBn.includes(searchTerm);
      const matchesCategory = activeCategory === 'ALL' || item.category.toUpperCase() === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [menuItems, searchTerm, activeCategory]);

  const addToCart = (item: MenuItem, qty: number = 1) => {
    if (item.stock === 0) return;
    setCart(prev => {
      const existing = prev.find(i => i.item.id === item.id);
      if (existing) return prev.map(i => i.item.id === item.id ? { ...i, qty: i.qty + qty } : i);
      return [...prev, { item, qty }];
    });
  };

  const calculateTotal = () => cart.reduce((acc, c) => acc + (c.item.price * c.qty), 0) + 50;

  const processPayment = async () => {
    setIsProcessing(true);
    const order: Order = {
      id: `ORD-${Date.now().toString().slice(-6)}`,
      customerId: currentUser?.id || 'GUEST',
      customerName: currentUser?.name || 'Guest User',
      customerPhone: currentUser?.phone || payMobile || 'Unknown',
      address: currentUser?.address || 'Default Pickup',
      items: [...cart],
      subtotal: calculateTotal() - 50,
      deliveryCharge: 50,
      total: calculateTotal(),
      status: OrderStatus.PENDING,
      paymentMethod: paymentMethod!,
      transactionId: `TRX-${Math.random().toString(36).toUpperCase().slice(2, 10)}`,
      createdAt: new Date().toISOString()
    };

    // Central API Call
    await API.placeOrder(order);

    setTimeout(() => {
      setLastOrder(order);
      setCart([]);
      setIsProcessing(false);
      setShowGateway(false);
      setView('RECEIPT');
    }, 2000);
  };

  const handleAdminAuth = async (token: string) => {
    const isValid = await API.validateAdmin(token);
    if (isValid) {
      setIsAdminTerminal(true);
      setView('ADMIN');
    } else {
      alert("Invalid Terminal Key. Access Denied.");
    }
  };

  if (isAdminTerminal) {
    return (
      <div className="min-h-screen p-6" style={{ backgroundColor: '#020617' }}>
        <AdminPanel 
          user={currentUser || {} as User} 
          users={[]} 
          menuItems={menuItems} 
          setMenuItems={setMenuItems} 
          orders={orders} 
          setOrders={setOrders} 
          onLogout={() => { setIsAdminTerminal(false); setView('HOME'); }} 
          onMenuUpdate={(update) => console.log('Log Update:', update)} 
          theme={currentTheme}
          setTheme={setCurrentTheme}
        />
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col" style={{ backgroundColor: currentTheme.bg, color: currentTheme.fg }}>
      {/* Headless Tip: No login link for Admin here */}
      <nav className="fixed top-0 inset-x-0 z-[100] glass px-6 h-20 flex justify-between items-center border-b">
        <div className="flex items-center gap-4 cursor-pointer" onClick={() => setView('HOME')}>
          <div className="w-12 h-12 rounded-2xl flex items-center justify-center text-white font-black text-2xl shadow-xl" style={{ backgroundColor: currentTheme.primary }}>B</div>
          <h1 className="text-xl font-black italic uppercase leading-none tracking-tighter">BFC Elite</h1>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setView('CART')} className="relative w-12 h-12 bg-gray-50/10 rounded-2xl flex items-center justify-center">
            <i className="fas fa-shopping-cart"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 w-5 h-5 bg-red-600 text-white text-[10px] rounded-full flex items-center justify-center font-bold">{cart.length}</span>}
          </button>
          {!currentUser ? (
             <Button size="sm" onClick={() => setView('LOGIN')}>Join Club</Button>
          ) : (
            <div className="flex items-center gap-3">
              <span className="hidden sm:block font-black text-[10px] uppercase opacity-40">{currentUser.name}</span>
              <img src={currentUser.avatar || `https://ui-avatars.com/api/?name=${currentUser.name}`} className="w-10 h-10 rounded-xl" />
            </div>
          )}
        </div>
      </nav>

      {/* Realistic Gateway Simulation */}
      {showGateway && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-black/90 backdrop-blur-xl p-6">
           <div className={`w-full max-w-sm rounded-[50px] overflow-hidden shadow-2xl animate-scale-in flex flex-col h-[580px] ${paymentMethod === 'BKASH' ? 'bg-[#D12053]' : 'bg-[#F15922]'}`}>
              <div className="p-8 flex justify-between items-center bg-white/10">
                 <h4 className="text-white font-black uppercase italic tracking-[5px] text-xs">{paymentMethod} Terminal</h4>
                 <button onClick={() => setShowGateway(false)} className="text-white/50"><i className="fas fa-times"></i></button>
              </div>

              <div className="flex-1 p-10 flex flex-col justify-center space-y-10 bg-white text-gray-900 rounded-t-[50px]">
                 <div className="text-center">
                    <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest mb-1">Elite Charge</p>
                    <h4 className="text-5xl font-black">৳{calculateTotal()}</h4>
                 </div>

                 {gatewayStep === 'NUMBER' && (
                   <div className="space-y-6">
                      <input value={payMobile} onChange={e => setPayMobile(e.target.value)} placeholder="017XXXXXXXX" className="w-full p-6 rounded-2xl bg-gray-100 text-center font-black text-2xl outline-none focus:ring-4 ring-red-600/10" />
                      <Button fullWidth size="lg" onClick={() => setGatewayStep('OTP')}>Send OTP</Button>
                   </div>
                 )}

                 {gatewayStep === 'OTP' && (
                   <div className="space-y-6">
                      <input placeholder="XXXXXX" maxLength={6} className="w-full p-6 rounded-2xl bg-gray-100 text-center font-black text-3xl tracking-[15px] outline-none" />
                      <Button fullWidth size="lg" onClick={() => setGatewayStep('PIN')}>Verify</Button>
                   </div>
                 )}

                 {gatewayStep === 'PIN' && (
                   <div className="space-y-6">
                      <input type="password" value={payPin} onChange={e => setPayPin(e.target.value)} placeholder="****" maxLength={4} className="w-full p-6 rounded-2xl bg-gray-100 text-center font-black text-4xl tracking-[20px] outline-none" />
                      <Button fullWidth size="lg" onClick={processPayment} disabled={isProcessing}>{isProcessing ? 'Deploying...' : 'Confirm'}</Button>
                   </div>
                 )}
              </div>
           </div>
        </div>
      )}

      <main className="flex-1 pt-20 pb-32">
        {view === 'HOME' && (
          <div className="reveal space-y-20 p-6 lg:p-24 text-center lg:text-left">
             <div className="grid lg:grid-cols-2 gap-12 items-center">
                <div className="space-y-8">
                   <h2 className="text-6xl lg:text-9xl font-black italic uppercase leading-[0.85] tracking-tighter">Premium <br/> <span style={{ color: currentTheme.primary }}>Bangla Taste.</span></h2>
                   <p className="text-lg opacity-60 max-w-lg mx-auto lg:mx-0">De-coupled, high-performance architecture for the elite foodie.</p>
                   <div className="flex flex-wrap justify-center lg:justify-start gap-4">
                      <Button size="lg" onClick={() => setView('MENU')}>Order Manifest</Button>
                      <button onClick={() => {
                        const token = prompt("Enter Strategic Terminal Key:");
                        if (token) handleAdminAuth(token);
                      }} className="px-10 py-5 rounded-[28px] border-2 border-white/10 text-[10px] font-black uppercase tracking-[4px] hover:bg-white/5 transition-all">Secure Login</button>
                   </div>
                </div>
                <img src="https://images.unsplash.com/photo-1601050690597-df0568f70950?q=80&w=1000" className="rounded-[80px] shadow-2xl h-[600px] object-cover" />
             </div>
          </div>
        )}

        {view === 'MENU' && (
          <div className="reveal max-w-7xl mx-auto px-6 space-y-12 pt-10">
             <div className="flex flex-col lg:flex-row justify-between items-end gap-10">
                <h2 className="text-6xl font-black italic uppercase tracking-tighter">Catalog</h2>
                <div className="flex gap-3 overflow-x-auto no-scrollbar pb-2">
                  {categories.map(cat => (
                    <button key={cat} onClick={() => setActiveCategory(cat)} className={`px-8 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeCategory === cat ? 'bg-red-600 text-white shadow-xl' : 'text-gray-500 hover:bg-black/5'}`}>{cat}</button>
                  ))}
                </div>
             </div>
             <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-10">
                {filteredMenu.map(item => (
                  <div key={item.id} className="rounded-[50px] overflow-hidden border border-white/5 shadow-xl p-5 flex flex-col bg-white" style={{ backgroundColor: currentTheme.card }}>
                     <div className="relative">
                        <img src={item.image} className="h-60 w-full object-cover rounded-[40px] mb-5" />
                        {item.stock === 0 && (
                          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm rounded-[40px] flex items-center justify-center">
                            <span className="text-white font-black uppercase italic tracking-widest">Stock Out</span>
                          </div>
                        )}
                     </div>
                     <h4 className="text-2xl font-black italic uppercase">{item.nameBn}</h4>
                     <p className="text-xs text-gray-400 font-bold uppercase mb-4">{item.name}</p>
                     <div className="flex justify-between items-center mt-auto">
                        <span className="text-xl font-black" style={{ color: currentTheme.primary }}>৳{item.price}</span>
                        <Button size="sm" onClick={() => addToCart(item)} disabled={item.stock === 0}>Deploy</Button>
                     </div>
                  </div>
                ))}
             </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="reveal max-w-4xl mx-auto px-6 pt-10 space-y-10">
             <h2 className="text-5xl font-black italic uppercase tracking-tighter text-center">Your Strategy</h2>
             {cart.length > 0 ? (
               <div className="grid lg:grid-cols-3 gap-10">
                 <div className="lg:col-span-2 space-y-6">
                    <div className="glass rounded-[50px] p-10 space-y-8">
                       {cart.map(c => (
                         <div key={c.item.id} className="flex items-center justify-between border-b border-white/5 pb-6 last:border-0 last:pb-0">
                            <div className="flex items-center gap-6">
                               <img src={c.item.image} className="w-20 h-20 rounded-2xl object-cover" />
                               <div>
                                  <h4 className="text-xl font-black uppercase italic">{c.item.nameBn}</h4>
                                  <p className="text-sm font-bold opacity-30">Unit: ৳{c.item.price}</p>
                               </div>
                            </div>
                            <div className="flex items-center bg-black/5 rounded-2xl p-2 gap-4">
                               <button onClick={() => addToCart(c.item, -1)} className="w-10 h-10 flex items-center justify-center font-black">-</button>
                               <span className="font-black">{c.qty}</span>
                               <button onClick={() => addToCart(c.item, 1)} className="w-10 h-10 flex items-center justify-center font-black">+</button>
                            </div>
                         </div>
                       ))}
                    </div>
                 </div>
                 <div className="space-y-6">
                    <div className="glass rounded-[50px] p-10 space-y-8">
                       <h3 className="text-2xl font-black uppercase tracking-tighter">Total Intel</h3>
                       <div className="flex justify-between text-4xl font-black text-red-600">
                          <span>৳{calculateTotal()}</span>
                       </div>
                       <Button fullWidth size="lg" onClick={() => setView('PAYMENT')}>Checkout</Button>
                    </div>
                 </div>
               </div>
             ) : (
               <div className="py-40 text-center opacity-10"><i className="fas fa-shopping-bag text-9xl"></i></div>
             )}
          </div>
        )}

        {view === 'PAYMENT' && (
          <div className="reveal max-w-4xl mx-auto px-6 pt-10 space-y-10">
             <h2 className="text-5xl font-black italic uppercase tracking-tighter text-center">Elite Gateway</h2>
             <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
                {['BKASH', 'NAGAD', 'ROCKET', 'UPAY', 'CARD', 'COD'].map(id => (
                  <button key={id} onClick={() => {
                    setPaymentMethod(id as any);
                    if (id === 'COD' || id === 'CARD') processPayment();
                    else { setGatewayStep('NUMBER'); setShowGateway(true); }
                  }} className="glass p-10 rounded-[50px] flex flex-col items-center gap-6 group hover:scale-105 transition-all border-4 border-transparent hover:border-red-600">
                     <i className={`fas ${id === 'CARD' ? 'fa-credit-card' : id === 'COD' ? 'fa-truck' : 'fa-mobile-screen'} text-4xl text-red-600`}></i>
                     <span className="text-sm font-black uppercase tracking-widest">{id}</span>
                  </button>
                ))}
             </div>
          </div>
        )}

        {view === 'RECEIPT' && lastOrder && (
          <div className="reveal max-w-2xl mx-auto px-6 pt-10 space-y-10">
             <div ref={receiptRef} className="bg-white rounded-[60px] p-16 shadow-2xl space-y-10 border-t-[20px] border-red-600">
                <div className="text-center space-y-2">
                   <h3 className="text-4xl font-black italic uppercase text-red-600">BFC Elite Order</h3>
                   <p className="text-[10px] font-black opacity-30 tracking-[10px] uppercase">Transaction Confirmed</p>
                </div>
                <div className="space-y-6">
                   {lastOrder.items.map((c, i) => (
                     <div key={i} className="flex justify-between items-center text-gray-900">
                        <span className="font-black text-xl italic">{c.item.nameBn} x {c.qty}</span>
                        <span className="text-xl font-black">৳{c.item.price * c.qty}</span>
                     </div>
                   ))}
                   <div className="pt-10 border-t-4 border-dashed border-gray-100 flex justify-between items-center">
                      <span className="text-2xl font-black italic text-gray-400">Total Dispatch</span>
                      <span className="text-5xl font-black text-red-600">৳{lastOrder.total}</span>
                   </div>
                </div>
                <div className="bg-gray-50 p-6 rounded-3xl text-center">
                   <p className="text-[8px] font-black opacity-30 uppercase tracking-widest">TXN ID: {lastOrder.transactionId}</p>
                </div>
             </div>
             <div className="grid grid-cols-3 gap-4">
                <Button variant="outline" size="sm" onClick={() => window.print()}>Print</Button>
                <Button variant="outline" size="sm" onClick={() => setView('HOME')}>Done</Button>
             </div>
          </div>
        )}
      </main>

      {/* Shared ChatBot across views */}
      <ChatBot currentUser={currentUser} menuItems={menuItems} menuUpdates={[]} isOpen={isChatOpen} setIsOpen={setIsChatOpen} onAddToCart={(name, qty) => {
         const item = menuItems.find(i => i.name.toLowerCase().includes(name.toLowerCase()));
         if (item) addToCart(item, qty);
      }} />

      <footer className="fixed bottom-0 inset-x-0 h-24 glass flex justify-around items-center lg:hidden">
         <button onClick={() => setView('HOME')} className={`text-xl ${view === 'HOME' ? 'text-red-600' : 'opacity-20'}`}><i className="fas fa-home"></i></button>
         <button onClick={() => setView('MENU')} className={`text-xl ${view === 'MENU' ? 'text-red-600' : 'opacity-20'}`}><i className="fas fa-utensils"></i></button>
         <div className="relative -top-8">
            <button onClick={() => setIsChatOpen(true)} className="w-20 h-20 bg-red-600 rounded-[30px] text-white text-3xl shadow-2xl border-4 border-white"><i className="fas fa-robot"></i></button>
         </div>
         <button onClick={() => setView('CART')} className={`text-xl relative ${view === 'CART' ? 'text-red-600' : 'opacity-20'}`}>
            <i className="fas fa-shopping-bag"></i>
            {cart.length > 0 && <span className="absolute -top-2 -right-2 w-4 h-4 bg-red-600 text-white text-[8px] rounded-full flex items-center justify-center">{cart.length}</span>}
         </button>
         <button onClick={() => {
            const token = prompt("Secure Terminal Key:");
            if (token) handleAdminAuth(token);
         }} className="text-xl opacity-20"><i className="fas fa-shield-halved"></i></button>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
