  return (
    <div className="h-[90vh] glass rounded-[60px] overflow-hidden flex flex-col lg:flex-row border-white/10 shadow-[0_50px_100px_rgba(0,0,0,0.8)] animate-elite-up">
       <aside className="w-full lg:w-80 border-b lg:border-b-0 lg:border-r border-white/5 p-10 flex flex-col gap-10 bg-black/40 backdrop-blur-3xl">
          <div className="flex items-center gap-5">
             <div className="w-14 h-14 bg-red-600 rounded-2xl flex items-center justify-center text-white text-3xl font-black">C</div>
             <div>
                <h1 className="text-xl font-black italic text-white uppercase tracking-tighter leading-none">Terminal</h1>
                <p className="text-[7px] font-black text-emerald-500 uppercase tracking-[6px] mt-1">Live Linked</p>
             </div>
          </div>

          <nav className="flex lg:flex-col gap-4">
             {['DASHBOARD', 'OPERATIONS', 'MANIFEST', 'LAYOUT'].map(t => (
               <button 
                 key={t} onClick={() => setActiveTab(t as any)} 
                 className={`flex items-center gap-5 px-8 py-5 rounded-[28px] text-[10px] font-black uppercase tracking-[3px] transition-all ${activeTab === t ? 'bg-red-600 text-white' : 'text-white/20 hover:text-white'}`}
               >
                 <i className={`fas ${t === 'DASHBOARD' ? 'fa-chart-pie' : t === 'OPERATIONS' ? 'fa-truck-fast' : t === 'MANIFEST' ? 'fa-folder-tree' : 'fa-palette'} text-lg`}></i>
                 {t}
               </button>
             ))}
          </nav>

          <div className="mt-auto">
             <button onClick={onLogout} className="w-full py-5 rounded-2xl bg-red-600/10 text-red-600 text-[9px] font-black uppercase tracking-[5px]">Kill Session</button>
          </div>
       </aside>

       <main className="flex-1 flex flex-col overflow-hidden bg-slate-950/20">
          <header className="p-8 lg:p-12 border-b border-white/5 bg-black/20 flex justify-between items-center">
             <div>
                <h2 className="text-4xl font-black italic uppercase text-white tracking-tighter">{activeTab}</h2>
                <span className="text-[8px] font-black text-red-600 uppercase tracking-[8px]">Strategic Command</span>
             </div>
             <div className="flex items-center gap-6">
                <div className="text-right">
                   <p className="text-[8px] font-black text-white/40 uppercase">System Status</p>
                   <p className="text-[10px] font-black text-emerald-500">HEADLESS_CONNECTED</p>
                </div>
                <div className="w-12 h-12 rounded-full border border-emerald-500/20 flex items-center justify-center text-emerald-500 animate-pulse">
                   <i className="fas fa-satellite-dish"></i>
                </div>
             </div>
          </header>

          <div className="flex-1 p-8 lg:p-12 overflow-y-auto custom-scrollbar">
             {activeTab === 'OPERATIONS' && (
               <div className="space-y-8 animate-elite-up">
                  <div className="grid gap-6">
                     {orders.map(o => (
                       <div key={o.id} className="glass p-8 rounded-[40px] flex flex-wrap justify-between items-center border-white/5 hover:bg-white/5 transition-all">
                          <div className="flex gap-8 items-center">
                             <div className="w-16 h-16 bg-red-600/10 text-red-600 rounded-[24px] flex items-center justify-center text-2xl"><i className="fas fa-box"></i></div>
                             <div>
                                <h5 className="text-xl font-black italic text-white uppercase">{o.customerName}</h5>
                                <p className="text-[9px] font-black text-white/20 tracking-[4px]">{o.id} • {o.paymentMethod}</p>
