                          <div className="flex items-center gap-4">
                             <span className={`text-[10px] font-black px-6 py-3 rounded-2xl uppercase tracking-[3px] ${o.status === OrderStatus.PENDING ? 'bg-amber-500/10 text-amber-500' : 'bg-emerald-500/10 text-emerald-500'}`}>
                                {o.status}
