                   </div>
                </div>

                <div className="space-y-6">
                   <Button fullWidth size="md" onClick={() => setView('MENU')}>Return to Catalog</Button>
                   <p className="text-[8px] font-black uppercase tracking-[8px] opacity-10">BFC Elite Tactical Response Team Notified</p>
