      </main>

      <footer className="fixed bottom-0 inset-x-0 h-24 glass border-t border-white/5 flex justify-around items-center lg:hidden safe-bottom z-[100]">
         <button onClick={() => setView('HOME')} className={`text-xl ${view === 'HOME' ? 'text-red-600' : 'opacity-20'}`}><i className="fas fa-home"></i></button>
         <button onClick={() => setView('MENU')} className={`text-xl ${view === 'MENU' ? 'text-red-600' : 'opacity-20'}`}><i className="fas fa-bolt"></i></button>
         <button onClick={() => setView('CART')} className={`text-xl relative ${view === 'CART' ? 'text-red-600' : 'opacity-20'}`}>
