      <div className="hero-glow top-0 left-0"></div>

      {/* Admin Gateway Modal */}
      {showGatewayModal && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6 backdrop-blur-3xl bg-black/80">
