            <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-red-600 to-transparent"></div>
            <div className="space-y-6">
              <div className="w-20 h-20 bg-red-600/10 rounded-3xl flex items-center justify-center text-red-600 text-3xl mx-auto border border-red-600/20 shadow-[0_0_50px_rgba(220,38,38,0.2)]">
                <i className="fas fa-terminal"></i>
              </div>
              <h2 className="text-3xl font-black italic uppercase tracking-tighter">Gateway Auth</h2>
              <p className="text-[10px] text-slate-500 font-bold uppercase tracking-[4px]">Enter Strategic Pairing Key</p>
            </div>

            <div className="space-y-4">
              <input 
                type="password" 
                value={gatewayKey}
                onChange={(e) => setGatewayKey(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && verifyGateway()}
                placeholder="MANIFEST_KEY_XXXX"
                className="w-full h-20 bg-slate-900 border border-white/10 rounded-[28px] px-8 text-center text-lg font-mono font-bold tracking-[8px] focus:border-red-600 outline-none transition-all placeholder:tracking-normal placeholder:text-slate-700"
                autoFocus
              />
              <p className="text-[9px] font-black text-slate-600 uppercase tracking-widest">Default: BFC-ELITE-GATEWAY-2025</p>
            </div>

            <div className="flex gap-4">
              <Button fullWidth variant="primary" size="lg" onClick={verifyGateway}>Initialize</Button>
              <Button fullWidth variant="outline" size="lg" onClick={() => { setShowGatewayModal(false); setGatewayKey(''); }}>Abort</Button>
            </div>
          </div>
        </div>
      )}

      <nav className="fixed top-0 inset-x-0 z-[100] h-20 glass border-b border-white/5 px-8 flex justify-between items-center backdrop-blur-3xl">
         <div className="flex items-center gap-6 cursor-pointer group relative" onClick={handleLogoClick}>
            <div className={`w-12 h-12 bg-red-600 rounded-2xl flex items-center justify-center text-white font-black text-2xl shadow-2xl group-active:scale-90 transition-all ${logoClicks > 0 ? 'ring-4 ring-red-600/20' : ''}`}>B</div>
            {logoClicks > 0 && (
              <div className="absolute -bottom-2 left-0 h-1 bg-red-600 transition-all duration-300" style={{ width: `${(logoClicks/5)*100}%` }}></div>
            )}
            <div className="hidden sm:block">
               <h1 className="text-xl font-black italic uppercase tracking-tighter leading-none">BFC Elite</h1>
               <span className="text-[7px] font-black tracking-[8px] uppercase text-red-600 opacity-60">Tactical Portal</span>
            </div>
         </div>

         <div className="flex items-center gap-6">
            <button onClick={() => setView('CART')} className="relative w-12 h-12 glass-light rounded-2xl flex items-center justify-center border border-white/5 hover:bg-white/10 transition-all group">
               <i className="fas fa-crosshairs text-lg text-white/40 group-hover:text-red-600 transition-colors"></i>
               {cart.length > 0 && (
                 <span className="absolute -top-2 -right-2 w-6 h-6 bg-red-600 text-white text-[10px] font-black rounded-full flex items-center justify-center border-2 border-slate-950">{cart.length}</span>
