            </button>
            {!currentUser ? (
              <Button size="sm" onClick={() => setView('LOGIN')}>Member Entry</Button>
            ) : (
              <div className="flex items-center gap-4 cursor-pointer" onClick={() => setView('PROFILE')}>
                <div className="text-right hidden sm:block">
                  <p className="text-[7px] font-black uppercase text-red-600 tracking-widest">Authenticated</p>
                  <p className="text-xs font-black">{currentUser.name}</p>
                </div>
                <img src={`https://ui-avatars.com/api/?name=${currentUser.name}&background=dc2626&color=fff`} className="w-11 h-11 rounded-2xl border border-white/10 shadow-xl" />
              </div>
            )}
         </div>
      </nav>

      <main className="flex-1 pt-20">
        {view === 'HOME' && (
          <div className="animate-elite-up min-h-[90vh] flex flex-col items-center justify-center p-8 lg:p-24 text-center relative overflow-hidden">
             <div className="space-y-12 max-w-5xl z-10">
                <div className="space-y-4">
                   <span className="text-red-600 font-black uppercase tracking-[15px] text-[10px] block animate-pulse">Gateway Live</span>
                   <h2 className="text-7xl lg:text-[140px] font-black italic uppercase leading-[0.8] tracking-tighter">Tactical <br/> <span className="text-transparent bg-clip-text bg-gradient-to-r from-red-600 to-rose-400">Flavor Control.</span></h2>
                </div>
                <p className="text-lg lg:text-2xl text-slate-400 max-w-2xl mx-auto font-medium leading-relaxed">The pinnacle of Bangladeshi cuisine, delivered through strategic precision.</p>
                <div className="flex flex-wrap justify-center gap-6 pt-8">
                   <Button size="lg" onClick={() => setView('MENU')}>Initiate Order</Button>
                   <button onClick={() => setView('LOGIN')} className="px-14 py-8 rounded-[28px] border-2 border-white/5 bg-white/5 hover:bg-white/10 transition-all font-black uppercase tracking-[4px] text-xs">Access Vault</button>
                </div>
             </div>
          </div>
        )}

        {(view === 'LOGIN' || view === 'SIGNUP') && (
