import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Order, MenuItem, OrderStatus, UserRole, User } from './types';
import { Button } from './components/Button';
import { API } from './services/api';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  AreaChart, Area
} from 'recharts';

interface AdminPanelProps {
  user: User;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  onLogout: () => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ user, menuItems, setMenuItems, orders, onLogout }) => {
  const [isMfaVerified, setIsMfaVerified] = useState(false);
  const [mfaCode, setMfaCode] = useState(['', '', '', '', '', '']);
  const [activeTab, setActiveTab] = useState<'INTEL' | 'LOGISTICS' | 'MANIFEST' | 'PERSONNEL'>('INTEL');
  const [role] = useState<UserRole>(UserRole.ADMIN);
  const inputRefs = useRef<(HTMLInputElement | null)[]>([]);

  const analyticsData = useMemo(() => [
    { name: '08:00', sales: 4000, orders: 24 },
    { name: '10:00', sales: 3000, orders: 18 },
    { name: '12:00', sales: 9000, orders: 45 },
    { name: '14:00', sales: 5000, orders: 30 },
    { name: '16:00', sales: 7000, orders: 38 },
    { name: '18:00', sales: 12000, orders: 60 },
    { name: '20:00', sales: 15000, orders: 75 },
  ], []);

  const handleMfaInput = (index: number, value: string) => {
    if (value.length > 1) value = value.slice(-1);
    const newCode = [...mfaCode];
    newCode[index] = value;
    setMfaCode(newCode);

    if (value && index < 5) {
      inputRefs.current[index + 1]?.focus();
    }
  };

  const handleKeyDown = (index: number, e: React.KeyboardEvent) => {
    if (e.key === 'Backspace' && !mfaCode[index] && index > 0) {
      inputRefs.current[index - 1]?.focus();
    }
  };

  const verifyMfa = () => {
    if (mfaCode.join('') === '123456') {
      setIsMfaVerified(true);
    } else {
      alert("CRITICAL ERROR: Verification mismatch. Identity rejected.");
      setMfaCode(['', '', '', '', '', '']);
      inputRefs.current[0]?.focus();
    }
  };

  const handleUpdateStatus = async (orderId: string, status: OrderStatus) => {
    await API.updateOrderStatus(orderId, status);
  };

  const handleToggleStock = async (item: MenuItem) => {
    const updated = { ...item, stock: item.stock > 0 ? 0 : 50 };
    await API.updateMenuItem(updated);
    setMenuItems(prev => prev.map(m => m.id === item.id ? updated : m));
  };

  const handleUpdatePrice = async (item: MenuItem, change: number) => {
    const updated = { ...item, price: Math.max(0, item.price + change) };
    await API.updateMenuItem(updated);
    setMenuItems(prev => prev.map(m => m.id === item.id ? updated : m));
  };

  if (!isMfaVerified) {
    return (
      <div className="fixed inset-0 bg-[#020617] flex items-center justify-center p-8 z-[5000]">
         <div className="w-full max-w-lg glass p-12 rounded-[60px] border-emerald-500/30 text-center space-y-10 animate-elite-up">
            <div className="space-y-4">
               <div className="w-24 h-24 bg-emerald-500/10 rounded-[35px] flex items-center justify-center text-emerald-500 text-4xl mx-auto border border-emerald-500/20 shadow-[0_0_50px_rgba(16,185,129,0.2)]">
                  <i className="fas fa-fingerprint"></i>
               </div>
               <h2 className="text-3xl font-black italic uppercase tracking-tighter">Personnel Sync</h2>
               <p className="text-xs text-slate-400 font-bold uppercase tracking-[4px]">Biometric Auth Required</p>
            </div>

            <div className="flex justify-center gap-3">
               {mfaCode.map((digit, i) => (
                 <input
                   key={i}
                   ref={el => inputRefs.current[i] = el}
                   type="text" 
                   maxLength={1} 
                   value={digit}
                   onChange={(e) => handleMfaInput(i, e.target.value)}
                   onKeyDown={(e) => handleKeyDown(i, e)}
                   className="w-12 h-16 bg-slate-900 border border-white/10 rounded-2xl text-center text-2xl font-black focus:border-emerald-500 outline-none transition-all"
                   autoFocus={i === 0}
                 />
               ))}
            </div>

            <p className="text-[10px] text-slate-500 font-black uppercase tracking-[5px]">Developer Code: 123456</p>

            <div className="flex gap-4">
              <Button fullWidth size="lg" onClick={verifyMfa} className="!bg-emerald-600 shadow-emerald-600/20">Verify Access</Button>
              <Button fullWidth variant="outline" size="lg" onClick={onLogout}>Abort</Button>
            </div>
         </div>
      </div>
    );
  }

  return (
    <div className="h-screen bg-[#020617] flex overflow-hidden font-sans">
       <aside className="w-80 glass border-r border-white/5 flex flex-col p-10 bg-black/40 backdrop-blur-3xl hidden lg:flex">
          <div className="flex items-center gap-5 mb-16">
             <div className="w-14 h-14 bg-red-600 rounded-2xl flex items-center justify-center text-white text-3xl font-black shadow-[0_0_40px_rgba(220,38,38,0.3)]">C</div>
             <div>
                <h1 className="text-xl font-black italic uppercase tracking-tighter leading-none">BFC Command</h1>
                <p className="text-[7px] font-black text-emerald-500 uppercase tracking-[6px] mt-1">Status: Operational</p>
             </div>
          </div>

          <nav className="space-y-4 flex-1">
             {[
               { id: 'INTEL', label: 'Intelligence', icon: 'fa-brain-circuit' },
               { id: 'LOGISTICS', label: 'Logistics', icon: 'fa-truck-ramp-box' },
               { id: 'MANIFEST', label: 'Manifest', icon: 'fa-folder-tree' },
               { id: 'PERSONNEL', label: 'Personnel', icon: 'fa-users-gear' }
             ].map(item => (
               <button 
                 key={item.id} onClick={() => setActiveTab(item.id as any)}
                 className={`w-full flex items-center gap-6 px-8 py-5 rounded-[28px] text-[10px] font-black uppercase tracking-[3px] transition-all duration-500 ${activeTab === item.id ? 'bg-red-600 text-white shadow-2xl scale-105' : 'text-slate-500 hover:text-white hover:bg-white/5'}`}
               >
                 <i className={`fas ${item.icon} text-lg`}></i>
                 {item.id}
               </button>
             ))}
          </nav>

          <div className="mt-auto space-y-6 pt-10 border-t border-white/5">
             <div className="flex items-center gap-4 p-4 glass-light rounded-3xl border border-white/5">
                <img src={`https://ui-avatars.com/api/?name=Admin&background=dc2626&color=fff`} className="w-10 h-10 rounded-xl" />
                <div>
                   <p className="text-[10px] font-black uppercase text-white leading-none">Root_Admin</p>
                   <p className="text-[8px] font-bold text-red-600 uppercase tracking-widest mt-1">{role}</p>
                </div>
             </div>
             <button onClick={onLogout} className="w-full py-5 rounded-[25px] bg-red-600/10 text-red-600 text-[9px] font-black uppercase tracking-[5px] border border-red-600/20 hover:bg-red-600 hover:text-white transition-all">Terminate System</button>
          </div>
       </aside>

       <main className="flex-1 overflow-y-auto custom-scrollbar p-6 md:p-12 bg-gradient-to-br from-slate-950 to-black">
