             <div>
                <h2 className="text-4xl md:text-6xl font-black italic uppercase text-white tracking-tighter leading-none">{activeTab}</h2>
                <div className="h-1 w-20 bg-red-600 mt-4 rounded-full"></div>
             </div>
             <div className="flex gap-6 items-center">
                <div className="text-right hidden sm:block">
                   <p className="text-[8px] font-black text-slate-500 uppercase tracking-widest">Network</p>
                   <p className="text-xs font-black text-emerald-500">Live_Sync_Established</p>
                </div>
                <div className="w-12 h-12 glass rounded-2xl flex items-center justify-center text-emerald-500 border-emerald-500/20 animate-pulse">
                   <i className="fas fa-satellite-dish"></i>
                </div>
                <button onClick={onLogout} className="lg:hidden w-12 h-12 glass rounded-2xl flex items-center justify-center text-red-600 border-red-600/20">
                  <i className="fas fa-power-off"></i>
                </button>
             </div>
          </header>

          <div className="lg:hidden flex gap-4 overflow-x-auto no-scrollbar pb-8 mb-4">
             {['INTEL', 'LOGISTICS', 'MANIFEST', 'PERSONNEL'].map(t => (
               <button 
                 key={t} onClick={() => setActiveTab(t as any)}
