               >
                 {t}
               </button>
             ))}
          </div>

          {activeTab === 'INTEL' && (
            <div className="space-y-12 animate-elite-up">
               <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
                  <div className="glass p-10 rounded-[50px] space-y-4 border-emerald-500/10">
                     <p className="text-[10px] font-black text-slate-500 uppercase tracking-[5px]">Total Gross</p>
                     <h4 className="text-5xl font-black italic text-emerald-500">৳58,240</h4>
