               </div>

               <div className="glass p-6 md:p-12 rounded-[60px] border-white/5 h-[450px]">
                  <div className="flex justify-between items-center mb-10">
                     <h3 className="text-lg md:text-xl font-black italic uppercase tracking-widest text-white/50">Strategic Revenue Stream</h3>
