                   onChange={(e) => handleMfaInput(i, e.target.value)}
                   onKeyDown={(e) => handleKeyDown(i, e)}
                   className="w-16 h-24 bg-transparent border-b-2 border-white/5 text-center text-4xl font-black text-red-600 focus:border-red-600 outline-none transition-all"
