                         <div className="flex justify-between"><span>Operational Subtotal</span><span>৳{calculateSubtotal()}</span></div>
                         <div className="flex justify-between"><span>Fleet Logistics</span><span>৳{DELIVERY_CHARGE}</span></div>
                      </div>
                      <div className="pt-8 border-t border-white/10 flex justify-between items-end">
                         <span className="text-xs font-black uppercase tracking-[5px] opacity-30">Mission Total</span>
