                   </div>
                </div>
             </div>
          </div>
        )}

        {view === 'RECEIPT' && lastOrder && (
          <div className="animate-elite-up min-h-[80vh] flex items-center justify-center p-8">
             <div className="w-full max-w-2xl glass p-12 lg:p-20 rounded-[70px] relative overflow-hidden text-center space-y-12 border-emerald-500/30">
                <div className="absolute top-0 left-0 w-full h-2 bg-emerald-500"></div>
                <div className="space-y-6">
                   <div className="w-28 h-28 bg-emerald-500 rounded-[40px] flex items-center justify-center text-white text-5xl mx-auto shadow-[0_20px_40px_rgba(16,185,129,0.3)]">
                      <i className="fas fa-check-double"></i>
                   </div>
                   <h2 className="text-5xl font-black italic uppercase tracking-tighter">Mission Success</h2>
                   <p className="text-slate-400 font-bold uppercase tracking-[5px] text-[10px]">Your order has been deployed successfully</p>
