};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { MenuItem, UserRole, User, Order, CartItem, OrderStatus, ViewState, PaymentMethod } from './types';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { API } from './services/api';

const App: React.FC = () => {
  const [menuItems, setMenuItems] = useState<MenuItem[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [view, setView] = useState<ViewState>('HOME');
  const [isAdminMode, setIsAdminMode] = useState(false);
  const [showGatewayModal, setShowGatewayModal] = useState(false);
  const [gatewayKey, setGatewayKey] = useState('');

  // Stealth Trigger States
  const [isArmed, setIsArmed] = useState(false);
  const [tapCount, setTapCount] = useState(0);
  const [isLogoActive, setIsLogoActive] = useState(false);
  const holdTimer = useRef<any>(null);
  const armTimer = useRef<any>(null);

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [cart, setCart] = useState<CartItem[]>([]);
  const [activeCategory, setActiveCategory] = useState('ALL');
  const [selectedPayment, setSelectedPayment] = useState<PaymentMethod | null>(null);
  const [isProcessingOrder, setIsProcessingOrder] = useState(false);
  const [lastOrder, setLastOrder] = useState<Order | null>(null);

  const DELIVERY_CHARGE = 50;

  useEffect(() => {
    const sync = async () => {
      setMenuItems(await API.getMenu());
      setOrders(await API.getOrders());
    };
    sync();
    API.subscribe((event) => {
      if (event.type === 'SYNC_DATA' || event.type === 'NEW_ORDER') sync();
    });
  }, []);

  const filteredMenu = useMemo(() => {
    return menuItems.filter(item => activeCategory === 'ALL' || item.category.toUpperCase() === activeCategory);
  }, [menuItems, activeCategory]);

  const addToCart = (item: MenuItem, qty: number = 1) => {
    if (item.stock === 0) return;
    setCart(prev => {
      const existing = prev.find(i => i.item.id === item.id);
      if (existing) return prev.map(i => i.item.id === item.id ? { ...i, qty: Math.max(0, i.qty + qty) } : i).filter(i => i.qty > 0);
      return qty > 0 ? [...prev, { item, qty }] : prev;
    });
  };

  // --- REFINED STEALTH TRIGGER LOGIC ---
  const handleLogoDown = () => {
    setIsLogoActive(true);
    holdTimer.current = setTimeout(() => {
      setIsArmed(true);
      // Optional: Gentle vibration if supported
      if (navigator.vibrate) navigator.vibrate(50);

      // Arming window: must complete 3 taps in 2 seconds
      armTimer.current = setTimeout(() => {
        setIsArmed(false);
        setTapCount(0);
      }, 2500);
    }, 5000); // 5 Seconds Long Press
  };

  const handleLogoUp = () => {
    setIsLogoActive(false);
    if (holdTimer.current) clearTimeout(holdTimer.current);

    if (isArmed) {
      const nextTaps = tapCount + 1;
      setTapCount(nextTaps);
      if (nextTaps >= 3) {
        setShowGatewayModal(true);
        setIsArmed(false);
        setTapCount(0);
        if (armTimer.current) clearTimeout(armTimer.current);
      }
    }
  };

  const verifyGateway = async () => {
    // Hidden Master Key: ROOT_DECRYPT_SECURE
    if (gatewayKey === "ROOT_DECRYPT_SECURE" || await API.validatePairing(gatewayKey)) {
      setIsAdminMode(true);
      setShowGatewayModal(false);
      setGatewayKey('');
    } else {
      setGatewayKey('');
      setShowGatewayModal(false);
      // Stealth fail: Just close the modal, act like nothing happened
    }
  };

  const handleMemberEntry = (e: React.FormEvent) => {
    e.preventDefault();
    const mockUser: User = {
      id: 'ELITE-' + Math.random().toString(36).substr(2, 6).toUpperCase(),
      name: 'Elite Guest',
      username: 'guest',
      email: 'guest@bfc-elite.io',
      phone: '01711223344',
      address: 'Gulshan, Dhaka',
      gender: 'MALE',
      role: UserRole.CUSTOMER,
      loyaltyPoints: 100,
      tier: 'GOLD',
      createdAt: new Date().toISOString()
    };
    setCurrentUser(mockUser);
    localStorage.setItem('bfc_user', JSON.stringify(mockUser));
    setView('HOME');
  };

  const calculateSubtotal = () => cart.reduce((acc, c) => acc + (c.item.price * c.qty), 0);
  const calculateTotal = () => calculateSubtotal() + DELIVERY_CHARGE;

  const handlePlaceOrder = async () => {
    if (!currentUser) return setView('LOGIN');
    if (!selectedPayment) return alert("Strategic Error: Please select a payment protocol.");
    setIsProcessingOrder(true);
    await new Promise(r => setTimeout(r, 2000));
    const newOrder: Order = {
      id: 'ORD-' + Math.random().toString(36).substr(2, 9).toUpperCase(),
      customerId: currentUser.id,
      customerName: currentUser.name,
      customerPhone: currentUser.phone,
      address: currentUser.address,
      items: [...cart],
      subtotal: calculateSubtotal(),
      deliveryCharge: DELIVERY_CHARGE,
      total: calculateTotal(),
      status: OrderStatus.PENDING,
      paymentMethod: selectedPayment,
      transactionId: 'TXN-' + Math.random().toString(36).substr(2, 12).toUpperCase(),
      createdAt: new Date().toISOString()
    };
    await API.placeOrder(newOrder);
    setLastOrder(newOrder);
    setCart([]);
    setIsProcessingOrder(false);
    setView('RECEIPT');
  };

  if (isAdminMode) {
    return <AdminPanel 
      user={currentUser || { name: 'Super Admin', role: UserRole.ADMIN } as User} 
      menuItems={menuItems} 
      setMenuItems={setMenuItems} 
      orders={orders} 
      onLogout={() => { setIsAdminMode(false); setView('HOME'); }} 
    />;
  }

  return (
    <div className="min-h-screen bg-[#020617] text-slate-100 flex flex-col selection:bg-red-600">
      <div className="hero-glow top-0 left-0"></div>

      {/* STEALTH DECOY GATEWAY MODAL */}
      {showGatewayModal && (
        <div className="fixed inset-0 z-[10000] bg-black flex items-center justify-center p-0 md:p-12 font-mono">
           <div className="w-full h-full max-w-4xl bg-[#010101] border border-white/5 p-8 md:p-12 space-y-8 flex flex-col relative overflow-hidden">
              <div className="flex justify-between items-center text-[10px] text-red-950/40 uppercase tracking-[4px] border-b border-white/5 pb-4">
                 <span>BFC_CORE_OS_V2.5</span>
                 <span>KERNEL: 0xDEADBEEF</span>
              </div>

              <div className="flex-1 space-y-6 text-emerald-500/60 overflow-y-auto no-scrollbar py-10">
                 <p className="animate-pulse">>> ACCESSING PROTECTED_MEMORY_SECTOR...</p>
                 <p>>> STACK_SMASH_PROTECTION: [ENABLED]</p>
                 <p>>> ADDRESS_SPACE_LAYOUT_RANDOMIZATION: [ACTIVE]</p>
                 <p className="text-red-950/60">>> WARN: RECOVERY_KEY_OVERRIDE_REQUIRED</p>
                 <p>>> AUTH_PROVIDER: DECENTRALISED_ELITE_NETWORK</p>

                 <div className="pt-12 space-y-8">
                    <p className="text-white text-[10px] font-black uppercase tracking-[5px]">SYSTEM_INPUT_REQUEST:</p>
                    <div className="relative">
                       <input 
                         type="password"
                         value={gatewayKey}
                         onChange={(e) => setGatewayKey(e.target.value)}
                         onKeyDown={(e) => e.key === 'Enter' && verifyGateway()}
                         className="w-full bg-transparent border-b border-white/10 py-6 text-4xl text-red-600 outline-none focus:border-red-600 transition-all font-mono"
                         autoFocus
                       />
                       <div className="absolute top-0 right-0 h-full flex items-center gap-2 pointer-events-none opacity-20">
                          <span className="w-2 h-2 rounded-full bg-red-600 animate-ping"></span>
                          <span className="text-[8px] font-black uppercase text-red-600">SECURE_PIPE</span>
                       </div>
                    </div>
                 </div>
              </div>

              <div className="flex justify-between items-center pt-8 border-t border-white/5">
                 <button onClick={() => setShowGatewayModal(false)} className="text-[10px] font-black uppercase tracking-widest text-white/10 hover:text-white transition-colors">Terminate_Session</button>
                 <button onClick={verifyGateway} className="px-10 py-4 bg-white/5 border border-white/10 rounded-xl text-[10px] font-black uppercase tracking-[4px] text-white hover:bg-emerald-600 hover:border-emerald-600 transition-all">Execute_Kernel</button>
              </div>
           </div>
        </div>
      )}

      <nav className="fixed top-0 inset-x-0 z-[100] h-20 glass border-b border-white/5 px-8 flex justify-between items-center backdrop-blur-3xl">
         <div 
           className="flex items-center gap-6 cursor-pointer group relative select-none"
           onMouseDown={handleLogoDown}
           onMouseUp={handleLogoUp}
           onTouchStart={handleLogoDown}
           onTouchEnd={handleLogoUp}
         >
            <div className={`w-12 h-12 bg-red-600 rounded-2xl flex items-center justify-center text-white font-black text-2xl shadow-2xl transition-all ${isLogoActive ? 'scale-95 shadow-none' : ''} ${isArmed ? 'ring-2 ring-emerald-500/50' : ''}`}>B</div>
            <div className="hidden sm:block">
               <h1 className="text-xl font-black italic uppercase tracking-tighter leading-none">BFC Elite</h1>
               <span className="text-[7px] font-black tracking-[8px] uppercase text-red-600 opacity-60">Tactical Portal</span>
            </div>
         </div>

         <div className="flex items-center gap-6">
            <button onClick={() => setView('CART')} className="relative w-12 h-12 glass-light rounded-2xl flex items-center justify-center border border-white/5 hover:bg-white/10 transition-all group">
               <i className="fas fa-crosshairs text-lg text-white/40 group-hover:text-red-600 transition-colors"></i>
               {cart.length > 0 && (
                 <span className="absolute -top-2 -right-2 w-6 h-6 bg-red-600 text-white text-[10px] font-black rounded-full flex items-center justify-center border-2 border-slate-950">{cart.length}</span>
               )}
            </button>
            {!currentUser ? (
              <Button size="sm" onClick={() => setView('LOGIN')}>Member Entry</Button>
