};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { MenuItem, UserRole, User, Order, CartItem, OrderStatus, ViewState, PaymentMethod } from './types';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { API } from './services/api';
import { verifyAdminIdentity } from './services/geminiService';

const App: React.FC = () => {
  const [menuItems, setMenuItems] = useState<MenuItem[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [view, setView] = useState<ViewState>('HOME');
  const [isAdminMode, setIsAdminMode] = useState(false);
  const [showGatewayModal, setShowGatewayModal] = useState(false);
  const [gatewayKey, setGatewayKey] = useState('');
  const [isVerifyingAi, setIsVerifyingAi] = useState(false);

  // Cart Enhancement States
  const [showClearCartModal, setShowClearCartModal] = useState(false);
  const [removingItemId, setRemovingItemId] = useState<string | null>(null);
  const [lastUpdatedId, setLastUpdatedId] = useState<string | null>(null);

  // Robust Phantom Trigger States
  const [isArmed, setIsArmed] = useState(false);
  const [tapCount, setTapCount] = useState(0);
  const [isLogoActive, setIsLogoActive] = useState(false);
  const holdTimer = useRef<any>(null);
  const armTimer = useRef<any>(null);

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [cart, setCart] = useState<CartItem[]>([]);
  const [activeCategory, setActiveCategory] = useState('ALL');
  const [selectedPayment, setSelectedPayment] = useState<PaymentMethod | null>(null);
  const [isProcessingOrder, setIsProcessingOrder] = useState(false);
  const [lastOrder, setLastOrder] = useState<Order | null>(null);

  const DELIVERY_CHARGE = 50;

  useEffect(() => {
    const sync = async () => {
      setMenuItems(await API.getMenu());
      setOrders(await API.getOrders());
    };
    sync();
    API.subscribe((event) => {
      if (event.type === 'SYNC_DATA' || event.type === 'NEW_ORDER') sync();
    });
  }, []);

  const filteredMenu = useMemo(() => {
    return menuItems.filter(item => activeCategory === 'ALL' || item.category.toUpperCase() === activeCategory);
  }, [menuItems, activeCategory]);

  const addToCart = (item: MenuItem, qty: number = 1) => {
    if (item.stock === 0) return;

    setLastUpdatedId(item.id);
    setTimeout(() => setLastUpdatedId(null), 300);

    setCart(prev => {
      const existing = prev.find(i => i.item.id === item.id);

      // Handle Removal Animation
      if (existing && existing.qty + qty <= 0) {
        setRemovingItemId(item.id);
        // Wait for animation to finish before state update
        setTimeout(() => {
          setCart(current => current.filter(i => i.item.id !== item.id));
          setRemovingItemId(null);
        }, 400);
        return prev;
      }

      if (existing) {
        return prev.map(i => i.item.id === item.id ? { ...i, qty: i.qty + qty } : i);
      }
      return qty > 0 ? [...prev, { item, qty }] : prev;
    });
  };

  const handleClearCart = () => {
    setCart([]);
    setShowClearCartModal(false);
  };

  // --- IMPROVED PHANTOM TRIGGER ---
  const handlePointerDown = (e: React.PointerEvent) => {
    setIsLogoActive(true);
    if (holdTimer.current) clearTimeout(holdTimer.current);

    holdTimer.current = setTimeout(() => {
      setIsArmed(true);
      if (navigator.vibrate) navigator.vibrate(100);

      if (armTimer.current) clearTimeout(armTimer.current);
      armTimer.current = setTimeout(() => {
        setIsArmed(false);
        setTapCount(0);
      }, 3000); 
    }, 5000); // 5 Seconds Hold
  };

  const handlePointerUp = () => {
    setIsLogoActive(false);
    if (holdTimer.current) {
      clearTimeout(holdTimer.current);
      holdTimer.current = null;
    }

    if (isArmed) {
      const nextTaps = tapCount + 1;
      setTapCount(nextTaps);
      if (nextTaps >= 3) {
        setShowGatewayModal(true);
        setIsArmed(false);
        setTapCount(0);
        if (armTimer.current) clearTimeout(armTimer.current);
      }
    }
  };

  const verifyGateway = async () => {
    if (!gatewayKey.trim()) return;
    setIsVerifyingAi(true);

    // AI Neural Handshake
    const isAuthorized = await verifyAdminIdentity(gatewayKey);

    if (isAuthorized) {
      setIsAdminMode(true);
      setShowGatewayModal(false);
      setGatewayKey('');
    } else {
      setGatewayKey('');
      console.warn("ADMIN_AUTH: Neural signature mismatch.");
      setTimeout(() => setShowGatewayModal(false), 1500);
    }
    setIsVerifyingAi(false);
  };

  const handleMemberEntry = (e: React.FormEvent) => {
    e.preventDefault();
    const mockUser: User = {
      id: 'ELITE-' + Math.random().toString(36).substr(2, 6).toUpperCase(),
      name: 'Elite Guest',
      username: 'guest',
      email: 'guest@bfc-elite.io',
      phone: '01711223344',
      address: 'Gulshan, Dhaka',
      gender: 'MALE',
      role: UserRole.CUSTOMER,
      loyaltyPoints: 100,
      tier: 'GOLD',
      createdAt: new Date().toISOString()
    };
    setCurrentUser(mockUser);
    localStorage.setItem('bfc_user', JSON.stringify(mockUser));
    setView('HOME');
  };

  const calculateSubtotal = () => cart.reduce((acc, c) => acc + (c.item.price * c.qty), 0);
  const calculateTotal = () => calculateSubtotal() + DELIVERY_CHARGE;

  const handlePlaceOrder = async () => {
    if (!currentUser) return setView('LOGIN');
    if (!selectedPayment) return alert("Strategic Error: Please select a payment protocol.");
    setIsProcessingOrder(true);
    await new Promise(r => setTimeout(r, 2000));
    const newOrder: Order = {
      id: 'ORD-' + Math.random().toString(36).substr(2, 9).toUpperCase(),
      customerId: currentUser.id,
      customerName: currentUser.name,
      customerPhone: currentUser.phone,
      address: currentUser.address,
      items: [...cart],
      subtotal: calculateSubtotal(),
      deliveryCharge: DELIVERY_CHARGE,
      total: calculateTotal(),
      status: OrderStatus.PENDING,
      paymentMethod: selectedPayment,
      transactionId: 'TXN-' + Math.random().toString(36).substr(2, 12).toUpperCase(),
      createdAt: new Date().toISOString()
    };
    await API.placeOrder(newOrder);
    setLastOrder(newOrder);
    setCart([]);
    setIsProcessingOrder(false);
    setView('RECEIPT');
  };

  if (isAdminMode) {
    return <AdminPanel 
      user={currentUser || { name: 'Super Admin', role: UserRole.ADMIN } as User} 
      menuItems={menuItems} 
      setMenuItems={setMenuItems} 
      orders={orders} 
      onLogout={() => { setIsAdminMode(false); setView('HOME'); }} 
    />;
  }

  return (
    <div className="min-h-screen bg-[#020617] text-slate-100 flex flex-col selection:bg-red-600">
      <div className="hero-glow top-0 left-0"></div>

      {/* CLEAR CART CONFIRMATION MODAL */}
      {showClearCartModal && (
        <div className="fixed inset-0 z-[11000] bg-black/90 backdrop-blur-md flex items-center justify-center p-6 font-mono">
           <div className="w-full max-w-lg glass p-10 rounded-[40px] border-red-600/20 space-y-8 animate-elite-up">
              <div className="flex items-center gap-4 text-red-600">
                 <i className="fas fa-triangle-exclamation text-2xl animate-pulse"></i>
                 <h3 className="text-xl font-black uppercase tracking-tighter">Mission_Abort_Request</h3>
              </div>
              <p className="text-slate-400 text-sm font-bold leading-relaxed">Confirm the purge of all strategic items from the Tactical Bag? This action cannot be undone.</p>
              <div className="flex gap-4">
                 <button onClick={() => setShowClearCartModal(false)} className="flex-1 py-5 rounded-2xl bg-white/5 border border-white/10 text-[10px] font-black uppercase tracking-widest hover:bg-white/10 transition-all">Cancel_Abort</button>
                 <button onClick={handleClearCart} className="flex-1 py-5 rounded-2xl bg-red-600 text-white text-[10px] font-black uppercase tracking-widest hover:bg-red-700 transition-all shadow-xl shadow-red-600/20">Execute_Purge</button>
              </div>
           </div>
        </div>
      )}

      {/* AI STEALTH GATEWAY MODAL */}
      {showGatewayModal && (
        <div className="fixed inset-0 z-[10000] bg-black flex items-center justify-center p-0 md:p-12 font-mono">
           <div className="w-full h-full max-w-4xl bg-[#010101] border border-white/5 p-8 md:p-12 space-y-8 flex flex-col relative overflow-hidden">
              <div className="flex justify-between items-center text-[10px] text-red-950/40 uppercase tracking-[4px] border-b border-white/5 pb-4">
                 <span>BFC_NEURAL_SHIELD_V4</span>
                 <span>ID: {Math.random().toString(16).slice(2, 10).toUpperCase()}</span>
              </div>

              <div className="flex-1 space-y-6 text-emerald-500/60 overflow-y-auto no-scrollbar py-10">
                 <p className="animate-pulse">>> INITIATING AI_NEURAL_HANDSHAKE...</p>
                 <p>>> ANALYZING_COGNITIVE_BIOMETRICS: [DONE]</p>
                 <p>>> SECTOR_07_INTEGRITY: [SECURE]</p>
                 <p className="text-red-950/60">>> AWAITING_STRATEGIC_IDENTIFIER_CHALLENGE...</p>
                 <p>>> COMMAND: "Define the objective of the Elite Manifest in Sector 07."</p>

                 <div className="pt-12 space-y-8">
                    <p className="text-white text-[10px] font-black uppercase tracking-[5px]">NEURAL_RESPONSE_INPUT:</p>
                    <div className="relative">
                       <input 
                         type="text"
                         value={gatewayKey}
                         onChange={(e) => setGatewayKey(e.target.value)}
                         onKeyDown={(e) => e.key === 'Enter' && !isVerifyingAi && verifyGateway()}
                         className="w-full bg-transparent border-b border-white/10 py-6 text-2xl text-red-600 outline-none focus:border-red-600 transition-all font-mono"
                         placeholder="_"
                         autoFocus
                         disabled={isVerifyingAi}
                       />
                       {isVerifyingAi && (
                         <div className="absolute top-0 right-0 h-full flex items-center gap-4">
                            <span className="text-[10px] text-emerald-500 animate-pulse">AI_DECRYPTING...</span>
                            <div className="w-2 h-2 bg-emerald-500 rounded-full animate-ping"></div>
                         </div>
                       )}
                    </div>
                 </div>
              </div>

              <div className="flex justify-between items-center pt-8 border-t border-white/5">
                 <button onClick={() => setShowGatewayModal(false)} className="text-[10px] font-black uppercase tracking-widest text-white/10 hover:text-red-600 transition-colors">Discard_Session</button>
                 <button onClick={verifyGateway} disabled={isVerifyingAi} className="px-10 py-4 bg-white/5 border border-white/10 rounded-xl text-[10px] font-black uppercase tracking-[4px] text-white hover:bg-red-600 hover:border-red-600 transition-all disabled:opacity-30">Verify_Handshake</button>
              </div>
           </div>
        </div>
      )}

      <nav className="fixed top-0 inset-x-0 z-[100] h-20 glass border-b border-white/5 px-8 flex justify-between items-center backdrop-blur-3xl">
         <div 
           className="flex items-center gap-6 cursor-pointer group relative select-none touch-none"
           onPointerDown={handlePointerDown}
           onPointerUp={handlePointerUp}
           onPointerLeave={() => { if(holdTimer.current) { clearTimeout(holdTimer.current); holdTimer.current = null; } setIsLogoActive(false); }}
         >
            <div className={`w-12 h-12 bg-red-600 rounded-2xl flex items-center justify-center text-white font-black text-2xl shadow-2xl transition-all ${isLogoActive ? 'scale-90 opacity-80' : ''} ${isArmed ? 'ring-2 ring-emerald-500 shadow-[0_0_20px_rgba(16,185,129,0.5)]' : ''}`}>B</div>
            <div className="hidden sm:block">
               <h1 className="text-xl font-black italic uppercase tracking-tighter leading-none">BFC Elite</h1>
               <span className="text-[7px] font-black tracking-[8px] uppercase text-red-600 opacity-60">Tactical Portal</span>
            </div>
         </div>

         <div className="flex items-center gap-6">
            <button onClick={() => setView('CART')} className="relative w-12 h-12 glass-light rounded-2xl flex items-center justify-center border border-white/5 hover:bg-white/10 transition-all group">
               <i className="fas fa-crosshairs text-lg text-white/40 group-hover:text-red-600 transition-colors"></i>
               {cart.length > 0 && (
                 <span className="absolute -top-2 -right-2 w-6 h-6 bg-red-600 text-white text-[10px] font-black rounded-full flex items-center justify-center border-2 border-slate-950">{cart.length}</span>
               )}
            </button>
            {!currentUser ? (
              <Button size="sm" onClick={() => setView('LOGIN')}>Member Entry</Button>
            ) : (
              <div className="flex items-center gap-4 cursor-pointer" onClick={() => setView('PROFILE')}>
                <div className="text-right hidden sm:block">
                  <p className="text-[7px] font-black uppercase text-red-600 tracking-widest">Authenticated</p>
                  <p className="text-xs font-black">{currentUser.name}</p>
                </div>
                <img src={`https://ui-avatars.com/api/?name=${currentUser.name}&background=dc2626&color=fff`} className="w-11 h-11 rounded-2xl border border-white/10 shadow-xl" />
              </div>
            )}
         </div>
      </nav>

      <main className="flex-1 pt-20">
        {view === 'HOME' && (
          <div className="animate-elite-up min-h-[90vh] flex flex-col items-center justify-center p-8 lg:p-24 text-center relative overflow-hidden">
             <div className="space-y-12 max-w-5xl z-10">
                <div className="space-y-4">
                   <span className="text-red-600 font-black uppercase tracking-[15px] text-[10px] block animate-pulse">Gateway Live</span>
