import { MenuItem, Order, OrderStatus, AuditLog } from '../types';
import { MOCK_MENU } from '../constants';

const DB_KEYS = {
  MENU: 'bfc_elite_menu_v2',
  ORDERS: 'bfc_elite_orders_v2',
  LOGS: 'bfc_elite_audit_logs',
  MASTER_KEY: 'DHAKA_ELITE_2025'
};

// Initialize DB
if (!localStorage.getItem(DB_KEYS.MENU)) {
  localStorage.setItem(DB_KEYS.MENU, JSON.stringify(MOCK_MENU));
}
if (!localStorage.getItem(DB_KEYS.LOGS)) {
  localStorage.setItem(DB_KEYS.LOGS, JSON.stringify([]));
}

export const API = {
  async getMenu(): Promise<MenuItem[]> {
    return JSON.parse(localStorage.getItem(DB_KEYS.MENU) || '[]');
  },

  async updateMenuItem(item: MenuItem, adminName: string): Promise<void> {
    const menu = await this.getMenu();
    const updated = menu.map(m => m.id === item.id ? item : m);
    localStorage.setItem(DB_KEYS.MENU, JSON.stringify(updated));

    await this.addLog({
      id: `LOG-${Math.random().toString(36).slice(2, 7)}`,
      action: 'MENU_UPDATE',
      user: adminName,
      details: `Updated ${item.name}: Price ৳${item.price}, Stock ${item.stock}`,
      timestamp: new Date().toISOString()
    });
    this.broadcast('SYNC_DATA');
  },

  async getOrders(): Promise<Order[]> {
    return JSON.parse(localStorage.getItem(DB_KEYS.ORDERS) || '[]');
  },

  async placeOrder(order: Order): Promise<void> {
    const orders = await this.getOrders();
    localStorage.setItem(DB_KEYS.ORDERS, JSON.stringify([order, ...orders]));
    this.broadcast('NEW_ORDER');
  },

  async updateOrderStatus(orderId: string, status: OrderStatus, adminName: string): Promise<void> {
    const orders = await this.getOrders();
    const updated = orders.map(o => o.id === orderId ? { ...o, status } : o);
    localStorage.setItem(DB_KEYS.ORDERS, JSON.stringify(updated));

    await this.addLog({
      id: `LOG-${Math.random().toString(36).slice(2, 7)}`,
      action: 'ORDER_STATUS_CHANGE',
      user: adminName,
      details: `Order ${orderId} changed to ${status}`,
      timestamp: new Date().toISOString()
    });
    this.broadcast('SYNC_DATA');
  },

  async getLogs(): Promise<AuditLog[]> {
    return JSON.parse(localStorage.getItem(DB_KEYS.LOGS) || '[]');
  },

  async addLog(log: AuditLog): Promise<void> {
    const logs = await this.getLogs();
    localStorage.setItem(DB_KEYS.LOGS, JSON.stringify([log, ...logs.slice(0, 99)]));
  },

  async validatePairing(key: string): Promise<boolean> {
    return key === DB_KEYS.MASTER_KEY;
  },

  broadcast(type: string) {
    window.dispatchEvent(new CustomEvent('BFC_ELITE_SYNC', { detail: { type } }));
  },

  subscribe(callback: (event: any) => void) {
    window.addEventListener('BFC_ELITE_SYNC', (e: any) => callback(e.detail));
  }
};

