        <button onClick={() => setView('CART')} className={`flex flex-col items-center gap-1 relative ${view === 'CART' ? 'text-red-600' : 'text-gray-300'}`}>
          <i className="fas fa-shopping-basket text-lg"></i>
          <span className="text-[10px] font-bold">Cart</span>
          {cart.length > 0 && <span className="absolute -top-1 right-0 w-4 h-4 bg-red-600 text-white text-[8px] rounded-full flex items-center justify-center font-bold">{cart.length}</span>}
        </button>
      </footer>
    </div>
  );
};

