import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline';
  size?: 'sm' | 'md' | 'lg';
  fullWidth?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  fullWidth, 
  className, 
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center font-bold transition-all active:scale-95 disabled:opacity-50 select-none rounded-2xl";

  const variants = {
    primary: "bg-red-600 text-white hover:bg-red-700 shadow-md",
    secondary: "bg-gray-900 text-white hover:bg-black",
    outline: "border-2 border-red-600 text-red-600 hover:bg-red-50 shadow-none"
  };

  const sizes = {
    sm: "px-6 py-2.5 text-xs",
    md: "px-8 py-4 text-sm",
    lg: "px-10 py-5 text-base"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${fullWidth ? 'w-full' : ''} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { MenuItem, UserRole, User, Order, CartItem, OrderStatus, ViewState, PaymentMethod } from './types';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { API } from './services/api';

const App: React.FC = () => {
  const [menuItems, setMenuItems] = useState<MenuItem[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [view, setView] = useState<ViewState>('HOME');
  const [isAdminMode, setIsAdminMode] = useState(false);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [activeCategory, setActiveCategory] = useState('All');

  // Persistence for user (though simplified for now)
  const [currentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('bfc_user');
    return saved ? JSON.parse(saved) : null;
  });

  useEffect(() => {
    const sync = async () => {
      setMenuItems(await API.getMenu());
      setOrders(await API.getOrders());
    };
    sync();
    API.subscribe(sync);
  }, []);

  const categories = useMemo(() => {
    return ['All', ...new Set(menuItems.map(item => item.category))];
  }, [menuItems]);

  const filteredMenu = useMemo(() => {
    if (activeCategory === 'All') return menuItems;
    return menuItems.filter(item => item.category === activeCategory);
  }, [menuItems, activeCategory]);

  const addToCart = (item: MenuItem) => {
    if (item.stock === 0) return;
    setCart(prev => {
      const existing = prev.find(i => i.item.id === item.id);
      if (existing) {
        return prev.map(i => i.item.id === item.id ? { ...i, qty: i.qty + 1 } : i);
      }
      return [...prev, { item, qty: 1 }];
    });
  };

  const removeFromCart = (itemId: string) => {
    setCart(prev => {
      const existing = prev.find(i => i.item.id === itemId);
      if (existing && existing.qty > 1) {
        return prev.map(i => i.item.id === itemId ? { ...i, qty: i.qty - 1 } : i);
      }
      return prev.filter(i => i.item.id !== itemId);
    });
  };

  const calculateTotal = () => cart.reduce((acc, c) => acc + (c.item.price * c.qty), 0);

  const handleCheckout = async () => {
    if (cart.length === 0) return;

    const name = prompt("Enter your name for the order:") || "Guest Customer";
    const phone = prompt("Enter your phone number:") || "01XXX-XXXXXX";
    const address = prompt("Enter delivery address:") || "Dhanmondi, Dhaka";

    const newOrder: Order = {
      id: `ORD-${Math.random().toString(36).slice(2, 9).toUpperCase()}`,
      customerId: currentUser?.id || 'GUEST',
      customerName: name,
      customerPhone: phone,
      address: address,
      items: cart,
      subtotal: calculateTotal(),
      deliveryCharge: 50,
      total: calculateTotal() + 50,
      status: OrderStatus.PENDING,
      paymentMethod: 'COD',
      transactionId: '',
      createdAt: new Date().toISOString()
    };

    try {
      await API.placeOrder(newOrder);
      alert("Order placed successfully!");
      setCart([]);
      setView('HOME');
    } catch (err) {
      alert("Failed to place order. Please try again.");
    }
  };

  const handleAdminAccess = () => {
    const pass = prompt("Enter Admin Password (admin123):");
    if (pass === 'admin123') {
      setIsAdminMode(true);
    } else if (pass !== null) {
      alert("Invalid Password!");
    }
  };

  if (isAdminMode) {
    return (
      <AdminPanel 
        user={currentUser || { name: 'Admin', role: UserRole.ADMIN } as User}
        menuItems={menuItems}
        setMenuItems={setMenuItems}
        orders={orders}
        onLogout={() => {
            setIsAdminMode(false);
            setView('HOME');
        }}
        onMenuUpdate={() => {}}
        cms={null}
        setCms={null}
        setOrders={setOrders}
      />
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-white">
      {/* Navbar */}
      <nav className="fixed top-0 inset-x-0 z-50 h-16 bg-white/90 backdrop-blur-md border-b border-gray-100 px-6 flex justify-between items-center">
        <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center text-white font-bold text-xl">B</div>
          <h1 className="text-xl font-bold text-gray-900 tracking-tight">BFC</h1>
        </div>

        <div className="flex items-center gap-4">
          <button onClick={() => setView('MENU')} className={`text-sm font-semibold px-2 ${view === 'MENU' ? 'text-red-600' : 'text-gray-500 hover:text-red-600'}`}>Menu</button>
          <button onClick={() => setView('CART')} className="relative p-2 text-gray-600 hover:text-red-600 transition-colors">
            <i className="fas fa-shopping-cart text-xl"></i>
            {cart.length > 0 && (
              <span className="absolute top-0 right-0 w-5 h-5 bg-red-600 text-white text-[10px] rounded-full flex items-center justify-center border-2 border-white font-bold">{cart.length}</span>
            )}
          </button>
          <button onClick={handleAdminAccess} className="p-2 text-gray-300 hover:text-gray-500 transition-colors">
             <i className="fas fa-cog"></i>
          </button>
        </div>
      </nav>

      <main className="flex-1 pt-16">
        {view === 'HOME' && (
          <div className="animate-fade-in hero-bg min-h-[90vh] flex flex-col items-center justify-center px-6 text-center">
            <div className="w-20 h-20 bg-red-600 rounded-[32px] mb-8 flex items-center justify-center text-white text-4xl font-black shadow-xl">B</div>
            <h2 className="text-4xl md:text-7xl font-extrabold text-gray-900 mb-6 leading-tight">
              Delicious Food, <br/>
              <span className="text-red-600">Bangladeshi Style.</span>
            </h2>
            <p className="text-gray-500 max-w-lg mb-12 text-lg leading-relaxed">The most authentic fried chicken and traditional snacks in Dhaka. Prepared fresh, delivered hot.</p>
            <div className="flex flex-col sm:flex-row gap-4 w-full sm:w-auto">
              <Button size="lg" onClick={() => setView('MENU')} className="px-12 py-5">Order Now</Button>
              <Button variant="outline" size="lg" onClick={() => setView('MENU')} className="px-12 py-5">View Menu</Button>
            </div>
          </div>
        )}

        {view === 'MENU' && (
          <div className="animate-fade-in max-w-7xl mx-auto px-6 py-12">
            <div className="flex flex-col md:flex-row justify-between items-center gap-8 mb-12">
              <h2 className="text-4xl font-bold text-gray-900">Our Menu</h2>
              <div className="flex gap-2 overflow-x-auto no-scrollbar w-full md:w-auto pb-2">
                {categories.map(cat => (
                  <button 
                    key={cat} 
                    onClick={() => setActiveCategory(cat)}
                    className={`px-6 py-2.5 rounded-full text-sm font-bold transition-all whitespace-nowrap ${activeCategory === cat ? 'bg-red-600 text-white shadow-lg' : 'bg-gray-100 text-gray-500 hover:bg-gray-200'}`}
                  >
                    {cat}
                  </button>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
              {filteredMenu.map(item => (
                <div key={item.id} className="bg-white rounded-[32px] overflow-hidden card-shadow group border border-gray-50 flex flex-col">
                  <div className="h-56 overflow-hidden relative">
                    <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt={item.name} />
                    <div className="absolute top-4 right-4 bg-white/90 backdrop-blur-sm px-4 py-1.5 rounded-full text-sm font-bold text-red-600 shadow-sm">৳{item.price}</div>
                    {item.stock === 0 && (
                      <div className="absolute inset-0 bg-white/60 backdrop-blur-sm flex items-center justify-center">
                        <span className="text-red-700 font-bold uppercase text-xs tracking-wider">Sold Out</span>
                      </div>
                    )}
                  </div>
                  <div className="p-6 flex flex-col flex-1">
                    <h4 className="text-xl font-bold text-gray-900 mb-1 leading-tight">{item.nameBn}</h4>
                    <p className="text-xs text-gray-400 mb-6 uppercase tracking-wider">{item.name}</p>
                    <div className="mt-auto">
                        <Button fullWidth size="sm" disabled={item.stock === 0} onClick={() => addToCart(item)} className="rounded-2xl">Add to Cart</Button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="animate-fade-in max-w-2xl mx-auto px-6 py-12">
            <h2 className="text-4xl font-bold text-gray-900 mb-12 text-center md:text-left">Your Cart</h2>
            {cart.length > 0 ? (
              <div className="space-y-8">
                <div className="bg-white rounded-[40px] p-8 card-shadow border border-gray-50 divide-y divide-gray-100">
                  {cart.map(c => (
                    <div key={c.item.id} className="py-6 flex items-center justify-between first:pt-0 last:pb-0">
                      <div className="flex items-center gap-6">
                        <img src={c.item.image} className="w-20 h-20 rounded-2xl object-cover shadow-sm" alt={c.item.name} />
                        <div>
                          <h4 className="font-bold text-gray-900 text-lg leading-tight">{c.item.nameBn}</h4>
                          <p className="text-sm text-gray-400">৳{c.item.price} / unit</p>
                        </div>
                      </div>
                      <div className="flex items-center gap-4">
                        <button onClick={() => removeFromCart(c.item.id)} className="w-10 h-10 rounded-full bg-gray-50 flex items-center justify-center text-gray-400 hover:bg-red-50 hover:text-red-600 transition-colors">
                          <i className="fas fa-minus text-xs"></i>
                        </button>
                        <span className="font-bold w-6 text-center text-lg">{c.qty}</span>
                        <button onClick={() => addToCart(c.item)} className="w-10 h-10 rounded-full bg-gray-50 flex items-center justify-center text-gray-400 hover:bg-red-50 hover:text-red-600 transition-colors">
                          <i className="fas fa-plus text-xs"></i>
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
                <div className="bg-white rounded-[40px] p-10 card-shadow border border-gray-50">
                  <div className="flex justify-between text-2xl font-bold mb-10">
                    <span className="text-gray-900">Total</span>
                    <span className="text-red-600">৳{calculateTotal()}</span>
                  </div>
                  <Button fullWidth size="lg" className="py-6 text-lg rounded-[24px]" onClick={handleCheckout}>Checkout Now</Button>
                </div>
              </div>
            ) : (
              <div className="text-center py-24 bg-white rounded-[40px] border-2 border-dashed border-gray-100">
