import React, { useState } from 'react';
import { Order, MenuItem, OrderStatus, User, MenuUpdate } from './types';
import { Button } from './components/Button';
import { API } from './services/api';

interface AdminPanelProps {
  user: User;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  onLogout: () => void;
  onMenuUpdate: (update: MenuUpdate) => void;
  cms: any;
  setCms: any;
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ menuItems, setMenuItems, orders, onLogout }) => {
  const [tab, setTab] = useState<'ORDERS' | 'MENU'>('ORDERS');

  const updatePrice = async (id: string, currentPrice: number) => {
    const val = prompt("Enter new price in BDT:", currentPrice.toString());
    if (val !== null) {
      const newPrice = parseInt(val);
      if (!isNaN(newPrice)) {
        const item = menuItems.find(m => m.id === id);
        if (item) {
          const updatedItem = { ...item, price: newPrice };
          setMenuItems(prev => prev.map(m => m.id === id ? updatedItem : m));
          await API.updateMenuItem(updatedItem, 'Admin');
        }
      }
    }
  };

  const toggleStock = async (id: string) => {
    const item = menuItems.find(m => m.id === id);
    if (item) {
      const updatedItem = { ...item, stock: item.stock > 0 ? 0 : 50 };
      setMenuItems(prev => prev.map(m => m.id === id ? updatedItem : m));
      await API.updateMenuItem(updatedItem, 'Admin');
    }
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus) => {
    await API.updateOrderStatus(orderId, status, 'Admin');
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col font-sans">
      <nav className="bg-white border-b border-gray-200 px-8 h-16 flex justify-between items-center sticky top-0 z-50">
