          <h2 className="font-bold text-gray-900 tracking-tight text-lg">Admin Control</h2>
        </div>
        <button onClick={onLogout} className="text-sm font-bold text-red-600 bg-red-50 px-5 py-2 rounded-xl hover:bg-red-100 transition-colors">Logout</button>
      </nav>

      <div className="flex-1 flex flex-col md:flex-row">
        <aside className="w-full md:w-64 bg-white border-r border-gray-200 p-6 flex md:flex-col gap-2">
          <button onClick={() => setTab('ORDERS')} className={`flex-1 md:flex-none text-left px-5 py-4 rounded-2xl text-sm font-bold transition-all ${tab === 'ORDERS' ? 'bg-red-600 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-50'}`}>
            <i className="fas fa-receipt mr-3"></i> Customer Orders
          </button>
          <button onClick={() => setTab('MENU')} className={`flex-1 md:flex-none text-left px-5 py-4 rounded-2xl text-sm font-bold transition-all ${tab === 'MENU' ? 'bg-red-600 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-50'}`}>
            <i className="fas fa-hamburger mr-3"></i> Menu Management
          </button>
        </aside>

        <main className="flex-1 p-6 md:p-10">
          {tab === 'ORDERS' ? (
            <div className="space-y-6 animate-fade-in">
              <h3 className="text-2xl font-bold text-gray-900">Manage Orders</h3>
              <div className="bg-white rounded-[32px] border border-gray-200 overflow-hidden shadow-sm">
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead className="bg-gray-50 text-gray-400 text-[10px] uppercase font-bold tracking-widest">
                            <tr>
                                <th className="px-6 py-5">Order ID</th>
                                <th className="px-6 py-5">Customer</th>
                                <th className="px-6 py-5">Total Amount</th>
                                <th className="px-6 py-5">Status</th>
                                <th className="px-6 py-5">Action</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100 text-sm">
                            {orders.length > 0 ? orders.map(o => (
                                <tr key={o.id} className="hover:bg-gray-50 transition-colors">
                                    <td className="px-6 py-5 font-mono text-gray-400 text-xs">#{o.id}</td>
                                    <td className="px-6 py-5">
                                        <div className="font-bold text-gray-800">{o.customerName}</div>
                                        <div className="text-[10px] text-gray-400">{o.customerPhone}</div>
                                    </td>
                                    <td className="px-6 py-5 font-semibold">৳{o.total}</td>
                                    <td className="px-6 py-5">
                                        <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase ${o.status === 'DELIVERED' ? 'bg-green-100 text-green-600' : 'bg-yellow-100 text-yellow-600'}`}>
                                            {o.status}
                                        </span>
                                    </td>
                                    <td className="px-6 py-5">
                                        <select 
                                            className="text-xs font-bold bg-gray-100 border-none rounded-lg px-3 py-2 outline-none"
