              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {menuItems.map(item => (
                  <div key={item.id} className="bg-white p-6 rounded-[32px] border border-gray-200 flex gap-5 items-center shadow-sm">
                    <img src={item.image} className="w-20 h-20 rounded-2xl object-cover shadow-sm" alt={item.name} />
                    <div className="flex-1">
                      <h5 className="font-bold text-gray-900 leading-tight mb-1">{item.nameBn}</h5>
                      <p className="text-red-600 font-bold text-sm">৳{item.price}</p>
                    </div>
                    <div className="flex flex-col gap-2">
                      <button 
                        onClick={() => toggleStock(item.id)} 
                        className={`px-3 py-2 rounded-xl text-[10px] font-bold uppercase transition-colors ${item.stock > 0 ? 'bg-green-50 text-green-600 hover:bg-green-100' : 'bg-red-50 text-red-600 hover:bg-red-100'}`}
                      >
                        {item.stock > 0 ? 'In Stock' : 'Out of Stock'}
                      </button>
                      <button 
                        onClick={() => updatePrice(item.id, item.price)} 
                        className="text-[10px] font-bold text-blue-600 bg-blue-50 px-3 py-2 rounded-xl hover:bg-blue-100 transition-colors"
                      >
                        Edit Price
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

