            <h2 className="text-4xl font-bold text-gray-900 mb-8">Checkout Details</h2>
            <form onSubmit={handleCheckoutSubmit} className="space-y-6">
              <div className="bg-white rounded-[40px] p-8 card-shadow border border-gray-50 space-y-6">
                <div>
                  <label className="block text-sm font-bold text-gray-600 mb-2">Full Name</label>
                  <input 
                    required 
                    type="text" 
                    value={checkoutInfo.name}
                    onChange={e => setCheckoutInfo({...checkoutInfo, name: e.target.value})}
                    placeholder="Enter your name" 
                    className="w-full px-6 py-4 rounded-2xl bg-gray-50 border-none outline-none focus:ring-2 focus:ring-red-600 transition-all"
                  />
                </div>
                <div>
                  <label className="block text-sm font-bold text-gray-600 mb-2">Phone Number</label>
                  <input 
                    required 
                    type="tel" 
                    value={checkoutInfo.phone}
                    onChange={e => setCheckoutInfo({...checkoutInfo, phone: e.target.value})}
                    placeholder="017XXXXXXXX" 
                    className="w-full px-6 py-4 rounded-2xl bg-gray-50 border-none outline-none focus:ring-2 focus:ring-red-600 transition-all"
                  />
                </div>
                <div>
                  <label className="block text-sm font-bold text-gray-600 mb-2">Delivery Address</label>
                  <textarea 
                    required 
                    value={checkoutInfo.address}
                    onChange={e => setCheckoutInfo({...checkoutInfo, address: e.target.value})}
                    placeholder="Area, Road, House No." 
                    rows={3}
                    className="w-full px-6 py-4 rounded-2xl bg-gray-50 border-none outline-none focus:ring-2 focus:ring-red-600 transition-all resize-none"
                  ></textarea>
                </div>
              </div>
              <div className="flex gap-4">
                <Button variant="outline" className="flex-1" onClick={() => setView('CART')}>Back to Cart</Button>
                <Button type="submit" className="flex-1">Continue to Payment</Button>
              </div>
            </form>
          </div>
        )}

        {view === 'PAYMENT' && (
          <div className="animate-fade-in max-w-2xl mx-auto px-6 py-12">
            <h2 className="text-4xl font-bold text-gray-900 mb-8">Payment Method</h2>
            <div className="bg-white rounded-[40px] p-8 card-shadow border border-gray-50 space-y-8">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {[
                  { id: 'BKASH', name: 'bKash', icon: 'fa-mobile-screen' },
                  { id: 'NAGAD', name: 'Nagad', icon: 'fa-mobile-screen' },
                  { id: 'CARD', name: 'Card Payment', icon: 'fa-credit-card' },
                  { id: 'COD', name: 'Cash on Delivery', icon: 'fa-hand-holding-dollar' }
                ].map((method) => (
                  <div key={method.id}>
                    <input 
                      type="radio" 
                      id={method.id} 
                      name="payment" 
                      className="hidden payment-option"
                      checked={selectedPayment === method.id}
                      onChange={() => setSelectedPayment(method.id as PaymentMethod)}
                    />
                    <label 
                      htmlFor={method.id}
                      className="flex items-center gap-4 p-5 rounded-2xl border-2 border-gray-100 cursor-pointer transition-all hover:border-red-200"
                    >
                      <div className="w-12 h-12 rounded-xl bg-gray-50 flex items-center justify-center text-gray-400 group-hover:text-red-600">
                        <i className={`fas ${method.icon} text-xl`}></i>
                      </div>
                      <span className="font-bold text-gray-700">{method.name}</span>
                    </label>
                  </div>
                ))}
              </div>

              <div className="border-t border-gray-100 pt-8 space-y-4">
                <div className="flex justify-between text-gray-600">
                  <span>Order Subtotal</span>
                  <span>৳{calculateTotal()}</span>
                </div>
                <div className="flex justify-between text-gray-600">
                  <span>Delivery Charge</span>
                  <span>৳50</span>
                </div>
                <div className="flex justify-between text-xl font-bold text-gray-900 pt-2">
                  <span>Total Payable</span>
                  <span className="text-red-600">৳{calculateTotal() + 50}</span>
                </div>
              </div>

              <Button 
                fullWidth 
                size="lg" 
                className="py-6 rounded-3xl" 
                disabled={isProcessingPayment}
                onClick={processPayment}
              >
                {isProcessingPayment ? (
                  <span className="flex items-center gap-3">
                    <i className="fas fa-circle-notch animate-spin"></i> Processing Securely...
                  </span>
                ) : (
                  selectedPayment === 'COD' ? 'Confirm Order' : `Pay ৳${calculateTotal() + 50} with ${selectedPayment}`
                )}
              </Button>
            </div>
          </div>
        )}

        {view === 'RECEIPT' && lastOrder && (
          <div className="animate-fade-in max-w-2xl mx-auto px-6 py-12">
            <div className="bg-white rounded-[40px] p-10 card-shadow border border-gray-50 print-area">
              <div className="text-center mb-10">
                <div className="w-16 h-16 bg-red-600 rounded-2xl flex items-center justify-center text-white font-bold text-2xl mx-auto mb-4">B</div>
                <h2 className="text-2xl font-bold text-gray-900">BFC Digital Receipt</h2>
                <p className="text-emerald-500 font-bold text-sm uppercase tracking-widest mt-2">Order Successful</p>
              </div>

              <div className="grid grid-cols-2 gap-8 mb-10 text-sm">
                <div>
                  <p className="text-gray-400 font-bold uppercase text-[10px] mb-1">Order Details</p>
                  <p className="font-bold text-gray-800">ID: {lastOrder.id}</p>
                  <p className="text-gray-500">{new Date(lastOrder.createdAt).toLocaleString()}</p>
                </div>
                <div className="text-right">
                  <p className="text-gray-400 font-bold uppercase text-[10px] mb-1">Customer Info</p>
                  <p className="font-bold text-gray-800">{lastOrder.customerName}</p>
                  <p className="text-gray-500">{lastOrder.customerPhone}</p>
                </div>
              </div>

              <div className="space-y-4 mb-10 border-t border-b border-gray-100 py-8">
                {lastOrder.items.map((c, i) => (
                  <div key={i} className="flex justify-between items-center text-sm">
                    <div>
                      <span className="font-bold text-gray-800">{c.item.nameBn}</span>
                      <span className="text-gray-400 ml-2">x{c.qty}</span>
                    </div>
                    <span className="font-bold text-gray-800">৳{c.item.price * c.qty}</span>
                  </div>
                ))}
              </div>

              <div className="space-y-3 mb-12">
                <div className="flex justify-between text-sm text-gray-500">
                  <span>Subtotal</span>
                  <span>৳{lastOrder.subtotal}</span>
                </div>
                <div className="flex justify-between text-sm text-gray-500">
                  <span>Delivery Charge</span>
                  <span>৳{lastOrder.deliveryCharge}</span>
                </div>
                <div className="flex justify-between text-xl font-black text-gray-900 border-t border-gray-100 pt-4">
                  <span>Total</span>
                  <span className="text-red-600">৳{lastOrder.total}</span>
                </div>
              </div>

              <div className="bg-gray-50 p-6 rounded-3xl text-center space-y-2 mb-10">
                <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Payment Status</p>
                <p className="font-black text-gray-800">{lastOrder.paymentMethod} - {lastOrder.status}</p>
                {lastOrder.transactionId && <p className="text-[10px] font-mono text-emerald-600">TXN: {lastOrder.transactionId}</p>}
              </div>

              <div className="flex gap-4 no-print">
                <Button fullWidth onClick={() => window.print()} variant="outline">Print Receipt</Button>
                <Button fullWidth onClick={() => setView('HOME')}>Back to Home</Button>
              </div>
            </div>
          </div>
        )}
      </main>

      {/* Mobile Footer */}
      <footer className="md:hidden fixed bottom-0 inset-x-0 h-16 bg-white border-t border-gray-100 flex justify-around items-center px-6 z-50 no-print">
        <button onClick={() => setView('HOME')} className={`flex flex-col items-center gap-1 ${view === 'HOME' ? 'text-red-600' : 'text-gray-300'}`}>
          <i className="fas fa-home text-lg"></i>
          <span className="text-[10px] font-bold">Home</span>
        </button>
        <button onClick={() => setView('MENU')} className={`flex flex-col items-center gap-1 ${view === 'MENU' ? 'text-red-600' : 'text-gray-300'}`}>
          <i className="fas fa-utensils text-lg"></i>
          <span className="text-[10px] font-bold">Menu</span>
        </button>
        <button onClick={() => setView('CART')} className={`flex flex-col items-center gap-1 relative ${['CART', 'CHECKOUT', 'PAYMENT'].includes(view) ? 'text-red-600' : 'text-gray-300'}`}>
          <i className="fas fa-shopping-basket text-lg"></i>
          <span className="text-[10px] font-bold">Cart</span>
          {cart.length > 0 && <span className="absolute -top-1 right-0 w-4 h-4 bg-red-600 text-white text-[8px] rounded-full flex items-center justify-center font-bold">{cart.length}</span>}
        </button>
      </footer>
    </div>
  );
};

export default App;

export enum UserRole {
  ADMIN = 'ADMIN',
  MANAGER = 'MANAGER',
  STAFF = 'STAFF',
  CUSTOMER = 'CUSTOMER'
}

export enum OrderStatus {
  PENDING = 'PENDING',
  PAID = 'PAID',
  PREPARING = 'PREPARING',
  READY = 'READY',
  ON_THE_WAY = 'ON_THE_WAY',
  DELIVERED = 'DELIVERED',
  CANCELLED = 'CANCELLED',
  FAILED = 'FAILED'
}

export interface User {
  id: string;
  name: string;
  username: string;
  email: string;
  phone: string;
  address: string;
  gender: 'MALE' | 'FEMALE' | 'OTHER';
  role: UserRole;
  loyaltyPoints: number;
  tier: 'ELITE' | 'GOLD' | 'SILVER' | 'BRONZE';
  createdAt: string;
}

export interface MenuItem {
  id: string;
  name: string;
  nameBn: string;
  description: string;
  price: number;
  category: string;
  image: string;
  stock: number;
  isPopular?: boolean;
}

export interface CartItem {
  item: MenuItem;
  qty: number;
}

export type PaymentMethod = 'BKASH' | 'NAGAD' | 'ROCKET' | 'VISA' | 'MASTER' | 'COD';

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  customerPhone: string;
  address: string;
  items: CartItem[];
  subtotal: number;
  deliveryCharge: number;
  total: number;
  status: OrderStatus;
  paymentMethod: PaymentMethod;
  transactionId: string;
  createdAt: string;
}

export type ViewState = 'HOME' | 'MENU' | 'CART' | 'CHECKOUT' | 'PAYMENT' | 'RECEIPT' | 'ADMIN';

export interface MenuUpdate {
  type: 'PRICE_CHANGE' | 'AVAILABILITY' | 'ADD' | 'DELETE';
  itemName: string;
  details: string;
  timestamp: Date;
}

import React, { useState, useEffect, useMemo } from 'react';
import { MenuItem, UserRole, User, Order, CartItem, OrderStatus, ViewState, PaymentMethod } from './types';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { API } from './services/api';

const App: React.FC = () => {
  const [menuItems, setMenuItems] = useState<MenuItem[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [view, setView] = useState<ViewState>('HOME');
  const [isAdminMode, setIsAdminMode] = useState(false);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [activeCategory, setActiveCategory] = useState('All');

  // Checkout & Payment Logic
  const [checkoutInfo, setCheckoutInfo] = useState({ name: '', phone: '', address: '' });
  const [selectedPayment, setSelectedPayment] = useState<PaymentMethod>('BKASH');
  const [paymentStatus, setPaymentStatus] = useState<'IDLE' | 'PROCESSING' | 'SUCCESS' | 'FAILED'>('IDLE');
  const [lastOrder, setLastOrder] = useState<Order | null>(null);

  useEffect(() => {
    const sync = async () => {
      setMenuItems(await API.getMenu());
      setOrders(await API.getOrders());
    };
    sync();
    API.subscribe(sync);
  }, []);

  const categories = useMemo(() => {
    return ['All', ...new Set(menuItems.map(item => item.category))];
  }, [menuItems]);

  const filteredMenu = useMemo(() => {
    if (activeCategory === 'All') return menuItems;
    return menuItems.filter(item => item.category === activeCategory);
  }, [menuItems, activeCategory]);

  const addToCart = (item: MenuItem) => {
    if (item.stock === 0) return;
    setCart(prev => {
      const existing = prev.find(i => i.item.id === item.id);
      if (existing) {
        return prev.map(i => i.item.id === item.id ? { ...i, qty: i.qty + 1 } : i);
      }
      return [...prev, { item, qty: 1 }];
    });
  };

  const removeFromCart = (itemId: string) => {
    setCart(prev => {
      const existing = prev.find(i => i.item.id === itemId);
      if (existing && existing.qty > 1) {
        return prev.map(i => i.item.id === itemId ? { ...i, qty: i.qty - 1 } : i);
      }
      return prev.filter(i => i.item.id !== itemId);
    });
  };

  const subtotal = useMemo(() => cart.reduce((acc, c) => acc + (c.item.price * c.qty), 0), [cart]);
  const deliveryCharge = 50;
  const totalPayable = subtotal + deliveryCharge;

  const handleCheckoutSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (cart.length === 0) return;
    setView('PAYMENT');
  };

  // PROFESSIONAL GATEWAY LOGIC (SSLCommerz / Shurjopay Mock)
  const executePaymentGateway = async () => {
    setPaymentStatus('PROCESSING');

    // Simulate API calls to gateway endpoints (initiate -> validate)
    await new Promise(resolve => setTimeout(resolve, 2500));

    const isSuccess = Math.random() > 0.05; // 95% success rate for mock

    if (isSuccess) {
      const newOrder: Order = {
        id: `ORD-${Date.now().toString().slice(-6)}-${Math.floor(Math.random() * 1000)}`,
        customerId: 'GUEST',
        customerName: checkoutInfo.name,
        customerPhone: checkoutInfo.phone,
        address: checkoutInfo.address,
        items: cart,
        subtotal,
        deliveryCharge,
        total: totalPayable,
        status: selectedPayment === 'COD' ? OrderStatus.PENDING : OrderStatus.PAID,
        paymentMethod: selectedPayment,
        transactionId: selectedPayment === 'COD' ? '' : `TXN-${Math.random().toString(36).toUpperCase().slice(2, 10)}`,
        createdAt: new Date().toISOString()
      };

      try {
        await API.placeOrder(newOrder);
        setLastOrder(newOrder);
        setCart([]);
        setPaymentStatus('SUCCESS');
        setView('RECEIPT');
      } catch (err) {
        setPaymentStatus('FAILED');
        alert("Server validation failed. Refund initiated if amount deducted.");
      }
    } else {
      setPaymentStatus('FAILED');
      alert("Payment cancelled or failed by Gateway. Please try again.");
    }
  };

  const handleAdminAccess = () => {
    const pass = prompt("Access Restricted. Enter Admin Key:");
    if (pass === 'admin123') setIsAdminMode(true);
    else if (pass !== null) alert("Unauthorized Access Attempt Logged.");
  };

  if (isAdminMode) {
    return (
      <AdminPanel 
        user={{ name: 'Admin', role: UserRole.ADMIN } as User}
        menuItems={menuItems}
        setMenuItems={setMenuItems}
        orders={orders}
        onLogout={() => setIsAdminMode(false)}
        onMenuUpdate={() => {}}
        cms={null} setCms={null} setOrders={setOrders}
      />
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-slate-50">
      {/* PROFESSIONAL NAVBAR */}
      <nav className="fixed top-0 inset-x-0 z-50 h-20 bg-white/80 backdrop-blur-xl border-b border-slate-200/50 px-6 lg:px-12 flex justify-between items-center no-print">
        <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-12 h-12 bg-red-600 rounded-2xl flex items-center justify-center text-white font-black text-2xl shadow-xl shadow-red-600/20 group-hover:scale-105 transition-transform">B</div>
          <div className="hidden sm:block">
            <h1 className="text-xl font-extrabold text-slate-900 tracking-tight leading-none">BFC</h1>
            <p className="text-[10px] font-bold text-red-600 uppercase tracking-widest mt-1">Bangla Food Club</p>
          </div>
        </div>

        <div className="flex items-center gap-2 md:gap-8">
          <button onClick={() => setView('MENU')} className={`text-sm font-bold transition-all px-4 py-2 rounded-xl ${view === 'MENU' ? 'bg-red-50 text-red-600' : 'text-slate-500 hover:text-red-600 hover:bg-red-50'}`}>Menu</button>
          <button onClick={() => setView('CART')} className="relative p-3 bg-slate-100 rounded-2xl text-slate-600 hover:text-red-600 hover:bg-red-50 transition-all">
            <i className="fas fa-shopping-bag text-xl"></i>
            {cart.length > 0 && (
              <span className="absolute -top-1 -right-1 w-6 h-6 bg-red-600 text-white text-[11px] rounded-full flex items-center justify-center border-2 border-white font-black animate-bounce">{cart.length}</span>
            )}
          </button>
          <button onClick={handleAdminAccess} className="p-3 text-slate-300 hover:text-slate-900 transition-colors">
             <i className="fas fa-sliders-h"></i>
          </button>
        </div>
      </nav>

      <main className="flex-1 pt-20">
        {view === 'HOME' && (
          <div className="animate-in hero-bg min-h-[85vh] flex flex-col items-center justify-center px-6 text-center">
            <span className="px-6 py-2 bg-red-50 text-red-600 text-[10px] font-black uppercase tracking-[4px] rounded-full mb-8 border border-red-100">Premium Quality • 2024</span>
            <h2 className="text-5xl md:text-8xl font-black text-slate-900 mb-8 leading-[1.1] tracking-tighter">
              Original Taste. <br/>
              <span className="text-red-600">Freshly Made.</span>
            </h2>
            <p className="text-slate-500 max-w-2xl mb-12 text-lg md:text-xl font-medium leading-relaxed">Discover the authentic flavors of Dhaka. We bring you the finest fried chicken and snacks prepared with secret traditional recipes.</p>
            <div className="flex flex-col sm:flex-row gap-5 w-full sm:w-auto">
              <Button size="lg" onClick={() => setView('MENU')} className="px-16 py-6 text-lg rounded-3xl shadow-2xl shadow-red-600/30">Order Now</Button>
              <Button variant="outline" size="lg" onClick={() => setView('MENU')} className="px-16 py-6 text-lg rounded-3xl !border-slate-200 !text-slate-900 hover:!bg-slate-50">View Catalog</Button>
            </div>
          </div>
        )}

        {view === 'MENU' && (
          <div className="animate-in max-w-7xl mx-auto px-6 py-16">
            <div className="flex flex-col md:flex-row justify-between items-end gap-10 mb-16">
              <div>
                <h2 className="text-5xl font-black text-slate-900 mb-4 tracking-tighter">Explore Menu</h2>
                <p className="text-slate-400 font-medium">Select from our chef's special hand-picked categories.</p>
              </div>
              <div className="flex gap-3 overflow-x-auto no-scrollbar w-full md:w-auto pb-4 md:pb-0">
                {categories.map(cat => (
                  <button 
                    key={cat} 
                    onClick={() => setActiveCategory(cat)}
                    className={`px-8 py-3.5 rounded-2xl text-xs font-black transition-all whitespace-nowrap uppercase tracking-widest ${activeCategory === cat ? 'bg-red-600 text-white shadow-xl shadow-red-600/20' : 'bg-white text-slate-400 border border-slate-100 hover:border-red-200 hover:text-red-600'}`}
                  >
                    {cat}
                  </button>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-10">
              {filteredMenu.map(item => (
                <div key={item.id} className="bg-white rounded-[40px] overflow-hidden card-shadow group border border-white flex flex-col hover:border-red-50 transition-all">
                  <div className="h-64 overflow-hidden relative">
                    <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" alt={item.name} />
                    <div className="absolute top-6 right-6 bg-white/95 backdrop-blur shadow-xl px-5 py-2 rounded-2xl text-sm font-black text-red-600">৳{item.price}</div>
                    {item.stock === 0 && (
                      <div className="absolute inset-0 bg-white/70 backdrop-blur-sm flex items-center justify-center">
                        <span className="text-red-700 font-black uppercase text-xs tracking-[4px]">Out of Stock</span>
                      </div>
                    )}
                  </div>
                  <div className="p-8 flex flex-col flex-1">
                    <div className="flex justify-between items-start mb-2">
                      <h4 className="text-xl font-black text-slate-900 leading-none">{item.nameBn}</h4>
                      {item.isPopular && <i className="fas fa-crown text-amber-400 text-sm"></i>}
                    </div>
                    <p className="text-[10px] text-slate-400 mb-8 uppercase font-bold tracking-[3px]">{item.name}</p>
                    <div className="mt-auto">
                        <Button fullWidth size="md" disabled={item.stock === 0} onClick={() => addToCart(item)} className="rounded-[22px]">Add to Cart</Button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="animate-in max-w-5xl mx-auto px-6 py-16 flex flex-col lg:flex-row gap-12">
            <div className="flex-1">
              <h2 className="text-5xl font-black text-slate-900 mb-12 tracking-tighter">Your Bag</h2>
              {cart.length > 0 ? (
                <div className="bg-white rounded-[48px] p-8 md:p-12 card-shadow border border-slate-50 divide-y divide-slate-100">
                  {cart.map(c => (
                    <div key={c.item.id} className="py-8 flex items-center justify-between first:pt-0 last:pb-0">
                      <div className="flex items-center gap-8">
                        <div className="w-24 h-24 rounded-3xl overflow-hidden shadow-lg">
                          <img src={c.item.image} className="w-full h-full object-cover" alt={c.item.name} />
                        </div>
                        <div>
                          <h4 className="font-black text-slate-900 text-xl leading-none mb-2">{c.item.nameBn}</h4>
                          <p className="text-sm font-bold text-slate-400">৳{c.item.price} per unit</p>
                        </div>
                      </div>
                      <div className="flex items-center gap-6">
                        <button onClick={() => removeFromCart(c.item.id)} className="w-12 h-12 rounded-2xl bg-slate-50 flex items-center justify-center text-slate-400 hover:bg-red-50 hover:text-red-600 transition-all">
                          <i className="fas fa-minus text-xs"></i>
                        </button>
                        <span className="font-black w-8 text-center text-xl text-slate-900">{c.qty}</span>
                        <button onClick={() => addToCart(c.item)} className="w-12 h-12 rounded-2xl bg-slate-50 flex items-center justify-center text-slate-400 hover:bg-red-50 hover:text-red-600 transition-all">
                          <i className="fas fa-plus text-xs"></i>
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-24 bg-white rounded-[48px] border-2 border-dashed border-slate-100">
                  <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-8 text-slate-200">
                      <i className="fas fa-shopping-bag text-4xl"></i>
                  </div>
                  <p className="text-slate-400 mb-10 text-xl font-medium">Your bag is currently empty.</p>
                  <Button variant="outline" onClick={() => setView('MENU')} className="px-12 rounded-2xl">Start Shopping</Button>
                </div>
              )}
            </div>

            {cart.length > 0 && (
              <div className="w-full lg:w-[400px] shrink-0">
                <div className="bg-white rounded-[48px] p-10 card-shadow border border-slate-50 sticky top-32">
                  <h3 className="text-2xl font-black text-slate-900 mb-8">Summary</h3>
                  <div className="space-y-4 mb-10">
                    <div className="flex justify-between text-slate-500 font-medium">
