const DB_KEYS = {
  MENU: 'bfc_elite_menu_v3',
  ORDERS: 'bfc_elite_orders_v3',
  LOGS: 'bfc_elite_audit_logs_v3',
  CUSTOMERS: 'bfc_elite_customers_v3',
  SESSION: 'bfc_current_user_v3'
};

// Initial Data Setup
if (!localStorage.getItem(DB_KEYS.MENU)) localStorage.setItem(DB_KEYS.MENU, JSON.stringify(MOCK_MENU));
if (!localStorage.getItem(DB_KEYS.ORDERS)) localStorage.setItem(DB_KEYS.ORDERS, JSON.stringify([]));
if (!localStorage.getItem(DB_KEYS.LOGS)) localStorage.setItem(DB_KEYS.LOGS, JSON.stringify([]));
if (!localStorage.getItem(DB_KEYS.CUSTOMERS)) {
  const defaultUser: User = {
    id: 'U1',
    name: 'Admin User',
    username: 'admin',
    email: 'admin@bfc.com',
    phone: '01712345678',
