export const API = {
  // --- Auth ---
  async login(phone: string, otp: string): Promise<User | null> {
    // Simulated OTP verification
    if (otp === '1234') {
      const customers: User[] = JSON.parse(localStorage.getItem(DB_KEYS.CUSTOMERS) || '[]');
      let user = customers.find(c => c.phone === phone);
      if (!user) {
        user = {
          id: `U${Date.now()}`,
          name: 'New Customer',
          username: `user_${Date.now()}`,
          email: '',
          phone,
          address: '',
          gender: 'OTHER',
          role: UserRole.CUSTOMER,
          loyaltyPoints: 0,
          tier: 'BRONZE',
          createdAt: new Date().toISOString()
        };
        localStorage.setItem(DB_KEYS.CUSTOMERS, JSON.stringify([...customers, user]));
      }
      localStorage.setItem(DB_KEYS.SESSION, JSON.stringify(user));
      return user;
    }
    return null;
  },

  getCurrentUser(): User | null {
    const session = localStorage.getItem(DB_KEYS.SESSION);
    return session ? JSON.parse(session) : null;
  },

  logout() {
    localStorage.removeItem(DB_KEYS.SESSION);
    this.broadcast('AUTH_CHANGE');
  },

  // --- Menu ---
  async getMenu(): Promise<MenuItem[]> {
    return JSON.parse(localStorage.getItem(DB_KEYS.MENU) || '[]');
  },

  async updateMenuItem(item: MenuItem, adminName: string): Promise<void> {
    const menu = await this.getMenu();
    const updated = menu.map(m => m.id === item.id ? item : m);
    localStorage.setItem(DB_KEYS.MENU, JSON.stringify(updated));
    await this.addLog('MENU_UPDATE', adminName, `Modified ${item.name}: ৳${item.price}`);
    this.broadcast('SYNC_DATA');
  },

  // --- Orders ---
  async getOrders(): Promise<Order[]> {
    return JSON.parse(localStorage.getItem(DB_KEYS.ORDERS) || '[]');
  },

  async placeOrder(order: Order): Promise<void> {
    const orders = await this.getOrders();
    localStorage.setItem(DB_KEYS.ORDERS, JSON.stringify([order, ...orders]));
    this.broadcast('NEW_ORDER');
  },

  async updateOrderStatus(orderId: string, status: OrderStatus, adminName: string): Promise<void> {
    const orders = await this.getOrders();
    const updated = orders.map(o => o.id === orderId ? { ...o, status } : o);
    localStorage.setItem(DB_KEYS.ORDERS, JSON.stringify(updated));
    await this.addLog('ORDER_STATUS', adminName, `Order ${orderId} status: ${status}`);
    this.broadcast('SYNC_DATA');
  },

  // --- Analytics ---
  async getAnalytics(): Promise<Analytics> {
    const orders = await this.getOrders();
    const totalSales = orders.filter(o => o.status !== OrderStatus.CANCELLED).reduce((acc, o) => acc + o.total, 0);
    const last7Days = [...Array(7)].map((_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      const dateStr = d.toISOString().split('T')[0];
      const dayTotal = orders
        .filter(o => o.createdAt.startsWith(dateStr) && o.status !== OrderStatus.CANCELLED)
        .reduce((acc, o) => acc + o.total, 0);
      return { date: dateStr, amount: dayTotal };
    }).reverse();

    return {
      totalSales,
      totalOrders: orders.length,
      averageOrderValue: orders.length ? totalSales / orders.length : 0,
      salesByDay: last7Days
    };
  },

  async getCustomers(): Promise<User[]> {
    return JSON.parse(localStorage.getItem(DB_KEYS.CUSTOMERS) || '[]');
  },

  async addLog(action: string, user: string, details: string): Promise<void> {
    const logs: AuditLog[] = JSON.parse(localStorage.getItem(DB_KEYS.LOGS) || '[]');
    const newLog: AuditLog = {
      id: `LOG-${Date.now()}`,
      action,
      user,
      details,
      timestamp: new Date().toISOString()
    };
    localStorage.setItem(DB_KEYS.LOGS, JSON.stringify([newLog, ...logs.slice(0, 99)]));
  },

  broadcast(type: string) {
    window.dispatchEvent(new CustomEvent('BFC_SYNC', { detail: { type } }));
  },

  subscribe(callback: (event: any) => void) {
    window.addEventListener('BFC_SYNC', (e: any) => callback(e.detail));
  }
};

