  DELIVERED = 'DELIVERED',
  CANCELLED = 'CANCELLED',
  FAILED = 'FAILED'
}

export interface User {
  id: string;
  name: string;
  username: string;
  email: string;
  phone: string;
  address: string;
  gender: 'MALE' | 'FEMALE' | 'OTHER';
  role: UserRole;
  loyaltyPoints: number;
  tier: 'ELITE' | 'GOLD' | 'SILVER' | 'BRONZE';
  createdAt: string;
}

export interface MenuItem {
  id: string;
  name: string;
  nameBn: string;
  description: string;
  price: number;
  category: string;
  image: string;
  stock: number;
  isPopular?: boolean;
}

export interface CartItem {
  item: MenuItem;
  qty: number;
}

export type PaymentMethod = 'BKASH' | 'NAGAD' | 'ROCKET' | 'VISA' | 'MASTER' | 'COD';

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  customerPhone: string;
  address: string;
  items: CartItem[];
  subtotal: number;
  deliveryCharge: number;
  total: number;
  status: OrderStatus;
  paymentMethod: PaymentMethod;
  transactionId: string;
  createdAt: string;
  paymentStatus: 'UNPAID' | 'PAID' | 'REFUNDED';
}

export type ViewState = 'HOME' | 'MENU' | 'CART' | 'CHECKOUT' | 'PAYMENT' | 'RECEIPT' | 'ADMIN' | 'LOGIN' | 'PROFILE' | 'TRACK_ORDERS' | 'GATEWAY';

export interface Analytics {
  totalSales: number;
  totalOrders: number;
  averageOrderValue: number;
  salesByDay: { date: string, amount: number }[];
}

export interface AuditLog {
  id: string;
  action: string;
  user: string;
  details: string;
  timestamp: string;
}

export interface MenuUpdate {
  type: 'PRICE_CHANGE' | 'AVAILABILITY' | 'ADD' | 'DELETE';
  itemName: string;
  details: string;
  timestamp: Date;
}

import React, { useState, useEffect, useMemo } from 'react';
import { MenuItem, UserRole, User, Order, CartItem, OrderStatus, ViewState, PaymentMethod } from './types';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { API } from './services/api';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('HOME');
  const [currentUser, setCurrentUser] = useState<User | null>(API.getCurrentUser());
  const [menuItems, setMenuItems] = useState<MenuItem[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [activeCategory, setActiveCategory] = useState('All');

  // Login State
  const [loginForm, setLoginForm] = useState({ phone: '', otp: '' });
  const [otpSent, setOtpSent] = useState(false);

  // Checkout State
  const [checkoutInfo, setCheckoutInfo] = useState({ 
    name: currentUser?.name || '', 
    phone: currentUser?.phone || '', 
    address: currentUser?.address || '' 
  });
  const [selectedPayment, setSelectedPayment] = useState<PaymentMethod>('BKASH');
  const [gatewayProcessing, setGatewayProcessing] = useState(false);
  const [lastOrder, setLastOrder] = useState<Order | null>(null);

  useEffect(() => {
    const init = async () => {
      setMenuItems(await API.getMenu());
      setOrders(await API.getOrders());
    };
    init();

    const unsub = API.subscribe(async (e) => {
      setOrders(await API.getOrders());
      setMenuItems(await API.getMenu());
      if (e.type === 'NEW_ORDER' && currentUser?.role === UserRole.ADMIN) {
        if ('Notification' in window && Notification.permission === 'granted') {
          new Notification('BFC New Order', { body: 'A new order has been received!' });
        }
      }
    });

    if ('Notification' in window && Notification.permission === 'default') {
      Notification.requestPermission();
    }

    return unsub;
  }, [currentUser]);

  const categories = useMemo(() => ['All', ...new Set(menuItems.map(item => item.category))], [menuItems]);
  const filteredMenu = useMemo(() => activeCategory === 'All' ? menuItems : menuItems.filter(i => i.category === activeCategory), [menuItems, activeCategory]);
  const subtotal = useMemo(() => cart.reduce((acc, c) => acc + (c.item.price * c.qty), 0), [cart]);
  const deliveryCharge = 50;
  const totalPayable = subtotal + deliveryCharge;

  const addToCart = (item: MenuItem) => {
    if (item.stock === 0) return;
    setCart(prev => {
      const existing = prev.find(i => i.item.id === item.id);
      if (existing) return prev.map(i => i.item.id === item.id ? { ...i, qty: i.qty + 1 } : i);
      return [...prev, { item, qty: 1 }];
    });
  };

  const removeFromCart = (itemId: string) => {
    setCart(prev => {
      const existing = prev.find(i => i.item.id === itemId);
      if (existing && existing.qty > 1) return prev.map(i => i.item.id === itemId ? { ...i, qty: i.qty - 1 } : i);
      return prev.filter(i => i.item.id !== itemId);
    });
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!otpSent) {
      if (!loginForm.phone.match(/^01[3-9]\d{8}$/)) {
        alert("Please enter a valid BD phone number.");
        return;
      }
      setOtpSent(true);
      // Simulate real SMS behavior
      console.log("OTP Sent: 1234");
      return;
    }
    const user = await API.login(loginForm.phone, loginForm.otp);
    if (user) {
      setCurrentUser(user);
      setCheckoutInfo({ name: user.name, phone: user.phone, address: user.address });
      setView('HOME');
    } else {
      alert("Invalid OTP. Try 1234");
    }
  };

  const handleLogout = () => {
    API.logout();
    setCurrentUser(null);
    setView('HOME');
  };

  const goToGateway = (e: React.FormEvent) => {
    e.preventDefault();
    if (cart.length === 0) return;
    setView('GATEWAY');
  };

  const processPayment = async () => {
    setGatewayProcessing(true);
    // Simulated SSLCommerz / Shurjopay delay
    await new Promise(r => setTimeout(r, 2500));

    const orderId = `BFC-${Date.now().toString().slice(-6)}`;
    const newOrder: Order = {
      id: orderId,
      customerId: currentUser?.id || 'GUEST',
      customerName: checkoutInfo.name,
      customerPhone: checkoutInfo.phone,
      address: checkoutInfo.address,
      items: [...cart],
      subtotal,
      deliveryCharge,
      total: totalPayable,
      status: selectedPayment === 'COD' ? OrderStatus.PENDING : OrderStatus.PAID,
      paymentMethod: selectedPayment,
      transactionId: selectedPayment === 'COD' ? '' : `TXN-${Math.random().toString(36).toUpperCase().slice(2, 10)}`,
      createdAt: new Date().toISOString(),
      paymentStatus: selectedPayment === 'COD' ? 'UNPAID' : 'PAID'
    };

    await API.placeOrder(newOrder);
    setLastOrder(newOrder);
    setCart([]);
    setGatewayProcessing(false);
    setView('RECEIPT');
  };

  // Nav Components
  const Navbar = () => (
    <nav className="fixed top-0 inset-x-0 z-50 h-20 bg-white/90 backdrop-blur-xl border-b border-slate-100 px-6 lg:px-12 flex justify-between items-center no-print">
      <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setView('HOME')}>
        <div className="w-12 h-12 bg-red-600 rounded-2xl flex items-center justify-center text-white font-black text-2xl shadow-xl shadow-red-600/20 group-hover:rotate-6 transition-all">B</div>
        <div className="hidden sm:block">
          <h1 className="text-xl font-black text-slate-900 leading-none">BFC</h1>
          <p className="text-[10px] font-bold text-red-600 uppercase tracking-widest mt-1">Bangla Food Club</p>
        </div>
      </div>
      <div className="flex items-center gap-2 md:gap-8">
        <button onClick={() => setView('MENU')} className={`text-sm font-bold transition-all px-4 py-2 rounded-xl ${view === 'MENU' ? 'bg-red-50 text-red-600' : 'text-slate-500 hover:text-red-600 hover:bg-red-50'}`}>Menu</button>
        {currentUser && <button onClick={() => setView('TRACK_ORDERS')} className={`text-sm font-bold transition-all px-4 py-2 rounded-xl ${view === 'TRACK_ORDERS' ? 'bg-red-50 text-red-600' : 'text-slate-500 hover:text-red-600'}`}>Track</button>}

        <button onClick={() => setView('CART')} className="relative p-3 bg-slate-100 rounded-2xl text-slate-600 hover:text-red-600 hover:bg-red-50 transition-all">
          <i className="fas fa-shopping-bag text-xl"></i>
          {cart.length > 0 && <span className="absolute -top-1 -right-1 w-6 h-6 bg-red-600 text-white text-[10px] rounded-full flex items-center justify-center border-2 border-white font-black animate-bounce">{cart.length}</span>}
        </button>

        {currentUser ? (
          <button onClick={() => setView('PROFILE')} className="w-12 h-12 rounded-2xl bg-slate-100 border-2 border-transparent hover:border-red-600 transition-all overflow-hidden">
             <img src={`https://ui-avatars.com/api/?name=${currentUser.name}&background=dc2626&color=fff`} className="w-full h-full object-cover" alt="Profile" />
          </button>
        ) : (
          <Button size="sm" onClick={() => setView('LOGIN')} className="rounded-2xl">Login</Button>
        )}

        <button onClick={() => currentUser?.role === UserRole.ADMIN ? setView('ADMIN') : alert('Settings - (Profile details and preferences accessible in Profile View)')} className="p-3 text-slate-300 hover:text-slate-900 transition-colors">
          <i className="fas fa-cog"></i>
        </button>
      </div>
    </nav>
  );

  if (view === 'ADMIN' && currentUser?.role === UserRole.ADMIN) {
    return <AdminPanel 
      user={currentUser}
      menuItems={menuItems} 
      setMenuItems={setMenuItems} 
      orders={orders} 
      onLogout={() => setView('HOME')} 
      onMenuUpdate={() => {}}
      cms={null} setCms={null} setOrders={setOrders}
    />;
  }

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 font-sans selection:bg-red-100 selection:text-red-600">
      <Navbar />
      <main className="flex-1 pt-20">

        {view === 'HOME' && (
          <div className="animate-in h-[85vh] flex flex-col items-center justify-center px-6 text-center">
            <span className="px-6 py-2 bg-red-50 text-red-600 text-[10px] font-black uppercase tracking-[5px] rounded-full mb-8 border border-red-100">Premium Quality • 2024</span>
            <h2 className="text-5xl md:text-8xl font-black text-slate-900 mb-8 leading-[1.1] tracking-tighter">
              Authentic Taste. <br/><span className="text-red-600">Purely Bengali.</span>
            </h2>
            <p className="text-slate-500 max-w-xl mb-12 text-lg font-medium leading-relaxed">The finest fried chicken and snacks prepared with secret traditional recipes. Delivered right to your doorstep in Dhaka.</p>
            <div className="flex flex-col sm:flex-row gap-5">
              <Button size="lg" onClick={() => setView('MENU')} className="px-16 py-6 text-lg rounded-3xl shadow-2xl shadow-red-600/30">Order Now</Button>
              <Button variant="outline" size="lg" onClick={() => setView('MENU')} className="px-16 py-6 text-lg rounded-3xl !border-slate-200 !text-slate-900 hover:!bg-slate-50">Browse Menu</Button>
            </div>
          </div>
        )}

        {view === 'LOGIN' && (
          <div className="animate-in max-w-md mx-auto px-6 py-20">
            <div className="bg-white rounded-[48px] p-10 md:p-14 shadow-2xl border border-slate-100 text-center">
              <div className="w-16 h-16 bg-red-600 rounded-3xl flex items-center justify-center text-white text-3xl font-black mx-auto mb-8 shadow-xl shadow-red-600/20">B</div>
              <h2 className="text-3xl font-black text-slate-900 mb-2">Welcome Back</h2>
              <p className="text-slate-400 font-medium mb-10">Enter your number to sign in</p>
              <form onSubmit={handleLogin} className="space-y-6">
                <div>
                  <input 
                    required type="tel" 
                    value={loginForm.phone}
                    onChange={e => setLoginForm({...loginForm, phone: e.target.value})}
                    placeholder="Phone Number (01XXXXXXXXX)" 
                    disabled={otpSent}
                    className="w-full px-8 py-5 rounded-[22px] bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-100 transition-all font-bold text-slate-900 text-center"
                  />
                </div>
                {otpSent && (
                  <div className="animate-in">
                    <input 
                      required type="text" 
                      value={loginForm.otp}
                      onChange={e => setLoginForm({...loginForm, otp: e.target.value})}
                      placeholder="Enter 4-digit OTP" 
                      maxLength={4}
                      className="w-full px-8 py-5 rounded-[22px] bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-100 transition-all font-bold text-slate-900 text-center tracking-[1em]"
                    />
                    <p className="text-[10px] text-slate-400 mt-4 font-bold uppercase tracking-widest">Didn't get it? <button type="button" onClick={() => setOtpSent(false)} className="text-red-600">Resend</button></p>
                  </div>
                )}
                <Button fullWidth size="lg" className="rounded-3xl py-6">{otpSent ? 'Verify & Continue' : 'Send Code'}</Button>
              </form>
            </div>
          </div>
        )}

        {view === 'MENU' && (
          <div className="animate-in max-w-7xl mx-auto px-6 py-12">
            <div className="flex flex-col md:flex-row justify-between items-end gap-10 mb-16">
              <div>
                <h2 className="text-5xl font-black text-slate-900 mb-4 tracking-tighter">Our Menu</h2>
                <p className="text-slate-400 font-medium">Authentic flavors hand-crafted for you.</p>
              </div>
              <div className="flex gap-3 overflow-x-auto no-scrollbar w-full md:w-auto pb-4 md:pb-0">
                {categories.map(cat => (
                  <button 
                    key={cat} 
                    onClick={() => setActiveCategory(cat)}
                    className={`px-8 py-3.5 rounded-2xl text-xs font-black transition-all whitespace-nowrap uppercase tracking-widest ${activeCategory === cat ? 'bg-red-600 text-white shadow-xl shadow-red-600/20' : 'bg-white text-slate-400 border border-slate-100 hover:border-red-200 hover:text-red-600'}`}
                  >
                    {cat}
                  </button>
                ))}
              </div>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-10">
              {filteredMenu.map(item => (
                <div key={item.id} className="bg-white rounded-[40px] overflow-hidden card-shadow group border border-white flex flex-col hover:border-red-50 transition-all">
                  <div className="h-64 overflow-hidden relative">
                    <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" alt={item.name} />
                    <div className="absolute top-6 right-6 bg-white/95 backdrop-blur shadow-xl px-5 py-2 rounded-2xl text-sm font-black text-red-600">৳{item.price}</div>
                    {item.stock === 0 && <div className="absolute inset-0 bg-white/70 flex items-center justify-center"><span className="text-red-700 font-black uppercase text-xs tracking-widest">Sold Out</span></div>}
                  </div>
                  <div className="p-8 flex flex-col flex-1">
                    <h4 className="text-xl font-black text-slate-900 mb-1 leading-none">{item.nameBn}</h4>
                    <p className="text-[10px] text-slate-400 mb-8 uppercase font-bold tracking-widest">{item.name}</p>
                    <Button fullWidth size="md" disabled={item.stock === 0} onClick={() => addToCart(item)} className="rounded-[22px]">Add to Cart</Button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="animate-in max-w-4xl mx-auto px-6 py-12">
            <h2 className="text-5xl font-black text-slate-900 mb-12 tracking-tighter">Your Bag</h2>
            {cart.length > 0 ? (
              <div className="grid lg:grid-cols-3 gap-12">
                <div className="lg:col-span-2 space-y-6">
                  <div className="bg-white rounded-[48px] p-8 md:p-10 shadow-2xl border border-slate-50 divide-y divide-slate-100">
                    {cart.map(c => (
                      <div key={c.item.id} className="py-8 flex items-center justify-between first:pt-0 last:pb-0">
                        <div className="flex items-center gap-6">
                          <img src={c.item.image} className="w-20 h-20 rounded-2xl object-cover shadow-lg" alt={c.item.name} />
                          <div>
                            <h4 className="font-black text-slate-900 text-lg leading-none mb-1">{c.item.nameBn}</h4>
                            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">৳{c.item.price}</p>
                          </div>
                        </div>
                        <div className="flex items-center gap-5">
                          <button onClick={() => removeFromCart(c.item.id)} className="w-10 h-10 rounded-xl bg-slate-50 flex items-center justify-center text-slate-400 hover:bg-red-50 hover:text-red-600 transition-all"><i className="fas fa-minus text-xs"></i></button>
                          <span className="font-black w-6 text-center text-lg">{c.qty}</span>
                          <button onClick={() => addToCart(c.item)} className="w-10 h-10 rounded-xl bg-slate-50 flex items-center justify-center text-slate-400 hover:bg-red-50 hover:text-red-600 transition-all"><i className="fas fa-plus text-xs"></i></button>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
                <div className="bg-white rounded-[48px] p-10 shadow-2xl border border-slate-50 h-fit space-y-8">
                  <h3 className="text-2xl font-black text-slate-900">Summary</h3>
                  <div className="space-y-4 text-slate-500 font-bold text-sm uppercase tracking-widest">
                    <div className="flex justify-between"><span>Subtotal</span><span>৳{subtotal}</span></div>
                    <div className="flex justify-between"><span>Delivery</span><span>৳{deliveryCharge}</span></div>
                    <div className="border-t border-slate-100 pt-6 flex justify-between text-2xl text-slate-900">
                      <span>Total</span><span className="text-red-600">৳{totalPayable}</span>
                    </div>
                  </div>
                  <Button fullWidth size="lg" className="py-6 rounded-3xl" onClick={() => setView('CHECKOUT')}>Checkout</Button>
                </div>
              </div>
            ) : (
              <div className="text-center py-24 bg-white rounded-[48px] border-2 border-dashed border-slate-200">
                <i className="fas fa-shopping-bag text-6xl text-slate-100 mb-8"></i>
                <p className="text-slate-400 font-bold mb-10">Your bag is empty.</p>
                <Button variant="outline" onClick={() => setView('MENU')}>Start Ordering</Button>
              </div>
            )}
          </div>
        )}

        {view === 'CHECKOUT' && (
          <div className="animate-in max-w-2xl mx-auto px-6 py-12">
            <h2 className="text-5xl font-black text-slate-900 mb-12 tracking-tighter">Checkout</h2>
            <form onSubmit={goToGateway} className="space-y-8">
              <div className="bg-white rounded-[48px] p-10 md:p-14 shadow-2xl border border-slate-50 space-y-8">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Full Name</label>
                  <input 
                    required type="text" 
                    value={checkoutInfo.name}
                    onChange={e => setCheckoutInfo({...checkoutInfo, name: e.target.value})}
                    placeholder="Recipient Name" 
                    className="w-full px-8 py-5 rounded-[22px] bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-100 transition-all font-bold text-slate-900"
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Contact Phone</label>
                  <input 
                    required type="tel" 
                    value={checkoutInfo.phone}
                    onChange={e => setCheckoutInfo({...checkoutInfo, phone: e.target.value})}
                    placeholder="01XXXXXXXXX" 
                    className="w-full px-8 py-5 rounded-[22px] bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-100 transition-all font-bold text-slate-900"
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Delivery Address</label>
                  <textarea 
                    required 
                    value={checkoutInfo.address}
                    onChange={e => setCheckoutInfo({...checkoutInfo, address: e.target.value})}
                    placeholder="Area, Street, House No." 
                    rows={4}
                    className="w-full px-8 py-6 rounded-[22px] bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-100 transition-all font-bold text-slate-900 resize-none"
                  ></textarea>
                </div>
              </div>
              <div className="flex gap-6">
                <Button variant="outline" className="flex-1 py-6 rounded-3xl" onClick={() => setView('CART')}>Edit Bag</Button>
                <Button type="submit" className="flex-1 py-6 rounded-3xl">Proceed to Pay</Button>
              </div>
            </form>
          </div>
        )}

        {view === 'GATEWAY' && (
          <div className="animate-in max-w-4xl mx-auto px-6 py-12">
            <h2 className="text-5xl font-black text-slate-900 mb-12 tracking-tighter">Secure Payment</h2>
            <div className="bg-white rounded-[64px] p-10 md:p-16 shadow-2xl border border-slate-50">
              <div className="grid md:grid-cols-2 gap-12">
                <div className="space-y-6">
                  <h3 className="text-xl font-black text-slate-900">Choose Method</h3>
                  <div className="grid grid-cols-2 gap-4">
                    {[
                      { id: 'BKASH', name: 'bKash', icon: 'fa-mobile-screen', color: 'text-pink-600' },
                      { id: 'NAGAD', name: 'Nagad', icon: 'fa-money-bill-transfer', color: 'text-orange-600' },
                      { id: 'ROCKET', name: 'Rocket', icon: 'fa-bolt-lightning', color: 'text-purple-600' },
                      { id: 'VISA', name: 'Card', icon: 'fa-credit-card', color: 'text-blue-600' },
                      { id: 'COD', name: 'Cash', icon: 'fa-hand-holding-dollar', color: 'text-slate-600' }
                    ].map((method) => (
                      <div key={method.id}>
                        <input 
                          type="radio" id={method.id} name="pm" className="hidden payment-radio"
                          checked={selectedPayment === method.id}
                          onChange={() => setSelectedPayment(method.id as PaymentMethod)}
                        />
                        <label 
                          htmlFor={method.id}
                          className="flex flex-col items-center justify-center gap-3 p-6 rounded-[32px] border-2 border-slate-50 cursor-pointer transition-all hover:bg-slate-50"
                        >
                          <i className={`fas ${method.icon} text-2xl ${method.color}`}></i>
                          <span className="font-black text-slate-900 text-[10px] uppercase tracking-widest">{method.name}</span>
                        </label>
                      </div>
                    ))}
                  </div>
                </div>
                <div className="bg-slate-50 p-10 rounded-[48px] space-y-8 flex flex-col justify-center">
                  <div className="space-y-4">
                    <div className="flex justify-between text-slate-400 font-black text-[10px] uppercase tracking-widest"><span>Order Total</span><span>৳{totalPayable}</span></div>
                    <div className="h-px bg-slate-200"></div>
                    <div className="text-center py-4">
                      <p className="text-4xl font-black text-slate-900">৳{totalPayable}</p>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-2">Inclusive of all taxes</p>
                    </div>
                  </div>
                  <Button 
                    fullWidth size="lg" className="py-7 rounded-[32px]" 
                    disabled={gatewayProcessing}
                    onClick={processPayment}
                  >
                    {gatewayProcessing ? (
                      <span className="flex items-center gap-4"><i className="fas fa-circle-notch animate-spin"></i> Processing...</span>
                    ) : (
                      `Pay via ${selectedPayment}`
                    )}
                  </Button>
                </div>
              </div>
            </div>
          </div>
        )}

        {view === 'RECEIPT' && lastOrder && (
          <div className="animate-in max-w-2xl mx-auto px-6 py-12">
            <div className="bg-white rounded-[56px] p-12 md:p-16 shadow-2xl border border-slate-50 print-area relative overflow-hidden">
              <div className="absolute top-0 inset-x-0 h-2 bg-red-600"></div>
              <div className="text-center mb-12">
                <div className="w-16 h-16 bg-red-600 rounded-2xl flex items-center justify-center text-white font-black text-2xl mx-auto mb-6">B</div>
                <h2 className="text-2xl font-black text-slate-900">Official Receipt</h2>
                <div className="mt-2 flex items-center justify-center gap-2 text-emerald-500 font-black text-[10px] uppercase tracking-widest">
                  <i className="fas fa-check-circle"></i> Order Confirmed
