              </div>

              <div className="grid grid-cols-2 gap-8 mb-12 text-[10px] uppercase tracking-widest font-black text-slate-400">
                <div>
                  <p className="mb-1 opacity-50">Invoice ID</p>
                  <p className="text-slate-900">{lastOrder.id}</p>
                </div>
                <div className="text-right">
                  <p className="mb-1 opacity-50">Date</p>
                  <p className="text-slate-900">{new Date(lastOrder.createdAt).toLocaleDateString()}</p>
                </div>
              </div>

              <div className="space-y-6 mb-12 border-t border-b border-slate-50 py-10">
                {lastOrder.items.map((c, i) => (
                  <div key={i} className="flex justify-between items-center text-sm">
                    <div className="flex items-center gap-4">
                      <span className="w-6 h-6 bg-slate-50 rounded flex items-center justify-center text-[10px] font-black text-slate-400">{c.qty}</span>
                      <span className="font-black text-slate-900 uppercase">{c.item.nameBn}</span>
                    </div>
                    <span className="font-black text-slate-900">৳{c.item.price * c.qty}</span>
                  </div>
                ))}
              </div>

              <div className="space-y-4 mb-12">
                <div className="flex justify-between text-slate-400 font-black uppercase text-[10px] tracking-widest"><span>Subtotal</span><span>৳{lastOrder.subtotal}</span></div>
                <div className="flex justify-between text-slate-400 font-black uppercase text-[10px] tracking-widest"><span>Delivery</span><span>৳{lastOrder.deliveryCharge}</span></div>
                <div className="flex justify-between text-3xl font-black text-red-600 pt-6 border-t border-slate-50"><span>Total</span><span>৳{lastOrder.total}</span></div>
              </div>

              <div className="bg-slate-50 p-10 rounded-[40px] text-center mb-12">
                <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-2">Payment Method</p>
                <p className="font-black text-slate-900 text-lg uppercase">{lastOrder.paymentMethod}</p>
                {lastOrder.transactionId && <p className="text-[10px] font-mono text-emerald-500 mt-2">REF: {lastOrder.transactionId}</p>}
