              </div>
            </div>
          </div>
        )}

        {view === 'PROFILE' && currentUser && (
          <div className="animate-in max-w-4xl mx-auto px-6 py-12">
            <div className="grid lg:grid-cols-3 gap-12">
              <div className="space-y-8">
                <div className="bg-white rounded-[48px] p-10 shadow-2xl border border-slate-50 text-center">
                  <div className="w-32 h-32 rounded-[48px] bg-red-600 mx-auto mb-8 flex items-center justify-center text-white text-5xl font-black shadow-xl shadow-red-600/20">
                    {currentUser.name.charAt(0)}
                  </div>
                  <h3 className="text-2xl font-black text-slate-900 mb-1">{currentUser.name}</h3>
                  <p className="text-slate-400 font-bold text-sm uppercase tracking-widest mb-8">{currentUser.phone}</p>
                  <div className="grid grid-cols-2 gap-4 mb-8">
                    <div className="bg-slate-50 p-4 rounded-3xl">
                      <p className="text-red-600 font-black text-lg">{currentUser.loyaltyPoints}</p>
                      <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Points</p>
                    </div>
                    <div className="bg-slate-50 p-4 rounded-3xl">
                      <p className="text-slate-900 font-black text-lg">{currentUser.tier}</p>
                      <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Tier</p>
                    </div>
                  </div>
                  <Button variant="outline" fullWidth onClick={handleLogout} className="rounded-2xl py-4">Logout</Button>
                </div>
              </div>
              <div className="lg:col-span-2 space-y-8">
                <h3 className="text-3xl font-black text-slate-900 tracking-tighter">Order History</h3>
                <div className="space-y-4">
                  {orders.filter(o => o.customerPhone === currentUser.phone).length > 0 ? (
                    orders.filter(o => o.customerPhone === currentUser.phone).map(o => (
                      <div key={o.id} className="bg-white p-8 rounded-[36px] border border-slate-50 shadow-xl flex justify-between items-center group hover:border-red-100 transition-all cursor-pointer" onClick={() => { setLastOrder(o); setView('RECEIPT'); }}>
                        <div>
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Order #{o.id}</p>
                          <h5 className="font-black text-slate-900 text-lg">৳{o.total}</h5>
                          <p className="text-xs text-slate-400 font-bold mt-1">{new Date(o.createdAt).toLocaleDateString()}</p>
                        </div>
                        <div className={`px-5 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest ${o.status === OrderStatus.DELIVERED ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>
                          {o.status}
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="text-center py-12 text-slate-300 font-bold">No orders yet.</div>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}

        {view === 'TRACK_ORDERS' && (
          <div className="animate-in max-w-3xl mx-auto px-6 py-12">
            <h2 className="text-5xl font-black text-slate-900 mb-12 tracking-tighter">Live Tracking</h2>
            <div className="space-y-6">
              {orders.filter(o => o.customerPhone === currentUser?.phone && o.status !== OrderStatus.DELIVERED).map(o => (
                <div key={o.id} className="bg-white rounded-[56px] p-10 md:p-14 shadow-2xl border border-slate-50">
                  <div className="flex justify-between items-start mb-12">
                    <div>
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Tracking ID: {o.id}</p>
                      <h4 className="text-2xl font-black text-slate-900">Your order is being <span className="text-red-600">{o.status.toLowerCase().replace('_', ' ')}</span></h4>
                    </div>
                    <div className="w-16 h-16 bg-red-600/5 rounded-3xl flex items-center justify-center text-red-600 text-2xl">
                      <i className={`fas ${o.status === OrderStatus.PREPARING ? 'fa-fire-burner' : o.status === OrderStatus.READY ? 'fa-box-open' : 'fa-truck-fast'} animate-pulse`}></i>
                    </div>
                  </div>

                  <div className="relative pt-8">
                    <div className="absolute top-0 inset-x-0 h-1 bg-slate-100 rounded-full overflow-hidden">
                      <div className={`h-full bg-red-600 transition-all duration-1000 ${
                        o.status === OrderStatus.PENDING ? 'w-[10%]' :
                        o.status === OrderStatus.PAID ? 'w-[25%]' :
                        o.status === OrderStatus.PREPARING ? 'w-[50%]' :
                        o.status === OrderStatus.READY ? 'w-[75%]' :
                        o.status === OrderStatus.ON_THE_WAY ? 'w-[90%]' : 'w-full'
                      }`}></div>
                    </div>
                    <div className="flex justify-between text-[10px] font-black uppercase tracking-widest text-slate-400 mt-6">
                      <span className={o.status === OrderStatus.PENDING ? 'text-red-600' : ''}>Received</span>
                      <span className={o.status === OrderStatus.PREPARING ? 'text-red-600' : ''}>Kitchen</span>
                      <span className={o.status === OrderStatus.READY ? 'text-red-600' : ''}>Ready</span>
                      <span className={o.status === OrderStatus.ON_THE_WAY ? 'text-red-600' : ''}>Transit</span>
                    </div>
                  </div>
                </div>
              ))}
              {orders.filter(o => o.customerPhone === currentUser?.phone && o.status !== OrderStatus.DELIVERED).length === 0 && (
                <div className="text-center py-20">
                  <p className="text-slate-400 font-bold text-xl">No active orders tracking right now.</p>
                  <Button variant="outline" className="mt-8 px-10 rounded-2xl" onClick={() => setView('MENU')}>Order Something New</Button>
                </div>
              )}
            </div>
          </div>
        )}

      </main>

      {/* FOOTER */}
      <footer className="md:hidden fixed bottom-0 inset-x-0 h-20 bg-white border-t border-slate-100 flex justify-around items-center px-6 z-50 no-print">
        <button onClick={() => setView('HOME')} className={`flex flex-col items-center gap-1 transition-all ${view === 'HOME' ? 'text-red-600 scale-110' : 'text-slate-300'}`}>
          <i className="fas fa-home text-xl"></i>
          <span className="text-[9px] font-black uppercase tracking-widest">Home</span>
        </button>
        <button onClick={() => setView('MENU')} className={`flex flex-col items-center gap-1 transition-all ${view === 'MENU' ? 'text-red-600 scale-110' : 'text-slate-300'}`}>
          <i className="fas fa-utensils text-xl"></i>
          <span className="text-[9px] font-black uppercase tracking-widest">Menu</span>
        </button>
        <button onClick={() => setView('CART')} className={`flex flex-col items-center gap-1 relative transition-all ${['CART', 'CHECKOUT', 'PAYMENT', 'GATEWAY'].includes(view) ? 'text-red-600 scale-110' : 'text-slate-300'}`}>
          <i className="fas fa-shopping-bag text-xl"></i>
          {cart.length > 0 && <span className="absolute -top-1 right-0 w-5 h-5 bg-red-600 text-white text-[9px] rounded-full flex items-center justify-center font-black border-2 border-white">{cart.length}</span>}
          <span className="text-[9px] font-black uppercase tracking-widest">Bag</span>
        </button>
        <button onClick={() => currentUser ? setView('PROFILE') : setView('LOGIN')} className={`flex flex-col items-center gap-1 transition-all ${['PROFILE', 'LOGIN', 'TRACK_ORDERS'].includes(view) ? 'text-red-600 scale-110' : 'text-slate-300'}`}>
          <i className="fas fa-user text-xl"></i>
          <span className="text-[9px] font-black uppercase tracking-widest">Profile</span>
        </button>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Order, MenuItem, OrderStatus, User, MenuUpdate, Analytics } from './types';
import { Button } from './components/Button';
import { API } from './services/api';

interface AdminPanelProps {
  user: User;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  onLogout: () => void;
  onMenuUpdate: (update: MenuUpdate) => void;
  cms: any;
  setCms: any;
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ user, menuItems, setMenuItems, orders, onLogout }) => {
  const [tab, setTab] = useState<'DASHBOARD' | 'ORDERS' | 'MENU' | 'CUSTOMERS'>('DASHBOARD');
  const [analytics, setAnalytics] = useState<Analytics | null>(null);
  const [customers, setCustomers] = useState<User[]>([]);

  useEffect(() => {
    const fetchData = async () => {
      setAnalytics(await API.getAnalytics());
      setCustomers(await API.getCustomers());
    };
    fetchData();
  }, [orders]);

  const updatePrice = async (id: string, currentPrice: number) => {
    const val = prompt("Enter new price in BDT:", currentPrice.toString());
    if (val !== null) {
      const newPrice = parseInt(val);
      if (!isNaN(newPrice)) {
        const item = menuItems.find(m => m.id === id);
        if (item) {
          const updatedItem = { ...item, price: newPrice };
          setMenuItems(prev => prev.map(m => m.id === id ? updatedItem : m));
          await API.updateMenuItem(updatedItem, user.name);
        }
      }
    }
  };

  const updateStock = async (id: string, currentStock: number) => {
    const val = prompt("Enter new stock level:", currentStock.toString());
    if (val !== null) {
      const newStock = parseInt(val);
      if (!isNaN(newStock)) {
        const item = menuItems.find(m => m.id === id);
        if (item) {
          const updatedItem = { ...item, stock: newStock };
          setMenuItems(prev => prev.map(m => m.id === id ? updatedItem : m));
          await API.updateMenuItem(updatedItem, user.name);
        }
      }
    }
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus) => {
    await API.updateOrderStatus(orderId, status, user.name);
  };

  return (
    <div className="min-h-screen bg-slate-950 text-white flex flex-col font-sans overflow-hidden">
      <nav className="bg-black/40 backdrop-blur-3xl border-b border-white/5 px-8 h-20 flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 bg-red-600 rounded-2xl flex items-center justify-center text-white font-black text-2xl shadow-2xl shadow-red-600/30">A</div>
          <div>
            <h2 className="font-black italic uppercase tracking-tighter text-lg leading-none">Command Center</h2>
            <p className="text-[8px] font-black text-emerald-500 uppercase tracking-[6px] mt-1">Authorized: {user.name}</p>
          </div>
        </div>
        <button onClick={onLogout} className="text-[10px] font-black uppercase tracking-[5px] text-red-600 bg-red-600/10 px-6 py-3 rounded-2xl hover:bg-red-600 hover:text-white transition-all border border-red-600/20 shadow-xl">Terminate Access</button>
      </nav>

      <div className="flex-1 flex flex-col md:flex-row h-[calc(100vh-80px)] overflow-hidden">
        <aside className="w-full md:w-72 bg-black/20 border-r border-white/5 p-8 flex md:flex-col gap-3 overflow-y-auto">
          {[
            { id: 'DASHBOARD', icon: 'fa-gauge-high', label: 'Intelligence' },
            { id: 'ORDERS', icon: 'fa-receipt', label: 'Fleet Ops' },
            { id: 'MENU', icon: 'fa-folder-tree', label: 'Manifest' },
            { id: 'CUSTOMERS', icon: 'fa-users', label: 'Civilians' }
          ].map((item) => (
            <button 
              key={item.id} 
              onClick={() => setTab(item.id as any)} 
              className={`flex items-center gap-6 px-8 py-5 rounded-[28px] text-[10px] font-black uppercase tracking-[3px] transition-all duration-500 whitespace-nowrap border ${tab === item.id ? 'bg-red-600 text-white shadow-2xl scale-105 border-white/20' : 'bg-white/5 text-white/30 border-white/5 hover:bg-white/10 hover:text-white'}`}
            >
              <i className={`fas ${item.icon} text-lg`}></i>
              {item.label}
            </button>
          ))}
        </aside>

        <main className="flex-1 p-10 overflow-y-auto bg-gradient-to-br from-slate-950 to-black custom-scrollbar">

          {tab === 'DASHBOARD' && analytics && (
            <div className="space-y-12 animate-in">
              <div className="flex justify-between items-end mb-8">
                <div>
                  <h3 className="text-4xl font-black italic uppercase tracking-tighter mb-2">Operational Analytics</h3>
                  <p className="text-white/30 font-bold text-xs tracking-widest">REAL-TIME DATA STREAM ACTIVE</p>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                <div className="bg-white/5 border border-white/5 p-10 rounded-[48px] backdrop-blur-xl">
