                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {tab === 'ORDERS' && (
            <div className="space-y-10 animate-in">
              <h3 className="text-4xl font-black italic uppercase tracking-tighter">Fleet Deployments</h3>
