                        <th className="px-10 py-8">Personnel</th>
                        <th className="px-10 py-8">Valuation</th>
                        <th className="px-10 py-8">Payment</th>
                        <th className="px-10 py-8">Vector</th>
                        <th className="px-10 py-8">Control</th>
                      </tr>
                    </thead>
