                      {orders.map(o => (
                        <tr key={o.id} className="hover:bg-white/5 transition-colors">
                          <td className="px-10 py-8 font-mono text-[10px] opacity-30">#{o.id}</td>
                          <td className="px-10 py-8">
                            <p className="text-white text-base">{o.customerName}</p>
