                            <span className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest border ${o.paymentStatus === 'PAID' ? 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20' : 'bg-red-600/10 text-red-600 border-red-600/20'}`}>
                              {o.paymentStatus}
                            </span>
                            <p className="text-[8px] text-white/30 uppercase tracking-widest mt-2">{o.paymentMethod}</p>
