                {menuItems.map(item => (
                  <div key={item.id} className="bg-white/5 p-10 rounded-[56px] border border-white/5 flex gap-8 items-center backdrop-blur-xl group hover:border-white/20 transition-all">
                    <div className="w-24 h-24 rounded-[32px] overflow-hidden shadow-2xl relative">
                       <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt={item.name} />
                       {item.stock === 0 && <div className="absolute inset-0 bg-red-600/40 flex items-center justify-center"><i className="fas fa-ban text-white"></i></div>}
                    </div>
                    <div className="flex-1 space-y-4">
                      <div>
                        <h5 className="font-black italic uppercase text-lg leading-none mb-1">{item.nameBn}</h5>
