                    </div>
                    <h5 className="font-black uppercase text-xl mb-1">{c.name}</h5>
                    <p className="text-white/40 font-bold text-xs mb-8">{c.phone}</p>
                    <div className="grid grid-cols-2 gap-4">
                      <div className="bg-white/5 p-5 rounded-3xl border border-white/5">
                        <p className="text-red-600 font-black text-xl">{c.loyaltyPoints}</p>
                        <p className="text-[8px] font-black text-white/20 uppercase tracking-widest">Intel Pts</p>
                      </div>
                      <div className="bg-white/5 p-5 rounded-3xl border border-white/5">
                        <p className="text-white font-black text-xl">{c.tier}</p>
