      setIsLoading(true);
      setTimeout(() => { setIsLoading(false); setStep('OTP'); }, 1000);
      return;
    }
    setIsLoading(true);
    const user = await API.login(loginPhone, otp);
    setIsLoading(false);
    if (user) {
      setCurrentUser(user);
      setView('HOME');
    } else {
      alert("Invalid OTP. Try 1234");
    }
  };

  const handleSocialLogin = async (provider: 'GOOGLE') => {
    setIsLoading(true);
    const user = await API.login('017XXXXXXXX', '1234', provider);
    setIsLoading(false);
    if (user) {
      setCurrentUser(user);
      setView('HOME');
    }
  };

  const addToCart = (item: MenuItem) => {
    if (item.stock === 0) return;
    setCart(prev => {
      const ex = prev.find(i => i.item.id === item.id);
      if (ex) return prev.map(i => i.item.id === item.id ? { ...i, qty: i.qty + 1 } : i);
      return [...prev, { item, qty: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => {
      const ex = prev.find(i => i.item.id === id);
