                                   className="bg-black/40 border border-white/10 rounded-2xl px-5 py-3 text-[10px] font-black uppercase tracking-[3px] outline-none focus:border-red-600 transition-all cursor-pointer"
                                   value={o.status}
                                   onChange={(e) => updateStatus(o.id, e.target.value as OrderStatus)}
                                 >
                                    {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                                 </select>
                              </td>
                           </tr>
                         ))}
                      </tbody>
                   </table>
                </div>
             </div>
           )}
        </main>
      </div>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.05); border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: rgba(220, 38, 38, 0.2); }
      `}</style>
    </div>
  );
};

