import { MenuItem, Order, OrderStatus, AuditLog, User, UserRole, Analytics } from '../types';
import { MOCK_MENU } from '../constants';

const DB_KEYS = {
  MENU: 'bfc_elite_menu_v6',
  ORDERS: 'bfc_elite_orders_v6',
  LOGS: 'bfc_elite_logs_v6',
  USERS: 'bfc_elite_users_v6',
  SESSION: 'bfc_elite_session_v6'
};

const initializeDB = () => {
  if (!localStorage.getItem(DB_KEYS.MENU)) localStorage.setItem(DB_KEYS.MENU, JSON.stringify(MOCK_MENU));
  if (!localStorage.getItem(DB_KEYS.ORDERS)) localStorage.setItem(DB_KEYS.ORDERS, JSON.stringify([]));
  if (!localStorage.getItem(DB_KEYS.LOGS)) localStorage.setItem(DB_KEYS.LOGS, JSON.stringify([]));
  if (!localStorage.getItem(DB_KEYS.USERS)) {
    const admin: User = {
      id: 'ADMIN_MASTER',
      name: 'BFC Command',
      username: 'admin',
      email: 'hq@bfc.com',
      phone: '01700000000',
      address: 'BFC Elite HQ, Dhaka',
      savedAddresses: ['BFC Elite HQ, Dhaka'],
      gender: 'MALE',
      role: UserRole.ADMIN,
      loyaltyPoints: 100000,
      tier: 'ELITE',
      createdAt: new Date().toISOString()
    };
    localStorage.setItem(DB_KEYS.USERS, JSON.stringify([admin]));
  }
};

initializeDB();

export const API = {
  async login(phone: string, otp: string, provider: 'PHONE' | 'GOOGLE' = 'PHONE'): Promise<User | null> {
    const users: User[] = JSON.parse(localStorage.getItem(DB_KEYS.USERS) || '[]');
    let user = users.find(u => u.phone === phone);

    if (otp === '1234' || provider === 'GOOGLE') {
      if (!user) {
        user = {
          id: `U_${Date.now()}`,
          name: provider === 'GOOGLE' ? 'Authenticated User' : 'Valued Client',
          username: `user_${Date.now()}`,
          email: '',
          phone,
          address: '',
          savedAddresses: [],
          gender: 'OTHER',
          role: phone === '01700000000' ? UserRole.ADMIN : UserRole.CUSTOMER,
          loyaltyPoints: 10,
          tier: 'BRONZE',
          createdAt: new Date().toISOString(),
          socialProvider: provider
        };
        localStorage.setItem(DB_KEYS.USERS, JSON.stringify([...users, user]));
      }
      localStorage.setItem(DB_KEYS.SESSION, JSON.stringify(user));
      this.broadcast('AUTH_CHANGE');
      return user;
    }
    return null;
  },

  getCurrentUser(): User | null {
    const s = localStorage.getItem(DB_KEYS.SESSION);
    return s ? JSON.parse(s) : null;
  },

  logout() {
    localStorage.removeItem(DB_KEYS.SESSION);
    this.broadcast('AUTH_CHANGE');
  },

  async getMenu(): Promise<MenuItem[]> {
    return JSON.parse(localStorage.getItem(DB_KEYS.MENU) || '[]');
  },

  async updateMenuItem(item: MenuItem, user: string) {
    const menu = await this.getMenu();
    const updated = menu.map(m => m.id === item.id ? item : m);
    localStorage.setItem(DB_KEYS.MENU, JSON.stringify(updated));
    this.addLog('STOCK_UPDATE', user, `Updated ${item.name} status`);
    this.broadcast('SYNC');
  },

  async getOrders(): Promise<Order[]> {
    return JSON.parse(localStorage.getItem(DB_KEYS.ORDERS) || '[]');
  },

  async placeOrder(order: Order) {
    const orders = await this.getOrders();
    localStorage.setItem(DB_KEYS.ORDERS, JSON.stringify([order, ...orders]));
    this.addLog('PAYMENT_LOG', order.customerName, `Verified ${order.paymentMethod} transaction: ${order.transactionId || 'COD'}`);
    this.broadcast('NEW_ORDER');
  },

  async updateOrderStatus(id: string, status: OrderStatus, user: string) {
    const orders = await this.getOrders();
    const updated = orders.map(o => {
      if (o.id === id) {
        return { 
          ...o, 
          status, 
          trackingHistory: [...o.trackingHistory, { status, time: new Date().toISOString() }] 
        };
      }
      return o;
    });
    localStorage.setItem(DB_KEYS.ORDERS, JSON.stringify(updated));
    this.addLog('STATUS_SHIFT', user, `Order ${id} marked as ${status}`);
    this.broadcast('SYNC');
  },

  async getAnalytics(): Promise<Analytics> {
    const orders = await this.getOrders();
    const valid = orders.filter(o => o.status !== OrderStatus.CANCELLED);
    const totalSales = valid.reduce((a, b) => a + b.total, 0);

    const salesByDay = [...Array(7)].map((_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      const str = d.toISOString().split('T')[0];
      const amt = valid.filter(o => o.createdAt.startsWith(str)).reduce((a, b) => a + b.total, 0);
      return { date: str, amount: amt };
    }).reverse();

    const paymentMix: Record<string, number> = {};
    valid.forEach(o => {
      paymentMix[o.paymentMethod] = (paymentMix[o.paymentMethod] || 0) + 1;
    });

    return {
      totalSales,
      totalOrders: orders.length,
      averageOrderValue: orders.length ? totalSales / orders.length : 0,
      salesByDay,
      paymentMix
    };
  },

  async getAuditLogs(): Promise<AuditLog[]> {
    return JSON.parse(localStorage.getItem(DB_KEYS.LOGS) || '[]');
  },

  async addLog(action: string, user: string, details: string) {
    const logs = JSON.parse(localStorage.getItem(DB_KEYS.LOGS) || '[]');
    const newLog: AuditLog = { id: `L_${Date.now()}`, action, user, details, timestamp: new Date().toISOString() };
    localStorage.setItem(DB_KEYS.LOGS, JSON.stringify([newLog, ...logs.slice(0, 99)]));
  },

  broadcast(type: string) {
    window.dispatchEvent(new CustomEvent('BFC_SYSTEM_EVENT', { detail: { type } }));
  },

  subscribe(cb: (e: any) => void) {
    const handler = (e: any) => cb(e.detail);
    window.addEventListener('BFC_SYSTEM_EVENT', handler);
    return () => window.removeEventListener('BFC_SYSTEM_EVENT', handler);
  }
};

